def source_level_memory_builtins_case():
    """Check copy, fill, and compare built-ins, including counts and type errors.

    Returns:
        None; raises AssertionError for incorrect memory behavior or acceptance.
    """
    source_text = r'''unsigned long strlen(const char* text);
int calls;
int negative() { calls++; return -1; }
int printf(const char* format); int main() {
    char data[] = "old";
    copy(data, "cat", 4);
    if (compare(data, "cat\0", 4) == 0) printf("copied;");
    fill(data, 321, 3);
    if (compare(data, "AAA", 3) == 0) printf("filled;");
    if (strlen(data) == 3) printf("nul-preserved;");
    copy(data, "z", 0);
    if (compare(data, "AAA", 3) == 0) printf("zero-copy;");
    fill(data, 0, 0);
    if (compare(data, "AAA", 3) == 0) printf("zero-fill;");
    copy(data, "z", -1);
    if (compare(data, "AAA", 3) == 0) printf("negative-copy;");
    fill(data, 0, -1);
    if (compare(data, "AAA", 3) == 0) printf("negative-fill;");
    if (compare(data, "z", -1) == 0) printf("negative-compare;");
    signed char small = -1;
    short medium = -1;
    long large = -1;
    long long wider = -1;
    if (copy(data, "z", small) != data || fill(data, 0, medium) != data ||
        compare(data, "z", large) != 0 || fill(0, 0, wider) != 0 ||
        copy(data, "z", negative()) != data ||
        calls != 1 || compare(data, "AAA", 3U) != 0) return 1;
    char high[] = "\xff";
    if (compare(high, "\x7f", 1) > 0) printf("unsigned-order;");
    return 0;
}
'''
    expected = "copied;filled;nul-preserved;zero-copy;zero-fill;negative-copy;negative-fill;negative-compare;unsigned-order;"
    with tempfile.TemporaryDirectory(prefix="crunch-memory-builtins-") as td:
        td = pathlib.Path(td)
        source, bir, asm, obj, exe = (td / "program.bc", td / "program.bir", td / "program.s", td / "program.o", td / "program")
        source.write_text(source_text)
        ir_text = command([BUILD / "crunch-ir", source]).stdout
        for needle in ("call memcpy 3", "call memset 3", "call memcmp 3"):
            expect(needle in ir_text, f"memory builtin was not lowered to {needle!r}")
        bir.write_text(ir_text)
        assembly = command([ASM, bir]).stdout
        for helper in ("memcpy", "memset", "memcmp"):
            expect(f"call __crunch_{helper}" in assembly, f"{helper} library helper was not called")
            expect(f"__crunch_{helper}:" not in assembly,
                   f"{helper} helper was emitted instead of linked from libcrunch.a")
        expect("__crunch_printf_number:" not in assembly and
               "__crunch_printf_real:" not in assembly,
               "unused printf formatting helper was emitted")
        asm.write_text(assembly)
        command([TEST_AS, "-o", obj, asm])
        command([*TEST_LINK, "-o", exe, obj, LIBCRUNCH])
        result = command([exe], check=False)
        expect(result.returncode == 0, f"memory built-ins program exited {result.returncode}: {result.stderr}")
        expect(result.stdout == expected, f"memory built-ins output was {result.stdout!r}")
        command([DRIVER, "-c", source, "-o", obj])
        command([DRIVER, obj, "-o", exe])
        result = command([exe], check=False)
        expect(result.returncode == 0 and result.stdout == expected,
               f"module memory built-ins failed: {result.returncode} {result.stdout!r}")

    invalid_sources = (
        ('int main() { copy(1, "x", 1); return 0; }\n', "copy should reject a non-pointer destination"),
        ('int main() { fill("x", 1.5, 1); return 0; }\n', "fill should reject real fill values"),
        ('int main() { compare("x", "y", 1.5); return 0; }\n', "compare should reject real byte counts"),
        ('int main() { fill(1, 0, 1); return 0; }\n', "fill should reject non-pointer destinations"),
    )
    for source_text, message in invalid_sources:
        with tempfile.TemporaryDirectory(prefix="crunch-memory-builtin-types-") as td:
            source = pathlib.Path(td) / "invalid.bc"
            source.write_text(source_text)
            result = command([BUILD / "crunch-ir", source], check=False)
            expect(result.returncode != 0, message)

def source_level_end_case():
    """Check process termination through end and rejection of invalid arguments.

    Returns:
        None; raises AssertionError for incorrect exit status or call validation.
    """
    source_text = '#include <stdlib.h>\nint printf(const char* format); int main() { printf("before;"); exit(7); printf("after;"); return 42; }\n'
    with tempfile.TemporaryDirectory(prefix="crunch-end-builtin-") as td:
        td = pathlib.Path(td)
        source, bir, asm, obj, exe = (td / "program.bc", td / "program.bir",
                                      td / "program.s", td / "program.o", td / "program")
        source.write_text(source_text)
        expanded = command([PP, source]).stdout
        expect("void noreturn exit(int status);" in expanded,
               "preprocessor did not insert the end declaration")
        tokens = command([LEXER, "-"], input=expanded).stdout
        expect(command([PARSER], input=tokens).returncode == 0,
               "lexer/parser pipeline rejected preprocessed source")
        expanded_source = td / "expanded.bc"
        expanded_source.write_text(expanded)
        ir_text = command([BUILD / "crunch-ir", expanded_source]).stdout
        expect("call exit 1" in ir_text, "exit(status) was not lowered to its runtime call")
        end_lines = ir_text.splitlines()
        call_index = end_lines.index("call exit 1")
        expect(end_lines[call_index + 1] != "drop",
               "IR treats a noreturn call as returning a value")
        minimal_source = td / "minimal.bc"
        minimal_source.write_text("#include <stdlib.h>\nint main() { exit(7); }\n")
        minimal_expanded = td / "minimal-expanded.bc"
        minimal_expanded.write_text(command([PP, minimal_source]).stdout)
        minimal_ir = command([BUILD / "crunch-ir", minimal_expanded]).stdout.splitlines()
        minimal_call_index = minimal_ir.index("call exit 1")
        expect(minimal_ir[minimal_call_index + 1] == "end",
               "IR emitted a return or value drop after a noreturn call")
        bir.write_text(ir_text)
        assembly = command([ASM, bir]).stdout
        expect("call __crunch_exit" in assembly, "exit library helper was not called")
        expect("__crunch_end:" not in assembly, "end was emitted instead of linked from libcrunch.a")
        asm.write_text(assembly)
        command([TEST_AS, "-o", obj, asm])
        command([*TEST_LINK, "-o", exe, obj, LIBCRUNCH])
        result = command([exe], check=False)
        expect(result.returncode == 7, f"exit(7) exited with status {result.returncode}")
        expect(result.stdout == "before;", f"exit(7) did not stop later output: {result.stdout!r}")

    for invalid_source in ('int main() { exit(); return 0; }\n',):
        with tempfile.TemporaryDirectory(prefix="crunch-end-arguments-") as td:
            source = pathlib.Path(td) / "invalid.bc"
            source.write_text("void noreturn exit(int status);\n" + invalid_source)
            result = command([BUILD / "crunch-ir", source], check=False)
            expect(result.returncode != 0,
                   f"end accepted invalid call {invalid_source.strip()!r}")

    with tempfile.TemporaryDirectory(prefix="crunch-noreturn-identifiers-") as directory:
        td = pathlib.Path(directory)
        source, exe = td / "noreturn.bc", td / "noreturn"
        source.write_text("""
struct S { int noreturn; };
int noreturn(int noreturn) { return noreturn + 1; }
_Noreturn int stop(int status);
int stop(int status) { while (status) { } return 0; }
int main() {
    struct S x;
    x.noreturn = 40;
    goto noreturn;
    return 1;
noreturn:
    return noreturn(x.noreturn) == 41 ? 0 : 2;
}
""")
        tokens = command([LEXER, source]).stdout
        expect("\nNORETURN\t" in tokens and "\nIDENTIFIER\t" in tokens,
               "_Noreturn and noreturn were not distinguished")
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "noreturn identifier or standard _Noreturn declaration failed")
        source.write_text("_Noreturn int value; int main() { return 0; }\n")
        expect(command([IR, source], check=False).returncode != 0,
               "_Noreturn was accepted on a variable")

def end_header_programs_case():
    """Check stdlib.h noreturn declarations through preprocessing and execution.

    Returns:
        None; raises AssertionError for wrong prototypes, output, or exit status.
    """
    cases = (
        ("end_header_literal.bc", 7, "before;"),
        ("end_header_variable.bc", 23, "second;"),
    )
    for filename, expected_status, expected_output in cases:
        source = FIXTURES / "units/function_calls" / filename
        with tempfile.TemporaryDirectory(prefix="crunch-end-header-") as td:
            directory = pathlib.Path(td)
            expanded_source = directory / "expanded.bc"
            expanded = command([PP, source]).stdout
            expect("void noreturn exit(int status);" in expanded,
                   f"{filename}: stdlib.h exit declaration was not included")
            expanded_source.write_text(expanded)

            tokens = command([LEXER, "-"], input=expanded).stdout
            ast = json.loads(command([PARSER], input=tokens).stdout)
            end_declaration = next(
                declaration for declaration in ast["declarations"]
                if declaration.get("kind") == "function" and
                declaration.get("name") == "exit"
            )
            expect(end_declaration["noreturn"] is True,
                   f"{filename}: end prototype was not registered as noreturn")
            expect(end_declaration["return_type"]["kind"] == "void" and
                   len(end_declaration["parameters"]) == 1 and
                   end_declaration["parameters"][0]["type"]["kind"] == "int",
                   f"{filename}: end prototype has an unexpected signature")

            ir_text = command([IR, expanded_source]).stdout
            expect("call exit 1" in ir_text,
                   f"{filename}: end call was not lowered to IR")
            ir_file, asm_file, obj_file, executable = (
                directory / "program.bir", directory / "program.s",
                directory / "program.o", directory / "program"
            )
            ir_file.write_text(ir_text)
            assembly = command([ASM, ir_file]).stdout
            asm_file.write_text(assembly)
            command([TEST_AS, "-o", obj_file, asm_file])
            command([*TEST_LINK, "-o", executable, obj_file, LIBCRUNCH])
            result = command([executable], check=False)
            expect(result.returncode == expected_status,
                   f"{filename}: expected exit status {expected_status}, got {result.returncode}")
            expect(result.stdout == expected_output,
                   f"{filename}: expected output {expected_output!r}, got {result.stdout!r}")

def standard_runtime_headers_case():
    """Check installed-style header prototypes through the compiler pipeline.

    Returns:
        None; raises AssertionError for incompatible declarations or runtime results.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-runtime-headers-") as td:
        directory = pathlib.Path(td)
        source = directory / "program.bc"
        source.write_text(
            "#include <stdlib.h>\n"
            "#include <string.h>\n"
            "#include <stdio.h>\n"
            "int main() {\n"
            "    char buffer[] = \"bad\";\n"
            "    memset(buffer, 0, 4);\n"
            "    memcpy(buffer, \"ok\", 3);\n"
            "    if (memcmp(buffer, \"ok\", 3) == 0 && strcmp(buffer, \"ok\") == 0) {\n"
            "        printf(\"%s\", buffer);\n"
            "        printf(\":\");\n"
            "        printf(\"%lu%f\", strlen(buffer), 1.25);\n"
            "        exit(9);\n"
            "    }\n"
            "    return 1;\n"
            "}\n"
        )
        expanded = command([PP, source]).stdout
        expanded_source = directory / "expanded.bc"
        expanded_source.write_text(expanded)
        tokens = command([LEXER, "-"], input=expanded).stdout
        ast = json.loads(command([PARSER], input=tokens).stdout)
        prototypes = {
            declaration["name"]: declaration
            for declaration in ast["declarations"]
            if declaration.get("kind") == "function" and
            declaration.get("body") is None
        }
        for name in ("exit", "memcpy", "memset", "memcmp", "strcmp",
                     "strlen", "printf"):
            expect(name in prototypes,
                   f"standard headers did not register the {name} prototype")
        expect(prototypes["exit"]["noreturn"] is True,
               "stdlib.h did not expose end as noreturn")

        ir_text = command([IR, expanded_source]).stdout
        for name in ("memset", "memcpy", "memcmp", "strcmp",
                     "strlen", "printf", "exit"):
            expect(f"call {name} " in ir_text,
                   f"header-declared {name} call was not lowered")
        ir_file, asm_file = directory / "program.bir", directory / "program.s"
        obj_file, executable = directory / "program.o", directory / "program"
        ir_file.write_text(ir_text)
        asm_file.write_text(command([ASM, ir_file]).stdout)
        command([TEST_AS, "-o", obj_file, asm_file])
        command([*TEST_LINK, "-o", executable, obj_file, LIBCRUNCH])
        result = command([executable], check=False)
        expect(result.returncode == 9,
               f"standard-header runtime program exited {result.returncode}")
        expect(result.stdout == "ok:21.250000",
               f"standard-header runtime output was {result.stdout!r}")
        for name in ("print_number", "print_real"):
            expect(name not in prototypes, f"stdio.h still exposes removed {name} API")

        headers = {
            "stdlib.h": ("atoi", "atol", "strtol", "malloc", "exit"),
            "stdio.h": ("rename", "renameat", "fopen", "printf"),
            "unistd.h": ("read", "write", "close", "lseek", "access", "fork", "getpid",
                         "readlink", "readlinkat", "unlink", "unlinkat", "symlinkat",
                         "rmdir", "dup", "dup2", "pipe", "file_open", "file_read",
                         "file_write", "file_close"),
            "fcntl.h": ("open", "openat"),
            "sys/stat.h": ("stat", "fstat", "lstat", "fstatat", "mkdir", "mkdirat"),
            "poll.h": ("poll",),
            "sys/select.h": ("select",),
            "signal.h": ("kill",),
            "sys/mman.h": ("mmap", "munmap", "mremap", "map_failed"),
            "dirent.h": ("getdents64", "dirent64_next"),
        }
        for header, expected in headers.items():
            source.write_text(f"#include <{header}>\nint main() {{ return 0; }}\n")
            expanded = command([PP, source]).stdout
            ast = json.loads(command([PARSER], input=command([LEXER, "-"],
                                                             input=expanded).stdout).stdout)
            names = {d["name"] for d in ast["declarations"] if d.get("kind") == "function"}
            expect(set(expected) <= names, f"{header} is missing {set(expected) - names}")
            expanded_source.write_text(expanded)
            command([IR, expanded_source])
        source.write_text("#include <string.h>\nint main() { return atoi(\"42\"); }\n")
        expanded_source.write_text(command([PP, source]).stdout)
        expect_clean_rejection(command([IR, expanded_source], check=False),
                               "atoi without stdlib.h")
        source.write_text(
            "#include <unistd.h>\n#include <fcntl.h>\n#include <sys/stat.h>\n"
            "#include <poll.h>\n#include <sys/select.h>\n#include <signal.h>\n"
            "#include <sys/mman.h>\n#include <dirent.h>\n#include <stdlib.h>\n"
            "#include <stdio.h>\n#include <unistd.h>\n#include <sys/stat.h>\n"
            "int main() { struct stat s; struct pollfd p; struct timeval t; "
            "p.fd = -1; t.tv_sec = 0; t.tv_usec = 0; "
            "if (stat(\".\", &s) || poll(&p, 1, 0) || "
            "select(0, 0, 0, 0, &t) || getpid() <= 0) return 1; "
            "if (STDIN_FILENO != 0 || O_RDONLY != 0 || SIGTERM != 15 || "
            "MAP_PRIVATE != 2 || DT_DIR != 4) return 2; return atoi(\"42\"); }\n")
        command([BUILD / "crunch", source, "-o", executable])
        expect(command([executable], check=False).returncode == 42,
               "standard headers failed when included together or repeatedly")

def null_header_case():
    """Check NULL availability and pointer behavior for each supporting header.

    Returns:
        None; raises AssertionError for incorrect definitions or behavior.
    """
    headers = ("stddef.h", "stdio.h", "stdlib.h", "string.h", "unistd.h", "sys/select.h")
    with tempfile.TemporaryDirectory(prefix="crunch-null-headers-") as td:
        source = pathlib.Path(td) / "null.bc"
        exe = pathlib.Path(td) / "program"
        for header in headers:
            source.write_text(
                f"#include <{header}>\n"
                "int *global = NULL; int *get_null() { return NULL; }\n"
                "int is_null(int *p) { return p == NULL; }\n"
                "int main() { int value = 1; int *p = &value; p = NULL; "
                "if (global != NULL || p != NULL || !is_null(NULL) || "
                "get_null() != NULL) return 1; return 42; }\n")
            command([BUILD / "crunch", source, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"NULL did not work through {header}")
        source.write_text(
            "#include <stddef.h>\n#undef NULL\n#include <stdlib.h>\n"
            "#include <stdio.h>\n#include <string.h>\n#include <unistd.h>\n"
            "#include <sys/select.h>\nint main() { int *p = NULL; "
            "return p == NULL ? 42 : 1; }\n")
        command([BUILD / "crunch", source, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "NULL was not restored or conflicted between headers")


def size_t_header_case():
    """Check size_t availability and compatibility with sizeof.

    Returns:
        None; raises AssertionError for incorrect type or execution behavior.
    """
    headers = ("stddef.h", "stdio.h", "stdlib.h", "string.h", "unistd.h", "dirent.h")
    with tempfile.TemporaryDirectory(prefix="crunch-size-t-") as td:
        source, exe = pathlib.Path(td) / "size.bc", pathlib.Path(td) / "program"
        source.write_text("#include <stddef.h>\nint main() { return 0; }\n")
        expanded = command([PP, source]).stdout
        for module in (False, True):
            ir = command([IR, *(["--module"] if module else []), "-"],
                         input=expanded).stdout
            expect(ir.startswith(f"CRUNCH-IR {3 if module else 2}\n"),
                   "unused size_t declaration changed signed-only IR")
        cases = (
            "size_t value; int main() { value = (size_t)-1; return value > 0 ? 42 : 1; }",
            "int main() { typedef size_t Count, *CountPtr; Count n = (Count)-1; "
            "CountPtr p = &n; return *p > 0 ? 42 : 1; }",
            "int main() { return (size_t)-1 > 0 ? 42 : 1; }",
            "typedef enum E { A = 1U, B = -1 } E; "
            "int main() { return A == 1 && B == -1 ? 42 : 1; }",
        )
        for case in cases:
            source.write_text("#include <stddef.h>\n" + case + "\n")
            expanded = command([PP, source]).stdout
            for module in (False, True):
                ir = command([IR, *(["--module"] if module else []), "-"],
                             input=expanded).stdout
                expect(ir.startswith(f"CRUNCH-IR {7 if module else 6}\n"),
                       "unsigned typedef use did not select unsigned IR")
            command([BUILD / "crunch", source, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   "unsigned typedef use executed incorrectly")
        for header in headers:
            source.write_text(
                f"#include <{header}>\n"
                "size_t measure() { return sizeof(int); }\n"
                "int main() { unsigned long value = 5; "
                "size_t *p = &value; unsigned long *q = p; "
                "size_t n = sizeof(int); "
                "if (sizeof(size_t) != 8 || *q != 5 || n != 4 || "
                "measure() != n || sizeof(int) - 5 != (size_t)-1) return 1; return 42; }\n")
            command([BUILD / "crunch", source, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"size_t or sizeof failed through {header}")
        source.write_text(
            "#include <stdlib.h>\n#include <stdio.h>\n#include <string.h>\n"
            "#include <unistd.h>\n#include <dirent.h>\n#include <stddef.h>\n"
            "typedef unsigned long size_t;\n"
            "int main() { size_t n = sizeof(long); return n == 8 ? 42 : 1; }\n")
        command([BUILD / "crunch", source, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "combined headers or compatible typedef redeclaration failed")


def stdio_file_typedef_case():
    """Check FILE compatibility and the self-compiled source loader.

    Returns:
        None; raises AssertionError for incorrect stream or source-file behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-stdio-file-") as directory:
        td = pathlib.Path(directory)
        source, obj, exe = td / "file.bc", td / "file.o", td / "program"
        source.write_text('''#include <stdio.h>
#include <stdio.h>
typedef struct FILE FILE;
FILE *identity(struct FILE *stream) { return stream; }
int main() {
    FILE *stream = fopen("data", "r");
    struct FILE *legacy = stream;
    char buffer[3];
    if (!stream || !stdin || !stdout || !stderr) return 1;
    if (identity(legacy) != stream || fread(buffer, 1, 3, stream) != 3) return 2;
    if (buffer[0] != 'A' || buffer[1] != 'A' || buffer[2] != 'A') return 3;
    return fclose(legacy);
}
''')
        (td / "data").write_bytes(b"A" * 4096 + b"Z")
        for separate in (False, True):
            if separate:
                command([DRIVER, "-c", source, "-o", obj])
                command([DRIVER, obj, "-o", exe])
            else:
                command([DRIVER, source, "-o", exe])
            result = command([exe], cwd=td, check=False)
            expect(result.returncode == 0,
                   f"FILE typedef failed in {'module' if separate else 'executable'} mode: "
                   f"{result.returncode} {result.stderr}")

        loader_object = td / "source-loader.o"
        command([DRIVER, "-I", ROOT / "include", "-c",
                 ROOT / "src/common/source.c", "-o", loader_object])
        source.write_text('''#include "common/source.h"
int main() {
    SourceFile source;
    if (source_load("data", &source) != COMPILER_OK) return 1;
    if (source.length != 4097 || source.data[0] != 'A' ||
        source.data[4095] != 'A' || source.data[4096] != 'Z' ||
        source.data[4097] != 0) return 2;
    source_destroy(&source);
    if (source.data != 0 || source.length != 0 || source.filename != 0) return 3;
    if (source_load("empty", &source) != COMPILER_OK ||
        source.length != 0 || source.data[0] != 0) return 4;
    source_destroy(&source);
    if (source_load("missing", &source) != COMPILER_IO_ERROR) return 5;
    if (source_load("-", &source) != COMPILER_OK || source.length != 3 ||
        source.data[0] != 'x' || source.data[2] != 'z') return 6;
    source_destroy(&source);
    return 0;
}
''')
        (td / "empty").write_bytes(b"")
        command([DRIVER, "-I", ROOT / "include", source, loader_object, "-o", exe])
        result = command([exe], input="xyz", cwd=td, check=False)
        expect(result.returncode == 0,
               f"self-compiled source loader failed: {result.returncode} {result.stderr}")


def variadic_frontend_case():
    """Check variadic signatures, diagnostics, and ignored arguments.

    Returns:
        None; raises AssertionError for incorrect parsing or semantic behavior.
    """
    directory = FIXTURES / "units/function_calls"
    fixture = directory / "variadic_frontend.bc"
    sema_case(fixture, True)
    sema_case(directory / "invalid_variadic_signature.bc", False, "conflicting declaration")
    sema_case(directory / "invalid_variadic_count.bc", False, "expects")
    ast = json.loads(source_parse(fixture).stdout)
    expect(ast["version"] == 31, "variadic signature did not select AST v31")
    expect(ast["declarations"][0].get("variadic") is True,
           "function variadic marker is missing")
    alias = ast["declarations"][1]["type"]
    expect(alias["pointee"].get("variadic") is True,
           "function-pointer variadic marker is missing")
    compile_run(fixture, 6)
    with tempfile.TemporaryDirectory(prefix="crunch-variadic-frontend-") as directory:
        source = pathlib.Path(directory) / "invalid.bc"
        for text in ("int f(...);", "int f(void, ...);", "int f(int, . . .);",
                     "int f(int, ..., int);", "int (*f)(...);"):
            source.write_text(text)
            tokens = command([LEXER, source])
            result = command([PARSER], input=tokens.stdout, check=False)
            expect(result.returncode != 0, f"invalid variadic syntax accepted: {text}")
        source.write_text("int f(int, ...); int (*p)(int) = f;")
        sema_case(source, False, "incompatible")
        source.write_text("void f(void); int g(int, ...); int main() { return g(1, f()); }")
        sema_case(source, False, "void type")
        source.write_text("int (*p)(int, ...); int main() { return p(); }")
        sema_case(source, False, "expects at least")
        source.write_text("void f(void); int (*p)(int, ...); int main() { return p(1, f()); }")
        sema_case(source, False, "void type")
        provider = pathlib.Path(directory) / "provider.bc"
        consumer = pathlib.Path(directory) / "consumer.bc"
        provider.write_text("int ignore(int value, ...) { return value; }\n")
        consumer.write_text("extern int ignore(int value, ...);\n"
                            "int main() { return ignore(42, 1.5, 2, 3) != 42; }\n")
        provider_obj, consumer_obj = pathlib.Path(directory) / "provider.o", pathlib.Path(directory) / "consumer.o"
        exe = pathlib.Path(directory) / "program"
        command([DRIVER, "-c", provider, "-o", provider_obj])
        command([DRIVER, "-c", consumer, "-o", consumer_obj])
        command([DRIVER, provider_obj, consumer_obj, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "separate-module variadic definition failed")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            command(["cc", "-std=c11", "-x", "c", "-c", consumer, "-o", consumer_obj])
            command(["cc", "-no-pie", provider_obj, consumer_obj, "-o", exe])
            expect(command([exe], check=False).returncode == 0,
                   "host call to Crunch variadic definition failed")


