def small_memory_aggregate_ir_case():
    """Exercise small MEMORY-class ABI calls, returns and variadic retrieval.

    Returns:
        None; raises AssertionError for invalid IR or ABI incompatibility.
    """
    for version in (54, 55):
        for size in range(1, 17):
            text = (f"CRUNCH-IR {version}\nfunc f 1 mem{size}\n"
                    f"param 0 0 mem{size}\nload 0\nretagg mem{size}\nend\n"
                    "func main 0 int\npush 0\nret int\nend\n")
            command([ASM, "--validate", "-"], input=text)
    for version in (22, 23, 50, 51, 53):
        for size in (1, 8, 16):
            text = (f"CRUNCH-IR {version}\nfunc f 1 mem{size}\n"
                    f"param 0 0 mem{size}\nload 0\nretagg mem{size}\nend\n"
                    "func main 0 int\npush 0\nret int\nend\n")
            expect(command([ASM, "--validate", "-"], input=text, check=False).returncode != 0,
                   f"v{version} accepted mem{size}")
    for spelling in ("mem0", "mem01", "mem17a", "mem999993", "mem1x"):
        text = f"CRUNCH-IR 55\nextern_func f 1 int {spelling}\n"
        expect(command([ASM, "--validate", "-"], input=text, check=False).returncode != 0,
               f"accepted invalid {spelling}")
    if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1":
        return

    ir = ["CRUNCH-IR 55\n"]
    c = [r'''
#define _GNU_SOURCE
#include <stdarg.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>
#include <stdlib.h>
''']
    checks = []
    for n in range(3, 17):
        tail = f"unsigned char tail[{n - 3}];" if n > 3 else ""
        c.append(f"""
typedef struct __attribute__((packed)) {{ unsigned char a; unsigned short b; {tail} }} S{n};
_Static_assert(sizeof(S{n}) == {n}, "size");
extern S{n} echo{n}(S{n}, long, S{n}, long);
extern int call{n}(void *, const void *);
extern int indirect{n}(void *, const void *);
extern int variadic{n}(void *, int, ...);
extern int named{n}(void *, S{n}, long, long, long, long, long, long, ...);
extern int callva{n}(const void *);
S{n} host{n}(S{n} a, long x, S{n} b, long y, long z, long w, long q, long r, long s) {{
    if (x != 11 || y != 12 || z != 13 || w != 14 || q != 15 || r != 16 || s != 17 ||
        memcmp(&a, &b, {n})) abort();
    ((unsigned char *)&a)[{n - 1}] ^= 0x55;
    return a;
}}
int hostva{n}(int tag, ...) {{
    va_list ap; va_start(ap, tag);
    S{n} a = va_arg(ap, S{n});
    long x = va_arg(ap, long);
    va_end(ap);
    return tag == 21 && x == 22 && ((unsigned char *)&a)[0] == 7;
}}
""")
        ir.append(f"""extern_func host{n} 9 mem{n} mem{n} long mem{n} long long long long long long
extern_func hostva{n} 3 int int mem{n} long
func echo{n} 4 mem{n}
param 0 0 mem{n}
param 1 1 long
param 2 2 mem{n}
param 3 3 long
load 1
push 11
eq long
jz L{n}
load 3
push 12
eq long
jz L{n}
load 2
retagg mem{n}
label L{n}
load 0
retagg mem{n}
end
""")
        for name, op in (("call", f"callagg host{n} 9"),
                         ("indirect", f"callptr 9 mem{n} mem{n} long mem{n} long long long long long long")):
            target = f"fnaddr host{n}\n" if name == "indirect" else ""
            ir.append(f"""func {name}{n} 2 int
param 0 0 ptr
param 1 1 ptr
load 0
{target}load 1
push 11
load 1
push 12
push 13
push 14
push 15
push 16
push 17
{op}
drop
push 0
ret int
end
""")
        ir.append(f"""abi_variadic variadic{n}
func variadic{n} 2 int
param 0 0 ptr
param 1 1 int
variadic
localblock list 24 8
localalias ap list 0 byte
laddr ap
vastart
load 0
laddr ap
vaargagg mem{n}
drop
laddr ap
vaarg gp
loadind long
push 22
eq long
ret int
end
abi_variadic named{n}
func named{n} 8 int
param 0 0 ptr
param 1 1 mem{n}
param 2 2 long
param 3 3 long
param 4 4 long
param 5 5 long
param 6 6 long
param 7 7 long
variadic
localblock list 24 8
localalias ap list 0 byte
laddr ap
vastart
load 0
laddr ap
vaargagg mem{n}
drop
laddr ap
vaarg gp
loadind long
push 22
eq long
ret int
end
func callva{n} 1 int
param 0 0 ptr
fnaddr hostva{n}
push 21
load 0
push 22
callptr 3 int int mem{n} long
ret int
end
""")
        checks.append(f"""
    {{
        S{n} a, b, result;
        memcpy(&a, src, {n});
        b = a;
        ((unsigned char *)&b)[0] = 9;
        result = echo{n}(a, 11, b, 12);
        if (memcmp(&b, &result, {n})) return {n};
        if (call{n}(dst, src) || dst[0] != 7 ||
            dst[{n - 1}] != (src[{n - 1}] ^ 0x55)) return {n};
        if (indirect{n}(dst, src) || dst[{n - 1}] != (src[{n - 1}] ^ 0x55)) return {n};
        memset(aligned, 0xcc, sizeof(aligned));
        if (!variadic{n}(aligned, 0, a, 22L) || memcmp(aligned, src, {n}) ||
            aligned[{n}] != 0xcc || !callva{n}(src)) return {n};
        memset(aligned, 0xcc, sizeof(aligned));
        if (!named{n}(aligned, a, 1L, 2L, 3L, 4L, 5L, 6L, a, 22L) ||
            memcmp(aligned, src, {n}) || aligned[{n}] != 0xcc) return {n};
    }}
""")
    for n in (1, 2):
        ir.append(f"""func small_echo{n} 1 mem{n}
param 0 0 mem{n}
load 0
retagg mem{n}
end
func small_round{n} 2 int
param 0 0 ptr
param 1 1 ptr
load 0
load 1
callagg small_echo{n} 1
drop
push 0
ret int
end
""")
        c.append(f"extern int small_round{n}(void *, const void *);\n")
    c.append("""
int main(void) {
    long page = sysconf(_SC_PAGESIZE);
    unsigned char *s = mmap(0, page * 2, PROT_READ | PROT_WRITE,
                            MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    unsigned char *d = mmap(0, page * 2, PROT_READ | PROT_WRITE,
                            MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (s == MAP_FAILED || d == MAP_FAILED ||
        mprotect(s + page, page, PROT_NONE) || mprotect(d + page, page, PROT_NONE)) return 99;
    _Alignas(8) unsigned char aligned[24];
""")
    for n in (1, 2):
        c.append(f"    memset(s + page - {n}, 7, {n});\n"
                 f"    if (small_round{n}(d + page - {n}, s + page - {n}) || "
                 f"memcmp(d + page - {n}, s + page - {n}, {n})) return {n};\n")
    for n, check in zip(range(3, 17), checks):
        c.append(f"    unsigned char *src{n} = s + page - {n}, *dst{n} = d + page - {n};\n"
                 f"    memset(src{n}, 7, {n});\n" +
                 check.replace("src", f"src{n}").replace("dst", f"dst{n}"))
    c.append("    return 0;\n}\n")
    with tempfile.TemporaryDirectory(prefix="small-memory-abi-", dir=ROOT / "build") as directory:
        td = pathlib.Path(directory)
        assembly, host, exe = td / "ir.s", td / "host.c", td / "test"
        generated = command([ASM, "--no-entry", "-"], input="".join(ir)).stdout
        expect("CABI1 D echo3 unknown mem3 mem3 long mem3 long" in generated,
               "small memory ABI metadata was not preserved")
        assembly.write_text(generated)
        host.write_text("".join(c))
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Werror", "-no-pie",
                 host, assembly, "-o", exe])
        result = command([exe], check=False)
        expect(result.returncode == 0,
               f"small MEMORY aggregate interoperability failed: {result.returncode} {result.stderr}")
        executable = """CRUNCH-IR 54
func echo 1 mem3
param 0 0 mem3
load 0
retagg mem3
end
func main 0 int
localblock input 3 1
localblock output 3 1
localalias i input 0 byte
localalias o output 0 byte
laddr i
push 42
storeind byte
drop
laddr o
laddr i
callagg echo 1
loadind byte
cast byte int
ret int
end
"""
        assembly.write_text(command([ASM, "-"], input=executable).stdout)
        obj = td / "ir.o"
        command([TEST_AS, "-o", obj, assembly])
        command([*TEST_LINK, "-o", exe, obj, LIBCRUNCH])
        expect(command([exe], check=False).returncode == 42,
               "v54 executable small aggregate round trip failed")


def variadic_frame_case():
    """Validate variadic frame initialization and System V interoperability.

    Returns:
        None; raises AssertionError for invalid IR or incorrect argument state.
    """
    ir = (FIXTURES / "ir/variadic_frame.bir").read_text()
    command([ASM, "--validate", "-"], input=ir)
    executable_ir = ("CRUNCH-IR 30\nfunc target 1 int\nparam 0 0 int\nvariadic\n"
                     "localblock list 24 8\nlocalalias ap list 0 byte\n"
                     "laddr ap\nvastart\npush 0\nret int\nend\n"
                     "func main 0 int\npush 0\nret int\nend\n")
    command([ASM, "--validate", "-"], input=executable_ir)
    invalid = (
        (ir.replace("CRUNCH-IR 31", "CRUNCH-IR 29", 1), "unknown instruction"),
        ("CRUNCH-IR 31\nfunc target 0 int\nvariadic\npush 0\nret int\nend\n", "variadic directive"),
        ("CRUNCH-IR 31\nfunc target 1 int\nparam 0 0 int\nvariadic\nvariadic\npush 0\nret int\nend\n", "variadic directive"),
        ("CRUNCH-IR 31\nfunc target 1 int\nparam 0 0 int\npush 0\ndrop\nvariadic\npush 0\nret int\nend\n", "variadic directive"),
        ("CRUNCH-IR 31\nfunc target 1 int\nparam 0 0 int\npush 0\nvastart\npush 0\nret int\nend\n", "requires a variadic function"),
        ("CRUNCH-IR 31\nfunc target 1 int\nparam 0 0 int\nvariadic\nvastart\npush 0\nret int\nend\n", "underflow"),
        ("CRUNCH-IR 31\nfunc target 1 int\nparam 0 0 int\nvariadic\npushr 0x0000000000000000\nvastart\npush 0\nret int\nend\n", "requires a pointer"),
        ("CRUNCH-IR 31\nfunc target 1 int\nparam 0 0 int\nvariadic\npush 0\nvastart extra\npush 0\nret int\nend\n", "invalid operands"),
        ("CRUNCH-IR 31\nfunc target 1 int\nparam 0 0 int\npush 0\nvaarg bad\nret int\nend\n", "invalid operands"),
        ("CRUNCH-IR 31\nfunc target 1 int\nparam 0 0 int\npushr 0x0000000000000000\nvaarg gp\nret int\nend\n", "vaarg requires a pointer"),
        ("CRUNCH-IR 31\nfunc target 1 int\nparam 0 0 int\npush 0\nvacopy\npush 0\nret int\nend\n", "underflow"),
        ("CRUNCH-IR 31\nfunc target 1 int\nparam 0 0 int\npush 0\npushr 0x0000000000000000\nvacopy\npush 0\nret int\nend\n", "vacopy requires two pointers"),
        ("CRUNCH-IR 31\nfunc target 0 int\npush 0\npush 0\nvaargagg agg8\nret int\nend\n", "unknown instruction"),
        ("CRUNCH-IR 33\nfunc target 0 int\npush 0\npush 0\nvaargagg int\nret int\nend\n", "invalid operands"),
        ("CRUNCH-IR 33\nfunc target 0 int\npush 0\nvaargagg agg8\nret int\nend\n", "underflow"),
        ("CRUNCH-IR 33\nfunc target 0 int\npush 0\npushr 0x0000000000000000\nvaargagg agg8\nret int\nend\n", "vaargagg requires"),
    )
    for text, diagnostic in invalid:
        result = command([ASM, "--validate", "-"], input=text, check=False)
        expect(result.returncode != 0 and diagnostic in result.stderr,
               f"invalid variadic-frame IR not rejected as expected: {result.stderr}")
    with tempfile.TemporaryDirectory(prefix="crunch-variadic-frame-") as directory:
        td = pathlib.Path(directory)
