        td = pathlib.Path(directory)
        obj, exe = td / "source.o", td / "program"
        env = dict(os.environ, LD_LIBRARY_PATH=str(BUILD))
        for mode in ("executable", "module", "dynamic"):
            if mode == "module":
                command([DRIVER, "-c", fixture, "-o", obj])
                command([DRIVER, obj, "-o", exe])
            else:
                command([DRIVER, *(["--dynamic"] if mode == "dynamic" else []),
                         fixture, "-o", exe], env=env)
            result = command([exe], check=False, env=env)
            expect(result.returncode == 42,
                   f"ctype failed in {mode} mode: {result.returncode} {result.stderr}")

        source = td / "override.bc"
        source.write_text("#include <ctype.h>\nint isalpha(int c) { return c + 3; }\n"
                          "int main() { return isalpha(39); }\n")
