def ssize_t_header_case():
    """Check POSIX signed-size declarations and syscall result behavior.

    Returns:
        None; raises AssertionError for incorrect types or execution behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-ssize-t-") as directory:
        td = pathlib.Path(directory)
        source, obj, exe = td / "source.bc", td / "source.o", td / "program"
        for header in ("sys/types.h", "stdio.h", "unistd.h", "dirent.h"):
            source.write_text(
                f"#include <{header}>\n"
                "typedef long ssize_t;\n"
                "int main() { long n = -1; ssize_t* p = &n; long* q = p; "
                "size_t bytes = sizeof(ssize_t); "
                "return *q < 0 && bytes == 8 ? 42 : 1; }\n")
            command([DRIVER, source, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"ssize_t was unavailable or incompatible through {header}")

        source.write_text("#include <sys/types.h>\n#include <stdio.h>\n#include <unistd.h>\n"
                          "#include <dirent.h>\nint main() { return 0; }\n")
        expanded = command([PP, source]).stdout
        for module in (False, True):
            ir = command([IR, *(["--module"] if module else []), "-"],
                         input=expanded).stdout
            expect(ir.startswith(f"CRUNCH-IR {3 if module else 2}\n"),
                   "unused ssize_t or size_t declarations changed signed-only IR")

        source.write_text('''#include <sys/types.h>
#include <stdio.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>
typedef long ssize_t;
ssize_t read(int fd, void* buffer, size_t count);
ssize_t write(int fd, const void* buffer, size_t count);
ssize_t readlink(const char* path, char* buffer, size_t count);
ssize_t readlinkat(int fd, const char* path, char* buffer, size_t count);
ssize_t getdents64(int fd, void* buffer, size_t count);
int main() {
    int fds[2];
    char buffer[4];
    if (pipe(fds) != 0) return 1;
    ssize_t n = write(fds[1], "abc", 3);
    if (n != 3 || close(fds[1]) != 0) return 2;
    n = read(fds[0], buffer, sizeof(buffer));
    if (n != 3 || buffer[0] != (char)'a' || buffer[2] != (char)'c') return 3;
    if (read(fds[0], buffer, sizeof(buffer)) != 0 || close(fds[0]) != 0) return 4;
    n = read(-1, buffer, 1);
    if (n >= 0 || n != -1 || errno != EBADF) return 5;
    if (snprintf(buffer, sizeof(buffer), "%ld", n) != 2 ||
        buffer[0] != (char)'-' || buffer[1] != (char)'1') return 10;
    if (write(-1, buffer, 1) != -1 || errno != EBADF) return 6;
    if (getdents64(-1, buffer, sizeof(buffer)) != -1 || errno != EBADF) return 7;
    if (readlink("", buffer, sizeof(buffer)) != -1) return 8;
    if (readlinkat(-1, "x", buffer, sizeof(buffer)) != -1 || errno != EBADF) return 9;
    return 42;
}
''')
        for separate in (False, True):
            if separate:
                command([DRIVER, "-c", source, "-o", obj])
                command([DRIVER, obj, "-o", exe])
            else:
                command([DRIVER, source, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"ssize_t syscall results failed in {'module' if separate else 'executable'} mode")


def size_t_library_case():
    """Check size-based library declarations and calls in both link modes.

    Returns:
        None; raises AssertionError for incorrect declarations or behavior.
    """
    source_text = """
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <dirent.h>
#include <sys/mman.h>
#include <errno.h>
size_t strlen(const char* text);
void* memcpy(void* destination, const void* source, size_t count);
void* memset(void* destination, int value, size_t count);
int memcmp(const void* a, const void* b, size_t count);
int strncmp(const char* a, const char* b, size_t count);
void* malloc(size_t count);
void* realloc(void* address, size_t count);
size_t fread(void* buffer, size_t size, size_t count, struct FILE* stream);
size_t fwrite(const void* buffer, size_t size, size_t count, struct FILE* stream);
int snprintf(char* buffer, size_t count, const char* format);
long read(int fd, void* buffer, size_t count);
long write(int fd, const void* buffer, size_t count);
long readlink(const char* path, char* buffer, size_t count);
long readlinkat(int fd, const char* path, char* buffer, size_t count);
long getdents64(int fd, void* buffer, size_t count);
void* mmap(void* address, size_t count, int prot, int flags, int fd, long offset);
int munmap(void* address, size_t count);
void* mremap(void* address, size_t oldsize, size_t newsize, int flags, void* dest);
size_t identity(size_t n) { return n; }
int main() {
    size_t max = (size_t)-1;
    if (identity(strlen("")) - 1 != max) return 1;
    if (identity(fread(0, 0, max, 0)) - 1 != max) return 2;
    if (identity(fwrite(0, max, 0, 0)) - 1 != max) return 3;
    if (strncmp("a", "b", max) >= 0) return 4;
    char buffer[8];
    if (snprintf(buffer, sizeof(buffer), "%s", "ok") != 2 ||
        strcmp(buffer, "ok") != 0) return 5;
    char* p = malloc(sizeof(buffer));
    if (!p) return 6;
    memcpy(p, buffer, 3);
    if (memcmp(p, "ok", 3) != 0) return 7;
    errno = 0;
    if (realloc(p, max) || errno != ENOMEM || strcmp(p, "ok") != 0) return 9;
    errno = 0;
    if (malloc(max) || errno != ENOMEM) return 10;
    p = realloc(p, 16);
    if (!p || strcmp(p, "ok") != 0) return 8;
    free(p);
    return 42;
}
"""
    with tempfile.TemporaryDirectory(prefix="crunch-size-api-") as directory:
        td = pathlib.Path(directory)
        source, obj, exe = td / "source.bc", td / "source.o", td / "program"
        source.write_text(source_text)
        for separate in (False, True):
            if separate:
                command([DRIVER, "-c", source, "-o", obj])
                command([DRIVER, obj, "-o", exe])
            else:
                command([DRIVER, source, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"size_t library calls failed in {'module' if separate else 'executable'} mode")


def size_t_library_abi_case():
    """Check full-width size_t calls across the Crunch and C runtime ABI.

    Returns:
        None; raises AssertionError for incorrect argument or result bits.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-size-abi-") as directory:
        td = pathlib.Path(directory)
        source, obj, exe = td / "source.bc", td / "source.o", td / "program"
        source.write_text("""
#include <stdio.h>
#include <string.h>
int main() {
    size_t max = (size_t)-1;
    int negative = -1;
    if (strlen("x") != max) return 1;
    if (fread(0, negative, 2, 0) != max - 1) return 2;
    if (fwrite(0, 3, negative, 0) != max - 2) return 3;
    if (snprintf(0, negative, "") != 42) return 4;
    return 42;
}
""")
        stub, stub_obj = td / "stub.c", td / "stub.o"
        stub.write_text("""
#include <stddef.h>
size_t __crunch_strlen(const char *p) { (void)p; return (size_t)-1; }
size_t __crunch_fread(void *p, size_t s, size_t n, void *f) {
    (void)p; (void)f; return s == (size_t)-1 && n == 2 ? (size_t)-2 : 0;
}
size_t __crunch_fwrite(const void *p, size_t s, size_t n, void *f) {
    (void)p; (void)f; return s == 3 && n == (size_t)-1 ? (size_t)-3 : 0;
}
int __crunch_snprintf_v36(const size_t *slots, size_t n) {
    return n == 0 && slots[1] == (size_t)-1 ? 42 : 1;
}
""")
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Werror",
                 "-fno-asynchronous-unwind-tables", "-c", stub, "-o", stub_obj])
        command([DRIVER, "-c", source, "-o", obj])
        command([DRIVER, obj, stub_obj, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "size_t runtime calls lost unsigned argument or return bits")
        stub.write_text("""
#include <stddef.h>
#include <stdint.h>
extern long __crunch_snprintf_v6(const size_t *, size_t);
static int error_number;
int *_crunch_errno_location(void) { return &error_number; }
long _crunch_format(const void *format, size_t count, const size_t *state,
                    void *writer, void *pad, int enabled) {
    (void)format; (void)count; (void)writer; (void)pad;
    return state[1] == (size_t)-2 && enabled ? 42 : 1;
}
int main(void) {
    char buffer = 'x';
    size_t slots[] = {(size_t)(uintptr_t)"", (size_t)-1, (size_t)(uintptr_t)&buffer};
    return __crunch_snprintf_v6(slots, 0) == 42 && buffer == 0 ? 0 : 1;
}
""")
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Werror", "-no-pie",
                 stub, ROOT / "lib/snprintf.s", "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "snprintf runtime rejected a high-bit unsigned capacity")


