def native_assembler_bootstrap_case(assembler=None):
    """Build the assembler with Crunch and compare object generation and failures.

    Args:
        assembler: Previously self-built assembler, or None to build it.
    Returns:
        None; raises AssertionError for an incorrect self-built assembler.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-selfhost-as-") as directory:
        td = pathlib.Path(directory)
        if assembler is None:
            objects = []
            for source in ("src/assembler/assembler.c", "src/driver/crunch_as_main.c"):
                obj = td / (pathlib.Path(source).name + ".o")
                command([DRIVER, "-D_Thread_local=", "-I", ROOT / "include",
                         "-c", ROOT / source, "-o", obj], timeout=600)
                objects.append(obj)
            assembler = td / "crunch-as"
            command([DRIVER, "--static", *objects, "-o", assembler], timeout=120)
        sources = (
            '.text\n.globl _start\n_start: mov $60,%eax\nmov $42,%edi\nsyscall\n',
            '.data\n.irpc v,abxy\n.ascii "\\v"\n.endr\n'
            '.section .text.pick,"axG",@progbits,pick,comdat\n.globl pick\npick: ret\n'
            '.section .data.pick,"awG",@progbits,pick,comdat\n.quad external\n',
            '.section .large,"awM",@nobits,4\n.zero 67108863\n',
        )
        for index, source in enumerate(sources):
            actual, expected = td / "actual.o", td / "expected.o"
            command([assembler, "-o", actual], input=source, timeout=120)
            command([BUILD / "crunch-as", "-o", expected], input=source, timeout=120)
            expect(actual.read_bytes() == expected.read_bytes(),
                   f"self-built assembler emitted a different object for case {index}")
            if index == 0:
                executable = td / "program"
                command([BUILD / "crunch-ld", "-nostdlib", "-o", executable, actual])
                expect(command([executable], check=False).returncode == 42,
                       "self-built assembler produced a nonfunctional executable")
        for expression in ("9223372036854775807+1", "-9223372036854775808-1",
                           "9223372036854775807*2", "-9223372036854775808*-1"):
            source = f".set invalid,{expression}\n.byte invalid\n"
            result = command([assembler, "-o", td / "invalid.o"], input=source,
                             check=False, timeout=120)
            expect(result.returncode != 0 and result.stderr,
                   f"self-built assembler accepted overflow: {expression}")

def native_archiver_bootstrap_case(archiver=None):
    """Build the archiver with Crunch and check archives and failure cleanup.

    Args:
        archiver: Previously self-built archiver, or None to build it.
    Returns:
        None; raises AssertionError for an incorrect self-built archiver.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-selfhost-ar-") as directory:
        td = pathlib.Path(directory)
        if archiver is None:
            archiver = td / "crunch-ar"
            command([DRIVER, "-D_Thread_local=", "-I", ROOT / "include",
                     "--static", ROOT / "src/archiver/crunch-ar.c", "-o", archiver],
                    timeout=600)
        source = td / "library.bc"
        source.write_text("int answer() { return 42; }\n")
        obj = td / "long_archive_member_name.o"
        command([DRIVER, "-c", source, "-o", obj])
        actual, expected = td / "actual.a", td / "expected.a"
        command([archiver, "rcs", actual, obj])
        command([BUILD / "crunch-ar", "rcs", expected, obj])
        original = actual.read_bytes()
        expect(original == expected.read_bytes(), "self-built archiver emitted a different archive")
        for args in (["t"], ["tv"]):
            expect(command([archiver, *args, actual]).stdout ==
                   command([BUILD / "crunch-ar", *args, expected]).stdout,
                   "self-built archiver listed incorrect members")
        extract = td / "extract"
        extract.mkdir()
        command([archiver, "x", actual], cwd=extract)
        expect((extract / obj.name).read_bytes() == obj.read_bytes(),
               "self-built archiver extracted incorrect data")
        main = td / "main.bc"
        main.write_text("int answer(); int main() { return answer(); }\n")
        exe = td / "program"
        command([DRIVER, "--static", main, actual, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "self-built archiver produced an unusable index")
        bad = td / "bad.o"
        bad.write_bytes(b"\x7fELF" + bytes(60))
        result = command([archiver, "rcs", actual, bad], check=False)
        expect(result.returncode != 0 and result.stderr and actual.read_bytes() == original,
               "self-built archiver damaged an archive after invalid input")
        expect(not list(td.glob("actual.a.tmp.*")),
               "self-built archiver left a temporary archive after failure")
        actual.chmod(0o640)
        command([archiver, "rcs", actual, obj])
        expect(actual.stat().st_mode & 0o777 == 0o640,
               "self-built archiver did not preserve existing permissions")
        fresh = td / "fresh.a"
        command([SHELL, "-c", 'umask 027; exec "$@"', "sh", archiver, "rcs", fresh, obj])
        expect(fresh.stat().st_mode & 0o777 == 0o640,
               "self-built archiver did not apply the creation umask")
        random_stub = td / "random.s"
        random_stub.write_text(
            ".text\n.globl __crunch_getrandom\n__crunch_getrandom:\n"
            "movl $0,(%rdi)\nmovw $0,4(%rdi)\nmov $6,%eax\nret\n")
        collision_ar = td / "collision-ar"
        command([DRIVER, "-D_Thread_local=", "-I", ROOT / "include", "--static",
                 ROOT / "src/archiver/crunch-ar.c", random_stub, "-o", collision_ar],
                timeout=600)
        occupied = td / "actual.a.tmp.aaaaaa"
        occupied.write_text("untouched")
        result = command([collision_ar, "rcs", actual, obj], check=False)
        expect(result.returncode != 0 and result.stderr and actual.read_bytes() == original and
               occupied.read_text() == "untouched",
               "temporary archive collision damaged existing files")
        expect(list(td.glob("actual.a.tmp.*")) == [occupied],
               "temporary archive collision left unexpected files")

def native_toolchain_bootstrap_case():
    """Build and exercise all native tools individually and together.

    Returns:
        None; raises AssertionError if a self-built tool behaves incorrectly.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-selfhost-tools-") as directory:
        td = pathlib.Path(directory)
        assembler, linker, archiver = (td / name for name in ("crunch-as", "crunch-ld", "crunch-ar"))
        common = [DRIVER, "-D_Thread_local=", "-I", ROOT / "include"]
        command([*common, "--static", ROOT / "src/assembler/assembler.c",
                 ROOT / "src/driver/crunch_as_main.c", "-o", assembler], timeout=600)
        command([*common, "-I", ROOT / "build", "--static",
                 ROOT / "src/linker/crunch-ld.c", "-o", linker], timeout=600)
        command([*common, "--static", ROOT / "src/archiver/crunch-ar.c",
                 "-o", archiver], timeout=600)
        native_assembler_bootstrap_case(assembler)
        native_archiver_bootstrap_case(archiver)
        linker_automatic_runtime_case(linker)
        native_shared_array_case(linker)
        main, value = td / "main.o", td / "value.o"
        command([assembler, "-o", main], input=
                ".text\n.globl _start\n_start: call value@PLT\n"
                "mov %eax,%edi\nmov $60,%eax\nsyscall\n")
        command([assembler, "-o", value], input=
                ".text\n.globl value\n.type value,@function\nvalue: mov $42,%eax\nret\n")
        archive, shared, exe = td / "value.a", td / "libvalue.so", td / "program"
        command([archiver, "rcs", archive, value])
        command([linker, "-nostdlib", "-o", exe, main, archive])
        expect(command([exe], check=False).returncode == 42,
               "self-built toolchain produced a broken static executable")
        command([linker, "-nostdlib", "-shared", "-soname", "libvalue.so", "-o", shared, value])
        command([linker, "-nostdlib", "-dynamic", "-rpath", td, "-o", exe, main, shared])
        expect(command([exe], check=False).returncode == 42,
               "self-built toolchain produced a broken dynamic executable")
        output_dir = td / "old-directory"
        output_dir.mkdir()
        command([linker, "-nostdlib", "-o", output_dir, main, archive])
        expect(command([output_dir], check=False).returncode == 42,
               "self-built linker could not replace an empty output directory")

def object_assembler_case():
    """Check the experimental object assembler as an opt-in compiler stage.

    Returns:
        None; raises AssertionError for incorrect assembler or driver behavior.
    """
    assembler = BUILD / "crunch-as"
    command([PYTHON, FIXTURES / "assembler/tests.py", assembler])
    with tempfile.TemporaryDirectory(prefix="crunch-object-assembler-") as directory:
        td = pathlib.Path(directory)
        obj, exe = td / "program.o", td / "program"
        source = FIXTURES / "ir/main42.bc"
        for inputs in ([source], ["-c", source]):
            output = obj if inputs[0] == "-c" else exe
            result = command([DRIVER, "--with-crunch-as", "-v",
                              *inputs, "-o", output])
            expect(f"{assembler} -o " in result.stderr, "driver did not select crunch-as")
            if output == obj:
                command([DRIVER, obj, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   "opt-in Crunch source compilation failed")
        for suffix, prefix in (("s", ""), ("S", "#define VALUE 42\n")):
            assembly = td / f"source.{suffix}"
            assembly.write_text(prefix + ".text\n.global _start\n_start:\n"
                                + ("mov $VALUE, %edi\n" if prefix else "mov $42, %edi\n")
                                + "mov $60, %eax\nsyscall\n")
            command([DRIVER, "--with-crunch-as", assembly, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"experimental assembler failed for .{suffix} input")
        command([assembler, "-o", obj], input=".text\n.globl value\nvalue:\nret\n")
        expect("value" in command(["nm", obj]).stdout, "assembler did not read standard input")
        command([assembler, "-o", obj, "-"], input=".text\n.globl value\nvalue:\nret\n")
        expect("value" in command(["nm", obj]).stdout, "assembler did not accept '-' input")
        result = command([assembler, "-o", "/dev/full"], input=".text\nret\n", check=False)
        expect(result.returncode != 0 and result.stderr,
               "assembler did not report object output failure")
        harness = td / "api-test"
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Wpedantic", "-Werror",
                 "-iquote", ROOT / "include", ROOT / "tests/unit/assembler/test_assembler.c",
                 ROOT / "src/assembler/assembler.c", "-o", harness])
        macro = td / "macro.s"
        macro.write_text('.file "api.c"\n'
                         ".ifdef api_seen\ninvalid_instruction\n.endif\n"
                         ".set api_seen,1\n"
                         ".macro emit_return\nret\n.endm\n"
                         ".macro emit_number value:req\n.byte \\value,\\@\n.endm\n"
                         ".text\n.globl value\n"
                         "value:\nmov $external+4, %rax\n"
                         "mov external+8(%rip), %rax\nmov %rax, external-4(%rip)\n"
                         "mov %fs, external(%rip)\ncall *external(%rip)\n"
                         "call external@PLT\njmp 1f\n1:\nloop 2f\n2:\nemit_return\n"
                         '.data\nemit_number "42"\n.p2align 6\n.quad external+4, external-8\n.long external+3\n'
                         ".local scratch\n.comm scratch,4,64\n.bss\n.zero 1\n"
                         '.section .api_merge,"aM",@progbits,4\n.byte 1\n'
                         '.section .api_group,"aG",@progbits,api_signature,comdat\n.quad external\n'
                         '.asciz "\\x41" "\\102"\n.string "api"\n'
                         '.irp v,"hello"\n.ifc \\v,hello\n.byte 1\n.endif\n.endr\n'
                         '.set api_count,2\n.rept api_count\n.byte 1\n.endr\n'
                         '.if api_count-2\ninvalid_instruction\n.endif\n')
        bad_macro = td / "bad-macro.s"
        bad_macro.write_text(".macro bad\ninvalid_instruction\n.endm\nbad\n")
        bad_inputs = [bad_macro]
        for index, instruction in enumerate((
                "mov symbol(%eax,%r9), %rax",
                "movq $symbol, %invalid",
                ".byte symbol",
                ".p2align 10\ninvalid_instruction",
                "loop out_of_range\n.zero 128\nout_of_range: ret",
                ".local scratch\n.comm scratch,4,1024\ninvalid_instruction",
                '.section .api_merge,"aM",@progbits,8\ninvalid_instruction',
                '.section .api_group,"aG",@progbits,api_signature,comdat\ninvalid_instruction',
                '.ascii "valid" trailing_junk',
                '.file "valid" trailing_junk',
                '.string "valid" trailing_junk',
                ".bytegarbage 42",
                ".data 1",
                ".altmacro",
                ".ifdef invalid+symbol\n.endif",
                ".macro required value:req\n.endm\nrequired",
                ".macro bad\n.byte 1\\missing\n.endm\nbad",
                ".if 0\n.else junk\n.endif",
                ".if api_count\n.byte 1\n.endif",
                "int $symbol",
                "mov symbol(%rip), %cr0",
                "addq $symbol, %rax",
                "call *symbol(%rax,%rsp,2)",
                "imul $symbol, symbol(%rax), %r10")):
            bad = td / f"bad-operand-{index}.s"
            bad.write_text(f".text\n{instruction}\n")
            bad_inputs.append(bad)
        other_obj = td / "other.o"
        api_args = [macro, td / "missing.s", obj, other_obj, *bad_inputs]
        api_result = command([harness, *api_args])
        expect(f"{bad_macro}:2: error:" in api_result.stderr and
               f"{bad_macro}:4: note: expanded from here" in api_result.stderr,
               "assembler API diagnostics lost their source or expansion location")
        expect(obj.read_bytes() == other_obj.read_bytes(),
               "assembler API state leaked across calls")
        many_symbols = td / "many-symbols.s"
        many_symbols.write_text(".lcomm saved,8\n.text\n" +
                                "".join(f"symbol_{i}:\n" for i in range(4200)) +
                                ".data\n.quad saved\n" +
                                ".quad symbol_4199\n" * 4200)
        command([harness, many_symbols, td / "missing.s", obj, other_obj, bad_macro])
        expect(obj.read_bytes() == other_obj.read_bytes(),
               "large assembler symbol or relocation tables leaked across API calls")
        include_dir = td / "api-includes"
        include_dir.mkdir()
        (include_dir / "api-unique.inc").write_text(".byte 42\n")
        include_input = td / "api-include.s"
        include_input.write_text('.data\n.include "api-unique.inc"\n')
        include_missing = td / "api-include-missing.s"
        include_missing.write_text('.include "api-definitely-missing.inc"\n')
        command([harness, "--includes", include_input, include_missing, include_dir, other_obj])
        sanitized = td / "api-test-sanitized"
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Wpedantic", "-Werror",
                 "-O1", "-g", "-fsanitize=address,undefined", "-iquote", ROOT / "include",
                 "-DASSEMBLER_TEST_FAIL_STRDUP",
                 ROOT / "tests/unit/assembler/test_assembler.c",
                 ROOT / "src/assembler/assembler.c", "-Wl,--wrap=strdup", "-o", sanitized])
        sanitizer_env = dict(os.environ, ASAN_OPTIONS="detect_leaks=1:exitcode=99",
                             LSAN_OPTIONS="exitcode=99", UBSAN_OPTIONS="halt_on_error=1")
        command([sanitized, *api_args], env=sanitizer_env)
        command([sanitized, "--includes", include_input, include_missing, include_dir, other_obj],
                env=sanitizer_env)
        symbol_data, symbol_branch = td / "symbol-data.s", td / "symbol-branch.s"
        symbol_data.write_text(".data\n.quad $marker\n")
        symbol_branch.write_text(".text\ncall marker\n")
        allocation_result = command([sanitized, "--fail-copy", symbol_data, symbol_branch, obj],
                                    env=sanitizer_env)
        for message in ("out of memory recording symbol", "out of memory recording relocation",
                        "out of memory recording branch"):
            expect(message in allocation_result.stderr, "missing diagnostic for failed symbol copy")
        unsupported = td / "unsupported.s"
        unsupported.write_text(".text\nmovq %xmm0, %eax\n")
        exe.write_text("unchanged")
        result = command([DRIVER, "--with-crunch-as", unsupported, "-o", exe],
                         check=False)
        expect(result.returncode != 0 and "crunch-as:" in result.stderr and
               exe.read_text() == "unchanged",
               "unsupported assembly did not fail explicitly or preserve output")
        included = td / "included.s"
        included.write_text("# comment\ninvalid_instruction\n")
        assembly = td / "source.S"
        assembly.write_text('#include "included.s"\n')
        result = command([DRIVER, "--with-crunch-as", "-c", assembly, "-o", obj],
                         check=False)
        expect(result.returncode != 0 and f"{included}:2: error:" in result.stderr,
               "preprocessed assembly diagnostic did not identify the included source")
        default_conf = td / "gnu-assembler.conf"
        default_conf.write_text("assembler = gnu\n")
        result = command([DRIVER, "-v", FIXTURES / "ir/main42.bc", "-o", exe],
                         env=dict(os.environ, CRUNCH_CONF_FILE=str(default_conf)))
        expect(f"{assembler} -o " not in result.stderr, "GNU assembler is not the default")

def native_linker_case():
    """Exercise native tool selection, native linking, and unsupported modes.

    Returns:
        None; raises AssertionError for incorrect selection or link behavior.
    """
    linker, assembler = BUILD / "crunch-ld", BUILD / "crunch-as"
    with tempfile.TemporaryDirectory(prefix="crunch-native-linker-") as directory:
        td = pathlib.Path(directory)
        conf, exe, obj = td / "crunch.conf", td / "program", td / "program.o"
        if test_linker == "crunch":
            expect(command([*TEST_LINK, "--version"]).stdout.startswith("crunch-ld "),
                   "native test mode did not select crunch-ld for direct links")
            for flags, output in (([], exe), (["-c"], obj)):
                result = command([DRIVER, "-v", *flags, FIXTURES / "ir/main42.bc", "-o", output])
                expect(f"{linker} -nostdlib " in result.stderr,
                       "native test mode did not select crunch-ld for the driver")
                if test_toolchain == "crunch":
                    expect(f"{assembler} -o " in result.stderr,
                           "full-native test mode did not select crunch-as for the driver")
                    if not flags:
                        expect(str(LIBCRUNCH) in result.stderr,
                               "full-native test mode did not link the native runtime")
        env = dict(os.environ, CRUNCH_CONF_FILE=str(conf))
        main, helper = td / "main.s", td / "helper.s"
        main.write_text(".text\n.globl _start\n_start:\ncall value\n"
                        "mov %eax,%edi\nmov $60,%eax\nsyscall\n")
        helper.write_text(".text\n.globl value\nvalue:\nmov $42,%eax\nret\n")
        helper_obj, archive = td / "helper.o", td / "libhelper.a"
        command(["as", "-o", helper_obj, helper])
        command(["ar", "rcs", archive, helper_obj])
        conf.write_text("assembler = crunch\nlinker = crunch\n")
        result = command([DRIVER, "-v", main, helper_obj, "-o", exe], env=env)
        expect(f"{assembler} -o " in result.stderr and f"{linker} -nostdlib " in result.stderr,
               "configured native tools were not selected")
        expect(command([exe], check=False).returncode == 42,
               "native cross-object executable did not run")
        command([assembler, "-o", obj, main])
        command([linker, "-nostdlib", "--require-defined=_start", "-o", exe, obj, archive])
        expect(command([exe], check=False).returncode == 42,
               "native linker did not extract a needed archive member")

        source, module = td / "main.bc", td / "module.bc"
        source.write_text('int calculate(int x); int printf(const char* format); int main() { printf("ok"); return calculate(40); }\n')
        module.write_text("int values[] = {1, 2}; int calculate(int x) { return x + values[1]; }\n")
        command([DRIVER, source, module, "-o", exe], env=env)
        result = command([exe], check=False)
        expect(result.returncode == 42 and result.stdout == "ok",
               "native linker failed to access module data or resolve the runtime")

        exe.write_text("unchanged")
        result = command([DRIVER, main, "-o", exe], env=env, check=False)
        expect(result.returncode != 0 and "undefined reference" in result.stderr and
               exe.read_text() == "unchanged", "failed native link changed the output")
        result = command([DRIVER, helper_obj, "-o", exe], env=env, check=False)
        expect(result.returncode != 0 and "required symbol" in result.stderr and
               exe.read_text() == "unchanged", "native linker accepted missing _start")
        command([DRIVER, "-c", main, "-o", obj], env=env)
        expect("REL (Relocatable file)" in command(["readelf", "-h", obj]).stdout,
               "native -c did not produce an ELF relocatable object")
        command([DRIVER, obj, helper_obj, "-o", exe], env=env)
        expect(command([exe], check=False).returncode == 42,
               "native -c output could not be linked")
        result = command([linker, "--unknown-option", helper_obj], check=False)
        expect(result.returncode != 0 and "unsupported option" in result.stderr,
               "native linker silently accepted an unknown option")
        tls = td / "tls.s"
        tls.write_text(".text\n.globl _start\n_start:\nlea value@TLSGD(%rip),%rdi\nret\n"
                       '.section .tdata,"awT",@progbits\n.globl value\nvalue: .long 42\n')
        command(["as", "-o", obj, tls])
        result = command([linker, "-nostdlib", "-o", exe, obj], check=False)
        expect(result.returncode != 0 and "unsupported relocation type" in result.stderr,
               "native linker silently accepted an unsupported TLS relocation")

        conf.write_text("assembler = crunch\nassembler = gnu\nlinker = crunch\nlinker = gnu\n")
        result = command([DRIVER, "--static", "-v", main, helper_obj, "-o", exe], env=env)
        expect(f"{assembler} -o " not in result.stderr and f"{linker} " not in result.stderr,
               "last GNU configuration settings did not override native tools")
        result = command([DRIVER, "--with-crunch-as", "-v", main, helper_obj,
                          "-o", exe], env=env)
        expect(f"{assembler} -o " in result.stderr, "CLI did not override assembler configuration")
        conf.write_text("assembler = invalid\n")
        for tool, args in ((DRIVER, [main, "-o", exe]), (PP, [FIXTURES / "ir/main42.bc"])):
            result = command([tool, *args], env=env, check=False)
            expect(result.returncode != 0 and "assembler must be gnu or crunch" in result.stderr,
                   "invalid tool configuration was accepted")


def native_archiver_case():
    """Check Crunch archive operations, indexes, interoperability, and failure safety.

    Returns:
        None; raises AssertionError for incorrect archives or archiver behavior.
    """
    archiver = BUILD / "crunch-ar"
    with tempfile.TemporaryDirectory(prefix="crunch-native-ar-") as directory:
        td = pathlib.Path(directory)
        library, main = td / "library.bc", td / "main.bc"
        library.write_text("int answer() { return 42; }\n")
        main.write_text("int answer(); int main() { return answer(); }\n")
        obj, archive, exe = td / "long_archive_member_name.o", td / "library.a", td / "program"
        command([DRIVER, "-c", library, "-o", obj])
        other = td / "boundary12345.o"
        command(["as", "-o", other], input=".text\n.globl extra\nextra: ret\n")
        command([archiver, "rcs", archive, obj, other])
        original = archive.read_bytes()
        names = [obj.name, other.name]
        for tool in (archiver, "ar"):
            expect(command([tool, "t", archive]).stdout.splitlines() == names,
                   f"{tool} did not read native archive members")
        index = command(["nm", "-s", archive]).stdout
        expect(f"answer in {obj.name}" in index and f"extra in {other.name}" in index,
               "native archive index is missing exported symbols")
        for selected in ("gnu", "crunch"):
            conf = td / "crunch.conf"
            conf.write_text(f"linker = {selected}\n")
            env = dict(os.environ, CRUNCH_CONF_FILE=str(conf))
            command([DRIVER, main, archive, "-o", exe], env=env)
            expect(command([exe], check=False).returncode == 42,
                   f"{selected} could not link the native archive")
        for tool in ("ar", archiver):
            extract = td / ("extract-gnu" if tool == "ar" else "extract-native")
            extract.mkdir()
            command([tool, "x", archive, obj.name], cwd=extract)
            expect((extract / obj.name).read_bytes() == obj.read_bytes(),
                   f"{tool} extracted incorrect member data")
        command([archiver, "q", archive, other])
        expect(command(["ar", "t", archive]).stdout.splitlines() == names + [other.name],
               "quick append did not preserve duplicate members")
        command([archiver, "d", archive, other])
        expect(command(["ar", "t", archive]).stdout.splitlines() == names,
               "delete did not remove exactly one matching member")
        command([archiver, "s", archive])
        expect("answer in " in command(["nm", "-s", archive]).stdout,
               "standalone index operation did not rebuild the symbol table")
        command([archiver, "r", archive, obj])
        expect(command(["ar", "t", archive]).stdout.splitlines() == names,
               "replacement duplicated an existing member")
        command([archiver, "rcs", archive, obj, other])
        expect(archive.read_bytes() == original, "archive output is not deterministic")
        for args in (["t", td / "missing.a"], ["r", archive, td / "missing.o"],
                     ["x", archive, "missing.o"]):
            result = command([archiver, *args], cwd=td, check=False)
            expect(result.returncode != 0 and result.stderr and archive.read_bytes() == original,
                   "missing archive or member did not fail safely")
        bad = td / "bad.o"
        bad.write_bytes(b"\x7fELF" + bytes(60))
        result = command([archiver, "rcs", archive, bad], check=False)
        expect(result.returncode != 0 and "ELF" in result.stderr and archive.read_bytes() == original,
               "invalid ELF input damaged an existing archive")
        malformed = bytearray(obj.read_bytes())
        shoff = struct.unpack_from("<Q", malformed, 40)[0]
        shentsize, shnum = struct.unpack_from("<HH", malformed, 58)
        for index in range(shnum):
            header = shoff + index * shentsize
            if struct.unpack_from("<I", malformed, header + 4)[0] == 2:
                struct.pack_into("<Q", malformed, header + 24, len(malformed) + 1)
                break
        else:
            raise AssertionError("fixture has no ELF symbol table")
        bad.write_bytes(malformed)
        result = command([archiver, "rcs", archive, bad], check=False)
        expect(result.returncode != 0 and "symbol table" in result.stderr and
               archive.read_bytes() == original, "out-of-bounds ELF symbol table was accepted")
        truncated = td / "truncated.a"
        truncated.write_bytes(b"!<arch>\nshort")
        result = command([archiver, "t", truncated], check=False)
        expect(result.returncode != 0 and result.stderr, "truncated archive was accepted")
        malformed_archive = bytearray(original)
        name_offset = malformed_archive.find(other.name.encode() + b"/")
        expect(name_offset >= 0, "archive fixture lost the short member name")
        malformed_archive[name_offset] = 0
        truncated.write_bytes(malformed_archive)
        result = command([archiver, "t", truncated], check=False)
        expect(result.returncode != 0 and "member name" in result.stderr,
               "archive containing an invalid member name was accepted")
        expect(not list(td.glob("library.a.tmp.*")), "archiver left a temporary archive after failure")


def driver_tool_paths_case():
    """Check configured tool paths and archive creation through the driver.

    Returns:
        None; raises AssertionError for incorrect paths, archives, or failure handling.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-tool-paths-") as directory:
        td = pathlib.Path(directory)
        conf, log = td / "crunch.conf", td / "calls"
        env = dict(os.environ, CRUNCH_CONF_FILE=str(conf))
        paths = []
        for name, tool in (("assembler", shutil.which("as")), ("linker", shutil.which("ld")),
                           ("archiver", shutil.which("ar"))):
            wrapper = td / f"{name} wrapper"
            wrapper.write_text(f'#!/bin/sh\nprintf "{name}\\n" >> "{log}"\nexec "{tool}" "$@"\n')
            wrapper.chmod(0o755)
            paths.append(wrapper)
        assembler, linker, archiver = paths
        conf.write_text(f"assembler_path = /does/not/exist\nassembler_path = {assembler}\n"
                        f"linker_path = {linker}\narchiver_path = {archiver}\n"
                        "assembler = gnu\nlinker = gnu\n")
        main, helper = td / "main.bc", td / "helper.bc"
        main.write_text("int answer(); int main() { return answer(); }\n")
        helper.write_text("int answer() { return 42; }\n")
        obj, archive, exe = td / "helper.o", td / "library.a", td / "program"
        command([DRIVER, "-c", helper, "-o", obj], env=env)
        command([DRIVER, "--archive", "-o", archive, obj], env=env)
        command([DRIVER, main, archive, "-o", exe], env=env)
        expect(command([exe], check=False).returncode == 42 and
               set(log.read_text().splitlines()) == {"assembler", "linker", "archiver"},
               "configured tool paths were not used for a working archive link")
        expect(command(["ar", "t", archive]).stdout.splitlines() == [obj.name],
               "archive has incorrect members")
        extra_obj = td / "extra.o"
        shutil.copy2(obj, extra_obj)
        command(["ar", "r", archive, extra_obj])
        command([DRIVER, "--archive", "-o", archive, obj], env=env)
        expect(command(["ar", "t", archive]).stdout.splitlines() == [obj.name],
               "archive creation retained members from an existing output")
        original = archive.read_bytes()
        missing = td / "missing.o"
        result = command([DRIVER, "--archive", "-o", archive, missing], env=env, check=False)
        expect(result.returncode != 0 and result.stderr and archive.read_bytes() == original,
               "failed archive creation did not preserve the output")
        other = td / "other"
        other.mkdir()
        shutil.copy2(obj, other / obj.name)
        for args in (["--archive", "-o", archive, obj, other / obj.name],
                     ["--archive", "-o", archive, main],
                     ["--archive", "-o", obj, obj],
                     ["--archive", "-c", "-o", archive, obj],
                     ["--archive", obj]):
            result = command([DRIVER, *args], env=env, check=False)
            expect(result.returncode != 0 and result.stderr and archive.read_bytes() == original,
                   f"invalid archive request was accepted: {args}")
        result = command([DRIVER, "--with-crunch-as", "-v", main, archive,
                          "-o", exe], env=env)
        expect(f"{BUILD / 'crunch-as'} -o " in result.stderr and
               f"{assembler} -o " not in result.stderr,
               "experimental assembler did not override the configured path")
        conf.write_text("archiver_path = /does/not/exist\n")
        result = command([DRIVER, "--archive", "-o", archive, obj], env=env, check=False)
        expect(result.returncode != 0 and "cannot run" in result.stderr and
               archive.read_bytes() == original, "missing archiver did not fail safely")
        for key in ("assembler_path", "linker_path"):
            conf.write_text(f"{key} = /does/not/exist\n")
            exe.write_text("unchanged")
            result = command([DRIVER, "--static", main, archive, "-o", exe], env=env, check=False)
            expect(result.returncode != 0 and "/does/not/exist" in result.stderr and
                   exe.read_text() == "unchanged", f"missing {key} did not fail safely")
        for key in ("assembler_path", "linker_path", "archiver_path"):
            for value in ("", "relative/tool"):
                conf.write_text(f"{key} = {value}\n")
                for tool, args in ((DRIVER, [main, "-o", exe]), (PP, [main])):
                    result = command([tool, *args], env=env, check=False)
                    expect(result.returncode != 0 and f"{key} must be an absolute path" in result.stderr,
                           f"{tool} accepted an invalid {key}")
        conf.write_text("")
        command([DRIVER, "--archive", "-o", archive, obj], env=env)
        expect(command(["ar", "t", archive]).stdout.splitlines() == [obj.name],
               "default native archiver did not create an archive")


def archiver_build_selection_case():
    """Check both configured archivers build usable runtime libraries.

    Returns:
        None; raises AssertionError for incorrect archiver selection or runtime links.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-ar-build-") as directory:
        td = pathlib.Path(directory)
        configure_tree = td / "configure-tree"
        configure_tree.mkdir()
        for name in ("configure", "Makefile.in", "build/config.mk.in",
                     "build/crunch-linker-config.h.in", "src/main.c"):
            target = configure_tree / name
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(ROOT / name, target)
        shutil.copytree(ROOT / "build-aux", configure_tree / "build-aux")
        for options, expected in (([], "gnu"), (["--with-default-archiver=gnu"], "gnu"),
                                  (["--with-default-archiver=crunch"], "crunch")):
            command([configure_tree / "configure", *options], cwd=configure_tree, timeout=180)
            config = (configure_tree / "build/config.mk").read_text()
            expect(f"CRUNCH_DEFAULT_ARCHIVER := {expected}\n" in config,
                   f"configure selected the wrong archiver for {options}")
        result = command([configure_tree / "configure", "--with-default-archiver=invalid"],
                         cwd=configure_tree, check=False, timeout=180)
        expect(result.returncode != 0 and "--with-default-archiver must be gnu or crunch" in result.stderr,
               "configure accepted an invalid default archiver")
        config_text = (BUILD.parent / "config.mk").read_text()
        shutil.copy2(BUILD.parent / "crunch-linker-config.h", td / "crunch-linker-config.h")
        config_text = "\n".join(line for line in config_text.splitlines()
                                if not line.startswith(("CRUNCH_AR :=", "CRUNCH_DEFAULT_ARCHIVER :=")))
        wrapper, calls = td / "gnu-ar", td / "gnu-calls"
        wrapper.write_text(f'#!/bin/sh\nprintf "called\\n" >> "{calls}"\n'
                           f'exec "{shutil.which("ar")}" "$@"\n')
        wrapper.chmod(0o755)
        source, obj = td / "main.bc", td / "main.o"
        source.write_text('int printf(const char* format); int main() { printf("archive;"); return 42; }\n')
        command([DRIVER, "-c", source, "-o", obj])
        archives = []
        for selected in ("gnu", "crunch"):
            out, config = td / selected, td / f"{selected}.mk"
            config.write_text(config_text + f"\nCRUNCH_AR := {wrapper}\n"
                              f"CRUNCH_DEFAULT_ARCHIVER := {selected}\n")
            archive = out / "libcrunch.a"
            env = {key: value for key, value in os.environ.items()
                   if key not in ("MAKEFLAGS", "MFLAGS", "MAKELEVEL")}
            make = ["make", "-C", ROOT / "build", f"CONFIG_MK={config}",
                    f"BUILD_DIR={out}", archive]
            command(make, env=env, timeout=180)
            expect(calls.exists(), "GNU archiver was not invoked for the GNU selection")
            if selected == "crunch":
                expect((out / "crunch-ar").is_file() and calls.read_text() == "called\n",
                       "native archiver selection unexpectedly invoked GNU ar")
            else:
                native_archive = out / "test-native/libcrunch.a"
                command(["make", "-C", ROOT / "build", f"CONFIG_MK={config}",
                         f"BUILD_DIR={out}", native_archive], env=env, timeout=180)
                expect((out / "crunch-ar").is_file() and calls.read_text() == "called\n",
                       "full-native test runtime used GNU ar")
                native_exe = td / "native-runtime-program"
                command([BUILD / "crunch-ld", "-nostdlib", "--require-defined=_start",
                         "-o", native_exe, obj, native_archive])
                native_result = command([native_exe], check=False)
                expect(native_result.returncode == 42 and native_result.stdout == "archive;",
                       "full-native test runtime could not link and execute")
            before = archive.stat().st_mtime_ns
            command(make, env=env, timeout=180)
            expect(archive.stat().st_mtime_ns == before, "unchanged runtime archive was rebuilt")
            archives.append(archive)
            for linker in (["ld"], [BUILD / "crunch-ld", "-nostdlib"]):
                exe = td / f"program-{selected}"
                command([*linker, "--require-defined=_start", "-o", exe, obj, archive])
                result = command([exe], check=False)
                expect(result.returncode == 42 and result.stdout == "archive;",
                       f"{selected} runtime archive failed to link or execute")
        expect(command(["ar", "t", archives[0]]).stdout ==
               command(["ar", "t", archives[1]]).stdout,
               "GNU and Crunch runtime archives contain different members")


def runtime_assembler_install_case():
    """Build and install the default native runtime without modifying the workspace.

    Returns:
        None; raises AssertionError for incorrect configuration, rebuilds, or execution.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-runtime-install-") as directory:
        td = pathlib.Path(directory)
        source, prefix = td / "source", td / "prefix"
        source.mkdir()
        for name in ("configure", "configure.ac", "Makefile.in", "Makefile.am", "aclocal.m4"):
            shutil.copy2(ROOT / name, source / name)
        for name in ("build-aux", "m4", "src", "include", "lib", "man", "conf"):
            shutil.copytree(ROOT / name, source / name)
        (source / "build").mkdir()
        for name in ("Makefile", "config.mk.in", "crunch-linker-config.h.in", "runtime-fallbacks.py"):
            shutil.copy2(ROOT / "build" / name, source / "build" / name)
        (source / "tests/unit").mkdir(parents=True)
        shutil.copytree(ROOT / "tests/unit/sema", source / "tests/unit/sema")
        env = {key: value for key, value in os.environ.items()
               if key not in ("MAKEFLAGS", "MFLAGS", "MAKELEVEL", "CRUNCH_CONF_FILE",
                              "CRUNCH_TEST_TOOLCHAIN", "CRUNCH_TEST_LINKER")}
        configure = [source / "configure", f"--prefix={prefix}"]
        result = command([*configure, "--with-runtime-assembler=invalid"],
                         cwd=source, env=env, check=False, timeout=180)
        expect(result.returncode != 0 and "--with-runtime-assembler must be gnu or crunch" in result.stderr,
               "configure accepted an invalid runtime assembler")
        command(configure, cwd=source, env=env, timeout=180)
        config = source / "build/config.mk"
        expect("CRUNCH_RUNTIME_ASSEMBLER := crunch\n" in config.read_text(),
               "Crunch runtime assembler is not the configure default")
        out = source / "build/out"
        archive = out / "libcrunch.a"
        make_archive = ["make", "-C", source / "build", f"CONFIG_MK={config}",
                        f"BUILD_DIR={out}", archive]
        command(make_archive, env=env, timeout=180)
        native_member = subprocess.run(["ar", "p", str(archive), "alloc_bytes.o"],
                                       check=True, stdout=subprocess.PIPE, timeout=60).stdout
        expect(native_member == (out / "lib-native/alloc_bytes.o").read_bytes(),
               "default runtime did not contain the native-assembled object")
        command([*configure, "--with-runtime-assembler=gnu"], cwd=source, env=env, timeout=180)
        expect("CRUNCH_RUNTIME_ASSEMBLER := gnu\n" in config.read_text(),
               "configure did not select the GNU runtime assembler")
        command(make_archive, env=env, timeout=180)
        gnu_member = subprocess.run(["ar", "p", str(archive), "alloc_bytes.o"],
                                    check=True, stdout=subprocess.PIPE, timeout=60).stdout
        expect(gnu_member == (out / "lib/alloc_bytes.o").read_bytes() and
               native_member != gnu_member,
               "GNU runtime override did not rebuild the archive with GNU objects")
        command(["make", "-C", source / "build", f"CONFIG_MK={config}", f"BUILD_DIR={out}",
                 out / "libcrunch.so"], env=env, timeout=180)
        command([PYTHON, "-c",
                 "import ctypes,sys; l=ctypes.CDLL(sys.argv[1]); "
                 "f=l.__crunch_strlen; f.argtypes=[ctypes.c_char_p]; f.restype=ctypes.c_long; "
                 "assert f(b'gnu')==3", out / "libcrunch.so"], env=env)
        command(configure, cwd=source, env=env, timeout=180)
        command(["make", "-j2"], cwd=source, env=env, timeout=300)
        rebuilt = subprocess.run(["ar", "p", str(archive), "alloc_bytes.o"],
                                 check=True, stdout=subprocess.PIPE, timeout=60).stdout
        expect(rebuilt == native_member, "switching back did not rebuild the native runtime")
        command(["make", "install"], cwd=source, env=env, timeout=300)
        installed_archive = prefix / "lib/crunch/libcrunch.a"
        installed_member = subprocess.run(["ar", "p", str(installed_archive), "alloc_bytes.o"],
                                          check=True, stdout=subprocess.PIPE, timeout=60).stdout
        expect(installed_member == native_member, "installed runtime is not the selected native runtime")
        conf = prefix / "etc/crunch/crunch.conf"
        conf.write_text(f"assembler = crunch\nlinker = crunch\nlibrary_path = {prefix / 'lib'}\n")
        driver = prefix / "bin/crunch"
        helper, main, obj, lib, exe = (td / name for name in
                                      ("helper.bc", "main.bc", "helper.o", "libhelper.a", "program"))
        helper.write_text("int answer() { return 42; }\n")
        main.write_text('int answer(); int printf(const char* format); int main() { printf("native;"); return answer(); }\n')
        result = command([driver, "-v", "-c", helper, "-o", obj], env=env)
        expect(str(prefix / "bin/crunch-as") in result.stderr and
               str(prefix / "bin/crunch-ld") in result.stderr,
               "installed compiler did not select its native assembler and linker")
        result = command([driver, "-v", "--archive", "-o", lib, obj], env=env)
        expect(f"{shutil.which('ar')} rcs" in result.stderr,
               "installed compiler did not select its detected GNU archiver")
        conf.write_text(f"assembler = crunch\nlinker = crunch\nlibrary_path = {prefix / 'lib'}\n"
                       f"archiver_path = {prefix / 'bin/crunch-ar'}\n")
        result = command([driver, "-v", "--archive", "-o", lib, obj], env=env)
        expect(str(prefix / "bin/crunch-ar") in result.stderr,
               "installed compiler did not honor its native archiver override")
        result = command([driver, "--static", "-v", main, "-L", td, "-lhelper", "-o", exe], env=env)
        run = command([exe], check=False)
        expect(str(installed_archive) in result.stderr and run.returncode == 42 and
               run.stdout == "native;", "installed all-native toolchain failed to link and run")
        installed_source = td / "installed-dynamic.bc"
        installed_source.write_text('int printf(const char* format); int main() { printf("shared;"); return 42; }\n')
        clean_env = {key: value for key, value in env.items()
                     if key not in ("LD_PRELOAD", "LD_LIBRARY_PATH", "LD_AUDIT")}
        result = command([driver, "-v", installed_source, "-o", exe], env=clean_env)
        run = command([exe], cwd=td, env=clean_env, check=False)
        expect(str(prefix / "lib/crunch/libcrunch.so") in result.stderr and
               run.returncode == 42 and run.stdout == "shared;",
               f"installed dynamic runtime was not found: {run.stderr}")
        command([prefix / "bin/crunch-ld", "-shared", "-soname", "libhelper.so",
                 "-o", td / "libhelper.so", obj], env=clean_env)
        command([driver, "--dynamic", "--rpath", "$ORIGIN", main, "-L", td,
                 "-lhelper", "-o", exe], env=clean_env)
        run = command([exe], cwd=td, env=clean_env, check=False)
        expect(run.returncode == 42 and run.stdout == "native;",
               f"installed driver RUNPATH did not find shared dependency: {run.stderr}")
        command([*configure, "--with-runtime-assembler=gnu"], cwd=source, env=env, timeout=180)
        command(make_archive, env=env, timeout=180)
        reverted = subprocess.run(["ar", "p", str(archive), "alloc_bytes.o"],
                                  check=True, stdout=subprocess.PIPE, timeout=60).stdout
        expect(reverted == gnu_member, "switching back did not rebuild the GNU runtime")
        main_obj = td / "main.o"
        command([driver, "-c", main, "-o", main_obj], env=env)
        for linker in (["ld"], [prefix / "bin/crunch-ld", "-nostdlib"]):
            command([*linker, "--require-defined=_start", "-o", exe, main_obj, obj, archive])
            run = command([exe], check=False)
            expect(run.returncode == 42 and run.stdout == "native;",
                   f"{linker} could not link the GNU-assembled runtime")


def static_archive_driver_case():
    """Check direct static archive inputs with both configured linkers.

    Returns:
        None; raises AssertionError for incorrect extraction or driver behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-driver-archive-") as directory:
        td = pathlib.Path(directory)
        main, library, unused = td / "main.bc", td / "library.bc", td / "unused.bc"
        main.write_text("int read_module(); int main() { return read_module(); }\n")
        library.write_text(
            "int values[] = {2, 42}; int read_module() {"
            "if (values[0] != 2) return 1; return values[1]; }\n")
        unused.write_text("int unused_archive_member() { return 7; }\n")
        main_obj, library_obj, unused_obj = (td / name for name in
                                              ("main.o", "library.o", "unused.o"))
        archive, combined, exe = td / "lib example.a", td / "combined.o", td / "program"
        conf = td / "crunch.conf"
        env = dict(os.environ, CRUNCH_CONF_FILE=str(conf))
        conf.write_text("assembler = crunch\nlinker = gnu\n")
        for source, obj in ((main, main_obj), (library, library_obj), (unused, unused_obj)):
            command([DRIVER, "-c", source, "-o", obj], env=env)
        command(["ar", "rcs", archive, library_obj, unused_obj])
        original = archive.read_bytes()
        for linker in ("gnu", "crunch"):
            conf.write_text(f"assembler = crunch\nlinker = {linker}\n")
            for input_file in (main, main_obj):
                command([DRIVER, input_file, archive, "-o", exe], env=env)
                expect(command([exe], check=False).returncode == 42,
                       f"{linker} failed to link or initialize a static archive member")
            command([DRIVER, "-c", main_obj, archive, "-o", combined], env=env)
            symbols = command(["nm", combined]).stdout
            expect("read_module" in symbols and "unused_archive_member" not in symbols,
                   f"{linker} partial link extracted incorrect archive members")
            command([DRIVER, combined, "-o", exe], env=env)
            expect(command([exe], check=False).returncode == 42,
                   f"{linker} partial link lost archived module initialization")
            reversed_link = command([DRIVER, archive, main_obj, "-o", exe], env=env, check=False)
            expect(reversed_link.returncode != 0 and "read_module" in reversed_link.stderr,
                   f"{linker} did not respect archive input order")
            command([DRIVER, "-c", archive, main_obj, "-o", combined], env=env)
            symbols = command(["nm", combined]).stdout
            expect(" U read_module" in symbols and " T read_module" not in symbols,
                   f"{linker} partial link extracted an earlier archive")
            exe.write_text("unchanged")
            missing = td / "missing.a"
            result = command([DRIVER, main_obj, missing, "-o", exe], env=env, check=False)
            expect(result.returncode != 0 and result.stderr and exe.read_text() == "unchanged",
                   f"{linker} missing archive did not fail safely")
            for option in ("-E", "--emit-ir", "-S"):
                result = command([DRIVER, option, archive, "-o", exe], env=env, check=False)
                expect(result.returncode != 0 and "require a Crunch source" in result.stderr and
                       exe.read_text() == "unchanged",
                       f"{option} accepted a static archive as source")
            result = command([DRIVER, main_obj, archive, "-o", archive], env=env, check=False)
            expect(result.returncode != 0 and "also an input" in result.stderr and
                   archive.read_bytes() == original, "archive output collision was not rejected")
        alias = td / "alias.a"
        os.link(archive, alias)
        result = command([DRIVER, main_obj, archive, "-o", alias], env=env, check=False)
        expect(result.returncode != 0 and "also an input" in result.stderr and
               archive.read_bytes() == original, "hard-linked archive output was not protected")


def driver_library_search_case():
    """Check static library search, ordering, precedence, and failure handling.

    Returns:
        None; raises AssertionError for incorrect search or driver behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-library-search-") as directory:
        td = pathlib.Path(directory)
        cli, first, second = (td / name for name in ("command line", "first", "second"))
        for path in (cli, first, second):
            path.mkdir()
        main, conf, exe, partial = td / "main.bc", td / "crunch.conf", td / "program", td / "partial.o"
        main.write_text("int answer(); int main() { return answer(); }\n")
        for path, value in ((cli, 42), (first, 23), (second, 17)):
            source, obj = path / "answer.s", path / "answer.o"
            source.write_text(f".text\n.globl answer\nanswer:\nmov ${value},%eax\nret\n")
            command(["as", "-o", obj, source])
            command(["ar", "rcs", path / "libanswer.a", obj])
        (cli / "libanswer.so").write_text("not a static archive")
        env = dict(os.environ, CRUNCH_CONF_FILE=str(conf))
        for linker in ("gnu", "crunch"):
            conf.write_text(f"linker = {linker}\nlibrary_path = {first}\nlibrary_path = {second}\n")
            for args, expected in (([main, "-lanswer"], 23),
                                   ([main, "-l", "answer", "-L", cli], 42),
                                   (["-L" + str(cli), main, "-l:libanswer.a"], 42),
                                   (["-L" + str(second), "-L", cli, main, "-lanswer"], 17)):
                command([DRIVER, "--static", *args, "-o", exe], env=env)
                expect(command([exe], check=False).returncode == expected,
                       f"{linker} searched static libraries in the wrong order: {args}")
            conf.write_text(f"linker = {linker}\nlibrary_path = {td / 'absent'}:{second}\n")
            command([DRIVER, "--static", main, "-lanswer", "-o", exe], env=env)
            expect(command([exe], check=False).returncode == 17,
                   f"{linker} did not search the full configured path")
            command([DRIVER, "-c", main, "-lanswer", "-o", partial], env=env)
            expect(" T answer" in command(["nm", partial]).stdout,
                   f"{linker} did not extract a library for a partial link")
            command([DRIVER, "-c", "-lanswer", main, "-o", partial], env=env)
            expect(" U answer" in command(["nm", partial]).stdout,
                   f"{linker} did not preserve library order in a partial link")
            exe.write_text("unchanged")
            for args in ([main, "-lmissing"], ["-lanswer", main]):
                result = command([DRIVER, "--static", *args, "-o", exe], env=env, check=False)
                expect(result.returncode != 0 and result.stderr and exe.read_text() == "unchanged",
                       f"{linker} did not fail safely for {args}")
            target = second / "libanswer.a"
            original = target.read_bytes()
            result = command([DRIVER, "-c", main, "-lanswer", "-o", target], env=env, check=False)
            expect(result.returncode != 0 and "also an input" in result.stderr and
                   target.read_bytes() == original, "library output collision was not rejected")
            for args in (["-E", main, "-lanswer"], ["-S", main, "-L", cli],
                         ["--archive", "-o", exe, "-lanswer"], ["--static", main, "-l:libanswer.so"],
                         [main, "-l", ""], [main, "-L"], [main, "-l"]):
                result = command([DRIVER, *args], env=env, check=False)
                expect(result.returncode != 0 and result.stderr, f"invalid options were accepted: {args}")
        for value in ("", ":/tmp", "/tmp:", "/tmp::/var"):
            conf.write_text(f"library_path = {value}\n")
            for tool, args in ((DRIVER, [main]), (PP, [main])):
                result = command([tool, *args], env=env, check=False)
                expect(result.returncode != 0 and "empty directory in library_path" in result.stderr,
                       f"{tool} accepted an invalid library path")


def linker_archive_order_case():
    """Compare archive ordering, rescanning, and groups with GNU ld.

    Returns:
        None; raises AssertionError for incorrect extraction or execution.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-archive-order-") as directory:
        td = pathlib.Path(directory)
        sources = {
            "start": ".text\n.globl _start\n_start:\ncall alpha\nmov %eax,%edi\nmov $60,%eax\nsyscall\n",
            "alpha": ".text\n.globl alpha\nalpha:\ncall beta\nret\n",
            "beta": ".text\n.globl beta\nbeta:\ncall gamma\nret\n",
            "gamma": ".text\n.globl gamma\ngamma:\nmov $42,%eax\nret\n",
            "unused": ".text\n.globl unused\nunused:\nret\n",
        }
        objects = {}
        for name, text in sources.items():
            source, obj = td / f"{name}.s", td / f"{name}.o"
            source.write_text(text)
            command(["as", "-o", obj, source])
            objects[name] = obj
        first, second, whole = td / "first.a", td / "second.a", td / "whole.a"
        command(["ar", "rcs", first, objects["gamma"], objects["alpha"], objects["unused"]])
        command(["ar", "rcs", second, objects["beta"]])
        command(["ar", "rcs", whole, objects["gamma"], objects["beta"], objects["alpha"]])
        start, exe, partial = objects["start"], td / "program", td / "combined.o"
        for linker in (["ld"], [BUILD / "crunch-ld", "-nostdlib"]):
            for inputs in ([start, whole], [start, first, second, first],
                           [start, "--start-group", first, second, "--end-group"],
                           ["--start-group", whole, start, "--end-group"],
                           [start, f"-L{td}", "-l:first.a", "-l:second.a", "-l:first.a"],
                           [start, "-(", first, "-(", second, "-)", "-)"]):
                command([*linker, "-o", exe, *inputs])
                expect(command([exe], check=False).returncode == 42,
                       f"{linker} failed archive rescan: {inputs}")
                command([*linker, "-r", "-o", partial, *inputs])
                symbols = command(["nm", partial]).stdout
                expect(" T alpha" in symbols and " T beta" in symbols and
                       " T gamma" in symbols and " unused" not in symbols,
                       f"{linker} selected incorrect partial-link members: {inputs}")
                command(["ld", "-o", exe, partial])
                expect(command([exe], check=False).returncode == 42,
                       f"{linker} produced an unusable partial link")
            for inputs, unresolved in (([whole, start], "alpha"),
                                       ([start, first, second], "gamma")):
                result = command([*linker, "-o", exe, *inputs], check=False)
                expect(result.returncode != 0 and unresolved in result.stderr,
                       f"{linker} resolved an earlier archive: {inputs}")
                command([*linker, "-r", "-o", partial, *inputs])
                symbols = command(["nm", partial]).stdout
                expect(f" U {unresolved}" in symbols and f" T {unresolved}" not in symbols,
                       f"{linker} incorrectly resolved {unresolved} in partial output")
            result = command([*linker, "--require-defined=gamma", "-r", "-o", partial, whole],
                             check=False)
            expect(result.returncode == 0 and " T gamma" in command(["nm", partial]).stdout,
                   f"{linker} did not use a required symbol to extract an archive member")
        for args in (["--end-group", start], ["--start-group", start]):
            result = command([BUILD / "crunch-ld", "-nostdlib", *args], check=False)
            expect(result.returncode != 0 and "group" in result.stderr,
                   "malformed archive group was accepted")


def linker_archive_common_case():
    """Compare common-symbol archive extraction and precedence with GNU ld.

    Returns:
        None; raises AssertionError for incorrect extraction or linked results.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-archive-common-") as directory:
        td = pathlib.Path(directory)
        sources = {
            "common_start": ".comm shared,8,8\n.text\n.globl _start\n_start:\n"
                            "mov shared(%rip),%edi\nmov $60,%eax\nsyscall\n",
            "undefined_start": ".text\n.globl _start\n_start:\n"
                               "mov shared(%rip),%edi\nmov $60,%eax\nsyscall\n",
            "weak_ref": ".weak shared\n.data\n.globl ref\nref: .quad shared\n",
            "strong": ".data\n.balign 8\n.globl shared,strong_marker\n.type shared,@object\n"
                      "shared: .quad 42\nstrong_marker: .quad 0\n",
            "notype": ".data\n.balign 8\n.globl shared,notype_marker\n"
                      "shared: .quad 23\nnotype_marker: .quad 0\n",
            "other": ".data\n.balign 8\n.globl shared,other_marker\n.type shared,@object\n"
                     "shared: .quad 17\nother_marker: .quad 0\n",
            "weak": ".data\n.balign 8\n.weak shared\n.globl weak_marker\n.type shared,@object\n"
                    "shared: .quad 7\nweak_marker: .quad 0\n",
            "common": ".comm shared,32,16\n.data\n.globl common_marker\ncommon_marker: .quad 0\n",
            "function": ".text\n.globl shared,function_marker\n.type shared,@function\n"
                        "shared: ret\nfunction_marker: ret\n",
        }
        objects = {}
        for name, text in sources.items():
            source, obj = td / f"{name}.s", td / f"{name}.o"
            source.write_text(text)
            command(["as", "-o", obj, source])
            objects[name] = obj
        cases = (
            ("strong", ["strong"], 42, {"strong_marker"}, "D"),
            ("notype", ["notype"], 23, {"notype_marker"}, "D"),
            ("weak", ["weak"], 0, set(), "C"),
            ("common", ["common"], 0, set(), "C"),
            ("function", ["function"], 0, set(), "C"),
            ("precedence", ["weak", "common", "strong", "other"], 42, {"strong_marker"}, "D"),
            ("first-definition", ["other", "strong"], 17, {"other_marker"}, "D"),
        )
        all_markers = {"strong_marker", "notype_marker", "other_marker", "weak_marker",
                       "common_marker", "function_marker"}
        exe, partial = td / "program", td / "combined.o"
        for linker in (["ld"], [BUILD / "crunch-ld", "-nostdlib"]):
            for name, members, exit_code, markers, symbol_type in cases:
                archive = td / f"{name}.a"
                if not archive.exists():
                    command(["ar", "rcs", archive, *(objects[member] for member in members)])
                for inputs, expected_exit, expected_markers, expected_type in (
                    ([objects["common_start"], archive], exit_code, markers, symbol_type),
                    ([archive, objects["common_start"]], 0, set(), "C"),
                ):
                    command([*linker, "-o", exe, *inputs])
                    expect(command([exe], check=False).returncode == expected_exit,
                           f"{linker} produced wrong common-symbol value for {name}: {inputs}")
                    command([*linker, "-r", "-o", partial, *inputs])
                    symbols = command(["nm", partial]).stdout
                    expect(f" {expected_type} shared" in symbols and
                           {marker for marker in all_markers if marker in symbols} == expected_markers,
                           f"{linker} selected incorrect common-symbol members for {name}: {symbols}")
                    command(["ld", "-o", exe, partial])
                    expect(command([exe], check=False).returncode == expected_exit,
                           f"{linker} partial link lost the common-symbol value for {name}")
            archive = td / "common-then-strong.a"
            if not archive.exists():
                command(["ar", "rcs", archive, objects["common"], objects["strong"]])
            command([*linker, "-r", "-o", partial, objects["undefined_start"], archive])
            symbols = command(["nm", partial]).stdout
            expect(" D shared" in symbols and "common_marker" in symbols and "strong_marker" in symbols,
                   f"{linker} did not replace an extracted common symbol: {symbols}")
            command(["ld", "-o", exe, partial])
            expect(command([exe], check=False).returncode == 42,
                   f"{linker} partial link did not preserve the strong definition")
            command([*linker, "-r", "-o", partial, objects["weak_ref"], td / "strong.a"])
            symbols = command(["nm", partial]).stdout
            expect(" w shared" in symbols and "strong_marker" not in symbols,
                   f"{linker} extracted a member for a weak reference: {symbols}")


def native_got_linker_case():
    """Compare native and GNU static GOT links, including partial links and GC.

    Returns:
        None; raises AssertionError for incorrect GOT relocation behavior.
    """
    linker = BUILD / "crunch-ld"
    with tempfile.TemporaryDirectory(prefix="crunch-got-") as directory:
        td = pathlib.Path(directory)
        main, defs, obj, defs_obj, exe = (td / name for name in
                                          ("main.s", "defs.s", "main.o", "defs.o", "program"))
        main.write_text(".text\n.globl _start\n_start:\n"
                        "mov shared@GOTPCREL(%rip),%rax\n"
                        "mov shared@GOTPCREL(%rip),%ecx\n"
                        "cmp %eax,%ecx\njne 1f\nmov (%rax),%edi\n"
                        "call *add@GOTPCREL(%rip)\nmov %eax,%edi\n"
                        "mov $60,%eax\nsyscall\n1: mov $1,%edi\nmov $60,%eax\nsyscall\n"
                        '.section .note.GNU-stack,"",@progbits\n')
        defs.write_text(".text\n.globl add\nadd: lea 2(%rdi),%eax\nret\n"
                        ".data\n.globl shared\nshared: .long 40\n"
                        '.section .note.GNU-stack,"",@progbits\n')
        command(["as", "-o", defs_obj, defs])
        for relaxation in ("yes", "no"):
            command(["as", f"-mrelax-relocations={relaxation}", "-o", obj, main])
            relocs = command(["readelf", "-rW", obj]).stdout
            names = ("R_X86_64_GOTPCRELX", "R_X86_64_REX_GOTPCRELX") if relaxation == "yes" else (
                "R_X86_64_GOTPCREL",)
            expect(all(name in relocs for name in names), "assembler did not emit the expected GOT variants")
            for command_link in (["ld"], [linker, "-nostdlib"]):
                command([*command_link, "-o", exe, obj, defs_obj])
                expect(command([exe], check=False).returncode == 42,
                       f"{command_link[0]} failed GOT relocations with relaxation {relaxation}")
            sections = command(["readelf", "-SW", exe]).stdout
            expect(re.search(r"\.got\s+PROGBITS\s+\S+\s+\S+\s+000010\b", sections),
                   "repeated references did not share a GOT entry")

        pic = td / "pic.c"
        pic.write_text("__attribute__((weak)) extern int missing;\n"
                       "extern int shared; extern int add(int); extern int other(void);\n"
                       "int calculate(void) { return &missing || other() != shared ? 1 : add(shared); }\n")
        pic_obj, other_obj, archive, partial = (td / name for name in
                                                ("pic.o", "other.o", "libdefs.a", "partial.o"))
        command(["cc", "-fPIC", "-fno-plt", "-O1", "-c", pic, "-o", pic_obj])
        other = td / "other.c"
        other.write_text("extern int shared; int other(void) { return shared; }\n")
        command(["cc", "-fPIC", "-fno-plt", "-O1", "-c", other, "-o", other_obj])
        main.write_text(".text\n.globl _start\n_start: call calculate\n"
                        "mov %eax,%edi\nmov $60,%eax\nsyscall\n"
                        '.section .note.GNU-stack,"",@progbits\n')
        command(["as", "-o", obj, main])
        command(["ar", "rcs", archive, defs_obj])
        for partial_linker in (None, ["ld"], [linker, "-nostdlib"]):
            inputs = [obj, pic_obj, other_obj]
            if partial_linker:
                command([*partial_linker, "-r", "-o", partial, *inputs])
                inputs = [partial]
            for final_linker in (["ld"], [linker, "-nostdlib"]):
                command([*final_linker, "-o", exe, *inputs, archive])
                expect(command([exe], check=False).returncode == 42,
                       f"PIC archive link failed with partial={partial_linker} final={final_linker}")
            sections = command(["readelf", "-SW", exe]).stdout
            expect(re.search(r"\.got\s+PROGBITS\s+\S+\s+\S+\s+000020\b", sections),
                   "cross-object global GOT entries were not deduplicated")
        conf = td / "crunch.conf"
        conf.write_text("linker = crunch\n")
        env = dict(os.environ, CRUNCH_CONF_FILE=str(conf))
        command([DRIVER, "--static", main, pic_obj, other_obj, defs_obj, "-o", exe], env=env)
        expect(command([exe], check=False).returncode == 42,
               "driver could not link cross-object PIC inputs with crunch-ld")
        command([DRIVER, "-c", pic_obj, other_obj, "-o", partial], env=env)
        command([DRIVER, "--static", main, partial, defs_obj, "-o", exe], env=env)
        expect(command([exe], check=False).returncode == 42,
               "driver could not link partially linked PIC inputs with crunch-ld")
        weak = td / "weak.s"
        weak.write_text(".data\n.globl missing\nmissing: .long 1\n")
        weak_obj = td / "weak.o"
        command(["as", "-o", weak_obj, weak])
        command(["ar", "rcs", archive, weak_obj])
        for final_linker in (["ld"], [linker, "-nostdlib"]):
            command([*final_linker, "-o", exe, obj, pic_obj, other_obj, archive])
            expect(command([exe], check=False).returncode == 42,
                   f"weak GOT reference unexpectedly extracted an archive member with {final_linker}")
        for final_linker in (["ld"], [linker, "-nostdlib"]):
            command([*final_linker, "-o", exe, obj, pic_obj, other_obj, weak_obj, archive])
            expect(command([exe], check=False).returncode == 1,
                   f"defined weak reference was not resolved by {final_linker}")

        local_objects = []
        for index, value in enumerate((20, 22)):
            local = td / f"local{index}.s"
            local.write_text(f'.section .text.f{index},"ax",@progbits\n.globl f{index}\n'
                             f'f{index}: mov value@GOTPCREL(%rip),%rax\nmov (%rax),%eax\nret\n'
                             f'.section .data.f{index},"aw",@progbits\nvalue: .long {value}\n'
                             '.section .text.unused,"ax",@progbits\n'
                             'mov absent@GOTPCREL(%rip),%rax\nret\n')
            local_obj = td / f"local{index}.o"
            command(["as", "-o", local_obj, local])
            local_objects.append(local_obj)
        main.write_text(".text\n.globl _start\n_start: call f0\npush %rax\n"
                        "call f1\npop %rdi\nadd %eax,%edi\nmov $60,%eax\nsyscall\n")
        command(["as", "-o", obj, main])
        for partial_linker in (None, [linker, "-nostdlib"]):
            inputs = [obj, *local_objects]
            if partial_linker:
                command([*partial_linker, "-r", "-o", partial, *inputs])
                inputs = [partial]
            for final_linker in (["ld"], [linker, "-nostdlib"]):
                command([*final_linker, "--gc-sections", "-o", exe, *inputs])
                expect(command([exe], check=False).returncode == 42,
                       f"local GOT entries or GC failed with {final_linker}")
            sections = command(["readelf", "-SW", exe]).stdout
            expect(re.search(r"\.got\s+PROGBITS\s+\S+\s+\S+\s+000010\b", sections),
                   "local symbols shared an entry or discarded sections allocated GOT entries")

        main.write_text(".text\n.globl _start\n_start:\n"
                        "mov shared@GOTPCREL+0x80000000(%rip),%rax\nret\n")
        command(["as", "-o", obj, main])
        exe.write_text("unchanged")
        result = command([linker, "-nostdlib", "-o", exe, obj, defs_obj], check=False)
        expect(result.returncode != 0 and "GOTPCREL relocation out of range" in result.stderr
               and exe.read_text() == "unchanged", "out-of-range GOT relocation did not fail safely")
        main.write_text(".text\n.globl _start\n_start:\nmov shared@GOTPCREL(%rip),%rax\nret\n")
        command(["as", "-o", obj, main])
        command([linker, "-nostdlib", "-o", exe, obj, defs_obj])
        sections = command(["readelf", "-SW", exe]).stdout
        got_address = int(re.search(r"\.got\s+PROGBITS\s+(\S+)", sections).group(1), 16)
        symbols = command(["nm", exe]).stdout
        start_address = int(re.search(r"^([0-9a-f]+)\s+\S\s+_start$", symbols, re.MULTILINE).group(1), 16)
        place = start_address + 3
        for displacement, valid in ((2**31 - 1, True), (-(2**31), True),
                                    (2**31, False), (-(2**31) - 1, False)):
            addend = displacement - got_address + place + 4
            expression = f"+{addend}" if addend >= 0 else str(addend)
            main.write_text(".text\n.globl _start\n_start:\n"
                            f"mov shared@GOTPCREL{expression}(%rip),%rax\nret\n")
            command(["as", "-o", obj, main])
            result = command([linker, "-nostdlib", "-o", exe, obj, defs_obj], check=False)
            expect((result.returncode == 0) == valid and
                   (valid or "GOTPCREL relocation out of range" in result.stderr),
                   f"GOT displacement boundary {displacement} was handled incorrectly")
        main.write_text(".text\n.globl _start\n_start:\nmov shared@GOTPCREL(%rip),%rax\nret\n")
        command(["as", "-o", obj, main])
        exe.write_text("unchanged")
        for options in (["-pie"],):
            result = command([linker, "-nostdlib", *options, "-o", exe, obj, defs_obj], check=False)
            expect(result.returncode != 0 and "GOT relocations in PIE" in result.stderr
                   and exe.read_text() == "unchanged", "unsupported GOT output mode did not fail safely")
        result = command([linker, "-nostdlib", "-o", exe, obj], check=False)
        expect(result.returncode != 0 and "undefined reference" in result.stderr
               and exe.read_text() == "unchanged", "undefined GOT symbol did not fail safely")


def relocatable_linker_case():
    """Check native partial links, symbol resolution, relocations, and rejection.

    Returns:
        None; raises AssertionError for incorrect relocatable output or behavior.
    """
    linker = BUILD / "crunch-ld"
    with tempfile.TemporaryDirectory(prefix="crunch-native-reloc-") as directory:
        td = pathlib.Path(directory)
        conf = td / "crunch.conf"
        conf.write_text("assembler = crunch\nlinker = crunch\n")
        env = dict(os.environ, CRUNCH_CONF_FILE=str(conf))
        main, module = td / "main.bc", td / "module.bc"
        main.write_text('int calculate(int x); int printf(const char* format); int main() { printf("ok"); return calculate(40); }\n')
        module.write_text("int values[] = {1, 2}; int calculate(int x) { return x + values[1]; }\n")
        partial, combined, exe = td / "partial.o", td / "combined.o", td / "program"
        command([DRIVER, "-c", main, "-o", partial], env=env)
        command([DRIVER, "-c", partial, module, "-o", combined], env=env)
        for final in ("crunch", "gnu"):
            if final == "crunch":
                command([DRIVER, combined, "-o", exe], env=env)
            else:
                command(["ld", "-o", exe, combined, LIBCRUNCH])
            result = command([exe], check=False)
            expect(result.returncode == 42 and result.stdout == "ok",
                   f"{final} failed to execute a chained native partial link")

        start, helper = td / "start.s", td / "helper.s"
        start.write_text(".text\n.globl _start\n_start:\ncall value\n"
                         "mov %eax,%edi\nmov $60,%eax\nsyscall\n"
                         ".weak missing_weak\n.data\n.quad missing_weak\n"
                         ".comm common_value,8,16\n")
        helper.write_text(".text\n.globl value\nvalue:\nmov $42,%eax\nret\n"
                          ".comm common_value,16,32\n")
        start_obj, helper_obj, archive = td / "start.o", td / "helper.o", td / "libhelper.a"
        command(["as", "-o", start_obj, start])
        command(["as", "-o", helper_obj, helper])
        command(["ar", "rcs", archive, helper_obj])
        command([linker, "-r", "-o", partial, start_obj, archive])
        symbols = command(["readelf", "-sW", partial]).stdout
        expect(re.search(r"\bWEAK\s+DEFAULT\s+UND\s+missing_weak\b", symbols) and
               re.search(r"\b16\s+OBJECT\s+GLOBAL\s+DEFAULT\s+COM\s+common_value\b", symbols),
               "partial link lost weak or common symbol semantics")
        command(["ld", "-o", exe, partial])
        expect(command([exe], check=False).returncode == 42,
               "partial link did not extract the required archive member")

        weak = td / "weak.s"
        weak.write_text(".text\n.weak value\nvalue: mov $3,%eax\nret\n")
        weak_obj = td / "weak.o"
        command(["as", "-o", weak_obj, weak])
        for inputs in ((start_obj, weak_obj, helper_obj), (start_obj, helper_obj, weak_obj)):
            command([linker, "-r", "-o", partial, *inputs])
            command(["ld", "-o", exe, partial])
            expect(command([exe], check=False).returncode == 42,
                   "partial link selected a weak definition over a strong one")

        weak.write_text(".data\n.weak common_value\ncommon_value: .quad 99\n")
        command(["as", "-o", weak_obj, weak])
        for inputs in ((weak_obj, helper_obj), (helper_obj, weak_obj)):
            command([linker, "-r", "-o", partial, *inputs])
            symbols = command(["readelf", "-sW", partial]).stdout
            expect(re.search(r"\b16\s+OBJECT\s+GLOBAL\s+DEFAULT\s+COM\s+common_value\b", symbols),
                   "partial link selected a weak definition over a common symbol")

        c_source, c_obj = td / "debug.c", td / "debug.o"
        c_source.write_text("int value(void) { return 42; }\n")
        command(["cc", "-g", "-fno-pic", "-ffunction-sections", "-c", c_source, "-o", c_obj])
        command([linker, "-r", "-o", partial, start_obj, c_obj])
        expect(".debug_info" in command(["readelf", "-SW", partial]).stdout,
               "partial link discarded debug sections")
        command(["ld", "-o", exe, partial])
        expect(command([exe], check=False).returncode == 42,
               "GNU ld could not link native partial output containing debug sections")

        got = td / "got.s"
        got.write_text(".text\n.globl _start\n_start:\nmov value@GOTPCREL(%rip),%rax\n"
                       "mov (%rax),%edi\nmov $60,%eax\nsyscall\n"
                       ".data\n.globl value\nvalue: .long 42\n")
        command(["as", "-o", start_obj, got])
        command([linker, "--relocatable", "-o", partial, start_obj])
        expect("GOTPCREL" in command(["readelf", "-rW", partial]).stdout,
               "partial link did not preserve the GOT relocation")
        command(["ld", "-o", exe, partial])
        expect(command([exe], check=False).returncode == 42,
               "GNU ld could not resolve the preserved GOT relocation")

        partial.write_text("unchanged")
        result = command([linker, "-r", "-s", "-o", partial, helper_obj], check=False)
        expect(result.returncode != 0 and "not supported with relocatable linking" in result.stderr
               and partial.read_text() == "unchanged", "unsupported -r option did not fail safely")


def native_comdat_linker_case():
    """Check COMDAT selection, group metadata, unwind data, and discarded references.

    Returns:
        None; raises AssertionError for incorrect group linking behavior.
    """
    linker = BUILD / "crunch-ld"
    with tempfile.TemporaryDirectory(prefix="crunch-native-comdat-") as directory:
        td = pathlib.Path(directory)
        objects = []
        for value in (11, 22):
            source, obj = td / f"group{value}.s", td / f"group{value}.o"
            source.write_text(
                '.section .text.pick,"axG",@progbits,pick,comdat\n'
                ".globl pick\n.type pick,@function\npick: .cfi_startproc\n"
                f"mov ${value},%eax\nret\n.cfi_endproc\n"
                '.section .data.pick,"awG",@progbits,pick,comdat\n'
                ".globl retained_data\nretained_data: .quad ext\n"
                f".text\n.globl keep{value}\nkeep{value}: .cfi_startproc\nret\n.cfi_endproc\n")
            command(["as", "-o", obj, source])
            objects.append(obj)
        start, start_obj = td / "start.s", td / "start.o"
        start.write_text(".text\n.globl _start\n_start: call pick\nmov %eax,%edi\n"
                         "mov $60,%eax\nsyscall\n.data\n.globl ext\next: .quad 1\n")
        command(["as", "-o", start_obj, start])
        partial, chained, exe = td / "partial.o", td / "chained.o", td / "program"
        for inputs, expected in ((objects, 11), (objects[::-1], 22)):
            command([linker, "-r", "-o", partial, *inputs])
            groups = command(["readelf", "-gW", partial]).stdout
            expect(groups.count("COMDAT group section") == 1 and
                   ".text.pick" in groups and ".data.pick" in groups and
                   ".rela.data.pick" in groups, "COMDAT group metadata was not preserved")
            frames = command(["readelf", "-wf", partial]).stdout
            expect(re.findall(r"FDE cie=([0-9a-f]+)", frames) == ["00000000"] * 3,
                   "discarded FDEs or surviving CIE references were mishandled")
            for partial_linker in ([linker, "-r"], ["ld", "-r"]):
                command([*partial_linker, "-o", chained, partial])
                for final in ([linker, "-nostdlib"], ["ld"]):
                    command([*final, "-o", exe, start_obj, chained])
                    expect(command([exe], check=False).returncode == expected,
                           "COMDAT selection changed during a chained link")
            for options in ([], ["--gc-sections"]):
                command([linker, "-nostdlib", *options, "-o", exe, start_obj, *inputs])
                expect(command([exe], check=False).returncode == expected,
                       "direct link selected the wrong COMDAT definition")
                if options:
                    expect("retained_data" in command(["readelf", "-sW", exe]).stdout,
                           "garbage collection split a retained section group")
        conf = td / "crunch.conf"
        conf.write_text("linker = crunch\n")
        env = dict(os.environ, CRUNCH_CONF_FILE=str(conf))
        command([DRIVER, "-c", *objects, "-o", partial], env=env)
        expect(command(["readelf", "-gW", partial]).stdout.count("COMDAT group section") == 1,
               "driver did not preserve the COMDAT group")

        for kind, flags, expected in (("local", ",comdat", 1), ("plain", "", 2)):
            members = []
            for index in (1, 2):
                source, obj = td / f"{kind}{index}.s", td / f"{kind}{index}.o"
                source.write_text(f'.section .text.{kind},"axG",@progbits,local_signature{flags}\n'
                                  f".byte {index}\n")
                command(["as", "-o", obj, source])
                members.append(obj)
            command([linker, "-r", "-o", partial, *members])
            groups = command(["readelf", "-gW", partial]).stdout
            expect(groups.count("group section") == expected,
                   f"{kind} signature or non-COMDAT group selection failed")
            command(["ld", "-r", "-o", chained, partial])

        refs, refs_obj = td / "refs.s", td / "refs.o"
        refs.write_text('.section .text.other,"axG",@progbits,pick,comdat\n'
                        ".Ldiscarded: ret\n.globl only_discarded\nonly_discarded: ret\n"
                        ".text\n.globl use_discarded\nuse_discarded: call only_discarded\nret\n"
                        '.section .debug_test,"",@progbits\n.quad .Ldiscarded\n')
        command(["as", "-o", refs_obj, refs])
        command([linker, "-r", "-o", partial, objects[0], refs_obj])
        expect("R_X86_64_NONE" in command(["readelf", "-rW", partial]).stdout and
               re.search(r"\bGLOBAL\s+DEFAULT\s+UND\s+only_discarded\b",
                         command(["readelf", "-sW", partial]).stdout),
               "discarded local debug or global reference was not preserved safely")
        extra, extra_obj, archive = td / "extra.s", td / "extra.o", td / "extra.a"
        extra.write_text(".text\n.globl only_discarded\nonly_discarded: ret\n")
        command(["as", "-o", extra_obj, extra])
        command(["ar", "rcs", archive, extra_obj])
        command([linker, "-r", "-o", partial, objects[0], refs_obj, archive])
        expect(not re.search(r"\bUND\s+only_discarded\b",
                             command(["readelf", "-sW", partial]).stdout),
               "reference to discarded global did not extract archive member")
        refs.write_text(refs.read_text().replace('.section .debug_test,"",@progbits',
                                                  '.section .other,"",@progbits'))
        command(["as", "-o", refs_obj, refs])
        partial.write_text("unchanged")
        result = command([linker, "-r", "-o", partial, objects[0], refs_obj], check=False)
        expect(result.returncode != 0 and "discarded section" in result.stderr and
               partial.read_text() == "unchanged", "live reference to discarded local was accepted")

        malformed = bytearray(objects[0].read_bytes())
        shoff = struct.unpack_from("<Q", malformed, 40)[0]
        shentsize, shnum = struct.unpack_from("<HH", malformed, 58)
        for index in range(shnum):
            header = shoff + index * shentsize
            if struct.unpack_from("<I", malformed, header + 4)[0] == 17:
                struct.pack_into("<Q", malformed, header + 56, 8)
                break
        else:
            raise AssertionError("fixture has no section group")
        bad = td / "malformed.o"
        bad.write_bytes(malformed)
        for args, kwargs in (([linker, "-r", "-o", partial, bad], {}),
                             ([DRIVER, "-c", bad, "-o", partial], {"env": env})):
            result = command(args, check=False, **kwargs)
            expect(result.returncode != 0 and "group" in result.stderr and
                   partial.read_text() == "unchanged", "malformed group did not fail safely")

        malformed = bytearray(objects[1].read_bytes())
        shoff = struct.unpack_from("<Q", malformed, 40)[0]
        shentsize, shnum, shstrndx = struct.unpack_from("<HHH", malformed, 58)
        names_offset = struct.unpack_from("<Q", malformed, shoff + shstrndx * shentsize + 24)[0]
        for index in range(shnum):
            header = shoff + index * shentsize
            name_offset = names_offset + struct.unpack_from("<I", malformed, header)[0]
            if malformed[name_offset:name_offset + 10] == b".eh_frame\0":
                frame_offset = struct.unpack_from("<Q", malformed, header + 24)[0]
                struct.pack_into("<I", malformed, frame_offset, 0xffffffff)
                break
        else:
            raise AssertionError("fixture has no unwind section")
        bad.write_bytes(malformed)
        result = command([linker, "-r", "-o", partial, objects[0], bad], check=False)
        expect(result.returncode != 0 and ".eh_frame" in result.stderr and
               partial.read_text() == "unchanged", "unsupported frame format did not fail safely")
        malformed = bytearray(objects[1].read_bytes())
        frame_size = 0
        relocation_offset = None
        for index in range(shnum):
            header = shoff + index * shentsize
            name_offset = names_offset + struct.unpack_from("<I", malformed, header)[0]
            if malformed[name_offset:name_offset + 10] == b".eh_frame\0":
                frame_size = struct.unpack_from("<Q", malformed, header + 32)[0]
            if malformed[name_offset:name_offset + 15] == b".rela.eh_frame\0":
                relocation_offset = struct.unpack_from("<Q", malformed, header + 24)[0]
        expect(frame_size > 0 and relocation_offset is not None, "missing frame relocation fixture")
        struct.pack_into("<Q", malformed, relocation_offset + 24, frame_size - 1)
        bad.write_bytes(malformed)
        result = command([linker, "-r", "-o", partial, objects[0], bad], check=False)
        expect(result.returncode != 0 and ".eh_frame relocation" in result.stderr and
               partial.read_text() == "unchanged", "cross-record frame relocation was accepted")


def native_comdat_assembler_case():
    """Check native COMDAT assembly across GNU and Crunch linker combinations.

    Returns:
        None; raises AssertionError for incorrect native toolchain behavior.
    """
    assembler, linker = BUILD / "crunch-as", BUILD / "crunch-ld"
    with tempfile.TemporaryDirectory(prefix="crunch-as-comdat-") as directory:
        td = pathlib.Path(directory)
        conf = td / "crunch.conf"
        conf.write_text("assembler = crunch\nlinker = crunch\n")
        env = dict(os.environ, CRUNCH_CONF_FILE=str(conf))
        sources, objects = [], {}
        for value in (11, 22):
            source = td / f"pick{value}.s"
            source.write_text('.section .text.pick,"axG",@progbits,pick,comdat\n'
                              ".globl pick\npick:\n"
                              f"mov ${value},%eax\nret\n"
                              '.section .data.pick,"awG",@progbits,pick,comdat\n'
                              ".globl retained_data\nretained_data: .quad ext\n")
            sources.append(source)
            for tool, label in ((assembler, "native"), ("as", "gnu")):
                obj = td / f"{label}{value}.o"
                command([tool, "-o", obj, source])
                objects[label, value] = obj
        start, start_obj = td / "start.s", td / "start.o"
        start.write_text(".text\n.globl _start\n_start: call pick\nmov %eax,%edi\n"
                         "mov $60,%eax\nsyscall\n.data\n.globl ext\next: .quad 1\n")
        command([assembler, "-o", start_obj, start])
        partial, exe = td / "partial.o", td / "program"
        for first, second in ((11, 22), (22, 11)):
            for left, right in (("native", "native"), ("native", "gnu"), ("gnu", "native")):
                inputs = (objects[left, first], objects[right, second])
                for partial_linker in ([linker, "-r"], ["ld", "-r"]):
                    command([*partial_linker, "-o", partial, *inputs])
                    groups = command(["readelf", "-gW", partial]).stdout
                    expect(groups.count("COMDAT group section") == 1 and
                           ".rela.data.pick" in groups, "partial link lost native group metadata")
                    for final in ([linker, "-nostdlib"], ["ld"]):
                        command([*final, "-o", exe, start_obj, partial])
                        expect(command([exe], check=False).returncode == first,
                               "mixed native/GNU group link selected the wrong definition")
            command([linker, "-nostdlib", "--gc-sections", "-o", exe, start_obj,
                     objects["native", first], objects["native", second]])
            expect(command([exe], check=False).returncode == first and
                   "retained_data" in command(["readelf", "-sW", exe]).stdout,
                   "native garbage collection split an assembled section group")
        command([DRIVER, "-c", *sources, "-o", partial], env=env)
        main = td / "main.bc"
        main.write_text("int ext = 1; int pick(); int main() { return pick(); }\n")
        command([DRIVER, main, partial, "-o", exe], env=env)
        expect(command([exe], check=False).returncode == 11,
               "configured native assembler and linker did not preserve COMDAT selection")
        plain_objects = []
        for value in (1, 2):
            source, obj = td / f"plain{value}.s", td / f"plain{value}.o"
            source.write_text('.section .plain.group,"aG",@progbits,plain_sig\n'
                              f".byte {value}\n")
            command([assembler, "-o", obj, source])
            plain_objects.append(obj)
        for partial_linker in ([linker, "-r"], ["ld", "-r"]):
            command([*partial_linker, "-o", partial, *plain_objects])
            expect(command(["readelf", "-gW", partial]).stdout.count("group section") == 2,
                   "non-COMDAT native groups were incorrectly deduplicated")


def preprocessor_case():
    """Exercise configured include paths, guards, pipe input, and error handling.

    Returns:
        None; raises AssertionError for incorrect preprocessing or diagnostics.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-preprocessor-") as td:
        directory = pathlib.Path(td)
        first_include = directory / "include-first"
        second_include = directory / "include-second"
        first_include.mkdir()
        second_include.mkdir()
        (first_include / "priority.h").write_text("int from_first_path;\n")
        (second_include / "priority.h").write_text("int from_second_path;\n")
        (second_include / "later.h").write_text("int from_later_path;\n")
        source = directory / "source.bc"
        expanded_source = directory / "expanded.bc"

        source.write_text(
            "#include <priority.h>\n"
            "#include <later.h>\n"
            "#include <stdlib.h>\n"
        )
        include_env = os.environ.copy()
        include_env["CRUNCH_INCLUDE_PATH"] = f"{first_include}:{second_include}"
        search_result = command([PP, source], cwd=BUILD, env=include_env)
        expect("int from_first_path;" in search_result.stdout and
               "int from_second_path;" not in search_result.stdout and
               "int from_later_path;" in search_result.stdout and
               "void noreturn exit(int status);" in search_result.stdout,
               "CRUNCH_INCLUDE_PATH order, multiple directories, or configured fallback failed")
        dash_i = command([PP, "-I", second_include, source], cwd=BUILD, env=include_env).stdout
        expect("int from_second_path;" in dash_i and "int from_first_path;" not in dash_i,
               "crunch-pp -I did not take precedence over CRUNCH_INCLUDE_PATH")
        dash_i_joined = command([PP, f"-I{second_include}", "-"], input=source.read_text(),
                                cwd=BUILD, env=include_env).stdout
        expect("int from_second_path;" in dash_i_joined,
               "crunch-pp -Idir with stdin input failed")
        bad_option = command([PP, "-I"], check=False)
        expect(bad_option.returncode == 2 and "usage: crunch-pp" in bad_option.stderr,
               "crunch-pp accepted -I without a directory")

        conf_one, conf_two = directory / "conf-one", directory / "conf-two"
        conf_one.mkdir()
        conf_two.mkdir()
        (conf_one / "confonly.h").write_text("int from_conf_one;\n")
        (conf_two / "confonly2.h").write_text("int from_conf_two;\n")
        (conf_one / "stdlib.h").write_text("int shadowed_builtin;\n")
        (first_include / "envwins.h").write_text("int env_version;\n")
        (conf_one / "envwins.h").write_text("int conf_version;\n")
        conf_file = directory / "crunch.conf"
        conf_file.write_text(
            "# comment\n\n"
            f"  include_path   =\t{conf_one}  \n"
            f"include_path=  {conf_two}\n"
        )
        conf_env = os.environ.copy()
        conf_env.pop("CRUNCH_INCLUDE_PATH", None)
        conf_env["CRUNCH_CONF_FILE"] = str(conf_file)
        source.write_text(
            "#include <confonly.h>\n#include <confonly2.h>\n#include <stdlib.h>\n")
        conf_result = command([PP, source], env=conf_env)
        expect("int from_conf_one;" in conf_result.stdout and
               "int from_conf_two;" in conf_result.stdout and
               "void noreturn exit(int status);" in conf_result.stdout and
               "int shadowed_builtin;" not in conf_result.stdout,
               "configuration include_path was not searched after the built-in directory")
        conf_env["CRUNCH_INCLUDE_PATH"] = str(first_include)
        source.write_text("#include <envwins.h>\n")
        order_result = command([PP, source], env=conf_env)
        expect("int env_version;" in order_result.stdout and
               "int conf_version;" not in order_result.stdout,
               "CRUNCH_INCLUDE_PATH did not take precedence over the configuration file")
        conf_env.pop("CRUNCH_INCLUDE_PATH")
        source.write_text("#include <end.h>\n")
        conf_env["CRUNCH_CONF_FILE"] = str(directory / "absent.conf")
        expect(command([PP, source], env=conf_env, check=False).returncode != 0 and
               command([PP, "-"], input="int x;\n", env=conf_env).returncode == 0,
               "a missing configuration file was not silently ignored")
        for text, message in (("include_path /tmp\n", "expected 'key = value'"),
                              ("colour = red\n", "unknown key"),
                              ("include_path = /a::/b\n", "empty directory")):
            conf_file.write_text(text)
            conf_env["CRUNCH_CONF_FILE"] = str(conf_file)
            bad = command([PP, "-"], input="int x;\n", env=conf_env, check=False)
            expect(bad.returncode != 0 and message in bad.stderr and f"{conf_file}:1:" in bad.stderr,
                   f"invalid configuration {text!r} was not diagnosed: {bad.stderr}")

        source.write_text("#include <stdlib.h>\nint main() { exit(0); }\n")
        expanded = command([PP, source])
        expect("void noreturn exit(int status);" in expanded.stdout,
               "include contents were not inserted at the directive")

        piped = command([PP, "-"], input=source.read_text())
        expect("void noreturn exit(int status);" in piped.stdout and
               "int main() { exit(0); }" in piped.stdout and
               "CRUNCH-PP-MAP" in piped.stdout,
               "preprocessor stdin mode did not expand includes and emit source mapping")

        source.write_text("int main() { return 0; }")
        file_without_newline = command([PP, source]).stdout
        stdin_without_newline = command([PP, "-"], input=source.read_text()).stdout
        expect("int main() { return 0; }" in file_without_newline and
               "int main() { return 0; }" in stdin_without_newline,
               "preprocessor changed or inconsistently handled a missing final newline")

        source.write_text(
            "#include <test/outer.h>\n"
            "#include <test/guarded.h>\n"
            "#include <test/guarded_cycle_a.h>\n"
            "int main() { return guarded_value + guarded_cycle_value; }\n"
        )
        guarded_output = command([PP, source]).stdout
        expect(guarded_output.count("int guarded_value;") == 1,
               "nested and repeated guarded inclusion duplicated header contents")
        expect(guarded_output.count("int guarded_cycle_value;") == 1,
               "mutually guarded includes did not terminate exactly once")
        expanded_source.write_text(guarded_output)
        guarded_ir = command([IR, expanded_source])
        expect("global guarded_value int 0" in guarded_ir.stdout and
               "global guarded_cycle_value int 0" in guarded_ir.stdout,
               "nested/repeated guarded headers did not compile into declarations")

        source.write_text(
            "#define CRUNCH_TEST_PRESET\n"
            "#include <test/branch.h>\n"
            "#include <test/branch.h>\n"
        )
        branch_output = command([PP, source]).stdout
        expect(branch_output.count("int selected_branch;") == 2 and
               "int unexpected_branch;" not in branch_output,
               "#else conditional selection or non-guarded repeat inclusion failed")

        source.write_text("#include <test/cycle_a.h>\n")
        cycle = command([PP, source], check=False)
        expect(cycle.returncode != 0 and "cyclic include" in cycle.stderr,
               "unguarded include cycle was not rejected")

        source.write_text(
            "#include <test/location_error.h>\n"
            "int main() { return 0; }\n"
        )
        mapped = command([PP, source]).stdout
        expanded_source.write_text(mapped)
        diagnostic = command([IR, expanded_source], check=False)
        expected_header = str(ROOT / "include/test/location_error.h") + ":2:"
        expect(diagnostic.returncode != 0 and expected_header in diagnostic.stderr,
               f"diagnostic did not retain included-header file and line: {diagnostic.stderr}")

        source.write_text(
            "#include <test/guarded.h>\n"
            "int main() { return missing_from_root; }\n"
        )
        expanded_source.write_text(command([PP, source]).stdout)
        diagnostic = command([IR, expanded_source], check=False)
        expect(diagnostic.returncode != 0 and
               f"{source}:2:" in diagnostic.stderr,
               f"diagnostic after include did not restore root file and line: {diagnostic.stderr}")

        source.write_text("#include <missing-header.h>\n")
        missing = command([PP, source], check=False)
        expect(missing.returncode != 0 and "cannot open included header" in missing.stderr,
               "missing header did not produce a preprocessor diagnostic")

        source.write_text("#pragma unknown_directive\n")
        unsupported = command([PP, source], check=False)
        expect(unsupported.returncode != 0 and "unsupported preprocessor directive" in unsupported.stderr,
               "unsupported directive was not rejected")

        for label, data, line in (
            ("ordinary line", b'int main() { return 0; }\0\n', 1),
            ("directive", b'#macro VALUE 1\0junk\n', 1),
            ("inactive branch", b'#ifdef MISSING\n\0\n#endif\nint main() { return 0; }\n', 2),
        ):
            source.write_bytes(data)
            for args in ([PP, source], [DRIVER, "--emit-ir", source]):
                result = command(args, check=False)
                expect(result.returncode != 0 and f"{source}:{line}: raw NUL byte" in result.stderr,
                       f"{args[0]} accepted or misreported NUL in {label}: {result.stderr}")

        header = directory / "nul-header.h"
        header.write_bytes(b'// header\n\0\n')
        source.write_text('#include "nul-header.h"\nint main() { return 0; }\n')
        result = command([PP, source], check=False)
        expect(result.returncode != 0 and f"{header}:2: raw NUL byte" in result.stderr,
               f"included file NUL lacked its location: {result.stderr}")

def library_boundary_case():
    """Check that library calls require declarations while core built-ins do not.

    Returns:
        None; raises AssertionError for incorrect call acceptance or execution.
    """
    rejected = (
        "int main() { exit(1); return 0; }",
        'int main() { return strcmp("a", "a"); }',
        'int main() { long n = strlen("a"); return 0; }',
        'int main() { return length("a"); }',
        "int main() { print_number(1); return 0; }",
        "int main() { print_real(1.5); return 0; }",
        'int main() { char* a = "x"; memcpy(a, a, 0); return 0; }',
    )
    with tempfile.TemporaryDirectory(prefix="crunch-library-") as td:
        directory = pathlib.Path(td)
        for number, body in enumerate(rejected):
            source = directory / f"reject{number}.bc"
            source.write_text(body + "\n")
            result = command([DRIVER, "--emit-ir", source], check=False)
            expect(result.returncode != 0 and "undefined function" in result.stderr,
                   f"library call without a header was accepted: {body}")

        core = directory / "core.bc"
        core.write_text('int main() { int n = 4; '
                        'if (compare("ab", "ab", 2) != 0) return 99; return (int)n; }\n')
        command([DRIVER, core, "-o", directory / "core"], cwd=directory)
        result = command([directory / "core"], check=False)
        expect(result.returncode == 4 and result.stdout == "",
               f"core built-ins without headers gave {result.returncode} {result.stdout!r}")

        cast = directory / "cast.bc"
        cast.write_text('int main() { char s[] = "Hello"; int n = (int)compare(s, s, 5); '
                        'int c = (int)compare(s, s, 5); return n + c; }\n')
        command([DRIVER, cast, "-o", directory / "cast"], cwd=directory)
        result = command([directory / "cast"], check=False)
        expect(result.returncode == 0, "cast of a built-in call gave a wrong result")

        shadow = directory / "shadow.bc"
        shadow.write_text("#include <string.h>\n#include <stdio.h>\n#include <stdlib.h>\n"
                          "int main() { return 0; }\n")
        command([DRIVER, "--emit-ir", shadow], cwd=directory)

        user = directory / "user.bc"
        user.write_text("int memcpy(int a) { return a + 1; }\n"
                        "int strlen(int a) { return a * 2; }\n"
                        "int print_number(int a) { return a + 10; }\n"
                        "int strcmp(int a, int b) { return a - b; }\n"
                        "int exit(int a) { return a + 1; }\n"
                        "int main() { return memcpy(1) + strlen(2) + print_number(3) "
                        "+ strcmp(9, 4) + exit(0); }\n")
        command([DRIVER, user, "-o", directory / "user"], cwd=directory)
        result = command([directory / "user"], check=False)
        expect(result.returncode == 25 and result.stdout == "",
               f"user-defined functions with library names gave {result.returncode}")

