def byte_pointer_initializer_case():
    """Check legacy byte-string copies and fixed-array initializer validation.

    Returns:
        None; raises AssertionError for incorrect copying, type checks, or module behavior.
    """
    for name in ("legacy_byte_pointer_initializer.bir", "legacy_byte_pointer_initializer_module.bir"):
        compile_run(FIXTURES / "ir" / name, 42, args=("abc",))
    for name in ("legacy_global_byte_pointer_initializer.bir", "legacy_global_byte_pointer_initializer_module.bir"):
        compile_run(FIXTURES / "ir" / name, 42)
    for text in ("int main() { int *p = 0; char a[] = p; return 0; }",
                 "int main() { char a[] = 0; return 0; }",
                 "char a[] = 0; int main() { return 0; }",
                 "int *p; char a[] = p; int main() { return 0; }"):
        result = command([DRIVER, "--emit-ir", "-"], input=text, check=False)
        expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
               f"incompatible byte-array initializer was accepted: {text}")

def array_descriptor_protection_case():
    """Reject fixed-array mutations while preserving legacy IR execution.

    Returns:
        None; raises AssertionError for incorrect results or diagnostics.
    """
    for name in ("legacy_descriptor_protection.bir", "legacy_descriptor_protection_module.bir"):
        compile_run(FIXTURES / "ir" / name, 42)

    for element in ("int", "struct Item", "int*"):
        array = f"{element} a[2];"
        field = f"{element} values[2];"
        prefix = f"struct Item {{ int x; }}; struct Box {{ {field} }}; "
        contexts = (
            ("", array, "a"),
            (array, "", "a"),
            ("extern " + array, "", "a"),
            ("", "struct Box b;", "b.values"),
            ("struct Box b;", "", "b.values"),
            ("", "struct Box b; struct Box* p = &b;", "p->values"),
            ("", "struct Box b[1];", "b[0].values"),
        )
        for globals_, locals_, target in contexts:
            for operation in (f"{target} = 0;", f"{target}++;", f"{target}--;",
                              f"++{target};", f"--{target};", f"{target} += 1;",
                              f"{target} -= 1;", f"if ({target}++) return 1;"):
                program = prefix + globals_ + " int main() { " + locals_ + operation + "return 0; }\n"
                result = command([DRIVER, "--emit-ir", "-"], input=program, check=False)
                expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
                       f"array mutation accepted: {program}: {result.stderr}")
    for element in ("char", "long", "double"):
        program = f"int main() {{ {element} a[2]; a++; return 0; }}\n"
        result = command([DRIVER, "--emit-ir", "-"], input=program, check=False)
        expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
               f"numeric array mutation accepted: {program}: {result.stderr}")
    anonymous = ("struct Box { struct { int values[2]; }; }; int main() { struct Box b; "
                 "b.values = 0; return 0; }\n")
    result = command([DRIVER, "--emit-ir", "-"], input=anonymous, check=False)
    expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
           f"anonymous array mutation accepted: {result.stderr}")
    shadow = ("int* values; int main() { int values[2]; values++; return 0; }\n")
    result = command([DRIVER, "--emit-ir", "-"], input=shadow, check=False)
    expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
           f"shadowing array mutation accepted: {result.stderr}")

def pointer_arrays_case():
    """Check dynamic pointer arrays, initialization, failure, and interoperability.

    Returns:
        None; raises AssertionError for incorrect results or diagnostics.
    """
    fixtures = FIXTURES / "units/dynamic_arrays"
    for name in ("legacy_pointer_arrays.bir", "legacy_pointer_arrays_module.bir"):
        compile_run(FIXTURES / "ir" / name, 42, checks=("array_resize ptr", "ptradd ptr", "storeind ptr"))
    with tempfile.TemporaryDirectory(prefix="crunch-pointer-arrays-") as td:
        directory = pathlib.Path(td)
        obj, exe = directory / "program.o", directory / "program"
        global_source = directory / "global.bc"
        global_source.write_text("int value = 42; int* items[] = {&value, 0}; "
                                 "int main() { int r = *items[0]; "
                                 "if (sizeof(items) != 16 || items[1] != 0) return 1; "
                                 "return r; }\n")
        compile_run(global_source, 42)
        command([DRIVER, "-c", global_source, "-o", obj])
        command([DRIVER, "-o", exe, obj])
        expect(command([exe], check=False).returncode == 42,
               "module pointer array initializer failed")

        main, helper = directory / "main.bc", directory / "helper.bc"
        main.write_text("int* shared[1]; int set(int* p); "
                        "int main() { int x = 42; if (set(&x) != 1 || "
                        "*shared[0] != 42) return 1; return x; }\n")
        helper.write_text("extern int* shared[]; int set(int* p) { "
                          "shared[0] = p; return 1; }\n")
        main_obj, helper_obj = directory / "main.o", directory / "helper.o"
        command([DRIVER, "-c", main, "-o", main_obj])
        command([DRIVER, "-c", helper, "-o", helper_obj])
        command([DRIVER, main_obj, helper_obj, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "pointer array failed across Crunch modules")

        helper.write_text("struct Box { int* values[3]; }; "
                          "int initialize(struct Box* p, int* a, int* b) { "
                          "p->values[0] = a; p->values[1] = b; p->values[2] = 0; return 3; }\n")
        command([DRIVER, "-c", helper, "-o", helper_obj])
        harness = directory / "interop.c"
        harness.write_text("struct Box { int *values[3]; int padding; };\n"
                           "extern int initialize(struct Box *, int *, int *);\n"
                           "int main(void) { int x = 1, y = 2; struct Box b = {{0}, 123}; "
                           "if (initialize(&b, &x, &y) != 3 || "
                           "b.values[0] != &x || b.values[1] != &y || b.values[2] || "
                           "b.padding != 123) return 1; return 0; }\n")
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Werror", "-no-pie",
                 harness, helper_obj, LIBCRUNCH, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "pointer array field failed with C storage")

        allocator = directory / "allocator.o"
        command(["as", "-o", allocator, fixtures / "failing_allocator.s"])
        for module in (False, True):
            ir_file, asm_file = directory / "failure.bir", directory / "failure.s"
            ir_file.write_text((FIXTURES / "ir" /
                                f"legacy_pointer_array_failure{'_module' if module else ''}.bir").read_text())
            asm_file.write_text(command([ASM, ir_file]).stdout)
            command([TEST_AS, "-o", obj, asm_file])
            command([*TEST_LINK, "-o", exe, obj, allocator, LIBCRUNCH])
            expect(command([exe], check=False).returncode == 42,
                   f"pointer array allocation failure in {'module' if module else 'v2'}")

        for program in (
                "int main() { int x; int* a[] = {&x, 1}; return 0; }",
                "int main() { int x; double* a[] = {&x}; return 0; }",
                "int main() { int x; const int* b[] = {&x}; int* a[] = {b[0]}; return 0; }",
                "int main() { int x; int* const a[] = {&x}; a[0]++; return 0; }"):
            result = command([DRIVER, "--emit-ir", "-"], input=program + "\n", check=False)
            expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
                   f"invalid pointer-array operation accepted: {program}: {result.stderr}")
        for program in (
                "int main() { int* a[2]; a++; return 0; }",
                "int main() { int* a[2]; ++a; return 0; }",
                "int main() { int* a[2]; a += 1; return 0; }",
                "int main() { int* a[2]; int* b[2]; a = b; return 0; }",
                "int* a[2]; int main() { int* b[2]; a = b; return 0; }",
                "struct A { int* a[2]; }; int main() { struct A a; int* b[2]; "
                "a.a = b; return 0; }",
                "struct A { int* a[2]; }; int main() { struct A a; struct A* p = &a; "
                "p->a++; return 0; }",
                "int main() { int* a[2]; int*** p = &a; return 0; }"):
            result = command([DRIVER, "--emit-ir", "-"], input=program + "\n", check=False)
            expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
                   f"invalid pointer-array operation accepted: {program}: {result.stderr}")

def indirect_array_fields_case():
    """Check indirect array descriptors, initialization, and allocation failures.

    Returns:
        None; raises AssertionError for incorrect results or diagnostics.
    """
    fixtures = FIXTURES / "units/dynamic_arrays"
    for name in ("legacy_indirect_array_fields.bir", "legacy_indirect_array_fields_module.bir"):
        compile_run(FIXTURES / "ir" / name, 42,
                    checks=("array_resize int", "array_resize byte", "storeind ptr"))
    with tempfile.TemporaryDirectory(prefix="crunch-indirect-arrays-") as td:
        directory = pathlib.Path(td)
        obj, exe = directory / "program.o", directory / "program"
        allocator = directory / "allocator.o"
        command(["as", "-o", allocator, fixtures / "failing_allocator.s"])
        for module in (False, True):
            ir_file, asm_file = directory / "failure.bir", directory / "failure.s"
            ir_file.write_text((FIXTURES / "ir" /
                                f"legacy_indirect_array_field_failure{'_module' if module else ''}.bir").read_text())
            asm_file.write_text(command([ASM, ir_file]).stdout)
            command([TEST_AS, "-o", obj, asm_file])
            command([*TEST_LINK, "-o", exe, obj, allocator, LIBCRUNCH])
            result = command([exe], check=False)
            expect(result.returncode == 42,
                   f"indirect array allocation failure in {'module' if module else 'v2'}: "
                   f"{result.returncode}")

        helper = directory / "helper.bc"
        helper.write_text("struct Box { int values[2]; }; "
                          "int initialize(struct Box* p) { p->values[0] = 17; "
                          "p->values[1] = 25; return 2; }\n")
        command([DRIVER, "-c", helper, "-o", obj])
        harness = directory / "interop.c"
        harness.write_text("struct Box { int values[2]; };\n"
                           "extern int initialize(struct Box *);\n"
                           "int main(void) { struct Box b = {{0}}; "
                           "return initialize(&b) != 2 || "
                           "b.values[0] != 17 || b.values[1] != 25; }\n")
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Werror", "-no-pie",
                 harness, obj, LIBCRUNCH, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "indirect fixed array field failed with C storage")

        for program, diagnostic in (
                ("struct A { int a[2]; }; int main() { struct A a; const struct A* p = &a; "
                 "p->a[1] = 1; return 0; }", "E_SEMANTIC"),
                ("struct A { int a[2]; }; int main() { struct A a; struct A* p = &a; "
                 "p->a[1.5] = 1; return 0; }", "E_SEMANTIC"),
                ("struct A { int a[2]; }; int main() { struct A a; struct A* p = &a; "
                 "double source[2]; p->a = source; return 0; }", "E_SEMANTIC")):
            result = command([DRIVER, "--emit-ir", "-"], input=program + "\n", check=False)
            expect(result.returncode != 0 and diagnostic in result.stderr,
                   f"invalid indirect array operation accepted: {program}: {result.stderr}")

