def nonexec_stack_case():
    """Check that generated assembly links without an executable stack requirement.

    Returns:
        None; raises AssertionError if stack metadata or linker diagnostics regress.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-stack-") as td:
        directory = pathlib.Path(td)
        source = directory / "p.bc"
        source.write_text("int main() { return 3; }\n")
        asm = command([DRIVER, "-S", source, "-o", directory / "p.s"], cwd=directory, check=False)
        text = (directory / "p.s").read_text() if (directory / "p.s").exists() else ""
        expect(".note.GNU-stack" in text, "generated assembly lacks .note.GNU-stack")
        result = command([DRIVER, source, "-o", directory / "p"], cwd=directory)
        expect("executable stack" not in result.stderr + result.stdout,
               "linker warned about an executable stack")

def caret_diagnostic_case():
    """Check source-line and caret diagnostics for errors in included headers.

    Returns:
        None; raises AssertionError for incorrect location or context rendering.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-caret-") as td:
        directory = pathlib.Path(td)
        (directory / "inc").mkdir()
        (directory / "inc/h.h").write_text("int bad() { return 1 +; }\n")
        source = directory / "m.bc"
        source.write_text('#include "inc/h.h"\nint main() {\n\tint x = "s";\n  return 0;\n}\n')
        result = command([DRIVER, source, "-o", directory / "m"], check=False)
        expect(result.returncode != 0 and
               "h.h:1:23: error[E_PARSE]: unexpected SEMICOLON\n  int bad() { return 1 +; }\n"
               + " " * 24 + "^\n" in result.stderr,
               f"parse error lacks source line and caret: {result.stderr!r}")
        (directory / "inc/h.h").write_text("int ok() { return 1; }\n")
        result = command([DRIVER, source, "-o", directory / "m"], check=False)
        expect("\tint x = \"s\";\n  \t" in result.stderr and "^\n" in result.stderr,
               f"semantic error lacks tab-preserving caret: {result.stderr!r}")

def frontend_allocation_failure_case(stage):
    """Build and run allocation-failure injection for a frontend stage.

    Args:
        stage: Frontend stage to exercise: lexer, parser, or sema.
    Returns:
        None; raises AssertionError for build failure, incorrect status, or leaks.
    """
    with tempfile.TemporaryDirectory(prefix=f"crunch-{stage}-allocation-") as td:
        program = pathlib.Path(td) / "test-allocation"
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Wpedantic", "-Werror",
                 "-O1", "-g", "-fsanitize=address,undefined", "-iquote", ROOT / "include",
                 ROOT / "tests/unit/parser/test_allocation.c",
                 ROOT / "src/parser/parser.c", ROOT / "src/lexer/lexer.c",
                 ROOT / "src/lexer/token.c", ROOT / "src/sema/sema.c",
                 ROOT / "src/common/constant_expr.c",
                 "-Wl,--wrap=malloc,--wrap=calloc,--wrap=realloc,--wrap=free",
                 "-o", program])
        env = dict(os.environ, ASAN_OPTIONS="detect_leaks=1:exitcode=99",
                   LSAN_OPTIONS="exitcode=99", UBSAN_OPTIONS="halt_on_error=1")
        command([program] + ([f"--{stage}"] if stage != "parser" else []), env=env)

