                          'int JOINED = NUMBER();\n'
                          '#macro LONG ' + 'x' * 300 + '\n'
                          '#define EMPTY\nEMPTY int empty_macro;\n'
                          '#if __has_include("once.h") && !__has_include("absent.h")\n'
                          'int header_found;\n#endif\n'
                          '#define CAP crunch_unknown_builtin\n'
                          '#if !__has_builtin(CAP) && !__has_attribute(crunch_unknown_attribute)\n'
                          'int capabilities_checked;\n#endif\n'
                          '#if __CHAR_BIT__ == 8 && __SIZEOF_LONG__ == 8 && defined(__CHAR_UNSIGNED__)\n'
                          'int target_layout_checked;\n#endif\n'
