def codegen_allocation_failure_case():
    """Inject failures in IR generation, IR reading, and assembly generation.

    Returns:
        None; raises AssertionError for incorrect status, diagnostics, or cleanup.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-codegen-allocation-") as td:
        directory = pathlib.Path(td)
        program = directory / "test-allocation"
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Wpedantic", "-Werror",
                 "-O1", "-g", "-fsanitize=address,undefined", "-iquote", ROOT / "include",
                 ROOT / "tests/unit/codegen/test_allocation.c",
                 ROOT / "src/ir/ir.c", ROOT / "src/codegen/x86_64.c",
                 ROOT / "src/common/source.c", ROOT / "src/common/constant_expr.c",
                 ROOT / "src/lexer/lexer.c", ROOT / "src/lexer/token.c",
                 ROOT / "src/parser/parser.c", ROOT / "src/sema/sema.c",
                 BUILD / "lib/pow.o",
                 "-Wl,--wrap=malloc,--wrap=calloc,--wrap=realloc,--wrap=free,"
                 "--wrap=strdup,--wrap=getline", "-o", program], timeout=180)
        source = directory / "input.bc"
        source.write_text(
            'int printf(const char* format);\n'
            'char global_text[] = "global";\n'
            'struct Pair { union { int x; int y; }; char text[4]; }; struct Pair global_pair;\n'
            'union Big { long words[3]; double values[3]; };\n'
            'union Big roundtrip(union Big value) { return value; }\n'
            'int consume(struct Pair value) { return value.x; }\n'
            'int main() { static struct Pair saved = {.x = 1, .text = "ok"}; '
            'struct Pair local; union Big big; char data[] = "abc";\n'
            'big.words[0] = 4; big = roundtrip(big);\n'
            'local.x = saved.x; local.x = consume(local); printf("message");\n'
            'switch (local.x) { case 1: local.x = 2; break; default: local.x = 3; }\n'
            'data[0] = (char)0; return local.x; }\n')
        module_source = directory / "module.bc"
        module_source.write_text('extern int external_count;\n'
                                 'extern int helper(int value);\n' + source.read_text())
        invalid = directory / "unsupported.bc"
        invalid.write_text('char text[] = "abc"; int invalid = 1 / 0;'
                           'int main() { return 0; }\n')
        env = dict(os.environ, ASAN_OPTIONS="detect_leaks=1:exitcode=99",
                   LSAN_OPTIONS="exitcode=99", UBSAN_OPTIONS="halt_on_error=1")
        for path, mode in ((source, "executable"), (module_source, "module"),
                           (invalid, "invalid")):
            command([program, "ir", path, mode], env=env)
        for module in (False, True):
            ir_file = directory / ("module.bir" if module else "executable.bir")
            args = [IR, "--module", module_source] if module else [IR, source]
            ir_file.write_text(command(args).stdout)
            command([program, "backend", ir_file, "valid"], env=env)
        growing_ir = directory / "growing-functions.bir"
        growing_ir.write_text(
            "CRUNCH-IR 3\n" +
            "".join(f"extern_func external_{i} 0 int\n" for i in range(17)) +
            "".join(f"func helper_{i} 0 int\npush 0\nret int\nend\n" for i in range(17)) +
            "func main 0 int\npush 0\nret int\nend\n")
        command([program, "backend", growing_ir, "valid"], env=env, timeout=180)
        stack_ir = directory / "stack-allocation.bir"
        stack_ir.write_text("CRUNCH-IR 59\n"
                            "func helper 0 int\npush 3\npush 32\nstackalloc_live\n"
                            "drop\nret int\nend\n"
                            "func main 0 int\npush 8\nstackalloc_live\n"
                            "drop\npush 0\nret int\nend\n")
        command([program, "backend", stack_ir, "valid"], env=env, timeout=180)
        invalid_ir = directory / "invalid.bir"
        invalid_ir.write_text('CRUNCH-IR 2\nstringlit bad_label 4g\n')
        command([program, "backend", invalid_ir, "invalid"], env=env)

