def command_line_define_case():
    """Check command-line macro definitions and invalid names.

    Returns:
        None; raises AssertionError for incorrect expansion or option validation.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-define-") as td:
        directory = pathlib.Path(td)
        source = directory / "m.bc"
        source.write_text(
            "int main() {\n#ifdef FLAG\n  return LIMIT + EXTRA;\n#else\n  return 1;\n#endif\n}\n")
        program = directory / "m"
        command([DRIVER, "-DFLAG", "-D", "LIMIT=40", "-DEXTRA=2", source, "-o", program])
        expect(command([program], check=False).returncode == 42, "-D macros were not applied")
        command([DRIVER, source, "-o", program])
        expect(command([program], check=False).returncode == 1, "macro defined without -D")
        bad = command([DRIVER, "-D", "1bad", source, "-o", program], check=False)
        expect(bad.returncode != 0 and "invalid macro name" in bad.stderr, "bad -D name accepted")
        expanded = command([PP, "-DLIMIT=5", source]).stdout
        expect("return 1;" in expanded and "LIMIT" not in expanded.split("return")[0],
               "crunch-pp -D did not run the preprocessor")
        output = command([PP, "-DFLAG", "-DEMPTY=", "-"],
                         input="#if FLAG\nEMPTY int value = FLAG;\n#endif\n").stdout
        expect("int value = 1;" in output and "EMPTY" not in output,
               f"bare and empty command-line definitions expanded incorrectly: {output}")

def switch_case():
    """Check switch constant labels, fall-through, break, and invalid forms.

    Returns:
        None; raises AssertionError for incorrect execution or semantic validation.
    """
    source_text = """int main() {
  int result = 0;
  switch (2) {
    case 1: result = 1; break;
    case 1 + 1: result = 20;
    case 3: result += 3; break;
    default: result = 99;
  }
  switch (8) {
    case 7: result = 0; break;
    default: result += 10;
    case 9: result += 2; break;
  }
  switch (0) { case 1: result = 0; }
  int i = 0;
  while (i < 3) {
    i++;
    switch (i) {
      case 1: result += 1; break;
      case 2: result += 2; break;
      default: break;
    }
    result += 10;
  }
  switch (1) {
    case 1:
      switch (2) {
        case 2: result += 1; break;
        default: result = 0;
      }
      result += 10;
      break;
    default: result = 0;
  }
  return result;
}
"""
    with tempfile.TemporaryDirectory(prefix="crunch-switch-") as td:
        directory = pathlib.Path(td)
        source = directory / "switch.bc"
        source.write_text(source_text)
        tree = json.loads(source_parse(source).stdout)
        expect('"kind": "switch"' in json.dumps(tree),
               "switch was not represented in the AST interchange output")
        compile_run(source, 79)
        source.write_text('''
int main(void) {
    int result = 0;
    switch (1) {
    case 1:
        if (result) return 1;
        int first = 3, second = first + 4;
        { int first = 9; result += first; }
        result += first;
    case 2:
        result += second;
        break;
    }
    return result;
}
''')
        compile_run(source, 19)
        for invalid, diagnostic in (
            ("int main() { switch (1) { case 1: break; case 1: break; } return 0; }\n",
             "duplicate case label"),
            ("int main() { switch (1) { default: break; default: break; } return 0; }\n",
             "duplicate default label"),
            ("int main() { int n = 1; switch (n) { case n: break; } return 0; }\n",
             "case label is not an integer constant expression"),
            ("int main() { switch (1.5) { default: break; } return 0; }\n",
             "switch expression must have integer type"),
            ("int main() { char n = 1; switch (n) { case 256: break; case 256: break; } return 0; }\n",
             "duplicate case label"),
            ("int main() { switch (0) { case 0: int x = 1, y = 2; break; } return x; }\n",
             "undefined identifier 'x'"),
        ):
            source.write_text(invalid)
            result = command([IR, source], check=False)
            expect(result.returncode != 0 and diagnostic in result.stderr,
                   f"invalid switch accepted or misdiagnosed: {result.stderr!r}")

def continue_case():
    """Check continue behavior in loops and switches and reject illegal use.

    Returns:
        None; raises AssertionError for incorrect control flow or diagnostics.
    """
    source_text = """int main() {
  int total = 0;
  for (int i = 0; i < 6; i++) {
    if (i == 2) continue;
    total += i;
  }
  int j = 0;
  while (j < 6) {
    j++;
    if (j == 3) continue;
    switch (j) {
      case 4: continue;
      default: break;
    }
    total += 10;
  }
  return total;
}
"""
    with tempfile.TemporaryDirectory(prefix="crunch-continue-") as td:
        source = pathlib.Path(td) / "continue.bc"
        source.write_text(source_text)
        compile_run(source, 53)
        for invalid in ("int main() { continue; return 0; }\n",
                        "int main() { switch (1) { case 1: continue; } return 0; }\n"):
            source.write_text(invalid)
            result = command([IR, source], check=False)
            expect(result.returncode != 0 and "continue used outside a loop" in result.stderr,
                   f"invalid continue accepted: {result.stderr!r}")

def file_io_case():
    """Exercise file creation, reading, writing, append mode, and error returns.

    Returns:
        None; raises AssertionError for unexpected file contents or status.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-fileio-") as td:
        directory = pathlib.Path(td)
        data = directory / "data.txt"
        source = directory / "io.bc"
        source.write_text(f'''#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <dirent.h>
#include <stdio.h>
#include <string.h>
int main() {{
  char text[] = "hello";
  char more[] = " world";
  char buffer[32];
  long fd = file_open("{data}", FILE_WRITE);
  if (fd < 0) return 1;
  if (file_write(fd, text, strlen(text)) != 5) return 2;
  if (file_close(fd) != 0) return 3;
  fd = file_open("{data}", FILE_APPEND);
  if (fd < 0 || file_write(fd, more, 6) != 6) return 4;
  file_close(fd);
  fd = file_open("{data}", FILE_READ);
  if (fd < 0) return 5;
  long n = file_read(fd, buffer, 31);
  file_close(fd);
  if (n != 11) return 6;
  buffer[n] = (char)0;
  if (strcmp(buffer, "hello world") != 0) return 7;
  if (file_open("{directory}/missing.txt", FILE_READ) >= 0) return 8;
  if (file_read(-1, buffer, 1) >= 0) return 9;
  if (file_write(-1, text, 1) >= 0) return 10;
  if (file_close(-1) >= 0) return 11;
  if (file_read(-1, 0, 0) >= 0) return 12;
  return 42;
}}
''')
        exe = directory / "io"
        command([DRIVER, source, "-o", exe])
        result = command([exe], check=False)
        expect(result.returncode == 42, f"file I/O program exited with {result.returncode}")
        expect(data.read_text() == "hello world", "file contents were not written correctly")

def void_pointer_case():
    """Check void-pointer conversions, operations, storage, and function ABI.

    Returns:
        None; raises AssertionError for incorrect compilation or execution.
    """
    source = FIXTURES / "units/types/void_pointer.bc"
    command([SEMA, source, "expect-ok"])
