        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Wpedantic", "-Werror",
                 fixtures / "allocator_pool.c", LIBCRUNCH,
                 "-Wl,--wrap=_crunch_mmap,--wrap=_crunch_munmap", "-o", exe])
        command([exe])
