def large_local_frame_case():
    """Check local-slot boundaries and execution above the old 512-slot limit.

    Returns:
        None; raises AssertionError for incorrect compilation, execution or validation.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-large-locals-") as td:
        directory = pathlib.Path(td)
        source, obj, exe = directory / "locals.bc", directory / "locals.o", directory / "locals"
        declarations = "\n".join(f"unsigned int v{i} = {i % 43}U;" for i in range(1024))
        source.write_text("int main(void) {\n" + declarations +
                          "\nreturn (int)(v0 + v1023);\n}\n")
        command([DRIVER, "-c", source, "-o", obj])
        for flag in ("--static", "--dynamic"):
            for input_file in (source, obj):
                command([DRIVER, flag, input_file, "-o", exe])
                expect(command([exe], check=False).returncode == 34,
                       f"large local frame failed ({flag}, {input_file.name})")
        source.write_text("int main(void) {\n" + declarations +
                          "\nint extra = 0;\nreturn extra;\n}\n")
        result = command([DRIVER, "--emit-ir", source, "-o", directory / "bad.bir"],
                         check=False)
        expect(result.returncode != 0 and "too many local" in result.stderr,
               "frontend failed to reject too many local variables")
        source.write_text("int main(void) {\n" + declarations +
                          "\nswitch (v0) { default: return 0; }\n}\n")
        result = command([DRIVER, "--emit-ir", source, "-o", directory / "bad.bir"],
                         check=False)
        expect(result.returncode != 0 and "too many local" in result.stderr,
               "frontend failed to reject a switch needing an extra local slot")
        source.write_text("int main(void) {\n" +
                          "\n".join("{ int v = 1; }" for _ in range(1025)) +
                          "\nreturn 0;\n}\n")
        result = command([DRIVER, "--emit-ir", source, "-o", directory / "bad.bir"],
                         check=False)
        expect(result.returncode != 0 and "too many local" in result.stderr,
               "frontend failed to reject exhausted slots across nested scopes")
        ir = directory / "bad.bir"
        ir.write_text("CRUNCH-IR 6\nfunc main 0 int\n"
                      "local 1024 int\npush 0\nret int\nend\n")
        expect(command([ASM, ir], check=False).returncode != 0,
               "backend accepted a local slot outside the supported range")


def stdio_open_case():
    """Check Crunch stream modes, errors, cleanup, and linkage.

    Returns:
        None; raises AssertionError for incorrect stream behavior.
    """
    source = FIXTURES / "units/library/stdio_open.bc"
    with tempfile.TemporaryDirectory(prefix="crunch-stdio-open-") as td:
        directory = pathlib.Path(td)
        obj, exe = directory / "program.o", directory / "program"
        for separate in (False, True):
            if separate:
                command([DRIVER, "-c", source, "-o", obj])
                command([DRIVER, obj, "-o", exe])
            else:
                command([DRIVER, source, "-o", exe])
            work = directory / ("module" if separate else "single")
            work.mkdir()
            for name in ("untouched", "append", "truncate"):
                (work / name).write_bytes(b"original")
            result = command([SHELL, "-c", 'umask 022; exec "$1"', "test", exe],
                             cwd=work, check=False)
            expect(result.returncode == 0,
                   f"stdio open/close failed in {work.name}: {result.returncode} {result.stderr}")
            expect((work / "untouched").read_bytes() == b"original" and
                   (work / "append").read_bytes() == b"original!" and
                   (work / "truncate").read_bytes() == b"" and
                   (work / "created").stat().st_mode & 0o777 == 0o644,
                   "incorrect fopen truncation, append, or creation permissions")
        internal = directory / "internal"
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Werror",
                 FIXTURES / "units/library/stdio_open_internal.c",
                 BUILD / "lib/fopen.o", BUILD / "lib/fclose.o", "-o", internal])
        command([internal])

def stdio_io_case():
    """Check stream reads, writes, seeks, partial transfers, and failures.

    Returns:
        None; raises AssertionError for incorrect stream behavior.
    """
    source = FIXTURES / "units/library/stdio_io.bc"
    with tempfile.TemporaryDirectory(prefix="crunch-stdio-io-") as td:
        directory = pathlib.Path(td)
        obj, exe = directory / "program.o", directory / "program"
        for separate in (False, True):
            if separate:
                command([DRIVER, "-c", source, "-o", obj])
                command([DRIVER, obj, "-o", exe])
            else:
                command([DRIVER, source, "-o", exe])
            work = directory / ("module" if separate else "single")
            work.mkdir()
            (work / "data").write_bytes(b"abcdefg")
            (work / "append").write_bytes(b"original")
            os.mkfifo(work / "pipe")
            result = command([exe], cwd=work, check=False)
            expect(result.returncode == 0,
                   f"stdio I/O failed in {work.name}: {result.returncode} {result.stderr}")
            expect((work / "data").read_bytes() == b"aXYdefg" and
                   (work / "append").read_bytes() == b"original!" and
                   (work / "sparse").stat().st_size == 4294967297,
                   "stream output, append, or large seek was incorrect")
        internal = directory / "internal"
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Werror",
                 FIXTURES / "units/library/stdio_io_internal.c",
                 *[BUILD / "lib" / f"{name}.o"
                   for name in ("fread", "fwrite", "fseek", "ftell", "rewind",
                                "clearerr", "stream_transfer")],
                 "-o", internal])
        command([internal])
        provider, consumer = directory / "provider.bc", directory / "consumer.bc"
        provider.write_text('#include <unistd.h>\n#include <fcntl.h>\n#include <sys/stat.h>\n#include <dirent.h>\n#include <stdio.h>\n#include <stdio.h>\n'
                            'struct FILE* make() { return fopen("data", "r"); }\n')
        consumer.write_text('#include <stdio.h>\nextern struct FILE* make();\n'
                            'int main() { struct FILE* f = make(); char b[1]; '
                            'if (f == 0 || fread(b, 1, 1, f) != 1 || '
                            "b[0] != (char)'a') return 1; return fclose(f); }\n")
        parts = []
        for src in (provider, consumer):
            part = src.with_suffix(".o")
            command([DRIVER, "-c", src, "-o", part])
            parts.append(part)
        command([DRIVER, *parts, "-o", exe])
        (directory / "data").write_bytes(b"abc")
        result = command([exe], cwd=directory, check=False)
        expect(result.returncode == 0, "stream use across modules failed")

def stdio_char_case():
    """Check character I/O and standard streams across compilation modes.

    Returns:
        None; raises AssertionError for incorrect stream behavior or linkage.
    """
    source = FIXTURES / "units/library/stdio_chars.bc"
    with tempfile.TemporaryDirectory(prefix="crunch-stdio-chars-") as td:
        directory = pathlib.Path(td)
        obj, exe = directory / "program.o", directory / "program"
        for separate in (False, True):
            if separate:
                command([DRIVER, "-c", source, "-o", obj])
                command([DRIVER, obj, "-o", exe])
            else:
                command([DRIVER, source, "-o", exe])
            work = directory / ("module" if separate else "single")
            work.mkdir()
            result = command([exe], cwd=work, input="A", check=False)
            expect(result.returncode == 0 and result.stdout == "OK" and result.stderr == "E",
                   f"character I/O failed in {work.name}: "
                   f"{result.returncode} {result.stdout!r} {result.stderr!r}")
            expect((work / "bytes").read_bytes() == b"\xff\x00\xff",
                   "character output did not preserve all byte values")
        provider, consumer = directory / "provider.bc", directory / "consumer.bc"
        provider.write_text("#include <stdio.h>\nstruct FILE* output() { return stdout; }\n")
        consumer.write_text("#include <stdio.h>\nextern struct FILE* output();\n"
                            "int main() { if (output() != stdout) return 1; "
                            "return fputc('X', output()) == 'X' ? 0 : 2; }\n")
        parts = []
        for src in (provider, consumer):
            part = src.with_suffix(".o")
            command([DRIVER, "-c", src, "-o", part])
            parts.append(part)
        command([DRIVER, *parts, "-o", exe])
        result = command([exe], check=False)
        expect(result.returncode == 0 and result.stdout == "X",
               "standard stream was not shared across Crunch modules")
        provider.write_text("#include <stdio.h>\nint crunch_put() { return fputc('Q', stdout); }\n")
        command([DRIVER, "-c", provider, "-o", parts[0]])
        csource = directory / "caller.c"
        csource.write_text('#include <stdio.h>\nextern int crunch_put(void);\n'
                           'int main(void) { if (crunch_put() != \'Q\') return 1; '
                           'return puts("C") < 0; }\n')
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Werror",
                 csource, parts[0], LIBCRUNCH, "-o", exe])
        result = command([exe], check=False)
        expect(result.returncode == 0 and result.stdout == "QC\n",
               "Crunch standard streams interfered with libc streams")

