def parser_bootstrap_case():
    """Build the unmodified parser with Crunch and compare token-stream behavior.

    Returns:
        None; raises AssertionError for compilation or behavior differences.
    """
    sources = ("src/driver/parser_main.c", "src/parser/parser.c", "src/parser/ast.c",
               "src/parser/ast_json.c", "src/lexer/token.c")
    with tempfile.TemporaryDirectory(prefix="crunch-bootstrap-parser-") as td:
        directory = pathlib.Path(td)
        objects = []
        for index, name in enumerate(sources):
            obj = directory / f"{index}.o"
            command([DRIVER, "-I", ROOT / "include", "-c", ROOT / name, "-o", obj])
            objects.append(obj)
        exe = directory / "parser"
        command([DRIVER, *objects, "-o", exe])
        text = directory / "floating.bc"
        text.write_text('''double a = 0.1;
float b = 1.000000059604644775390625000000000000000000001f;
double c = 4.9406564584124654e-324;
float d = 1.401298464324817e-45f;
double e = 0x1.0000000000001p0;
float f = 0x1.000002p0f;
int main() { return 0; }
''')
        extended = directory / "extended.bc"
        extended.write_text("long double x = 1.0000000000000000001L; "
                            "double long y = 0x1.0000000000000002p0l;\n")
        octal = directory / "octal.bc"
        octal.write_text(r'''char value[] = "\1" "" "7"; int c = '\377';''' + "\n")
        streams = []
        sources = [text, extended, octal, FIXTURES / "units/lexer/literals_and_operators.bc",
                   FIXTURES / "units/function_calls/variadic_frontend.bc",
                   FIXTURES / "units/types/array_typedef.bc",
                   FIXTURES / "units/types/static_assert.bc",
                   FIXTURES / "units/types/volatile_access.bc",
                   FIXTURES / "units/lexer/invalid_character.bc"]
        sources.extend(sorted((FIXTURES / "parser").glob("*.bc")))
        sources.extend(sorted((FIXTURES / "units/parser").glob("*.bc")))
        for source in sources:
            streams.append(command([LEXER, source], check=False).stdout)
        streams.extend(("", "CRUNCH-TOKENS 1\n", "CRUNCH-TOKENS 9\n",
                        "CRUNCH-TOKENS 1\nINVALID\t0\t1\t1\t40\nEOF\t1\t1\t2\t-\n"))
        for stream in streams:
            baseline = command([PARSER], input=stream, check=False)
            actual = command([exe], input=stream, check=False)
            expect((actual.returncode, actual.stdout, actual.stderr) ==
                   (baseline.returncode, baseline.stdout, baseline.stderr),
                   f"self-built parser differs for token stream {stream[:160]!r}: "
                   f"{actual.returncode} {actual.stderr!r} vs "
                   f"{baseline.returncode} {baseline.stderr!r}")
        for flags in (["--static"], ["-pie"]):
            command([DRIVER, *flags, *objects, "-o", exe])
            for stream in (streams[0], streams[-1], ""):
                baseline = command([PARSER], input=stream, check=False)
                actual = command([exe], input=stream, check=False,
                                 env=dict(os.environ, LD_LIBRARY_PATH=str(BUILD)))
                expect((actual.returncode, actual.stdout, actual.stderr) ==
                       (baseline.returncode, baseline.stdout, baseline.stderr),
                       f"self-built parser differs for link flags {flags}")

def parser_serializer_bootstrap_case():
    """Compare a Crunch-built AST serializer with the host build on real values.

    Returns:
        None; raises AssertionError for compilation or serialized output differences.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-bootstrap-ast-json-") as td:
        directory = pathlib.Path(td)
        harness = directory / "harness.c"
        harness.write_text('''#include "parser/ast_json.h"
#include <stdint.h>
#include <stdio.h>
int main() {
    Type type = {0}; type.kind = TYPE_REAL;
    Expr value = {0}; value.kind = EXPR_REAL;
    Decl declaration = {0};
    declaration.kind = DECL_VARIABLE;
    declaration.as.variable.name = "value";
    declaration.as.variable.type = &type;
    declaration.as.variable.initializer.kind = INIT_EXPRESSION;
    declaration.as.variable.initializer.expression = &value;
    Decl *items[1] = {&declaration};
    AstProgram program = {0};
    program.declarations.items = items;
    program.declarations.count = 1;
    union { uint64_t bits; double real; } number;
    uint64_t bits = UINT64_C(0x123456789abcdef0);
    for (int i = 0; i < 1000; ++i) {
        bits ^= bits << 13; bits ^= bits >> 7; bits ^= bits << 17;
        number.bits = bits;
        value.as.real_value = number.real;
        if (!ast_write_json(stdout, &program)) return 1;
    }
    return 0;
}
''')
        host = directory / "host"
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            command(["cc", "-std=c11", "-Wall", "-Wextra", "-Werror",
                     "-iquote", ROOT / "include", harness, ROOT / "src/parser/ast_json.c",
                     "-o", host])
        objects = []
        for index, source in enumerate((harness, ROOT / "src/parser/ast_json.c")):
            obj = directory / f"{index}.o"
            command([DRIVER, "-I", ROOT / "include", "-c", source, "-o", obj])
            objects.append(obj)
        executable = directory / "serializer"
        command([DRIVER, *objects, "-o", executable])
        actual = command([executable])
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            baseline = command([host])
            expect((actual.returncode, actual.stdout, actual.stderr) ==
                   (baseline.returncode, baseline.stdout, baseline.stderr),
                   "Crunch-built AST serializer differs from the host build")
        else:
            lines = actual.stdout.splitlines()
            expect(len(lines) == 1000, "serializer emitted the wrong number of documents")
            bits = 0x123456789abcdef0
            for line in lines:
                bits ^= (bits << 13) & 0xffffffffffffffff
                bits ^= bits >> 7
                bits ^= (bits << 17) & 0xffffffffffffffff
                number = struct.unpack(">d", bits.to_bytes(8, "big"))[0]
                expected = "null" if (bits >> 52) & 2047 == 2047 else format(number, ".17g")
                match = re.search(r'"value":(null|[-0-9.e+]+)', line)
                expect(match is not None and match.group(1) == expected,
                       f"serializer value differs for {bits:016x}")
                json.loads(line)

