def build_2gen_script_case():
    """Check bootstrap script sequencing, output paths, and overwrite protection.

    Returns:
        None; raises AssertionError for incorrect script behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-build-2gen-script-") as td:
        directory = pathlib.Path(td)
        root = directory / "project"
        root.mkdir()
        (root / "tests").mkdir()
        bindir = directory / "bin"
        bindir.mkdir()
        script = root / "build_2gen_crunch.sh"
        shutil.copy2(ROOT / "build_2gen_crunch.sh", script)
        configure = root / "configure"
        configure.write_text("#!/bin/sh\nprintf 'configured\\n' >> configure-log\n")
        configure.chmod(0o755)
        make = bindir / "make"
        make.write_text("#!/bin/sh\nmkdir -p build/out\n"
                        ": > build/out/crunch\n: > build/out/libcrunch.a\n")
        make.chmod(0o755)
        bootstrap = root / "tests/bootstrap-compiler.sh"
        bootstrap.write_text("""#!/bin/sh
set -eu
mode=gnu
if [ "${1-}" = --native ]; then shift; mode=native; echo native >> native-log; fi
if [ "${1-}" = --glibc ]; then shift; mode=glibc; echo glibc >> glibc-log; fi
case "$1" in
    */bootstrap-stage1)
        test "$CRUNCH_BOOTSTRAP_COMPILER" = "$PWD/build/out/crunch"
        if [ "$mode" != glibc ]; then
            test "$CRUNCH_BOOTSTRAP_RUNTIME" = "$PWD/build/out/libcrunch.a"
        fi ;;
    */bootstrap-stage2)
        test "$CRUNCH_BOOTSTRAP_COMPILER" = "$PWD/bootstrap-stage1/crunch"
        if [ "$mode" != glibc ]; then
            test "$CRUNCH_BOOTSTRAP_RUNTIME" = "$PWD/bootstrap-stage1/libcrunch.a"
        fi ;;
    *) exit 1 ;;
esac
mkdir "$1"
for tool in crunch crunch-pp crunch-ir crunch-opt crunch-asm; do : > "$1/$tool"; done
: > "$1/libcrunch.a"
""")
        env = dict(os.environ, PATH=str(bindir) + os.pathsep + os.environ.get("PATH", ""),
                   CRUNCH_BOOTSTRAP_COMPILER="wrong", CRUNCH_BOOTSTRAP_RUNTIME="wrong")
        result = command([script], cwd=directory, env=env)
        for tool in ("crunch", "crunch-pp", "crunch-ir", "crunch-opt", "crunch-asm"):
            expect(str(root / "bootstrap-stage2" / tool) in result.stdout,
                   f"second-generation {tool} path was not printed")
        (root / "bootstrap-stage1").rename(root / "gnu-stage1")
        (root / "bootstrap-stage2").rename(root / "gnu-stage2")
        result = command([script, "--native"], cwd=directory, env=env)
        expect((root / "native-log").read_text() == "native\nnative\n",
               "native bootstrap mode was not passed to both generations")
        for tool in ("crunch-as", "crunch-ld", "crunch-ar"):
            expect(str(root / "bootstrap-stage2" / tool) in result.stdout,
                   f"second-generation {tool} path was not printed")
        (root / "bootstrap-stage1").rename(root / "native-stage1")
        (root / "bootstrap-stage2").rename(root / "native-stage2")
        result = command([script, "--glibc"], cwd=directory, env=env)
        expect((root / "glibc-log").read_text() == "glibc\nglibc\n",
               "glibc bootstrap mode was not passed to both generations")
        for tool in ("crunch", "crunch-as", "crunch-ld", "crunch-ar"):
            expect(str(root / "bootstrap-stage2" / tool) in result.stdout,
                   f"second-generation glibc {tool} path was not printed")
        marker = root / "bootstrap-stage2" / "marker"
        marker.write_text("keep")
        result = command([script], cwd=directory, env=env, check=False)
        expect(result.returncode != 0 and "already exists" in result.stderr and
               (root / "configure-log").read_text() == "configured\nconfigured\nconfigured\n" and
               marker.read_text() == "keep",
               "bootstrap script did not protect existing output paths")
        (root / "bootstrap-stage1").rename(root / "saved-stage1")
        result = command([script], cwd=directory, env=env, check=False)
        expect(result.returncode != 0 and "bootstrap-stage2" in result.stderr and
               (root / "configure-log").read_text() == "configured\nconfigured\nconfigured\n" and
               marker.read_text() == "keep",
               "bootstrap script did not protect an existing second stage")
        (root / "bootstrap-stage1").symlink_to(root / "missing-target")
        result = command([script], cwd=directory, env=env, check=False)
        expect(result.returncode != 0 and "bootstrap-stage1" in result.stderr and
               (root / "configure-log").read_text() == "configured\nconfigured\nconfigured\n",
               "bootstrap script did not protect a dangling output symlink")


INSTALLED_TOOLCHAIN_CASES = (
    ("control", (), None, "control:31\n"),
    ("records", (), None, "records:85\n"),
    ("memory", (), None, "memory:crunch-compiler:15\n"),
    ("arguments", ("6", "7"), None, "args:42\n"),
    ("stream", (), "37\n", "stream:42\n"),
    ("numeric", (), None, "numeric:3.000000\n"),
    ("globals", (), None, "globals:46\n"),
    ("sorting", (), None, "sort:1,2,5,7,9\n"),
    ("file_io", (), None, "file:two\n"),
    ("modules", (), None, "modules:48:4\n"),
)

def native_bootstrap_corpus_case(stages, directory, env):
    """Compare native generations on the installed corpus and invalid inputs.

    Args:
        stages: First- and second-generation tool directories.
        directory: Temporary working directory for outputs.
        env: Environment with native-tool selection and no loader overrides.
    Returns:
        None; raises AssertionError for a behavior or diagnostic difference.
    """
    fixtures = FIXTURES / "units/installed_toolchain"
    output = directory / "corpus-program"
    output_file = directory / "corpus-output.txt"
    for name, args, stdin, expected in INSTALLED_TOOLCHAIN_CASES:
        sources = [fixtures / f"{name}.bc"]
        if name == "modules":
            sources.append(fixtures / "module_helper.bc")
        for mode, flags in (("static", ["--static"]), ("dynamic", ["--dynamic"]),
                            ("pie", ["--dynamic", "-pie"])):
            compilations, executions = [], []
            for stage in stages:
                stage_env = dict(env, CRUNCH_CONF_FILE=str(stage / "bootstrap.conf"))
                compiled = command([stage / "crunch", *flags, *sources, "-o", output],
                                   cwd=directory, env=stage_env, check=False, timeout=120)
                compilations.append((compiled.returncode, compiled.stdout, compiled.stderr))
                expect(compiled.returncode == 0,
                       f"{stage.name} {name} {mode} did not compile: {compiled.stderr}")
                image = output.read_bytes()
                expect(struct.unpack_from("<H", image, 16)[0] == (3 if mode == "pie" else 2),
                       f"{stage.name} {name} {mode} has the wrong ELF type")
                if mode != "static":
                    expect(str(stage).encode() + b"\0" in image,
                           f"{stage.name} {name} {mode} did not select its own runtime")
                output_file.unlink(missing_ok=True)
                result = command([output, *args], input=stdin, env=stage_env, cwd=directory,
                                 check=False)
                side_effect = output_file.read_bytes() if output_file.exists() else None
                executions.append((result.returncode, result.stdout, result.stderr, side_effect))
                expect(result.returncode == 0 and result.stdout == expected and not result.stderr,
                       f"{stage.name} {name} {mode} failed: {executions[-1]!r}")
                if name == "file_io":
                    expect(side_effect == b"one\ntwo\n",
                           f"{stage.name} {name} {mode} wrote incorrect file data")
                else:
                    expect(side_effect is None,
                           f"{stage.name} {name} {mode} unexpectedly wrote corpus output")
            expect(compilations[0] == compilations[1],
                   f"{name} {mode} compiler diagnostics differ: {compilations!r}")
            expect(executions[0] == executions[1],
                   f"{name} {mode} execution differs: {executions!r}")

    for tool, args, text in (
            ("crunch-pp", ["-"], '#include "missing-bootstrap-header.h"\n'),
            ("crunch-ir", ["--module", "-"], "int main() { return missing_variable; }\n"),
            ("crunch-asm", ["--validate", "-"],
             "CRUNCH-IR 35\nfunc f 0 int\nlocalblock b 16777217 8\npush 0\nret int\nend\n"),
            ("crunch-as", ["-o", directory / "invalid.o"],
             ".set invalid,9223372036854775807+1\n.byte invalid\n")):
        results = []
        for stage in stages:
            stage_env = dict(env, CRUNCH_CONF_FILE=str(stage / "bootstrap.conf"))
            result = command([stage / tool, *args], input=text, cwd=directory,
                             env=stage_env, check=False)
            results.append((result.returncode, result.stdout, result.stderr))
            expect(result.returncode != 0 and result.stderr,
                   f"{stage.name} {tool} accepted invalid input")
        expect(results[0] == results[1],
               f"{tool} diagnostics differ between generations: {results!r}")

    unresolved = directory / "unresolved.o"
    command([stages[0] / "crunch-as", "-o", unresolved],
            input=".text\n.globl _start\n_start: call missing_symbol\n", env=env)
    results = []
    for stage in stages:
        output.write_text("preserved")
        stage_env = dict(env, CRUNCH_CONF_FILE=str(stage / "bootstrap.conf"))
        result = command([stage / "crunch-ld", "-nostdlib", "-o", output, unresolved],
                         cwd=directory, env=stage_env, check=False)
        results.append((result.returncode, result.stdout, result.stderr))
        expect(result.returncode != 0 and "missing_symbol" in result.stderr and
               output.read_text() == "preserved",
               f"{stage.name} linker failed to reject an unresolved symbol safely")
    expect(results[0] == results[1],
           f"linker diagnostics differ between generations: {results!r}")


def glibc_integrated_bootstrap_case():
    """Build and compare two complete GNU/glibc toolchain generations.

    Returns:
        None; raises AssertionError for bootstrap or execution failures.
    """
    if ("CS_GNU_LIBC_VERSION" not in os.confstr_names or
            not os.confstr("CS_GNU_LIBC_VERSION") or not pathlib.Path("/usr/bin/cc").exists()):
        return

    def dependencies(path):
        """Return ELF dynamic dependency names.

        Args:
            path: Executable to inspect.
        Returns:
            List of DT_NEEDED library names.
        """
        image = path.read_bytes()
        expect(image[:4] == b"\x7fELF", f"{path} is not ELF")
        shoff = struct.unpack_from("<Q", image, 40)[0]
        shentsize, shnum = struct.unpack_from("<HH", image, 58)
        sections = [struct.unpack_from("<IIQQQQIIQQ", image, shoff + i * shentsize)
                    for i in range(shnum)]
        dynamic = next((section for section in sections if section[1] == 6), None)
        expect(dynamic is not None, f"{path} is not dynamically linked")
        strings = sections[dynamic[6]]
        data = image[strings[4]:strings[4] + strings[5]]
        needed = []
        for offset in range(dynamic[4], dynamic[4] + dynamic[5], 16):
            tag, value = struct.unpack_from("<qQ", image, offset)
            if tag == 0:
                break
            if tag == 1:
                needed.append(data[value:data.index(b"\0", value)].decode())
        return needed

    with tempfile.TemporaryDirectory(prefix="crunch-glibc-bootstrap-") as directory:
        td = pathlib.Path(directory)
        poison = td / "poison"
        poison.mkdir()
        (poison / "stdio.h").write_text("#error poisoned system header\n")
        env = {key: value for key, value in os.environ.items()
               if key not in ("LD_LIBRARY_PATH", "LD_PRELOAD", "LD_AUDIT",
                              "CRUNCH_GLIBC_CC")}
        env.update(PATH="/usr/bin:/bin", CRUNCH_INCLUDE_PATH=str(poison),
                   CPATH=str(poison), C_INCLUDE_PATH=str(poison),
                   CRUNCH_BOOTSTRAP_RUNTIME=str(td / "missing-crunch-libc"),
                   SOURCE_DATE_EPOCH="0")
        first, second = td / "stage1", td / "stage2"
        for compiler, stage in ((BUILD / "crunch", first), (first / "crunch", second)):
            runenv = dict(env, CRUNCH_BOOTSTRAP_COMPILER=str(compiler))
            bootstrap = command([SHELL, ROOT / "tests/bootstrap-compiler.sh", "--glibc", stage],
                                env=runenv, timeout=1800)
            expect("case falls through" not in bootstrap.stderr,
                   f"{stage.name} emitted default fall-through warnings")
            for name in ("crunch", "crunch-pp", "crunch-ir", "crunch-opt", "crunch-asm",
                         "crunch-as", "crunch-ld", "crunch-ar"):
                binary = stage / name
                needed = dependencies(binary)
                expect("libc.so.6" in needed and
                       not any(lib.startswith("libcrunch") for lib in needed),
                       f"{binary} has unexpected dynamic dependencies: {needed}")
            expect((stage / "libcrunch-support.a").is_file() and
                   not (stage / "libcrunch.a").exists(),
                   f"{stage.name} did not retain only the compiler support archive")

        clean_env = {key: value for key, value in env.items()
                     if key not in ("CRUNCH_INCLUDE_PATH", "CPATH", "C_INCLUDE_PATH")}
        source = ("#include <stdio.h>\n#include <stdint.h>\n"
                  "static _Thread_local int value = 40;\n"
                  "int main(void) { uint32_t n = 2; printf(\"glibc:%d\\n\", value + n); "
                  "return value + n; }\n")
        outcomes = []
        for stage in (first, second):
            stage_env = dict(clean_env, CRUNCH_CONF_FILE=str(stage / "bootstrap.conf"))
            switch = "int main(void) { switch (1) { case 1: (void)0; case 2: break; } return 0; }\n"
            for flags in ([], ["-Wcase-fall-through"], ["-Wall"]):
                result = command([stage / "crunch", "--emit-ir", *flags, "-"],
                                 input=switch, env=stage_env)
                expect(("case falls through" in result.stderr) == bool(flags),
                       f"{stage.name} incorrect fall-through warning for {flags}: {result.stderr!r}")
            for name in ("src/driver/crunch_main.c", "src/sema/sema.c",
                         "src/assembler/assembler.c", "src/linker/crunch-ld.c",
                         "src/archiver/crunch-ar.c"):
                expanded = command([stage / "crunch", "--glibc", "-E", "-I",
                                    stage / "project-headers", ROOT / name],
                                   env=stage_env, timeout=240).stdout
                markers = re.findall(r"/\*CRUNCH-PP-MAP:\d+:([0-9a-f]+)\*/", expanded)
                paths = [os.fsdecode(bytes.fromhex(marker)) for marker in markers]
                expect(not any(path.startswith(str(ROOT / "include") + os.sep) for path in paths),
                       f"{stage.name} {name} used a Crunch system header")
                expect(any(path.endswith("/stdio.h") for path in paths),
                       f"{stage.name} {name} did not use system stdio.h")
            executable = td / "program"
            compiled = command([stage / "crunch", "--glibc", "-v", "-o", executable, "-"],
                               input=source, env=stage_env, timeout=240)
            expect(str(stage / "crunch-as") in compiled.stderr,
                   f"{stage.name} did not use its own assembler")
            result = command([executable], env=stage_env, check=False)
            outcomes.append((result.returncode, result.stdout, result.stderr))
            expect(outcomes[-1] == (42, "glibc:42\n", ""),
                   f"{stage.name} glibc program failed: {outcomes[-1]!r}")
            start_obj, value_obj = td / "start.o", td / "value.o"
            command([stage / "crunch-as", "-o", start_obj], input=
                    ".text\n.globl _start\n_start: call answer\n"
                    "mov %eax,%edi\nmov $60,%eax\nsyscall\n")
            command([stage / "crunch-as", "-o", value_obj], input=
                    ".text\n.globl answer\nanswer: mov $42,%eax\nret\n")
            archive = td / (stage.name + ".a")
            command([stage / "crunch-ar", "rcs", archive, value_obj])
            command([stage / "crunch-ld", "-nostdlib", "-o", executable, start_obj, archive])
            expect(command([executable], check=False).returncode == 42,
                   f"{stage.name} self-built tools failed to link an archive")
        expect(outcomes[0] == outcomes[1], "glibc generations produced different results")

        for tool, args, text in (
                ("crunch-ir", ["--module", "-"], "int main(void) { return missing; }\n"),
                ("crunch-as", ["-o", td / "invalid.o"], ".text\ninvalid_instruction\n")):
            results = []
            for stage in (first, second):
                result = command([stage / tool, *args], input=text, env=clean_env, check=False)
                results.append((result.returncode, result.stdout, result.stderr))
                expect(result.returncode != 0 and result.stderr,
                       f"{stage.name} {tool} accepted invalid input")
            expect(results[0] == results[1],
                   f"glibc generations reported different {tool} diagnostics")


def native_integrated_bootstrap_case():
    """Build and smoke-test two complete native generations without GNU tools.

    Returns:
        None; raises AssertionError for bootstrap or executable failures.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-native-bootstrap-") as directory:
        td = pathlib.Path(directory)
        poison = td / "no-binutils"
        poison.mkdir()
        for name in ("as", "ld", "ar"):
            tool = poison / name
            tool.write_text("#!/bin/sh\necho 'unexpected GNU tool invocation' >&2\nexit 99\n")
            tool.chmod(0o755)
        env = {key: value for key, value in os.environ.items()
               if key not in ("LD_LIBRARY_PATH", "LD_PRELOAD", "LD_AUDIT",
                              "CRUNCH_INCLUDE_PATH")}
        env["PATH"] = str(poison) + os.pathsep + os.environ.get("PATH", "")
        first, second = td / "stage1", td / "stage2"
        for compiler, runtime, stage in (
                (DRIVER, BUILD / "libcrunch.a", first),
                (first / "crunch", first / "libcrunch.a", second)):
            runenv = dict(env, CRUNCH_BOOTSTRAP_COMPILER=str(compiler),
                          CRUNCH_BOOTSTRAP_RUNTIME=str(runtime))
            command([SHELL, ROOT / "tests/bootstrap-compiler.sh", "--native", stage],
                    env=runenv, timeout=1800)
            for name in ("crunch", "crunch-pp", "crunch-ir", "crunch-opt", "crunch-asm",
                         "crunch-as", "crunch-ld", "crunch-ar",
                         "libcrunch.a", "libcrunch-fallback.a", "libcrunch-support.a",
                         "libcrunch.so.1"):
                expect((stage / name).is_file(), f"{stage.name} is missing {name}")
            expect((stage / "libcrunch.so").is_symlink(),
                   f"{stage.name} shared runtime link is missing")
            expect((stage / "lib-native/parse_real.o").is_file() and
                   (stage / "lib-fallback-native/fallback_open.o").is_file(),
                   f"{stage.name} did not build its own runtime objects")
            for flag in ("--static", "--dynamic"):
                exe = td / (stage.name + flag)
                stage_env = dict(env, CRUNCH_CONF_FILE=str(stage / "bootstrap.conf"))
                result = command([stage / "crunch", "-v", flag,
                                  FIXTURES / "ir/main42.bc", "-o", exe],
                                 env=stage_env, timeout=120)
                expect(str(stage / "crunch-as") in result.stderr and
                       str(stage / "crunch-ld") in result.stderr,
                       f"{stage.name} did not use its own native tools")
                runenv = {key: value for key, value in stage_env.items()
                          if key not in ("LD_LIBRARY_PATH", "LD_PRELOAD", "LD_AUDIT")}
                expect(command([exe], cwd="/", env=runenv, check=False).returncode == 42,
                       f"{stage.name} {flag} executable failed")
        native_bootstrap_corpus_case((first, second), td, env)


def compiler_stages_bootstrap_case():
    """Build two generations of the core compiler and compare their behavior.

    Returns:
        None; raises AssertionError for compilation or behavior differences.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-bootstrap-stages-") as td:
        root = pathlib.Path(td)
        first = root / "stage1"
        second = root / "stage2"
        first_build = command([SHELL, ROOT / "tests/bootstrap-compiler.sh", first],
                              env=dict(os.environ, CRUNCH_BOOTSTRAP_COMPILER=str(DRIVER),
                                       CRUNCH_BOOTSTRAP_RUNTIME=str(BUILD / "libcrunch.a")),
                              timeout=1200)
        second_build = command([SHELL, ROOT / "tests/bootstrap-compiler.sh", second],
                               env=dict(os.environ, CRUNCH_BOOTSTRAP_COMPILER=str(first / "crunch"),
                                        CRUNCH_BOOTSTRAP_RUNTIME=str(first / "libcrunch.a")),
                               timeout=1200)
        expect("case falls through" not in first_build.stderr + second_build.stderr,
               "bootstrap emitted default fall-through warnings")
        config = root / "empty.conf"
        config.write_text("")
        temporary = root / "temp"
        temporary.mkdir()
        env = dict(os.environ, CRUNCH_CONF_FILE=str(config), TMPDIR=str(temporary))
        stages = (first, second)
        for args, text in (
                (["-"], "#define A(x) ((x)+1)\nint x=A(3);\n"),
                (["-"], "#define PAIR(x,y) x + y\nint x = PAIR(1);\n"),
                (["-"], '#include "missing-bootstrap.h"\n')):
            baseline = command([PP, *args], input=text, check=False, env=env)
            for stage in stages:
                actual = command([stage / "crunch-pp", *args], input=text, check=False, env=env)
                expect((actual.returncode, actual.stdout, actual.stderr) ==
                       (baseline.returncode, baseline.stdout, baseline.stderr),
                       f"{stage.name} preprocessor differs for {args}: {actual.stderr!r}")
        for source in (ROOT / "src/driver/asm_main.c",
                       FIXTURES / "units/library/allocator.bc",
                       FIXTURES / "units/expressions/power_runtime.bc",
                       FIXTURES / "units/structures/whole_structure_assignment.bc"):
            preprocessed = command([PP, "-D_Thread_local=", "-I", ROOT / "include",
                                    source], timeout=120).stdout
            baseline = command([IR, "--module", "-"], input=preprocessed, check=False, timeout=120)
            host_asm = command([ASM, "-"], input=baseline.stdout, check=False, timeout=120)
            expect(baseline.returncode == 0 and host_asm.returncode == 0,
                   f"host compiler failed for {source}: {baseline.stderr} {host_asm.stderr}")
            for stage in stages:
                actual = command([stage / "crunch-ir", "--module", "-"],
                                 input=preprocessed, check=False, timeout=120)
                expect((actual.returncode, actual.stdout, actual.stderr) ==
                       (baseline.returncode, baseline.stdout, baseline.stderr),
                       f"{stage.name} IR generator differs for {source}: {actual.stderr!r}")
                self_asm = command([stage / "crunch-asm", "-"], input=actual.stdout,
                                   check=False, timeout=120)
                expect((self_asm.returncode, self_asm.stdout, self_asm.stderr) ==
                       (host_asm.returncode, host_asm.stdout, host_asm.stderr),
                       f"{stage.name} backend differs for {source}: {self_asm.stderr!r}")
        invalid_source = "int main(void) { return missing_variable; }\n"
        baseline = command([IR, "--module", "-"], input=invalid_source, check=False)
        expect(baseline.returncode != 0, "host IR generator accepted invalid source")
        for stage in stages:
            actual = command([stage / "crunch-ir", "--module", "-"],
                             input=invalid_source, check=False)
            expect((actual.returncode, actual.stdout, actual.stderr) ==
                   (baseline.returncode, baseline.stdout, baseline.stderr),
                   f"{stage.name} frontend diagnostic differs: {actual.stderr!r}")
        for text in ("CRUNCH-IR 35\nfunc f 0 int\nlocalblock b 16777217 8\npush 0\nret int\nend\n",
                     "CRUNCH-IR 35\nfunc f 0 int\npush 0\njmp L+\nret int\nend\n"):
            host = command([ASM, "--validate", "-"], input=text, check=False)
            expect(host.returncode != 0, "host backend accepted invalid IR")
            for stage in stages:
                actual = command([stage / "crunch-asm", "--validate", "-"], input=text, check=False)
                expect((actual.returncode, actual.stdout, actual.stderr) ==
                       (host.returncode, host.stdout, host.stderr),
                       f"{stage.name} backend diagnostic differs: {actual.stderr!r}")
        executable = root / "fixture"
        for stage in stages:
            for source in (FIXTURES / "units/library/allocator.bc",
                           FIXTURES / "units/structures/whole_structure_assignment.bc"):
                command([stage / "crunch", "--static", "-I", ROOT / "include",
                         source, "-o", executable], env=env, timeout=240)
                result = command([executable], check=False)
                expect(result.returncode == 42,
                       f"{stage.name} compiler output failed for {source}: {result.returncode}")
        third_main = root / "third-main.o"
        command([second / "crunch", "-D_Thread_local=", "-I", ROOT / "include", "-c",
                 ROOT / "src/driver/asm_main.c", "-o", third_main], env=env, timeout=240)
        third_asm = root / "third-asm"
        objects = second / "objects"
        command([second / "crunch", "--static", third_main, objects / "src_common_diagnostic.c.o",
                 objects / "src_codegen_x86_64.c.o", "-o", third_asm], env=env, timeout=240)
        sample = "CRUNCH-IR 35\nfunc f 0 int\npush 0\nret int\nend\n"
        host = command([ASM, "--validate", "-"], input=sample, check=False)
        actual = command([third_asm, "--validate", "-"], input=sample, check=False)
        expect((actual.returncode, actual.stdout, actual.stderr) ==
               (host.returncode, host.stdout, host.stderr), "third-generation backend driver differs")
        expect(not list(temporary.iterdir()), "self-built driver left temporary files")


def backend_scanner_case():
    """Compare the IR scanner's supported formats with the host C library.

    Returns:
        None; raises AssertionError for a mismatch.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-ir-scan-") as td:
        executable = pathlib.Path(td) / "scanner"
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Wpedantic", "-Werror",
                 "-iquote", ROOT / "include", ROOT / "tests/unit/codegen/test_scan.c",
                 ROOT / "src/common/diagnostic.c", "-o", executable])
        command([executable])


def stdout_helpers_case():
    """Check standard-output helpers and their failure and linkage behavior.

    Returns:
        None; raises AssertionError for incorrect output, errors, or linkage.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-stdout-helpers-") as td:
        directory = pathlib.Path(td)
        source, obj, exe = directory / "main.bc", directory / "main.o", directory / "main"
        source.write_text('''#include <stdio.h>
#include <unistd.h>
#include <errno.h>
int main() {
    if (puts("hello") < 0 || puts("") < 0 || putchar(321) != 65) return 1;
    if (close(1) != 0) return 2;
    if (putchar('X') != EOF || !ferror(stdout) || errno != EBADF) return 3;
    clearerr(stdout);
    if (puts("bad") != EOF || !ferror(stdout) || errno != EBADF) return 4;
    return 0;
}
''')
        command([DRIVER, "-c", source, "-o", obj])
        for flags, input_file in ((["--static"], source), (["--static"], obj),
                                  (["--dynamic"], obj), (["-pie"], obj)):
            command([DRIVER, *flags, input_file, "-o", exe])
            result = command([exe], check=False, env=dict(os.environ, LD_LIBRARY_PATH=str(BUILD)))
            expect(result.returncode == 0 and result.stdout == "hello\n\nA",
                   f"stdout helpers failed for {flags}: {result.returncode} {result.stdout!r}")
        source.write_text('''#include <stdio.h>
#include <errno.h>
int main() {
    if (puts("X") != EOF || !ferror(stdout) || errno != ENOSPC) return 1;
    return 0;
}
''')
        stub, stub_obj = directory / "partial.s", directory / "partial.o"
        stub.write_text('.text\n.globl __crunch_write\n__crunch_write:\n'
                        ' cmpb $0, seen(%rip)\n jne 1f\n'
                        ' movb $1, seen(%rip)\n mov %rdx, %rax\n ret\n'
                        '1: movl $28, errno(%rip)\n mov $-1, %rax\n ret\n'
                        '.bss\nseen: .byte 0\n.section .note.GNU-stack,"",@progbits\n')
        command([TEST_AS, "-o", stub_obj, stub])
        command([DRIVER, "-c", source, "-o", obj])
        command([DRIVER, "--static", obj, stub_obj, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "puts did not report a failed newline after writing the string")
        source.write_text('''#include <stdio.h>
int puts(const char *s) { return s[0]; }
int putchar(int c) { return c + 1; }
int main() { return puts("A") != 65 || putchar(1) != 2; }
''')
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "user-defined output helpers were intercepted")


