def c_keyword_names_case():
    """Check C keyword spellings and the renamed nonreturning runtime call.

    Returns:
        None; raises AssertionError for incorrect parsing or execution.
    """
    source = FIXTURES / "units/types/c_keyword_names.bc"
    with tempfile.TemporaryDirectory(prefix="crunch-c-keywords-") as directory:
        td = pathlib.Path(directory)
        obj, exe = td / "main.o", td / "program"
        command([DRIVER, "-c", source, "-o", obj])
        for flags in (["--static"], ["--dynamic"], ["-pie"]):
            for input_file in (source, obj):
                command([DRIVER, *flags, input_file, "-o", exe])
                result = command([exe], check=False)
                expect(result.returncode == 42,
                       f"C keyword executable failed for {flags}: {result.returncode} {result.stderr}")
        for name in ("byte", "real"):
            result = command([IR, "-"], input=f"{name} value; int main() {{ return 0; }}\n",
                             check=False)
            expect(result.returncode != 0, f"obsolete type keyword {name} was accepted")
        for version, call in ((2, "call"), (3, "runtime_call")):
            for name in ("end", "exit"):
                ir = f"CRUNCH-IR {version}\nfunc main 0 int\npush 37\n{call} {name} 1\nend\n"
                assembly = command([ASM, "-"], input=ir).stdout
                expect(f"call __crunch_{name}" in assembly, f"IR {name} call was not preserved")
                asm = td / "legacy.s"
                asm.write_text(assembly)
                command([TEST_AS, "-o", obj, asm])
                command([*TEST_LINK, "-o", exe, obj, LIBCRUNCH])
                expect(command([exe], check=False).returncode == 37,
                       f"IR {name} call did not terminate with the expected status")
                invalid_ir = ir.replace("push 37", "pushr 0x3ff0000000000000")
                expect(command([ASM, "-"], input=invalid_ir, check=False).returncode != 0,
                       f"IR {name} accepted a non-integer exit status")


def syscall_prototype_case():
    """Compare syscall declarations and target type widths with GNU libc.

    Returns:
        None; raises AssertionError for mismatched declarations or type widths.
    """
    source = FIXTURES / "units/library/syscall_prototypes.bc"
    with tempfile.TemporaryDirectory(prefix="crunch-syscall-prototypes-") as directory:
        td = pathlib.Path(directory)
        obj, exe = td / "source.o", td / "program"
        if ("CS_GNU_LIBC_VERSION" in os.confstr_names and
                os.confstr("CS_GNU_LIBC_VERSION")):
            command(["cc", "-D_GNU_SOURCE", "-std=c11", "-Werror", "-fsyntax-only",
                     "-x", "c", source])
        command([DRIVER, "-c", source, "-o", obj])
        command([DRIVER, "--static", obj, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "syscall typedefs have unexpected Linux x86-64 sizes")
        expanded = command([DRIVER, "-E", source]).stdout
        mismatch = expanded.replace("extern ssize_t read(int, void*, size_t);",
                                    "extern ssize_t read(int, char*, size_t);")
        expect(mismatch != expanded and
               command([IR, "--module", "-"], input=mismatch, check=False).returncode != 0,
               "conflicting syscall prototype was accepted")
        fixed = td / "fixed.bc"
        fixed.write_text("""#include <fcntl.h>
#include <sys/mman.h>
extern int open(const char*, int, mode_t);
extern int openat(int, const char*, int, mode_t);
extern void* mremap(void*, size_t, size_t, int, void*);
int main(void) { return 0; }
""")
        command([DRIVER, "-c", fixed, "-o", obj])


def syscall_process_case():
    """Exercise descriptor, readiness, and process syscalls through the runtime.

    Returns:
        None; raises AssertionError for incorrect ABI, results, or linkage.
    """
    source = FIXTURES / "units/library/syscall_process.bc"
    helper = FIXTURES / "units/library/syscall_wait_child.s"
    with tempfile.TemporaryDirectory(prefix="crunch-syscall-process-") as directory:
        td = pathlib.Path(directory)
        obj, asm, exe = td / "main.o", td / "main.s", td / "program"
        standalone = td / "standalone.bc"
        standalone.write_text("#include <unistd.h>\n#include <fcntl.h>\n#include <sys/stat.h>\n#include <dirent.h>\n#include <stdio.h>\n#include <stdlib.h>\n"
                              "int main() { int fds[2]; "
                              "if (getpid() <= 0 || pipe(&fds[0]) != 0) return 1; "
                              "if (close(fds[0]) != 0 || close(fds[1]) != 0) return 2; "
                              "return 42; }\n")
        conf = td / "crunch.conf"
        env = {key: value for key, value in os.environ.items()
               if key not in ("LD_PRELOAD", "LD_LIBRARY_PATH", "LD_AUDIT")}
        env["CRUNCH_CONF_FILE"] = str(conf)
        assemblers = ("crunch",) if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1" else ("crunch", "gnu")
        for assembler in assemblers:
            conf.write_text(f"assembler = {assembler}\nlinker = crunch\n")
            preprocessed = command([DRIVER, "-E", source], env=env).stdout
            ir = command([IR, "--module", "-"], input=preprocessed).stdout
            for entry in ("globalblock poll_layout 8 4\n",
                          "globalalias poll_layout__events_low poll_layout 4 byte\n",
                          "globalalias poll_layout__events_high poll_layout 5 byte\n",
                          "globalalias poll_layout__revents_low poll_layout 6 byte\n",
                          "globalalias poll_layout__revents_high poll_layout 7 byte\n",
                          "globalblock time_layout 16 8\n"):
                expect(entry in ir, f"incorrect Linux syscall structure layout: {entry!r}")
            command([DRIVER, "-c", source, "-o", obj], env=env)
            command([DRIVER, "-S", standalone, "-o", asm], env=env)
            for flags in (["--static"], ["--dynamic"], ["-pie"]):
                for input_file in (source, obj):
                    command([DRIVER, *flags, input_file, helper, "-o", exe], env=env)
                    result = command([exe], cwd=td, env=env, check=False)
                    expect(result.returncode == 42,
                           f"{assembler} syscall failure for {flags} {input_file.name}: "
                           f"{result.returncode} {result.stderr}")
                command([DRIVER, *flags, asm, "-o", exe], env=env)
                result = command([exe], cwd=td, env=env, check=False)
                expect(result.returncode == 42,
                       f"{assembler} standalone syscall failure for {flags}: {result.stderr}")


def syscall_file_case():
    """Test raw and C-style Linux file syscalls in both compilation modes.

    Returns:
        None; raises AssertionError for incorrect results, ABI, or linkage.
    """
    source = FIXTURES / "units/library/syscall_file.bc"
    with tempfile.TemporaryDirectory(prefix="crunch-syscall-file-") as td:
        directory = pathlib.Path(td)
        obj, exe = directory / "program.o", directory / "program"
        expanded = command([PP, "-I", ROOT / "include", source]).stdout
        ir = command([IR, "-"], input=expanded).stdout
        fields = {
            "st_dev": (0, "long"), "st_ino": (8, "long"), "st_nlink": (16, "long"),
            "st_mode": (24, "int"), "st_uid": (28, "int"), "st_gid": (32, "int"),
            "_padding": (36, "int"), "st_rdev": (40, "long"), "st_size": (48, "long"),
            "st_blksize": (56, "long"), "st_blocks": (64, "long"),
            "st_atime": (72, "long"), "st_atime_nsec": (80, "long"),
            "st_mtime": (88, "long"), "st_mtime_nsec": (96, "long"),
            "st_ctime": (104, "long"), "st_ctime_nsec": (112, "long"),
            "_reserved0": (120, "long"), "_reserved1": (128, "long"),
            "_reserved2": (136, "long"),
        }
        expect("globalblock global_info 144 8\n" in ir, "incorrect stat buffer size")
        for field, (offset, kind) in fields.items():
            expect(f"globalalias global_info__{field} global_info {offset} {kind}\n" in ir,
                   f"incorrect stat offset or type for {field}")
        for separate in (False, True):
            if separate:
                command([DRIVER, "-c", source, "-o", obj])
                command([DRIVER, obj, "-o", exe])
