def errno_case():
    """Check writable shared errno and C-style file I/O failure reporting.

    Returns:
        None; raises AssertionError for incorrect errno, return values, or linkage.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-errno-") as td:
        directory = pathlib.Path(td)
        source = directory / "errno.bc"
        source.write_text(f'''#include <errno.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <dirent.h>
#include <stdio.h>
int fail_close() {{ return (int)file_close(-1); }}
int main() {{
  if (errno != 0) return 1;
  int *saved = &errno;
  errno = ERANGE;
  long fd = file_open("{directory}/data", FILE_WRITE);
  if (fd < 0 || errno != ERANGE) return 2;
  char text[] = "ok";
  if (file_write(fd, text, 2) != 2 || errno != ERANGE) return 3;
  if (file_close(fd) != 0 || errno != ERANGE) return 4;
  errno = 0;
  if (file_open("{directory}/absent", FILE_READ) != -1 || errno != ENOENT) return 5;
  if (*saved != ENOENT || &errno != saved) return 6;
  if (file_read(-1, text, 1) != -1 || errno != EBADF) return 7;
  errno = 0;
  if (file_write(-1, text, 1) != -1 || errno != EBADF) return 8;
  errno = 0;
  if (fail_close() != -1 || errno != EBADF) return 9;
  if (file_open("{directory}", FILE_WRITE) != -1 || errno != EISDIR) return 10;
  fd = file_open("{directory}/data", FILE_READ);
  if (fd < 0 || errno != EISDIR) return 11;
  if (file_read(fd, 0, 1) != -1 || errno != EFAULT) return 12;
  if (file_read(fd, text, 2) != 2 || errno != EFAULT) return 13;
  if (file_read(fd, text, 2) != 0 || errno != EFAULT) return 14;
  if (file_close(fd) != 0 || errno != EFAULT) return 15;
  fd = file_open("/dev/full", FILE_WRITE);
  if (fd < 0) return 16;
  if (file_write(fd, text, 2) != -1 || errno != ENOSPC) return 17;
  file_close(fd);
  errno = 0;
  if (*saved != 0) return 18;
  return 42;
}}
''')
        program = directory / "errno"
        command([DRIVER, source, "-o", program])
        result = command([program], check=False)
        expect(result.returncode == 42,
               f"errno regression failed at check {result.returncode}: {result.stderr}")


def internal_errno_location_case():
    """Check internal assembly access to the shared runtime errno storage.

    Returns:
        None; raises AssertionError for incorrect linkage or storage behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-internal-errno-") as td:
        directory = pathlib.Path(td)
        source, obj, program = directory / "check.s", directory / "check.o", directory / "check"
        source.write_text('''.text
.globl _start
_start:
    call _crunch_errno_location
    lea errno(%rip), %rcx
    cmp %rcx, %rax
    jne failure
    cmpl $0, (%rax)
    jne failure
    movl $34, (%rax)
    call __crunch___errno_location
    lea errno(%rip), %rcx
    cmp %rcx, %rax
    jne failure
    cmpl $34, (%rax)
    jne failure
    movl $7, errno(%rip)
    call _crunch_errno_location
    cmpl $7, (%rax)
    jne failure
    mov $-9, %rax
    call __crunch_syscall_result
    cmp $-1, %rax
    jne failure
    call _crunch_errno_location
    cmpl $9, (%rax)
    jne failure
    mov $42, %edi
    jmp done
failure:
    mov $1, %edi
done:
    mov $60, %eax
    syscall
.section .note.GNU-stack,"",@progbits
''')
        command([TEST_AS, "-o", obj, source])
        command([*TEST_LINK, "-o", program, obj, LIBCRUNCH])
        result = command([program], check=False)
        expect(result.returncode == 42,
               f"internal errno accessor failed with status {result.returncode}")

def external_globals_case():
    """Exercise external storage, address identity, errno, and invalid declarations.

    Returns:
        None; raises AssertionError for incorrect compilation, execution, or validation.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-extern-globals-") as directory:
        td = pathlib.Path(directory)
        main, helper, definitions = (td / name for name in ("main.c", "helper.c", "values.c"))
        main.write_text('''#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <dirent.h>
#include <stdio.h>
extern int number, other;
extern int number;
extern char small;
extern long big;
extern double fraction;
extern int *pointer;
int update();
int *err_address();
int main() {
  if (&errno != __errno_location() || &errno != err_address()) return 1;
  errno = 0;
  if (file_close(-1) != -1 || errno != EBADF) return 2;
  if (update() != 42 || number != 41 || other != 1) return 3;
  if (small != 7 || big != 99 || fraction != 2.5 || *pointer != 41) return 4;
  if (errno != ERANGE) return 5;
  if (&pointer != &pointer) return 6;
  return 42;
}
''')
        helper.write_text('''extern int number, other;
extern char small;
extern long big;
extern double fraction;
extern int *pointer;
extern int errno;
int *err_address() { return &errno; }
int update() {
  number = 41; other = 1; small = (char)7; big = 99; fraction = 2.5;
  pointer = &number; errno = 34;
  return number + other;
}
''')
        definitions.write_text('''extern int number;
int number;
extern int number;
int other;
char small;
long big;
double fraction;
int *pointer;
''')
        exe = td / "program"
        objects = [td / f"{i}.o" for i in range(3)]
        for source, obj in zip((main, helper, definitions), objects):
            command([DRIVER, "-c", "-o", obj, source])
        tree = json.loads(source_parse(helper).stdout)
        variables = [d for d in tree["declarations"] if d["kind"] == "variable"]
        expect(len(variables) == 7 and all(d["extern"] for d in variables),
               "AST did not preserve extern on every variable declarator")
        tree = json.loads(source_parse(definitions).stdout)
        variables = [d for d in tree["declarations"] if d["kind"] == "variable"]
        expect(variables[0]["extern"] and not variables[1]["extern"] and
               variables[2]["extern"], "AST extern declaration flags are incorrect")
        combined = td / "combined.o"
        command([DRIVER, "-c", "-o", combined, *objects])
        for inputs in ((main, helper, definitions), tuple(objects), (combined,)):
            command([DRIVER, "-o", exe, *inputs])
            result = command([exe], check=False)
            expect(result.returncode == 42, f"external globals failed: {inputs}: {result.returncode}")
        missing = command([DRIVER, "-o", exe, objects[0], objects[1]], check=False)
        expect(missing.returncode != 0 and missing.stderr.strip(),
               "missing external global definitions linked successfully")

        single = td / "single.c"
        single.write_text('''extern int errno;
int main() { errno = 42; return *(&errno); }
''')
        command([DRIVER, "-o", exe, single])
        expect(command([exe], check=False).returncode == 42,
               "standalone extern errno failed")
        for declarations in ("extern int value; int value = 42; extern int value;",
                             "int value = 42; extern int value;"):
            single.write_text(declarations + " int main() { return value; }\n")
            command([DRIVER, "-o", exe, single])
            expect(command([exe], check=False).returncode == 42,
                   f"declaration and definition did not reconcile: {declarations}")
        for source in (
            "dim extern int x[4]; int main() { return 0; }",
            "extern void x; int main() { return 0; }",
            "extern int x; extern long x; int main() { return 0; }",
            "extern const int x; int x; int main() { return 0; }",
            "extern int x; static int x; int main() { return 0; }",
            "extern int x; int x(); int main() { return 0; }",
        ):
            result = command([IR, "--module", "-"], input=source, check=False)
            expect(result.returncode != 0 and result.stderr.strip() and not result.stdout,
                   f"invalid external global accepted: {source}")
        for directive in (
            "extern_global value\n", "extern_global value void\n",
            "extern_global value int extra\n", "extern_global 1bad int\n",
            "extern_global value int\nextern_global value ptr\n",
            "global value long 0\nextern_global value int\n",
            "extern_global value int\ninternal value\n",
            "extern_global value int\nextern_func value 0 int\n",
            "extern_global value int\nglobalblock value 4 4\n",
            "extern_global value int\nglobal value int 0\nglobal value int 0\n",
        ):
            result = command([ASM, "-"], input="CRUNCH-IR 3\n" + directive, check=False)
            expect(result.returncode != 0 and result.stderr.strip() and not result.stdout,
                   f"invalid external global IR accepted: {directive}")
        for instruction in ("gload missing int", "gaddr missing"):
            text = f"CRUNCH-IR 3\nfunc main 0 int\n{instruction}\ndrop\npush 0\nret int\nend\n"
            result = command([ASM, "-"], input=text, check=False)
            expect(result.returncode != 0 and result.stderr.strip() and not result.stdout,
                   f"undeclared global reference accepted: {instruction}")
        for instruction in ("gload value long", "gstore value ptr", "gaddr missing"):
            text = ("CRUNCH-IR 3\nextern_global value int\n"
                    "func main 0 int\npush 0\nret int\n" + instruction + "\nend\n")
            result = command([ASM, "-"], input=text, check=False)
            expect(result.returncode != 0 and result.stderr.strip() and not result.stdout,
                   f"invalid unreachable global reference accepted: {instruction}")


def file_scope_visibility_case():
    """Check declaration order and the visible composite type at each use.

    Returns:
        None; raises AssertionError for incorrect visibility or execution.
    """
    invalid = (
        "int f(void) { return x; } int x = 42;",
        "int f(void) { return g(); } int g(void) { return 42; }",
        "int *p = &x; int x;",
        "int a[]; int f(void) { return sizeof(a); } int a[4];",
        "extern int a[]; int f(void) { return sizeof(a); } extern int a[4];",
        "int a[]; int f(void) { extern int a[]; return sizeof(a); } int a[4];",
        "int f(void) { extern long x; return 0; } int x;",
        "int f(void) { int g(long); return 0; } int g(int x) { return x; }",
        "int f(void) { extern int x; return x; } static int x;",
        "int f(void) { int g(void); return g(); } static int g(void) { return 1; }",
    )
    with tempfile.TemporaryDirectory(prefix="crunch-file-visibility-") as directory:
        td = pathlib.Path(directory)
        source, exe = td / "source.c", td / "program"
        for text in invalid:
            result = command([IR, "--module", "-"], input=text, check=False)
            expect(result.returncode != 0 and result.stderr.strip() and not result.stdout,
                   f"invalid declaration visibility accepted: {text}")
            source.write_text(text)
            command([SEMA, source, "expect-error-repeat"])
        source.write_text('''extern int data[];
int before(void) { return data[1]; }
extern int data[4];
int after(void) { return sizeof(data); }
int data[] = {1, 2};
int block_size(void) { extern int data[]; return sizeof(data); }
int recursive(int n) { return n ? recursive(n - 1) : 20; }
int call_later(void) { int later(int); return later(4); }
int later(int n) { return n + 4; }
int putchar(int);
int call_putchar(void) { int (*fn)(int) = putchar; return fn(1); }
int putchar(int n) { return n + 1; }
int get_value(void) { extern int value; return value; }
int value = 12;
int main(void) {
    return before() + after() + block_size() + recursive(1) + call_later() +
           call_putchar() + get_value() == 76 ? 42 : 1;
}
''')
        for flags in (["--static"], ["--dynamic"], ["-pie"]):
            command([DRIVER, *flags, source, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"visible declarations produced incorrect output with {flags}")


