def strtoul_case():
    """Check unsigned conversion, IR compatibility, and the C runtime ABI.

    Returns:
        None; raises AssertionError for incorrect conversion or IR behavior.
    """
    fixture = FIXTURES / "units/library/strtoul.bc"
    with tempfile.TemporaryDirectory(prefix="crunch-strtoul-") as directory:
        td = pathlib.Path(directory)
        exe, obj = td / "program", td / "program.o"
        command([DRIVER, fixture, "-o", exe])
        expect(command([exe], check=False).returncode == 42, "strtoul executable failed")
        command([DRIVER, "-c", fixture, "-o", obj])
        command([DRIVER, obj, "-o", exe])
        expect(command([exe], check=False).returncode == 42, "strtoul module failed")
        source = td / "signed.bc"
        for initializer in (False, True):
            source.write_text("#include <stdlib.h>\n" +
                              ("int values[1] = {1};\n"
                               if initializer else "") +
                              "int main() { char x = (char)255; return x + 1; }\n")
            for module in (False, True):
                expanded = command([PP, source]).stdout
                ir = command([IR, *(["--module"] if module else []), "-"],
                             input=expanded).stdout
                version = (13 if initializer else 3) if module else (12 if initializer else 2)
                expect(ir.startswith(f"CRUNCH-IR {version}\n"),
                       f"unused unsigned runtime prototype changed IR: {ir}")
            command([DRIVER, source, "-o", exe])
            with_header = command([exe], check=False).returncode
            expect("__crunch_strtoul" not in command(["nm", exe]).stdout,
                   "unused strtoul runtime was linked")
            source.write_text(source.read_text().replace("#include <stdlib.h>\n", ""))
            command([DRIVER, source, "-o", exe])
            expect(command([exe], check=False).returncode == with_header,
                   "including stdlib changed signed-only execution")
        expanded = command([PP, fixture]).stdout
        for module in (False, True):
            ir = command([IR, *(["--module"] if module else []), "-"],
                         input=expanded).stdout
            expect(ir.startswith(f"CRUNCH-IR {7 if module else 6}\n") and
                   "call strtoul 3\n" in ir,
                   f"strtoul call did not select unsigned IR: {ir}")
        source.write_text('#include <stdlib.h>\nint main() {'
                          ' if (strtoul("1", 0, 10)) return 42; return 0; }\n')
        expanded = command([PP, source]).stdout
        for module in (False, True):
            ir = command([IR, *(["--module"] if module else []), "-"],
                         input=expanded).stdout
            expect(ir.startswith(f"CRUNCH-IR {7 if module else 6}\n"),
                   f"unsigned runtime result did not select unsigned IR: {ir}")
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "strtoul call without unsigned syntax failed")
        for declaration in ("int strtoul(int x) { return x; }",
                            "extern int strtoul(int x);"):
            text = declaration + " int main() { return strtoul(42); }\n"
            for module in ((True,) if declaration.startswith("extern") else (False, True)):
                ir = command([IR, *(["--module"] if module else []), "-"],
                             input=text).stdout
                version = 39 if module and declaration.startswith("extern") else (3 if module else 2)
                expect(ir.startswith(f"CRUNCH-IR {version}\n") and
                       "call strtoul 1\n" in ir and "runtime_call strtoul" not in ir,
                       f"ordinary strtoul linkage changed: {ir}")
                command([ASM, "-"], input=ir)
        source.write_text("int strtoul(int x) { return x; }"
                          " int main() { return strtoul(42); }\n")
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "user-defined strtoul did not use ordinary linkage")
        other = td / "other.bc"
        other.write_text("int strtoul(int x) { return x; }\n")
        source.write_text("extern int strtoul(int x); int main() { return strtoul(42); }\n")
        command([DRIVER, source, other, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "external strtoul did not use ordinary linkage")
        for used in (False, True):
            text = ("char* malloc(unsigned long value); int main() { " +
                    ("malloc(1); " if used else "") + "return 0; }\n")
            ir = command([IR, "-"], input=text).stdout
            expect(ir.startswith(f"CRUNCH-IR {6 if used else 2}\n"),
                   f"unsigned runtime parameter selected the wrong IR: {ir}")
        result = command([IR, "-"], input="unsigned long strtoul(struct Missing p[2]);"
                         " int main() { return 0; }\n", check=False)
        expect(result.returncode != 0 and "array parameter requires a complete element type" in result.stderr,
               "unused runtime prototype skipped type validation")
        helper = td / "helper.bc"
        helper.write_text('#include <stdlib.h>\nunsigned long parse() {'
                          ' return strtoul("42!", 0, 10); }\n')
        source.write_text("extern unsigned long parse(); int main() {"
                          " if (parse() == 42UL) return 42; return 1; }\n")
        command([DRIVER, "-c", helper, "-o", obj])
        command([DRIVER, source, obj, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "separately compiled strtoul call failed")
        for call in ('strtoul("1", 0)', 'strtoul(1, 0, 10)',
                     'strtoul("1", 1.5, 10)'):
            source.write_text("#include <stdlib.h>\nint main() { " + call + "; return 0; }\n")
            result = command([DRIVER, "--emit-ir", source], check=False)
            expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
                   f"invalid strtoul source call accepted: {call}")
        for version in (2, 3, 4, 5):
            op = "runtime_call" if version in (3, 4) else "call"
            init = ("internal setup\ninitializer setup\nfunc setup 0 int\n"
                    "push 0\nret int\nend\n" if version in (4, 5) else "")
            text = (f"CRUNCH-IR {version}\n{init}func main 0 int\npush 0\npush 0\npush 10\n"
                    f"{op} strtoul 3\nret int\nend\n")
            result = command([ASM, "-"], input=text, check=False)
            expect(result.returncode != 0 and "unknown" in result.stderr,
                   f"legacy IR v{version} accepted strtoul: {result.stderr}")
        for version, op in ((6, "call"), (7, "runtime_call")):
            for args in ("pushr 0x3ff0000000000000\npush 0\npush 10\n",
                         "push 0\npushr 0x3ff0000000000000\npush 10\n",
                         "push 0\npush 0\npushr 0x3ff0000000000000\n",
                         "push 0\npush 0\n"):
                text = (f"CRUNCH-IR {version}\nfunc main 0 int\n{args}"
                        f"{op} strtoul {2 if args.count('push') == 2 else 3}\n"
                        "drop\npush 0\nret int\nend\n")
                result = command([ASM, "-"], input=text, check=False)
                expect(result.returncode != 0 and "strtoul" in result.stderr,
                       f"invalid strtoul IR accepted: {text}")
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Werror",
                 FIXTURES / "units/library/strtoul_differential.c",
                 BUILD / "lib/strtoul.o", BUILD / "lib/strtol.o",
                 BUILD / "lib/parse_integer.o", "-o", exe])
        command([exe])

