def null_pointer_case():
    """Check null pointer constants, initialization, comparisons, and invalid mixing.

    Returns:
        None; raises AssertionError for incorrect null semantics or execution.
    """
    source_text = r'''char* strchr(char* text, int value);
char *global_bytes = (char*)0;
    int *global_numbers = (int*)(65536 * 65536);
struct node { int *next; };
int *null_return() { return (int*)0; }
int is_null(int *value) { return value == 0; }
int main() {
  char *found = strchr("abc", 'z');
  if (found != 0) return 1;
  if (0 != found) return 2;
  if (!(found == 0)) return 3;
  if ((char*)0 != found) return 16;
  if (found != (char*)0) return 17;
  if ((char*)0 != 0 || 0 != (char*)0) return 20;
  found = strchr("abc", 'b');
  if (found == 0) return 4;
  if (0 == found) return 5;
  int *numbers = 1 - 1;
  if (numbers != 0) return 6;
  numbers = 1 / 2;
  if (numbers != 0) return 7;
  numbers = 65536 * 65536;
  if (numbers != 0) return 23;
  numbers = 3 ^ 3;
  if (numbers != 0) return 18;
  if (!is_null(1 << 4 & 0)) return 19;
  numbers = 0 && (1 / 0);
  if (numbers != 0) return 24;
  numbers = !1;
  if (numbers != 0) return 21;
  if (null_return() != 0 || !is_null(0)) return 8;
  global_bytes = 0;
  global_numbers = 0;
  if (global_bytes != 0 || global_numbers != 0) return 9;
  int value = 10;
  numbers = 1 ? &value : (int*)0;
  if (numbers == 0 || *numbers != 10) return 10;
  numbers = 0 ? &value : 0;
  if (numbers != 0) return 11;
  struct node item;
  item.next = 0;
  if (item.next != 0) return 12;
  item.next = &value;
  if (item.next == 0) return 13;
  item.next = 0;
  if (item.next != 0) return 14;
  char buffer[1];
  if (copy(0, buffer, 0) != 0 || fill(0, 0, 0) != 0 || compare(0, buffer, 0) != 0) return 15;
  return 31;
}
'''
    with tempfile.TemporaryDirectory(prefix="crunch-null-") as td:
        source = pathlib.Path(td) / "null.bc"
        source.write_text(source_text)
        compile_run(source, 31)
        for bad in ("int main() { char *p = \"a\"; if (p == 1) return 1; return 0; }\n",
                    "int main() { char *p = \"a\"; if (p == 0.0) return 1; return 0; }\n",
                    "int main() { int *p = 1; return 0; }\n",
                    "int main() { int *p; p = 1; return 0; }\n",
                    "int main() { int *p; int zero = 0; p = zero; return 0; }\n",
                    "int main() { int *p; int zero = 0; if (p == zero) return 1; return 0; }\n",
                    "int main() { int *p; if (p == 1 + 1) return 1; return 0; }\n",
                    "int main() { int *p; p = 65536 * 65536 + 1; return 0; }\n",
                    "int main() { int *p; p = 1 / 0; return 0; }\n",
                    "int main() { int *p; p = 1 << 32; return 0; }\n",
                    "int f(int *p) { return 0; } int main() { return f(1); }\n",
                    "int *f() { return 1; } int main() { return 0; }\n"):
            source.write_text(bad)
            result = command([IR, source], check=False)
            expect(result.returncode != 0,
                   f"invalid pointer/integer use accepted: {bad!r}")

def environment_lookup_case():
    """Check env_get using an explicit process environment and absent names.

    Returns:
        None; raises AssertionError for incorrect environment lookup.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-env-") as td:
        directory = pathlib.Path(td)
        source = directory / "env.bc"
        source.write_text(
            "#include <environment.h>\n"
            "#include <string.h>\n"
            "int main(int argc, char argv[][], char envp[][]) {\n"
            "  char *value = env_get(envp, \"CRUNCH_LOOKUP_TEST\");\n"
            "  if (!value || strcmp(value, \"hello-world\") != 0) return 1;\n"
            "  if (env_get(envp, \"CRUNCH_LOOKUP_MISSING\")) return 2;\n"
            "  if (env_get(envp, \"CRUNCH_LOOKUP_PREFIX\")) return 3;\n"
            "  if (env_get(envp, \"\")) return 4;\n"
            "  if (env_get(0, \"CRUNCH_LOOKUP_TEST\")) return 5;\n"
            "  if (env_get(envp, 0)) return 6;\n"
            "  value = env_get(envp, \"CRUNCH_LOOKUP_EMPTY\");\n"
            "  if (!value || strlen(value) != 0) return 7;\n"
            "  return 42;\n"
            "}\n")
        executable = directory / "env"
        command([DRIVER, source, "-o", executable])
        env = {"CRUNCH_LOOKUP_TEST": "hello-world",
               "CRUNCH_LOOKUP_PREFIX_EXTRA": "not-a-match",
               "CRUNCH_LOOKUP_EMPTY": "",
               "": "not-a-valid-name"}
        result = command([executable], check=False, env=env)
        expect(result.returncode == 42,
               f"environment lookup returned status {result.returncode}")

def user_include_case():
    """Check quoted includes relative to user source paths and include errors.

    Returns:
        None; raises AssertionError for incorrect search behavior or diagnostics.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-userinc-") as td:
        directory = pathlib.Path(td)
        (directory / "inc/sub").mkdir(parents=True)
        (directory / "other").mkdir()
        (directory / "inc/a.h").write_text('#ifndef A_H\n#define A_H\n#include "sub/b.h"\n#endif\n')
        (directory / "inc/sub/b.h").write_text("int fromb() { return 7; }\n#include \"c.h\"\n")
        (directory / "inc/sub/c.h").write_text("int fromc() { return 5; }\n")
        source = directory / "m.bc"
        source.write_text('#include "inc/a.h"\n#include "inc/a.h"\n'
                          "int main() { return fromb() + fromc(); }\n")
        command([DRIVER, source, "-o", directory / "m"], cwd=directory / "other")
        result = command([directory / "m"], check=False)
        expect(result.returncode == 12, f"user headers gave exit status {result.returncode}")
        (directory / "libinc").mkdir()
        (directory / "libinc/lib.h").write_text("int fromlib() { return 3; }\n")
        lib = directory / "lib.bc"
        lib.write_text('#include "lib.h"\nint main() { return fromlib(); }\n')
        command([DRIVER, "-I", "libinc", lib, "-o", directory / "lib"], cwd=directory)
        result = command([directory / "lib"], check=False)
        expect(result.returncode == 3, "quoted include did not search -I directories")
        for text in ('#include "missing.h"\n', '#include "/etc/passwd"\n', '#include "a.h\n'):
            bad = directory / "bad.bc"
            bad.write_text(text)
            result = command([PP, bad], check=False)
            expect(result.returncode != 0, f"bad user include accepted: {text!r}")

def stdin_pipeline_case():
    """Check source/IR stdin pipelines and rejection of multiple input paths.

    Returns:
        None; raises AssertionError for incorrect stdin handling or execution.
    """
    tools = BUILD
    source = '#include <stdlib.h>\nint main() { exit(9); return 0; }\n'
    with tempfile.TemporaryDirectory(prefix="crunch-stdin-") as td:
        directory = pathlib.Path(td)
        expanded = command([tools / "crunch-pp"], input=source).stdout
        for args in ([], ["-"]):
            ir = command([tools / "crunch-ir", *args], input=expanded).stdout
            expect(ir.startswith("CRUNCH-IR 2"), f"crunch-ir {args} did not read standard input")
            optimized = command([tools / "crunch-opt", *args], input=ir).stdout
            expect(optimized == ir, "optimizer changed the IR")
            assembly = command([tools / "crunch-asm", *args], input=optimized).stdout
            expect("main:" in assembly, f"crunch-asm {args} did not read standard input")
        expect(command([tools / "crunch-ir", "a", "b"], check=False).returncode == 2,
               "crunch-ir accepted two input files")
        expect(command([tools / "crunch-asm", "a", "b"], check=False).returncode == 2,
               "crunch-asm accepted two input files")
        expect(command([tools / "crunch-opt", "a", "b"], check=False).returncode == 2,
               "crunch-opt accepted two input files")
        payload = b"CRUNCH-IR 2\n" + bytes(range(256)) * 100 + b"no trailing newline"
        input_file = directory / "input.bir"
        input_file.write_bytes(payload)
        for args in ([], ["-"], [str(input_file)]):
            result = subprocess.run([str(tools / "crunch-opt"), *args],
                                    input=payload if not args or args == ["-"] else None,
                                    stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=15)
            expect(result.returncode == 0 and result.stdout == payload and not result.stderr,
                   f"optimizer did not preserve bytes ({args}): {result.stderr!r}")
        selfhosted = directory / "selfhosted-opt"
        command([DRIVER, "--static", "-I", ROOT / "include",
                 ROOT / "src/driver/opt_main.c", ROOT / "src/optimizer/optimizer.c",
                 "-o", selfhosted], timeout=120)
        for args in ([], [str(input_file)]):
            result = subprocess.run([str(selfhosted), *args], input=payload if not args else None,
                                    stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=15)
            expect(result.returncode == 0 and result.stdout == payload and not result.stderr,
                   f"self-hosted optimizer did not preserve bytes: {result.stderr!r}")
        result = command([tools / "crunch-opt", directory / "missing"], check=False)
        expect(result.returncode != 0 and "crunch-opt:" in result.stderr,
               "optimizer did not report input-open failure")
        result = command([tools / "crunch-opt", directory], check=False)
        expect(result.returncode != 0 and "crunch-opt:" in result.stderr,
               "optimizer did not report input-read failure")
        with open("/dev/full", "wb") as full:
            result = subprocess.run([str(tools / "crunch-opt")], input=b"IR",
                                    stdout=full, stderr=subprocess.PIPE, timeout=15)
        expect(result.returncode != 0 and b"crunch-opt:" in result.stderr,
               "optimizer did not report output-write failure")
        result = command([DRIVER, "-v", "-S", "-"], input=source)
        expect(result.stderr.find("crunch-ir") < result.stderr.find("crunch-opt") <
               result.stderr.find("crunch-asm"), "driver optimizer stage is missing or out of order")
        result = command([DRIVER, "-v", "--emit-ir", "-"], input=source)
        expect("crunch-opt" not in result.stderr, "--emit-ir must stop before optimization")
        isolated = directory / "tools"
        isolated.mkdir()
        shutil.copy2(DRIVER, isolated / "crunch")
        for tool in ("crunch-pp", "crunch-ir", "crunch-asm"):
            (isolated / tool).symlink_to(tools / tool)
        broken = isolated / "crunch-opt"
        broken.write_text("#!/bin/sh\necho 'optimizer failed deliberately' >&2\nexit 7\n")
        broken.chmod(0o755)
        result = command([isolated / "crunch", "-S", "-"], input=source, check=False)
        expect(result.returncode != 0 and "crunch-opt" in result.stderr and
               "exit status 7" in result.stderr,
               f"driver did not propagate optimizer failure: {result.stderr}")

def driver_case():
    """Exercise driver options, version output, compile modes, and failure reporting.

    Returns:
        None; raises AssertionError for incorrect driver behavior.
    """
    version = command([DRIVER, "--version"]).stdout.splitlines()
    expect(len(version) == 3 and version[0] == "crunch 0.9.0" and
           version[1].startswith("built ") and version[2] == "Linux x86_64",
           f"unexpected --version output {version!r}")
    expect(command([ROOT / "configure", "--version"]).stdout.startswith("crunch configure 0.9.0"),
           "configure version differs from the compiler version")
    for tool in ("crunch-ar", "crunch-ld"):
        expect(command([BUILD / tool, "--version"]).stdout.strip() == f"{tool} 0.9.0",
               f"{tool} version differs from the compiler version")
    with tempfile.TemporaryDirectory(prefix="crunch-driver-") as td:
        directory = pathlib.Path(td)
        source = directory / "program.bc"
        source.write_text('#include <stdlib.h>\nint printf(const char* format); int main() { printf("ok;"); exit(37); return 0; }\n')
        program = directory / "program"
        command([DRIVER, source, "-o", program], cwd=directory)
        result = command([program], check=False)
        expect(result.returncode == 37 and result.stdout == "ok;",
               f"driver-built program exited {result.returncode} with {result.stdout!r}")

        default_build = command([DRIVER, source], cwd=directory)
        expect((directory / "a.out").exists(), "driver did not default to a.out")
        expect(command([directory / "a.out"], check=False).returncode == 37,
               "default a.out did not run correctly")

        assembly = command([DRIVER, "-S", source]).stdout
        expect(".global _start" in assembly, "-S did not write assembly to stdout")
        expect(command([DRIVER, "--emit-ir", source]).stdout.startswith("CRUNCH-IR 2"),
               "--emit-ir did not write Crunch IR")
        expect("void noreturn exit(int status);" in command([DRIVER, "-E", source]).stdout,
               "-E did not write preprocessed source")
        object_file = directory / "program.o"
        command([DRIVER, "-c", source, "-o", object_file])
        expect(object_file.read_bytes()[:4] == b"\x7fELF", "-c did not write an object file")
        glibc_source = directory / "conftest.c"
        glibc_source.write_text("int function(void) { return 1; }\n")
        command([DRIVER, "--glibc", "-c", glibc_source], cwd=directory)
        expect((directory / "conftest.o").read_bytes()[:4] == b"\x7fELF",
               "glibc mode did not name the object after its input")
        glibc_source.write_text(
            "int add(int * restrict a, int *__restrict b, int *__restrict__ c) "
            "{ *a += *b; *c += 1; return *a; }\n"
            "int main(void) { int x = 1, y = 2, z = 3; "
            "return add(&x, &y, &z) != 3 || z != 4; }\n")
        command([DRIVER, glibc_source, "-o", directory / "restrict-test"])
        expect(command([directory / "restrict-test"], check=False).returncode == 0,
               "restrict-qualified pointer parameters did not execute correctly")
        serialized = command([LEXER, glibc_source]).stdout
        expect(serialized.count("\nRESTRICT\t") == 3 and
               command([PARSER], input=serialized, check=False).returncode == 0,
               "restrict qualifiers did not survive the lexer/parser token stream")
        assembly_file = directory / "program.s"
        command([DRIVER, "-S", source, "-o", assembly_file])
        expect(".global _start" in assembly_file.read_text(), "-S -o did not write the file")

        include_dir = directory / "headers"
        include_dir.mkdir()
        (include_dir / "mine.h").write_text("int from_driver_include;\n")
        include_source = directory / "include.bc"
        include_source.write_text("#include <mine.h>\nint main() { return 3; }\n")
        missing = command([DRIVER, include_source, "-o", directory / "i"], check=False)
        expect(missing.returncode != 0 and "cannot open included header" in missing.stderr,
               "driver did not report a missing header")
        command([DRIVER, "-I", include_dir, include_source, "-o", directory / "i"])
        expect(command([directory / "i"], check=False).returncode == 3,
               "driver -I program did not run correctly")

        bad_source = directory / "bad.bc"
        bad_source.write_text("int main() { return undefined_name; }\n")
        bad_output = directory / "bad"
        bad = command([DRIVER, bad_source, "-o", bad_output], check=False)
        expect(bad.returncode == 1 and "undefined identifier" in bad.stderr and
               "expected Crunch IR" not in bad.stderr and not bad_output.exists(),
               f"driver mishandled a semantic error: {bad.stderr}")
        no_file = command([DRIVER, directory / "absent.bc"], check=False)
        expect(no_file.returncode == 1 and "cannot open source file" in no_file.stderr and
               "expected Crunch IR" not in no_file.stderr,
               f"driver mishandled a missing source file: {no_file.stderr}")
        usage = command([DRIVER], check=False)
        expect(usage.returncode == 2 and "usage: crunch" in usage.stderr,
               "driver accepted a missing source file")
        unknown = command([DRIVER, "--bogus", source], check=False)
        expect(unknown.returncode == 2 and "unknown option" in unknown.stderr,
               "driver accepted an unknown option")

def multi_input_driver_case():
    """Exercise source and object combinations, relocatable links, and failure handling.

    Returns:
        None; raises AssertionError for incorrect driver output or behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-driver-modules-") as directory:
        td = pathlib.Path(directory)
        temp = td / "temp"
        temp.mkdir()
        env = dict(os.environ, TMPDIR=str(temp))
        header = td / "shared.h"
        header.write_text("int calculate(int x);\n")
        main = td / "main.c"
        main.write_text('#include "shared.h"\n'
                        'static int private() { return 0; }\n'
                        'int printf(const char* format); int main() { printf("ok"); return calculate(VALUE) + private(); }\n')
        helper = td / "helper.c"
        helper.write_text('#include "shared.h"\nstatic int private() { return 2; }\n'
                          'int calculate(int x) { return x + private(); }\n')
        exe, main_o, helper_o, combined = (td / name for name in
                                           ("program", "main.o", "helper.o", "combined.o"))
        flags = ["-DVALUE=40", "-I", td]
        command([DRIVER, *flags, "-o", exe, main, helper], env=env)
        result = command([exe], check=False)
        expect(result.returncode == 42 and result.stdout == "ok",
               "multi-source executable produced an incorrect result")
        command([DRIVER, *flags, "-c", "-o", main_o, main], env=env)
        command([DRIVER, "-c", "-o", helper_o, helper], env=env)
        for inputs in ([main_o, helper_o], [main, helper_o], [main_o, helper]):
            command([DRIVER, *flags, "-o", exe, *inputs], env=env)
            expect(command([exe], check=False).returncode == 42,
                   f"mixed object link failed for {inputs}")
        stdin_source = "int calculate(int x); int main() { return calculate(40); }\n"
        command([DRIVER, "-o", exe, "-", helper_o], input=stdin_source, env=env)
        expect(command([exe], check=False).returncode == 42,
               "standard-input source did not link with an object")
        for inputs in ([main, helper], [main_o, helper_o], [main, helper_o]):
            command([DRIVER, *flags, "-c", "-o", combined, *inputs], env=env)
            command([DRIVER, "-o", exe, combined], env=env)
            expect(command([exe], check=False).returncode == 42,
                   f"combined relocatable object failed for {inputs}")

        duplicates = td / "duplicate.c"
        duplicates.write_text("int calculate(int x) { return x; }\n")
        bad = td / "bad.c"
        bad.write_text("int broken() { return missing; }\n")
        init = td / "initializer.c"
        init.write_text("int values[] = {1, 2}; int f() { return 0; }\n")
        for inputs in ([main, bad], [main, helper, duplicates], [helper]):
            result = command([DRIVER, *flags, "-o", exe, *inputs], env=env, check=False)
            expect(result.returncode != 0 and result.stderr.strip(),
                   f"invalid multi-input link succeeded: {inputs}")
        preserved = td / "preserved"
        preserved.write_text("unchanged")
        command([DRIVER, *flags, "-o", preserved, main, bad], env=env, check=False)
        expect(preserved.read_text() == "unchanged",
               "a compile error destroyed the existing output")
        command([DRIVER, "-c", "-o", combined, init], env=env)
        command([DRIVER, *flags, "-o", exe, main, helper, combined], env=env)
        expect(command([exe], check=False).returncode == 42,
               "initialized object failed to link with multiple sources")
        for mode in ("-E", "--emit-ir", "-S"):
            result = command([DRIVER, mode, main, helper], env=env, check=False)
            expect(result.returncode != 0 and "only one source" in result.stderr,
                   f"{mode} accepted multiple sources")
            expect(command([DRIVER, mode, helper_o], env=env, check=False).returncode != 0,
                   f"{mode} accepted an object input")
        result = command([DRIVER, "-c", "-o", "-", helper], env=env, check=False)
        expect(result.returncode != 0, "object output to stdout was accepted")
        result = command([DRIVER, "-", "-", "-o", exe], input=stdin_source, env=env, check=False)
        expect(result.returncode != 0 and "only once" in result.stderr,
               "driver accepted repeated standard input")
        original = helper.read_text()
        result = command([DRIVER, "-c", "-o", helper, helper], env=env, check=False)
        expect(result.returncode != 0 and helper.read_text() == original,
               "driver overwrote its input")
        alias = td / "alias.c"
        alias.symlink_to(helper)
        result = command([DRIVER, "-o", alias, helper], env=env, check=False)
        expect(result.returncode != 0 and helper.read_text() == original,
               "driver overwrote an input through a symlink")
        expect(not list(temp.iterdir()), "driver left temporary objects behind")

        empty_sources = []
        for index in range(65):
            source = td / f"empty{index}.c"
            source.write_text("")
            empty_sources.append(source)
        command([DRIVER, "-c", "-o", combined, *empty_sources], env=env)
        expect(combined.read_bytes()[:4] == b"\x7fELF" and not list(temp.iterdir()),
               "many-source relocatable link failed or left temporary objects")
        many_defines = [f"-DMACRO{index}={index}" for index in range(65)]
        command([DRIVER, *many_defines, "-E", empty_sources[0]], env=env)

def driver_intermediate_output_case():
    """Check atomic intermediate files, streaming outputs, and cleanup.

    Returns:
        None; raises AssertionError for incorrect output or temporary-file handling.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-intermediate-output-") as directory:
        td = pathlib.Path(directory)
        destination = td / "output dir"
        destination.mkdir()
        good = td / "good.bc"
        good.write_text("int main() { return 42; }\n")
        bad = td / "bad.bc"
        bad.write_text("int main() { return missing; }\n")
        bad_pp = td / "bad-pp.bc"
        bad_pp.write_text('#include "absent.h"\n')
        original = b"previous output\n"
        for mode, source in (("-E", bad_pp), ("--emit-ir", bad), ("-S", bad)):
            output = destination / (mode[1:] + ".txt")
            output.write_bytes(original)
            output.chmod(0o604)
            result = command([DRIVER, mode, "-o", output, source], check=False)
            expect(result.returncode != 0 and result.stderr.strip() and
                   output.read_bytes() == original and output.stat().st_mode & 0o777 == 0o604,
                   f"{mode} failure changed existing output")
            absent = destination / (mode[1:] + "-absent")
            result = command([DRIVER, mode, "-o", absent, source], check=False)
            expect(result.returncode != 0 and not absent.exists(),
                   f"{mode} failure created an output")
            stdout = command([DRIVER, mode, good]).stdout
            result = command([DRIVER, mode, "-o", output, good])
            expect(not result.stdout and output.read_text() == stdout and
                   output.stat().st_mode & 0o777 == 0o604,
                   f"{mode} did not replace output with the correct content and mode")
            expect(command([DRIVER, mode, "-o", "-", good]).stdout == stdout,
                   f"{mode} standard output changed")

        new_file = destination / "new.s"
        command(["sh", "-c", 'umask 027; exec "$@"', "sh",
                 DRIVER, "-S", "-o", new_file, good])
        expect(new_file.stat().st_mode & 0o777 == 0o640,
               "new intermediate output ignored the process umask")
        restricted = destination / "restricted.s"
        command(["sh", "-c", 'umask 777; exec "$@"', "sh",
                 DRIVER, "-S", "-o", restricted, good])
        expect(restricted.stat().st_mode & 0o777 == 0,
               "restrictive umask prevented staging or changed output permissions")
        target, alias = destination / "target", destination / "alias"
        target.write_bytes(original)
        target.chmod(0o600)
        alias.symlink_to(target)
        result = command([DRIVER, "-S", "-o", alias, bad], check=False)
        expect(result.returncode != 0 and alias.is_symlink() and target.read_bytes() == original,
               "failed intermediate output changed a symlink or its target")
        command([DRIVER, "-S", "-o", alias, good])
        expect(not alias.is_symlink() and target.read_bytes() == original and
               alias.stat().st_mode & 0o777 == 0o600 and ".global _start" in alias.read_text(),
               "successful intermediate output did not safely replace the symlink")
        hardlink = destination / "hardlink"
        os.link(target, hardlink)
        command([DRIVER, "-S", "-o", hardlink, good])
        expect(target.read_bytes() == original and ".global _start" in hardlink.read_text(),
               "intermediate output changed a hard-linked file")
        collision = destination / "source-alias"
        collision.symlink_to(good)
        result = command([DRIVER, "-S", "-o", collision, good], check=False)
        expect(result.returncode != 0 and collision.is_symlink() and
               good.read_text() == "int main() { return 42; }\n",
               "intermediate output overwrote its input through a symlink")
        dangling = destination / "dangling"
        dangling.symlink_to(destination / "missing-target")
        result = command([DRIVER, "-E", "-o", dangling, bad_pp], check=False)
        expect(result.returncode != 0 and dangling.is_symlink(),
               "failed intermediate output removed a dangling symlink")
        command([DRIVER, "-E", "-o", dangling, good])
        expect(not dangling.is_symlink() and not (destination / "missing-target").exists(),
               "successful intermediate output followed a dangling symlink")
        assembly = td / "bad.S"
        assembly.write_text('#include "absent.h"\n')
        saved = destination / "assembly.i"
        saved.write_bytes(original)
        result = command([DRIVER, "-E", "-o", saved, assembly], check=False)
        expect(result.returncode != 0 and saved.read_bytes() == original,
               "failed assembly preprocessing damaged existing output")

        null = pathlib.Path("/dev/null")
        before = null.stat()
        result = command([DRIVER, "-E", "-o", null, bad_pp], check=False)
        expect(result.returncode != 0 and null.exists() and
               null.stat().st_rdev == before.st_rdev and null.stat().st_ino == before.st_ino,
               "failed intermediate output damaged a special-file destination")
        command([DRIVER, "-E", "-o", null, good])
        expect(null.stat().st_ino == before.st_ino,
               "successful intermediate output replaced a special-file destination")
        expect(not list(destination.glob(".crunch-output-*")),
               "driver left intermediate output temporaries behind")

def driver_link_output_case():
    """Check atomic linker output replacement and cleanup on failures.

    Returns:
        None; raises AssertionError for incorrect output or temporary-file handling.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-link-output-") as directory:
        td = pathlib.Path(directory)
        destination = td / "output dir"
        destination.mkdir()
        temp = td / "temp"
        temp.mkdir()
        env = dict(os.environ, TMPDIR=str(temp))
        good = td / "good.s"
        good.write_text(".text\n.globl _start\n_start:\n"
                        " mov $60,%eax\n mov $42,%edi\n syscall\n"
                        '.section .note.GNU-stack,"",@progbits\n')
        bad = td / "bad.s"
        bad.write_text(".text\n.globl _start\n_start:\n call missing_symbol\n")
        exe, obj = destination / "program", destination / "combined.o"
        original = b"previous executable"
        exe.write_bytes(original)
        exe.chmod(0o640)
        result = command([DRIVER, "-o", exe, bad], env=env, check=False)
        expect(result.returncode != 0 and "missing_symbol" in result.stderr and
               exe.read_bytes() == original and exe.stat().st_mode & 0o777 == 0o640,
               f"failed executable link damaged existing output: {result.stderr}")
        absent = destination / "absent"
        result = command([DRIVER, "-o", absent, bad], env=env, check=False)
        expect(result.returncode != 0 and not absent.exists(),
               "failed executable link left an output")
        obj.write_bytes(b"previous object")
        result = command([DRIVER, "-c", "-o", obj, good, good], env=env, check=False)
        expect(result.returncode != 0 and obj.read_bytes() == b"previous object",
               "failed relocatable link damaged existing output")

        reference = destination / "reference"
        os.link(exe, reference)
        command(["sh", "-c", 'umask 027; exec "$@"', "sh",
                 DRIVER, "-o", exe, good], env=env)
        expect(command([exe], check=False).returncode == 42 and
               exe.stat().st_mode & 0o777 == 0o750 and reference.read_bytes() == original,
               "successful executable replacement had incorrect content, mode, or hard-link behavior")
        command(["sh", "-c", 'umask 027; exec "$@"', "sh",
                 DRIVER, "-c", "-o", obj, good], env=env)
        expect(int.from_bytes(obj.read_bytes()[16:18], "little") == 1 and
               obj.stat().st_mode & 0o777 == 0o640,
               "successful object replacement had incorrect content or mode")

        target, alias = destination / "target", destination / "alias"
        target.write_bytes(original)
        alias.symlink_to(target)
        result = command([DRIVER, "-o", alias, bad], env=env, check=False)
        expect(result.returncode != 0 and alias.is_symlink() and target.read_bytes() == original,
               "failed link changed an output symlink or its target")
        command([DRIVER, "-o", alias, good], env=env)
        expect(not alias.is_symlink() and target.read_bytes() == original and
               command([alias], check=False).returncode == 42,
               "successful link did not replace the output symlink")
        blocked = destination / "existing-directory"
        blocked.mkdir()
        result = command([DRIVER, "-o", blocked, good], env=env, check=False)
        expect(result.returncode != 0 and "cannot replace output" in result.stderr and
               blocked.is_dir() and not list(blocked.iterdir()),
               "failed output replacement was not reported safely")
        result = command([DRIVER, "-o", destination / "missing-dir" / "program", good],
                         env=env, check=False)
        expect(result.returncode != 0 and "temporary output directory" in result.stderr,
               "missing output directory was not reported")
        expect(not list(destination.glob(".crunch-output-*")) and not list(temp.iterdir()),
               "driver left linker or object temporaries behind")

def assembly_driver_case():
    """Check assembly inputs, relocatable output, entry points, and mixed links.

    Returns:
        None; raises AssertionError for incorrect driver behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-driver-assembly-") as directory:
        td = pathlib.Path(directory)
        temp = td / "temp"
        temp.mkdir()
        env = dict(os.environ, TMPDIR=str(temp))
        start, first, second = (td / name for name in ("start.s", "first.s", "second.s"))
        start.write_text(".text\n.globl _start\n_start:\n"
                         " call calculate\n mov %eax,%edi\n mov $60,%eax\n syscall\n"
                         '.section .note.GNU-stack,"",@progbits\n')
        first.write_text(".text\n.Lshared:\n.globl calculate\ncalculate:\n"
                         " call helper\n add $2,%eax\n ret\n"
                         '.section .note.GNU-stack,"",@progbits\n')
        second.write_text(".text\n.Lshared:\n.globl helper\nhelper:\n mov $40,%eax\n ret\n"
                          '.section .note.GNU-stack,"",@progbits\n')
        combined, executable = td / "combined.o", td / "program"
        command([DRIVER, "-o", combined, start, first, second], env=env)
        expect(combined.read_bytes()[:6] == b"\x7fELF\x02\x01" and
               int.from_bytes(combined.read_bytes()[16:18], "little") == 1,
               "assembly inputs with .o output did not produce a relocatable object")
        command([DRIVER, "-o", executable, combined], env=env)
        expect(command([executable], check=False).returncode == 42,
               "assembly-only relocatable object did not link or execute")
        command([DRIVER, "-o", executable, start, first, second], env=env)
        expect(command([executable], check=False).returncode == 42,
               "assembly-only executable did not run correctly")
        command([DRIVER, start, first, second], cwd=td, env=env)
        expect(command([td / "a.out"], check=False).returncode == 42,
               "assembly-only default executable did not run correctly")

        one = td / "first.o"
        command([DRIVER, "-c", first, "-o", one], env=env)
        command([DRIVER, "-o", executable, start, one, second], env=env)
        expect(command([executable], check=False).returncode == 42,
               "assembly and object inputs did not link")
        explicit = td / "relocatable"
        command([DRIVER, "-c", "-o", explicit, start, first, second], env=env)
        expect(int.from_bytes(explicit.read_bytes()[16:18], "little") == 1,
               "-c did not produce relocatable output without an .o suffix")

        crunch_main = td / "main.bc"
        crunch_main.write_text("int calculate(); int main() { return calculate(); }\n")
        command([DRIVER, "-o", executable, crunch_main, first, second], env=env)
        expect(command([executable], check=False).returncode == 42,
               "Crunch main did not link with assembly functions")
        crunch_helper = td / "helper.bc"
        crunch_helper.write_text("int calculate() { return 42; }\n")
        command([DRIVER, "-o", executable, start, crunch_helper], env=env)
        expect(command([executable], check=False).returncode == 42,
               "assembly entry point did not link with a Crunch module")
        command([DRIVER, "-o", combined, start, crunch_helper], env=env)
        command([DRIVER, "-o", executable, combined], env=env)
        expect(command([executable], check=False).returncode == 42,
               "mixed Crunch and assembly relocatable output failed")
        standalone = td / "standalone.bc"
        standalone.write_text("int main() { return 42; }\n")
        command([DRIVER, "-o", combined, standalone], env=env)
        expect(int.from_bytes(combined.read_bytes()[16:18], "little") == 2 and
               command([combined], check=False).returncode == 42,
               "Crunch-only .o output no longer produces an executable")

        missing = td / "missing"
        result = command([DRIVER, "-o", missing, first, second], env=env, check=False)
        expect(result.returncode != 0 and "_start" in result.stderr and not missing.exists(),
               f"assembly without an entry point was accepted: {result.stderr}")
        local = td / "local.s"
        local.write_text(".text\n_start:\n ret\n")
        result = command([DRIVER, "-o", missing, local], env=env, check=False)
        expect(result.returncode != 0 and "_start" in result.stderr,
               f"a local _start was accepted as an entry point: {result.stderr}")
        result = command([DRIVER, "-o", missing, start, start, first, second],
                         env=env, check=False)
        expect(result.returncode != 0 and "_start" in result.stderr,
               "duplicate assembly entry points were accepted")
        result = command([DRIVER, "-o", combined, td / "absent.s"], env=env, check=False)
        expect(result.returncode != 0 and result.stderr.strip(),
               "missing assembly input was accepted")
        for mode in ("-E", "--emit-ir", "-S"):
            result = command([DRIVER, mode, first], env=env, check=False)
            expect(result.returncode != 0 and "Crunch source" in result.stderr,
                   f"{mode} accepted assembly input: {result.stderr}")
        broken = td / "broken.s"
        broken.write_text("not_an_instruction %rax\n")
        preserved = td / "preserved.o"
        preserved.write_text("unchanged")
        result = command([DRIVER, "-o", preserved, broken], env=env, check=False)
        expect(result.returncode != 0 and result.stderr.strip() and
               preserved.read_text() == "unchanged",
               "assembler failure was hidden or overwrote the output")
        result = command([DRIVER, "-o", first, first], env=env, check=False)
        expect(result.returncode != 0 and "also an input" in result.stderr,
               "driver allowed an assembly input to be overwritten")
        expect(not list(temp.iterdir()), "driver left assembly temporary objects behind")

def preprocessed_assembly_driver_case():
    """Exercise preprocessing, source mapping, and failures for assembly inputs.

    Returns:
        None; raises AssertionError for incorrect driver or preprocessor behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-driver-preprocessed-asm-") as directory:
        td = pathlib.Path(directory)
        temp, includes = td / "temp", td / "includes"
        temp.mkdir()
        includes.mkdir()
        env = dict(os.environ, TMPDIR=str(temp))
        (includes / "constants.h").write_text(
            "#ifndef CONSTANTS_H\n#define CONSTANTS_H\n"
            "#define ADD_TWO(x) ((x) + 2)\n"
            "#ifndef __ASSEMBLER__\nthis is not assembly\n#endif\n#endif\n")
        source = td / 'helper "quoted".S'
        source.write_text(
            '# A comment with unmatched /* and ADD_TWO(\n'
            '#include <constants.h>\n'
            '#if defined(__ASSEMBLER__) && VALUE == 40\n'
            '.text\n.globl calculate\ncalculate:\n'
            ' mov $ADD_TWO(VALUE), %eax # unmatched /* ADD_TWO(\n'
            ' ret\n'
            '#else\ninvalid_instruction\n#endif\n'
            '.section .note.GNU-stack,"",@progbits\n')
        start = td / "start.s"
        start.write_text(".text\n.globl _start\n_start:\n call calculate\n"
                         " mov %eax,%edi\n mov $60,%eax\n syscall\n"
                         '.section .note.GNU-stack,"",@progbits\n')
        exe, obj = td / "program", td / "combined.o"
        flags = ["-I", includes, "-DVALUE=40"]
        command([DRIVER, *flags, "-o", exe, start, source], env=env)
        expect(command([exe], check=False).returncode == 42,
               "preprocessed assembly did not link or execute")
        command([DRIVER, *flags, "-o", obj, start, source], env=env)
        expect(int.from_bytes(obj.read_bytes()[16:18], "little") == 1,
               ".S input with .o output did not select relocatable mode")
        command([DRIVER, "-o", exe, obj], env=env)
        expect(command([exe], check=False).returncode == 42,
               "preprocessed assembly object did not link or execute")
        crunch_main = td / "main.bc"
        crunch_main.write_text("int calculate(); int main() { return calculate(); }\n")
        command([DRIVER, *flags, "-o", exe, crunch_main, source], env=env)
        expect(command([exe], check=False).returncode == 42,
               "preprocessed assembly did not link with Crunch")

        expanded = command([DRIVER, *flags, "-E", source], env=env).stdout
        expect('mov $((40) + 2), %eax # unmatched /* ADD_TWO(' in expanded and
               "invalid_instruction" not in expanded and
               '# 1 "' in expanded and 'quoted\\".S"' in expanded,
               "assembly preprocessing mishandled comments, macros, or markers")
        from_pp = command([PP, "--assembly", *flags, source], env=env).stdout
        expect(from_pp == expanded, "standalone assembly preprocessing differs from driver")
        override = command([PP, "--assembly", "-D__ASSEMBLER__=2"],
                           input="#if __ASSEMBLER__ == 2\nselected\n#endif\n").stdout
        expect("selected" in override, "command-line __ASSEMBLER__ value was not preserved")
        mapped = td / 'bad "quoted".S'
        mapped.write_text("invalid_instruction\n")
        result = command([DRIVER, "-o", obj, mapped], env=env, check=False)
        expect(result.returncode != 0 and f"{mapped}:1:" in result.stderr,
               f"assembler error lost quoted source filename: {result.stderr}")
        for mode in ("-S", "--emit-ir"):
            result = command([DRIVER, mode, source], env=env, check=False)
            expect(result.returncode != 0 and "Crunch source" in result.stderr,
                   f"{mode} accepted preprocessed assembly")

        raw = td / "raw.s"
        raw.write_text(".data\n.long VALUE\n")
        command([DRIVER, "-DVALUE=40", "-c", "-o", obj, raw], env=env)
        expect(b"VALUE\0" in obj.read_bytes(), "raw .s input was preprocessed")
        bad_header = includes / "bad.h"
        bad_header.write_text("# comment\ninvalid_instruction\n")
        broken = td / "broken.S"
        broken.write_text('#include <bad.h>\n')
        preserved = td / "preserved.o"
        preserved.write_text("unchanged")
        result = command([DRIVER, "-I", includes, "-o", preserved, broken],
                         env=env, check=False)
        expect(result.returncode != 0 and f"{bad_header}:2:" in result.stderr and
               preserved.read_text() == "unchanged",
               f"assembler error lost source mapping or overwrote output: {result.stderr}")
        broken.write_text('#include "absent.h"\n')
        result = command([DRIVER, "-o", preserved, broken], env=env, check=False)
        expect(result.returncode != 0 and "absent.h" in result.stderr and
               "Assembler messages" not in result.stderr and
               preserved.read_text() == "unchanged",
               f"preprocessor failure was hidden or overwrote output: {result.stderr}")
        broken.write_text("#if 1\n.text\n")
        result = command([DRIVER, "-E", broken], env=env, check=False)
        expect(result.returncode != 0 and "unterminated conditional" in result.stderr,
               "malformed preprocessed assembly was accepted")
        for directive in ("pragma unknown_directive",):
            broken.write_text(f"#{directive}\n")
            result = command([DRIVER, "-E", broken], env=env, check=False)
            expect(result.returncode != 0 and "unsupported preprocessor directive" in result.stderr,
                   f"unsupported directive #{directive} was silently treated as a comment")
        expect(not list(temp.iterdir()), "driver left preprocessed assembly temporary objects")

def assembly_driver_differential_case():
    """Compare GNU and native assembly through driver compilation and linking.

    Returns:
        None; raises AssertionError for incorrect results or failure handling.
    """
    fixtures = FIXTURES / "units/assembly_driver"
    sources = [fixtures / "start.s", fixtures / "helper.S", fixtures / "base.s"]
    flags = ["-I", fixtures, "-DVALUE=40"]
    with tempfile.TemporaryDirectory(prefix="crunch-driver-assembly-diff-") as directory:
        td = pathlib.Path(directory)
        temp = td / "temp"
        temp.mkdir()
        configs = {}
        for assembler in ("gnu", "crunch"):
            for linker in ("gnu", "crunch"):
                config = td / f"{assembler}-{linker}.conf"
                config.write_text(f"assembler = {assembler}\nlinker = {linker}\n")
                configs[assembler, linker] = dict(os.environ, TMPDIR=str(temp),
                                                   CRUNCH_CONF_FILE=str(config))

        objects = {}
        relocations = {}
        signatures = {}
        for assembler in ("gnu", "crunch"):
            env = configs[assembler, "gnu"]
            objects[assembler] = []
            for source in sources:
                obj = td / f"{assembler}-{source.name}.o"
                command([DRIVER, *flags, "-c", source, "-o", obj], env=env)
                objects[assembler].append(obj)

            helper = objects[assembler][1]
            relocs = command(["readelf", "-rW", helper]).stdout
            relocations[assembler] = sorted(re.findall(
                r"(?m)^\s*[0-9a-f]+\s+[0-9a-f]+\s+(R_X86_64_\w+)\s+"
                r"[0-9a-f]+\s+(base|base_pointer|identity)\s+([+-])\s+([0-9a-f]+)\s*$",
                relocs))
            symbols = command(["readelf", "-sW", helper]).stdout
            signatures[assembler] = sorted(
                (name, kind, binding, index == "UND")
                for kind, binding, index, name in re.findall(
                    r"(?m)^\s*\d+:\s+[0-9a-f]+\s+\d+\s+(\w+)\s+(\w+)\s+"
                    r"\w+\s+(\w+)\s+(calculate|base_pointer|base|identity)\s*$",
                    symbols))
            expect(len(relocations[assembler]) >= 4 and len(signatures[assembler]) == 4,
                   f"{assembler} object is missing expected relocations or symbols:\n{relocs}\n{symbols}")
        expect(relocations["gnu"] == relocations["crunch"],
               f"assembler relocation mismatch: {relocations}")
        expect(signatures["gnu"] == signatures["crunch"],
               f"assembler symbol mismatch: {signatures}")

        for assembler in ("gnu", "crunch"):
            for linker in ("gnu", "crunch"):
                env = configs[assembler, linker]
                exe = td / f"program-{assembler}-{linker}"
                partial = td / f"partial-{assembler}-{linker}.o"
                for inputs in (sources, objects[assembler]):
                    command([DRIVER, *flags, "-o", exe, *inputs], env=env)
                    result = command([exe], check=False)
                    expect((result.returncode, result.stdout, result.stderr) == (42, "ok\n", ""),
                           f"{assembler}/{linker} executable failed: {result}")
                command([DRIVER, *flags, "-c", "-o", partial, *sources], env=env)
                command([DRIVER, "-o", exe, partial], env=env)
                result = command([exe], check=False)
                expect((result.returncode, result.stdout, result.stderr) == (42, "ok\n", ""),
                       f"{assembler}/{linker} partial link failed: {result}")

                main = td / "main.bc"
                main.write_text("int calculate(); int main() { return calculate(); }\n")
                command([DRIVER, *flags, "-o", exe, main, *sources[1:]], env=env)
                expect(command([exe], check=False).returncode == 42,
                       f"{assembler}/{linker} mixed Crunch and assembly link failed")

            env = configs[assembler, "gnu"]
            raw = td / "raw.s"
            raw.write_text(".data\n.long VALUE\n")
            raw_obj = td / f"raw-{assembler}.o"
            command([DRIVER, "-DVALUE=40", "-c", "-o", raw_obj, raw], env=env)
            expect(re.search(r"\bUND\s+VALUE\b",
                             command(["readelf", "-sW", raw_obj]).stdout) is not None,
                   f"{assembler} unexpectedly preprocessed raw .s input")

            preserved = td / "preserved.o"
            broken = td / "broken.s"
            broken.write_text("invalid_instruction\n")
            bad_header = td / "bad.h"
            bad_header.write_text("# comment\ninvalid_instruction\n")
            preprocessed = td / "broken.S"
            preprocessed.write_text('#include "bad.h"\n')
            bad_conditional = td / "bad-conditional.h"
            bad_conditional.write_text(".if 0\n.elseif missing\n.endif\n")
            conditional_source = td / "bad-conditional.S"
            conditional_source.write_text('#include "bad-conditional.h"\n')
            missing = td / "missing.S"
            missing.write_text('#include "missing-header.h"\n')
            for source, location in ((broken, f"{broken}:1:"),
                                     (preprocessed, f"{bad_header}:2:"),
                                     (conditional_source, f"{bad_conditional}:2:"),
                                     (missing, "missing-header.h")):
                preserved.write_text("unchanged")
                result = command([DRIVER, "-c", "-o", preserved, source],
                                 env=env, check=False)
                expect(result.returncode != 0 and location in result.stderr and
                       preserved.read_text() == "unchanged",
                       f"{assembler} failure lost diagnostics or output: {result.stderr}")
                if source == missing:
                    expect("Assembler messages" not in result.stderr and
                           "crunch-as:" not in result.stderr,
                           f"{assembler} reported assembler errors for a missing include")

        unsupported = td / "unsupported.S"
        unsupported.write_text(".text\n.altmacro\n")
        output = td / "unsupported.o"
        command([DRIVER, "-c", "-o", output, unsupported], env=configs["gnu", "gnu"])
        output.write_text("unchanged")
        result = command([DRIVER, "-c", "-o", output, unsupported],
                         env=configs["crunch", "gnu"], check=False)
        expect(result.returncode != 0 and f"{unsupported}:2:" in result.stderr and
               output.read_text() == "unchanged",
               f"native assembler did not reject unsupported .altmacro safely: {result.stderr}")
        expect(not list(temp.iterdir()), "differential driver tests left temporary objects")

def assembly_include_driver_case():
    """Compare assembler includes through raw and preprocessed driver inputs.

    Returns:
        None; raises AssertionError for incorrect inclusion or failure handling.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-driver-include-") as directory:
        td = pathlib.Path(directory)
        first, second = td / "first", td / "second"
        first.mkdir()
        second.mkdir()
        (first / "start.inc").write_text(
            '.include "value.inc"\n.text\n.globl _start\n_start:\n'
            " mov $VALUE, %edi\n mov $60, %eax\n syscall\n")
        (second / "value.inc").write_text(".equ VALUE,42\n")
        (first / "header.h").write_text("#define SELECTED 1\n")
        raw = td / "main.s"
        raw.write_text('.include "start.inc"\n')
        preprocessed = td / "main.S"
        preprocessed.write_text(
            '#include <header.h>\n#if SELECTED\n.include "start.inc"\n#endif\n')
        bad = first / "bad.inc"
        bad.write_text("# comment\ninvalid_instruction\n")
        config = td / "config"
        output = td / "program"
        for assembler in ("gnu", "crunch"):
            for linker in ("gnu", "crunch"):
                config.write_text(f"assembler = {assembler}\nlinker = {linker}\n")
                env = dict(os.environ, CRUNCH_CONF_FILE=str(config))
                for source in (raw, preprocessed):
                    command([DRIVER, "-I", first, "-I", second, source, "-o", output],
                            cwd=td, env=env)
                    expect(command([output], check=False).returncode == 42,
                           f"{assembler}/{linker} failed to execute {source.suffix} includes")
                for text, location in (('.include "missing.inc"\n', "missing.inc"),
                                       ('.include "bad.inc"\n', f"{bad}:2:")):
                    raw.write_text(text)
                    output.write_text("unchanged")
                    result = command([DRIVER, "-I", first, "-o", output, raw],
                                     cwd=td, env=env, check=False)
                    expect(result.returncode != 0 and location in result.stderr and
                           output.read_text() == "unchanged",
                           f"{assembler}/{linker} include failure was unsafe: {result.stderr}")
                raw.write_text('.include "start.inc"\n')

def driver_help_tools_case():
    """Check help reflects configured tool selections and custom paths.

    Returns:
        None; raises AssertionError for incorrect help output.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-help-tools-") as td:
        conf = pathlib.Path(td) / "crunch.conf"
        env = dict(os.environ, CRUNCH_CONF_FILE=str(conf))
        conf.write_text("assembler = gnu\nlinker = gnu\n")
        expected_archiver = ("crunch" if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1"
                             else (BUILD.parent / "config.mk").read_text().split(
                                 "CRUNCH_DEFAULT_ARCHIVER := ", 1)[1].splitlines()[0])
        for flag in ("--help", "-h"):
            result = command([DRIVER, flag], env=env)
            expect(not result.stderr and
                   "  assembler: gnu\n  linker:    crunch (dynamic executables)\n"
                   f"             gnu (static and relocatable)\n  archiver:  {expected_archiver}\n"
                   in result.stdout,
                   f"help did not reflect GNU selections: {result.stdout}")
        conf.write_text("assembler = crunch\nlinker = crunch\n"
                        "assembler_path = /custom/as\nlinker_path = /custom/ld\n"
                        "archiver_path = /custom/ar\n")
        result = command([DRIVER, "--help"], env=env)
        expect("  assembler: crunch (/custom/as)\n"
               "  linker:    crunch (dynamic executables: /custom/ld)\n"
               "             crunch (static and relocatable: /custom/ld)\n"
               "  archiver:  /custom/ar (configured path)\n" in result.stdout,
               f"help did not reflect configured paths: {result.stdout}")
        conf.write_text("assembler = invalid\n")
        result = command([DRIVER, "--help"], env=env)
        expect("Tools: unavailable (configuration error)" in result.stdout and
               "assembler must be gnu or crunch" in result.stderr,
               "help hid an invalid configuration")


def assembler_selection_option_case():
    """Check the renamed assembler option overrides configured tool choices.

    Returns:
        None; raises AssertionError for incorrect option handling.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-assembler-option-") as td:
        directory = pathlib.Path(td)
        conf = directory / "crunch.conf"
        conf.write_text("assembler = gnu\nassembler_path = /nonexistent/as\nlinker = crunch\n")
        env = dict(os.environ, CRUNCH_CONF_FILE=str(conf))
        obj = directory / "program.o"
        result = command([DRIVER, "--with-crunch-as", "-v", "-c",
                          FIXTURES / "ir/main42.bc", "-o", obj], env=env)
        expect(obj.is_file() and f"{BUILD / 'crunch-as'} -o " in result.stderr,
               "assembler option did not override the configured assembler path")
        help_text = command([DRIVER, "--help"], env=env).stdout
        expect("--with-crunch-as" in help_text and "--experimental-crunch-as" not in help_text,
               "driver help does not describe the renamed assembler option")
        old = command([DRIVER, "--experimental-crunch-as", "-c",
                       FIXTURES / "ir/main42.bc", "-o", obj], env=env, check=False)
        expect(old.returncode != 0, "old assembler option remains accepted")


def linker_input_classification_case():
    """Check malformed inputs and supported implicit executable linker scripts.

    Returns:
        None; raises AssertionError for incorrect input classification.
    """
    linker = BUILD / "crunch-ld"
    with tempfile.TemporaryDirectory(prefix="crunch-linker-input-") as td:
        directory = pathlib.Path(td)
        obj, inp, output = (directory / name for name in ("start.o", "input", "output"))
        command([BUILD / "crunch-as", "-o", obj], input=
                ".text\n.globl _start\n_start:\n"
                "mov $60, %rax\nmov $17, %rdi\nsyscall\n"
                ".globl other\nother:\n"
                "mov $60, %rax\nmov $42, %rdi\nsyscall\n")
        for data in (b"not an ELF object", b"", b"/* comment */", b"ENTRYPOINT",
                     b"ENTRY(_start)\0garbage", b"\x7fELF"):
            inp.write_bytes(data)
            for mode in (["-nostdlib"], ["-r"], ["-nostdlib", "-shared"]):
                output.write_bytes(b"unchanged")
                result = command([linker, *mode, "-o", output, obj, inp], check=False)
                expect_clean_rejection(result, f"input {data!r} in mode {mode}", "crunch-ld:")
                expect(output.read_bytes() == b"unchanged",
                       f"rejected input modified output in mode {mode}")
        for script, status in (("/* header */\nENTRY(other)\n", 42),
                               ("SECTIONS { . = 0x400000; }\n", 17),
                               ("marker = 7;\n", 17)):
            inp.write_text(script)
            command([linker, "-nostdlib", "-o", output, obj, inp])
            expect(command([output], check=False).returncode == status,
                   f"implicit script did not produce a working executable: {script!r}")
        inp.write_text("ENTRY(other)\n")
        command([linker, "-nostdlib", "-T", inp, "-o", output, obj])
        expect(command([output], check=False).returncode == 42,
               "explicit linker script did not produce a working executable")


def linker_help_case():
    """Check linker help and preserve the short SONAME option.

    Returns:
        None; raises AssertionError for incorrect help or SONAME handling.
    """
    linker = BUILD / "crunch-ld"
    with tempfile.TemporaryDirectory(prefix="crunch-linker-help-") as td:
        directory = pathlib.Path(td)
        result = command([linker, "--help"], cwd=directory)
        expect(not result.stderr and "Usage: crunch-ld" in result.stdout and
               "--help" in result.stdout and "--soname" in result.stdout and
               not (directory / "a.out").exists(),
               "linker help did not exit cleanly without creating output")
        missing = command([linker, "-h"], check=False)
        expect(missing.returncode != 0 and "missing argument" in missing.stderr,
               "-h no longer requires a SONAME")
        obj, shared = directory / "input.o", directory / "libtest.so"
        command([BUILD / "crunch-as", "-o", obj], input=".text\n")
        command([linker, "-nostdlib", "-shared", "-h", "libtest-soname.so", "-o", shared, obj])
        expect(b"libtest-soname.so\0" in shared.read_bytes(),
               "-h did not set the shared-object SONAME")


def linker_automatic_runtime_case(linker=None):
    """Check standalone linker runtime search, explicit inputs, and opt-outs.

    Args:
        linker: Linker to test, or None for the host-built linker.
    Returns:
        None; raises AssertionError for incorrect runtime selection or output.
    """
    linker, assembler = linker or BUILD / "crunch-ld", BUILD / "crunch-as"
    with tempfile.TemporaryDirectory(prefix="crunch-linker-runtime-") as td:
        directory = pathlib.Path(td)
        libs = directory / "lib"
        runtime = libs / "crunch"
        runtime.mkdir(parents=True)
        for name in ("libcrunch.a", "libcrunch.so.1", "libcrunch-fallback.a"):
            shutil.copyfile(BUILD / name, runtime / name)
        (runtime / "libcrunch.so").symlink_to("libcrunch.so.1")
        conf = directory / "crunch.conf"
        conf.write_text(f"library_path = {directory / 'missing'}\nlibrary_path = {libs}\n")
        env = {k: v for k, v in os.environ.items()
               if k not in ("LD_LIBRARY_PATH", "LD_PRELOAD", "LD_AUDIT")}
        env["CRUNCH_CONF_FILE"] = str(conf)
        obj, exe = directory / "start.o", directory / "program"
        command([assembler, "-o", obj], input=
                ".text\n.globl _start\n_start:\n"
                "lea message(%rip), %rdi\ncall __crunch_strlen@PLT\n"
                "mov %rax, %rdi\nmov $60, %rax\nsyscall\n"
                ".section .rodata\nmessage: .string \"abc\"\n")
        for flags in ([], ["--dynamic"], ["--dynamic", "--pie"]):
            command([linker, *flags, "-o", exe, obj], env=env)
            expect(command([exe], cwd="/", env=env, check=False).returncode == 3,
                   f"automatic runtime failed for {flags}")
        command([linker, "--dynamic", "--rpath", "$ORIGIN/other", "-o", exe, obj], env=env)
        expect(f"$ORIGIN/other:{runtime}\0".encode() in exe.read_bytes(),
               "explicit RUNPATH was not placed before the automatic runtime path")
        conf.write_text("library_path = lib\n")
        command([linker, "--dynamic", "-o", exe, obj], cwd=directory, env=env)
        expect(command([exe], cwd="/", env=env, check=False).returncode == 3,
               "relative configured runtime path was not resolved at link time")
        alias = directory / "alias"
        alias.symlink_to("lib/crunch", target_is_directory=True)
        conf.write_text("library_path = alias/../crunch\n")
        command([linker, "--dynamic", "-o", exe, obj], cwd=directory, env=env)
        expect(str(runtime.resolve()).encode() + b"\0" in exe.read_bytes() and
               command([exe], cwd="/", env=env, check=False).returncode == 3,
               "symlink and parent components were not resolved in RUNPATH")
        conf.write_text(f"library_path = {directory / 'missing'}\nlibrary_path = {libs}\n")
        for flags in (["-lcrunch"], ["-l:libcrunch.a"]):
            command([linker, "-o", exe, obj, *flags], env=env)
            expect(command([exe], env=env, check=False).returncode == 3,
                   f"configured explicit static runtime failed: {flags}")
        shared = directory / "module.so"
        command([linker, "--shared", "--no-undefined", "-o", shared, obj], env=env)
        expect(b"libcrunch.so.1\0" in shared.read_bytes(),
               "shared link did not add the configured runtime")
        command([PYTHON, "-c", "import ctypes,sys; ctypes.CDLL(sys.argv[1])", shared],
                cwd="/", env=env)
        for flags in (["-lcrunch"], ["-l:libcrunch.so"]):
            command([linker, "--shared", "--no-undefined", "-o", shared, obj, *flags], env=env)
            expect(b"libcrunch.so.1\0" in shared.read_bytes(),
                   f"configured explicit shared runtime failed: {flags}")
        for flag in ("-nostdlib", "-nodefaultlibs"):
            for mode in ([], ["--dynamic"], ["--shared", "--no-undefined"]):
                result = command([linker, *mode, flag, "-o", exe, obj], env=env, check=False)
                expect(result.returncode != 0, f"{flag} did not suppress the runtime for {mode}")
        result = command([linker, "-r", "--require-defined=__crunch_strlen",
                          "-o", directory / "combined.o", obj], env=env, check=False)
        expect(result.returncode != 0, "relocatable link added the runtime")

        alternate = directory / "alternate"
        alternate.mkdir()
        custom_obj = alternate / "custom.o"
        command([assembler, "-o", custom_obj], input=
                ".text\n.globl __crunch_strlen\n.type __crunch_strlen,@function\n"
                "__crunch_strlen: mov $17, %rax\nret\n")
        command([BUILD / "crunch-ar", "rcs", alternate / "libcrunch.a", custom_obj])
        custom_shared = alternate / "libcrunch.so"
        command([linker, "-nostdlib", "-shared", "-soname", "custom-crunch.so",
                 "-o", custom_shared, custom_obj], env=env)
        for flags in ([alternate / "libcrunch.a"], ["-L", alternate, "-lcrunch"]):
            command([linker, "-o", exe, obj, *flags], env=env)
            expect(command([exe], env=env, check=False).returncode == 17,
                   f"explicit static runtime was not selected: {flags}")
        for flags in ([custom_shared], ["-L", alternate, "-lcrunch"]):
            command([linker, "-shared", "-o", shared, obj, *flags], env=env)
            data = shared.read_bytes()
            expect(b"custom-crunch.so\0" in data and b"libcrunch.so.1\0" not in data,
                   f"explicit shared runtime was accompanied by the default: {flags}")
        command([linker, "--dynamic", "-o", exe, obj, runtime / "libcrunch.so"], env=env)
        expect(str(runtime).encode() not in exe.read_bytes(),
               "explicit runtime unexpectedly gained an automatic RUNPATH")
        command([linker, "--dynamic", "-nostdlib", "--rpath", "$ORIGIN/lib",
                 "-o", exe, obj, runtime / "libcrunch.so"], env=env)
        expect(b"$ORIGIN/lib\0" in exe.read_bytes() and
               str(runtime).encode() not in exe.read_bytes(),
               "-nostdlib changed the explicit RUNPATH")
        original = (runtime / "libcrunch.a").read_bytes()
        result = command([linker, "-o", runtime / "libcrunch.a", obj], env=env, check=False)
        expect(result.returncode != 0 and (runtime / "libcrunch.a").read_bytes() == original,
               "automatic runtime could be overwritten by output")
        unsafe = directory / "bad$path"
        unsafe.mkdir()
        (unsafe / "libcrunch.so").symlink_to(runtime / "libcrunch.so.1")
        result = command([linker, "--dynamic", "-L", unsafe, "-o", exe, obj],
                         env=env, check=False)
        expect(result.returncode != 0 and "cannot be embedded in RUNPATH" in result.stderr,
               "runtime directory with loader token was not rejected")
        alias.unlink()
        alias.symlink_to(unsafe, target_is_directory=True)
        result = command([linker, "--dynamic", "-L", alias, "-o", exe, obj],
                         env=env, check=False)
        expect(result.returncode != 0 and "cannot be embedded in RUNPATH" in result.stderr,
               "symlink to a runtime directory with a loader token was not rejected")


def installed_toolchain_corpus_case(gnu_matrix=False):
    """Run varied programs through installed tools and optional GNU combinations.

    Args:
        gnu_matrix: Test the three combinations containing GNU assembler or linker.
    Returns:
        None; raises AssertionError for incorrect pipeline or program behavior.
    """
    cases = INSTALLED_TOOLCHAIN_CASES
    env = {k: v for k, v in os.environ.items()
           if k not in ("MAKEFLAGS", "MFLAGS", "MAKELEVEL", "CRUNCH_CONF_FILE",
                        "CRUNCH_INCLUDE_PATH", "LD_LIBRARY_PATH", "LD_PRELOAD", "LD_AUDIT")}
    fixtures = FIXTURES / "units/installed_toolchain"
    with tempfile.TemporaryDirectory(prefix="crunch-installed-corpus-") as td:
        directory = pathlib.Path(td)
        prefix = directory / "prefix"
        command(["make", "-C", ROOT, f"prefix={prefix}", "install"], env=env, timeout=300)
        compiler, native_as, native_ld, ir, asm = (prefix / "bin" / name for name in
                                                   ("crunch", "crunch-as", "crunch-ld",
                                                    "crunch-ir", "crunch-asm"))
        expect((prefix / "include/crunch/stdalign.h").is_file(), "stdalign.h was not installed")
        expect((prefix / "lib/crunch/libcrunch-support.a").is_file(),
               "compiler support archive was not installed")
        alignment_source = directory / "alignment.bc"
        alignment_exe = directory / "alignment"
        alignment_source.write_text(
            "#include <stdalign.h>\nint main(void) { return alignof(long) == 8 ? 42 : 1; }\n")
        command([compiler, alignment_source, "-o", alignment_exe], env=env)
        expect(command([alignment_exe], env=env, check=False).returncode == 42,
               "installed stdalign.h failed")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1" and shutil.which("gcc"):
            result = command([compiler, "--glibc", "-o", alignment_exe, "-"], env=env,
                             input="int main(void) { volatile double x = 2.0; "
                                   "return x ** 3.0 == 8.0 ? 42 : 1; }\n")
            expect(result.returncode == 0 and
                   command([alignment_exe], env=env, check=False).returncode == 42,
                   "installed glibc mode did not find its compiler support archive")
        strip = shutil.which("strip")
        if not strip:
            if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
                raise AssertionError("installed corpus requires strip for interoperability testing")
            print("install / native toolchain corpus: external strip unavailable; interoperability skipped")
        if gnu_matrix:
            interpreter_config = (BUILD.parent / "crunch-linker-config.h").read_text()
            interpreter_match = re.search(r'^#define CRUNCH_DYNAMIC_LINKER "([^"]+)"$',
                                          interpreter_config, re.MULTILINE)
            expect(interpreter_match is not None, "configured dynamic linker missing")
            interpreter = interpreter_match.group(1)
            combinations = (("native", native_as, "gnu", "ld"),
                            ("gnu", "as", "native", native_ld),
                            ("gnu", "as", "gnu", "ld"))
        else:
            combinations = (("native", native_as, "native", native_ld),)

        assemblies = {}
        for name in [case[0] for case in cases] + ["module_helper"]:
            source = fixtures / f"{name}.bc"
            assembly = directory / f"{name}.s"
            if name in ("modules", "module_helper"):
                preprocessed = command([compiler, "-E", source], env=env).stdout
                module = command([ir, "--module", "-"], input=preprocessed, env=env).stdout
                assembly.write_text(command([asm, "-"], input=module, env=env).stdout)
            else:
                command([compiler, "-S", source, "-o", assembly], env=env)
            assemblies[name] = assembly

        objects = {}
        for assembler_name, assembler in dict((a, tool) for a, tool, _, _ in combinations).items():
            for name, assembly in assemblies.items():
                obj = directory / f"{name}-{assembler_name}.o"
                command([assembler, "-o", obj, assembly], env=env)
                objects[name, assembler_name] = obj

        for name, args, stdin, expected in cases:
            for assembler_name, _, linker_name, linker in combinations:
                objs = [objects[name, assembler_name]]
                if name == "modules":
                    objs.append(objects["module_helper", assembler_name])
                for mode in ("static", "dynamic", "pie"):
                    if linker_name == "native":
                        flags = [] if mode == "static" else ["-dynamic"]
                        if mode == "pie":
                            flags += ["-pie"]
                        runtime = []
                    else:
                        flags = [] if mode == "static" else [
                            "--dynamic-linker", interpreter, "-rpath", str(prefix / "lib/crunch")]
                        if mode == "pie":
                            flags += ["-pie"]
                        runtime_dir = prefix / "lib/crunch"
                        runtime = ([runtime_dir / "libcrunch.a"] if mode == "static" else
                                   [runtime_dir / "libcrunch-fallback.a", runtime_dir / "libcrunch.so"])
                    for linker_strip in (False, True):
                        label = f"{name} {assembler_name}/{linker_name} {mode}"
                        exe = directory / f"{name}-{assembler_name}-{linker_name}-{mode}"
                        command([linker, *flags, *(["-s"] if linker_strip else []),
                                 "-o", exe, *objs, *runtime], env=env)
                        output_file = directory / "corpus-output.txt"
                        if name == "file_io":
                            output_file.unlink(missing_ok=True)
                        result = command([exe, *args], input=stdin, env=env, cwd=directory,
                                         check=False)
                        expect(result.returncode == 0 and result.stdout == expected and not result.stderr,
                               f"{label} linker-strip={linker_strip}: exit {result.returncode}, "
                               f"stdout={result.stdout!r}, stderr={result.stderr!r}")
                        if name == "file_io":
                            expect(output_file.read_bytes() == b"one\ntwo\n",
                                   f"{label}: file contents")
                        if strip and not linker_strip:
                            command([strip, exe], env=env)
                            if name == "file_io":
                                output_file.unlink()
                            result = command([exe, *args], input=stdin, env=env, cwd=directory,
                                             check=False)
                            expect(result.returncode == 0 and result.stdout == expected and not result.stderr,
                                   f"{label} after strip: exit {result.returncode}, "
                                   f"stdout={result.stdout!r}, stderr={result.stderr!r}")
                            if name == "file_io":
                                expect(output_file.read_bytes() == b"one\ntwo\n",
                                       f"{label} after strip: file contents")


def install_case():
    """Check staged installation, reinstallation, configuration preservation, and removal.

    Returns:
        None; raises AssertionError for incorrect installed artifacts or behavior.
    """
    root = BUILD.parent.parent
    clean_env = {k: v for k, v in os.environ.items()
                 if k not in ("MAKEFLAGS", "MFLAGS", "MAKELEVEL", "CRUNCH_INCLUDE_PATH",
                              "CRUNCH_CONF_FILE")}
    with tempfile.TemporaryDirectory(prefix="crunch-install-") as td:
        directory = pathlib.Path(td)
        staging = directory / "temporary"
        staging.mkdir()
        clean_env["TMPDIR"] = str(staging)
        legacy_install = root / "build/out/install"
        previous = {entry.name: entry.stat().st_mtime_ns for entry in legacy_install.iterdir()} \
            if legacy_install.is_dir() else None
        prefix = directory / "prefix"
        make = ["make", "-C", root, f"prefix={prefix}"]
        command(make + ["install"], env=clean_env, timeout=300)
        expect(not list(staging.glob("crunch-install.*")), "installation staging was not removed")
        after = {entry.name: entry.stat().st_mtime_ns for entry in legacy_install.iterdir()} \
            if legacy_install.is_dir() else None
        expect(after == previous, "installation modified build/out/install")
        failed_install = command(make + ["CC=false", "install-exec-local"],
                                 env=clean_env, check=False, timeout=300)
        expect(failed_install.returncode != 0 and not list(staging.glob("crunch-install.*")),
               "failed installation left temporary binaries behind")
        for tool in ("crunch", "crunch-pp", "crunch-lexer", "crunch-parser",
                     "crunch-ir", "crunch-opt", "crunch-asm", "crunch-as", "crunch-ld", "crunch-ar"):
            expect(os.access(prefix / "bin" / tool, os.X_OK), f"{tool} was not installed")
        for header in ("glibc/alloca.h", "string.h", "stdio.h", "stdlib.h", "stddef.h", "stdint.h", "inttypes.h", "elf.h", "math.h", "float.h", "ctype.h", "environment.h", "errno.h",
                       "limits.h", "stdbool.h", "stdalign.h", "unistd.h", "fcntl.h", "poll.h",
                       "signal.h", "dirent.h", "sys/types.h", "sys/stat.h", "sys/select.h",
                       "sys/mman.h", "sys/utsname.h", "sys/wait.h", "sys/random.h",
                       "sys/socket.h", "sys/un.h", "sys/uio.h", "sys/ioctl.h", "time.h", "netinet/in.h",
                       "sched.h", "sys/ipc.h", "sys/shm.h", "sys/time.h", "sys/sendfile.h",
                       "sys/resource.h", "sys/sem.h", "sys/msg.h", "sys/file.h",
                       "sys/getdents.h", "sys/sysinfo.h"):
            expect((prefix / "include/crunch" / header).is_file(), f"{header} was not installed")
        for header in ("file.h", "system.h"):
            expect(not (prefix / "include/crunch" / header).exists(),
                   f"obsolete header {header} was installed")
        expect(not (prefix / "include/crunch/test").exists(), "test headers were installed")
        conf = prefix / "etc/crunch/crunch.conf"
        expect(conf.is_file(), "default configuration file was not installed")
        default_conf = conf.read_text()
        expect(f"library_path = {prefix / 'lib'}\n" in default_conf,
               "installed configuration has the wrong default library path")
        destdir = directory / "stage"
        command(make + [f"DESTDIR={destdir}", "install"], env=clean_env, timeout=300)
        staged_conf = destdir / str(conf).lstrip("/")
        expect(staged_conf.read_text() == default_conf,
               "DESTDIR leaked into the installed library path")
        linker_manual = prefix / "share/man/man1/crunch-ld.1"
        staged_linker_manual = destdir / str(linker_manual).lstrip("/")
        expect(linker_manual.read_bytes() == (root / "src/linker/crunch-ld.1").read_bytes() and
               staged_linker_manual.read_bytes() == linker_manual.read_bytes(),
               "linker man page was not installed correctly")
        command(make + [f"DESTDIR={destdir}", "uninstall"], env=clean_env)
        expect(not staged_conf.exists(), "staged uninstall left the default configuration")
        expect(not staged_linker_manual.exists(), "staged uninstall left the linker man page")
        expect((prefix / "lib/crunch/libcrunch.a").is_file(),
               "libcrunch.a was not installed")
        expect((prefix / "lib/crunch/libcrunch-support.a").is_file(),
               "compiler support archive was not installed")
        installed_shared = prefix / "lib/crunch/libcrunch.so"
        expect(installed_shared.is_symlink() and os.readlink(installed_shared) == "libcrunch.so.1" and
               installed_shared.is_file(), "shared runtime was not installed correctly")
        command([PYTHON, "-c",
                 "import ctypes,sys; l=ctypes.CDLL(sys.argv[1]); "
                 "f=l.__crunch_strlen; f.argtypes=[ctypes.c_char_p]; f.restype=ctypes.c_long; "
                 "assert f(b'installed')==9", installed_shared], env=clean_env)
        expect((prefix / "share/man/man1/crunch-ar.1").is_file() and
               command([prefix / "bin/crunch-ar", "--version"]).stdout.startswith("crunch-ar "),
               "native archiver or its man page was not installed correctly")
        installed_obj = directory / "standalone.o"
        installed_program = directory / "standalone"
        command([prefix / "bin/crunch-as", "-o", installed_obj], input=
                ".text\n.globl _start\n_start:\n"
                "lea message(%rip), %rdi\ncall __crunch_strlen@PLT\n"
                "mov %rax, %rdi\nmov $60, %rax\nsyscall\n"
                ".section .rodata\nmessage: .string \"abc\"\n", env=clean_env)
        installed_env = {k: v for k, v in clean_env.items()
                         if k not in ("LD_LIBRARY_PATH", "LD_PRELOAD", "LD_AUDIT")}
        for flags in ([], ["--dynamic"]):
            command([prefix / "bin/crunch-ld", *flags, "-o", installed_program,
                     installed_obj], env=installed_env)
            expect(command([installed_program], env=installed_env, check=False).returncode == 3,
                   f"installed standalone linker could not use its runtime: {flags}")
        installed_source = directory / "standalone.bc"
        installed_source.write_text('#include <string.h>\nint main() { return strlen("abc"); }\n')
        installed_asm = directory / "standalone.s"
        command([prefix / "bin/crunch", "-S", installed_source, "-o", installed_asm],
                env=installed_env)
        command([prefix / "bin/crunch-as", "-o", installed_obj, installed_asm], env=installed_env)
        command([prefix / "bin/crunch-ld", "-dynamic", "-o", installed_program, installed_obj],
                env=installed_env)
        expect(command([installed_program], cwd="/", env=installed_env, check=False).returncode == 3,
               "standalone source-assembly-link pipeline could not load its runtime")
        command([prefix / "bin/crunch", FIXTURES / "units/library/elf_header.bc",
                 "-o", installed_program], env=installed_env, cwd=directory)
        expect(command([installed_program], env=installed_env, check=False).returncode == 0,
               "installed compiler could not use the installed ELF64 header")
        manual = (prefix / "share/man/man1/crunch.1").read_text()
        expect(f"{conf}".replace("-", "\\-") in manual and "%" not in manual and "@" not in manual,
               "man page was not installed with the configured file names")
        expect('"crunch 0.9.0"' in manual and
               command([prefix / "bin/crunch", "--version"]).stdout.startswith("crunch 0.9.0\n"),
               "installed compiler and man page have inconsistent release versions")
        manual_dir = prefix / "share/man/man3"
        manual_names = ("input", "fopen", "fclose", "fseek", "ftell", "rewind", "fread", "fwrite",
                        "fgetc", "fputc", "putchar", "fgets", "getline", "fputs", "puts", "fprintf", "snprintf", "vsnprintf", "stdin", "stdout", "stderr", "feof", "ferror", "clearerr", "open", "openat", "fstatat", "readlinkat", "unlinkat",
                        "mkdirat", "renameat", "symlinkat", "read", "write", "close", "stat", "fstat",
                        "lstat", "readlink", "getdents64", "dirent64_next",
                        "unlink", "rename", "mkdir", "rmdir", "lseek",
                        "access", "dup", "dup2", "pipe", "poll", "select", "fork", "getpid", "kill",
                        "malloc", "calloc", "free", "realloc", "allocator_trim", "strtod", "strtof", "strtold",
                        "socket", "bind", "connect", "listen", "accept", "recvfrom", "sendmsg", "recvmsg",
                        "sigaction", "sigemptyset", "nanosleep", "sleep", "mmap", "munmap", "mremap",
                        "map_failed", "execve", "waitpid", "uname", "getrandom", "chmod", "fchmod", "_exit",
                        "file_open", "file_read", "file_write", "file_close",
                        "mprotect", "brk", "sigprocmask", "ioctl", "ioctl_value", "pread", "pwrite", "readv",
                        "writev", "sched_yield", "msync", "mincore", "madvise", "shmget", "shmat",
                        "shmctl", "shmdt", "pause", "alarm", "getitimer", "setitimer",
                        "sendfile", "sendto", "shutdown", "getsockname", "getpeername",
                        "socketpair", "setsockopt", "getsockopt", "clone", "vfork",
                        "wait4", "semget", "semop", "semctl", "semctl_value", "msgget",
                        "msgsnd", "msgrcv", "msgctl", "fcntl", "fcntl_ptr", "flock",
                        "fsync", "fdatasync", "truncate", "ftruncate", "getdents", "getcwd",
                        "chdir", "fchdir", "creat", "link", "symlink", "chown", "fchown",
                        "lchown", "umask", "gettimeofday", "getrlimit", "getrusage", "sysinfo")
        for name in manual_names:
            page = manual_dir / f"{name}.3crunch"
            expect(page.is_file() and page.read_text() == (root / f"man/{name}.3crunch").read_text(),
                   f"{name}(3crunch) was not installed correctly")
            expect(not (destdir / str(page).lstrip("/")).exists(),
                   f"staged uninstall left {name}(3crunch)")
            if shutil.which("man"):
                env = dict(clean_env, MANPAGER="cat", PAGER="cat", MANWIDTH="80")
                rendered = command(["man", "-M", prefix / "share/man", "-s", "3",
                                    "-e", "crunch", name], env=env)
                expect("Crunch Library Manual" in rendered.stdout and
                       f"{name.upper()}(3crunch)" in rendered.stdout,
                       f"man lookup did not select {name}(3crunch): {rendered.stdout}")
        input_manual = manual_dir / "input.3crunch"
        example = input_manual.read_text().split(".nf\n")[2].split("\n.fi")[0]
        source_example = directory / "input-example.bc"
        source_example.write_text(example.replace("\\\\", "\\"))
        executable_example = directory / "input-example"
        command([prefix / "bin/crunch", source_example, "-o", executable_example],
                env=clean_env, cwd=directory)
        example_result = command([executable_example], input="Alice ignored\n")
        expect(example_result.stdout ==
               "Name (up to 5 bytes): Hello, Alice! Read 5 bytes.\n",
               "input(3crunch) example did not compile and run as documented")
        realloc_manual = manual_dir / "realloc.3crunch"
        realloc_example = realloc_manual.read_text().split(".nf\n")[2].split("\n.fi")[0]
        source_example.write_text(realloc_example.replace("\\\\", "\\"))
        command([prefix / "bin/crunch", source_example, "-o", executable_example],
                env=clean_env, cwd=directory)
        command([executable_example], env=clean_env, cwd=directory)

        extra = directory / "extra"
        extra.mkdir()
        (extra / "extra.h").write_text("int from_installed_conf;\n")
        conf.write_text(f"include_path = {extra}\n")
        source = directory / "program.bc"
        source.write_text('#include <stdlib.h>\n#include <extra.h>\n'
                          'int printf(const char* format); int main() { printf("installed;"); exit(21); return 0; }\n')
        program = directory / "program"
        command([prefix / "bin/crunch", source, "-o", program], env=clean_env, cwd=directory)
        result = command([program], check=False)
        expect(result.returncode == 21 and result.stdout == "installed;",
               "program built by the installed compiler did not run correctly")

        source.write_text('#include <assert.h>\n'
                          'int main(void) { int n = 0; assert(++n == 1); return n - 1; }\n')
        command([prefix / "bin/crunch", source, "-o", program], env=clean_env, cwd=directory)
        command([program], env=clean_env, cwd=directory)

        source.write_text('#include <sys/types.h>\n#include <unistd.h>\n'
                          'int main() { char buffer[1]; ssize_t n = read(-1, buffer, 1); '
                          'return n == -1 ? 42 : 1; }\n')
        command([prefix / "bin/crunch", source, "-o", program], env=clean_env, cwd=directory)
        expect(command([program], check=False).returncode == 42,
               "installed compiler could not use ssize_t and read")

        source.write_text('#include <sys/utsname.h>\n#include <sys/wait.h>\n'
                          '#include <sys/random.h>\n'
                          'int main() { struct utsname host; char byte; '
                          'return !uname(&host) && getrandom(&byte, 1, 0) == 1 && '
                          'WIFEXITED(0) ? 42 : 1; }\n')
        command([prefix / "bin/crunch", source, "-o", program], env=clean_env, cwd=directory)
        expect(command([program], check=False).returncode == 42,
               "installed compiler could not use bootstrap process headers")

        source.write_text('#include <sys/socket.h>\n#include <sys/un.h>\n'
                          '#include <sys/uio.h>\n#include <netinet/in.h>\n'
                          '#include <time.h>\n#include <signal.h>\n#include <unistd.h>\n'
                          'int main() { struct timespec t; t.tv_sec = 0; t.tv_nsec = 0; '
                          'int fd = socket(AF_UNIX, SOCK_STREAM, 0); '
                          'return fd >= 0 && !close(fd) && !nanosleep(&t, 0) ? 42 : 1; }\n')
        command([prefix / "bin/crunch", source, "-o", program], env=clean_env, cwd=directory)
        expect(command([program], check=False).returncode == 42,
               "installed compiler could not use socket and time headers")

        source.write_text('#include <stdint.h>\n'
                          'int main() { uint64_t n = UINT64_C(18446744073709551615); '
                          'return n == UINT64_MAX ? 42 : 1; }\n')
        command([prefix / "bin/crunch", source, "-o", program], env=clean_env, cwd=directory)
        expect(command([program], check=False).returncode == 42,
               "installed compiler could not use stdint.h")

        source.write_text('#include <ctype.h>\n'
                          "int main() { return isdigit('3') && toupper('a') == 'A' ? 42 : 1; }\n")
        command([prefix / "bin/crunch", source, "-o", program], env=clean_env, cwd=directory)
        expect(command([program], check=False).returncode == 42,
               "installed compiler could not use ctype.h")

        source.write_text('#include <stdio.h>\n'
                          'int main() { FILE *f = stdout; struct FILE *g = f; '
                          'return f == g ? 42 : 1; }\n')
        command([prefix / "bin/crunch", source, "-o", program], env=clean_env, cwd=directory)
        expect(command([program], check=False).returncode == 42,
               "installed compiler could not use the FILE typedef")

        source.write_text('#include <string.h>\n'
                          'struct Data { int value; }; int main() { struct Data d; '
                          'memset(&d, 0, sizeof(d)); return d.value == 0 ? 42 : 1; }\n')
        command([prefix / "bin/crunch", source, "-o", program], env=clean_env, cwd=directory)
        expect(command([program], check=False).returncode == 42,
               "installed compiler could not use memory functions with object pointers")

        source.write_text("int main() { return 42; }\n")
        command([prefix / "bin/crunch", "--with-crunch-as", source, "-o", program],
                env=clean_env, cwd=directory)
        expect(command([program], check=False).returncode == 42,
               "installed compiler could not use its experimental assembler")

        conf.write_text("assembler = crunch\nlinker = crunch\n")
        result = command([prefix / "bin/crunch", "-v", source, "-o", program],
                         env=clean_env, cwd=directory)
        expect(str(prefix / "bin/crunch-ld") in result.stderr and
               command([program], check=False).returncode == 42,
               "installed compiler could not use its configured native linker")
        installed_obj = directory / "installed.o"
        command([prefix / "bin/crunch", "-c", source, "-o", installed_obj],
                env=clean_env, cwd=directory)
        command([prefix / "bin/crunch", installed_obj, "-o", program], env=clean_env, cwd=directory)
        expect(command([program], check=False).returncode == 42,
               "installed compiler could not link its native relocatable output")

        configured_tools = []
        for name in ("crunch-as", "crunch-ld", "crunch-ar"):
            path = directory / f"installed {name}"
            path.symlink_to(prefix / "bin" / name)
            configured_tools.append(path)
        conf.write_text(f"assembler = crunch\nlinker = crunch\n"
                        f"assembler_path = {configured_tools[0]}\n"
                        f"linker_path = {configured_tools[1]}\n"
                        f"archiver_path = {configured_tools[2]}\n")
        installed_helper = directory / "helper.bc"
        installed_helper.write_text("int answer() { return 42; }\n")
        source.write_text("int answer(); int main() { return answer(); }\n")
        archive = directory / "installed.a"
        command([prefix / "bin/crunch", "-c", installed_helper, "-o", installed_obj],
                env=clean_env, cwd=directory)
        result = command([prefix / "bin/crunch", "--archive", "-v", "-o", archive, installed_obj],
                         env=clean_env, cwd=directory)
        expect(str(configured_tools[2]) in result.stderr, "installed archiver path was ignored")
        result = command([prefix / "bin/crunch", "-v", source, archive, "-o", program],
                         env=clean_env, cwd=directory)
        expect(str(configured_tools[0]) in result.stderr and str(configured_tools[1]) in result.stderr and
               command([program], check=False).returncode == 42,
               "installed tool paths were ignored or produced an unusable archive")
        default_archive = prefix / "lib/libinstalled.a"
        shutil.copy2(archive, default_archive)
        conf.write_text(default_conf)
        command([prefix / "bin/crunch", source, "-linstalled", "-o", program],
                env=clean_env, cwd=directory)
        expect(command([program], check=False).returncode == 42,
               "installed compiler did not search PREFIX/lib from its configuration")
        conf.write_text("")
        command([prefix / "bin/crunch", source, "-linstalled", "-o", program],
                env=clean_env, cwd=directory)
        expect(command([program], check=False).returncode == 42,
               "installed compiler did not use its compiled-in PREFIX/lib default")
        conf.write_text(f"library_path = {directory / 'missing-libraries'}\n")
        result = command([prefix / "bin/crunch", source, "-linstalled", "-o", program],
                         env=clean_env, cwd=directory, check=False)
        expect(result.returncode != 0 and "cannot find library" in result.stderr,
               "configured library path did not replace the default")
        default_archive.unlink()

        conf.write_text(f"include_path = {prefix / 'include/crunch'}\n")
        library = directory / "library.bc"
        library.write_text(
            '#include <stdlib.h>\n#include <string.h>\n#include <stdio.h>\n'
            '#include <errno.h>\n#include <limits.h>\n#include <stddef.h>\n'
            '#include <unistd.h>\n#include <fcntl.h>\n#include <sys/stat.h>\n'
            '#include <sys/mman.h>\n#include <sys/select.h>\n#include <signal.h>\n'
            '#include <poll.h>\n#include <dirent.h>\n'
            'int main() {\n'
            '  int *null_pointer = NULL; size_t size = sizeof(int); '
            'if (null_pointer != NULL || size != 4) exit(18);\n'
            '  if (LONG_MIN + LONG_MAX != -1 || UINT_MAX != 4294967295U) exit(16);\n'
            '  if (atoi("42") != 42 || O_RDONLY != 0 || SIGTERM != 15 || MAP_PRIVATE != 2 || DT_DIR != 4) exit(17);\n'
            '  char line[2]; if (input(line, 1) != 1 || line[0] != 90 || line[1] != 0) exit(12);\n'
            '  if (errno != 0) exit(10);\n'
            '  if (file_close(-1) != -1 || errno != EBADF) exit(11);\n'
            '  if (close(-1) != -1 || errno != EBADF) exit(13);\n'
            '  if (lseek(-1, 0, SEEK_SET) != -1 || errno != EBADF) exit(15);\n'
            '  struct stat info; if (stat(".", &info) != 0) exit(14);\n'
            '  char a[] = "abc"; char b[] = "abc"; char c[8];\n'
            '  memset(c, 120, 3); c[3] = (char)0;\n'
            '  memcpy(c, a, 4);\n'
            '  if (strlen(c) != 3) exit(1);\n'
            '  if (strcmp(a, b) != 0) exit(2);\n'
            '  if (memcmp(a, b, 3) != 0) exit(3);\n'
            '  printf("%d;%f;", 123, 1.5);\n'
            '  exit(42);\n  return 0;\n}\n')
        library_program = directory / "library"
        command([prefix / "bin/crunch", library, "-o", library_program], env=clean_env, cwd=directory)
        result = command([library_program], input="Z\n", check=False)
        expect(result.returncode == 42 and result.stdout.startswith("123;") and result.stdout.endswith(";"),
               f"installed compiler failed to link every library function: {result.returncode} {result.stdout!r}")
        conf.write_text(f"include_path = {extra}\n")

        reinstall = command(make + ["install"], env=clean_env, timeout=300)
        expect(f"include_path = {extra}" in conf.read_text() and
               "keeping existing" in reinstall.stdout,
               "reinstall overwrote an existing configuration file")

        uninstall = command(make + ["uninstall"], env=clean_env)
        expect(not (prefix / "bin/crunch").exists() and
               not (prefix / "include/crunch").exists() and
               not (prefix / "lib/crunch/libcrunch.a").exists() and
               not installed_shared.exists() and
               not (prefix / "lib/crunch/libcrunch.so.1").exists(),
               "uninstall left binaries, headers, or the library behind")
        expect(conf.exists() and "keeping modified" in uninstall.stdout,
               "uninstall removed a modified configuration file")

        conf.write_text(default_conf)
        command(make + ["install"], env=clean_env, timeout=300)
        command(make + ["uninstall"], env=clean_env)
        expect(not conf.exists() and not conf.parent.exists(),
               "uninstall left the unmodified default configuration behind")
        expect(not (prefix / "share/man/man1/crunch.1").exists(), "uninstall left the man page")
        expect(not (prefix / "share/man/man1/crunch-ar.1").exists(),
               "uninstall left the archiver man page")
        expect(not linker_manual.exists(), "uninstall left the linker man page")
        expect(not any((manual_dir / f"{name}.3crunch").exists() for name in manual_names),
               "uninstall left a Crunch library man page")

def preprocessor_continuation_case():
    """Check multiline definitions, source mapping, and continuation boundaries.

    Returns:
        None; raises AssertionError for incorrect expansion or diagnostics.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-preprocessor-continuation-") as td:
        directory = pathlib.Path(td)
        source, executable = directory / "source.bc", directory / "program"
        source.write_bytes(
            b"/* leading comment */ #define VA\\\nL 1\\\n2\n"
            b"#macro AD\\\nD(a,\\\n b) ((a)+\\\n(b))\n"
            b'#define TEXT "hel\\\r\nlo"\r\n'
            b"#define COMMENT 3 /* comment \\\n continued */ + 4 // tail \\\n discarded #endif\n"
            b"#define FLAG \\\n\n"
            b"#if 0\n#define IGNORED x \\\n#endif\n#endif\n"
            b"#ifdef IGNORED\n#error inactive macro was defined\n#endif\n"
            b"#ifdef FLAG\n"
            b'int printf(const char* format); int main() { printf("%s", TEXT); return ADD(VAL, 30) + COMMENT - 7; }\n'
            b"#endif\n")
        for separate in (False, True):
            if separate:
                obj = directory / "program.o"
                command([DRIVER, "-c", source, "-o", obj])
                command([DRIVER, obj, "-o", executable])
            else:
                command([DRIVER, source, "-o", executable])
            result = command([executable], check=False)
            expect(result.returncode == 42 and result.stdout == "hello",
                   f"continued definitions failed: {result.returncode} {result.stderr}")
        source.write_text("#define SPLIT(x,\\\n x) x\n")
        result = command([PP, source], check=False)
        expect(result.returncode != 0 and "duplicate parameter" in result.stderr and
               "line 1" in result.stderr, f"continued macro diagnostic: {result.stderr}")
        source.write_bytes(b"#macro VALUE 1 + \\\n 2 + \\\n \0\n")
        result = command([PP, source], check=False)
        expect(result.returncode != 0 and f"{source}:3: raw NUL byte" in result.stderr,
               f"continued line NUL location was incorrect: {result.stderr}")
        source.write_text("#define NUMBER 1 + \\\n 2\nint main() { return missing; }\n")
        result = command([DRIVER, "--emit-ir", source], check=False)
        expect(result.returncode != 0 and f"{source}:3:" in result.stderr,
               f"source mapping after continuation was incorrect: {result.stderr}")
        header = directory / "continued.h"
        header.write_text("#macro NUMBER 1 + \\\n 2\nint bad() { return missing; }\n")
        source.write_text('#include "continued.h"\nint main() { return 0; }\n')
        result = command([DRIVER, "--emit-ir", source], check=False)
        expect(result.returncode != 0 and f"{header}:3:" in result.stderr,
               f"included file mapping after continuation was incorrect: {result.stderr}")
        source.write_text("int a; \\\nint b;\n#define X 3 \\ \nint c;\n")
        expanded = command([PP, source]).stdout
        expect("int a; int b;\n" in expanded and "int c;\n" in expanded,
               "ordinary source continuation or backslash followed by spaces mishandled")
        source.write_bytes(
            b"#if defined(\\\r\n__CRUNCH__) && \\\n 1\n"
            b"int cho\\\nsen = 42;\n"
            b"// ignored \\\n#error continued comment\n"
            b"#el\\\nse\n#error wrong branch\n#endif\n")
        expanded = command([PP, source]).stdout
        expect("int chosen = 42;" in expanded and "#error continued comment" in expanded,
               f"splicing before directives and comments failed: {expanded}")
        source.write_text("#if 1 && \\\n 1\n#endif\nint main() { return missing; }\n")
        result = command([DRIVER, "--emit-ir", source], check=False)
        expect(result.returncode != 0 and f"{source}:4:" in result.stderr,
               f"source mapping after conditional continuation was incorrect: {result.stderr}")
        source.write_text("#if 1\n#endif /* comment\n"
                          "must not leak */ int marker;\n"
                          "/* open comment\nclosing */ #if 1\n"
                          "int other;\n#endif\n")
        expanded = command([PP, source]).stdout
        expect("must not leak" not in expanded and "int marker;" in expanded,
               f"directive comment leaked into output: {expanded}")
        lexed = command([BUILD / "crunch-lexer", "-"], input=expanded)
        expect(lexed.stdout.count("INT\t") == 2,
               "directive comment left invalid lexer input")
        header.write_text("int from_header;\n")
        source.write_text('#include \\\n "continued.h"\nint after_header;\n')
        expanded = command([PP, source]).stdout
        expect("int from_header;" in expanded and "int after_header;" in expanded,
               "continued include did not include its header")
        source.write_text("#define VALUE 42\\\n")
        expect(command([PP, source], check=False).returncode == 0,
               "a continuation ending at EOF was rejected")
        lines = (
            "#define ID(x) x\n#define ORIGIN(x) (__LINE__ + x)\n"
            "#line 50 \"virtual.bc\"\n"
            "int first = __LINE__ + \\\n__LINE__;\n"
            "int split = __LI\\\nNE__ + __LINE__;\n"
            "int arg = ORIGIN(\\\n__LINE__) + __LINE__;\n"
            "int nested = ID(\n__LINE__ \\\r\n+ __LINE__);\n"
            "#if \\\n__LINE__ == 60\nint condition = 1;\n"
            "#elif __LINE__ == 62\nint condition = 2;\n#endif\n")
        expanded = command([PP, "-"], input=lines).stdout
        pattern = r'"(?:\\.|[^"\\])*"|[A-Za-z_][A-Za-z_0-9]*|[0-9]+|[^\s]'
        actual = re.sub(r"/\*[^*]*(?:\*(?!/)[^*]*)*\*/|//[^\n]*", "", expanded)
        gcc = shutil.which("gcc")
        if gcc:
            reference = command([gcc, "-E", "-P", "-x", "c", "-"], input=lines).stdout
            expect(re.findall(pattern, actual) == re.findall(pattern, reference),
                   f"spliced physical line numbers differ from GCC: {actual} vs {reference}")
        expect("int condition = 1;" in actual and "condition = 2" not in actual,
               f"spliced line numbers in conditionals are wrong: {actual}")
        source.write_text("#define ID(x) x\nint main(void) { return ID(\\\n__LINE__) + 39; }\n")
        command([DRIVER, "--static", source, "-o", executable])
        expect(command([executable], check=False).returncode == 42,
               "spliced macro argument used the wrong physical line")
        (directory / "4").write_text("int found_header;\n")
        (directory / "8").write_text("int included_header;\n")
        headers = ("#define S1(x) #x\n#define S(x) S1(x)\n"
                   "#if __has_include(S(\\\n__LINE__))\nint found;\n#endif\n"
                   "#include S(\\\n__LINE__)\n")
        expanded = command([PP, "-I", directory, "-"], input=headers).stdout
        expect("int found;" in expanded and "int included_header;" in expanded,
               f"spliced line numbers in header operands are wrong: {expanded}")
        if gcc:
            reference = command([gcc, "-E", "-P", "-x", "c", "-I", directory, "-"],
                                input=headers).stdout
            actual = re.sub(r"/\*CRUNCH-PP-MAP:[^*]*\*/", "", expanded)
            expect(actual.split() == reference.split(),
                   "spliced header operand selection differs from GCC")

def preprocessor_multiline_macro_case():
    """Check multiline calls, source locations, comments and assembler input.

    Returns:
        None; raises AssertionError for incorrect expansion or diagnostics.
    """
    source = (
        "#define ADD(x,y) ((x)+(y))\n"
        "#define ID(x) x\n#define STR(x) #x\n#define CAT(x,y) x##y\n"
        "#define VAR(x,...) ADD(x,__VA_ARGS__)\n"
        "#define LINE(x) (__LINE__ + x)\n"
        "#line 40 \"virtual.bc\"\n"
        "int located = LINE(\n__LINE__\n) + __LINE__;\n"
        'const char *text = STR(first // comment containing ),\n second);\n'
        "int CAT(val,\nue) = ID\n(20) + ID(\n22);\n"
        "int capability = __has_builtin(\ncrunch_unknown_builtin);\n"
        "int spliced = ADD(\n20, \\\n22);\n"
        "int main(void) { return VAR(\n20,\nADD(20,\n2)); }\n")
    expanded = command([PP, "-"], input=source).stdout
    pattern = r'"(?:\\.|[^"\\])*"|[A-Za-z_][A-Za-z_0-9]*|[0-9]+|[^\s]'
    gcc = shutil.which("gcc")
    if gcc:
        reference = command([gcc, "-E", "-P", "-x", "c", "-"], input=source).stdout
        actual = re.sub(r"/\*[^*]*(?:\*(?!/)[^*]*)*\*/|//[^\n]*", "", expanded)
        expect(re.findall(pattern, actual) == re.findall(pattern, reference),
               f"multiline macro expansion differs from GCC: {actual} vs {reference}")
    expect('"first second"' in expanded and "value" in expanded,
           f"multiline stringification or token pasting failed: {expanded}")
    with tempfile.TemporaryDirectory(prefix="crunch-multiline-macro-") as td:
        directory = pathlib.Path(td)
        executable = directory / "program"
        command([DRIVER, "--static", "-o", executable, "-"], input=source)
        expect(command([executable], check=False).returncode == 42,
               "multiline macro program did not execute")
        for suffix, expected in ((") + missing;\n", 121), (");\nint b = missing;\n", 122)):
            diagnostic = ('#define ID(x) x\n#line 120 "virtual.bc"\n'
                          'int a = ID(\n1' + suffix)
            result = command([DRIVER, "--emit-ir", "-"], input=diagnostic, check=False)
            expect(result.returncode != 0 and f"virtual.bc:{expected}:" in result.stderr,
                   f"incorrect location following multiline invocation: {result.stderr}")
        repeated = ('#define TWICE(x) ((x)+(x))\n#line 100 "virtual.bc"\n'
                    'int main(void) { return TWICE(\n1 + missing\n); }\n')
        result = command([DRIVER, "--emit-ir", "-"], input=repeated, check=False)
        locations = re.findall(r"virtual\.bc:(\d+):\d+: error", result.stderr)
        expect(result.returncode != 0 and locations == ["100", "100"],
               f"duplicated macro arguments acquired incorrect locations: {result.stderr}")
        asm = directory / "helper.S"
        asm.write_text("#define ADD(a,b) ((a)+(b))\n.text\n.globl helper\nhelper:\n"
                       "mov $ADD(20, // comment\n22), %eax\nret\n"
                       '.section .note.GNU-stack,"",@progbits\n')
        main = directory / "main.bc"
        main.write_text("int helper(void); int main(void) { return helper(); }\n")
        command([DRIVER, "--static", main, asm, "-o", executable])
        expect(command([executable], check=False).returncode == 42,
               "multiline assembler macro did not execute")
    boundary = ("#define F(x) x\nF\n#define VALUE 42\n"
                "#if 0\nF(\n#error inactive\n#endif\nint value = VALUE;\n")
    output = command([PP, "-"], input=boundary).stdout
    expect("int value = 42;" in output, "directive or inactive branch after a macro was mishandled")
    open_comment = ("#define F(x) x\nint first = F(\n1); /* comment\n"
                    "continued */\nint second = F(\n2); /* comment\n"
                    "continued */ #define VALUE 42\n"
                    "int main(void) { return VALUE; }\n")
    with tempfile.TemporaryDirectory(prefix="crunch-multiline-comment-") as directory:
        executable = pathlib.Path(directory) / "program"
        command([DRIVER, "--static", "-o", executable, "-"], input=open_comment)
        expect(command([executable], check=False).returncode == 42,
               "source markers corrupted a comment following a multiline call")
    recursive = "#define SELF(x) SELF(x)\nSELF(\n1)\n"
    result = command([PP, "-"], input=recursive).stdout
    expect(re.search(r"\bSELF\s*\(\s*1\s*\)", result) is not None,
           "recursive macro suppression failed across lines")
    empty = "#define ONE(x) 1\n#define VAR(x,...) x\nONE(\n) VAR(\n42)"
    result = command([PP, "-"], input=empty).stdout
    expect(re.search(r"\b1\s+42\b", re.sub(r"/\*[^*]*\*/", "", result)) is not None,
           "empty or omitted multiline macro arguments failed")
    for bad in ("#define F(x) x\nF(\n1\n",
                "#define F(x) x\nF(\n1,2)\n",
                "#define F(x) x\nF(\n#define VALUE 1\nVALUE)\n"):
        result = command([PP, "-"], input=bad, check=False)
        expect(result.returncode != 0, "invalid multiline macro call was accepted")


def preprocessor_macro_comment_case():
    """Check block comments between function-like macro names and invocations.

    Returns:
        None; raises AssertionError for incorrect expansions or diagnostics.
    """
    source = (
        "#define ADD(a,b) ((a)+(b))\n#define TWICE(x) ((x)+(x))\n"
        "#define WRAPPED(x) TWICE/**/(x)\n"
        "#define STR(x) #x\n"
        "#if ADD/**/(1,1) == 2\n"
        "int ADD/**/;\n"
        'char *text = STR/*name*/(hello/**/world);\n'
        "int main(void) { return ADD /* one */ /**/ (WRAPPED/**/(20), 2); }\n"
        "#else\n#error invocation in conditional failed\n#endif\n")
    expanded = command([PP, "-"], input=source).stdout
    pattern = r'"(?:\\.|[^"\\])*"|[A-Za-z_][A-Za-z_0-9]*|[0-9]+|[^\s]'
    actual = re.sub(r"/\*[^*]*(?:\*(?!/)[^*]*)*\*/", "", expanded)
    gcc = shutil.which("gcc")
    if gcc:
        reference = command([gcc, "-std=c11", "-E", "-P", "-x", "c", "-"],
                            input=source).stdout
        expect(re.findall(pattern, actual) == re.findall(pattern, reference),
               f"comment-separated macro invocation differs from GCC: {actual} vs {reference}")
    expect("int ADD" in actual and '"hello world"' in actual,
           f"comments or a non-invoked macro were mishandled: {actual}")
    with tempfile.TemporaryDirectory(prefix="crunch-macro-comment-") as td:
        directory = pathlib.Path(td)
        executable = directory / "program"
        command([DRIVER, "--static", "-o", executable, "-"], input=source)
        expect(command([executable], check=False).returncode == 42,
               "comment-separated macro program did not execute")
        (directory / "header.h").write_text("int from_header;\n")
        include = '#define STR(x) #x\n#include STR/**/(header.h)\n'
        output = command([PP, "-I", directory, "-"], input=include).stdout
        expect("int from_header;" in output, "comment-separated include macro did not expand")
    line = "#define NUM(x) x\n#line NUM/**/(42)\nint line = __LINE__;\n"
    expect("int line = 42;" in command([PP, "-"], input=line).stdout,
           "comment-separated #line macro did not expand")
    continued = "#define ID(x) x\nint value = ID/*comment*/\\\n(42);\n"
    output = command([PP, "-"], input=continued).stdout
    output = re.sub(r"/\*CRUNCH-PP-MAP:[^*]*\*/\n", "", output)
    expect("int value = 42;" in output,
           "comment-separated macro after line splicing did not expand")
    invalid = command([PP, "-"], input="#define F(x) x\nF/**/(1, 2)\n", check=False)
    expect(invalid.returncode != 0 and "expects 1 argument" in invalid.stderr,
           "wrong argument count after a comment was not rejected")


def preprocessor_empty_macro_case():
    """Check empty replacements, their definedness and macro argument expansion.

    Returns:
        None; raises AssertionError for incorrect expansions or diagnostics.
    """
    source = (
        "#define EMPTY /* comment */\n#define EMPTY\n"
        "#define STR(x) #x\n#define EXPAND_STR(x) STR(x)\n"
        "#define CAT(a,b) a##b\n#define EXPAND_CAT(a,b) CAT(a,b)\n"
        "#if defined(EMPTY) && EMPTY 1 && 1 +EMPTY+ 1 == 2\n"
        "EMPTY int EXPAND_CAT(EMPTY,value) = 42;\n"
        "char *raw = STR(EMPTY); char *expanded = EXPAND_STR(EMPTY);\n"
        "#else\n#error defined empty macro failed\n#endif\n"
        "#undef EMPTY\n#ifndef EMPTY\nint undefined_after_undef;\n#endif\n")
    expanded = command([PP, "-"], input=source).stdout
    pattern = r'"(?:\\.|[^"\\])*"|[A-Za-z_][A-Za-z_0-9]*|[0-9]+|[^\s]'
    actual = re.sub(r"/\*CRUNCH-PP-MAP:[^*]*\*/", "", expanded)
    tokens = re.findall(pattern, actual)
    expect(tokens == ["int", "value", "=", "42", ";", "char", "*", "raw", "=",
                      '"EMPTY"', ";", "char", "*", "expanded", "=", '""', ";",
                      "int", "undefined_after_undef", ";"],
           f"empty macro expansion failed: {actual}")
    gcc = shutil.which("gcc")
    if gcc:
        reference = command([gcc, "-std=c11", "-E", "-P", "-x", "c", "-"],
                            input=source).stdout
        expect(tokens == re.findall(pattern, reference),
               f"empty macro expansion differs from GCC: {actual} vs {reference}")
    invalid = command([PP, "-"], input="#define EMPTY\n#if EMPTY\n#endif\n", check=False)
    expect(invalid.returncode != 0, "an empty #if expression was accepted")
    cli_source = ("#if FLAG && defined(EMPTY)\n"
                  "EMPTY int value = FLAG;\n#endif\n")
    cli_output = command([PP, "-DFLAG", "-DEMPTY=", "-"], input=cli_source).stdout
    expect("int value = 1;" in cli_output and "EMPTY" not in cli_output,
           f"command-line empty or bare definition expanded incorrectly: {cli_output}")
    if gcc:
        reference = command([gcc, "-E", "-P", "-x", "c", "-DFLAG", "-DEMPTY=", "-"],
                            input=cli_source).stdout
        actual = re.sub(r"/\*CRUNCH-PP-MAP:[^*]*\*/", "", cli_output)
        expect(re.findall(pattern, actual) == re.findall(pattern, reference),
               "command-line macro expansion differs from GCC")
    program = ("#define EMPTY\n#define P(x) x\n"
               "EMPTY int main(void) { return P(EMPTY 40 +EMPTY+ 2); }\n")
    with tempfile.TemporaryDirectory(prefix="crunch-empty-macro-") as td:
        executable = pathlib.Path(td) / "program"
        command([DRIVER, "--static", "-o", executable, "-"], input=program)
        expect(command([executable], check=False).returncode == 42,
               "empty macro program did not execute")


def preprocessor_has_include_case():
    """Check header-availability queries, search paths and diagnostics.

    Returns:
        None; raises AssertionError for incorrect results or diagnostics.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-has-include-") as td:
        root = pathlib.Path(td)
        first, second = root / "first", root / "second"
        first.mkdir()
        second.mkdir()
        (root / "local.h").write_text("#error must not be included\n")
        (first / "defined.h").write_text("#error must not be included\n")
        (first / "comma,name.h").write_text("")
        (first / "only-first.h").write_text("")
        (second / "present.h").write_text("")
        (first / "directory.h").mkdir()
        (first / "wrapper.h").write_text(
            "#if __has_include_next(<present.h>) && "
            "!__has_include_next(<only-first.h>)\nint next_found = 2;\n"
            "#else\n#error incorrect include-next lookup\n#endif\n")
        source = root / "source.bc"
        source.write_text(
            '#define local wrong\n#define present wrong\n'
            '#define H <defined.h>\n#define QUERY __has_include\n'
            '#define ALIAS QUERY\n#define STRING(x) #x\n'
            '#define CHECK(x) __has_include(x)\n#define IGNORE(x) 1\n'
            '#if defined(__has_include) && defined(__has_include_next) && '
            '__has_include("local.h") && !__has_include(<local.h>) && '
            '__has_include(<defined.h>) && __has_include(<comma,name.h>) && '
            '__has_include(H) && ALIAS(<defined.h>) && ALIAS(<present.h>) && '
            '__has_include(STRING(defined.h)) && CHECK("defined.h") && '
            'CHECK(<defined.h>) && IGNORE(defined + 1) && '
            'IGNORE(__has_include(invalid tokens)) && '
            '!__has_include(STRING(__has_include(invalid))) && '
            '!__has_include(<directory.h>) && '
            '!__has_include(<crunch-missing-header.h>)\nint found = 40;\n'
            '#else\n#error incorrect header availability\n#endif\n'
            '#include <wrapper.h>\n'
            '#if 0\n#if __has_include(invalid tokens)\n#error inactive\n#endif\n#endif\n'
            'int main(void) { return found + next_found; }\n')
        flags = ["-I", first, "-I", second]
        env = dict(os.environ, CRUNCH_CONF_FILE=str(root / "absent.conf"))
        env.pop("CRUNCH_INCLUDE_PATH", None)
        expanded = command([PP, *flags, source], env=env).stdout
        pattern = r"int\s+(found|next_found)\s*=\s*(\d+)"
        expect(re.findall(pattern, expanded) == [("found", "40"), ("next_found", "2")],
               f"header availability checks failed: {expanded}")
        gcc = shutil.which("gcc")
        if gcc:
            reference = command([gcc, "-E", "-P", "-x", "c", *flags, source]).stdout
            expect(re.findall(pattern, expanded) == re.findall(pattern, reference),
                   "header availability results differ from GCC")
        exe = root / "program"
        command([DRIVER, "--static", *flags, source, "-o", exe], env=env)
        expect(command([exe], check=False).returncode == 42,
               "header-availability program did not execute")
        overridden = ("#undef __has_include\n#ifdef __has_include\n#error still defined\n#endif\n"
                      "#define __has_include(x) 1\n#if __has_include(anything)\nint overridden;\n#endif\n")
        expect("int overridden;" in command([PP, "-"], input=overridden, env=env).stdout,
               "header query could not be undefined and overridden")
        expect("int value;" in command([PP, "-D__has_include=0", "-"], env=env, input=
                                       "#if __has_include == 0\nint value;\n#endif\n").stdout,
               "command-line override of header query failed")
        defined_argument = ("#define ID(x) x\n#define FLAG 1\n"
                            "#if ID(defined(FLAG))\n#endif\n")
        actual = command([PP, "-"], env=env, input=defined_argument, check=False)
        expect(actual.returncode != 0, "expanded defined operand was accepted")
        if gcc:
            expect(command([gcc, "-E", "-x", "c", "-"], input=defined_argument,
                           check=False).returncode != 0,
                   "GCC unexpectedly accepted expanded defined operand")
        for expression in ("__has_include()", "__has_include(<missing.h>",
                           "__has_include(invalid tokens)", '__has_include("/bad.h")',
                           "__has_include(<present.h> extra)",
                           "0 && __has_include(invalid tokens)"):
            result = command([PP, *flags, "-"], env=env, check=False,
                             input=f"#if {expression}\n#endif\n")
            expect(result.returncode != 0 and "invalid #if expression" in result.stderr,
                   f"invalid header availability expression accepted: {expression}")


def preprocessor_pack_case():
    """Check packing state, token interchange, source maps and GCC interoperability.

    Returns:
        None; raises AssertionError for incorrect packing or diagnostics.
    """
    with tempfile.TemporaryDirectory(prefix="pack-test-", dir=BUILD) as td:
        root = pathlib.Path(td)
        (root / "pack.h").write_text(
            "#pragma pack(push, 4)\nstruct Header { char a; int b; };\n")
        source = ('#define ALIGNMENT 2\n'
                  '#pragma /* space */ pack ( push , ALIGNMENT )\n'
                  'struct Before { char a; int b; };\n'
                  '#include "pack.h"\n'
                  '#pragma pack(pop)\n'
                  '#if 0\n#pragma pack(bad, unsupported)\n#endif\n'
                  'struct After { char a; int b;\n'
                  '#pragma pack(1)\n};\n'
                  '#pragma pack(pop)\n'
                  '#line 70 "mapped.bc"\nint mapped;\n')
        expanded = command([PP, "-I", root, "-"], input=source).stdout
        expect(re.findall(r"^#pragma pack\((\d+)\)$", expanded, re.M) ==
               ["2", "4", "2", "1", "0"], f"incorrect pack state: {expanded}")
        lexed = command([LEXER, "-"], input=expanded).stdout
        lines = lexed.splitlines()
        expect(lines[0] == "CRUNCH-TOKENS 2", "packed stream did not use v2")
        records = [line.split("\t") for line in lines[1:]]
        braces = [r for r in records if r[0] == "RBRACE"]
        expect([r[5] for r in braces] == ["2", "4", "1"],
               f"closing braces lost current packing: {braces}")
        mapped = next(r for r in records if r[4] == "6d6170706564")
        expect(mapped[2] == "70" and mapped[5] == "0",
               f"packing corrupted source location: {mapped}")
        tree = json.loads(command([PARSER], input=lexed).stdout)
        expect(tree["version"] == 43 and
               {d["name"]: d.get("pack_alignment") for d in tree["declarations"]
                if d.get("kind") == "struct"} ==
               {"Before": 2, "Header": 4, "After": 1},
               "AST did not preserve packed structure alignment")
        v1 = command([LEXER, "-"], input="int value;\n").stdout
        expect(v1 == ("CRUNCH-TOKENS 1\nINT\t0\t1\t1\t696e74\n"
                      "IDENTIFIER\t4\t1\t5\t76616c7565\n"
                      "SEMICOLON\t9\t1\t10\t3b\nEOF\t11\t2\t1\t-\n"),
               f"version 1 stream changed: {v1}")
        command([PARSER], input=v1)
        for bad in ("", "3", "17", "-1", "1x", "999999999999999999999"):
            invalid = lexed.replace("\t2\n", f"\t{bad}\n", 1)
            expect(command([PARSER], input=invalid, check=False).returncode != 0,
                   f"invalid v2 alignment accepted: {bad!r}")
        expect(command([PARSER], input=lexed.replace("\t2\n", "\t2\textra\n", 1),
                       check=False).returncode != 0, "extra v2 field accepted")
        for pragma in ("pack(pop)", "pack(3)", "pack(32)", "pack(push,)",
                       "pack(pop,1)", "pack(push,label,1)", "pack(1) extra",
                       "pack", "pack(1,2)"):
            result = command([PP, "-"], input=f"#pragma {pragma}\n", check=False)
            expect(result.returncode != 0 and "#pragma pack" in result.stderr,
                   f"unsupported pack accepted: {pragma}")
        direct = command([LEXER, "-"], input="#pragma pack(8)\nint x;\n").stdout
        expect("\t2\t1\t696e74\t8\n" in direct,
               f"standalone lexer lost packing or line mapping: {direct}")
        assembly = command([PP, "--assembly", "-"], input=
                           "#pragma pack(push,1)\n.byte 42\n#pragma pack(pop)\n").stdout
        expect("#pragma" not in assembly and ".byte 42" in assembly,
               f"packing leaked into assembly: {assembly}")
        gcc = shutil.which("gcc")
        if gcc:
            checks = ("\n_Static_assert(sizeof(struct Before)==6, \"before\");\n"
                      "_Static_assert(sizeof(struct Header)==8, \"header\");\n"
                      "_Static_assert(sizeof(struct After)==5, \"after\");\n")
            gcc_expanded = command([gcc, "-E", "-P", "-x", "c", "-"],
                                   input=expanded + checks).stdout
            command([gcc, "-fsyntax-only", "-x", "c", "-"], input=gcc_expanded)


def preprocessor_target_pragma_case():
    """Check GCC target controls survive preprocessing but cannot affect compilation.

    Returns:
        None; raises AssertionError for incorrect rejection or GCC comparison.
    """
    pragmas = ('GCC push_options', 'GCC pop_options', 'GCC reset_options',
               'GCC target("sse2,mmx")', 'GCC target("general-regs-only")',
               'GCC target("popcnt")', 'GCC target("rdrnd")',
               'GCC target("avx2")', 'GCC optimize("O3")')
    for pragma in pragmas:
        source = f"#pragma {pragma}\nint value;\n"
        preprocessed = command([PP, "-"], input=source).stdout
        expect(f"#pragma {pragma}" in preprocessed and "int value;" in preprocessed,
               f"target control was not preserved: {pragma}")
        lexed = command([LEXER, "-"], input=preprocessed, check=False)
        expect(lexed.returncode != 0 and "\nINVALID\t" in lexed.stdout,
               f"lexer accepted a preserved target control: {pragma}")
        compiled = command([IR, "-"], input=preprocessed, check=False)
        expect(compiled.returncode != 0 and
               "unsupported GCC pragma in compilation" in compiled.stderr,
               f"direct IR compilation accepted a preserved target control: {pragma}")
        result = command([DRIVER, "--emit-ir", "-"], input=source, check=False)
        expect(result.returncode != 0 and "unsupported GCC pragma in compilation" in result.stderr,
               f"target control was not rejected by compilation: {pragma}")
        result = command([PP, "--assembly", "-"], input=source, check=False)
        expect(result.returncode != 0 and "unsupported GCC option pragma in assembly" in result.stderr,
               f"target control was not rejected in assembly: {pragma}")
    inactive = "#if 0\n" + "".join(f"#pragma {item}\n" for item in pragmas) + \
               "#endif\nint value;\n"
    inactive_output = command([PP, "-"], input=inactive).stdout
    expect("int value;" in inactive_output and "#pragma GCC" not in inactive_output,
           "inactive target controls were not skipped")
    for pragma in ('GCC target_other("popcnt")', 'GCC unknown', 'unknown_directive'):
        result = command([PP, "-"], input=f"#pragma {pragma}\n", check=False)
        expect(result.returncode != 0 and "unsupported preprocessor directive" in result.stderr,
               f"unrelated pragma was unexpectedly accepted: {pragma}")
    feature_probe = ("#if __has_builtin(__builtin_ia32_rdrand32_step) || "
                     "__has_builtin(__builtin_popcount) || "
                     "__has_attribute(__vector_size__)\n"
                     "#error unsupported intrinsic capability advertised\n#endif\n"
                     "int unavailable;\n")
    expect("int unavailable;" in command([PP, "-"], input=feature_probe).stdout,
           "unsupported target intrinsic or vector attribute was advertised")
    with tempfile.TemporaryDirectory(prefix="crunch-target-pragma-") as directory:
        td = pathlib.Path(directory)
        (td / "target.h").write_text('#pragma GCC target("popcnt")\n')
        output = td / "output"
        result = command([DRIVER, "-E", "-I", td, "-"], input=
                         '#include <target.h>\nint value;\n')
        expect('#pragma GCC target("popcnt")' in result.stdout,
               "target control in an included header was not preserved")
        output.write_text("unchanged")
        result = command([DRIVER, "--emit-ir", "-I", td, "-o", output, "-"], check=False,
                         input='#include <target.h>\nint value;\n')
        expect(result.returncode != 0 and "unsupported GCC pragma in compilation" in result.stderr and
               "target.h" in result.stderr and output.read_text() == "unchanged",
               "target control in an included header did not fail compilation safely")
        assembly = td / "target.S"
        assembly.write_text('#pragma GCC target("popcnt")\n.byte 1\n')
        result = command([DRIVER, "-E", "-o", output, assembly], check=False)
        expect(result.returncode != 0 and "unsupported GCC option pragma in assembly" in result.stderr and
               output.read_text() == "unchanged",
               "assembly target control did not fail safely")
        comments = ('/* before\n*/ #pragma GCC /* gap */ target("popcnt") /* after\n'
                    'end */\nint value;\n')
        preprocessed = command([PP, "-"], input=comments).stdout
        compiled = command([IR, "-"], input=preprocessed, check=False)
        expect(compiled.returncode != 0 and "unsupported GCC pragma in compilation" in compiled.stderr,
               "comment handling hid a preserved target pragma")
        operator = '_Pragma("GCC target(\\"popcnt\\")")\nint value;\n'
        expect("_Pragma" in command([PP, "-"], input=operator).stdout and
               command([DRIVER, "--emit-ir", "-"], input=operator, check=False).returncode != 0,
               "unsupported _Pragma unexpectedly affected compilation")
    gcc = shutil.which("gcc")
    if gcc and os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
        source = ("int before(unsigned x) { return __builtin_popcount(x); }\n"
                  "#pragma GCC push_options\n#pragma GCC target(\"popcnt\")\n"
                  "int during(unsigned x) { return __builtin_popcount(x); }\n"
                  "#pragma GCC pop_options\n"
                  "int after(unsigned x) { return __builtin_popcount(x); }\n")
        assembly = command([gcc, "-O2", "-mno-popcnt", "-S", "-x", "c",
                            "-o", "-", "-"], input=source).stdout
        bodies = [assembly.split(f"{name}:\n", 1)[1].split(".size", 1)[0]
                  for name in ("before", "during", "after")]
        instruction = r"^\s*popcnt[lq]?\s"
        expect([bool(re.search(instruction, body, re.M)) for body in bodies] ==
               [False, True, False],
               "GCC target pragma did not scope POPCNT instruction generation")
        preserved = command([PP, "-"], input=source).stdout
        assembly = command([gcc, "-O2", "-mno-popcnt", "-S", "-x", "c",
                            "-o", "-", "-"], input=preserved).stdout
        bodies = [assembly.split(f"{name}:\n", 1)[1].split(".size", 1)[0]
                  for name in ("before", "during", "after")]
        expect([bool(re.search(instruction, body, re.M)) for body in bodies] ==
               [False, True, False],
               "preserved target pragmas changed GCC instruction generation")
        probe = ('#define OPTION "popcnt"\n'
                 '#pragma /* left */ GCC /* middle */ target(OPTION) // right\n'
                 '#pragma GCC push_options\n#pragma GCC pop_options\n')
        reference = command([gcc, "-E", "-P", "-x", "c", "-"], input=probe).stdout
        actual = command([PP, "-"], input=probe).stdout
        pattern = r"^#pragma[^\n]*"
        expect([line.strip() for line in re.findall(pattern, actual, re.M)] ==
               [line.strip() for line in re.findall(pattern, reference, re.M)],
               "preserved GCC option pragmas differ from GCC preprocessing")


def preprocessor_pragma_once_case():
    """Check pragma-once identity, recursion, conditionals and include-next.

    Returns:
        None; raises AssertionError for incorrect inclusion or diagnostics.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-pragma-once-") as td:
        root = pathlib.Path(td)
        first, second, third = root / "first", root / "second", root / "third"
        for directory in (first, second, third):
            directory.mkdir()
        header = root / "once.h"
        header.write_text('#pragma /* comment */ once\n#line 71 "logical.h"\n'
                          '#include "alias.h"\nint once_value = 40;\n')
        (root / "alias.h").symlink_to(header.name)
        os.link(header, root / "hardlink.h")
        (root / "conditional.h").write_text(
            "#if ENABLE\n#pragma once\n#endif\nint conditional_value;\n")
        source = root / "source.bc"
        source.write_text(
            '#include "once.h"\n#include "alias.h"\n#include "hardlink.h"\n'
            '#include "conditional.h"\n#define ENABLE 1\n'
            '#include "conditional.h"\n#include "conditional.h"\n')
        env = dict(os.environ, CRUNCH_CONF_FILE=str(root / "absent.conf"))
        env.pop("CRUNCH_INCLUDE_PATH", None)
        expanded = command([PP, source], env=env).stdout
        pattern = r"int\s+(once_value|conditional_value)\b"
        expect(re.findall(pattern, expanded) ==
               ["once_value", "conditional_value", "conditional_value"],
               f"pragma once identity, recursion or inactive handling failed: {expanded}")
        gcc = shutil.which("gcc")
        if gcc:
            reference = command([gcc, "-E", "-P", "-x", "c", source]).stdout
            expect(re.findall(pattern, expanded) == re.findall(pattern, reference),
                   "pragma-once inclusion differs from GCC")
        (first / "wrap.h").write_text(
            "#pragma once\nint first_wrapper;\n#include_next <wrap.h>\n")
        os.link(first / "wrap.h", second / "wrap.h")
        (third / "wrap.h").write_text("int third_wrapper;\n")
        flags = ["-I", first, "-I", second, "-I", third]
        next_source = "#include <wrap.h>\n"
        output = command([PP, *flags, "-"], input=next_source, env=env).stdout
        pattern = r"int\s+(first_wrapper|third_wrapper)\s*;"
        expect(re.findall(pattern, output) == ["first_wrapper"],
               f"include-next did not stop at an already included file: {output}")
        if gcc:
            reference = command([gcc, "-E", "-P", "-x", "c", *flags, "-"],
                                input=next_source).stdout
            expect(re.findall(pattern, output) == re.findall(pattern, reference),
                   "pragma once and include-next differ from GCC")
        (root / "extra.h").write_text("#pragma once extra\nint extra;\n")
        extra = command([PP, "-I", root, "-"], env=env, input=
                        '#include <extra.h>\n#include <extra.h>\n')
        expect(extra.stdout.count("int extra;") == 1 and
               "warning: extra tokens" in extra.stderr,
               f"pragma-once trailing tokens were mishandled: {extra.stderr}")
        (root / "assembly.h").write_text("#pragma once\n.byte 42\n")
        assembly = command([PP, "--assembly", "-I", root, "-"], env=env, input=
                           "#include <assembly.h>\n#include <assembly.h>\n").stdout
        expect(assembly.count(".byte 42") == 1,
               "pragma once did not work in preprocessed assembly")
        (root / "bad.h").write_text(
            '#line 91 "virtual-header.h"\n#pragma once\nint value = missing;\n')
        source.write_text('#include "bad.h"\n')
        result = command([DRIVER, "--emit-ir", source], env=env, check=False)
        expect(result.returncode != 0 and "virtual-header.h:92:" in result.stderr,
               f"pragma once lost logical source mapping: {result.stderr}")
        source.write_text('#pragma once\n#include "source.bc"\n'
                          'int main(void) { return 42; }\n')
        executable = root / "program"
        result = command([DRIVER, "--static", source, "-o", executable], env=env)
        expect("#pragma once in main file" in result.stderr and
               command([executable], check=False).returncode == 42,
               "pragma once in the main file did not prevent recursive inclusion")

        diagnostic = ('#pragma GCC diagnostic push\n'
                      '#pragma /* gap */ GCC diagnostic ignored "-pedantic"\n'
                      '#pragma GCC diagnostic ignored "-Wpedantic" /* gap */\n'
                      '#pragma GCC diagnostic pop\n'
                      '#if 0\n#pragma pack(1)\n#endif\n'
                      'int diagnostic_selection = 42;\n')
        output = command([PP, "-"], input=diagnostic, env=env).stdout
        expect("int diagnostic_selection = 42;" in output,
               "GCC pedantic diagnostic controls were not accepted")
        warning = command([PP, "-"], env=env, input=
                          '#pragma GCC diagnostic push\n'
                          '#pragma GCC diagnostic ignored "-Wpedantic"\n'
                          '#warning still visible\n'
                          '#pragma GCC diagnostic pop\n')
        expect("warning: still visible" in warning.stderr,
               "pedantic diagnostic control suppressed an unrelated warning")
        if gcc:
            reference = command([gcc, "-E", "-P", "-x", "c", "-"], input=diagnostic).stdout
            pattern = r"int\s+diagnostic_selection\s*=\s*(\d+)\s*;"
            expect(re.findall(pattern, output) == re.findall(pattern, reference) == ["42"],
                   "GCC diagnostic controls changed preprocessed declarations")
        assembly = command([PP, "--assembly", "-"], env=env, input=
                           '#pragma GCC diagnostic push\n'
                           '#pragma GCC diagnostic ignored "-Wpedantic"\n'
                           '#pragma GCC diagnostic pop\n.byte 42\n').stdout
        expect(".byte 42" in assembly, "diagnostic controls failed in assembly")
        for pragma in ('GCC diagnostic error "-Wpedantic"',
                       'GCC diagnostic ignored "-Wcpp"',
                       'GCC diagnostic push extra',
                       'GCC diagnostic ignored "-pedantic" extra'):
            rejected = command([PP, "-"], input=f"#pragma {pragma}\n", check=False)
            expect(rejected.returncode != 0 and
                   "unsupported preprocessor directive" in rejected.stderr,
                   f"unsafe or malformed pragma accepted: {pragma}")
        source.write_text('#pragma GCC diagnostic push\n'
                          '#pragma GCC diagnostic ignored "-Wpedantic"\n'
                          '#pragma GCC diagnostic pop\n'
                          'int main(void) { return missing; }\n')
        result = command([DRIVER, "--emit-ir", source], env=env, check=False)
        expect(result.returncode != 0 and f"{source}:4:" in result.stderr,
               f"diagnostic controls lost source line mapping: {result.stderr}")


def preprocessor_include_operand_case():
    """Check macro-expanded include operands and literal header-name handling.

    Returns:
        None; raises AssertionError for incorrect inclusion or diagnostics.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-include-macro-") as td:
        root = pathlib.Path(td)
        first, second, third = root / "first", root / "second", root / "third"
        first.mkdir()
        second.mkdir()
        third.mkdir()
        (root / "pick.h").write_text("int quoted_local = 1;\n")
        (root / "literalquote.h").write_text("int quoted_literal = 0;\n")
        (first / "pick.h").write_text("int angle_search = 2;\n")
        (first / "literal.h").write_text("int literal_header = 0;\n")
        (first / "wrapper.h").write_text(
            '#define NEXT_HEADER "wrapper.h"\n#include_next NEXT_HEADER\n')
        (second / "wrapper.h").write_text(
            "#define NEXT_ANGLE <wrapper.h>\n#include_next NEXT_ANGLE\n")
        (third / "wrapper.h").write_text("int next_header = 39;\n")
        source = root / "source.bc"
        source.write_text(
            '#define LOCAL "pick.h"\n#define ALIAS LOCAL\n#include ALIAS\n'
            '#define ANGLE <pick.h>\n#include ANGLE\n'
            '#define literal wrong\n#include /*comment*/ <literal.h>\n'
            '#define literalquote wrong\n#include "literalquote.h"\n'
            '#define STR(x) #x\n#define QUOTE(x) STR(x)\n'
            '#include QUOTE(wrapper.h) /* comment\nignored */\n'
            '#if 0\n#include MISSING(\n#endif\n'
            'int main(void) { return quoted_local + angle_search + next_header; }\n')
        env = dict(os.environ, CRUNCH_CONF_FILE=str(root / "absent.conf"))
        env.pop("CRUNCH_INCLUDE_PATH", None)
        flags = ["-I", first, "-I", second, "-I", third]
        expanded = command([PP, *flags, source], env=env).stdout
        pattern = r"int\s+(quoted_local|angle_search|literal_header|quoted_literal|next_header)\s*=\s*(\d+)"
        expected = [("quoted_local", "1"), ("angle_search", "2"),
                    ("literal_header", "0"), ("quoted_literal", "0"), ("next_header", "39")]
        expect(re.findall(pattern, expanded) == expected,
               f"expanded include search failed: {expanded}")
        expect("ignored" not in expanded, "trailing multiline comment leaked into output")
        gcc = shutil.which("gcc")
        if gcc:
            reference = command([gcc, "-E", "-P", "-x", "c", *flags, source]).stdout
            expect(re.findall(pattern, expanded) == re.findall(pattern, reference),
                   "macro-expanded include search differs from GCC")
        exe = root / "program"
        command([DRIVER, "--static", *flags, source, "-o", exe], env=env)
        expect(command([exe], check=False).returncode == 42,
               "macro-expanded includes did not compile and execute")
        for text in ('#include UNKNOWN\n', '#define H 42\n#include H\n',
                     '#define H "pick.h" trailing\n#include H\n',
                     '#define H "/pick.h"\n#include H\n',
                     '#define H <pick.h\n#include H\n'):
            result = command([PP, "-I", first, "-"], input=text, env=env, check=False)
            expect(result.returncode != 0 and "crunch-pp:" in result.stderr,
                   f"invalid include operand was not rejected: {text!r}")
        source.write_text('#define H "pick.h"\n#include H\nint main(void) { return missing; }\n')
        result = command([DRIVER, "--emit-ir", source], env=env, check=False)
        expect(result.returncode != 0 and f"{source}:3:" in result.stderr,
               f"source mapping after expanded include was incorrect: {result.stderr}")


def preprocessor_include_next_case():
    """Check include-next search provenance, duplicate directories and diagnostics.

    Returns:
        None; raises AssertionError for incorrect include resolution.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-include-next-") as td:
        root = pathlib.Path(td)
        first, second, third, fourth = (root / name for name in ("first", "second", "third", "fourth"))
        for directory in (first, second, third, fourth):
            (directory / "sys").mkdir(parents=True)
        (first / "sys/wrap.h").write_text("int first;\n#include_next <sys/wrap.h>\n")
        (second / "sys/wrap.h").write_text('int second;\n#include_next "sys/wrap.h"\n')
        (third / "sys/wrap.h").write_text("int third;\n#include_next <sys/wrap.h>\n")
        (fourth / "sys/wrap.h").write_text("int fourth;\n")
        alias = root / "alias"
        alias.symlink_to(first, target_is_directory=True)
        conf = root / "crunch.conf"
        conf.write_text(f"include_path = {fourth}\n")
        env = dict(os.environ, CRUNCH_INCLUDE_PATH=f"{third}:{first}",
                   CRUNCH_CONF_FILE=str(conf))
        flags = ["-I", first, "-I", str(first) + "/.", "-I", alias, "-I", second]
        source = "#include <sys/wrap.h>\n#if 0\n#include_next <absent.h>\n#endif\n"
        expanded = command([PP, *flags, "-"], input=source, env=env).stdout
        pattern = r"int\s+(first|second|third|fourth)\s*;"
        expect(re.findall(pattern, expanded) == ["first", "second", "third", "fourth"],
               f"include-next search order or duplicate handling failed: {expanded}")
        gcc = shutil.which("gcc")
        if gcc:
            gcc_flags = ["-I", first, "-I", str(first) + "/.", "-I", alias,
                         "-I", second, "-I", third, "-I", first, "-I", fourth]
            reference = command([gcc, "-E", "-P", "-x", "c", *gcc_flags, "-"],
                                input=source).stdout
            expect(re.findall(pattern, expanded) == re.findall(pattern, reference),
                   "include-next search order differs from GCC")
        command([IR, "--module", "-"], input=expanded)
        (first / "sub").mkdir()
        (first / "outer.h").write_text('#include "sub/local.h"\n')
        (first / "sub/local.h").write_text('int local;\n#include_next <target.h>\n')
        (first / "target.h").write_text("int found_first;\n")
        (second / "target.h").write_text("int found_second;\n")
        output = command([PP, *flags, "-"], input="#include <outer.h>\n", env=env).stdout
        expect("int local;" in output and "int found_first;" in output and
               "int found_second;" not in output,
               "include-next in a relative quoted header skipped the wrong directory")
        (first / "direct.h").write_text("int local_copy;\n#include_next <direct.h>\n")
        (second / "direct.h").write_text("int next_copy;\n")
        (first / "main.bc").write_text('#include "direct.h"\n')
        output = command([PP, *flags, first / "main.bc"], env=env).stdout
        expect(output.count("int local_copy;") == 2 and "int next_copy;" in output,
               "include-next did not revisit a quoted header through the search path")
        (first / "missing.h").write_text("#include_next <absent.h>\n")
        result = command([PP, *flags, "-"], input="#include <missing.h>\n",
                         env=env, check=False)
        expect(result.returncode != 0 and "cannot open included header" in result.stderr,
               f"missing include-next target was not reported: {result.stderr}")


def preprocessor_parent_include_case():
    """Check relative parent headers across inclusion and availability searches.

    Returns:
        None; raises AssertionError for incorrect resolution or execution.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-parent-include-") as directory:
        root = pathlib.Path(directory)
        deep = root / "dir/deep"
        deep.mkdir(parents=True)
        first, second = root / "search/first", root / "search/second"
        first.mkdir(parents=True)
        second.mkdir()
        (root / "other/inner").mkdir(parents=True)
        (root / "linked").symlink_to(root / "other/inner", target_is_directory=True)
        (root / "dir/parent.h").write_text("int parent_value = 1;\n")
        (root / "top.h").write_text("#pragma once\nint top_value = 2;\n")
        (deep / "local.h").write_text("int local_value = 3;\n")
        (root / "search/angle.h").write_text("int angle_value = 4;\n")
        (root / "search/next.h").write_text("int next_value = 5;\n")
        (root / "other/from.h").write_text("int link_value = 27;\n")
        (root / "from.h").write_text("#error incorrectly normalized symlink\n")
        (first / "wrapper.h").write_text(
            "#if !__has_include_next(<../next.h>) || "
            "__has_include_next(<../missing.h>)\n#error incorrect next lookup\n#endif\n"
            "#include_next <../next.h>\n")
        source = deep / "main.bc"
        source.write_text(
            '#define PARENT "../parent.h"\n'
            '#define ANGLE <../angle.h>\n'
            '#if !__has_include(PARENT) || !__has_include("../../top.h") || '
            '!__has_include(ANGLE) || __has_include("../../missing.h")\n'
            '#error incorrect parent lookup\n#endif\n'
            '#include PARENT\n#include "../../top.h"\n#include "../.././top.h"\n'
            '#include "./local.h"\n#include ANGLE\n#include <wrapper.h>\n'
            '#include "../../linked/../from.h"\n'
            'int main(void) { return parent_value + top_value + local_value + '
            'angle_value + next_value + link_value; }\n')
        flags = ["-I", first, "-I", second]
        env = dict(os.environ, CRUNCH_CONF_FILE=str(root / "absent.conf"))
        env.pop("CRUNCH_INCLUDE_PATH", None)
        output = command([PP, *flags, source], env=env).stdout
        pattern = r"int\s+(parent_value|top_value|local_value|angle_value|next_value|link_value)\s*=\s*(\d+)"
        expected = [("parent_value", "1"), ("top_value", "2"), ("local_value", "3"),
                    ("angle_value", "4"), ("next_value", "5"), ("link_value", "27")]
        expect(re.findall(pattern, output) == expected, f"parent include resolution failed: {output}")
        gcc = shutil.which("gcc")
        if gcc:
            reference = command([gcc, "-E", "-P", "-x", "c", *flags, source]).stdout
            expect(re.findall(pattern, reference) == expected,
                   "parent include resolution differs from GCC")
        executable = root / "program"
        command([DRIVER, "--static", *flags, source, "-o", executable], env=env)
        expect(command([executable], check=False).returncode == 42,
               "parent include program did not execute")


def preprocessor_header_guard_case():
    """Check that only whole-file guards can suppress later includes.

    Returns:
        None; raises AssertionError for incorrect recursive or repeated inclusion.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-header-guard-") as td:
        directory = pathlib.Path(td)
        (directory / "partial.h").write_text(
            "#ifndef PARTIAL\n#define PARTIAL\n"
            '#include "partial.h"\nint inside;\n#endif\nint outside;\n')
        (directory / "alternate.h").write_text(
            "#ifndef ALTERNATE\n#define ALTERNATE\nint first_branch;\n"
            "#else\nint second_branch;\n#endif\n")
        source = ('#include <partial.h>\n#include <partial.h>\n'
                  '#include <alternate.h>\n#include <alternate.h>\n')
        expanded = command([PP, "-I", directory, "-"], input=source).stdout
        pattern = r"int\s+(inside|outside|first_branch|second_branch)\s*;"
        actual = re.findall(pattern, expanded)
        expect(actual == ["outside", "inside", "outside", "outside",
                          "first_branch", "second_branch"],
               f"partial or recursive guard suppressed content: {actual}")
        gcc = shutil.which("gcc")
        if gcc:
            reference = command([gcc, "-E", "-P", "-x", "c", "-I", directory, "-"],
                                input=source).stdout
            expect(actual == re.findall(pattern, reference),
                   "partial-guard expansion differs from GCC")


def preprocessor_timestamp_case():
    """Check translation timestamps, reproducibility, and macro overrides.

    Returns:
        None; raises AssertionError for incorrect predefined macro behavior.
    """
    source = ("#if !defined(__DATE__) || !defined(__TIME__)\n#error missing time\n#endif\n"
              "#define DATE_ALIAS __DATE__\nDATE_ALIAS __TIME__\n")
    for epoch, expected in (("0", '"Jan  1 1970" "00:00:00"'),
                            ("951782400", '"Feb 29 2000" "00:00:00"'),
                            ("4107542400", '"Mar  1 2100" "00:00:00"'),
                            ("253402300799", '"Dec 31 9999" "23:59:59"')):
        env = dict(os.environ, SOURCE_DATE_EPOCH=epoch, TZ="Pacific/Honolulu")
        actual = command([PP, "-"], input=source, env=env).stdout
        expect(expected in actual, f"incorrect timestamp for {epoch}: {actual!r}")
        gcc = shutil.which("gcc")
        if gcc:
            reference = command([gcc, "-E", "-P", "-x", "c", "-"],
                                input=source, env=env).stdout
            expect(expected in reference, f"timestamp for {epoch} differs from GCC")
    for invalid in ("", "bad", "-1", " 1", "253402300800", "99999999999999999999999"):
        invalid_env = dict(os.environ, SOURCE_DATE_EPOCH=invalid)
        command([PP, "-"], input="int unused;\n", env=invalid_env)
        expect(command([PP, "-"], input="__DATE__\n", env=invalid_env,
                       check=False).returncode != 0,
               f"invalid SOURCE_DATE_EPOCH was accepted: {invalid!r}")
    invalid_env = dict(os.environ, SOURCE_DATE_EPOCH="bad")
    overridden = command([PP, '-D__DATE__="manual"', "-"], input=
                         "__DATE__\n#undef __DATE__\n#ifdef __DATE__\n#error defined\n#endif\n"
                         "#define __DATE__ 42\n__DATE__\n", env=invalid_env).stdout
    expect('"manual"' in overridden and "\n42\n" in overridden,
           "timestamp macro override or undefinition failed")
    with tempfile.TemporaryDirectory(prefix="crunch-native-timestamp-") as td:
        native_pp = pathlib.Path(td) / "crunch-pp"
        command([DRIVER, "--static", "-I", ROOT / "include",
                 ROOT / "src/driver/pp_main.c", "-o", native_pp], timeout=600)
        epoch_env = dict(os.environ, SOURCE_DATE_EPOCH="951782400")
        actual = command([native_pp, "-"], input="__DATE__ __TIME__\n", env=epoch_env).stdout
        expect('"Feb 29 2000" "00:00:00"' in actual,
               "self-built preprocessor produced an incorrect reproducible timestamp")
        clock_env = dict(os.environ)
        clock_env.pop("SOURCE_DATE_EPOCH", None)
        actual = command([native_pp, "-"], input="__DATE__ __TIME__\n", env=clock_env).stdout
        expect(re.search(r'"[A-Z][a-z]{2} [ 0-9][0-9] [0-9]{4}" '
                         r'"[0-9]{2}:[0-9]{2}:[0-9]{2}"', actual),
               "self-built preprocessor could not obtain the system time")


def preprocessor_function_alias_case():
    """Check single-identifier aliases of function-like macros.

    Returns:
        None; raises AssertionError for incorrect expansions or source locations.
    """
    source = (
        "#define A B\n#define B F\n#define F(x) ((x)+1)\n"
        "#define ID(x) x\n#define STR(x) #x\n#define TEXT(x) STR(x)\n"
        "#if A(41) != 42\n#error alias in condition failed\n#endif\n"
        "int a = A(41); int b = A(A(40));\n"
        "const char *s = TEXT(A(41));\n"
        "A /*call*/\n(41)\n"
        "#define VARIADIC(...) __VA_ARGS__\n#define VAR_ALIAS VARIADIC\n"
        "#define ZERO() 42\n#define ZERO_ALIAS ZERO\n"
        "VAR_ALIAS(1, 2, 3) VAR_ALIAS() ZERO_ALIAS()\n"
        "#define C C\n#define D E\n#define E D\nC(1) D(2)\n"
        "#define R(x) R_ALIAS(x)\n#define R_ALIAS R\n"
        "R_ALIAS(3) ID(R_ALIAS(3))\n"
        "#define VALUE_CALL F\nVALUE_CALL\n#define AFTER 7\nAFTER\n"
        '#line 100 "alias-source.bc"\n'
        "int line = A(\n__LINE__\n); int next = __LINE__;\n"
        "#line 200\nint spliced = A(\\\n__LINE__); int after_splice = __LINE__;\n")
    expanded = command([PP, "-"], input=source).stdout
    pattern = r'"(?:\\.|[^"\\])*"|[A-Za-z_][A-Za-z_0-9]*|[0-9]+|[^\s]'
    gcc = shutil.which("gcc")
    if gcc:
        reference = command([gcc, "-E", "-P", "-x", "c", "-"], input=source).stdout
        actual = re.sub(r"/\*CRUNCH-PP-MAP:[^*]*\*/", "", expanded)
        actual = re.sub(r"/\*.*?\*/", " ", actual, flags=re.S)
        expect(re.findall(pattern, actual) == re.findall(pattern, reference),
               f"function macro aliases differ from GCC:\nCrunch: {actual}\nGCC: {reference}")
    expect("R(3)" in expanded and "C(1)" in expanded and "D(2)" in expanded,
           f"recursive aliases were not suppressed: {expanded}")
    expect(re.search(r"int\s+line\s*=\s*\(\(\s*100\s*\)\s*\+\s*1\)", expanded) and
           re.search(r"int\s+next\s*=\s*102\s*;", expanded) and
           re.search(r"int\s+spliced\s*=\s*\(\(\s*200\s*\)\s*\+\s*1\)", expanded) and
           re.search(r"int\s+after_splice\s*=\s*201\s*;", expanded),
           f"alias invocation lost multiline source locations: {expanded}")
    invalid = command([PP, "-"], input="#define A F\n#define F(x) x\nA(1,2)\n",
                      check=False)
    expect(invalid.returncode != 0 and "expects 1 argument" in invalid.stderr,
           "wrong argument count through an alias was not rejected")
    with tempfile.TemporaryDirectory(prefix="crunch-function-alias-") as td:
        directory = pathlib.Path(td)
        executable = directory / "program"
        (directory / "alias_header.h").write_text("int header_value = 40;\n")
        env = dict(os.environ, CRUNCH_CONF_FILE=str(directory / "absent.conf"))
        program = (
            "#define HEADER(x) <x.h>\n#define H HEADER\n#include H(alias_header)\n"
            "#define PLUS(x,y) ((x)+(y))\n#define ADD PLUS\n"
            "int main(void) { return ADD(header_value, 2); }\n")
        command([DRIVER, "--static", "-I", directory, "-o", executable, "-"],
                input=program, env=env)
        expect(command([executable], check=False).returncode == 42,
               "alias-expanded header or program did not execute")
        if gcc:
            command([gcc, "-std=c11", "-I", directory, "-fsyntax-only", "-x", "c", "-"],
                    input=program)
        asm = directory / "helper.S"
        asm.write_text("#define ADD(x,y) ((x)+(y))\n#define ALIAS ADD\n"
                       ".text\n.globl helper\nhelper:\nmov $ALIAS(40,2), %eax\nret\n"
                       '.section .note.GNU-stack,"",@progbits\n')
        main = directory / "main.bc"
        main.write_text("int helper(void); int main(void) { return helper(); }\n")
        command([DRIVER, "--static", "-o", executable, main, asm], env=env)
        expect(command([executable], check=False).returncode == 42,
               "function macro alias did not work in assembly")


def preprocessor_identity_rescan_case():
    """Check function macro names returned by identity macro invocations.

    Returns:
        None; raises AssertionError for incorrect expansion or diagnostics.
    """
    source = (
        "#define ID(x) x\n#define WRAP ID\n#define F(x) ((x)+1)\n#define ALIAS F\n"
        "#define STRING(x) #x\n#define EXPAND_STRING(x) STRING(x)\n"
        "#define EMPTY\n"
        "#if ID(F)(41) != 42\n#error identity in condition failed\n#endif\n"
        "ID(F)(1) ID(ALIAS)(2) ID(F)(ID(ALIAS)(1)) WRAP(F)(3)\n"
        "ID(ID)(5) ID(F) EMPTY (3) ID(F) /* comment */ (3)\n"
        "#define SELF(x) ID(SELF)(x)\nSELF(6) ID(SELF)(7)\n"
        "#define SECOND(x) x\n#define PASS(x) ID(x)(1)\nPASS(SECOND(SECOND))\n"
        "EXPAND_STRING(ID(F)(4))\n"
        "ID(F)\n(5)\n"
        '#line 100 "identity.bc"\n'
        "ID(F)(\n__LINE__\n) __LINE__\n"
        "WRAP(F)(\n__LINE__\n) __LINE__\n")
    expanded = command([PP, "-"], input=source).stdout
    pattern = r'"(?:\\.|[^"\\])*"|[A-Za-z_][A-Za-z_0-9]*|[0-9]+|[^\s]'
    actual = re.sub(r"/\*CRUNCH-PP-MAP:[^*]*\*/", "", expanded)
    actual = re.sub(r"/\*.*?\*/", " ", actual, flags=re.S)
    expected_prefix = "((1)+1) ((2)+1) ((((1)+1))+1) ((3)+1)"
    expected_tokens = re.findall(pattern, expected_prefix)
    expect(re.findall(pattern, actual)[:len(expected_tokens)] == expected_tokens,
           f"identity macro calls were not expanded: {actual}")
    gcc = shutil.which("gcc")
    if gcc:
        reference = command([gcc, "-E", "-P", "-x", "c", "-"], input=source).stdout
        expect(re.findall(pattern, actual) == re.findall(pattern, reference),
               f"identity rescanning differs from GCC:\nCrunch: {actual}\nGCC: {reference}")
    expect("ID(5)" in actual and "SECOND(1)" in actual and
           "SELF(6)" in actual and '"((4)+1)"' in actual and
           re.search(r"\(\(\s*101\s*\)\s*\+\s*1\)\s*102", actual) and
           re.search(r"\(\(\s*103\s*\)\s*\+\s*1\)\s*105", actual),
           f"identity rescanning lost suppression or source locations: {actual}")
    invalid = command([PP, "-"], input="#define ID(x) x\n#define F(x) x\n"
                      "ID(F)(1,2)\n", check=False)
    expect(invalid.returncode != 0 and "expects 1 argument" in invalid.stderr,
           "wrong argument count through an identity macro was not rejected")
    with tempfile.TemporaryDirectory(prefix="crunch-identity-rescan-") as td:
        directory = pathlib.Path(td)
        executable = directory / "program"
        (directory / "identity_header.h").write_text("int header_value = 41;\n")
        env = dict(os.environ, CRUNCH_CONF_FILE=str(directory / "absent.conf"))
        program = (
            "#define ID(x) x\n#define HEADER(x) <x.h>\n"
            "#include ID(HEADER)(identity_header)\n"
            "#define INC(x) ((x)+1)\n"
            "int main(void) { return ID(INC)(header_value); }\n")
        command([DRIVER, "--static", "-I", directory, "-o", executable, "-"],
                input=program, env=env)
        expect(command([executable], check=False).returncode == 42,
               "identity-expanded header or program did not execute")


def preprocessor_replacement_rescan_case():
    """Compare replacement-tail rescanning and suppression with GCC.

    Returns:
        None; raises AssertionError for incorrect expansion or diagnostics.
    """
    source = (
        "#define F(x) x\n#define GET() F\n#define PREFIX 1 + F\n"
        "#define ID(x) x\n#define LATER() ID(F)\n#define EMPTY\n"
        "#define EARLY F EMPTY\n#define PASS(x) ID(x)(1)\n"
        "#define CAT(a,b) a##b\n#define LEFT(x) CAT(x,)\n"
        "#define RIGHT(x) CAT(,x)\n#define JOIN(x) CAT(x,oo)\n"
        "#define f(x) x\n#define foo(x) 7\n"
        "#define S(x) #x\n#define STR(x) S(x)\n"
        "#if GET()(41) != 41 || PREFIX(1) != 2\n#error rescan failed\n#endif\n"
        "GET()(42) PREFIX(41) GET()(GET())(3)\n"
        "GET()\n(5) PREFIX\n(6) ID(GET())\n(7) LATER()\n(8)\n"
        "GET() /* comment\ncontinued */\n(10)\n"
        "EARLY(9) PASS(F(F)) LEFT(F(F))(2) RIGHT(F(F))(3) JOIN(f(f))(4)\n"
        "STR(PASS(F(F)))\n"
        '#line 100 "rescan.bc"\n'
        "GET()(\n__LINE__\n) __LINE__\n"
        "PREFIX(\n__LINE__\n) __LINE__\n")
    expanded = command([PP, "-"], input=source).stdout
    pattern = r'"(?:\\.|[^"\\])*"|[A-Za-z_][A-Za-z_0-9]*|[0-9]+|[^\s]'
    actual = re.sub(r"/\*CRUNCH-PP-MAP:[^*]*\*/", "", expanded)
    actual = re.sub(r"/\*.*?\*/", " ", actual, flags=re.S)
    tokens = re.findall(pattern, actual)
    expected = re.findall(pattern, '42 1 + 41 F(3) 5 1 + 6 7 8 10 '
                          'F(9) F(1) F(2) F(3) 7 "F(1)" 101 102 1 + 103 105')
    expect(tokens == expected, f"incorrect replacement rescanning: {actual}")
    gcc = shutil.which("gcc")
    if gcc:
        reference = command([gcc, "-E", "-P", "-x", "c", "-"], input=source).stdout
        expect(tokens == re.findall(pattern, reference),
               f"replacement rescanning differs from GCC:\nCrunch: {actual}\nGCC: {reference}")
    invalid = command([PP, "-"], input="#define F(x) x\n#define GET() F\n"
                      "GET()(1,2)\n", check=False)
    expect(invalid.returncode != 0 and "expects 1 argument" in invalid.stderr,
           "wrong argument count through a replacement was not rejected")
    repeated = command([PP, "-"], input="#define ID(x) x\n" + "ID(1)\n" * 4000,
                       timeout=5).stdout
    expect(len(re.findall(r"(?m)^1$", repeated)) == 4000,
           "repeated identity macros were not expanded")
    repeated = command([PP, "-"], input="#define F(x) x\n#define ID(x) x\n" +
                       "ID(F)\n" * 4000, timeout=5).stdout
    expect(len(re.findall(r"(?m)^F$", repeated)) == 4000,
           "repeated uncalled macro names were not preserved")
    with tempfile.TemporaryDirectory(prefix="crunch-replacement-rescan-") as td:
        directory = pathlib.Path(td)
        executable = directory / "program"
        (directory / "rescan_header.h").write_text("int header_value = 41;\n")
        env = dict(os.environ, CRUNCH_CONF_FILE=str(directory / "absent.conf"))
        program = (
            "#define HEADER(x) <x.h>\n#define GET_HEADER() HEADER\n"
            "#include GET_HEADER()(rescan_header)\n"
            "#define INC(x) ((x)+1)\n#define GET_INC() INC\n"
            "int main(void) { return GET_INC()(header_value); }\n")
        command([DRIVER, "--static", "-I", directory, "-o", executable, "-"],
                input=program, env=env)
        expect(command([executable], check=False).returncode == 42,
               "replacement-expanded header or program did not execute")


def preprocessor_split_rescan_case():
    """Compare calls split between macro replacements and source with GCC.

    Returns:
        None; raises AssertionError for incorrect expansion or diagnostics.
    """
    source = (
        "#define F(x) x\n#define START F(\n#define CALL() F(\n"
        "#define PAIR(x,y) x + y\n#define ADD PAIR(1,\n"
        "#define ID(x) x\n#define INDIRECT ID(F)(\n#define ALIAS F\n"
        "#define ALIAS_OPEN ALIAS(\n#define ARG_OPEN(x) x(\n"
        "#define S(x) #x\n#define TEXT S(hello\n"
        "#define CAT(a,b) a##b\n#define JOIN CAT(he,\n#define hello 7\n"
        "#define FORWARD START\n#define COMPLETE START 4)\n"
        "#define RECUR(x) RECUR(x)\n#define OPEN_RECUR RECUR(\n"
        "#if START 42) != 42 || ADD 41) != 42\n#error split failed\n#endif\n"
        "START 1) CALL() 2) ADD 3) INDIRECT 5)\n"
        "FORWARD 6) COMPLETE + START 7)\n"
        "START\n8) CALL()\n9) INDIRECT\n10) ALIAS_OPEN\n12) ARG_OPEN(F)\n13)\n"
        "TEXT world) JOIN llo) OPEN_RECUR 11)\n"
        '#line 100 "split.bc"\n'
        "START\n__LINE__) __LINE__\n"
        "CALL(\\\n)\n__LINE__) __LINE__\n"
        "#define LOC(a,b) a b\n#define OBJ LOC(__LINE__,\n"
        "#define FUN() LOC(__LINE__,\n"
        "OBJ\n__LINE__) FUN()\n__LINE__)\n")
    expanded = command([PP, "-"], input=source).stdout
    pattern = r'"(?:\\.|[^"\\])*"|[A-Za-z_][A-Za-z_0-9]*|[0-9]+|[^\s]'
    actual = re.sub(r"/\*CRUNCH-PP-MAP:[^*]*\*/", "", expanded)
    actual = re.sub(r"/\*.*?\*/", " ", actual, flags=re.S)
    tokens = re.findall(pattern, actual)
    gcc = shutil.which("gcc")
    if gcc:
        reference = command([gcc, "-E", "-P", "-x", "c", "-"], input=source).stdout
        expect(tokens == re.findall(pattern, reference),
               f"split macro calls differ from GCC:\nCrunch: {actual}\nGCC: {reference}")
    expected = re.findall(pattern, '1 2 1 + 3 5 6 4 + 7 8 9 10 12 13 '
                          '"hello world" 7 RECUR(11) 100 101 104 104 '
                          '108 108 109 110')
    expect(tokens == expected, f"incorrect split macro expansion: {actual}")
    for suffix in ("1,2)", "1"):
        invalid = command([PP, "-"], input="#define F(x) x\n#define START F(\n"
                          f"START {suffix}\n", check=False)
        expect(invalid.returncode != 0,
               f"malformed split invocation was accepted: {suffix}")
    repeated = command([PP, "-"], input="#define F(x) x\n#define START F(\n" +
                       "START 1)\n" * 4000, timeout=5).stdout
    expect(len(re.findall(r"(?m)^\s*1$", repeated)) == 4000,
           "repeated split invocations were not expanded")
    with tempfile.TemporaryDirectory(prefix="crunch-split-rescan-") as td:
        directory = pathlib.Path(td)
        executable = directory / "program"
        (directory / "split_header.h").write_text("int header_value = 41;\n")
        env = dict(os.environ, CRUNCH_CONF_FILE=str(directory / "absent.conf"))
        program = (
            "#define HEADER(x) <x.h>\n#define OPEN_HEADER HEADER(split_header\n"
            "#include OPEN_HEADER)\n"
            "#define INC(x) ((x)+1)\n#define OPEN_INC() INC(\n"
            "int main(void) { return OPEN_INC() header_value); }\n")
        command([DRIVER, "--static", "-I", directory, "-o", executable, "-"],
                input=program, env=env)
        expect(command([executable], check=False).returncode == 42,
               "split macro header or program did not execute")


def preprocessor_token_boundary_case():
    """Check that expansion preserves token boundaries and stringification.

    Returns:
        None; raises AssertionError for incorrect preprocessing or execution.
    """
    source = (
        "#define PLUS +\n#define ONE() 1\n#define EXP() 1e\n#define WORD() name\n#define SLASH() /\n"
        "#define EMPTY\n#define ID(x) x\n#define CAT(a,b) a##b\n"
        "#define S(x) #x\n#define STR(x) S(x)\n"
        "PLUS+1 1+PLUS+1 ONE().5 ONE()e2 EXP(). EXP()+2 WORD()tail SLASH()*x\n"
        "ID(1+PLUS+1) ID(+) +ID(+)+ CAT(he,llo) CAT(,x) CAT(x,)\n"
        "STR(PLUS+) STR(ONE()e2) STR(+EMPTY+) STR(1+PLUS+1)\n"
        "#if 1 PLUS+1 == 2\nint condition_ok;\n#else\n#error wrong tokens\n#endif\n")
    expanded = command([PP, "-"], input=source).stdout
    expected = ("+ +1", "1+ + +1", "1 .5", "1 e2", "1e .", "1e +2", "name tail", "/ *x",
                '"++"', '"1e2"', '"1+++1"')
    for value in expected:
        expect(value in expanded, f"incorrect token boundary or stringification {value!r}: {expanded}")
    gcc = shutil.which("gcc")
    if gcc:
        reference = command([gcc, "-E", "-P", "-x", "c", "-"], input=source).stdout
        token_pattern = (r'"(?:\\.|[^"\\])*"|(?:[0-9]|\.[0-9])'
                         r'(?:[eEpP][+-]|[A-Za-z0-9_.])*|[A-Za-z_][A-Za-z_0-9]*|'
                         r'\+\+|--|->|&&|\|\||==|!=|<=|>=|<<|>>|##|[^\s]')
        actual = re.sub(r"/\*CRUNCH-PP-MAP:[^*]*\*/", "", expanded)
        expect(re.findall(token_pattern, actual) == re.findall(token_pattern, reference),
               f"expanded token boundaries differ from GCC:\nCrunch: {actual}\nGCC: {reference}")
    with tempfile.TemporaryDirectory(prefix="crunch-token-boundary-") as td:
        directory = pathlib.Path(td)
        executable = directory / "program"
        program = ("#define PLUS +\n#define ID(x) x\n"
                   "int main(void) { return ID(40 PLUS+2); }\n")
        command([DRIVER, "--static", "-o", executable, "-"], input=program)
        expect(command([executable], check=False).returncode == 42,
               "adjacent expanded operators did not execute correctly")
        (directory / "boundary.h").write_text("int header_selected;\n")
        include_source = ("#define NAME boundary\n#define HEADER <NAME.h>\n"
                          "#include HEADER\n"
                          "#if __has_include(HEADER)\nint header_found;\n#endif\n")
        env = dict(os.environ, CRUNCH_CONF_FILE=str(directory / "absent.conf"))
        included = command([PP, "-I", directory, "-"], input=include_source, env=env).stdout
        expect("int header_selected;" in included and "int header_found;" in included,
               f"token boundaries corrupted an expanded header name: {included}")
        unusual = "a\x1fb.h"
        (directory / unusual).write_text("int unusual_header;\n")
        for directive in (f"#include <{unusual}>\n",
                          f"#define HEADER <{unusual}>\n#include HEADER\n"):
            result = command([PP, "-I", directory, "-"], input=directive, env=env)
            expect("int unusual_header;" in result.stdout,
                   "header name contained a byte reserved for an internal token boundary")
        if gcc:
            reference = command([gcc, "-E", "-P", "-I", directory, "-x", "c", "-"],
                                input=include_source).stdout
            expect("int header_selected;" in reference and "int header_found;" in reference,
                   "GCC did not select the same expanded header")
        assembly = ("#define PLUS +\n.text\n.globl helper\nhelper:\n"
                    "mov $40 PLUS+2, %eax\nret\n"
                    '.section .note.GNU-stack,"",@progbits\n')
        source_file = directory / "main.S"
        source_file.write_text(assembly)
        driver_source = directory / "main.bc"
        driver_source.write_text("int helper(void); int main(void) { return helper(); }\n")
        command([DRIVER, "--static", "-o", executable, driver_source, source_file])
        expect(command([executable], check=False).returncode == 42,
               "token boundaries in assembly did not execute correctly")
    control = "\x1f"
    preserved = command([PP, "-"], input=f'const char *s = "a{control}b";\n'
                        f'/* first\n{control} second */\n').stdout
    expect(f'"a{control}b"' in preserved and control in preserved.split("/* first", 1)[1],
           "literal or comment bytes were mistaken for internal boundaries")


def preprocessor_variadic_case():
    """Check variadic arguments, stringification, token pasting and GNU comma elision.

    Returns:
        None; raises AssertionError for incorrect expansions or diagnostics.
    """
    source = r'''
#define NUM 23
#define V(...) [__VA_ARGS__]
#define N(first, rest...) [first; rest]
#define S(...) #__VA_ARGS__
#define CAT(a,b) [a##b]
#define CHAIN(a,b,c) [a##b##c]
#define PREFIX(a,b) before a##b after
#define LOG(first,...) [first, ##__VA_ARGS__]
#define EMPTY
V(NUM, (1, 2), 3)
V()
N(a, NUM, 4)
N(a)
S(alpha, "quoted", NUM)
CAT(x,y) CAT(,y) CAT(x,) CAT(,)
CHAIN(a,,c) CHAIN(,,z) CHAIN(a,,) CHAIN(,,)
PREFIX(,x) PREFIX(x,) PREFIX(,)
LOG(x) LOG(x,) LOG(x,NUM,2)
'''
    expanded = command([PP, "-"], input=source).stdout
    for expected in ("[23, (1, 2), 3]", '"alpha, \\"quoted\\", NUM"',
                     "[xy] [y] [x] []", "[ac] [z] [a] []"):
        expect(expected in expanded, f"incorrect variadic expansion {expected!r}: {expanded}")
    gcc = shutil.which("gcc")
    if gcc:
        reference = command([gcc, "-std=gnu11", "-E", "-P", "-x", "c", "-"],
                            input=source).stdout
        token_pattern = r'"(?:\\.|[^"\\])*"|[A-Za-z_][A-Za-z_0-9]*|[0-9]+|[^\s]'
        actual = re.sub(r"/\*CRUNCH-PP-MAP:[^*]*\*/", "", expanded)
        expect(re.findall(token_pattern, actual) == re.findall(token_pattern, reference),
               f"variadic expansion differs from GCC:\nCrunch: {actual}\nGCC: {reference}")
    no_parameters = r'''
#define left L
#define right R
#define leftright 42
#define JOIN left ## right
#define ZERO() 1 ## 2
#define TRIPLE foo ## bar ## baz
#define foobarbaz 31
#define QUOTED() "x ## y"
#define OP() + ## +
#define HASH #
JOIN ZERO() TRIPLE QUOTED() OP() HASH
#if JOIN + ZERO() != 54
#error token paste failed in condition
#endif
'''
    expanded = command([PP, "-"], input=no_parameters).stdout
    expect('42 12 31 "x ## y" ++ #' in expanded,
           f"object or zero-argument token paste failed: {expanded}")
    if gcc:
        reference = command([gcc, "-std=gnu11", "-E", "-P", "-x", "c", "-"],
                            input=no_parameters).stdout
        token_pattern = r'"(?:\\.|[^"\\])*"|\+\+|[A-Za-z_][A-Za-z_0-9]*|[0-9]+|[^\s]'
        actual = re.sub(r"/\*CRUNCH-PP-MAP:[^*]*\*/", "", expanded)
        expect(re.findall(token_pattern, actual) == re.findall(token_pattern, reference),
               f"parameterless token paste differs from GCC:\nCrunch: {actual}\nGCC: {reference}")
    for invalid in ("#define BAD(x,...,y) x\n", "#define BAD(x...,y) x\n",
                    "#define BAD(x,x...) x\n", "#define BAD(x,y,...) x\nBAD(1)\n"):
        result = command([PP, "-"], input=invalid, check=False)
        expect(result.returncode != 0, f"invalid variadic macro accepted: {invalid}")
    program = ("#define G(TAG, NAME, ATTRS, MEMBERS...) "
               "union { struct { MEMBERS } ATTRS; struct TAG { MEMBERS } ATTRS NAME; } ATTRS\n"
               "struct S { G(, named, , int first; int second;); };\n"
               "int main(void) { struct S x; x.named.first = 17; x.second = 25; "
               "return x.first + x.named.second; }\n")
    with tempfile.TemporaryDirectory(prefix="crunch-variadic-") as td:
        executable = pathlib.Path(td) / "program"
        command([DRIVER, "--static", "-o", executable, "-"], input=program)
        expect(command([executable], check=False).returncode == 42,
               "Linux-style named variadic structure macro did not execute")
        pasted = ("#define VALUE() 4 ## 2\n#define NAME global ## _value\n"
                  "int NAME = VALUE(); int main(void) { return NAME; }\n")
        command([DRIVER, "--static", "-o", executable, "-"], input=pasted)
        expect(command([executable], check=False).returncode == 42,
               "parameterless token pastes did not compile and execute")


def thread_local_case():
    """Check restricted C11 TLS, IR validation, and glibc thread isolation.

    Returns:
        None; raises AssertionError for incorrect results or diagnostics.
    """
    source = ("_Alignas(16) static _Thread_local int value = 5, count;\n"
              "_Thread_local static int other = 9;\n"
              "static int shared = 17;\n"
              "static _Thread_local int *pointer = &shared;\n"
              "int *address(void) { return &value; }\n"
              "int read_value(void) { return value + count + other + *pointer; }\n"
              "void write_value(int n) { value = n; count++; other++; }\n")
    with tempfile.TemporaryDirectory(prefix="crunch-tls-") as td:
        directory = pathlib.Path(td)
        path = directory / "tls.bc"
        path.write_text(source)
        tokens = command([LEXER, path]).stdout
        expect("\nTHREAD_LOCAL\t" in tokens, "TLS keyword was not tokenized")
        tree = json.loads(command([PARSER], input=tokens).stdout)
        variables = [d for d in tree["declarations"] if d["kind"] == "variable"]
        expect(tree["version"] == 42 and
               [d.get("thread_local", False) for d in variables] ==
               [True, True, True, False, True],
               "AST did not preserve TLS on each declarator")
        ir = command([IR, "--module", path]).stdout
        expect(ir.startswith("CRUNCH-IR 53\n") and "thread_local value\n" in ir,
               "TLS did not select module IR v53")
        assembly = command([ASM, "--no-entry", "-"], input=ir).stdout
        expect("@TPOFF" in assembly and "@tls_object" in assembly and
               '.section .tdata,"awT"' in assembly,
               "TLS assembly did not use ELF local-exec storage")
        asm_path, object_path = directory / "tls.s", directory / "tls-native.o"
        asm_path.write_text(assembly + "\n.globl _start\n_start:\n ret\n")
        command([BUILD / "crunch-as", "-o", object_path, asm_path])
        rejected = command([BUILD / "crunch-ld", "-nostdlib", "-o",
                            directory / "native-executable", object_path], check=False)
        expect(rejected.returncode != 0 and "unsupported relocation" in rejected.stderr,
               "native executable linker did not reject TLS relocations")
        expect(command([ASM, "-"], input=ir, check=False).returncode != 0,
               "TLS assembly was accepted with the Crunch entry point")
        expect(command([DRIVER, "-c", path, "-o", directory / "native.o"],
                       check=False).returncode != 0,
               "Crunch runtime compilation accepted TLS")
        expect(command([IR, path], check=False).returncode != 0,
               "TLS was accepted in executable IR mode")
        for bad in (
                "_Thread_local int x; int main(void) { return x; }",
                "static _Thread_local int x[2];",
                "static _Thread_local long double x;",
                "static _Thread_local int x; static int x;",
                "static _Thread_local int x; int f(void) { extern int x; return x; }",
                "static _Thread_local int f(void);",
                "void f(void) { static _Thread_local int x; }"):
            result = command([IR, "--module", "-"], input=bad, check=False)
            expect(result.returncode != 0, f"unsupported TLS declaration accepted: {bad}")
        for directive in ("thread_local missing\n", "thread_local x extra\n",
                          "thread_local x\nthread_local x\n"):
            invalid = "CRUNCH-IR 53\ninternal x\nglobal x int 0\n" + directive
            result = command([ASM, "--no-entry", "-"], input=invalid, check=False)
            expect(result.returncode != 0, f"invalid TLS IR accepted: {directive!r}")
        old_ir = "CRUNCH-IR 51\ninternal x\nglobal x int 0\nthread_local x\n"
        expect(command([ASM, "--no-entry", "-"], input=old_ir, check=False).returncode != 0,
               "old IR accepted TLS directive")
        extern_ir = "CRUNCH-IR 53\nextern_global x int\nthread_local x\n"
        expect(command([ASM, "--no-entry", "-"], input=extern_ir, check=False).returncode != 0,
               "external TLS directive was accepted")
        bad_relocation = ("CRUNCH-IR 53\ninternal x\nthread_local x\nglobal x int 0\n"
                          "global p ptr 0\nglobalreloc p x 0\n")
        expect(command([ASM, "--no-entry", "-"], input=bad_relocation,
                       check=False).returncode != 0,
               "static TLS address relocation was accepted")
        gcc = shutil.which("gcc")
        if (gcc and os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1" and
                "CS_GNU_LIBC_VERSION" in os.confstr_names and os.confstr("CS_GNU_LIBC_VERSION")):
            obj, executable = directory / "tls.o", directory / "test"
            command([DRIVER, "--glibc", "-c", path, "-o", obj])
            second = directory / "second.o"
            command([DRIVER, "--glibc", "-c", "-o", second, "-"], input=
                    "static _Thread_local int value = 77;\n"
                    "int read_secondary(void) { return value; }\n")
            merged = directory / "merged.o"
            command([BUILD / "crunch-ld", "-nostdlib", "-r", "-o", merged, obj, second])
            host = directory / "host.c"
            host.write_text(
                "#include <pthread.h>\n#include <stdint.h>\n"
                "extern int *address(void); extern int read_value(void); "
                "extern void write_value(int); extern int read_secondary(void);\n"
                "static void *worker(void *p) { "
                "if (address()==p || ((uintptr_t)address() & 15) || "
                "read_value()!=31 || *address()!=5 || "
                "read_secondary()!=77) return (void *)1; "
                "write_value(40); return read_value()!=68 ? (void *)1 : 0; }\n"
                "int main(void) { pthread_t t; void *result; "
                "if (pthread_create(&t, 0, worker, address()) || pthread_join(t, &result)) return 1; "
                "return result != 0 || ((uintptr_t)address() & 15) || "
                "read_value()!=31 || *address()!=5 || "
                "read_secondary()!=77; }\n")
            command([gcc, "-no-pie", "-pthread", host, merged, "-o", executable])
            expect(command([executable], check=False).returncode == 0,
                   "TLS initialization, address-taking, or thread isolation failed")
            command([DRIVER, "--glibc", "-o", executable, "-"], input=
                    "_Alignas(16) static _Thread_local int x = 42; "
                    "int read_vla(int n, ...) { int a[n]; a[0] = x; return a[0]; } "
                    "int main(void) { return read_vla(1, 0) != 42; }\n")
            expect(command([executable], check=False).returncode == 0,
                   "glibc-linked TLS executable failed")


def glibc_header_discovery_case():
    """Check automatic GNU include discovery, precedence and failure handling.

    Returns:
        None; raises AssertionError for incorrect discovery or include behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-glibc-includes-") as directory:
        td = pathlib.Path(directory)
        cli, environ, configured, first, second = (
            td / name for name in ("cli", "environment", "configured", "system one", "system:two"))
        for path in (cli, environ, configured, first, second):
            path.mkdir()
        names = ("CLI", "ENVIRONMENT", "CONFIGURED", "FIRST", "SECOND")
        for index, (path, name) in enumerate(zip((cli, environ, configured, first, second), names)):
            (path / "order.h").write_text(
                f"#define {name} 1\n" +
                ("#include_next <order.h>\n" if index < 4 else ""))
        compiler = td / "fake compiler"
        lines = ("#include <...> search starts here:", f" {first}", f" {first}",
                 f" {second}", "End of search list.")
        compiler.write_text("#!/bin/sh\n[ \"$LC_ALL\" = C ] || exit 9\nprintf '%s\\n' " +
                            " ".join(shlex.quote(line) for line in lines) + " >&2\n")
        compiler.chmod(0o755)
        conf = td / "crunch.conf"
        conf.write_text(f"include_path = {configured}\n")
        env = dict(os.environ, CRUNCH_CONF_FILE=str(conf), CRUNCH_INCLUDE_PATH=str(environ),
                   CRUNCH_GLIBC_CC=str(compiler), LC_ALL="not-a-valid-locale")
        source = ("#include <order.h>\n"
                  "#if CLI && ENVIRONMENT && CONFIGURED && FIRST && SECOND\n"
                  "int selected;\n#else\n#error wrong include order\n#endif\n")
        result = command([DRIVER, "--glibc", "-E", "-I", cli, "-"],
                         input=source, env=env)
        expect("int selected;" in result.stdout, "discovered include search order is incorrect")
        hosted_source = ("#if defined(__STDC_HOSTED__) && __STDC_HOSTED__ == EXPECTED\n"
                         "int hosted_setting_correct;\n#else\n#error incorrect hosted setting\n#endif\n")
        for definitions in (["-DEXPECTED=1"], ["-DEXPECTED=1", "-D__STDC_HOSTED___OTHER=2"],
                            ["-DEXPECTED=0", "-D__STDC_HOSTED__=0"]):
            output = command([DRIVER, "--glibc", "-E", *definitions, "-"],
                             input=hosted_source, env=env).stdout
            expect("int hosted_setting_correct;" in output,
                   f"glibc hosted default or override failed: {definitions}")
        native_hosted = command([DRIVER, "-E", "-"], env=env, input=
                                "#ifdef __STDC_HOSTED__\n#error unexpected hosted mode\n"
                                "#endif\nint native_mode;\n").stdout
        expect("int native_mode;" in native_hosted,
               "glibc hosted default leaked into the native driver")
        assembly = td / "test.S"
        assembly.write_text(source + hosted_source.replace("EXPECTED", "1"))
        result = command([DRIVER, "--glibc", "-E", "-I", cli, assembly], env=env)
        expect("int selected;" in result.stdout,
               "preprocessed assembly did not use discovered include paths")

        output = td / "output"
        for script, message in (("#!/bin/sh\nexit 1\n", "discovery failed"),
                                ("#!/bin/sh\nprintf 'invalid output\\n' >&2\n", "cannot parse")):
            compiler.write_text(script)
            output.write_text("unchanged")
            result = command([DRIVER, "--glibc", "-E", "-o", output, "-"],
                             input="int value;\n", env=env, check=False)
            expect(result.returncode != 0 and message in result.stderr and
                   output.read_text() == "unchanged",
                   "failed header discovery did not preserve the output")
        bad_env = dict(env, CRUNCH_GLIBC_CC="relative-cc")
        result = command([DRIVER, "--glibc", "-c", "-o", output, "-"],
                         input="int value;\n", env=bad_env, check=False)
        expect(result.returncode != 0 and "absolute path" in result.stderr and
               output.read_text() == "unchanged",
               "relative compiler path was accepted for header discovery")
        command([DRIVER, "-E", "-"], input="int ordinary;\n", env=env)

        if ("CS_GNU_LIBC_VERSION" not in os.confstr_names or
                not os.confstr("CS_GNU_LIBC_VERSION") or not pathlib.Path("/usr/bin/cc").exists()):
            return
        real_env = dict(os.environ, CRUNCH_CONF_FILE="/dev/null", PATH="/usr/bin:/bin")
        for name in ("CRUNCH_INCLUDE_PATH", "CRUNCH_GLIBC_CC", "CPATH", "C_INCLUDE_PATH"):
            real_env.pop(name, None)
        glibc_driver = BUILD / "crunch"
        executable = td / "real-program"
        program = ("#define _GNU_SOURCE\n#include <stdio.h>\n#include <stdint.h>\n"
                   "#include <fcntl.h>\n"
                   "#if !defined(__GLIBC__) || !defined(__STDC_HOSTED__) || __STDC_HOSTED__ != 1\n"
                   "#error GNU hosted headers were not selected\n#endif\n"
                   "int main(void) { uint32_t value = 42; puts(\"discovered\"); return value; }\n")
        reference = command(["gcc", "-std=gnu11", "-funsigned-char", "-E", "-P", "-x", "c", "-"],
                            input=program, env=real_env)
        expect("int main" in reference.stdout,
               "host GCC did not accept the hosted header-selection probe")
        command([glibc_driver, "--glibc", "-o", executable, "-"], input=program, env=real_env)
        result = command([executable], check=False)
        expect(result.returncode == 42 and result.stdout == "discovered\n",
               "automatically discovered GNU headers did not produce a working program")
        platform_probe = ("#include <EGL/eglplatform.h>\n"
                          "#if defined(__unix__) && defined(__unix)\n"
                          "int unix_header_selected = 1;\n#else\n"
                          "int unix_header_selected = 0;\n#endif\n")
        reference = command(["gcc", "-std=gnu11", "-funsigned-char", "-E", "-P", "-x", "c", "-"],
                            input=platform_probe, env=real_env, check=False)
        if reference.returncode == 0:
            actual = command([glibc_driver, "--glibc", "-E", "-"],
                             input=platform_probe, env=real_env)
            marker = r"int\s+unix_header_selected\s*=\s*([01])\s*;"
            expect(re.findall(marker, actual.stdout) == re.findall(marker, reference.stdout) == ["1"],
                   "GNU Unix platform header selection differs from GCC")
        relative = td / "relative"
        relative.mkdir()
        (relative / "relative.h").write_text("int from_relative_path;\n")
        relative_env = dict(real_env, CPATH="relative")
        result = command([glibc_driver, "--glibc", "-E", "-"], cwd=td,
                         input="#include <relative.h>\n", env=relative_env)
        expect("int from_relative_path;" in result.stdout,
               "relative compiler include path was not discovered")
        obj = td / "link-only.o"
        command([glibc_driver, "--glibc", "-c", "-o", obj, "-"],
                input="int main(void) { return 42; }\n", env=real_env)
        compiler.write_text("#!/bin/sh\n"
                            "if [ \"$1\" = -E ]; then exit 99; fi\n"
                            "exec /usr/bin/cc \"$@\"\n")
        link_env = dict(real_env, CRUNCH_GLIBC_CC=str(compiler))
        command([glibc_driver, "--glibc", obj, "-o", executable], env=link_env)
        expect(command([executable], check=False).returncode == 42,
               "glibc link-only invocation unexpectedly queried include paths")
        native_stage = td / "native-stage"
        native_stage.mkdir()
        native_driver = native_stage / "crunch"
        command([DRIVER, "--static", "-D_Thread_local=", "-I", ROOT / "include",
                 ROOT / "src/driver/crunch_main.c", "-o", native_driver],
                env=real_env, timeout=360)
        for name in ("crunch-pp", "crunch-ir", "crunch-opt", "crunch-asm",
                     "libcrunch-support.a"):
            (native_stage / name).symlink_to(BUILD / name)
        command([native_driver, "--glibc", "-o", executable, "-"],
                input=program, env=real_env, timeout=240)
        result = command([executable], check=False)
        expect(result.returncode == 42 and result.stdout == "discovered\n",
               "native self-built driver could not discover GNU headers")


def gcc_stddef_preprocessor_case():
    """Check GCC's installed stddef header through Crunch's frontend when available.

    Returns:
        None; raises AssertionError for incorrect preprocessing or frontend behavior.
    """
    gcc = shutil.which("gcc")
    if not gcc:
        return
    result = command([gcc, "-E", "-x", "c", "-", "-v"], input="")
    begin = result.stderr.find("#include <...> search starts here:")
    end = result.stderr.find("End of search list.", begin)
    if begin < 0 or end < 0:
        return
    directories = [line.strip() for line in result.stderr[begin:end].splitlines()[1:]
                   if line.startswith(" ") and pathlib.Path(line.strip()).is_dir()]
    if not directories:
        return
    source = ("#include <stddef.h>\n"
              "int main(void) { size_t s = sizeof(int); ptrdiff_t d = 2; "
              "return s == 4 && d == 2 ? 0 : 1; }\n")
    command([gcc, "-std=c11", "-fsyntax-only", "-x", "c", "-"], input=source)
    with tempfile.TemporaryDirectory(prefix="crunch-gcc-stddef-") as td:
        conf = pathlib.Path(td) / "config"
        conf.write_text("")
        env = dict(os.environ, CRUNCH_INCLUDE_PATH=os.pathsep.join(directories),
                   CRUNCH_CONF_FILE=str(conf))
        expanded = command([PP, "-"], input=source, env=env).stdout
        command([IR, "-"], input=expanded)
        limits_source = ("#define _POSIX_C_SOURCE 200809L\n#include <limits.h>\n"
                         "int crunch_path_limit = PATH_MAX;\n")
        limits_reference = command([gcc, "-E", "-P", "-x", "c", "-"],
                                   input=limits_source).stdout
        limits_expanded = command([PP, "--no-crunch-includes", "-"],
                                  input=limits_source, env=env).stdout
        limit_pattern = r"int\s+crunch_path_limit\s*=\s*(\d+)\s*;"
        expect(re.findall(limit_pattern, limits_expanded) ==
               re.findall(limit_pattern, limits_reference) and
               re.findall(limit_pattern, limits_reference),
               "GNU limits.h did not expose the system PATH_MAX")
        stdarg_type = (
            "#define __need___va_list\n#include <stdarg.h>\n#include <stdarg.h>\n"
            "_Static_assert(sizeof(__builtin_va_list) == 24, \"size\");\n"
            "_Static_assert(_Alignof(__builtin_va_list) == 8, \"alignment\");\n"
            "int read_list(__gnuc_va_list list) { return list[0].gp_offset; }\n"
            "int main(void) { va_list list; list[0].gp_offset = 42; "
            "return read_list(list); }\n")
        command([gcc, "-std=c11", "-fsyntax-only", "-x", "c", "-"], input=stdarg_type)
        stdarg_expanded = command([PP, "-"], input=stdarg_type, env=env).stdout
        command([IR, "-"], input=stdarg_expanded)
        executable = pathlib.Path(td) / "stdarg-type"
        command([DRIVER, "--static", "-o", executable, "-"], input=stdarg_type, env=env)
        expect(command([executable], check=False).returncode == 42,
               "GCC builtin va_list type did not preserve array parameter behavior")
        no_defaults_env = dict(env, CRUNCH_INCLUDE_PATH="")
        missing = command([PP, "--no-crunch-includes", "-"], input="#include <stddef.h>\n",
                          env=no_defaults_env, check=False)
        expect(missing.returncode != 0, "preprocessor silently used Crunch's built-in headers")
        for fixture_name in ("variadic_args.bc", "variadic_aggregate.bc"):
            fixture = FIXTURES / "units/function_calls" / fixture_name
            expanded_fixture = command([PP, fixture], env=env).stdout
            header_paths = [os.fsdecode(bytes.fromhex(m)) for m in
                            re.findall(r"/\*CRUNCH-PP-MAP:\d+:([0-9a-f]+)\*/",
                                       expanded_fixture)]
            expect(any(p.endswith("/stdarg.h") and
                       not p.startswith(str(ROOT / "include") + os.sep) for p in header_paths),
                   "variadic fixture did not use GCC's stdarg header")
            obj = pathlib.Path(td) / "stdarg-fixture.o"
            command([DRIVER, "-c", fixture, "-o", obj], env=env)
            command([DRIVER, "--static", obj, "-o", executable], env=env)
            expect(command([executable], check=False).returncode == 0,
                   f"GCC stdarg fixture {fixture_name} failed")
        function_pointer = (
            "#include <stdarg.h>\nint plus(int n) { return n + 1; }\n"
            "int readfn(int n, ...) { va_list v; va_start(v, n); "
            "int (*f)(int) = va_arg(v, int (*)(int)); va_end(v); return f(41); }\n"
            "int main(void) { return readfn(0, plus) != 42; }\n")
        command([DRIVER, "-c", "-o", obj, "-"], input=function_pointer, env=env)
        command([DRIVER, "--static", obj, "-o", executable], env=env)
        expect(command([executable], check=False).returncode == 0,
               "GCC va_arg function-pointer type failed")
        for body, diagnostic in (
                ("__builtin_va_start(ap, x);", "final named parameter"),
                ("__builtin_va_copy(ap, 42);", "writable System V argument list"),
                ("__builtin_va_end(42);", "writable System V argument list"),
                ("(void)__builtin_va_arg(ap, float);", "va_arg supports promoted"),
                ("__builtin_va_arg(ap, int) = 1;", "modifiable lvalue")):
            invalid = ("int f(int x, int n, ...) { __builtin_va_list ap; " +
                       body + " return 0; }\n")
            result = command([IR, "--module", "-"], input=invalid, check=False)
            expect(result.returncode != 0 and diagnostic in result.stderr,
                   f"invalid GCC variadic builtin not rejected: {result.stderr}")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            abi_source = (
                "int read_list(__builtin_va_list ap) { return ap[0].gp_offset == 8 && "
                "ap[0].fp_offset == 48 && ap[0].overflow_arg_area != 0 && "
                "ap[0].reg_save_area != 0; }\n"
                "void write_list(__builtin_va_list ap) { ap[0].gp_offset = 16; }\n")
            host_source = (
                "#include <stdarg.h>\n"
                "extern int read_list(va_list); extern void write_list(va_list);\n"
                "int check(int n, ...) { va_list ap; va_start(ap, n); "
                "int ok = read_list(ap); write_list(ap); "
                "ok = ok && ap[0].gp_offset == 16; va_end(ap); return ok; }\n"
                "int main(void) { return !check(1, 42); }\n")
            abi_object = pathlib.Path(td) / "stdarg-abi.o"
            host_file = pathlib.Path(td) / "stdarg-host.c"
            host_file.write_text(host_source)
            command([DRIVER, "-c", "-o", abi_object, "-"], input=abi_source, env=env)
            command([gcc, "-no-pie", host_file, abi_object, "-o", executable])
            expect(command([executable], check=False).returncode == 0,
                   "GCC and Crunch disagreed on builtin va_list parameter layout")
            abi_source = (
                "#include <stdarg.h>\n"
                "struct pair { long i; double d; };\n"
                "extern int host_read(va_list);\n"
                "int crunch_read(int n, ...) { va_list a, b; va_start(a, n); "
                "va_copy(b, a); int v = va_arg(a, int); double d = va_arg(a, double); "
                "struct pair p = va_arg(a, struct pair); int copied = va_arg(b, int); "
                "va_end(b); va_end(a); return v == 42 && copied == 42 && d == 2.5 && "
                "p.i == 19 && p.d == 3.5; }\n"
                "int crunch_forward(int n, ...) { va_list a; va_start(a, n); "
                "int result = host_read(a); va_end(a); return result; }\n")
            host_source = (
                "#include <stdarg.h>\n"
                "struct pair { long i; double d; };\n"
                "extern int crunch_read(int, ...); extern int crunch_forward(int, ...);\n"
                "int host_read(va_list a) { int i = va_arg(a, int); "
                "double d = va_arg(a, double); struct pair p = va_arg(a, struct pair); "
                "return i == 42 && d == 2.5 && p.i == 19 && p.d == 3.5; }\n"
                "int main(void) { struct pair p = {19, 3.5}; "
                "return !(crunch_read(0, 42, 2.5, p) && "
                "crunch_forward(0, 42, 2.5, p)); }\n")
            host_file.write_text(host_source)
            command([DRIVER, "-c", "-o", abi_object, "-"], input=abi_source, env=env)
            command([gcc, "-no-pie", host_file, abi_object, "-o", executable])
            expect(command([executable], check=False).returncode == 0,
                   "GCC and Crunch disagreed on variadic argument consumption")
        freestanding = (
            "#include <stdint.h>\n"
            "#if INT8_MAX != 127 || UINT16_MAX != 65535 || "
            "INT_FAST32_MAX != 9223372036854775807L || "
            "UINT64_MAX != 18446744073709551615UL || "
            "SIG_ATOMIC_MIN != (-2147483647 - 1) || WINT_MAX != 4294967295U || "
            "INT64_C(42) != 42 || UINT32_C(42) != 42 || UINTMAX_C(42) != 42\n"
            "#error incorrect integer limits\n#endif\n"
            "_Static_assert(sizeof(int8_t) == 1 && sizeof(int16_t) == 2 && "
            "sizeof(int32_t) == 4 && sizeof(int64_t) == 8, \"exact widths\");\n"
            "_Static_assert(sizeof(int_fast16_t) == 8 && sizeof(uint_fast32_t) == 8 && "
            "sizeof(intptr_t) == 8 && sizeof(uintmax_t) == 8, \"target widths\");\n"
            "int main(void) { int32_t n = 42; return n; }\n")
        command([gcc, "-ffreestanding", "-std=c11", "-fsyntax-only", "-x", "c", "-"],
                input=freestanding)
        freestanding_expanded = command([PP, "-"], input=freestanding, env=env).stdout
        command([IR, "-"], input=freestanding_expanded)
        executable = pathlib.Path(td) / "freestanding"
        command([DRIVER, "--static", "-o", executable, "-"], input=freestanding, env=env)
        expect(command([executable], check=False).returncode == 42,
               "GCC freestanding stdint program did not execute")
        limits_source = (
            "#include <limits.h>\n"
            "#if CHAR_BIT != 8 || CHAR_MIN != 0 || CHAR_MAX != 255 || "
            "SCHAR_MIN != -128 || SCHAR_MAX != 127 || UCHAR_MAX != 255 || "
            "SHRT_MIN != -32768 || SHRT_MAX != 32767 || USHRT_MAX != 65535 || "
            "INT_MIN != (-2147483647 - 1) || INT_MAX != 2147483647 || "
            "UINT_MAX != 4294967295U || LONG_MAX != 9223372036854775807L\n"
            "#error incorrect GCC integer limits\n#endif\n"
            "int main(void) { char value = (char)255; return value == CHAR_MAX ? 42 : 1; }\n")
        command([gcc, "-ffreestanding", "-funsigned-char", "-std=c11",
                 "-fsyntax-only", "-x", "c", "-"], input=limits_source)
        limits_expanded = command([PP, "-"], input=limits_source, env=env).stdout
        command([IR, "-"], input=limits_expanded)
        command([DRIVER, "--static", "-o", executable, "-"], input=limits_source, env=env)
        expect(command([executable], check=False).returncode == 42,
               "GCC limits header program did not execute")
        float_source = (
            "#include <float.h>\n"
            "#if FLT_RADIX != 2 || FLT_EVAL_METHOD != 0 || DECIMAL_DIG != 21 || "
            "FLT_MANT_DIG != 24 || DBL_MANT_DIG != 53 || LDBL_MANT_DIG != 64 || "
            "FLT_DIG != 6 || DBL_DIG != 15 || LDBL_DIG != 18 || "
            "FLT_DECIMAL_DIG != 9 || DBL_DECIMAL_DIG != 17 || LDBL_DECIMAL_DIG != 21 || "
            "FLT_MIN_EXP != -125 || DBL_MIN_EXP != -1021 || LDBL_MIN_EXP != -16381 || "
            "FLT_MAX_EXP != 128 || DBL_MAX_EXP != 1024 || LDBL_MAX_EXP != 16384 || "
            "FLT_MIN_10_EXP != -37 || DBL_MIN_10_EXP != -307 || LDBL_MIN_10_EXP != -4931 || "
            "FLT_MAX_10_EXP != 38 || DBL_MAX_10_EXP != 308 || LDBL_MAX_10_EXP != 4932 || "
            "FLT_HAS_SUBNORM != 1 || DBL_HAS_SUBNORM != 1 || LDBL_HAS_SUBNORM != 1\n"
            "#error incorrect GCC floating-point format\n#endif\n"
            "_Static_assert(sizeof(FLT_MAX) == sizeof(float) && "
            "sizeof(DBL_MAX) == sizeof(double) && "
            "sizeof(LDBL_MAX) == sizeof(long double), \"floating types\");\n"
            "int main(void) {\n"
            "return FLT_MAX == 0x1.fffffep127f && FLT_MIN == 0x1p-126f && "
            "FLT_EPSILON == 0x1p-23f && FLT_TRUE_MIN == 0x1p-149f && "
            "DBL_MAX == 0x1.fffffffffffffp1023 && DBL_MIN == 0x1p-1022 && "
            "DBL_EPSILON == 0x1p-52 && DBL_TRUE_MIN == 0x1p-1074 && "
            "LDBL_MAX == 0x1.fffffffffffffffep16383L && LDBL_MIN == 0x1p-16382L && "
            "LDBL_EPSILON == 0x1p-63L && LDBL_TRUE_MIN == 0x1p-16445L ? 42 : 1;\n}\n")
        command([gcc, "-ffreestanding", "-std=c11", "-fsyntax-only", "-x", "c", "-"],
                input=float_source)
        float_expanded = command([PP, "-D__STDC_VERSION__=201112L", "-"],
                                 input=float_source, env=env).stdout
        command([IR, "-"], input=float_expanded)
        command([DRIVER, "--static", "-D__STDC_VERSION__=201112L", "-o", executable, "-"],
                input=float_source, env=env)
        expect(command([executable], check=False).returncode == 42,
               "GCC float header values differ from target floating formats")
        bits_source = ("#include <asm-generic/bitsperlong.h>\n"
                       "#if __BITS_PER_LONG != 64\n#error wrong long width\n#endif\n"
                       "int main(void) { return __BITS_PER_LONG - 22; }\n")
        reference = command([gcc, "-E", "-P", "-x", "c", "-"],
                            input=bits_source, check=False)
