            expect(not any(path.startswith(str(ROOT / "include") + os.sep) for path in paths),
                   "self-preprocessing silently used a Crunch system header")
            self_ir = command([IR, "--module", "-"], input=self_expanded, timeout=120).stdout
            self_ir_path = pathlib.Path(td) / "gnu-pp.bir"
