def dynamic_stack_ir_case():
    """Check dynamic stack IR allocation, restoration, and validation.

    Returns:
        None; raises AssertionError for incorrect execution or rejected validation.
    """
    ir = """CRUNCH-IR 50
func main 0 int
local 0 ptr
local 1 int
local 2 ptr
push 0
store 1 int
label L1
stackmark
store 0 ptr
push 33
stackalloc
dup
store 2 ptr
push 42
storeind int
drop
load 2
loadind int
push 42
ne int
jnz L2
load 0
stackrestore
load 1
push 1
add int
store 1 int
load 1
push 100000
lt int
jnz L1
push 42
ret int
label L2
push 1
ret int
end
"""
    with tempfile.TemporaryDirectory(prefix="crunch-stack-ir-") as td:
        directory = pathlib.Path(td)
        assembly, obj, exe = directory / "program.s", directory / "program.o", directory / "program"
        assembly.write_text(command([ASM, "-"], input=ir).stdout)
        command([TEST_AS, "-o", obj, assembly])
        command([*TEST_LINK, "-o", exe, obj, LIBCRUNCH])
        expect(command([exe], check=False, stack_size=1048576).returncode == 42,
               "dynamic stack allocation or restoration failed")
        for size in (18446744073709551615, 9223372036854775808):
            overflow = (f"CRUNCH-IR 50\nfunc main 0 int\npushu {size} ulong\n"
                        "stackalloc\ndrop\npush 0\nret int\nend\n")
            assembly.write_text(command([ASM, "-"], input=overflow).stdout)
            command([TEST_AS, "-o", obj, assembly])
            command([*TEST_LINK, "-o", exe, obj, LIBCRUNCH])
            result = subprocess.run([str(exe)], stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                    preexec_fn=lambda: resource.setrlimit(resource.RLIMIT_CORE, (0, 0)))
            expect(result.returncode == -signal.SIGILL,
                   f"oversized dynamic stack allocation did not trap: {size}")
    for version, instructions in (
        (49, "stackmark\ndrop\n"),
        (50, "push 1\nstackmark\ndrop\ndrop\n"),
        (50, "push 1\npush 2\nstackalloc\ndrop\ndrop\n"),
        (50, "push 1\nstackrestore\n"),
        (50, "stackmark extra\ndrop\n"),
    ):
        text = f"CRUNCH-IR {version}\nfunc main 0 int\n{instructions}push 0\nret int\nend\n"
        result = command([ASM, "--validate", "-"], input=text, check=False)
        expect(result.returncode != 0, f"invalid dynamic stack IR accepted: {text}")

def alignas_case():
    """Check C11 alignment specifiers, storage, and diagnostics.

    Returns:
        None; raises AssertionError for incorrect alignment or validation.
    """
    source = FIXTURES / "units/types/alignas.bc"
    helper = FIXTURES / "units/types/alignas_helper.s"
    command([SEMA, source, "expect-ok-repeat"])
    tree = json.loads(command([PARSER], input=command([LEXER, source]).stdout).stdout)
    expect(tree["version"] == 41, "aligned declarations did not select AST version 41")
    module_ir = command([IR, "--module", source]).stdout
    expect(module_ir.startswith("CRUNCH-IR 49\n"), "aligned module did not select IR version 49")
    command([ASM, "--validate", "-"], input=module_ir)
    with tempfile.TemporaryDirectory(prefix="crunch-alignas-") as td:
        directory = pathlib.Path(td)
        obj, helper_obj, exe = directory / "program.o", directory / "helper.o", directory / "program"
        command([TEST_AS, helper, "-o", helper_obj])
        command([DRIVER, "-c", source, "-o", obj])
        command([DRIVER, obj, helper_obj, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "aligned objects or structure layout were incorrect")
        abi_source = FIXTURES / "units/types/alignas_abi.bc"
        abi_helper = FIXTURES / "units/types/alignas_abi_helper.c"
        command([DRIVER, "-c", abi_source, "-o", obj])
        command([DRIVER, "-c", abi_helper, "-o", helper_obj])
        command([DRIVER, obj, helper_obj, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "aligned aggregate calls across Crunch modules failed")
        header = directory / "header.bc"
        header.write_text("#include <stdalign.h>\n"
                          "alignas(16) int x; int main(void) { "
                          "alignas(long double) char y; return sizeof y == 1 ? 42 : 1; }\n")
        command([DRIVER, header, "-o", exe])
        expect(command([exe], check=False).returncode == 42, "stdalign.h alignas failed")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            command(["cc", "-std=c11", "-pedantic-errors", "-x", "c", source,
                     "-x", "assembler", helper, "-o", exe])
            expect(command([exe], check=False).returncode == 42, "host alignment differs")
            command(["cc", "-std=c11", "-pedantic-errors", "-fno-asynchronous-unwind-tables",
                     "-fno-stack-protector", "-c", abi_helper, "-o", helper_obj])
            command([DRIVER, obj, helper_obj, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   "aligned aggregate calls across Crunch and C modules failed")
        for code in (
            "_Alignas(32) int x;",
            "_Alignas(3) int x;",
            "_Alignas(2) int x;",
            "_Alignas(-1) int x;",
            "int n; _Alignas(n) int x;",
            "_Alignas(void) int x;",
            "_Alignas(16) typedef int T;",
            "_Alignas(16) int f(void);",
            "struct S { _Alignas(16) int x : 1; };",
            "int main(void) { _Alignas(16) register int x; return 0; }",
        ):
            result = command([DRIVER, "--emit-ir", "-"], input=code + "\n", check=False)
            expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
                   f"invalid alignment accepted or rejected by wrong stage: {code}")

def preprocessor_if_case():
    """Check expression conditionals, arithmetic, macro expansion, and branch selection.

    Returns:
        None; raises AssertionError for incorrect selections or diagnostics.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-preprocessor-if-") as td:
        directory = pathlib.Path(td)
        source = directory / "if.bc"
        exe = directory / "program"
        source.write_text(
            "#define VERSION 12\n#define FLAG\n#define U 99\n"
            "#define TWICE(x) ((x) * 2)\n"
            "#if VERSION > 10 && defined(VERSION) && defined FLAG && !defined(MISSING)\n"
            "int chosen() { return TWICE(20) + 2; }\n"
            "#elif 1 / 0\n"
            "int chosen() { return 1; }\n"
            "#else\nint chosen() { return 2; }\n#endif\n"
            "#if 0\n#if 1 / 0\nbad\n#endif\n"
            "#elif UNKNOWN || 0\nbad\n"
            "#elif (0 ? 1 / 0 : 7) == 7\n"
            "#if 1 || 1 / 0\nint valid;\n#endif\n"
            "#else\nbad\n#endif\n"
            "#if 1U != 1 || 0x10UL != 16 || 077 != 63\nbad\n#endif\n"
            "#if !('A' == 65 && '\\n' == 10 && '\\x41' == 65 && '\\101' == 65)\n"
            "bad\n#endif\n"
            "#if (1 ? -1 : 0U) > 0 && (-1 < 0) && (-1 < 1U) == 0\n"
            "int unsigned_conversion;\n#else\nbad\n#endif\n"
            "#if (1 + 2 * 3 == 7) && (8 >> 2 == 2) && ((1 << 4) == 16)"
            " && ((~0 & 3) == 3) && ((5 ^ 3) == 6) && (5 % 3 == 2)\n"
            "int precedence;\n#else\nbad\n#endif\n"
            "#if (0xfffffffffffffffeU + 2U) == 0 && (0 && 1 / 0) == 0"
            " && (-8 >> 2) == -2 && defined /* comment */ (VERSION)\n"
            "int edge_arithmetic;\n#else\nbad\n#endif\n"
            "int main() { return chosen(); }\n"
        )
        expanded = command([PP, source]).stdout
        expect("bad" not in expanded and "int valid;" in expanded and
               "int unsigned_conversion;" in expanded and "int precedence;" in expanded and
               "int edge_arithmetic;" in expanded,
               f"incorrect #if branch selection:\n{expanded}")
        for flags in ([], ["-c"]):
            target = exe if not flags else directory / "program.o"
            command([DRIVER, *flags, source, "-o", target])
            if flags:
                command([DRIVER, target, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"#if program failed with flags {flags}")

        invalid = (
            "#if\n#endif\n", "#if 1 +\n#endif\n", "#if 09\n#endif\n",
            "#if 1.0\n#endif\n", "#if defined()\n#endif\n",
            "#if defined(VERSION\n#endif\n", "#if 1 / 0\n#endif\n",
            "#if 1 << 64\n#endif\n", "#if 9223372036854775807 + 1\n#endif\n",
            "#if 0 && (1 + )\n#endif\n", "#if 1 ? 2\n#endif\n",
            "#if 1\n#elif 1\n#else\n#else\n#endif\n",
            "#if 0\n#elif 2 / 0\n#endif\n",
            "#if 9223372036854775807 * 2\n#endif\n",
            "#if 0x10000000000000000U\n#endif\n",
            "#elif 1\n", "#if 1\n#else\n#elif 1\n#endif\n",
        )
        for text in invalid:
            source.write_text(text)
            result = command([PP, source], check=False)
            expect(result.returncode != 0 and result.stderr.strip(),
                   f"invalid conditional accepted: {text!r}")

        source.write_text("#if SELECTED == 12\nint selected;\n#else\nint wrong;\n#endif\n")
        result = command([PP, "-D", "SELECTED=12", source])
        expect("int selected;" in result.stdout and "int wrong;" not in result.stdout,
               "command-line macro did not participate in #if")

def preprocessor_error_line_case():
    """Check error directives and logical source locations across stages.

    Returns:
        None; raises AssertionError for incorrect diagnostics or source mapping.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-line-directive-") as directory:
        td = pathlib.Path(directory)
        source, header, exe = td / "source.bc", td / "child.h", td / "program"
        header.write_text('''#line 201 "child.bc"
const char *child_file = __FILE__;
int child_line = __LINE__;
''')
        source.write_text('''#include <string.h>
#define NUM 100
#define FILE_NAME "virtual.bc"
#line NUM FILE_NAME
int before = __LINE__;
#include "child.h"
int after = __LINE__;
const char *name = __FILE__;
#line 500
int main(void) {
    if (before != 100 || after != 102 || child_line != 202) return 1;
    if (strcmp(name, "virtual.bc") || strcmp(child_file, "child.bc")) return 2;
    return __LINE__ == 503 ? 0 : 3;
}
''')
        for flags in ([], ["--static"], ["--dynamic"], ["-pie"]):
            command([DRIVER, *flags, source, "-o", exe])
            command([exe])
        source.write_text('''#if 0
#error forbidden inactive error
#line not valid tokens
#endif
#line 71 "logical.c"
int main(void) { return missing_symbol; }
''')
        result = command([DRIVER, "--emit-ir", source], check=False)
        expect(result.returncode != 0 and "logical.c:71:" in result.stderr and
               "missing_symbol" in result.stderr,
               f"logical compiler diagnostic incorrect: {result.stderr}")
        source.write_text('''#line 12 "logical.c"
#error meaningful failure
''')
        result = command([DRIVER, "-E", source], check=False)
        expect(result.returncode != 0 and "logical.c:12: error: meaningful failure" in result.stderr,
               f"#error did not fail with its message and location: {result.stderr}")
        source.write_text('''#line 20 "warning.bc"
#define TEXT expanded
#warning TEXT /* hidden */ tail // ignored
#if 0
#warning inactive
#endif
int main(void) { return 42; }
''')
        result = command([DRIVER, "--static", source, "-o", exe])
        expect(command([exe], check=False).returncode == 42 and
               "warning.bc:21: warning: TEXT" in result.stderr and
               "tail" in result.stderr and
               all(word not in result.stderr for word in ("expanded", "hidden", "ignored", "inactive")),
               f"#warning diagnostic or execution incorrect: {result.stderr}")
        preprocessed = command([DRIVER, "-E", source])
        expect("warning.bc:21: warning: TEXT" in preprocessed.stderr and
               "TEXT" not in preprocessed.stdout,
               "preprocessing mixed warning diagnostics into stdout")
        comments = command([PP, "-"], input=
                           '#warning "/* kept */" /* hidden\n'
                           'still hidden */ int after_comment;\n')
        expect('"/* kept */"' in comments.stderr and "hidden" not in comments.stderr and
               "hidden" not in comments.stdout and "int after_comment;" in comments.stdout,
               "warning comments or quoted text were mishandled")
        source.write_text('#line 80 "warning.bc"\n#warning first \\\nsecond\n'
                          'int main(void) { return missing; }\n')
        result = command([DRIVER, "--emit-ir", source], check=False)
        expect(result.returncode != 0 and "warning.bc:80: warning: first second" in result.stderr and
               "warning.bc:82:" in result.stderr and "missing" in result.stderr,
               f"continued #warning lost source locations: {result.stderr}")
        assembly_source = td / "warning.S"
        assembly_source.write_text('#line 44 "warning.S"\n#warning assembly message\n.text\n')
        result = command([DRIVER, "-E", assembly_source])
        expect("warning.S:44: warning: assembly message" in result.stderr and
               "assembly message" not in result.stdout,
               "assembly preprocessing lost or mixed the warning")
        for operand in ("0", "2147483648", "-1", "4U", "5 extra", '"x"', '3 "unterminated',
                        '1 "bad\\0name"'):
            source.write_text(f"#line {operand}\n")
            result = command([PP, source], check=False)
            expect(result.returncode != 0 and "invalid #line directive" in result.stderr,
                   f"invalid #line {operand} was accepted: {result.stderr}")
        source.write_text(r'''#line \
44 "space \" and \\ name.bc"
__FILE__ __LINE__
#line 19
__FILE__ __LINE__
''')
        output = command([PP, source]).stdout
        expect(r'"space \" and \\ name.bc" 44' in output and
               r'"space \" and \\ name.bc" 19' in output,
               f"continued #line or escaped name failed: {output}")
        for assembler in (("crunch",) if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1"
                          else ("gnu", "crunch")):
            source = td / "invalid.S"
            source.write_text('#line 73 "generated.S"\ninvalid_instruction\n')
            flags = ["--with-crunch-as"] if assembler == "crunch" else []
            result = command([DRIVER, *flags, "-c", source,
                              "-o", td / "bad.o"], check=False)
            expect(result.returncode != 0 and "generated.S:73:" in result.stderr,
                   f"{assembler} assembler lost #line location: {result.stderr}")


def preprocessor_directives_end_to_end_case():
    """Check supported directives together through compilation and execution.

    Returns:
        None; raises AssertionError for incorrect directive removal or program output.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-preprocessor-directives-") as td:
        directory = pathlib.Path(td)
        source = directory / "program.bc"
        expanded_source = directory / "expanded.bc"
        ir_file = directory / "program.bir"
        asm_file = directory / "program.s"
        obj_file = directory / "program.o"
        executable = directory / "program"
        source.write_text(
            "#include <stdlib.h>\n"
            "#define FEATURE_ENABLED\n"
            "#macro BASE_VALUE 3\n"
            "#macro ADD(left, right) ((left) + (right))\n"
            "#ifdef FEATURE_ENABLED\n"
            "#macro SELECTED_VALUE 5\n"
            "#else\n"
            "#macro SELECTED_VALUE 99\n"
            "#endif\n"
            "#ifndef MISSING_FEATURE\n"
            "#macro ABSENT_BRANCH_VALUE 1\n"
            "#else\n"
            "#macro ABSENT_BRANCH_VALUE 99\n"
            "#endif\n"
            "#undef FEATURE_ENABLED\n"
            "#/**/undef/**/BASE_VALUE\n"
            "#undef ADD\n"
            "#ifdef FEATURE_ENABLED\n"
            "#macro DEFINED_AFTER_UNDEF 99\n"
            "#else\n"
            "#macro DEFINED_AFTER_UNDEF 1\n"
            "#endif\n"
            "#ifndef BASE_VALUE\n"
            "#macro MACRO_AFTER_UNDEF 1\n"
            "#else\n"
            "#macro MACRO_AFTER_UNDEF 99\n"
            "#endif\n"
            "int main() {\n"
            "    exit(SELECTED_VALUE + ABSENT_BRANCH_VALUE + "
            "DEFINED_AFTER_UNDEF + MACRO_AFTER_UNDEF);\n"
            "    return 0;\n"
            "}\n"
        )
        expanded = command([PP, source]).stdout
        expect("void noreturn exit(int status);" in expanded,
               "#include did not insert the runtime header")
        for unexpected in ("SELECTED_VALUE", "ABSENT_BRANCH_VALUE",
                           "DEFINED_AFTER_UNDEF", "MACRO_AFTER_UNDEF",
                           "FEATURE_ENABLED", "BASE_VALUE"):
            expect(unexpected not in expanded,
                   f"directive processing left unexpected token {unexpected}")
        expanded_source.write_text(expanded)
        ir_file.write_text(command([IR, expanded_source]).stdout)
        asm_file.write_text(command([ASM, ir_file]).stdout)
        command([TEST_AS, "-o", obj_file, asm_file])
        command([*TEST_LINK, "-o", executable, obj_file, LIBCRUNCH])
        result = command([executable], check=False)
        expect(result.returncode == 8,
               f"directive integration program exited {result.returncode}, expected 8")


def identifier_rules_case():
    """Check consistent ASCII identifier rules across preprocessing and lexing.

    Returns:
        None; raises AssertionError for inconsistent identifier acceptance.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-identifiers-") as td:
        directory = pathlib.Path(td)
        source = directory / "source.bc"
        expanded = directory / "expanded.bc"
        source.write_text(
            "#ifndef _Guard9\n"
            "#define _Guard9\n"
            "#macro _VALUE9 5\n"
            "#macro _ADD2(_left, right9) ((_left) + (right9))\n"
            "int valid_name9;\n"
            "int valid_func9(int _arg2) { return _ADD2(_VALUE9, _arg2); }\n"
            "#endif\n"
            "int main() { return valid_func9(0) - 5; }\n"
        )
        result = command([PP, source])
        expanded.write_text(result.stdout)
        expect("int valid_name9;" in result.stdout and
               "int valid_func9(int _arg2)" in result.stdout and
               "return ((5) + ( _arg2));" in result.stdout,
               "valid ASCII identifiers were not accepted consistently")
        expect(command([IR, expanded], check=False).returncode == 0,
               "accepted identifier syntax did not compile")

        invalid_inputs = {
            "digit-leading macro": "#macro 9VALUE 5\n",
            "punctuation in macro": "#macro $BAD 5\n",
            "digit-leading guard": "#define 9GUARD\n",
            "punctuation in guard": "#ifndef BAD-NAME\n#endif\n",
        }
        for label, contents in invalid_inputs.items():
            source.write_text(contents)
            invalid = command([PP, source], check=False)
            expect(invalid.returncode != 0,
                   f"preprocessor accepted {label}")

        invalid_declarations = {
            "digit-leading variable": "int 9value;\nint main() { return 0; }\n",
            "punctuation in variable": "int bad-name;\nint main() { return 0; }\n",
            "digit-leading function": "int 9func() { return 0; }\nint main() { return 0; }\n",
        }
        for label, contents in invalid_declarations.items():
            source.write_text(contents)
            invalid = command([IR, source], check=False)
            expect(invalid.returncode != 0,
                   f"Crunch accepted {label}")


def selective_memory_builtins_case():
    """Check that a program without memory operations omits unused helpers.

    Returns:
        None; raises AssertionError for unnecessary helper emission.
    """
    source_text = 'int printf(const char* format); int main() { printf("ok"); return 0; }\n'
    with tempfile.TemporaryDirectory(prefix="crunch-memory-selective-") as td:
        td = pathlib.Path(td)
        source, bir = td / "program.bc", td / "program.bir"
        source.write_text(source_text)
        bir.write_text(command([BUILD / "crunch-ir", source]).stdout)
        assembly = command([ASM, bir]).stdout
        for helper in ("memcpy", "memset", "memcmp"):
            expect(f"__crunch_{helper}:" not in assembly, f"unused {helper} helper was emitted")
        expect("__crunch_end:" not in assembly, "unused end helper was emitted")

