def type_keyword_case():
    """Check the structure and loop keywords across compiler stages.

    Returns:
        None; raises AssertionError for incorrect tokenization, rejection, or execution.
    """
    source_text = (
        "struct point { int x; }; typedef struct { int y; } Value;\n"
        "int main() { int type = 1, loop = 0, def = 0; struct point p; Value q;"
        " while (loop < 3) { loop++; if (loop == 2) continue; if (loop == 3) break; }"
        " if (loop != 3) return 1; p.x = 40; q.y = 1; return p.x + q.y + type + def; }\n"
    )
    tokens = command([LEXER, "-"], input=source_text).stdout
    records = [line.split("\t") for line in tokens.splitlines()[1:]]
    for kind, spelling in (("STRUCT", "struct"), ("LOOP", "while"), ("DEF", "typedef"),
                           ("IDENTIFIER", "type"), ("IDENTIFIER", "loop"), ("IDENTIFIER", "def")):
        expect(any(fields[0] == kind and fields[4] == spelling.encode().hex()
                   for fields in records), f"unexpected token for {spelling}")
    tree = json.loads(command([PARSER], input=tokens).stdout)
    expect(any(d["kind"] == "struct" and d["name"] == "point"
               for d in tree["declarations"]),
           "struct declaration changed the AST structure kind")
    expect('"kind": "loop"' in json.dumps(tree), "while changed the AST loop kind")
    for text in ("type point { int x; }; int main() { return 0; }\n",
                 "int main() { loop (1) { break; } return 0; }\n",
                 "def int Value; int main() { return 0; }\n",
                 "int main() { int struct = 1; return 0; }\n",
                 "int main() { int while = 1; return 0; }\n"):
        result = command([IR, "-"], input=text, check=False)
        expect(result.returncode != 0 and "E_PARSE" in result.stderr,
               f"obsolete syntax or reserved identifier was accepted: {text}")
    with tempfile.TemporaryDirectory(prefix="crunch-type-keyword-") as directory:
        source = pathlib.Path(directory) / "keyword.bc"
        source.write_text(source_text)
        compile_run(source, 42)
        obj, executable = pathlib.Path(directory) / "keyword.o", pathlib.Path(directory) / "keyword"
        command([DRIVER, "-c", source, "-o", obj])
        command([DRIVER, obj, "-o", executable])
        result = command([executable], check=False)
        expect(result.returncode == 42, f"module keyword test exited {result.returncode}")

