def hexadecimal_bitwise_case():
    """Run hexadecimal literals and bit operations through both compilation modes.

    Returns:
        None; raises AssertionError for incorrect execution or rejection.
    """
    fixture = FIXTURES / "units/expressions/hex_bitwise.bc"
    with tempfile.TemporaryDirectory(prefix="crunch-hex-bitwise-") as directory:
        td = pathlib.Path(directory)
        obj, exe, source = td / "hex.o", td / "program", td / "invalid.bc"
        for module in (False, True):
            if module:
                command([DRIVER, "-c", "-o", obj, fixture])
                command([DRIVER, "-o", exe, obj])
            else:
                command([DRIVER, "-o", exe, fixture])
            expect(command([exe], check=False).returncode == 42,
                   f"hexadecimal literals or bit operations failed (module={module})")

        for literal in ("0x", "0xg", "0x1z", "0x1_0"):
            source.write_text(f"long value = {literal};\nint main() {{ return 0; }}\n")
            result = command([IR, source], check=False)
            expect(result.returncode != 0 and "E_LEX_INVALID_TOKEN" in result.stderr,
                   f"malformed hexadecimal literal was not rejected by the lexer: {literal}")
        for declaration in ("long value = 0x10000000000000000",):
            source.write_text(declaration + ";\nint main() { return 0; }\n")
            result = command([IR, source], check=False)
            expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
                   f"out-of-range hexadecimal literal was not rejected: {declaration}")
        source.write_text("char value = (char)0x100;\nint main() { return value; }\n")
        result = command([IR, source], check=False)
        expect(result.returncode == 0 and "W_SEMANTIC" in result.stderr and
               "out of range" in result.stderr,
               "out-of-range hexadecimal conversion did not warn")
        for program in (
                "const int values[] = {1}; int main() { values[0] += 1; return 0; }",
                "int main() { int values[] = {1}; values[0] %= 1.5; return 0; }",
                "int main() { unsigned int values[] = {1U}; values[0] >>= 32U; return 0; }",
                "int main() { unsigned int values[] = {1U}; values[0] /= 0U; return 0; }"):
            result = command([DRIVER, "--emit-ir", "-"], input=program + "\n", check=False)
            expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
                   f"invalid indexed compound assignment accepted: {program}: {result.stderr}")
        main, helper = td / "main.bc", td / "helper.bc"
        main.write_text('''unsigned int shared = 4294967295U;
int counter = 7;
double rate = 2.5;
int update();
int indirect(unsigned int* p);
int increment(unsigned int* p);
int main() {
  if (update() != 42 || shared != 0U || counter != 9 || rate != 5.0) return 1;
  if (!indirect(&shared) || shared != 2U) return 2;
  if (!increment(&shared) || shared != 3U) return 3;
  return 42;
}
''')
        helper.write_text('''extern unsigned int shared;
extern int counter;
extern double rate;
int update() {
  if ((shared += 1U) != 0U || (counter += 2) != 9 ||
      (rate *= 2) != 5.0) return 1;
  return 42;
}
int indirect(unsigned int* p) { return (*p += 2U) == 2U; }
int increment(unsigned int* p) { return (*p)++ == 2U; }
''')
        main_obj, helper_obj = td / "main.o", td / "helper.o"
        command([DRIVER, "-c", main, "-o", main_obj])
        command([DRIVER, "-c", helper, "-o", helper_obj])
        command([DRIVER, main_obj, helper_obj, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "cross-module global compound assignments failed")
        for program in (
                "const int value = 1; int main() { value += 1; return 0; }",
                "double value = 1.0; int main() { value %= 2; return 0; }",
                "unsigned int value = 1U; int main() { value >>= 32U; return 0; }",
                "unsigned int value = 1U; int main() { value /= 0U; return 0; }"):
            result = command([DRIVER, "--emit-ir", "-"], input=program + "\n", check=False)
            expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
                   f"invalid global compound assignment accepted: {program}: {result.stderr}")
        for program in (
                "int main() { const int x = 1; const int* p = &x; *p += 1; return 0; }",
                "int main() { int x = 1; int* p = &x; *p %= 1.5; return 0; }",
                "int main() { unsigned int x = 1U; unsigned int* p = &x; *p >>= 32U; return 0; }",
                "int main() { unsigned int x = 1U; unsigned int* p = &x; *p /= 0U; return 0; }",
                "int main() { void* p; *p += 1; return 0; }"):
            result = command([DRIVER, "--emit-ir", "-"], input=program + "\n", check=False)
            expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
                   f"invalid pointer compound assignment accepted: {program}: {result.stderr}")
        for program in (
                "const int x = 1; int main() { x++; return 0; }",
                "int main() { const int x = 1; const int* p = &x; (*p)++; return 0; }",
                "int main() { const int x[] = {1}; ++x[0]; return 0; }",
                "struct A { const int x; }; int main() { struct A a; a.x++; return 0; }",
                "struct A { int x; }; int main() { struct A a; const struct A* p = &a; ++p->x; return 0; }"):
            result = command([DRIVER, "--emit-ir", "-"], input=program + "\n", check=False)
            expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
                   f"invalid numeric increment accepted: {program}: {result.stderr}")
        source.write_text("int counter; int main() { if (0) counter++; " +
                          "counter++;" * 520 +
                          " if (counter != 520) return 1; return 42; }\n")
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "numeric postfix temporary was not safely reused")
        source.write_text('''int counter = 5;
int main() {
  int values[] = {counter++, counter++};
  if (values[0] != 5 || values[1] != 6 || counter++ != 7 || counter != 8) return 1;
  return 42;
}
''')
        for module in (False, True):
            if module:
                command([DRIVER, "-c", source, "-o", obj])
                command([DRIVER, obj, "-o", exe])
            else:
                command([DRIVER, source, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"postfix updates failed in array initialization (module={module})")

def unsigned_frontend_case():
    """Check unsigned syntax and lossless AST literals.

    Returns:
        None; raises AssertionError for incorrect parsing.
    """
    fixture = FIXTURES / "units/parser/unsigned_frontend.bc"
    tree = json.loads(source_parse(fixture).stdout)
    declarations = {item["name"]: item for item in tree["declarations"]}
    expect(declarations["zero"]["type"]["kind"] == "unsigned_int", "missing unsigned int type")
    expect(declarations["maximum"]["type"]["kind"] == "unsigned_long", "missing unsigned long type")
    pointer = declarations["pointer"]["type"]
    expect(pointer["kind"] == "pointer" and pointer["pointee"]["kind"] == "unsigned_long" and
           pointer["pointee"]["const"], "unsigned pointer type or qualifier lost")
    expect(declarations["Word"]["type"]["kind"] == "unsigned_int", "unsigned alias lost")
    function = declarations["identity"]
    expect(function["return_type"]["kind"] == "unsigned_long" and
           function["parameters"][0]["type"]["kind"] == "unsigned_int",
           "unsigned function signature lost")

    for name, value, suffix, overflow in (
            ("zero", "0", "u", False), ("boundary", "4294967295", "u", False),
            ("above", "4294967296", "u", False),
            ("maximum", "18446744073709551615", "u", False),
            ("decimal_maximum", "18446744073709551615", "ul", False),
            ("forced", "1", "ul", False), ("reverse", "1", "ul", False),
            ("decimal", "8", "u", False),
            ("overflow", "18446744073709551615", "u", True),
            ("signed_hex", "4294967295", "none", False)):
        literal = declarations[name]["initializer"]["expression"]
        expect(literal["kind"] == "integer" and literal["value"] == value and
               literal["suffix"] == suffix and literal["out_of_range"] == overflow,
               f"incorrect literal representation for {name}: {literal}")
    signed_min = declarations["signed_min"]["initializer"]["expression"]
    expect(signed_min["kind"] == "unary" and signed_min["operand"]["value"] ==
           "-9223372036854775808" and signed_min["operand"]["suffix"] == "none" and
           signed_min["operand"]["out_of_range"], "signed minimum representation changed")

    with tempfile.TemporaryDirectory(prefix="crunch-unsigned-frontend-") as directory:
        source = pathlib.Path(directory) / "case.bc"
        for suffix in ("u", "U", "ul", "uL", "Ul", "UL", "lu", "lU", "Lu", "LU"):
            source.write_text(f"long value = 0Xff{suffix};\n")
            literal = json.loads(source_parse(source).stdout)["declarations"][0]["initializer"]["expression"]
            expect(literal["value"] == "255" and not literal["out_of_range"] and
                   literal["suffix"] == ("u" if len(suffix) == 1 else "ul"),
                   f"incorrect suffix handling: {suffix}")
        for literal in ("1UU", "1ULU", "1lL", "1Ll", "1ulL", "0xffUU",
                        "0x1ULfoo", "1.0U", "1e2U"):
            source.write_text(f"int main() {{ return {literal}; }}\n")
            result = command([LEXER, source], check=False)
            expect(result.returncode != 0 and "invalid token" in result.stderr.lower(),
                   f"invalid literal suffix accepted: {literal}")
        for declaration in ("unsigned unsigned int value;",):
            source.write_text(declaration + "\n")
            lexed = command([LEXER, source])
            result = command([PARSER], input=lexed.stdout, check=False)
            expect(result.returncode != 0 and not result.stdout.strip(),
                   f"invalid unsigned type accepted: {declaration}")
        source.write_text("int main() { return -18446744073709551616U; }\n")
        sema_case(source, False, "exceeds the range of unsigned long")


def character_types_case():
    """Check distinct signed and unsigned character types across compiler stages.

    Returns:
        None; raises AssertionError for incorrect typing, execution, or ABI behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-character-types-") as directory:
        td = pathlib.Path(directory)
        source = td / "characters.bc"
        source.write_text("""
signed char gs = -128;
unsigned char gu = 255;
signed char ga[3] = {-128, -1, 127};
unsigned char gb[3] = {0, 128, 255};
signed char text[] = "hi";
unsigned char bytes[] = "ok";
signed char converted = (signed char)255;
unsigned char converted_u = (unsigned char)-1;
int constant_signed = (signed char)255 + (signed char)1;
int constant_unsigned = (unsigned char)255 + (unsigned char)1;
int bound[(signed char)255 + 3];
signed char float_static = (signed char)-12.5;
unsigned char float_static_u = (unsigned char)255.5;
double real_signed = (signed char)255;
double real_unsigned = (unsigned char)255;
struct Pair { signed char s; unsigned char u; };
signed char identity(signed char x) { return x; }
int main() {
    signed char s = -128;
    unsigned char u = 255;
    signed char a[3] = {-128, -1, 127};
    unsigned char b[3] = {0, 128, 255};
    signed char local_text[] = "hi";
    unsigned char local_bytes[] = "ok";
    static signed char local_static = -3;
    static unsigned char local_static_u = 254;
    struct Pair p;
    p.s = -7; p.u = 240;
    signed char *sp = &a[0];
    unsigned char *up = &b[0];
    if (sizeof(s) != 1 || sizeof(u) != 1 || sizeof(p) != 2) return 1;
    if (s != -128 || u != 255 || s + u != 127 || sizeof(s + u) != 4) return 2;
    if (gs != -128 || gu != 255 || ga[1] != -1 || gb[2] != 255) return 3;
    if (sp[1] != -1 || up[1] != 128 || p.s != -7 || p.u != 240) return 4;
    if (identity(-5) != -5 || (signed char)255 != -1 ||
        (unsigned char)-1 != 255) return 5;
    if ((signed char)12.5 != 12 || (unsigned char)255.5 != 255) return 6;
    if (text[1] != 'i' || bytes[1] != 'k' || local_text[0] != 'h' ||
        local_bytes[0] != 'o' || local_static != -3 || local_static_u != 254 ||
        converted != -1 || converted_u != 255) return 7;
    if (constant_signed != 0 || constant_unsigned != 256 || sizeof(bound) != 8 ||
        float_static != -12 || float_static_u != 255 ||
        real_signed != -1.0 || real_unsigned != 255.0) return 8;
    if (-s != 128 || ~s != 127 || (s >> 1) != -64 ||
        (u >> 1) != 127 || sizeof(+u) != 4) return 9;
    switch (s) { case -128: break; default: return 10; }
    if (s++ != -128 || s != -127 || ++u != 0) return 11;
    s += 2; u += 255;
    if (s != -125 || u != 255) return 12;
    if (*++sp != -1 || *++up != 128 || (*sp)++ != -1 || *sp != 0) return 13;
    return 42;
}
""")
        tree = json.loads(source_parse(source).stdout)
        expect(tree["version"] == 19, "character types did not select AST v19")
        expect(tree["declarations"][0]["type"]["kind"] == "signed_char" and
               tree["declarations"][1]["type"]["kind"] == "unsigned_char",
               "character types lost their distinct AST identities")
        sema_case(source, True)
        ir, _ = compile_run(source, 42)
        expect(ir.startswith("CRUNCH-IR 16\n"), "character types did not select IR v16")
        module = command([IR, "--module", source]).stdout
        expect(module.startswith("CRUNCH-IR 17\n"), "character module did not select IR v17")
        command([ASM, "--validate"], input=module)
        for version in range(2, 16):
            for name in ("sbyte", "ubyte"):
                text = f"CRUNCH-IR {version}\nfunc main 0 int\npush 0\nret int\nneg {name}\nend\n"
                result = command([ASM, "--validate"], input=text, check=False)
                expect(result.returncode != 0 and not result.stdout,
                       f"IR v{version} accepted {name}")
        for kind, value in (("sbyte", "-129"), ("sbyte", "128"),
                            ("ubyte", "-1"), ("ubyte", "256")):
            text = f"CRUNCH-IR 16\nglobal value {kind} {value}\nfunc main 0 int\npush 0\nret int\nend\n"
            result = command([ASM, "--validate"], input=text, check=False)
            expect(result.returncode != 0 and not result.stdout,
                   f"out-of-range {kind} initializer {value} was accepted")
        raw_ir = td / "signed-byte.bir"
        raw_ir.write_text("CRUNCH-IR 16\nfunc main 0 int\n"
                          "push 255\npush 2\nlt sbyte\nret int\nend\n")
        compile_run(raw_ir, 1)
        for text in ("signed char *p; unsigned char *q; int main() { p = q; return 0; }",
                     "char *p; unsigned char *q; int main() { p = q; return 0; }",
                     "signed char f(signed char x); int f(signed char x);",
                     "int main() { signed char x = 1; x <<= 32; return x; }",
                     "int main() { switch (0) { case (signed char)255: break; "
                     "case -1: break; } return 0; }"):
            source.write_text(text + "\n")
            sema_case(source, False)
        source.write_text('#include <limits.h>\nint main() { '
                          'return SCHAR_MIN == -128 && SCHAR_MAX == 127 && '
                          'UCHAR_MAX == 255 ? 42 : 1; }\n')
        exe = td / "limits"
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 42, "character limits were incorrect")

        provider, consumer = td / "provider.bc", td / "consumer.bc"
        provider.write_text("signed char value = -8; unsigned char other = 250; "
                            "signed char identity(signed char x) { return x; }\n")
        consumer.write_text("extern signed char value; extern unsigned char other; "
                            "signed char identity(signed char x); int main() { "
                            "return value == -8 && other == 250 && identity(-2) == -2 ? 42 : 1; }\n")
        objects = [td / "provider.o", td / "consumer.o"]
        for unit, obj in zip((provider, consumer), objects):
            command([DRIVER, "-c", unit, "-o", obj])
        command([DRIVER, *objects, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "character types failed across Crunch modules")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1":
            return
        provider.write_text("""
extern signed char c_func(signed char a, unsigned char b, signed char c,
                          unsigned char d, signed char e, unsigned char f,
                          signed char g, unsigned char h);
struct Pair { signed char s; unsigned char u; };
signed char crunch_func(signed char a, unsigned char b, signed char c,
                        unsigned char d, signed char e, unsigned char f,
                        signed char g, unsigned char h) {
    if (a != -1 || b != 255 || c != -2 || d != 254 ||
        e != -3 || f != 253 || g != -4 || h != 252) return 0;
    return -99;
}
signed char invoke() { return c_func(-1, 255, -2, 254, -3, 253, -4, 252); }
extern unsigned char c_unsigned();
unsigned char invoke_unsigned() { return c_unsigned(); }
unsigned char crunch_unsigned() { return 254; }
signed char read_pair(struct Pair *p) { p->u = 251; return p->s; }
unsigned char data[3] = {1, 128, 255};
""")
        command([DRIVER, "-c", provider, "-o", objects[0]])
        host = td / "host.c"
        host.write_text("""
struct Pair { signed char s; unsigned char u; };
extern signed char crunch_func(signed char, unsigned char, signed char, unsigned char,
                               signed char, unsigned char, signed char, unsigned char);
extern signed char invoke(void), read_pair(struct Pair *);
extern unsigned char invoke_unsigned(void), crunch_unsigned(void);
extern unsigned char data[3];
signed char c_func(signed char a, unsigned char b, signed char c, unsigned char d,
                   signed char e, unsigned char f, signed char g, unsigned char h) {
    return a == -1 && b == 255 && c == -2 && d == 254 && e == -3 &&
           f == 253 && g == -4 && h == 252 ? -98 : 0;
}
unsigned char c_unsigned(void) { return 255; }
int main(void) {
    struct Pair p = {-5, 0};
    return crunch_func(-1,255,-2,254,-3,253,-4,252) != -99 ||
           invoke() != -98 || read_pair(&p) != -5 || p.u != 251 ||
           data[0] != 1 || data[1] != 128 || data[2] != 255 ||
           invoke_unsigned() != 255 || crunch_unsigned() != 254;
}
""")
        command(["cc", "-no-pie", host, objects[0], "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "signed or unsigned char C ABI mismatch")


def integer_specifier_case():
    """Check equivalent integer type spellings and invalid specifier combinations.

    Returns:
        None; raises AssertionError for an incorrect type or accepted invalid spelling.
    """
    specifiers = {
        "int": (("int",), ("signed",), ("signed", "int")),
        "unsigned_int": (("unsigned",), ("unsigned", "int")),
        "short": (("short",), ("short", "int"), ("signed", "short"),
                  ("signed", "short", "int")),
        "unsigned_short": (("unsigned", "short"), ("unsigned", "short", "int")),
        "long": (("long",), ("long", "int"), ("signed", "long"),
                 ("signed", "long", "int")),
        "unsigned_long": (("unsigned", "long"), ("unsigned", "long", "int")),
        "long_long": (("long", "long"), ("long", "long", "int"),
                      ("signed", "long", "long"), ("signed", "long", "long", "int")),
        "unsigned_long_long": (("unsigned", "long", "long"),
                               ("unsigned", "long", "long", "int")),
        "signed_char": (("signed", "char"),),
        "unsigned_char": (("unsigned", "char"),),
    }
    with tempfile.TemporaryDirectory(prefix="crunch-integer-specifiers-") as directory:
        source = pathlib.Path(directory) / "types.bc"
        declarations = [(kind, " ".join(order))
                        for kind, groups in specifiers.items()
                        for group in groups for order in itertools.permutations(group)]
        source.write_text("\n".join(f"{spelling} value_{i};"
                                    for i, (_, spelling) in enumerate(declarations)) + "\n")
        tree = json.loads(source_parse(source).stdout)
        for declaration, (kind, spelling) in zip(tree["declarations"], declarations):
            expect(declaration["type"]["kind"] == kind, f"incorrect type for {spelling}")
        sema_case(source, True)
        source.write_text("unsigned const long int value = 42; "
                          "signed int long identity(signed long int x) { return x; } "
                          "int main() { return (int)identity(value); }\n")
        compile_run(source, 42)
        for spelling in ("signed unsigned", "short long", "long long long", "signed signed int",
                         "unsigned unsigned", "int int", "short short", "signed float",
                         "short char", "char int", "signed unsigned char",
                         "unsigned double", "double long long", "double int", "double double"):
            source.write_text(f"{spelling} value;\n")
            lexed = command([LEXER, source])
            result = command([PARSER], input=lexed.stdout, check=False)
            expect(result.returncode != 0 and not result.stdout.strip(),
                   f"invalid or unsupported type accepted: {spelling}")
        source.write_text("long double a; double long b; "
                          "double c = 1.0000000000000000001L; "
                          "double d = 1e4932l;\n")
        tree = json.loads(source_parse(source).stdout)
        expect(tree["version"] == 33, "extended-real syntax did not select AST v33")
        expect(tree["declarations"][0]["type"]["kind"] == "long_double" and
               tree["declarations"][1]["type"]["kind"] == "long_double",
               "long double type spellings were not preserved")
        for declaration, literal in zip(tree["declarations"][2:],
                                        ("1.0000000000000000001L", "1e4932l")):
            expression = declaration["initializer"]["expression"]
            expect(expression["type"] == "long_double" and expression["value"] == literal,
                   f"extended literal lost precision: {expression}")
        sema_case(source, True)
        for declaration in ("long double *p;", "struct S { long double value; };",
                            "int f(void) { return sizeof(long double); }"):
            source.write_text(declaration + "\n")
            sema_case(source, True)
        source.write_text(r'''
struct layout { char c; long double value; char end; };
int sizes[sizeof(long double) == 16 && sizeof(struct layout) == 48 ? 1 : -1];
int precise[1.0000000000000000001084202172485504434L > 1.0L ? 1 : -1];
int mixed[(1.0L + 0.0000000000000000001084202172485504434L) > 1.0 ? 1 : -1];
int hexadecimal[0x1.0000000000000002p0L > 1.0L ? 1 : -1];
int extended_range[1e4932L > 1e308 ? 1 : -1];
int main(void) { return 0; }
''')
        sema_case(source, True)
        source.write_text(r'''
int not_equal[1.0000000000000000001084202172485504434L == 1.0 ? 1 : -1];
''')
        sema_case(source, False, "array")
        source.write_text("int main(void) { return 1.0L % 2; }\n")
        sema_case(source, False, "integer operator")
        source.write_text("long double x = 1e4933L;\n")
        sema_case(source, False, "out of range")
        source.write_text("int main(void) { int n = 0; "
                          "return sizeof(long double) == 16 && "
                          "sizeof((n++, 0x1p0L + 1.0)) == 16 && "
                          "0x1.8p2 == 6.0 && 0x1p-1f == 0.5f && n == 0 ? 42 : 1; }\n")
        compile_run(source, 42)
        source.write_text("int main(void) { return "
                          "0x1.0000000000000002p0L > 1.0L && "
                          "1.0L + 0x1p-63L > 1.0 && "
                          "(int)(-123.75L) == -123 ? 42 : 1; }\n")
        compile_run(source, 42)
        pointer_executable = pathlib.Path(directory) / "long_double_pointer"
        command([DRIVER, FIXTURES / "units/types/long_double_pointer.bc", "-o",
                 pointer_executable])
        expect(command([pointer_executable], check=False).returncode == 0,
               "long double pointer arithmetic used the wrong element size")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            wrapper = pathlib.Path(directory) / "pointer.bc"
            host = pathlib.Path(directory) / "pointer.c"
            obj = pathlib.Path(directory) / "pointer.o"
            wrapper.write_text("long double *advance_extended(long double *p, int n) "
                               "{ return &p[n]; }\n")
            host.write_text("extern long double *advance_extended(long double *, int);\n"
                            "int main(void) { long double values[4]; "
                            "return advance_extended(values, 3) != &values[3] || "
                            "advance_extended(values + 2, -1) != &values[1]; }\n")
            command([DRIVER, "-c", wrapper, "-o", obj])
            command(["cc", "-std=c11", "-Wall", "-Wextra", "-Werror", "-no-pie",
                     host, obj, "-o", pointer_executable])
            expect(command([pointer_executable], check=False).returncode == 0,
                   "host long double pointer interoperability failed")


def unsigned_source_case():
    """Execute scalar unsigned source and check unsupported lowering boundaries.

    Returns:
        None; raises AssertionError for incorrect output, execution, or diagnostics.
    """
    source = FIXTURES / "units/types/unsigned_runtime.bc"
    compile_run(source, 42, checks=("CRUNCH-IR 6", "pushu", "div uint", "div ulong",
                                    "global max64 ulong 18446744073709551615"))
    with tempfile.TemporaryDirectory(prefix="crunch-unsigned-source-") as directory:
        td = pathlib.Path(directory)
        ir = command([IR, "--module", source]).stdout
        expect(ir.startswith("CRUNCH-IR 7\n"), "unsigned module did not use IR v7")
        assembly = td / "module.s"
        obj, exe = td / "module.o", td / "module"
        assembly.write_text(command([ASM, "-"], input=ir).stdout)
        command([TEST_AS, "-o", obj, assembly])
        command([*TEST_LINK, "-o", exe, obj, LIBCRUNCH])
        expect(command([exe], check=False).returncode == 42, "unsigned module execution failed")

        module = td / "abi.bc"
        module.write_text("""
extern unsigned long c_mix(unsigned int a, unsigned long b);
unsigned long from_c(unsigned int x) { return c_mix(x, 0xffffffffffffffffUL); }
unsigned int seventh(unsigned int a, unsigned int b, unsigned int c,
                     unsigned int d, unsigned int e, unsigned int f, unsigned int g) {
    return g;
}
unsigned long to_c(unsigned int x) { return x; }
""")
        ir = command([IR, "--module", module]).stdout
        assembly.write_text(command([ASM, "-"], input=ir).stdout)
        command(["as", "-o", obj, assembly])
        host = td / "host.c"
        host.write_text(
            "extern unsigned long from_c(unsigned int), to_c(unsigned int);\n"
            "extern unsigned int seventh(unsigned int, unsigned int, unsigned int, "
            "unsigned int, unsigned int, unsigned int, unsigned int);\n"
            "unsigned long c_mix(unsigned int a, unsigned long b) { "
            "return a == 0xffffffffU ? b : 0; }\n"
            "int main(void) { return from_c(0xffffffffU) != 0xffffffffffffffffUL || "
            "to_c(0xffffffffU) != 0xffffffffUL || "
            "seventh(1,2,3,4,5,6,0xffffffffU) != 0xffffffffU; }\n")
        command(["cc", "-no-pie", host, obj, "-o", exe])
        expect(command([exe], check=False).returncode == 0, "unsigned source C ABI failed")

def unsigned_arrays_case():
    """Execute unsigned arrays and pointers, including size boundaries and C interop.

    Returns:
        None; raises AssertionError for incorrect execution or ABI behavior.
    """
    source = FIXTURES / "units/types/fixed_unsigned_arrays.bc"
    compile_run(source, 42, checks=("ptradd uint",))
    for name in ("legacy_unsigned_arrays.bir", "legacy_unsigned_arrays_module.bir"):
        compile_run(FIXTURES / "ir" / name, 42,
                    checks=("array_resize uint", "array_resize ulong"))
    with tempfile.TemporaryDirectory(prefix="crunch-unsigned-arrays-") as directory:
        td = pathlib.Path(directory)
        assembly, obj, exe = td / "module.s", td / "module.o", td / "module"
        ir = command([IR, "--module", source]).stdout
        assembly.write_text(command([ASM, "-"], input=ir).stdout)
        command([TEST_AS, "-o", obj, assembly])
        command([*TEST_LINK, "-o", exe, obj, LIBCRUNCH])
        expect(command([exe], check=False).returncode == 42,
               "unsigned array module execution failed")

        module = td / "abi.bc"
        module.write_text("""
unsigned int shared[] = {0xffffffffU, 2U};
extern unsigned int* c_next(unsigned int* p);
unsigned int* from_c(unsigned int* p) { return c_next(p); }
unsigned long read_long(unsigned long* p) { return p[1]; }
void write_int(unsigned int* p) { p[0] = 0xffffffffU; }
""")
        ir = command([IR, "--module", module]).stdout
        assembly.write_text(command([ASM, "-"], input=ir).stdout)
        command(["as", "-o", obj, assembly])
        host = td / "host.c"
        host.write_text(
            "extern unsigned int shared[], *from_c(unsigned int *);\n"
            "extern unsigned long read_long(unsigned long *);\n"
            "extern void write_int(unsigned int *);\n"
            "unsigned int *c_next(unsigned int *p) { return p + 1; }\n"
            "int main(void) { unsigned int a[2] = {0, 7}; "
            "unsigned long b[2] = {0, 0xffffffffffffffffUL}; "
            "write_int(a); return a[0] != 0xffffffffU || *from_c(a) != 7 || "
            "read_long(b) != 0xffffffffffffffffUL || shared[0] != 0xffffffffU || "
            "shared[1] != 2; }\n")
        command(["cc", "-no-pie", host, obj, LIBCRUNCH, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "unsigned pointer C ABI or global startup failed")

        main, helper = td / "main.bc", td / "helper.bc"
        main.write_text("unsigned long shared[2] = {0xffffffffffffffffUL, 0UL}; "
                        "int update(); int main() { if (update() != 2 || "
                        "shared[0] != 0xffffffffffffffffUL || shared[1] != 7UL) return 1; "
                        "return 42; }\n")
        helper.write_text("extern unsigned long shared[]; int update() { "
                          "shared[1] = 7UL; return 2; }\n")
        main_obj, helper_obj = td / "main.o", td / "helper.o"
        command([DRIVER, "-c", main, "-o", main_obj])
        command([DRIVER, "-c", helper, "-o", helper_obj])
        command([DRIVER, main_obj, helper_obj, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "unsigned array failed across Crunch modules")

        allocated = td / "allocated.bc"
        allocated.write_text(
            "#include <stdlib.h>\nint main() { unsigned int* p = malloc(8U); "
            "if (!p) return 1; p[0] = 0xffffffffU; p[1] = 7U; "
            "if (*p != 0xffffffffU || p[1] != 7U) return 2; free(p); return 42; }\n")
        command([DRIVER, allocated, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "unsigned pointer from malloc did not preserve values")

        invalid = td / "invalid.bc"
        for text in (
                "int main() { unsigned int u; int* p = &u; return 0; }",
                "int main() { const unsigned int u = 1U; unsigned int* p = &u; return 0; }",
                "int main() { const unsigned int a[] = {1U}; a[0] = 2U; return 0; }"):
            invalid.write_text(text + "\n")
            sema_case(invalid, False)

        ir = (FIXTURES / "ir/legacy_unsigned_array_boundaries.bir").read_text()
        assembly.write_text(command([ASM, "-"], input=ir).stdout)
        command(["as", "-o", obj, assembly])
        host.write_text(
            "#include <stddef.h>\n"
            "extern int local_count(unsigned long), resize_count(unsigned int);\n"
            "static unsigned int calls; static unsigned long requested;\n"
            "void *__crunch_alloc_bytes(unsigned long n) { ++calls; requested = n; return 0; }\n"
            "void __crunch_free_bytes(void *p) { (void)p; }\n"
            "int main(void) { "
            "local_count(2147483647UL); "
            "if (calls != 1 || requested != 8589934588UL) return 1; "
            "local_count(2147483648UL); local_count(0xffffffffffffffffUL); "
            "if (calls != 1) return 2; "
            "resize_count(2147483647U); "
            "if (calls != 2 || requested != 17179869176UL) return 3; "
            "resize_count(2147483648U); resize_count(0xffffffffU); "
            "return calls != 2; }\n")
        command(["cc", "-no-pie", host, obj, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "unsigned array count boundary handling failed")

def unsigned_semantics_case():
    """Check unsigned conversions, typed constants, layouts, and invalid operations.

    Returns:
        None; raises AssertionError for incorrect semantic acceptance or diagnostics.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-unsigned-sema-") as directory:
        source = pathlib.Path(directory) / "case.bc"
        source.write_text("""
struct Values { unsigned int a; unsigned long b; unsigned int *p; };
unsigned long convert(unsigned int x, long y) { return x + y; }
int main() {
    unsigned int u = -1;
    unsigned long wide = 18446744073709551615UL;
    long signed_value = wide;
    int narrow = u;
    char small = u;
    double r = wide;
    unsigned int *p = 0U;
    int *q = (0U + 0U);
    struct Values values;
    u = (unsigned int)r;
    u += 1;
    wide >>= 63;
    return sizeof(values) + sizeof(u) + sizeof(wide) + sizeof(1 << 1U) +
           (p == q) + convert(u, signed_value) + small + narrow;
}
""")
        # Distinct signed/unsigned object pointers remain incompatible.
        sema_case(source, False, "equality operands have incompatible types")
        text = source.read_text().replace("(p == q)", "(p == 0U) + (q == 0)")
        source.write_text(text)
        sema_case(source, True)
        for expression in (
                "(0xffffffffU + 1U) == 0U",
                "(-1 < 1U) == 0",
                "((long)-1 < 1U) == 1",
                "(0xffffffffffffffffUL / 2UL) == 9223372036854775807U",
                "(0x8000000000000000U >> 63) == 1",
                "(-1U) == 0xffffffffU",
                "(1 ? -1 : 0U) == 0xffffffffU",
                "((int)0xffffffffU) == -1",
                "((unsigned int)1.9) == 1U",
                "(9007199254740993U + 0.0) == 9007199254740992.0",
                "((unsigned long)(double)9007199254740993U) == 9007199254740992UL",
                "(1U ? 2.0 : 3.0) == 2.0",
                "!(0U + 0.0)",
                "(1U && 0.5) == 1",
                "(1U / 0.0) > 1.0",
                "sizeof(1U) == 4",
                "sizeof(4294967296U) == 8",
                "sizeof(1 << 1UL) == 4"):
            source.write_text(f"int main() {{ switch (0) {{ case !({expression}): break; "
                              "case 0: break; } return 0; }\n")
            sema_case(source, False, "duplicate case label")
            source.write_text("int main() { switch (0) { "
                              "case 4294967295U: break; case -1: break; } return 0; }\n")
            sema_case(source, False, "duplicate case label")
        source.write_text("int main() { unsigned int u = 0; switch (u) { "
                          "case -1: break; case 4294967295U: break; } return 0; }\n")
        sema_case(source, False, "duplicate case label")
        for expression, diagnostic in (
                ("1U << 32", "shift count"),
                ("1UL >> 64", "shift count"),
                ("1 << -1U", "shift count"),
                ("1U / 0", "division by zero"),
                ("1U % 0", "remainder by zero")):
            source.write_text(f"int main() {{ return {expression}; }}\n")
            sema_case(source, False, diagnostic)
        for expression in ("(unsigned int)-1.0", "(unsigned int)(1U / 0.0)",
                           "(unsigned int)(0U / 0.0)",
                           "(unsigned long)18446744073709551616.0"):
            source.write_text(f"int main() {{ return {expression}; }}\n")
            result = command([IR, source], check=False)
            expect(result.returncode == 0 and "W_SEMANTIC" in result.stderr and
                   "out of range" in result.stderr,
                   f"out-of-range conversion did not warn: {expression}: {result.stderr}")
        for operation, diagnostic in (("u <<= 32", "shift count"),
                                      ("u /= 0", "division by zero"),
                                      ("u %= 0", "remainder by zero")):
            source.write_text(f"int main() {{ unsigned int u = 1U; {operation}; return 0; }}\n")
            sema_case(source, False, diagnostic)
        source.write_text("int main() { double r = 1.0; r /= 0U; return 0; }\n")
        sema_case(source, True)
        for expression in ("0U && f()", "1U ? 0 : f()"):
            source.write_text(f"int f() {{ return 1; }} int main() {{ "
                              f"switch (0) {{ case {expression}: break; }} return 0; }}\n")
            sema_case(source, False, "case label is not an integer constant expression")

def unsigned_ir_case():
    """Execute versioned unsigned IR and reject invalid or legacy uses.

    Returns:
        None; raises AssertionError for incorrect execution or IR validation.
    """
    def real_bits(value):
        """Return the raw binary64 spelling for a floating-point value.

        Args:
            value: Python float to encode.
        Returns:
            Hexadecimal IR bit-pattern spelling.
        """
        return "0x" + struct.pack(">d", value).hex()

    checks = [
        "pushu 4294967295 uint\npushu 1 uint\ngt uint",
        "pushu 4294967295 uint\npushu 1 uint\nadd uint\npushu 0 uint\neq uint",
        "pushu 1 uint\nneg uint\npushu 4294967295 uint\neq uint",
        "pushu 2147483648 uint\npushu 1 uint\nshl uint\npushu 0 uint\neq uint",
        "pushu 240 uint\npushu 15 uint\nbxor uint\npushu 255 uint\neq uint",
        "pushu 256 uint\npushu 2 uint\ndiv byte\npush 0\neq byte",
        "pushu 4294967295 uint\npushu 2 uint\ndiv uint\npushu 2147483647 uint\neq uint",
        "pushu 4294967295 uint\npushu 2 uint\nrem uint\npushu 1 uint\neq uint",
        "pushu 2147483648 uint\npushu 31 uint\nshr uint\npushu 1 uint\neq uint",
        "pushu 18446744073709551615 ulong\npushu 1 ulong\ngt ulong",
        "pushu 18446744073709551615 ulong\npushu 2 ulong\ndiv ulong\n"
        "pushu 9223372036854775807 ulong\neq ulong",
        "pushu 18446744073709551615 ulong\npushu 2 ulong\nrem ulong\npushu 1 ulong\neq ulong",
        "pushu 9223372036854775808 ulong\npushu 63 ulong\nshr ulong\npushu 1 ulong\neq ulong",
        "pushu 4294967295 uint\ncast uint long\npush 4294967295\neq long",
        "push -4294967296\nbool uint\npush 0\neq int",
        "push -1\ncast uint uint\ncast uint ulong\npushu 4294967295 ulong\neq ulong",
        "push -1\ncast int ulong\npushu 18446744073709551615 ulong\neq ulong",
        "pushu 18446744073709551615 ulong\ncast ulong int\npush -1\neq int",
        "pushu 4294967295 uint\ncast uint real\npushr " + real_bits(4294967295.0) + "\neq real",
        "pushu 18446744073709551615 ulong\ncast ulong real\npushr " + real_bits(2.0**64) + "\neq real",
        "pushu 9223372036854776833 ulong\ncast ulong real\npushr " +
        real_bits(float(9223372036854776833)) + "\neq real",
        "pushr " + real_bits(4294967295.0) + "\ncast real uint\npushu 4294967295 uint\neq uint",
        "pushr " + real_bits(2.0**63) + "\ncast real ulong\npushu 9223372036854775808 ulong\neq ulong",
        "pushr " + real_bits(2.0**64) + "\ncast real ulong\npushu 0 ulong\neq ulong",
        "pushr 0x43efffffffffffff\ncast real ulong\n"
        "pushu 18446744073709549568 ulong\neq ulong",
        "pushr " + real_bits(-0.5) + "\ncast real ulong\npushu 0 ulong\neq ulong",
        "pushr 0x7ff8000000000000\ncast real uint\npushu 0 uint\neq uint",
        "gload g32 uint\npushu 4294967295 uint\neq uint",
        "gload g64 ulong\npushu 18446744073709551615 ulong\neq ulong",
        "pushu 4294967295 uint\nstore 0 uint\nload 0\npushu 4294967295 uint\neq uint",
        "pushu 4294967295 uint\nlstore field uint\nlload field uint\npushu 4294967295 uint\neq uint",
        "laddr field\npush 1\nptradd uint\npushu 2147483648 uint\nstoreind uint\n"
        "pushu 2147483648 uint\neq uint",
        "lload field2 uint\npushu 2147483648 uint\neq uint",
        "pushu 2147483648 uint\ngstore alias uint\ngload alias uint\n"
        "pushu 2147483648 uint\neq uint",
        "gaddr g32\npushu 2147483648 uint\nstoreind uint\npushu 2147483648 uint\neq uint",
        "gload g32 uint\npushu 2147483648 uint\neq uint",
        "gaddr g32\nloadind uint\npushu 2147483648 uint\neq uint",
        "pushu 4294967295 uint\ncall identity32 1\npushu 4294967295 uint\neq uint",
        "pushu 18446744073709551615 ulong\ncall identity64 1\n"
        "pushu 18446744073709551615 ulong\neq ulong",
        "push 2\narray_alloc uint\nstore 1 ptr\nstore 2 long\n"
        "load 1\npush 1\nptradd uint\npushu 4294967295 uint\nstoreind uint\n"
        "pushu 4294967295 uint\neq uint",
        "load 1\npush 1\nptradd uint\nloadind uint\npushu 4294967295 uint\neq uint",
        "load 1\nload 2\npush 0\narray_resize uint\nstore 1 ptr\nstore 2 long\npush 1",
        "push 2\narray_alloc ulong\nstore 1 ptr\nstore 2 long\n"
        "load 1\npush 1\nptradd ulong\npushu 18446744073709551615 ulong\n"
        "storeind ulong\npushu 18446744073709551615 ulong\neq ulong",
        "load 1\npush 1\nptradd ulong\nloadind ulong\npushu 18446744073709551615 ulong\neq ulong",
        "load 1\nload 2\npush 0\narray_resize ulong\nstore 1 ptr\nstore 2 long\npush 1",
    ]
    body = "\n".join(test + "\njz L999" for test in checks)
    template = """global g32 uint 4294967295
global g64 ulong 18446744073709551615
globalblock record 8 8
globalalias alias record 0 uint
func main 0 int
local 0 uint
local 1 ptr
local 2 long
localblock object 8 8
localalias field object 0 uint
localalias field2 object 4 uint
""" + body + """
push 42
ret int
label L999
push 1
ret int
end
func identity32 1 uint
param 0 0 uint
load 0
ret uint
end
func identity64 1 ulong
param 0 0 ulong
load 0
ret ulong
end
"""
    with tempfile.TemporaryDirectory(prefix="crunch-unsigned-ir-") as directory:
        td = pathlib.Path(directory)
        ir, assembly, obj, exe = (td / "values.bir", td / "values.s",
                                  td / "values.o", td / "values")
        for version in (6, 7):
            ir.write_text(f"CRUNCH-IR {version}\n" + template)
            assembly.write_text(command([ASM, ir]).stdout)
            command([TEST_AS, "-o", obj, assembly])
            command([*TEST_LINK, "-o", exe, obj, LIBCRUNCH])
            expect(command([exe], check=False).returncode == 42,
                   f"unsigned IR execution failed for version {version}")
            command([BUILD / "crunch-as", "-o", obj, assembly])
            command([*TEST_LINK, "-o", exe, obj, LIBCRUNCH])
            expect(command([exe], check=False).returncode == 42,
                   f"native-assembled unsigned IR execution failed for version {version}")
            initializer = f"""CRUNCH-IR {version}
global initialized uint 0
internal setup
initializer setup
func setup 0 int
pushu 42 uint
gstore initialized uint
push 0
ret int
end
func main 0 int
gload initialized uint
cast uint int
ret int
end
"""
            assembly.write_text(command([ASM, "-"], input=initializer).stdout)
            command([TEST_AS, "-o", obj, assembly])
            command([*TEST_LINK, "-o", exe, obj, LIBCRUNCH])
            expect(command([exe], check=False).returncode == 42,
                   f"unsigned IR v{version} did not run its initializer")
        main_ir = "func main 0 int\npush 0\nret int\nend\n"
        for version in (2, 3, 4, 5):
            for unsigned_line in ("global x uint 1", "func ignored 0 uint\npush 0\nret uint\nend",
                                  "func ignored 0 int\npush 0\nret int\nadd ulong\nend",
                                  "func ignored 0 int\npushu 1 uint\nret int\nend"):
                result = command([ASM, "-"], input=f"CRUNCH-IR {version}\n" +
                                 unsigned_line + "\n" + main_ir, check=False)
                expect(result.returncode != 0 and not result.stdout,
                       f"legacy IR v{version} accepted unsigned syntax: {unsigned_line}")
        for instruction in ("pushu -1 ulong", "pushu +1 uint", "pushu 4294967296 uint",
                            "pushu 18446744073709551616 ulong", "pushu 1 int",
                            "pushu 1 ulong extra", "pushu 0xff uint"):
            result = command([ASM, "-"], input="CRUNCH-IR 6\nfunc main 0 int\npush 0\nret int\n" +
                             instruction + "\nend\n", check=False)
            expect(result.returncode != 0 and result.stderr and not result.stdout,
                   f"invalid unreachable unsigned literal accepted: {instruction}")
        for declaration in ("global x uint 4294967296", "global x ulong -1",
                            "global x ulong 18446744073709551616"):
            result = command([ASM, "-"], input="CRUNCH-IR 6\n" + declaration + "\n" +
                             main_ir, check=False)
            expect(result.returncode != 0 and result.stderr and not result.stdout,
                   f"invalid unsigned global accepted: {declaration}")
        legacy = "CRUNCH-IR 2\nglobal uint int 1\n" + main_ir
        expect(command([ASM, "-"], input=legacy, check=False).returncode == 0,
               "legacy symbol named uint was rejected")

        module = """CRUNCH-IR 7
extern_func dirty 0 uint
extern_func c_mix 7 ulong uint uint uint uint uint uint ulong
func from_c 0 ulong
call dirty 0
cast uint ulong
ret ulong
end
func invoke_c 0 ulong
pushu 1 uint
pushu 2 uint
pushu 3 uint
pushu 4 uint
pushu 5 uint
pushu 4294967295 uint
pushu 18446744073709551615 ulong
call c_mix 7
ret ulong
end
func identity32 1 uint
param 0 0 uint
load 0
ret uint
end
func identity64 1 ulong
param 0 0 ulong
load 0
ret ulong
end
func seventh32 7 uint
param 0 0 uint
param 1 1 uint
param 2 2 uint
param 3 3 uint
param 4 4 uint
param 5 5 uint
param 6 6 uint
load 6
ret uint
end
"""
        assembly.write_text(command([ASM, "-"], input=module).stdout)
        command(["as", "-o", obj, assembly])
        host, dirty = td / "host.c", td / "dirty.s"
        host.write_text("#include <stdint.h>\n"
                        "extern unsigned int identity32(unsigned int);\n"
                        "extern unsigned int seventh32(unsigned int, unsigned int, unsigned int, "
                        "unsigned int, unsigned int, unsigned int, unsigned int);\n"
                        "extern unsigned long from_c(void), invoke_c(void), identity64(unsigned long);\n"
                        "unsigned long c_mix(unsigned int a, unsigned int b, unsigned int c, "
                        "unsigned int d, unsigned int e, unsigned int f, unsigned long g) { "
                        "return a == 1 && b == 2 && c == 3 && d == 4 && e == 5 && "
                        "f == 0xffffffffU && g == 0xffffffffffffffffUL ? g : 0; }\n"
                        "int main(void) { return from_c() != 0xffffffffUL || "
                        "invoke_c() != 0xffffffffffffffffUL || "
                        "identity32(0xffffffffU) != 0xffffffffU || "
                        "seventh32(1, 2, 3, 4, 5, 6, 0xffffffffU) != 0xffffffffU || "
                        "identity64(0xffffffffffffffffUL) != 0xffffffffffffffffUL; }\n")
        dirty.write_text(".text\n.globl dirty\ndirty:\n"
                         "movabs $0x12345678ffffffff,%rax\nret\n"
                         '.section .note.GNU-stack,"",@progbits\n')
        command(["cc", "-no-pie", host, dirty, obj, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "unsigned C ABI parameter or result was corrupted")

def module_initialization_case():
    """Check legacy IR module initialization across link modes and startup runtimes.

    Returns:
        None; raises AssertionError for incorrect initialization or IR validation.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-module-init-") as directory:
        td = pathlib.Path(directory)
        obj1, obj2, obj3 = (td / name for name in ("first.o", "second.o", "main.o"))
        exe, combined = td / "program", td / "combined.o"
        for name, obj in (("first", obj1), ("second", obj2), ("main", obj3)):
            text = (FIXTURES / "ir" / f"legacy_initializer_{name}.bir").read_text()
            assembly = td / f"{name}.s"
            assembly.write_text(command([ASM, "-"], input=text).stdout)
            command([TEST_AS, "-o", obj, assembly])
        expect((FIXTURES / "ir/legacy_initializer_first.bir").read_text().startswith("CRUNCH-IR 4\n"),
               "initialized module did not use the versioned initializer contract")
        command([DRIVER, "-o", exe, obj1, obj2, obj3])
        expect(command([exe], check=False).returncode == 42,
               "module startup order or initialization failed")
        command([DRIVER, "-c", "-o", combined, obj1, obj2, obj3])
        command([DRIVER, "-o", exe, combined])
        expect(command([exe], check=False).returncode == 42,
               "relocatable link lost module initialization")

        library_obj = td / "library.o"
        assembly = td / "library.s"
        assembly.write_text(command([ASM, FIXTURES / "ir/legacy_initializer_library.bir"]).stdout)
        command([TEST_AS, "-o", library_obj, assembly])
        host = td / "host.c"
        host.write_text("extern int read_module(void);"
                        "extern void __crunch_run_initializers(void);"
                        "int main(void) { if (read_module() != 42) return 1;"
                        "__crunch_run_initializers();"
                        "return read_module(); }\n")
        command(["cc", "-no-pie", host, library_obj, LIBCRUNCH, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "C startup or repeated explicit initialization failed")
        start = td / "start.s"
        start.write_text(".text\n.globl _start\n_start:\n"
                         "and $-16,%rsp\ncall __crunch_run_initializers\n"
                         "call __crunch_run_initializers\ncall read_module\n"
                         "mov %eax,%edi\nmov $60,%eax\nsyscall\n"
                         '.section .note.GNU-stack,"",@progbits\n')
        command([DRIVER, "-o", exe, start, library_obj])
        expect(command([exe], check=False).returncode == 42,
               "custom entry point did not initialize modules exactly once")

        for directive in ("initializer missing", "initializer main",
                          "initializer x extra", "initializer x\ninitializer x"):
            text = ("CRUNCH-IR 4\n" + directive +
                    "\nfunc main 0 int\npush 0\nret int\nend\n")
            result = command([ASM, "-"], input=text, check=False)
            expect(result.returncode != 0 and result.stderr.strip() and not result.stdout,
                   f"invalid module initializer IR was accepted: {directive}")
        old_ir = ("CRUNCH-IR 3\ninitializer main\nfunc main 0 int\n"
                  "push 0\nret int\nend\n")
        expect(command([ASM, "-"], input=old_ir, check=False).returncode != 0,
               "IR v3 accepted an initializer directive")

def executable_initialization_case():
    """Check legacy IR global initializers run once, even when main recurs.

    Returns:
        None; raises AssertionError for incorrect startup, recursion, or IR validation.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-executable-init-") as directory:
        td = pathlib.Path(directory)
        obj, exe, assembly = td / "source.o", td / "program", td / "source.s"
        ir = (FIXTURES / "ir/legacy_initializer_executable.bir").read_text()
        expect(ir.startswith("CRUNCH-IR 5\n") and
               "\ninitializer crunch_module_init_2\n" in ir and "call printf 1\n" in ir,
               "executable runtime initialization did not use IR v5")
        result = command([ASM, "-"], input=ir.replace("call printf 1\n",
                                                       "runtime_call printf 1\n"),
                         check=False)
        expect(result.returncode != 0, "IR v5 accepted a module runtime call")
        env = {"CRUNCH_INIT": "ok"}
        for name in ("executable", "executable_module"):
            fixture = FIXTURES / "ir" / f"legacy_initializer_{name}.bir"
            assembly.write_text(command([ASM, fixture]).stdout)
            command([TEST_AS, "-o", obj, assembly])
            command([DRIVER, "-o", exe, obj])
            expect(command([exe, "x"], env=env, check=False).returncode == 42,
                   f"{name} reinitialized globals when main recurred")

        other_obj = td / "other.o"
        assembly.write_text(command([ASM, FIXTURES / "ir/legacy_initializer_mixed.bir"]).stdout)
        command([TEST_AS, "-o", obj, assembly])
        assembly.write_text(command([ASM, FIXTURES / "ir/legacy_initializer_other.bir"]).stdout)
        command([TEST_AS, "-o", other_obj, assembly])
        command([DRIVER, "-o", exe, obj, other_obj])
        expect(command([exe, "x"], env=env, check=False).returncode == 42,
               "executable and module initializers did not both run")

        main_ir = "func main 0 int\npush 0\nret int\nend\n"
        for invalid in (
                "",
                "initializer missing\n",
                "initializer main\n",
                "initializer x extra\n",
                "internal x\ninitializer x\ninitializer x\n"
                "func x 0 int\npush 0\nret int\nend\n",
                "initializer x\nfunc x 0 int\npush 0\nret int\nend\n",
                "internal x\ninitializer x\nfunc x 0 long\npush 0\nret long\nend\n",
                "internal x\ninitializer x\nfunc x 1 int\nparam 0 0 int\npush 0\nret int\nend\n",
                "extern_func x 0 int\ninitializer x\n"):
            invalid = "CRUNCH-IR 5\n" + invalid + main_ir
            result = command([ASM, "-"], input=invalid, check=False)
            expect(result.returncode != 0 and result.stderr.strip() and not result.stdout,
                   f"invalid executable initializer IR was accepted: {invalid}")
        no_main = ("CRUNCH-IR 5\ninternal init\ninitializer init\n"
                   "func init 0 int\npush 0\nret int\nend\n")
        result = command([ASM, "-"], input=no_main, check=False)
        expect(result.returncode != 0 and "main" in result.stderr,
               "IR v5 accepted an executable without main")
        legacy = ("CRUNCH-IR 2\ninternal init\ninitializer init\n"
                  "func init 0 int\npush 0\nret int\nend\n"
                  "func main 0 int\npush 0\nret int\nend\n")
        expect(command([ASM, "-"], input=legacy, check=False).returncode != 0,
               "IR v2 accepted an initializer directive")
        expect(command([ASM, "-"], input="CRUNCH-IR 2\n" + main_ir).returncode == 0,
               "legacy executable IR was rejected")

        allocator = td / "allocator.o"
        command(["as", "-o", allocator,
                 FIXTURES / "units/dynamic_arrays/failing_allocator.s"])
        for module in (False, True):
            assembly = td / "program.s"
            fixture = FIXTURES / "ir" / f"legacy_initializer_failure{'_module' if module else ''}.bir"
            assembly.write_text(command([ASM, fixture]).stdout)
            command([TEST_AS, "-o", obj, assembly])
            command([*TEST_LINK, "-o", exe, obj, allocator, LIBCRUNCH])
            expect(command([exe], check=False).returncode == 42,
                   f"failed initializer was retried (module={module})")

def static_linkage_case():
    """Check file-scope static linkage and invalid declarations.

    Returns:
        None; raises AssertionError for incorrect visibility or compilation behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-static-") as directory:
        td = pathlib.Path(directory)
        source = td / "source.bc"
        source.write_text(
            "struct Box { int value; };\n"
            "static struct Box box;\n"
            "static int hidden = 20, other = 1;\n"
            'static char text[] = "X";\n'
            "static int helper(int n);\n"
            "int helper(int n) { return n + hidden + other + text[0] - 88 + box.value; }\n"
            "int main() { return helper(21); }\n"
        )
        tokens = command([LEXER, source]).stdout
        expect("STATIC\t" in tokens, "static was not tokenized as a keyword")
        tree = json.loads(command([PARSER], input=tokens).stdout)
        declarations = tree["declarations"]
        expect([d["static"] for d in declarations if d["kind"] != "struct"] ==
               [True, True, True, True, True, False, False],
               "AST did not preserve each static specifier")
        ir = command([IR, source]).stdout
        emitted_assembly = command([ASM, "-"], input=ir).stdout
        for name in ("box", "hidden", "other", "text", "helper"):
            expect(f".local {name}\n" in emitted_assembly,
                   f"{name} is not object-local: {emitted_assembly}")
        obj, other, assembly, exe = (td / "source.o", td / "other.o",
                                     td / "other.s", td / "program")
        command([DRIVER, "-c", "-o", obj, source])
        assembly.write_text(".text\n.globl helper\nhelper:\n ret\n.data\n"
                            ".globl hidden, other, text, text$length, box\n"
                            "hidden:\n .long 1\nother:\n .long 0\n"
                            "text:\n .quad 0\ntext$length:\n .long 0\nbox:\n .long 0\n"
                            ".section .note.GNU-stack,\"\",@progbits\n")
        command([TEST_AS, "-o", other, assembly])
        command([*TEST_LINK, "-o", exe, obj, other, LIBCRUNCH])
        expect(command([exe], check=False).returncode == 42,
               "static symbols collided or the compiled program misbehaved")

        for text in ("int f(); static int f() { return 1; } int main() { return 0; }",
                     "static int main() { return 0; }"):
            source.write_text(text)
            result = command([IR, source], check=False)
            expect(result.returncode != 0 and result.stderr.strip(),
                   f"invalid static declaration accepted: {text}")
        for directive in ("internal missing", "internal main", "internal main extra",
                          "internal x\ninternal x\nglobal x int 0"):
            ir = "CRUNCH-IR 2\n" + directive + "\nfunc main 0 int\npush 0\nret int\nend\n"
            result = command([ASM, "-"], input=ir, check=False)
            expect(result.returncode != 0 and result.stderr.strip() and not result.stdout,
                   f"invalid internal IR accepted: {directive}")

def global_static_string_case():
    """Check legacy IR static bytes and their transition to allocated storage.

    Returns:
        None; raises AssertionError for incorrect storage, copying, or release behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-global-bytes-") as directory:
        td = pathlib.Path(directory)
        obj, stub, stub_obj, exe = (td / "source.o",
                                            td / "free.s", td / "free.o", td / "program")
        ir = (FIXTURES / "ir/legacy_global_static_string.bir").read_text()
        expect("globalbytes first 41004200\n" in ir and
               "global first$length int 4\n" in ir,
               f"missing static string data in IR: {ir}")
        assembly = command([ASM, "-"], input=ir).stdout
        expect(".section .data\n" in assembly and ".quad .Lcrunch_initial_" in assembly,
               "global string storage was not emitted in writable data")
        asm_file = td / "source.s"
        asm_file.write_text(assembly)
        command([TEST_AS, "-o", obj, asm_file])
        stub.write_text(
            ".text\n.globl __crunch_free_bytes\n__crunch_free_bytes:\n"
            " test %rdi,%rdi\n jz 1f\n test %rsi,%rsi\n jz 1f\n"
            " addl $1, frees(%rip)\n mov $11,%eax\n syscall\n1: ret\n"
            '.section .note.GNU-stack,"",@progbits\n'
        )
        command(["as", "-o", stub_obj, stub])
        for linker in (["ld"], NATIVE_LINK):
            command([*linker, "-o", exe, obj, stub_obj, LIBCRUNCH])
            result = command([exe], check=False)
            expect(result.returncode == 42,
                   f"global static array check failed with {linker[0]}: {result.returncode}")

        no_resize = (FIXTURES / "ir/legacy_global_static_no_resize.bir").read_text()
        expect("array_resize" not in no_resize and "globalbytes text 7465737400\n" in no_resize,
               "string initialization still allocates at startup")
        for directive in ("globalbytes missing 4100",
                          "global x ptr 0\nglobal x$length int 2\nglobalbytes x 41",
                          "global x ptr 0\nglobal x$length int 3\nglobalbytes x 4100",
                          "global x ptr 0\nglobal x$length int 2\nglobalbytes x 4100\nglobalbytes x 4100"):
            result = command([ASM, "-"], input="CRUNCH-IR 2\n" + directive +
                             "\nfunc main 0 int\npush 0\nret int\nend\n", check=False)
            expect(result.returncode != 0 and result.stderr.strip() and not result.stdout,
                   f"invalid global byte directive accepted: {directive}")

def cross_object_static_array_case():
    """Check that resize protects static array storage from another object.

    Returns:
        None; raises AssertionError for incorrect cross-object ownership handling.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-static-objects-") as directory:
        td = pathlib.Path(directory)
        objects = []
        for index in range(2):
            ir = (FIXTURES / "ir" / f"legacy_cross_object_static_{index}.bir").read_text()
            asm = command([ASM, "-"], input=ir).stdout
            expect(".global _start\n" not in asm, "module without main emitted an entry point")
            assembly, obj = td / f"unit{index}.s", td / f"unit{index}.o"
            assembly.write_text(asm)
            command(["as", "-o", obj, assembly])
            objects.append(obj)
        harness, harness_obj = td / "harness.s", td / "harness.o"
        harness.write_text(
            ".text\n.globl _start\n_start:\n"
            " mov words(%rip),%rax\n add $1,%rax\n mov %rax,shared(%rip)\n"
            " movl $2,shared$length(%rip)\n call probe\n mov %rax,%rdi\n mov $60,%eax\n syscall\n"
            ".globl __crunch_free_bytes\n__crunch_free_bytes:\n"
            " test %rdi,%rdi\n jz 1f\n test %rsi,%rsi\n jz 1f\n"
            " mov words(%rip),%rax\n add $1,%rax\n cmp %rax,%rdi\n je 2f\n"
            " mov $11,%eax\n syscall\n1: ret\n"
            "2: mov $99,%edi\n mov $60,%eax\n syscall\n"
            ".data\n.globl shared, shared$length\nshared: .quad 0\nshared$length: .long 0\n"
            '.section .note.GNU-stack,"",@progbits\n'
        )
        command(["as", "-o", harness_obj, harness])
        combined = td / "combined.o"
        for linker in (["ld"], NATIVE_LINK):
            command([*linker, "-r", "-o", combined, *objects])
            for inputs in (objects, list(reversed(objects)), [combined]):
                exe = td / "program"
                command([*linker, "-o", exe, harness_obj, *inputs, LIBCRUNCH])
                result = command([exe], check=False)
                expect(result.returncode == 42,
                       f"cross-object static array was incorrectly released by {linker[0]}: "
                       f"{result.returncode}")
        reserved = ("CRUNCH-IR 2\nglobal __start___crunch_static_arrays int 0\n"
                    "func main 0 int\npush 0\nret int\nend\n")
        result = command([ASM, "-"], input=reserved, check=False)
        expect(result.returncode != 0 and "reserved array registry" in result.stderr,
               "a definition of the linker registry symbol was accepted")

def special_runtime_override_case():
    """Check user-first formatted and vfork calls, and their runtime fallbacks.

    Returns:
        None; raises AssertionError on a compile, link, or execution failure.
    """
    for version, count, valid in ((39, 130, True), (39, 131, False), (37, 129, False)):
        ir = (f"CRUNCH-IR {version}\nextern_func target 0 int\nfunc main 0 int\n"
              "fnaddr target\n" + "push 0\n" * count +
              f"callptr {count} int" + " int" * count + "\nret int\nend\n")
        result = command([ASM, "--validate"], input=ir, check=False)
        expect((result.returncode == 0) == valid,
               f"IR v{version} callptr argument boundary was not enforced at {count}")
    for version, marker, valid in (
            (39, "__crunch_fallback_printf", True),
            (39, "__crunch_fallback_fprintf", True),
            (39, "__crunch_fallback_snprintf", True),
            (39, "__crunch_fallback_vfork", True),
            (39, "__crunch_fallback_not_reserved", False),
            (37, "__crunch_fallback_printf", False)):
        ir = (f"CRUNCH-IR {version}\nfunc main 0 int\nweak_fnaddr {marker}\n"
              "drop\npush 0\nret int\nend\n")
        result = command([ASM, "--validate"], input=ir, check=False)
        expect((result.returncode == 0) == valid,
               f"IR v{version} weak function marker validation failed for {marker}")
    for version, directives, valid in (
            (39, "require_user_runtime printf\n", True),
            (39, "require_user_runtime unknown\n", False),
            (39, "require_user_runtime printf\nrequire_user_runtime printf\n", False),
            (37, "require_user_runtime printf\n", False)):
        ir = f"CRUNCH-IR {version}\n{directives}func main 0 int\npush 0\nret int\nend\n"
        result = command([ASM, "--validate"], input=ir, check=False)
        expect((result.returncode == 0) == valid,
               f"IR v{version} runtime guard validation failed for {directives!r}")
    with tempfile.TemporaryDirectory(prefix="crunch-special-override-") as directory:
        td = pathlib.Path(directory)
        main, helper, fallback = td / "main.bc", td / "helper.bc", td / "fallback.bc"
        main.write_text(
            "int printf(const char* format); int vfork(void); "
            'int main() { return printf("x", 19, 2.0) + vfork(); }\n')
        helper.write_text(
            "#include <stdarg.h>\n"
            "int printf(const char* format, ...) { va_list ap; va_start(ap, format); "
            "int x = va_arg(ap, int); double y = va_arg(ap, double); va_end(ap); return x + y; } "
            "int vfork(void) { return 21; }\n")
        fallback.write_text(
            'int printf(const char* format); int main() { printf("ok%d", 1); return 42; }\n')
        objects = [td / "main.o", td / "helper.o", td / "fallback.o"]
        for source, obj in zip((main, helper, fallback), objects):
            command([DRIVER, "-c", source, "-o", obj])
        archive, combined = td / "helper.a", td / "combined.o"
        command([DRIVER, "--archive", objects[1], "-o", archive])
        command([DRIVER, "-c", *objects[:2], "-o", combined])
        shared = td / "helper.so"
        command([BUILD / "crunch-ld", "-nostdlib", "-shared", "-o", shared, objects[1]])
        for flags in (["--static"], ["--dynamic"], ["--dynamic", "-pie"]):
            inputs_list = [objects[:2], [objects[0], archive], [combined], [objects[2]]]
            if "--dynamic" in flags:
                inputs_list.append([objects[0], shared])
            for inputs in inputs_list:
                exe = td / "program"
                command([DRIVER, *flags, "--rpath", td, *inputs, "-o", exe] if "--dynamic" in flags
                        else [DRIVER, *flags, *inputs, "-o", exe])
                result = command([exe], check=False)
                expected = "ok1" if inputs == [objects[2]] else ""
                expect(result.returncode == 42 and result.stdout == expected,
                       f"special runtime override failed ({flags}, {inputs}): "
                       f"{result.returncode} {result.stdout!r} {result.stderr!r}")

        vfork_source = td / "vfork.bc"
        vfork_source.write_text(
            "#include <unistd.h>\n#include <sys/wait.h>\n"
            "int main() { int status = 0; pid_t p = vfork(); "
            "if (p == 0) _exit(7); if (p < 0 || waitpid(p, &status, 0) != p) return 1; "
            "return status == (7 << 8) ? 42 : 2; }\n")
        for mode in ("--static", "--dynamic"):
            command([DRIVER, mode, vfork_source, "-o", td / "vfork"])
            expect(command([td / "vfork"], check=False).returncode == 42,
                   f"runtime vfork fallback failed ({mode})")

        other_main, other_helper = td / "other-main.bc", td / "other-helper.bc"
        other_main.write_text(
            "struct FILE { int unused; }; "
            "int fprintf(struct FILE* stream, const char* format); "
            "int snprintf(char* buffer, unsigned long size, const char* format); "
            "int main() { char b[4]; return fprintf(0, \"x\", 19) + snprintf(b, 4, \"x\", 23); }\n")
        other_helper.write_text(
            "#include <stdarg.h>\nstruct FILE { int unused; }; "
            "int fprintf(struct FILE* stream, const char* format, ...) { va_list ap; "
            "va_start(ap, format); int v = va_arg(ap, int); va_end(ap); return v; } "
            "int snprintf(char* b, unsigned long size, const char* format, ...) { va_list ap; "
            "va_start(ap, format); int v = va_arg(ap, int); va_end(ap); return v; }\n")
        other_objects = [td / "other-main.o", td / "other-helper.o"]
        for source, obj in zip((other_main, other_helper), other_objects):
            command([DRIVER, "-c", source, "-o", obj])
        other_archive = td / "other.a"
        command([DRIVER, "--archive", other_objects[1], "-o", other_archive])
        for mode in ("--static", "--dynamic"):
            for helper_input in (other_objects[1], other_archive):
                command([DRIVER, mode, other_objects[0], helper_input, "-o", td / "other"])
                expect(command([td / "other"], check=False).returncode == 42,
                       f"fprintf/snprintf override failed ({mode}, {helper_input})")

        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1":
            return
        c_source, c_obj = td / "ordinary.c", td / "ordinary.o"
        c_source.write_text(
            "extern int printf(const char *, ...);\n"
            "extern int fprintf(void *, const char *, ...);\n"
            "extern int snprintf(char *, unsigned long, const char *, ...);\n"
            "extern void *_crunch_stdout;\n"
            "int ordinary(void) {\n"
            "  char buf[64]; const char *want = \"1 2 3 4 5 6 7 3.500000\"; int i;\n"
            "  int n = snprintf(buf, sizeof buf, \"%d %d %d %d %d %d %d %f\","
            " 1, 2, 3, 4, 5, 6, 7, 3.5);\n"
            "  for (i = 0; want[i] && buf[i] == want[i]; ++i) {}\n"
            "  if (want[i] || buf[i] || n != i) return 1;\n"
            "  if (printf(\"%d:%f|\", 7, 3.5) != 11) return 2;\n"
            "  if (fprintf(_crunch_stdout, \"%s|\", \"ok\") != 3) return 3;\n"
            "  return 42;\n"
            "}\n")
        command(["cc", "-std=c11", "-fno-builtin", "-fPIC", "-fno-asynchronous-unwind-tables",
                 "-fno-stack-protector", "-c", c_source, "-o", c_obj])
        caller = td / "ordinary.bc"
        caller.write_text("int ordinary(void); int main() { return ordinary(); }\n")
        for mode in ("--static", "--dynamic"):
            exe = td / "ordinary"
            command([DRIVER, mode, caller, c_obj, "-o", exe])
            result = command([exe], check=False)
            expect(result.returncode == 42 and result.stdout == "7:3.500000|ok|",
                   f"ordinary formatted fallback failed ({mode}): "
                   f"{result.returncode} {result.stdout!r} {result.stderr!r}")


def runtime_signature_metadata_case():
    """Verify fallback argument classes against the public runtime headers.

    Returns:
        None; raises AssertionError for missing or inconsistent metadata.
    """
    header = (ROOT / "include/common/runtime_routines.h").read_text()
    entries = re.findall(r'X\("([A-Za-z_][A-Za-z_0-9]*)",\s*[0-9]+,\s*\'.\',\s*"([ip]*)"\)', header)
    expected = dict(entries)
    expect(len(entries) == len(expected) and expected, "invalid runtime signature metadata")
    seen = {}
    headers = sorted((ROOT / "include").glob("*.h")) + sorted((ROOT / "include/sys").glob("*.h"))
    for path in headers:
        include = path.relative_to(ROOT / "include")
        expanded = command([PP, "-"], input=f"#include <{include}>\n").stdout
        tokens = command([LEXER, "-"], input=expanded).stdout
        tree = json.loads(command([PARSER], input=tokens).stdout)
        for declaration in tree["declarations"]:
            name = declaration.get("name")
            if declaration.get("kind") != "function" or name not in expected:
                continue
            classes = "".join("p" if parameter["type"]["kind"] in ("pointer", "array", "function")
                              else "i" for parameter in declaration["parameters"])
            expect(classes == expected[name],
                   f"runtime argument classes for {name} disagree with {include}")
            seen[name] = classes
    expect(seen.keys() == expected.keys(),
           f"runtime functions missing public prototypes: {sorted(expected.keys() - seen.keys())}")


def matching_runtime_declaration_case():
    """Execute fixed-ABI runtime-name overrides and fallback calls.

    Returns:
        None; raises AssertionError on a compile, link, or execution failure.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-runtime-override-") as directory:
        td = pathlib.Path(directory)
        main, helper, fallback = td / "main.bc", td / "helper.bc", td / "fallback.bc"
        main.write_text(
            "int getpid(void); int strcmp(const char* x, const char* y); void exit(int status); "
            'int main() { exit(7); if (strcmp("a", "a") != 17) return 1; '
            'if (compare("x", "x", 1) != 0) return 2; return getpid(); }\n')
        helper.write_text(
            "int getpid(void) { return 42; } "
            "int strcmp(const char* x, const char* y) { return 17; } "
            "void exit(int status) { return; }\n")
        fallback.write_text(
            "int getpid(void); int strcmp(const char* x, const char* y); "
            'int main() { if (getpid() <= 0 || strcmp("a", "a") != 0) return 1; return 42; }\n')
        objects = [td / "main.o", td / "helper.o", td / "fallback.o"]
        for source, obj in zip((main, helper, fallback), objects):
            command([DRIVER, "-c", source, "-o", obj])
        archive, combined = td / "helper.a", td / "combined.o"
        command([DRIVER, "--archive", objects[1], "-o", archive])
        command([DRIVER, "-c", *objects[:2], "-o", combined])
        for mode in ("--static", "--dynamic"):
            for inputs in (objects[:2], [objects[0], archive], [combined], [objects[2]]):
                exe = td / "program"
                command([DRIVER, mode, *inputs, "-o", exe])
                result = command([exe], check=False)
                expect(result.returncode == 42 and not result.stdout,
                       f"runtime override failed ({mode}, {inputs}): "
                       f"{result.returncode} {result.stdout!r} {result.stderr!r}")

        noreturn = td / "noreturn.bc"
        noreturn.write_text(
            "#include <stdlib.h>\n"
            "int main(int argc, char **argv) { "
            "for (int i = 0; i < argc; i++) { if (argc > 10) exit(0); } return 42; }\n")
        command([DRIVER, "--static", noreturn, "-o", td / "noreturn"])
        expect(command([td / "noreturn"], check=False).returncode == 42,
               "ordinary calls to a noreturn declaration broke loop stack validation")


def incompatible_runtime_declaration_case():
    """Execute user functions whose signatures cannot use the runtime ABI.

    Returns:
        None; raises AssertionError on a compile, link, or execution failure.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-runtime-names-") as directory:
        td = pathlib.Path(directory)
        main, helper = td / "main.bc", td / "helper.bc"
        main.write_text(
            "double getpid(void); int fork(double x); int printf(int x); int exit(int x); "
            "int fprintf(int x, const char* text); int snprintf(int x, int n, const char* text); "
            "typedef int (*callback)(int); "
            "int main() { callback f = printf; "
            "if (getpid() != 42.0 || fork(21.0) != 42) return 1; "
            'if (exit(7) != 7 || fprintf(7, "x") != 7 || snprintf(7, 0, "x") != 7) return 2; '
            'if (compare("x", "x", 1) != 0) return 3; return f(42); }\n')
        helper.write_text(
            "double getpid(void) { return 42.0; } int fork(double x) { return x * 2.0; } "
            "int printf(int x) { return x; } int exit(int x) { return x; } "
            "int fprintf(int x, const char* text) { return x; } "
            "int snprintf(int x, int n, const char* text) { return x; }\n")
        objects = [td / "main.o", td / "helper.o"]
        for source, obj in zip((main, helper), objects):
            command([DRIVER, "-c", source, "-o", obj])
        archive, combined = td / "helper.a", td / "combined.o"
        command([DRIVER, "--archive", objects[1], "-o", archive])
        command([DRIVER, "-c", *objects, "-o", combined])
        for mode in ("--static", "--dynamic"):
            for inputs in (objects, [objects[0], archive], [combined]):
                exe = td / "program"
                command([DRIVER, mode, *inputs, "-o", exe])
                result = command([exe], check=False)
                expect(result.returncode == 42 and not result.stdout,
                       f"incompatible runtime names failed ({mode}, {inputs}): "
                       f"{result.returncode} {result.stdout!r}")

        missing = td / "missing.bc"
        missing.write_text("int printf(int value); int main() { return printf(42); }\n")
        missing_obj = td / "missing.o"
        command([DRIVER, "-c", missing, "-o", missing_obj])
        for flags in (["--static"], ["--dynamic"], ["--dynamic", "-pie"]):
            result = command([DRIVER, *flags, missing_obj, "-o", td / "missing"],
                             check=False)
            expect(result.returncode != 0 and "__crunch_guard_printf" in result.stderr,
                   f"incompatible printf unexpectedly bound the fallback ({flags}): {result.stderr}")

        for name, declaration, call in (
                ("strcmp", "int strcmp(int a, int b);", "strcmp(1, 2)"),
                ("getpid", "double getpid(void);", "(int)getpid()")):
            missing.write_text(f"{declaration} int main() {{ return {call}; }}\n")
            command([DRIVER, "-c", missing, "-o", td / "invalid.o"])
            result = command([DRIVER, "--static", td / "invalid.o", "-o", td / "invalid"],
                             check=False)
            expect(result.returncode != 0 and f"__crunch_guard_{name}" in result.stderr,
                   f"incompatible {name} unexpectedly bound the runtime fallback")
        missing.write_text("int printf(int value); typedef int (*callback)(int); "
                           "callback f = printf; int main() { return f(42); }\n")
        command([DRIVER, "-c", missing, "-o", td / "indirect.o"])
        result = command([DRIVER, "--static", td / "indirect.o", "-o", td / "indirect"],
                         check=False)
        expect(result.returncode != 0 and "__crunch_guard_printf" in result.stderr,
               "incompatible function pointer unexpectedly bound the runtime fallback")

        second = td / "second.bc"
        second.write_text("int printf(int value); int call_again() { return printf(42); }\n")
        second_obj, partial = td / "second.o", td / "guards.o"
        command([DRIVER, "-c", second, "-o", second_obj])
        command([DRIVER, "-c", missing_obj, second_obj, "-o", partial])
        printf_impl = td / "printf.bc"
        printf_impl.write_text("int printf(int value) { return value; }\n")
        printf_obj = td / "printf.o"
        command([DRIVER, "-c", printf_impl, "-o", printf_obj])
        for inputs in ([missing_obj, second_obj, printf_obj], [partial, printf_obj]):
            command([DRIVER, "--static", *inputs, "-o", td / "guarded"])
            expect(command([td / "guarded"], check=False).returncode == 42,
                   "compatible user definition failed with repeated runtime guards")
        result = command([DRIVER, "--static", partial, "-o", td / "guarded"], check=False)
        expect(result.returncode != 0 and "__crunch_guard_printf" in result.stderr,
               "partial linking lost the incompatible runtime guard")
        printf_shared = td / "printf.so"
        command([BUILD / "crunch-ld", "-nostdlib", "-shared", "-o", printf_shared, printf_obj])
        command([DRIVER, "--dynamic", "--rpath", td, missing_obj, printf_shared,
                 "-o", td / "guarded"])
        expect(command([td / "guarded"], check=False).returncode == 42,
               "shared user definition was blocked by a runtime guard")

        legacy = command([IR, "-"], input="int printf(int x); int main(){return printf(1);}\n",
                         check=False)
        expect(legacy.returncode != 0 and "module mode" in legacy.stderr,
               "executable IR silently bound a user signature to the runtime")


def abi_metadata_case():
    """Check versioned function metadata through object and shared links.

    Returns:
        None; raises AssertionError for missing or incorrect ABI records.
    """
    def records(path, require_retain=False):
        """Read ABI records from all matching ELF sections.

        Args:
            path: ELF file to inspect.
            require_retain: Whether each ABI section must retain its ELF flag.
        Returns:
            A list of metadata records.
        """
        image = path.read_bytes()
        shoff = struct.unpack_from("<Q", image, 40)[0]
        entsize, count, string_index = struct.unpack_from("<HHH", image, 58)
        headers = [struct.unpack_from("<IIQQQQIIQQ", image, shoff + i * entsize)
                   for i in range(count)]
        strings = image[headers[string_index][4]:headers[string_index][4] + headers[string_index][5]]
        result = []
        for header in headers:
            start = header[0]
            name = strings[start:strings.index(b"\0", start)]
            if name == b"__crunch_abi":
                expect(header[1] == 1 and header[2] & ~0x200000 == 2,
                       "invalid ABI metadata section flags")
                expect(not require_retain or header[2] & 0x200000,
                       f"ABI metadata section lost its retain flag: {path}")
                result.extend(image[header[4]:header[4] + header[5]].decode("ascii").splitlines())
        return result

    with tempfile.TemporaryDirectory(prefix="crunch-abi-metadata-") as directory:
        td = pathlib.Path(directory)
        source, obj = td / "module.bc", td / "module.o"
        source.write_text(
            "#include <stdarg.h>\nint external(int x); static int private(int x) { return x; } "
            "double compute(int x, double y) { return external(private(x)) + y; } "
            "int variadic(int x, ...) { va_list ap; va_start(ap, x); "
            "int v = va_arg(ap, int); va_end(ap); return v; }\n")
        command([DRIVER, "-c", source, "-o", obj])
        expected = {"CABI1 D compute unknown real int real", "CABI1 R external unknown int int",
                    "CABI1 D variadic variadic int int"}
        expect(set(records(obj, require_retain=True)) == expected,
               f"incorrect object ABI records: {records(obj)}")
        no_frame, no_frame_obj = td / "no-frame.bc", td / "no-frame.o"
        no_frame.write_text("int external_variadic(int x, ...); "
                            "int no_frame(int x, ...) { return external_variadic(x, 1); }\n")
        command([DRIVER, "-c", no_frame, "-o", no_frame_obj])
        expect(set(records(no_frame_obj)) ==
               {"CABI1 D no_frame variadic int int", "CABI1 R external_variadic variadic int int"},
               "metadata lost a variadic declaration or a definition without a frame")
        legacy = td / "legacy.bir"
        legacy.write_text("CRUNCH-IR 25\nextern_func old 1 int int\n"
                          "func f 1 int\nparam 0 0 int\nload 0\nret int\nend\n")
        legacy_obj = td / "legacy.o"
        legacy_asm = td / "legacy.s"
        legacy_asm.write_text(command([ASM, legacy]).stdout)
        command([DRIVER, "-c", legacy_asm, "-o", legacy_obj])
        expect(set(records(legacy_obj)) ==
               {"CABI1 R old unknown int int", "CABI1 D f unknown int int"},
               "legacy IR falsely asserted variadicity")
        for text in (
            "abi_variadic missing\n",
            "abi_variadic f\nabi_variadic f\nextern_func f 1 int int\n",
            "abi_variadic f extra\nextern_func f 1 int int\n",
            "abi_variadic f\nextern_func f 0 int\n",
            "func f 1 int\nparam 0 0 int\nvariadic\npush 0\nret int\nend\n",
        ):
            result = command([ASM, "--validate", "-"], input="CRUNCH-IR 41\n" + text,
                             check=False)
            expect(result.returncode != 0, "invalid ABI variadic annotation was accepted")
        result = command([ASM, "--validate", "-"],
                         input="CRUNCH-IR 39\nabi_variadic f\nextern_func f 1 int int\n",
                         check=False)
        expect(result.returncode != 0, "older IR accepted a v41 ABI annotation")
        guarded, guarded_obj = td / "guarded.bc", td / "guarded.o"
        guarded.write_text("int printf(int value); int guarded() { return printf(1); }\n")
        command([DRIVER, "-c", guarded, "-o", guarded_obj])
        expect("CABI1 G printf" in records(guarded_obj),
               "runtime ABI guard was not recorded in object metadata")
        linkers = ((NATIVE_LINK,) if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1"
                   else (["ld"], NATIVE_LINK))
        for linker in linkers:
            partial, shared = td / "partial.o", td / "module.so"
            command([*linker, "-r", "-o", partial, obj])
            expect(set(records(partial, require_retain=True)) == expected,
                   f"partial link lost ABI metadata ({linker})")
            command([*linker, "-shared", "-s", "-o", shared, partial])
            expect(set(records(shared)) == expected, f"stripped shared link lost ABI metadata ({linker})")
            command([*linker, "-shared", "-s", "-o", shared, guarded_obj])
            expect("CABI1 G printf" in records(shared),
                   f"stripped shared link lost guard metadata ({linker})")
            command([*linker, "-r", "-o", partial, guarded_obj])
            expect("CABI1 G printf" in records(partial, require_retain=True),
                   f"partial link lost ABI guard metadata ({linker})")
            if linker != NATIVE_LINK:
                command([*linker, "-shared", "-s", "--gc-sections", "-o", shared, partial])
                expect("CABI1 G printf" in records(shared),
                       f"garbage collection discarded partial-link guard metadata ({linker})")
            gc_main, gc_user = td / "gc-main.bc", td / "gc-user.bc"
            gc_main.write_text("int printf(int value); int main() { return printf(42); }\n")
            gc_user.write_text("int printf(int value) { return value; }\n")
            gc_main_obj, gc_user_obj = td / "gc-main.o", td / "gc-user.o"
            command([DRIVER, "-c", gc_main, "-o", gc_main_obj])
            command([DRIVER, "-c", gc_user, "-o", gc_user_obj])
            command([*linker, "-r", "-o", partial, gc_main_obj])
            expect("CABI1 G printf" in records(partial, require_retain=True),
                   f"partial link lost executable guard metadata ({linker})")
            exe = td / "gc-program"
            command([*linker, "--gc-sections", "-o", exe, partial, gc_user_obj])
            expect("CABI1 G printf" in records(exe),
                   f"garbage collection discarded ABI guard metadata ({linker})")
            expect(command([exe], check=False).returncode == 42,
                   f"garbage collection changed guarded program behavior ({linker})")


def abi_mismatch_warning_case():
    """Check optional ABI warnings for objects, archives, and direct shared inputs.

    Returns:
        None; raises AssertionError for incorrect warning or link behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-abi-warning-") as directory:
        td = pathlib.Path(directory)
        config = td / "crunch.conf"
        config.write_text("linker = crunch\n" +
                          ("assembler = crunch\n" if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1"
                           else ""))
        env = dict(os.environ, CRUNCH_CONF_FILE=str(config))
        caller, wrong, right = td / "caller.bc", td / "wrong.bc", td / "right.bc"
        caller.write_text("int target(int x); int main(void) { return target(42); }\n")
        wrong.write_text("int target(double x) { return 42; }\n")
        right.write_text("int target(int x) { return x; }\n")
        objects = []
        for source in (caller, wrong, right):
            obj = source.with_suffix(".o")
            command([DRIVER, "-c", source, "-o", obj], env=env)
            objects.append(obj)
        caller_obj, wrong_obj, right_obj = objects
        out = td / "linked.o"
        quiet = command([*NATIVE_LINK, "-r", "-o", out, caller_obj, wrong_obj])
        expect("possible ABI mismatch" not in quiet.stderr, "ABI warning was enabled by default")
        mismatch = command([*NATIVE_LINK, "-Wabi-mismatch", "-r", "-o", out,
                            caller_obj, wrong_obj])
        expect("possible ABI mismatch for `target'" in mismatch.stderr and
               str(caller_obj) in mismatch.stderr and str(wrong_obj) in mismatch.stderr,
               f"missing ABI mismatch warning: {mismatch.stderr}")
        wall_link = command([*NATIVE_LINK, "-Wall", "-r", "-o", out, caller_obj, wrong_obj])
        expect("possible ABI mismatch for `target'" in wall_link.stderr,
               "linker -Wall did not enable ABI warnings")
        partial = td / "partial.o"
        command([*NATIVE_LINK, "-r", "-o", partial, caller_obj, wrong_obj])
        retained = command([*NATIVE_LINK, "-Wabi-mismatch", "-r", "-o", out, partial])
        expect("possible ABI mismatch for `target'" in retained.stderr,
               "partial-link ABI records were not compared")
        same = command([DRIVER, "-Wabi-mismatch", "--static", caller_obj, right_obj,
                        "-o", td / "program"], env=env)
        expect("possible ABI mismatch" not in same.stderr, f"matching signatures warned: {same.stderr}")
        expect(command([td / "program"], check=False).returncode == 42,
               "warning option changed executable behavior")
        archive = td / "wrong.a"
        command([DRIVER, "--archive", wrong_obj, "-o", archive], env=env)
        selected = command([DRIVER, "-Wabi-mismatch", "-c", caller_obj, archive,
                            "-o", out], env=env)
        expect("possible ABI mismatch for `target'" in selected.stderr and
               "wrong.a(wrong.o)" in selected.stderr, "selected archive member was not checked")
        unused = command([DRIVER, "-Wabi-mismatch", "-c", right_obj, archive,
                          "-o", out], env=env)
        expect("possible ABI mismatch" not in unused.stderr, "unselected archive member warned")
        legacy = td / "legacy.s"
        legacy.write_text(".text\n.globl target\ntarget:\n mov $42, %eax\n ret\n")
        legacy_obj = td / "legacy.o"
        command([DRIVER, "-c", legacy, "-o", legacy_obj], env=env)
        unchecked = command([*NATIVE_LINK, "-Wabi-mismatch", "-r", "-o", out,
                             caller_obj, legacy_obj])
        expect("possible ABI mismatch" not in unchecked.stderr,
               "unrecorded assembly was incorrectly reported as a mismatch")
        dynamic = command([DRIVER, "-Wabi-mismatch", caller, wrong,
                           "-o", td / "dynamic"], env=env)
        expect("possible ABI mismatch for `target'" in dynamic.stderr,
               "dynamic driver link did not enable ABI warnings")
        warning_source = td / "warning.bc"
        warning_source.write_text("int target(int x); int main(void) { int unused = 1; return target(42); }\n")
        all_warnings = command([DRIVER, "-Wall", warning_source, wrong, "-o", td / "all-warnings"],
                               env=env)
        expect("unused variable 'unused'" in all_warnings.stderr and
               "possible ABI mismatch for `target'" in all_warnings.stderr,
               f"-Wall did not enable both warnings: {all_warnings.stderr}")
        shared_ref = td / "shared-ref.bc"
        shared_ref.write_text("int target(double x); int use_shared(void) { return target(1.0); }\n")
        shared_ref_obj = td / "shared-ref.o"
        command([DRIVER, "-c", shared_ref, "-o", shared_ref_obj], env=env)
        main = td / "main.bc"
        main.write_text("int main(void) { return 0; }\n")
        main_obj = td / "main.o"
        command([DRIVER, "-c", main, "-o", main_obj], env=env)
        hidden_assembly = td / "hidden.s"
        hidden_ir = command([IR, "--module", wrong]).stdout
        hidden_assembly.write_text(command([ASM], input=hidden_ir).stdout + "\n.hidden target\n")
        hidden_obj = td / "hidden.o"
        command([TEST_AS, "-o", hidden_obj, hidden_assembly])
        protected_assembly = td / "protected.s"
        protected_ir = command([IR, "--module", right]).stdout
        protected_assembly.write_text(command([ASM], input=protected_ir).stdout + "\n.protected target\n")
        protected_obj = td / "protected.o"
        command([TEST_AS, "-o", protected_obj, protected_assembly])
        linkers = ((NATIVE_LINK,) if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1"
                   else (["ld"], NATIVE_LINK))
        for index, linker in enumerate(linkers):
            wrong_so, right_so, ref_so, hidden_so = (td / f"{name}-{index}.so"
                                                      for name in ("wrong", "right", "ref", "hidden"))
            for obj, shared in ((wrong_obj, wrong_so), (right_obj, right_so),
                                (shared_ref_obj, ref_so), (hidden_obj, hidden_so)):
                command([*linker, "-shared", "-s", "-o", shared, obj])
            silent = command([DRIVER, caller_obj, wrong_so, "-o", td / "shared-quiet"], env=env)
            expect("possible ABI mismatch" not in silent.stderr,
                   "shared ABI warning was enabled by default")
            mismatch = command([DRIVER, "-Wabi-mismatch", caller_obj, wrong_so,
                                "-o", td / "shared-wrong"], env=env)
            expect("possible ABI mismatch for `target'" in mismatch.stderr and
                   str(wrong_so) in mismatch.stderr, f"shared definition not checked: {mismatch.stderr}")
            searched = command([DRIVER, "-Wabi-mismatch", caller_obj, "-L", td,
                                f"-l:{wrong_so.name}", "-o", td / "shared-searched"], env=env)
            expect("possible ABI mismatch for `target'" in searched.stderr and
                   str(wrong_so) in searched.stderr, "searched shared definition not checked")
            match = command([DRIVER, "-Wabi-mismatch", caller_obj, right_so,
                             "-o", td / "shared-right"], env=env)
            expect("possible ABI mismatch" not in match.stderr, f"matching shared ABI warned: {match.stderr}")
            expect(command([td / "shared-right"], check=False).returncode == 42,
                   "shared ABI warning changed executable behavior")
            hidden = command([DRIVER, "-Wabi-mismatch", caller_obj, hidden_so, right_so,
                              "-o", td / "shared-hidden"], env=env)
            expect("possible ABI mismatch" not in hidden.stderr,
                   f"hidden shared definition was treated as exported: {hidden.stderr}")
            candidates = command([DRIVER, "-Wabi-mismatch", caller_obj, right_so, wrong_so,
                                  "-o", td / "shared-candidates"], env=env)
            expect("possible ABI mismatch for `target'" in candidates.stderr and
                   str(wrong_so) in candidates.stderr,
                   f"mismatching shared candidate was not checked: {candidates.stderr}")
            overridden = command([DRIVER, "-Wabi-mismatch", caller_obj, right_obj, wrong_so,
                                  "-o", td / "shared-overridden"], env=env)
            expect("possible ABI mismatch" not in overridden.stderr,
                   f"preempted shared definition produced a warning: {overridden.stderr}")
            protected = command([DRIVER, "-Wabi-mismatch", caller_obj, protected_obj, wrong_so,
                                 "-o", td / "shared-protected"], env=env)
            expect("possible ABI mismatch" not in protected.stderr,
                   f"preempted shared definition warned for protected executable symbol: {protected.stderr}")
            from_shared = command([DRIVER, "-Wabi-mismatch", main_obj, right_obj, ref_so,
                                   "-o", td / "shared-reference"], env=env)
            expect("possible ABI mismatch for `target'" in from_shared.stderr and
                   str(ref_so) in from_shared.stderr and str(right_obj) in from_shared.stderr,
                   f"shared declaration not checked: {from_shared.stderr}")
            between_shared = command([DRIVER, "-Wabi-mismatch", main_obj, ref_so, right_so,
                                      "-o", td / "shared-pair"], env=env)
            expect("possible ABI mismatch for `target'" in between_shared.stderr and
                   str(ref_so) in between_shared.stderr and str(right_so) in between_shared.stderr,
                   f"shared-to-shared mismatch not checked: {between_shared.stderr}")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            gnu_config = td / "gnu.conf"
            gnu_config.write_text("linker = gnu\n")
            for flag in ("-Wabi-mismatch", "-Wall"):
                skipped = command([DRIVER, flag, "-c", caller_obj, "-o", out],
                                  env=dict(env, CRUNCH_CONF_FILE=str(gnu_config)))
                expect("warning:" in skipped.stderr and "--enable-native-only" in skipped.stderr and
                       "linker = crunch" in skipped.stderr and "Option discarded." in skipped.stderr,
                       f"unsupported GNU linker silently ignored {flag}: {skipped.stderr}")
            gnu_wall = command([DRIVER, "-Wall", "-c", warning_source, "-o", out],
                               env=dict(env, CRUNCH_CONF_FILE=str(gnu_config)))
            expect("unused variable 'unused'" in gnu_wall.stderr and
                   "Option discarded." in gnu_wall.stderr,
                   f"-Wall lost frontend warnings with GNU ld: {gnu_wall.stderr}")
        command([DRIVER, "-Wall", "--archive", wrong_obj, "-o", archive], env=env)
        old = command([DRIVER, "--warn-abi-mismatch", "-c", caller_obj, "-o", out],
                      env=env, check=False)
        expect(old.returncode != 0 and "unknown option" in old.stderr,
               "replaced ABI option was unexpectedly accepted")


def shared_runtime_link_guard_case():
    """Check ABI guards for shared inputs known to the native linker.

    Returns:
        None; raises AssertionError for incorrect rejection or user override behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-shared-runtime-guard-") as directory:
        td = pathlib.Path(directory)
        guarded, main, user = td / "guarded.bc", td / "main.bc", td / "user.bc"
        guarded.write_text(
            "int printf(int value); typedef int (*callback)(int); "
            "static callback f = printf; int guarded() { return f(42); }\n")
        main.write_text(
            'int printf(const char *format); int guarded(); '
            'int main(int argc, char **argv) { printf("started"); '
            'return argc == 12345 ? guarded() : 42; }\n')
        user.write_text("int printf(int value) { return value; }\n")
        guarded_obj, main_obj, user_obj = td / "guarded.o", td / "main.o", td / "user.o"
        for source, obj in ((guarded, guarded_obj), (main, main_obj), (user, user_obj)):
            command([DRIVER, "-c", source, "-o", obj])
        repeat = td / "repeat.bc"
        repeat.write_text("int printf(int value); int again() { return printf(1); }\n")
        repeat_obj = td / "repeat.o"
        command([DRIVER, "-c", repeat, "-o", repeat_obj])
        user_main = td / "user-main.bc"
        user_main.write_text(
            "int guarded(); int printf(int value); "
            "int main(int argc, char **argv) { return argc == 12345 ? printf(42) : guarded(); }\n")
        user_main_obj = td / "user-main.o"
        command([DRIVER, "-c", user_main, "-o", user_main_obj])
        plain_main = td / "plain-main.bc"
        plain_main.write_text("int guarded(); int main() { return guarded(); }\n")
        plain_obj = td / "plain-main.o"
        command([DRIVER, "-c", plain_main, "-o", plain_obj])
        archive, partial = td / "user.a", td / "user-partial.o"
        command([DRIVER, "--archive", user_obj, "-o", archive])
        command([DRIVER, "-c", user_main_obj, user_obj, "-o", partial])
        user_shared = td / "user.so"
        command([BUILD / "crunch-ld", "-nostdlib", "-shared", "-o", user_shared, user_obj])
        command([BUILD / "crunch-ar", "x", BUILD / "libcrunch-fallback.a",
                 "fallback_printf.o"], cwd=td)
        fallback_obj = td / "fallback_printf.o"

        lazy = td / "lazy.bc"
        lazy.write_text("int dirent64_next(int x); int use_it() { return dirent64_next(1); }\n")
        lazy_obj = td / "lazy.o"
        command([DRIVER, "-c", lazy, "-o", lazy_obj])
        linkers = ((NATIVE_LINK,) if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1"
                   else (["ld"], NATIVE_LINK))
        for linker in linkers:
            shared, lazy_shared = td / "guarded.so", td / "lazy.so"
            command([*linker, "-shared", "-o", lazy_shared, lazy_obj])
            if linker == ["ld"]:
                command([PYTHON, "-c",
                         "import ctypes,os,sys; ctypes.CDLL(sys.argv[1],mode=os.RTLD_LAZY)",
                         lazy_shared])
            for inputs in ([guarded_obj], [guarded_obj, repeat_obj]):
                combined = td / "guarded-partial.o"
                if len(inputs) > 1:
                    command([*linker, "-r", "-o", combined, *inputs])
                    inputs = [combined]
                command([*linker, "-shared", "-o", shared, *inputs])
                for pie in ([], ["-pie"]):
                    exe = td / "program"
                    exe.write_text("unchanged")
                    result = command([DRIVER, "--dynamic", *pie, "--rpath", td,
                                      main_obj, shared, "-o", exe], check=False)
                    expect(result.returncode != 0 and "incompatible runtime fallback" in result.stderr
                           and "printf" in result.stderr and exe.read_text() == "unchanged",
                           f"native linker accepted an incompatible shared fallback: {result.stderr!r}")
                    for definitions in ([user_main_obj, user_obj], [user_main_obj, archive], [partial],
                                        [plain_obj, user_shared]):
                        command([DRIVER, "--dynamic", *pie, "--rpath", td, *definitions, shared,
                                 "-o", exe])
                        result = command([exe], check=False)
                        expect(result.returncode == 42 and not result.stderr,
                               f"shared guard rejected a user definition ({linker}, {definitions}): "
                               f"{result.returncode} {result.stderr!r}")
                command([DRIVER, "--dynamic", "--rpath", td, plain_obj, user_obj,
                         fallback_obj, shared, "-o", td / "user-fallback"])
                result = command([td / "user-fallback"], check=False)
                expect(result.returncode == 42 and not result.stderr,
                       f"shared guard rejected a selected user override: {result.stderr!r}")
            self_shared = td / "self.so"
            command([*linker, "-shared", "-o", self_shared, guarded_obj, user_obj])
            result = command([DRIVER, "--dynamic", "--rpath", td, main_obj,
                              fallback_obj, self_shared,
                              "-o", td / "self"], check=False)
            expect(result.returncode != 0 and "incompatible runtime fallback" in result.stderr,
                   f"preemptible shared user definition was not guarded: {result.stderr!r}")
            if linker == ["ld"]:
                command(["ld", "-shared", "-Bsymbolic", "-o", self_shared, guarded_obj, user_obj])
                symbolic_main = td / "symbolic.bc"
                symbolic_main.write_text(
                    'int printf(const char *format); int guarded(); '
                    'int main() { printf("ok"); return guarded(); }\n')
                symbolic_obj = td / "symbolic.o"
                command([DRIVER, "-c", symbolic_main, "-o", symbolic_obj])
                command([DRIVER, "--dynamic", "--rpath", td, symbolic_obj,
                         fallback_obj, self_shared, "-o", td / "self"])
                result = command([td / "self"], check=False)
                expect(result.returncode == 42 and result.stdout == "ok" and not result.stderr,
                       f"symbolically bound shared user definition was rejected: {result.stderr!r}")
            compare_guard = td / "compare-guard.bc"
            compare_guard.write_text("int strcmp(int a, int b); int guarded() { return strcmp(1, 2); }\n")
            compare_main = td / "compare-main.bc"
            compare_main.write_text(
                'int strcmp(const char *a, const char *b); int guarded(); '
                'int main(int argc, char **argv) { '
                'return argc == 12345 ? guarded() : strcmp("x", "x"); }\n')
            compare_obj, compare_main_obj = td / "compare-guard.o", td / "compare-main.o"
            command([DRIVER, "-c", compare_guard, "-o", compare_obj])
            command([DRIVER, "-c", compare_main, "-o", compare_main_obj])
            command([*linker, "-shared", "-o", shared, compare_obj])
            result = command([DRIVER, "--dynamic", "--rpath", td, compare_main_obj, shared,
                              "-o", td / "compare"], check=False)
            expect(result.returncode != 0 and "incompatible runtime fallback" in result.stderr
                   and "strcmp" in result.stderr,
                   f"shared fixed-ABI fallback was not guarded: {result.stderr!r}")
            hidden = td / "hidden.o"
            command([TEST_AS, "-o", hidden, "-"],
                    input=".hidden __crunch_dso_guard_printf\n")
            command([*linker, "-shared", "-o", shared, guarded_obj, hidden])
            result = command([DRIVER, "--dynamic", "--rpath", td, main_obj, shared,
                              "-o", td / "hidden"], check=False)
            expect(result.returncode != 0 and "incompatible runtime fallback" in result.stderr,
                   f"hidden shared guard was not detected ({linker}): {result.stderr!r}")
            command([DRIVER, "--dynamic", "--rpath", td, plain_obj, user_obj, shared,
                     "-o", td / "hidden"])
            expect(command([td / "hidden"], check=False).returncode == 42,
                   f"hidden shared guard rejected a user definition ({linker})")
            command([*linker, "-shared", "-s", "-o", shared, guarded_obj, hidden])
            result = command([DRIVER, "--dynamic", "--rpath", td, main_obj, shared,
                              "-o", td / "hidden"], check=False)
            expect(result.returncode != 0 and "incompatible runtime fallback" in result.stderr,
                   f"stripped hidden shared guard was not detected ({linker}): {result.stderr!r}")
            command([DRIVER, "--dynamic", "--rpath", td, plain_obj, user_obj, shared,
                     "-o", td / "hidden"])
            expect(command([td / "hidden"], check=False).returncode == 42,
                   f"stripped hidden guard rejected a user definition ({linker})")
            if linker == ["ld"]:
                version_script = td / "exports.map"
                version_script.write_text("{ global: guarded; local: *; };\n")
                command(["ld", "-shared", "--version-script", version_script,
                         "-o", shared, guarded_obj])
                result = command([DRIVER, "--dynamic", "--rpath", td, main_obj, shared,
                                  "-o", td / "hidden"], check=False)
                expect(result.returncode != 0 and "incompatible runtime fallback" in result.stderr,
                       f"version-script-hidden shared guard was not detected: {result.stderr!r}")
                command(["ld", "-shared", "-s", "--version-script", version_script,
                         "-o", shared, guarded_obj])
                result = command([DRIVER, "--dynamic", "--rpath", td, main_obj, shared,
                                  "-o", td / "hidden"], check=False)
                expect(result.returncode != 0 and "incompatible runtime fallback" in result.stderr,
                       f"stripped version-script-hidden guard was not detected: {result.stderr!r}")


def separate_module_case():
    """Check typed external calls, module entry points, and runtime call distinction.

    Returns:
        None; raises AssertionError for incorrect translation, diagnostics, or execution.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-modules-") as directory:
        td = pathlib.Path(directory)
        params = ", ".join(f"double r{i}, int i{i}" for i in range(1, 10))
        arguments = ", ".join(["0.0, 0"] * 8 + ["40.0, 2"])
        main_source = (
            f"double mix({params}); extern int printf(int value); extern int exit(int value); "
            f"int main() {{ if (mix({arguments}) != 42.0) return 1; "
            'if (compare("X", "X", 1) != 0) return 2; exit(7); return printf(42); }\n'
        )
        helper_source = (f"double mix({params}) {{ return r9 + i9; }} "
                         "int printf(int value) { return value; } int exit(int value) { return value; }\n")
        objects = []
        for index, source in enumerate((main_source, helper_source)):
            lexed = command([LEXER, "-"], input=source).stdout
            tree = json.loads(command([PARSER], input=lexed).stdout)
            if index == 0:
                printf_decl = next(d for d in tree["declarations"] if d.get("name") == "printf")
                expect(printf_decl["extern"], "explicit extern was not preserved in the AST")
            ir = command([IR, "--module", "-"], input=source).stdout
            expect(ir.startswith(f"CRUNCH-IR {39 if index == 0 else 3}\n"),
                   "module IR has the wrong version")
            if index == 0:
                expect("extern_func printf 1 int int\n" in ir and
                       "call printf 1\n" in ir and "runtime_call memcmp 3\n" in ir,
                       f"external and runtime calls were not distinguished: {ir}")
            assembly = command([ASM, "-"], input=ir).stdout
            expect((".global _start\n" in assembly) == (index == 0),
                   "incorrect module entry-point emission")
            assembly_file, obj = td / f"unit{index}.s", td / f"unit{index}.o"
            assembly_file.write_text(assembly)
            command(["as", "-o", obj, assembly_file])
            objects.append(obj)
        combined = td / "combined.o"
        command([*TEST_LINK, "-r", "-o", combined, *objects])
        for inputs in (objects, [combined]):
            exe = td / "program"
            command([*TEST_LINK, "--require-defined=_start", "--require-defined=main",
                     "-o", exe, *inputs, LIBCRUNCH])
            result = command([exe], check=False)
            expect(result.returncode == 42 and result.stdout == "",
                   f"mixed-register external call failed: {result.returncode} {result.stdout!r}")

        for inputs in ([objects[0]], [objects[1]], [objects[0], objects[1], objects[1]]):
            result = command([*TEST_LINK, "--require-defined=_start", "--require-defined=main",
                              "-o", td / "invalid-program", *inputs, LIBCRUNCH], check=False)
            expect(result.returncode != 0,
                   f"linking missing or duplicate module definitions succeeded: {inputs}")

        source = 'int printf(const char* format); int main() { printf("ok%d", 1); return 42; }\n'
        ir = command([IR, "--module", "-"], input=source).stdout
        expect("runtime_call printf 3\n" in ir and "extern_func printf" in ir and
               "weak_fnaddr __crunch_fallback_printf\n" in ir,
               "standard printf did not emit runtime/user dispatch")
        runtime_asm = td / "runtime.s"
        runtime_asm.write_text(command([ASM, "-"], input=ir).stdout)
        runtime_obj, exe = td / "runtime.o", td / "runtime"
        command([TEST_AS, "-o", runtime_obj, runtime_asm])
        command([*TEST_LINK, "-o", exe, runtime_obj, LIBCRUNCH])
        result = command([exe], check=False)
        expect(result.returncode == 42 and result.stdout == "ok1",
               "runtime printf fallback failed")

        noreturn_sources = (
            "extern void noreturn stop(); int main() { stop(); }\n",
            "void noreturn exit(int status); void noreturn stop() { exit(42); }\n",
        )
        noreturn_objects = []
        for index, source in enumerate(noreturn_sources):
            ir = command([IR, "--module", "-"], input=source).stdout
            assembly = command([ASM, "-"], input=ir).stdout
            path, obj = td / f"noreturn{index}.s", td / f"noreturn{index}.o"
            path.write_text(assembly)
            command(["as", "-o", obj, path])
            noreturn_objects.append(obj)
        command([*TEST_LINK, "-o", exe, *noreturn_objects, LIBCRUNCH])
        expect(command([exe], check=False).returncode == 42,
               "external noreturn function did not terminate the program")

        for declarations in ("int printf(int x); extern int printf(int x);",
                             "extern int printf(int x); int printf(int x);"):
            ir = command([IR, "--module", "-"],
                         input=declarations + " int main() { return printf(42); }\n").stdout
            expect("extern_func printf 1 int int\n" in ir and "runtime_call printf" not in ir,
                   f"extern declaration order changed linkage: {ir}")

        for name in ("end", "exit"):
            source = td / f"user-{name}.bc"
            source.write_text(f"int {name}(int x) {{ return x; }} "
                              f"int main() {{ {name}(1); return 42; }}\n")
            command([DRIVER, source, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"user-defined {name} was treated as a noreturn runtime function")

        for source in (
            "static int absent(); int main() { return 0; }\n",
            "dim extern int value[2]; int main() { return 0; }\n",
            "int f(int value); extern double f(int value); int main() { return 0; }\n",
        ):
            result = command([IR, "--module", "-"], input=source, check=False)
            expect(result.returncode != 0 and result.stderr.strip() and not result.stdout,
                   f"invalid module source was accepted: {source}")
        source = td / "block-extern.bc"
        helper = td / "block-extern-helper.bc"
        source.write_text("int main() { extern int value(); return value(); }\n")
        helper.write_text("int value() { return 42; }\n")
        command([DRIVER, source, helper, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "block-scope external function declaration failed across modules")
        legacy = command([IR, "-"], input="extern int printf(int x); int main(){return printf(1);}\n",
                         check=False)
        expect(legacy.returncode != 0 and "module mode" in legacy.stderr,
               "executable mode silently bound an external runtime-name function to the runtime")
        for directive in (
            "extern_func f 1 int\n",
            "extern_func f 1 int void\n",
            "extern_func f 0 int extra\n",
            "extern_func f 1 int real\nextern_func f 1 int int\n",
            "extern_func f 0 int\ninternal f\n",
            "extern_func f 1 int real\nfunc f 1 int\nparam 0 0 int\npush 0\nret int\nend\n",
            "func f 1 int\npush 0\nret int\nend\n",
            "func f 2 int\nparam 0 0 int\nparam 1 0 int\npush 0\nret int\nend\n",
            "global f int 0\nextern_func f 0 int\n",
            "global __crunch_print int 0\n",
            "extern_func __crunch_printf 0 int\n",
            "stringlit __crunch_print 00\n",
            "func _start 0 int\npush 0\nret int\nend\n",
            "func __crunch_print 0 int\npush 0\nret int\nend\n",
            "extern_global value void\n",
        ):
            text = "CRUNCH-IR 3\n" + directive + "func main 0 int\npush 0\nret int\nend\n"
            result = command([ASM, "-"], input=text, check=False)
            expect(result.returncode != 0 and result.stderr.strip() and not result.stdout,
                   f"invalid module IR was accepted: {directive}")
        for instructions in ("call missing 0", "runtime_call missing 0", "call printf 1"):
            text = "CRUNCH-IR 3\nfunc main 0 int\npush 0\n" + instructions + "\nret int\nend\n"
            result = command([ASM, "-"], input=text, check=False)
            expect(result.returncode != 0 and result.stderr.strip() and not result.stdout,
                   f"undeclared module call was accepted: {instructions}")
        for body in ("func main 0 real\npushr 0x0\nret real\nend\n",
                     "func main 0 int\npush 0\nret int\ncall missing 0\nend\n"):
            result = command([ASM, "-"], input="CRUNCH-IR 3\n" + body, check=False)
            expect(result.returncode != 0 and result.stderr.strip() and not result.stdout,
                   f"invalid module body was accepted: {body}")

def module_function_sections_case():
    """Execute functions in modules containing initialized and uninitialized globals.

    Returns:
        None; raises AssertionError for incorrect function section placement or execution.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-module-sections-") as directory:
        td = pathlib.Path(directory)
        main, helper, obj, exe = (td / name for name in
                                  ("main.c", "helper.c", "helper.o", "program"))
        main.write_text("int run(); int main() { return run(); }\n")
        for source, output in (
                ('int printf(const char *format); static char text[] = "Hello!\\n"; '
                 'int run() { printf("%s", text); return 42; }\n', "Hello!\n"),
                ("static int value = 42; int run() { return value; }\n", ""),
                ("struct Box { int value; }; static struct Box box; "
                 "int run() { box.value = 42; return box.value; }\n", "")):
            helper.write_text(source)
            command([DRIVER, "-c", "-o", obj, helper])
            command([DRIVER, "-o", exe, main, obj])
            result = command([exe], check=False)
            expect(result.returncode == 42 and result.stdout == output,
                   f"module with globals failed: {result.returncode} {result.stdout!r}")

def project_case(name, sources, expected_stdout, input_text=None):
    """Build and execute a multi-file fixture through separate driver link paths.

    Args:
        name: Project fixture directory name.
        sources: Source filenames in link order.
        expected_stdout: Exact output expected from each executable.
        input_text: Text supplied to each executable's standard input, or None.
    Returns:
        None; raises AssertionError for a build or execution failure.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-project-") as directory:
        project = pathlib.Path(directory) / name
        shutil.copytree(FIXTURES / "projects" / name, project)
        env = {key: value for key, value in os.environ.items()
               if key not in ("MAKEFLAGS", "MFLAGS", "MAKELEVEL", "CRUNCH_INCLUDE_PATH",
                              "CRUNCH_CONF_FILE")}
        if test_linker == "crunch":
            env["CRUNCH_CONF_FILE"] = str(native_config)
        command(["make", f"CRUNCH={DRIVER}"], cwd=project, env=env)
        objects = [pathlib.Path(source).with_suffix(".o") for source in sources]
        command([DRIVER, "-I", "include", "-o", "direct", *sources], cwd=project, env=env)
        command([DRIVER, "-c", "-o", "combined.o", *reversed(objects)], cwd=project, env=env)
        command([DRIVER, "-o", "relocatable", "combined.o"], cwd=project, env=env)
        for executable in ("program", "direct", "relocatable"):
            result = command([project / executable], cwd=project, env=env, check=False,
                             input=input_text)
            expect(result.returncode == 0 and result.stdout == expected_stdout,
                   f"{name}/{executable}: exit {result.returncode}, "
                   f"stdout {result.stdout!r}, stderr {result.stderr!r}")

def linked_list_project_case():
    """Run the linked-list project and check allocation-failure cleanup.

    Returns:
        None; raises AssertionError for incorrect list, snapshot, or cleanup behavior.
    """
    project_case("linked_list", ["main.c", "list.c"], "")
    project = FIXTURES / "projects/linked_list"
    with tempfile.TemporaryDirectory(prefix="crunch-linked-list-") as directory:
        directory = pathlib.Path(directory)
        obj, exe = directory / "list.o", directory / "failure"
        command([DRIVER, "-c", "-I", project / "include", project / "list.c", "-o", obj])
        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Wpedantic", "-Werror",
                 "-no-pie", project / "failure.c", obj, LIBCRUNCH,
                 "-Wl,--wrap=__crunch_malloc,--wrap=__crunch_free,"
                 "--wrap=__crunch_alloc_bytes,--wrap=__crunch_free_bytes", "-o", exe])
        result = command([exe], check=False)
        expect(result.returncode == 0,
               f"linked-list allocation failure or cleanup failed: {result.returncode}")

def allocated_reader_project_case():
    """Run a growing file reader in three build modes and inject allocation failures.

    Returns:
        None; raises AssertionError for incorrect output, errors, or cleanup.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-allocated-reader-") as directory:
        project = pathlib.Path(directory) / "allocated_reader"
        shutil.copytree(FIXTURES / "projects/allocated_reader", project)
        env = {key: value for key, value in os.environ.items()
               if key not in ("MAKEFLAGS", "MFLAGS", "MAKELEVEL", "CRUNCH_INCLUDE_PATH",
                              "CRUNCH_CONF_FILE")}
        if test_linker == "crunch":
            env["CRUNCH_CONF_FILE"] = str(native_config)
        command(["make", f"CRUNCH={DRIVER}"], cwd=project, env=env)
        command([DRIVER, "-I", "include", "-o", "direct", "main.c", "reader.c"],
                cwd=project, env=env)
        command([DRIVER, "-c", "-o", "combined.o", "reader.o", "main.o"],
                cwd=project, env=env)
        command([DRIVER, "-o", "relocatable", "combined.o"], cwd=project, env=env)
        payloads = ("", "0123456789abcdef", "a\0b\n",
                    "0123456789abcdef" * 512 + "end\n")
        for executable in ("program", "direct", "relocatable"):
            for payload in payloads:
                (project / "data").write_text(payload)
                result = command([project / executable, "data"], cwd=project, env=env,
                                 check=False)
                expect(result.returncode == 0 and result.stdout == payload,
                       f"{executable}: length {len(payload)}, exit {result.returncode}, "
                       f"stdout length {len(result.stdout)}, stderr {result.stderr!r}")
            result = command([project / executable, "missing"], cwd=project, env=env,
                             check=False)
            expect(result.returncode == 2 and result.stdout == "",
                   f"{executable}: missing file returned {result.returncode}")

        command(["cc", "-std=c11", "-Wall", "-Wextra", "-Wpedantic", "-Werror",
                 "-no-pie", "failure.c", "reader.o", LIBCRUNCH,
                 "-Wl,--wrap=__crunch_malloc,--wrap=__crunch_realloc,"
                 "--wrap=__crunch_free,--wrap=__crunch_close", "-o", "failure"],
                cwd=project, env=env)
        command([project / "failure", "data", "."], cwd=project, env=env)

def invalid_project_case():
    """Check that multi-file projects reject missing, duplicate, and conflicting functions.

    Returns:
        None; raises AssertionError if the expected compilation or link error is missing.
    """
    project = FIXTURES / "projects" / "invalid"
    with tempfile.TemporaryDirectory(prefix="crunch-invalid-project-") as directory:
        directory = pathlib.Path(directory)
        output = directory / "program"
        flags = [DRIVER, "-I", project / "include", "-o", output]
        main_object = directory / "main.o"
        command([DRIVER, "-c", "-I", project / "include", "-o", main_object,
                 project / "main.c"])
        for sources, diagnostic in (
                ([main_object], "undefined reference"),
                ([project / "main.c", project / "first.c", project / "second.c"],
                 "multiple definition"),
                ([project / "conflict.c", project / "first.c"], "E_SEMANTIC")):
            result = command([*flags, *sources], check=False)
            expect(result.returncode != 0 and diagnostic in result.stderr,
                   f"invalid project {sources} not rejected as expected: {result.stderr}")

def dynamic_driver_case():
    """Check opt-in shared-runtime executable links through the compiler driver.

    Returns:
        None; raises AssertionError for incorrect driver or executable behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-driver-dynamic-") as directory:
        td = pathlib.Path(directory)
        conf, source, exe = td / "crunch.conf", td / "main.bc", td / "program"
        selected_linker = "crunch" if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1" else "gnu"
        conf.write_text(f"assembler = crunch\nlinker = {selected_linker}\n")
        env = {key: value for key, value in os.environ.items()
               if key not in ("LD_PRELOAD", "LD_LIBRARY_PATH", "LD_AUDIT")}
        env["CRUNCH_CONF_FILE"] = str(conf)
        source.write_text('#include <stdlib.h>\nint values[] = {40, 2};'
                          'int printf(const char* format); int main() { printf("dynamic;"); exit(values[0]+values[1]); return 0; }\n')

        def dynamic_metadata(path):
            """Read dependency names and RUNPATH from an ELF executable.

            Args:
                path: Linked executable path.
            Returns:
                Pair of dependency list and RUNPATH, or empty values for static output.
            """
            image = path.read_bytes()
            phoff, shoff = struct.unpack_from("<QQ", image, 32)
            phentsize, phnum, shentsize, shnum, _ = struct.unpack_from("<HHHHH", image, 54)
            headers = [struct.unpack_from("<IIQQQQQQ", image, phoff + i * phentsize)
                       for i in range(phnum)]
            dynamic = next((h for h in headers if h[0] == 2), None)
            if not dynamic:
                return [], None
            sh = [struct.unpack_from("<IIQQQQIIQQ", image, shoff + i * shentsize)
                  for i in range(shnum)]
            dyn = next(h for h in sh if h[1] == 6)
            strings = sh[dyn[6]]
            data = image[strings[4]:strings[4] + strings[5]]
            needed, runpath = [], None
            for pos in range(dynamic[2], dynamic[2] + dynamic[5], 16):
                tag, value = struct.unpack_from("<qQ", image, pos)
                if tag == 0:
                    break
                if tag in (1, 29):
                    text = data[value:data.index(b"\0", value)].decode()
                    if tag == 1:
                        needed.append(text)
                    else:
                        runpath = text
            return needed, runpath

        for flags in ([], ["--static"], ["--dynamic"], ["--dynamic", "-z", "relro"]):
            result = command([DRIVER, *flags, "-v", source, "-o", exe], env=env)
            run = command([exe], cwd=td, env=env, check=False)
            expect(run.returncode == 42 and run.stdout == "dynamic;",
                   f"driver executable failed for {flags}: {run.stderr}")
            needed, runpath = dynamic_metadata(exe)
            if "--static" not in flags:
                expect(needed == ["libcrunch.so.1"] and runpath == str(BUILD) and
                       str(BUILD / "crunch-ld") in result.stderr,
                       f"driver did not select its shared runtime: {needed}, {runpath}")
            else:
                expect(not needed and runpath is None, "static driver output gained dynamic dependencies")

        for assembler in (("crunch",) if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1"
                          else ("crunch", "gnu")):
            conf.write_text(f"assembler = {assembler}\nlinker = {selected_linker}\n")
            for fixture, args in (
                    ("units/expressions/power_runtime.bc", ()),
                    ("units/types/local_fixed_arrays.bc", ()),
                    ("units/types/global_fixed_arrays.bc", ()),
                    ("units/function_calls/argv_runtime.bc", ("xy",))):
                command([DRIVER, "--dynamic", "-z", "relro", FIXTURES / fixture,
                         "-o", exe], env=env)
                run = command([exe, *args], cwd=td, env=env, check=False)
                expect(run.returncode == 42,
                       f"{assembler} dynamic RELRO build failed for {fixture}: {run.stderr}")
        conf.write_text(f"assembler = crunch\nlinker = {selected_linker}\n")

        provider_obj, provider = td / "provider.o", td / "libdriverprobe.so.1"
        command([BUILD / "crunch-as", "-o", provider_obj], input=
                ".text\n.globl external_answer\n.type external_answer,@function\n"
                "external_answer: mov $42,%eax\nret\n"
                ".globl read_external\n.type read_external,@function\n"
                "read_external: mov external_data@GOTPCREL(%rip),%rax\nmov (%rax),%eax\nret\n"
                ".data\n.globl external_data\n.type external_data,@object\n"
                ".size external_data,4\nexternal_data: .long 40\n")
        command([BUILD / "crunch-ld", "-nostdlib", "-shared", "-soname", provider.name,
                 "-o", provider, provider_obj])
        assembly = td / "entry.s"
        assembly.write_text(".text\n.globl _start\n_start:\nand $-16,%rsp\n"
                            "call external_answer@PLT\nmov %eax,%edi\nmov $60,%eax\nsyscall\n")
        command([DRIVER, "--dynamic", assembly, provider, "-o", exe], env=env)
        run = command([exe], env=dict(env, LD_LIBRARY_PATH=str(td)), check=False)
        expect(run.returncode == 42 and provider.name in dynamic_metadata(exe)[0],
               f"driver failed to pass direct shared input: {run.stderr}")
        source.write_text("extern int external_answer(); int main() { return external_answer(); }\n")
        command([DRIVER, "--dynamic", source, provider, "-o", exe], env=env)
        run = command([exe], env=dict(env, LD_LIBRARY_PATH=str(td)), check=False)
        expect(run.returncode == 42, f"Crunch source could not call a shared dependency: {run.stderr}")
        source.write_text("extern int external_data; int read_external(); "
                          "int main() { int *p = &external_data; "
                          "external_data = external_data + 2; "
                          "if (*p != 42) return 1; return read_external(); }\n")
        for assembler in (("crunch",) if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1"
                          else ("crunch", "gnu")):
            conf.write_text(f"assembler = {assembler}\nlinker = {selected_linker}\n")
            command([DRIVER, "--dynamic", source, provider, "-o", exe], env=env)
            run = command([exe], env=dict(env, LD_LIBRARY_PATH=str(td)), check=False)
            expect(run.returncode == 42,
                   f"{assembler} dynamic external data access failed: {run.stderr}")
            obj = td / "external-data.o"
            command([DRIVER, "-c", source, "-o", obj], env=env)
            for flags, input_file in ((["--dynamic"], provider), (["--static"], provider_obj)):
                command([DRIVER, *flags, obj, input_file, "-o", exe], env=env)
                run = command([exe], env=dict(env, LD_LIBRARY_PATH=str(td)), check=False)
                expect(run.returncode == 42,
                       f"{assembler} external data object failed for {flags}: {run.stderr}")
            command([DRIVER, "--dynamic", FIXTURES / "units/expressions/character_escapes.bc",
                     "-o", exe], env=env)
            run = command([exe], env=env, check=False)
            expect(run.returncode == 0 and run.stdout == "\n",
                   f"{assembler} dynamic standard stream access failed: {run.stderr}")
            errno_source = td / "errno-accessor.bc"
            errno_source.write_text("#include <errno.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <sys/stat.h>\n#include <dirent.h>\n#include <stdio.h>\n"
                                    "int main() { int *p = __errno_location(); *p = 0; "
                                    "if (file_close(-1) != -1) return 1; "
                                    "if (*p != EBADF || p != __errno_location()) return 2; "
                                    "return 42; }\n")
            command([DRIVER, "--dynamic", errno_source, "-o", exe], env=env)
            run = command([exe], env=env, check=False)
            expect(run.returncode == 42,
                   f"{assembler} dynamic errno accessor failed: {run.stderr}")
            errno_source.write_text("#include <errno.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <sys/stat.h>\n#include <dirent.h>\n#include <stdio.h>\n"
                                    "int *other_errno(); int main() { "
                                    "int *p = &errno; errno = 0; "
                                    "if (p != __errno_location() || p != other_errno()) return 1; "
                                    "if (file_close(-1) != -1 || errno != EBADF) return 2; "
                                    "*p = ERANGE; return *other_errno() == ERANGE ? 42 : 3; }\n")
            errno_module = td / "errno-module.bc"
            errno_module.write_text("extern int errno; int *other_errno() { return &errno; }\n")
            obj, errno_obj = td / "errno-main.o", td / "errno-module.o"
            command([DRIVER, "-c", errno_source, "-o", obj], env=env)
            command([DRIVER, "-c", errno_module, "-o", errno_obj], env=env)
            for inputs in ((errno_source, errno_module), (obj, errno_obj)):
                command([DRIVER, "--dynamic", *inputs, "-o", exe], env=env)
                run = command([exe], env=env, check=False)
                expect(run.returncode == 42,
                       f"{assembler} dynamic errno storage failed for {inputs}: {run.stderr}")
        conf.write_text(f"assembler = crunch\nlinker = {selected_linker}\n")
        source.write_text("extern int external_answer(); int main() { return external_answer(); }\n")

        first, second = td / "first", td / "second"
        first.mkdir()
        second.mkdir()
        answer_obj = first / "answer.o"
        command([BUILD / "crunch-as", "-o", answer_obj], input=
                ".text\n.globl external_answer\n.type external_answer,@function\n"
                "external_answer: mov $23,%eax\nret\n")
        command([BUILD / "crunch-ar", "rcs", first / "libdriverprobe.a", answer_obj])
        partial_forbidden = td / "forbidden.o"
        command([BUILD / "crunch-ld", "-r", "--forbid-defined=missing_symbol",
                 "-o", partial_forbidden, answer_obj])
        partial_forbidden.write_text("preserved")
        for flag in ("--forbid-defined=external_answer", "--forbid-defined"):
            args = [flag] if "=" in flag else [flag, "external_answer"]
            result = command([BUILD / "crunch-ld", "-r", *args, "-o", partial_forbidden,
                              answer_obj], check=False)
            expect(result.returncode != 0 and "external_answer" in result.stderr and
                   partial_forbidden.read_text() == "preserved",
                   "forbidden linker symbol was not rejected safely")
        command([BUILD / "crunch-ld", "-nostdlib", "-shared", "-o", first / "libdriverprobe.so", provider_obj])
        command([BUILD / "crunch-ld", "-nostdlib", "-shared", "-soname", "libdriverprobe.so.1",
                 "-o", second / "libdriverprobe.so", provider_obj])
        (second / "libdriverprobe.so.1").symlink_to("libdriverprobe.so")
        conf.write_text(f"assembler = crunch\nlinker = {selected_linker}\n"
                        f"library_path = {second}\n")
        library_env = dict(env, LD_LIBRARY_PATH=f"{first}:{second}")
        for args, expected, dependency in (
                ([source, "-L", first, "-ldriverprobe"], 42, "libdriverprobe.so"),
                ([source, "-L", second, "-l:libdriverprobe.so.1"], 42, "libdriverprobe.so.1"),
                (["--dynamic", source, "-L", first, "-ldriverprobe"], 42, "libdriverprobe.so"),
                (["--dynamic", source, "-L", first, "-l", "driverprobe"], 42, "libdriverprobe.so"),
                (["--dynamic", source, "-ldriverprobe"], 42, "libdriverprobe.so.1"),
                (["--dynamic", source, "-L", first, "-l:libdriverprobe.a"], 23, None),
                (["--dynamic", source, "-L", second, "-l:libdriverprobe.so.1"], 42,
                 "libdriverprobe.so.1"),
                (["--static", source, "-L", first, "-ldriverprobe"], 23, None)):
            command([DRIVER, *args, "-o", exe], env=env)
            run = command([exe], env=library_env, check=False)
            needed, _ = dynamic_metadata(exe)
            expect(run.returncode == expected and (dependency is None or dependency in needed),
                   f"library search failed for {args}: {needed}, {run.stderr}")
        command([DRIVER, "--dynamic", source, first / "libdriverprobe.so", "-o", exe], env=env)
        expect(str(first / "libdriverprobe.so") in dynamic_metadata(exe)[0],
               "direct no-SONAME shared input did not retain its path")
        command([DRIVER, "--dynamic", source, "-L", "first", "-ldriverprobe", "-o", exe],
                cwd=td, env=env)
        needed, runpath = dynamic_metadata(exe)
        expect("libdriverprobe.so" in needed and "first" not in runpath and
               command([exe], cwd=td, env=library_env, check=False).returncode == 42,
               "relative search changed the recorded dependency or runtime path")
        failed = command([exe], cwd=td, env=env, check=False)
        expect(failed.returncode != 0 and "libdriverprobe.so" in failed.stderr,
               "link-time library path unexpectedly became a runtime path")
        bundle = td / "bundle"
        binary, lib, alternate = bundle / "bin", bundle / "lib", bundle / "alternate"
        for path in (binary, lib, alternate):
            path.mkdir(parents=True)
        shutil.copy2(BUILD / "libcrunch.so.1", lib / "libcrunch.so.1")
        shutil.copy2(second / "libdriverprobe.so", lib / "libdriverprobe.so.1")
        command([BUILD / "crunch-ld", "-nostdlib", "-shared", "-soname", "libdriverprobe.so.1",
                 "-o", alternate / "libdriverprobe.so.1", answer_obj])
        bundled_exe = binary / "program"
        paths = ["$ORIGIN/../lib", "$ORIGIN/../alternate",
                 "$ORIGIN/../missing:$ORIGIN/../last", "$ORIGIN/../unused"]
        command([DRIVER, "--rpath", paths[0], "-rpath", paths[1],
                 "--rpath=" + paths[2], "-rpath=" + paths[3],
                 source, "-L", second, "-ldriverprobe", "-o", bundled_exe], env=env)
        needed, runpath = dynamic_metadata(bundled_exe)
        expect(runpath == ":".join([*paths, str(BUILD)]) and
               "libdriverprobe.so.1" in needed, f"incorrect driver RUNPATH: {runpath}")
        run = command([bundled_exe], cwd=td, env=env, check=False)
        expect(run.returncode == 42, f"bundled RUNPATH search failed: {run.stderr}")
        moved = td / "relocated"
        shutil.move(bundle, moved)
        run = command([moved / "bin/program"], cwd=td, env=env, check=False)
        expect(run.returncode == 42, f"relocated RUNPATH search failed: {run.stderr}")
        debug = command([moved / "bin/program"], cwd=td, env=dict(env, LD_DEBUG="libs"), check=False)
        expect(debug.returncode == 42 and
               f"calling init: {moved}/bin/../lib/libcrunch.so.1" in debug.stderr,
               "explicit RUNPATH did not take precedence over the built-in runtime path")
        command([DRIVER, "--dynamic", "--rpath=$ORIGIN/../absent", source,
                 "-L", first, "-l:libdriverprobe.a", "-o", exe], env=env)
        expect(command([exe], cwd=td, env=env, check=False).returncode == 23,
               "built-in runtime path did not remain a fallback")
        failed = command([DRIVER, "--dynamic", "--rpath", str(first), source,
                          "-l:libdriverprobe.a", "-o", exe], env=env, check=False)
        expect(failed.returncode != 0 and "cannot find" in failed.stderr,
               "runtime path unexpectedly affected link-time search")
        partial = td / "search.o"
        command([DRIVER, "-c", source, "-L", first, "-ldriverprobe", "-o", partial], env=env)
        command([DRIVER, "--static", partial, "-o", exe], env=env)
        expect(command([exe], env=env, check=False).returncode == 23,
               "relocatable link did not select the static archive")
        command([DRIVER, assembly, "-L", first, "-ldriverprobe", "-o", partial], env=env)
        command([DRIVER, "--static", partial, "-o", exe], env=env)
        expect(command([exe], env=env, check=False).returncode == 23,
               "implicit relocatable link did not select the static archive")
        (first / "libdriverprobe.so").unlink()
        command([DRIVER, "--dynamic", source, "-L", first, "-ldriverprobe", "-o", exe], env=env)
        run = command([exe], env=library_env, check=False)
        expect(run.returncode == 23 and "libdriverprobe.so.1" not in dynamic_metadata(exe)[0],
               "later shared library took precedence over earlier archive")
        command([DRIVER, "--dynamic", source, "-L", second, "-ldriverprobe", "-ldriverprobe",
                 "-o", exe], env=env)
        expect(dynamic_metadata(exe)[0].count("libdriverprobe.so.1") == 1,
               "repeated searched shared dependencies were not deduplicated")
        exe.write_text("preserved")
        for args in (["--dynamic", source, "-L", first, "-l:missing.so"],
                     ["--dynamic", source, "-l:bad.txt"],
                     ["--static", source, "-L", second, "-l:libdriverprobe.so.1"],
                     ["-c", source, "-L", second, "-l:libdriverprobe.so.1"],
                     ["--dynamic", "-L", first, "-ldriverprobe", source]):
            result = command([DRIVER, *args, "-o", exe], env=env, check=False)
            expect(result.returncode != 0 and result.stderr and exe.read_text() == "preserved",
                   f"invalid library search did not fail safely: {args}")
        for args in (["-c", source, "--rpath", "foo"], ["--static", source, "-rpath", "foo"],
                     [assembly, "-o", td / "implicit.o", "--rpath", "foo"],
                     ["--dynamic", "-c", source, "--rpath", "foo"],
                     ["--dynamic", assembly, "-o", td / "implicit.o", "--rpath", "foo"],
                     ["--archive", "--rpath", "foo", provider_obj],
                     ["--dynamic", source, "--rpath="], ["--dynamic", source, "-rpath="],
                     ["--dynamic", source, "--rpath"], ["--dynamic", source, "-rpath", "-v"]):
            output_args = [] if "-o" in args else ["-o", exe]
            result = command([DRIVER, *args, *output_args], env=env, check=False)
            expect(result.returncode != 0 and result.stderr and exe.read_text() == "preserved",
                   f"invalid driver RUNPATH was not rejected safely: {args}")
        implicit_obj = td / "implicit.o"
        implicit_obj.write_text("preserved")
        for args in (["-c", source, "-z", "relro"], ["--static", source, "-zrelro"],
                     [assembly, "-o", implicit_obj, "-zrelro"],
                     ["--dynamic", "-c", source, "-z", "relro"],
                     ["--dynamic", "-E", source, "-z", "relro"],
                     ["--dynamic", assembly, "-o", implicit_obj, "-zrelro"],
                     ["--archive", "-z", "relro", provider_obj],
                     ["--dynamic", source, "-z"], ["--dynamic", source, "-z", "-v"],
                     ["--dynamic", source, "-z", "now"], ["--dynamic", source, "-znorelro"]):
            output_args = [] if "-o" in args else ["-o", exe]
            result = command([DRIVER, *args, *output_args], env=env, check=False)
            expect(result.returncode != 0 and result.stderr and exe.read_text() == "preserved"
                   and implicit_obj.read_text() == "preserved",
                   f"invalid driver RELRO option was not rejected safely: {args}")
        target = second / "libdriverprobe.so"
        original_target = target.read_bytes()
        result = command([DRIVER, "--dynamic", source, "-L", second, "-ldriverprobe",
                          "-o", target], env=env, check=False)
        expect(result.returncode != 0 and "also an input" in result.stderr and
               target.read_bytes() == original_target,
               "searched shared library output collision was not rejected")
        (first / "libdriverprobe.so").write_text("not a shared object")
        result = command([DRIVER, "--dynamic", source, "-L", first, "-ldriverprobe",
                          "-o", exe], env=env, check=False)
        expect(result.returncode != 0 and result.stderr and exe.read_text() == "preserved",
               "invalid preferred shared library silently fell back to the archive")

        source.write_text('#include <stdlib.h>\nint values[] = {40, 2};'
                          'int printf(const char* format); int main() { printf("dynamic;"); exit(values[0]+values[1]); return 0; }\n')
        wrapper, marker = td / "linker-wrapper", td / "linker-called"
        wrapper.write_text(f"#!/bin/sh\nprintf called > '{marker}'\nexec '{BUILD / 'crunch-ld'}' \"$@\"\n")
        wrapper.chmod(0o755)
        conf.write_text("assembler = crunch\nlinker = crunch\n"
                        f"linker_path = {wrapper}\n")
        result = command([DRIVER, "--dynamic", "-v", source, "-o", exe], env=env)
        expect(marker.read_text() == "called" and str(wrapper) in result.stderr and
               command([exe], env=env, check=False).returncode == 42,
               "configured native linker was not usable with --dynamic")

        exe.write_text("preserved")
        for args in (["--dynamic", "--static", source], ["--dynamic", "-c", source],
                     ["--static", "-S", source], ["--dynamic", "--archive", provider_obj],
                     ["--dynamic", assembly, "-o", td / "implicit.o"],
                     ["--static", assembly, provider]):
            output_args = [] if "-o" in args else ["-o", exe]
            result = command([DRIVER, *args, *output_args], env=env, check=False)
            expect(result.returncode != 0 and result.stderr and exe.read_text() == "preserved",
                   f"invalid driver mode was not rejected safely: {args}")
        conflicting_errno = td / "defined-errno.bc"
        conflicting_errno.write_text("int errno; int main() { errno = 42; return errno; }\n")
        result = command([DRIVER, conflicting_errno, "-o", exe], env=env, check=False)
        expect(result.returncode != 0 and "errno" in result.stderr and exe.read_text() == "preserved",
               "dynamic link accepted an executable definition of protected runtime errno")
        competing_obj, competing_so = td / "competing-errno.o", td / "competing-errno.so"
        command([BUILD / "crunch-as", "-o", competing_obj], input=
                ".data\n.globl errno\n.type errno,@object\n.size errno,4\nerrno: .long 0\n")
        command([BUILD / "crunch-ld", "-nostdlib", "-shared", "-o", competing_so, competing_obj])
        result = command([DRIVER, source, competing_so, "-o", exe], env=env, check=False)
        expect(result.returncode != 0 and "errno" in result.stderr and exe.read_text() == "preserved",
               "dynamic link accepted conflicting shared definitions of errno")
        legacy = td / "legacy-errno.s"
        legacy.write_text(".text\n.globl _start\n_start:\n"
                          "movl $42, errno(%rip)\nmov errno(%rip), %edi\n"
                          "mov $60, %eax\nsyscall\n")
        result = command([DRIVER, legacy, "-o", exe], env=env, check=False)
        expect(result.returncode != 0 and "errno" in result.stderr and exe.read_text() == "preserved",
               "unsupported direct shared errno relocation was not rejected safely")
        command([DRIVER, "--static", legacy, "-o", exe], env=env)
        expect(command([exe], env=env, check=False).returncode == 42,
               "legacy direct errno reference failed with static linking")
        command([DRIVER, "--static", conflicting_errno, "-o", exe], env=env)
        expect(command([exe], env=env, check=False).returncode == 42,
               "static link rejected an executable definition of errno")
        exe.write_text("preserved")
        alias = td / "runtime-alias"
        alias.symlink_to(BUILD / "libcrunch.so.1")
        original = alias.read_bytes()
        result = command([DRIVER, "--dynamic", source, "-o", alias], env=env, check=False)
        expect(result.returncode != 0 and "shared runtime input" in result.stderr and
               alias.read_bytes() == original, "shared runtime output collision was not rejected")
        isolated = td / "isolated"
        isolated.mkdir()
        shutil.copy2(BUILD / "crunch", isolated / "crunch")
        result = command([isolated / "crunch", "--dynamic", provider_obj, "-o", exe],
                         env=env, check=False)
        expect(result.returncode != 0 and "libcrunch.so" in result.stderr and
               exe.read_text() == "preserved",
               "missing shared runtime did not fail safely")


def native_relro_case():
    """Check dynamic RELRO layout, loader protection, and writable data.

    Returns:
        None; raises AssertionError for incorrect RELRO behavior or rejection.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-relro-") as directory:
        td = pathlib.Path(directory)
        assembler, linker = BUILD / "crunch-as", BUILD / "crunch-ld"
        provider, library, exe = td / "provider.so", td / "consumer.so", td / "program"
        common = (
            ".data\ncounter: .long 0\n.globl normal\nnormal: .long 0\n"
            ".bss\n.balign 8\nscratch: .zero 8\n"
            '.section .data.rel.ro.example,"aw",@progbits\n'
            ".globl ro_pointer\nro_pointer: .quad external_value\n.zero 8193\n"
            ".text\ninitialize: movl $38,counter(%rip)\nret\n"
            "finalize: addl $1,counter(%rip)\n"
            "mov finished@GOTPCREL(%rip),%rax\naddl $1,(%rax)\nret\n"
            ".globl got_address\n.type got_address,@function\n"
            "got_address: lea external_value@GOTPCREL(%rip),%rax\nret\n"
            ".globl check\n.type check,@function\ncheck:\n"
            "mov external_value@GOTPCREL(%rip),%rax\nmov (%rax),%eax\n"
            "mov ro_pointer@GOTPCREL(%rip),%rdx\nmov (%rdx),%rdx\nadd (%rdx),%eax\n"
            "add counter(%rip),%eax\nret\n"
            '.section .init_array,"aw",@init_array\n.globl init_entry\ninit_entry: .quad initialize\n'
            '.section .fini_array,"aw",@fini_array\n.globl fini_entry\nfini_entry: .quad finalize\n'
        )
        start = (
            ".text\n.globl _start\n_start:\n"
            "mov (%rsp),%rax\ncmp $2,%rax\nje write_ro\n"
            "cmp $3,%rax\nje write_init\ncmp $4,%rax\nje write_fini\n"
            "cmp $5,%rax\nje write_got\n"
            "movl $1,normal(%rip)\nmovq $1,scratch(%rip)\n"
            "and $-16,%rsp\ncall check@PLT\ncmp $42,%eax\njne fail\n"
            "call __crunch_run_finalizers@PLT\ncmpl $39,counter(%rip)\njne fail\n"
            "mov $42,%edi\nmov $60,%eax\nsyscall\n"
            "write_ro: movq $0,ro_pointer(%rip)\njmp fail\n"
            "write_init: movq $0,init_entry(%rip)\njmp fail\n"
            "write_fini: movq $0,fini_entry(%rip)\njmp fail\n"
            "write_got: lea external_value@GOTPCREL(%rip),%rax\nmovq $0,(%rax)\n"
            "fail: mov $1,%edi\nmov $60,%eax\nsyscall\n"
            '.section __crunch_init_array,"aw",@progbits\n.quad initialize\n'
        )
        command([assembler, "-o", td / "provider.o"], input=
                ".data\n.globl external_value\nexternal_value: .long 2\n"
                ".globl finished\nfinished: .long 0\n")
        command([linker, "-nostdlib", "-shared", "-soname", provider.name, "-o", provider, td / "provider.o"])
        command([assembler, "-o", td / "shared.o"], input=common)
        command([assembler, "-o", td / "main.o"], input=common + start)

        def image_layout(path):
            """Read named sections and program headers from a generated ELF.

            Args:
                path: Executable or shared object to inspect.
            Returns:
                Pair of section dictionary and program header list.
            """
            image = path.read_bytes()
            phoff, shoff = struct.unpack_from("<QQ", image, 32)
            phentsize, phnum, shentsize, shnum, shstrndx = struct.unpack_from("<HHHHH", image, 54)
            ph = [struct.unpack_from("<IIQQQQQQ", image, phoff + i * phentsize)
                  for i in range(phnum)]
            sh = [struct.unpack_from("<IIQQQQIIQQ", image, shoff + i * shentsize)
                  for i in range(shnum)]
            strings = image[sh[shstrndx][4]:sh[shstrndx][4] + sh[shstrndx][5]]
            sections = {strings[h[0]:strings.index(b"\0", h[0])].decode(): h for h in sh}
            return sections, ph

        def check_layout(path, enabled):
            """Validate protection boundaries and dynamic section placement.

            Args:
                path: Generated ELF file.
                enabled: Whether RELRO should be present.
            Returns:
                None; raises AssertionError on an invalid layout.
            """
            sections, headers = image_layout(path)
            segments = [p for p in headers if p[0] == 0x6474e552]
            expect(len(segments) == int(enabled), "incorrect PT_GNU_RELRO count")
            expect((".data.rel.ro" in sections) == enabled, "incorrect data.rel.ro placement")
            if not enabled:
                return
            segment = segments[0]
            start_addr, end_addr = segment[3], segment[3] + segment[6]
            expect(end_addr % 4096 == 0 and segment[5] == segment[6] and
                   any(p[0] == 1 and p[1] & 2 and p[3] <= start_addr and
                       p[3] + p[6] >= end_addr for p in headers),
                   "RELRO does not end at a writable load segment page boundary")
            for name in (".dynamic", ".got", ".data.rel.ro", ".init_array", ".fini_array"):
                sec = sections[name]
                expect(start_addr <= sec[3] and sec[3] + sec[5] <= end_addr,
                       f"{name} is outside RELRO")
            for name in (".data", ".bss", "__crunch_init_array"):
                if name in sections:
                    expect(sections[name][3] >= end_addr, f"{name} overlaps RELRO")

        env = {"PATH": os.environ.get("PATH", ""), "LD_LIBRARY_PATH": str(td)}
        probe = ("import resource,subprocess,sys; "
                 "resource.setrlimit(resource.RLIMIT_CORE,(0,0)); "
                 "p=subprocess.run(sys.argv[1:]); sys.exit(0 if p.returncode == -11 else 1)")
        loader = r"""
import _ctypes, ctypes, sys
provider = ctypes.CDLL(sys.argv[3])
library = ctypes.CDLL(sys.argv[1])
assert library.check() == 42
normal = ctypes.c_int.in_dll(library, "normal")
normal.value = 12
assert normal.value == 12
addresses = [ctypes.addressof(ctypes.c_void_p.in_dll(library, name))
             for name in ("ro_pointer", "init_entry", "fini_entry")]
library.got_address.restype = ctypes.c_void_p
addresses.append(library.got_address())
with open("/proc/self/maps") as maps:
    lines = [line.split() for line in maps]
    regions = [(int(parts[0].split("-")[0], 16), int(parts[0].split("-")[1], 16), parts[1])
               for parts in lines]
    base = next(int(parts[0].split("-")[0], 16) for parts in lines
                if len(parts) >= 6 and parts[2] == "00000000" and parts[-1] == sys.argv[1])
addresses.append(base + int(sys.argv[2]))
for address in addresses:
    assert any(lo <= address < hi and perms[:2] == "r-" for lo, hi, perms in regions)
assert any(lo <= ctypes.addressof(normal) < hi and perms[1] == "w"
           for lo, hi, perms in regions)
_ctypes.dlclose(library._handle)
assert ctypes.c_int.in_dll(provider, "finished").value == 1
"""
        write_probe = ("import ctypes,resource,sys; resource.setrlimit(resource.RLIMIT_CORE,(0,0)); "
                       "l=ctypes.CDLL(sys.argv[1]); "
                       "ctypes.c_void_p.in_dll(l,sys.argv[2]).value=0")
        for enabled in (False, True):
            options = ["-z", "relro"] if enabled else []
            command([linker, "-nostdlib", "-shared", *options, "-o", library, td / "shared.o", provider])
            command([linker, "-nostdlib", "-dynamic", *options, "-o", exe, td / "main.o", provider])
            check_layout(library, enabled)
            check_layout(exe, enabled)
            result = command([exe], env=env, check=False)
            expect(result.returncode == 42, f"RELRO executable failed: {result.stderr}")
            if enabled:
                command([PYTHON, "-c", loader, library,
                         image_layout(library)[0][".dynamic"][3], provider], env=env)
                for count in range(1, 5):
                    command([PYTHON, "-c", probe, exe, *(["x"] * count)], env=env)
                for name in ("ro_pointer", "init_entry", "fini_entry"):
                    result = command([PYTHON, "-c", write_probe, library, name], env=env, check=False)
                    expect(result.returncode == -11, f"shared {name} was writable")
            else:
                command([PYTHON, "-c", write_probe, library, "ro_pointer"], env=env)
                expect(command([exe, "x"], env=env, check=False).returncode == 1,
                       "default executable data.rel.ro unexpectedly became read-only")

        driver_source = td / "driver.s"
        driver_source.write_text(common + start)
        conf = td / "driver.conf"
        conf.write_text("assembler = crunch\nlinker = crunch\n")
        driver_env = dict(env, CRUNCH_CONF_FILE=str(conf))
        for flags in (["-z", "relro"], ["-zrelro", "--dynamic"], ["-pie", "-z", "relro"]):
            command([DRIVER, *flags, driver_source, provider, "-o", exe],
                    env=driver_env)
            check_layout(exe, True)
            result = command([exe], env=driver_env, check=False)
            expect(result.returncode == 42, f"driver RELRO executable failed: {result.stderr}")
            for count in range(1, 5):
                command([PYTHON, "-c", probe, exe, *(["x"] * count)], env=driver_env)
        command([DRIVER, driver_source, provider, "-o", exe], env=driver_env)
        check_layout(exe, False)

        command([linker, "-nostdlib", "-r", "-o", td / "partial.o", td / "shared.o"])
        command([linker, "-nostdlib", "-shared", "-zrelro", "-o", library, td / "partial.o", provider])
        check_layout(library, True)
        command([PYTHON, "-c", loader, library,
                 image_layout(library)[0][".dynamic"][3], provider], env=env)
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            command(["as", "-o", td / "gnu.o", "-"], input=common)
            command([linker, "-nostdlib", "-shared", "-z", "relro", "-o", library, td / "gnu.o", provider])
            check_layout(library, True)
            command([PYTHON, "-c", loader, library,
                     image_layout(library)[0][".dynamic"][3], provider], env=env)

        command([assembler, "-o", td / "simple.o"], input=
                ".text\n.globl _start\n_start: mov $60,%eax\nmov $42,%edi\nsyscall\n")
        for mode in ("-shared", "-dynamic"):
            command([linker, "-nostdlib", mode, "-z", "relro", "-o", exe, td / "simple.o"])
            sections, headers = image_layout(exe)
            relro_headers = [p for p in headers if p[0] == 0x6474e552]
            expect(len(relro_headers) == 1 and ".dynamic" in sections and ".got" not in sections,
                   f"RELRO missing from minimal {mode} output")
            if mode == "-dynamic":
                expect(command([exe], env=env, check=False).returncode == 42,
                       "minimal RELRO executable failed")

        source = td / "module.bc"
        source.write_text("extern int order; int main() { return order + 30; }\n")
        command([DRIVER, "-c", source, "-o", td / "module.o"])
        asm = td / "legacy-init.s"
        asm.write_text(command([ASM, FIXTURES / "ir/legacy_init_first.bir"]).stdout)
        command([assembler, "-o", td / "legacy-init.o", asm])
        command([linker, "-nostdlib", "-dynamic", "-z", "relro", "-o", exe,
                 td / "module.o", td / "legacy-init.o",
                 BUILD / "libcrunch-fallback.a", BUILD / "libcrunch.so"])
        result = command([exe], env={"LD_LIBRARY_PATH": str(BUILD)}, check=False)
        expect(result.returncode == 42, f"Crunch initialized module failed under RELRO: {result.stderr}")
        command([DRIVER, "-c", FIXTURES / "units/function_calls/end_header_literal.bc",
                 "-o", td / "end.o"])
        command([linker, "-nostdlib", "-dynamic", "-z", "relro", "-o", exe,
                 td / "end.o", BUILD / "libcrunch-fallback.a", BUILD / "libcrunch.so"])
        result = command([exe], env={"LD_LIBRARY_PATH": str(BUILD)}, check=False)
        expect(result.returncode == 7 and result.stdout == "before;",
               "shared Crunch exit() failed under RELRO")

        output = td / "preserved"
        output.write_text("preserved")
        for flags in (["-z", "relro"], ["-r", "-z", "relro"],
                      ["-shared", "-r", "-z", "relro"], ["-shared", "-z", "now"],
                      ["-shared", "-z"]):
            result = command([linker, "-nostdlib", "-o", output, td / "main.o", *flags], check=False)
            expect(result.returncode != 0 and result.stderr and output.read_text() == "preserved",
                   f"invalid RELRO option was not rejected safely: {flags}")
        command([assembler, "-o", td / "bad.o"], input=
                '.section .data.rel.ro.bad,"a",@progbits\n.quad 1\n')
        result = command([linker, "-nostdlib", "-shared", "-z", "relro", "-o", output, td / "bad.o"],
                         check=False)
        expect(result.returncode != 0 and "RELRO section" in result.stderr and
               output.read_text() == "preserved", "malformed RELRO section was accepted")


def native_runpath_case():
    """Check opt-in runtime paths for executables and shared dependencies.

    Returns:
        None; raises AssertionError for incorrect metadata or loader behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-runpath-") as directory:
        td = pathlib.Path(directory)
        bundle = td / "bundle"
        binary, lib, private = bundle / "bin", bundle / "lib", bundle / "private"
        for path in (binary, lib, private):
            path.mkdir(parents=True)
        assembler, linker = BUILD / "crunch-as", BUILD / "crunch-ld"
        leaf = private / "libcrunch_runpath_leaf_test.so"
        consumer = lib / "libcrunch_runpath_consumer_test.so"
        exe = binary / "program"
        for name, source in (
                ("leaf", ".text\n.globl value\n.type value,@function\nvalue: mov $40,%eax\nret\n"),
                ("consumer", ".text\n.globl answer\n.type answer,@function\nanswer:\n"
                 "sub $8,%rsp\ncall value@PLT\nadd $8,%rsp\nadd $2,%eax\nret\n"),
                ("main", ".text\n.globl _start\n_start:\nand $-16,%rsp\n"
                 "call answer@PLT\nmov %eax,%edi\nmov $60,%eax\nsyscall\n")):
            command([assembler, "-o", td / f"{name}.o"], input=source)
        command([linker, "-nostdlib", "-shared", "-soname", leaf.name, "-o", leaf, td / "leaf.o"])
        command([linker, "-nostdlib", "-shared", "-soname", consumer.name, "-o", consumer,
                 td / "consumer.o", leaf])

        def dynamic_paths(path):
            """Read the dynamic search path tags from a generated ELF file.

            Args:
                path: Executable or shared object to inspect.
            Returns:
                List of (tag, search path) pairs.
            """
            image = path.read_bytes()
            shoff = struct.unpack_from("<Q", image, 40)[0]
            entsize, count = struct.unpack_from("<HH", image, 58)
            headers = [struct.unpack_from("<IIQQQQIIQQ", image, shoff + i * entsize)
                       for i in range(count)]
            dynamic = next(h for h in headers if h[1] == 6)
            strings = headers[dynamic[6]]
            data = image[strings[4]:strings[4] + strings[5]]
            entries = [struct.unpack_from("<qQ", image, pos)
                       for pos in range(dynamic[4], dynamic[4] + dynamic[5], 16)]
            return [(tag, data[value:data.index(b"\0", value)].decode())
                    for tag, value in entries if tag in (15, 29)]

        env = {"PATH": os.environ.get("PATH", "")}
        command([linker, "-nostdlib", "-dynamic", "-o", exe, td / "main.o", consumer])
        expect(dynamic_paths(exe) == [] and dynamic_paths(consumer) == [],
               "runtime path was emitted without an option")
        failed = command([exe], env=env, check=False)
        expect(failed.returncode != 0 and consumer.name in failed.stderr,
               "loader unexpectedly found the direct dependency")
        command([linker, "-nostdlib", "-dynamic", "-rpath", "$ORIGIN/../missing",
                 "--rpath=$ORIGIN/../lib", "-rpath=$ORIGIN/../private",
                 "-o", exe, td / "main.o", consumer])
        expect(dynamic_paths(exe) == [(29, "$ORIGIN/../missing:$ORIGIN/../lib:$ORIGIN/../private")],
               "executable RUNPATH entries were not combined in order")
        failed = command([exe], env=env, check=False)
        expect(failed.returncode != 0 and leaf.name in failed.stderr,
               "executable RUNPATH unexpectedly applied to a transitive dependency")
        command([linker, "-nostdlib", "-shared", "--rpath", "$ORIGIN/../private",
                 "-soname", consumer.name, "-o", consumer, td / "consumer.o", leaf])
        expect(dynamic_paths(consumer) == [(29, "$ORIGIN/../private")],
               "shared object RUNPATH is missing or incorrect")
        result = command([exe], env=env, check=False)
        expect(result.returncode == 42, f"runtime paths failed: {result.stderr}")
        moved = td / "moved"
        shutil.move(bundle, moved)
        result = command([moved / "bin/program"], cwd=td, env=env, check=False)
        expect(result.returncode == 42, f"relocated runtime paths failed: {result.stderr}")

        output = td / "preserved"
        for mode, obj in (("-shared", "leaf"), ("-dynamic", "main")):
            if mode == "-dynamic":
                command([assembler, "-o", td / "standalone.o"], input=
                        ".text\n.globl _start\n_start: mov $60,%eax\nxor %edi,%edi\nsyscall\n")
                obj = "standalone"
            command([linker, "-nostdlib", mode, "--rpath=standalone", "-o", output, td / f"{obj}.o"])
            expect(dynamic_paths(output) == [(29, "standalone")],
                   f"RUNPATH missing from relocation-free {mode} output")
        output.write_text("preserved")
        invalid = (["-rpath", "path"], ["-r", "-rpath", "path"],
                   ["-shared", "-r", "-rpath", "path"],
                   ["-dynamic", "--rpath="], ["-shared", "-rpath"])
        for flags in invalid:
            result = command([linker, "-nostdlib", "-o", output, td / "main.o", *flags], check=False)
            expect(result.returncode != 0 and result.stderr and output.read_text() == "preserved",
                   f"invalid RUNPATH option was not rejected safely: {flags}")
        result = command([linker, "-nostdlib", "-dynamic", "-rpath", str(moved / "lib"),
                          "-o", output, td / "main.o", "-lcrunch_runpath_consumer_test"],
                         check=False)
        expect(result.returncode != 0 and "cannot find" in result.stderr and
               output.read_text() == "preserved", "RUNPATH affected link-time library search")


def native_dynamic_strip_case():
    """Verify GNU strip preserves executable interpreters and dynamic loading.

    Returns:
        None; raises AssertionError if stripped executable or shared output fails.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-dynamic-strip-") as directory:
        td = pathlib.Path(directory)
        assembler, linker = BUILD / "crunch-as", BUILD / "crunch-ld"
        provider, library = td / "provider.o", td / "libanswer.so"
        obj, exe = td / "start.o", td / "program"
        command([assembler, "-o", provider], input=
                ".text\n.globl answer\n.type answer,@function\nanswer: mov $42,%eax\nret\n")
        command([linker, "-nostdlib", "-shared", "-soname", "libanswer.so",
                 "-o", library, provider])
        command(["strip", library])
        command([assembler, "-o", obj], input=
                ".text\n.globl _start\n_start:\n"
                "and $-16,%rsp\ncall answer@PLT\nmov %eax,%edi\nmov $60,%eax\nsyscall\n")
        env = {k: v for k, v in os.environ.items()
               if k not in ("LD_LIBRARY_PATH", "LD_PRELOAD", "LD_AUDIT")}
        for mode in ([], ["-pie"], ["-pie", "-z", "relro", "-s"]):
            for strip_flags in ([], ["--strip-debug"]):
                command([linker, "-nostdlib", "-dynamic", *mode,
                         "-rpath", str(td),
                         "-o", exe, obj, library])
                expect(command([exe], env=env, check=False).returncode == 42,
                       f"unstripped dynamic executable failed: {mode}")
                command(["strip", *strip_flags, exe])
                result = command([exe], env=env, check=False)
                expect(result.returncode == 42,
                       f"stripped dynamic executable failed for {mode}, {strip_flags}: {result.stderr}")


def native_dynamic_executable_case():
    """Execute fixed-address dynamic links and check their supported boundaries.

    Returns:
        None; raises AssertionError for incorrect dynamic executable behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-dynamic-exe-") as directory:
        td = pathlib.Path(directory)
        assembler, linker = BUILD / "crunch-as", BUILD / "crunch-ld"
        provider, main, exe = td / "provider.o", td / "main.o", td / "program"
        library = td / "libanswer.so"
        command([assembler, "-o", provider], input=
                ".data\n.globl value\n.type value,@object\nvalue: .long 40\n"
                ".text\n.globl answer\n.type answer,@function\n"
                "answer: mov value@GOTPCREL(%rip),%rax\nmov (%rax),%eax\n"
                "mov executable_value@GOTPCREL(%rip),%rdx\nadd (%rdx),%eax\nret\n"
                "initialize: mov value@GOTPCREL(%rip),%rax\nmovl $41,(%rax)\nret\n"
                "finalize: mov $1,%eax\nmov $1,%edi\nlea message(%rip),%rsi\n"
                "mov $1,%edx\nsyscall\nret\n"
                '.section .rodata\nmessage: .byte 70\n'
                '.section .init_array,"aw",@init_array\n.quad initialize\n'
                '.section .fini_array,"aw",@fini_array\n.quad finalize\n')
        command([linker, "-nostdlib", "-shared", "-soname", "libanswer.so", "-o", library, provider])
        source = (".data\n.globl executable_value\nexecutable_value: .long 1\n"
                  "pointer: .quad value+4\nlocal_pointer: .quad executable_value\n"
                  "weak_pointer: .quad missing+8\n"
                  ".weak missing\n.text\n.globl _start\n_start:\n"
                  "mov missing@GOTPCREL(%rip),%rax\ntest %rax,%rax\njne fail\n"
                  "mov value@GOTPCREL(%rip),%rax\nlea 4(%rax),%rdx\n"
                  "cmp pointer(%rip),%rdx\njne fail\n"
                  "cmpq $8,weak_pointer(%rip)\njne fail\n"
                  "mov executable_value@GOTPCREL(%rip),%rax\n"
                  "cmp local_pointer(%rip),%rax\njne fail\n"
                  "lea executable_value(%rip),%rdx\ncmp local_pointer(%rip),%rdx\njne fail\n"
                  "and $-16,%rsp\ncall answer@PLT\nmov %eax,%edi\n"
                  "mov $60,%eax\nsyscall\nfail: mov $1,%edi\nmov $60,%eax\nsyscall\n")
        command([assembler, "-o", main], input=source)
        env = {key: value for key, value in os.environ.items()
               if key not in ("LD_PRELOAD", "LD_LIBRARY_PATH", "LD_AUDIT")}
        env["LD_LIBRARY_PATH"] = str(td)
        interpreter = next(p for p in ("/lib64/ld-linux-x86-64.so.2",
                                       "/lib/ld-linux-x86-64.so.2",
                                       "/lib/x86_64-linux-gnu/ld-linux-x86-64.so.2")
                           if os.path.isfile(p))
        for options, inputs in ((["-dynamic"], [main, library, library]),
                                (["--dynamic-linker", interpreter,
                                  "-L", td], [main, "-lanswer"])):
            command([linker, "-nostdlib", *options, "-o", exe, *inputs])
            result = command([exe], env=env, check=False)
            expect(result.returncode == 42 and not result.stdout,
                   f"dynamic executable failed: {result.stderr}")
            image = exe.read_bytes()
            expect(struct.unpack_from("<H", image, 16)[0] == 2, "output is not ET_EXEC")
            phoff = struct.unpack_from("<Q", image, 32)[0]
            phentsize, phnum = struct.unpack_from("<HH", image, 54)
            headers = [struct.unpack_from("<IIQQQQQQ", image, phoff + i * phentsize)
                       for i in range(phnum)]
            interps = [ph for ph in headers if ph[0] == 3]
            actual_interp = image[interps[0][2]:interps[0][2] + interps[0][5]] if interps else b""
            expect(len(interps) == 1 and actual_interp.startswith(b"/") and
                   actual_interp.endswith(b"\0") and
                   (options[0] != "--dynamic-linker" or actual_interp == os.fsencode(interpreter) + b"\0") and
                   sum(ph[0] == 2 for ph in headers) == 1, "bad dynamic program headers")
            dynamic = next(ph for ph in headers if ph[0] == 2)
            entries = [struct.unpack_from("<qQ", image, pos)
                       for pos in range(dynamic[2], dynamic[2] + dynamic[5], 16)]
            expect(sum(tag == 1 for tag, _ in entries) == 1, "duplicate DT_NEEDED")
            strings_addr = next(value for tag, value in entries if tag == 5)
            load = next(ph for ph in headers if ph[0] == 1 and
                        ph[3] <= strings_addr < ph[3] + ph[5])
            strings = load[2] + strings_addr - load[3]
            needed = next(value for tag, value in entries if tag == 1)
            expect(image[strings + needed:image.index(b"\0", strings + needed)] == b"libanswer.so",
                   "incorrect dependency SONAME")

        command([assembler, "-o", main],
                input=source.replace(".globl _start\n_start:", ".globl custom_entry\ncustom_entry:"))
        command([linker, "-nostdlib", "-dynamic", "-e", "custom_entry", "-o", exe, main, library])
        expect(command([exe], env=env, check=False).returncode == 42,
               "explicit dynamic executable entry was not used")
        command([assembler, "-o", main], input=
                ".data\nvalue: .long 42\n.text\n.globl _start\n_start:\n"
                "mov value@GOTPCREL(%rip),%rax\nmov (%rax),%edi\nmov $60,%eax\nsyscall\n")
        command([linker, "-nostdlib", "-dynamic", "-o", exe, main])
        expect(command([exe], env=env, check=False).returncode == 42,
               "dynamic executable without shared dependencies failed")

        obj = td / "crunch.o"
        command([DRIVER, "-c", FIXTURES / "units/function_calls/end_header_literal.bc", "-o", obj])
        command([linker, "-nostdlib", "-dynamic", "-o", exe, obj,
                 BUILD / "libcrunch-fallback.a", BUILD / "libcrunch.so"])
        runtime_env = dict(env, LD_LIBRARY_PATH=str(BUILD))
        result = command([exe], env=runtime_env, check=False)
        expect(result.returncode == 7 and result.stdout == "before;",
               "Crunch-generated executable did not use the shared runtime")

        command([assembler, "-o", main], input=
                ".data\ncount: .long 0\ndone: .byte 0\n"
                ".text\ninitialize: cmpb $0,done(%rip)\njne return\n"
                "movb $1,done(%rip)\naddl $1,count(%rip)\nreturn: ret\n"
                '.section __crunch_init_array,"aw",@progbits\n.quad initialize\n'
                ".text\n.globl _start\n_start: and $-16,%rsp\n"
                "call __crunch_run_initializers@PLT\ncall __crunch_run_initializers@PLT\n"
                "mov count(%rip),%edi\nadd $41,%edi\nmov $60,%eax\nsyscall\n")
        command([linker, "-nostdlib", "-dynamic", "-o", exe, main, BUILD / "libcrunch.so"])
        expect(command([exe], env=runtime_env, check=False).returncode == 42,
               "shared runtime could not find executable module registry")

        invalid = (
            (".text\n.globl _start\n_start: call missing@PLT\n", "undefined reference"),
            (".text\n.globl _start\n_start: mov value(%rip),%eax\n", "undefined or preemptible"),
            (".text\n.globl _start\n_start: ret\n.section .rodata\n.quad value\n",
             "read-only"),
        )
        for assembly, diagnostic in invalid:
            command([assembler, "-o", main], input=assembly)
            exe.write_text("preserved")
            result = command([linker, "-nostdlib", "-dynamic", "-o", exe, main, library], check=False)
            expect(result.returncode != 0 and diagnostic in result.stderr and exe.read_text() == "preserved",
                   f"unsupported executable input was not rejected safely: {result.stderr}")
        command([assembler, "-o", main], input=".text\n.globl other\nother: ret\n")
        result = command([linker, "-nostdlib", "-dynamic", "-o", exe, main], check=False)
        expect(result.returncode != 0 and "entry symbol" in result.stderr and exe.read_text() == "preserved",
               "missing entry point was not rejected safely")
        for flags in (["-dynamic", "-shared"], ["-dynamic", "-r"],
                      ["--dynamic-linker", "relative"]):
            result = command([linker, "-nostdlib", *flags, "-o", exe, main], check=False)
            expect(result.returncode != 0 and result.stderr and exe.read_text() == "preserved",
                   f"unsupported dynamic executable mode was accepted: {flags}")


def native_dynamic_pie_case():
    """Exercise dynamic PIE relocation, ASLR, driver modes, and rejection.

    Returns:
        None; raises AssertionError for incorrect PIE behavior.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-dynamic-pie-") as directory:
        td = pathlib.Path(directory)
        assembler, linker = BUILD / "crunch-as", BUILD / "crunch-ld"
        obj, provider, library, exe = (td / name for name in
                                       ("main.o", "provider.o", "libpieprobe.so", "program"))
        command([assembler, "-o", provider], input=
                ".data\n.globl value\n.type value,@object\nvalue: .long 40\n"
                ".text\n.globl answer\n.type answer,@function\n"
                "answer: mov value@GOTPCREL(%rip),%rax\nmov (%rax),%eax\nadd $2,%eax\nret\n")
        command([linker, "-nostdlib", "-shared", "-soname", library.name, "-o", library, provider])
        assembly = (
            ".data\nlocal: .long 1\nlocal_pointer: .quad local\n"
            "shared_pointer: .quad value+4\nweak_pointer: .quad missing+8\n"
            "address: .quad _start\n.weak missing\n"
            ".text\n.globl _start\n_start:\n"
            "lea local(%rip),%rax\ncmp local_pointer(%rip),%rax\njne fail\n"
            "mov value@GOTPCREL(%rip),%rax\nlea 4(%rax),%rax\n"
            "cmp shared_pointer(%rip),%rax\njne fail\n"
            "cmpq $8,weak_pointer(%rip)\njne fail\n"
            "mov missing@GOTPCREL(%rip),%rax\ntest %rax,%rax\njne fail\n"
            "and $-16,%rsp\ncall answer@PLT\ncmp $42,%eax\njne fail\n"
            "mov $1,%eax\nmov $1,%edi\nlea address(%rip),%rsi\n"
            "mov $8,%edx\nsyscall\nmov $42,%edi\nmov $60,%eax\nsyscall\n"
            "fail: mov $1,%edi\nmov $60,%eax\nsyscall\n")
        env = {key: value for key, value in os.environ.items()
               if key not in ("LD_PRELOAD", "LD_LIBRARY_PATH", "LD_AUDIT")}
        for tool in ((assembler,) if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1"
                     else (assembler, "as")):
            args = [tool, "-o", obj] + (["-"] if tool == "as" else [])
            command(args, input=assembly)
            command([linker, "-nostdlib", "-dynamic", "-pie", "-z", "relro",
                     "--rpath", str(td), "-o", exe, obj, library])
            image = exe.read_bytes()
            expect(struct.unpack_from("<H", image, 16)[0] == 3, "PIE is not ET_DYN")
            phoff = struct.unpack_from("<Q", image, 32)[0]
            entsize, count = struct.unpack_from("<HH", image, 54)
            headers = [struct.unpack_from("<IIQQQQQQ", image, phoff + i * entsize)
                       for i in range(count)]
            expect(all(any(h[0] == kind for h in headers) for kind in (2, 3, 6, 0x6474e552)),
                   "PIE program headers are incomplete")
            dynamic = next(h for h in headers if h[0] == 2)
            entries = dict(struct.unpack_from("<qQ", image, pos)
                           for pos in range(dynamic[2], dynamic[2] + dynamic[5], 16))
            expect(entries.get(0x6ffffffb, 0) & 0x08000000, "DF_1_PIE is missing")
            addresses = set()
            for _ in range(4):
                result = subprocess.run([str(exe)], env=env, capture_output=True, timeout=60)
                expect(result.returncode == 42 and len(result.stdout) == 8,
                       f"PIE relocation failed: {result.returncode} {result.stderr!r}")
                addresses.add(struct.unpack("<Q", result.stdout)[0])
            expect(len(addresses) > 1, "PIE address did not vary across runs")

        source = td / "main.bc"
        source.write_text("#include <errno.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <sys/stat.h>\n#include <dirent.h>\n#include <stdio.h>\n"
                          "int *other_errno(); int main() { errno = 0; "
                          "if (&errno != other_errno() || file_close(-1) != -1 || "
                          "errno != EBADF) return 1; return 42; }\n")
        module = td / "other.bc"
        module.write_text("extern int errno; int *other_errno() { return &errno; }\n")
        obj2, partial = td / "other.o", td / "partial.o"
        command([DRIVER, "-c", source, "-o", obj], env=env)
        command([DRIVER, "-c", module, "-o", obj2], env=env)
        command([linker, "-nostdlib", "-r", "-o", partial, obj, obj2])
        for flags, inputs in ((["-pie"], [source, module]),
                              (["--dynamic", "--pie", "-z", "relro"], [obj, obj2]),
                              (["-pie"], [partial])):
            command([DRIVER, *flags, *inputs, "-o", exe], env=env)
            result = command([exe], env=env, check=False)
            expect(result.returncode == 42, f"driver PIE failed for {flags}: {result.stderr}")
        conf = td / "crunch.conf"
        driver_env = dict(env, CRUNCH_CONF_FILE=str(conf))
        for tool in (("crunch",) if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1"
                     else ("crunch", "gnu")):
            conf.write_text(f"assembler = {tool}\nlinker = crunch\n")
            for fixture, args in (
                    ("units/expressions/power_runtime.bc", ()),
                    ("units/types/global_fixed_arrays.bc", ()),
                    ("units/function_calls/argv_runtime.bc", ("xy",))):
                command([DRIVER, "-pie", "-z", "relro", FIXTURES / fixture, "-o", exe],
                        env=driver_env)
                result = command([exe, *args], env=driver_env, check=False)
                expect(result.returncode == 42,
                       f"{tool} PIE runtime failed for {fixture}: {result.stderr}")
            command([DRIVER, "-pie", FIXTURES / "units/expressions/character_escapes.bc",
                     "-o", exe], env=driver_env)
            result = command([exe], env=driver_env, check=False)
            expect(result.returncode == 0 and result.stdout == "\n",
                   f"{tool} PIE standard streams failed: {result.stderr}")

        invalid = (
            (".data\nlocal: .quad 0\n.long local\n", "absolute relocation"),
            (".text\n.quad _start\n", "read-only"),
            (".text\nmov value(%rip),%eax\n", "undefined or preemptible"),
        )
        for text, diagnostic in invalid:
            command([assembler, "-o", obj], input=".text\n.globl _start\n_start: ret\n" + text)
            exe.write_text("preserved")
            result = command([linker, "-nostdlib", "-dynamic", "-pie", "-o", exe, obj, library], check=False)
            expect(result.returncode != 0 and diagnostic in result.stderr and exe.read_text() == "preserved",
                   f"unsafe PIE relocation accepted for {text!r}: {result.stderr}")
        absolute = td / "absolute.o"
        command([assembler, "-o", absolute], input=".globl fixed\n.set fixed,42\n")
        command([assembler, "-o", obj], input=
                ".data\nfixed_pointer: .quad fixed\n.text\n.globl _start\n_start:\n"
                "cmpq $42,fixed_pointer(%rip)\njne fail\nmov $42,%edi\n"
                "mov $60,%eax\nsyscall\nfail: mov $1,%edi\nmov $60,%eax\nsyscall\n")
        command([linker, "-nostdlib", "-dynamic", "-pie", "-o", exe, obj, absolute])
        expect(command([exe], env=env, check=False).returncode == 42,
               "absolute data symbol incorrectly received a PIE load bias")
        command([assembler, "-o", obj], input=
                ".text\n.globl _start\n_start: lea fixed(%rip),%rax\nret\n")
        exe.write_text("preserved")
        result = command([linker, "-nostdlib", "-dynamic", "-pie", "-o", exe, obj, absolute], check=False)
        expect(result.returncode != 0 and "absolute symbol" in result.stderr and
               exe.read_text() == "preserved", "absolute PC-relative PIE relocation accepted")
        command([assembler, "-o", obj], input=
                ".data\n.quad _end\n.text\n.globl _start\n_start: ret\n")
        result = command([linker, "-nostdlib", "-dynamic", "-pie", "-o", exe, obj], check=False)
        expect(result.returncode != 0 and "_end" in result.stderr and
               exe.read_text() == "preserved", "unsupported PIE linker symbol accepted")
        for flags, input_file, output in (
                (["--static", "-pie"], source, exe), (["-c", "-pie"], source, exe),
                (["-S", "-pie"], source, exe), (["--emit-ir", "-pie"], source, exe),
                (["-E", "-pie"], source, exe), (["--archive", "-pie"], obj, exe),
                (["-pie"], td / "input.s", td / "output.o")):
            if input_file.suffix == ".s":
                input_file.write_text(".text\n")
            output.write_text("preserved")
            result = command([DRIVER, *flags, input_file, "-o", output], env=env, check=False)
            expect(result.returncode != 0 and "-pie" in result.stderr and
                   output.read_text() == "preserved", f"invalid driver PIE mode accepted: {flags}")


def native_dynamic_init_case(pie=False):
    """Check dynamic executable constructors, process entry, and Crunch modules.

    Args:
        pie: Whether to link position-independent executables.
    Returns:
        None; raises AssertionError for incorrect constructor behavior or rejection.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-dynamic-init-") as directory:
        td = pathlib.Path(directory)
        pie_flags = ["-pie"] if pie else []
        assembler, linker = BUILD / "crunch-as", BUILD / "crunch-ld"
        provider, library = td / "provider.o", td / "provider.so"
        command([assembler, "-o", provider], input=
                ".text\ninitialize: mov order@GOTPCREL(%rip),%rax\nmovl $1,(%rax)\nret\n"
                ".globl external_init\n.type external_init,@function\nexternal_init:\n"
                "mov order@GOTPCREL(%rip),%rdx\nmov (%rdx),%eax\n"
                "imul $10,%eax,%eax\nadd $7,%eax\nmov %eax,(%rdx)\nret\n"
                '.section .init_array,"aw",@init_array\n.quad initialize\n')
        command([linker, "-nostdlib", "-shared", "-soname", "provider.so", "-o", library, provider])
        first, second, partial, exe = (td / name for name in
                                       ("first.o", "second.o", "partial.o", "program"))
        first_source = (
            ".data\n.globl order\norder: .long 0\nbad: .long 0\n"
            ".text\ninit_eight:\n"
            "mov %rsp,%rax\nand $15,%eax\ncmp $8,%eax\njne invalid\n"
            "cmp $3,%rdi\njne invalid\n"
            "mov 8(%rsi),%rax\ncmpb $65,(%rax)\njne invalid\n"
            "cmpq $0,24(%rsi)\njne invalid\n"
            "mov (%rdx),%rax\ncmpb $67,(%rax)\njne invalid\n"
            "movl order(%rip),%eax\nimul $10,%eax,%eax\nadd $8,%eax\n"
            "mov %eax,order(%rip)\nxor %edx,%edx\nret\n"
            "invalid: movl $1,bad(%rip)\nret\n"
            "init_four: movl order(%rip),%eax\nimul $10,%eax,%eax\n"
            "add $4,%eax\nmov %eax,order(%rip)\nret\n"
            ".globl _start,custom_entry\n_start:\ncustom_entry:\n"
            "test %rdx,%rdx\njz fail\n"
            "mov %rsp,%rax\nand $15,%eax\njne fail\n"
            "cmpq $3,(%rsp)\njne fail\nmov 16(%rsp),%rax\ncmpb $65,(%rax)\njne fail\n"
            "cmpl $0,bad(%rip)\njne fail\ncmpl $1782934,order(%rip)\njne fail\n"
            "mov $42,%edi\nmov $60,%eax\nsyscall\n"
            "fail: mov $1,%edi\nmov $60,%eax\nsyscall\n"
            '.section .init_array.101,"aw",@init_array\n.quad init_eight\n'
            '.section .init_array,"aw",@init_array\n.quad init_four\n'
        )
        second_source = (
            ".text\ninit_two: movl order(%rip),%eax\nimul $10,%eax,%eax\n"
            "add $2,%eax\nmov %eax,order(%rip)\nret\n"
            "init_nine: movl order(%rip),%eax\nimul $10,%eax,%eax\n"
            "add $9,%eax\nmov %eax,order(%rip)\nret\n"
            "init_three: movl order(%rip),%eax\nimul $10,%eax,%eax\n"
            "add $3,%eax\nmov %eax,order(%rip)\nret\n"
            '.section .init_array.100,"aw",@init_array\n.quad external_init\n'
            '.section .init_array.101,"aw",@init_array\n.quad init_two\n'
            '.section .init_array.200,"aw",@init_array\n.quad init_nine\n'
            '.section .init_array.65535,"aw",@init_array\n.quad init_three\n'
        )
        command([assembler, "-o", first], input=first_source)
        command([assembler, "-o", second], input=second_source)
        command([linker, "-nostdlib", "-r", "-o", partial, first, second])
        env = {"CTOR_TEST": "ok", "LD_LIBRARY_PATH": str(td)}
        for objects, options in (([first, second], []), ([partial], ["-s"]),
                                 ([first, second], ["-e", "custom_entry"])):
            command([linker, "-nostdlib", "-dynamic", *pie_flags, *options, "-o", exe, *objects, library])
            result = command([exe, "A", "B"], env=env, check=False)
            expect(result.returncode == 42,
                   f"constructor order, arguments or entry state failed: {result.returncode} {result.stderr}")
            image = exe.read_bytes()
            shoff = struct.unpack_from("<Q", image, 40)[0]
            entsize, count = struct.unpack_from("<HH", image, 58)
            headers = [struct.unpack_from("<IIQQQQIIQQ", image, shoff + i * entsize)
                       for i in range(count)]
            dynamic = next(h for h in headers if h[1] == 6)
            tags = dict(struct.unpack_from("<qQ", image, pos)
                        for pos in range(dynamic[4], dynamic[4] + dynamic[5], 16))
            init = next(h for h in headers if h[1] == 14)
            expect(tags.get(25) == init[3] and tags.get(27) == init[5] == 48,
                   f"incorrect executable constructor metadata: {tags}")

        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            command(["as", "-o", first, "-"], input=first_source)
            command(["as", "-o", second, "-"], input=second_source)
            command([linker, "-nostdlib", "-dynamic", *pie_flags, "-o", exe, first, second, library])
            expect(command([exe, "A", "B"], env=env, check=False).returncode == 42,
                   "GNU-assembled executable constructors failed")

        modules = ("legacy_init_first.bir", "legacy_init_second.bir", "legacy_init_main.bir")
        objects = []
        for index, fixture in enumerate(modules):
            asm, obj = td / f"module{index}.s", td / f"module{index}.o"
            asm.write_text(command([ASM, FIXTURES / "ir" / fixture]).stdout)
            command([assembler, "-o", obj, asm])
            objects.append(obj)
        command([linker, "-nostdlib", "-dynamic", *pie_flags, "-o", exe, *objects, BUILD / "libcrunch.so"])
        expect(command([exe], env={"LD_LIBRARY_PATH": str(BUILD)}, check=False).returncode == 42,
               "legacy IR module initializers were not run exactly once in order")
        argv_obj = td / "argv.o"
        command([DRIVER, "-c", FIXTURES / "units/function_calls/argv_runtime.bc", "-o", argv_obj])
        command([linker, "-nostdlib", "-dynamic", *pie_flags, "-o", exe, objects[0], argv_obj,
                 BUILD / "libcrunch-fallback.a", BUILD / "libcrunch.so"])
        expect(command([exe, "xy"], env={"LD_LIBRARY_PATH": str(BUILD)}, check=False).returncode == 42,
               "Crunch main did not receive its original arguments after initialization")

        invalid = (
            ('.section .init_array,"aw",@init_array\n.quad 0\n', "require relocations"),
            ('.section .init_array.65536,"aw",@init_array\n.quad target\n', "array priority"),
            ('.section .init_array,"a",@init_array\n.quad target\n', "array layout"),
            ('.section .init_array,"aw",@init_array\n.balign 16\n.quad target\n', "array layout"),
            ('.section .init_array,"aw",@progbits\n.quad target\n', "array section"),
        )
        for source, diagnostic in invalid:
            command([assembler, "-o", first], input=".text\n.globl _start\n_start: ret\ntarget: ret\n" + source)
            exe.write_text("preserved")
            result = command([linker, "-nostdlib", "-dynamic", "-o", exe, first], check=False)
            expect(result.returncode != 0 and diagnostic in result.stderr and exe.read_text() == "preserved",
                   f"invalid executable constructor accepted: {result.stderr}")


def native_dynamic_fini_case(pie=False):
    """Check managed executable finalization and both Crunch exit paths.

    Args:
        pie: Whether to link position-independent executables.
    Returns:
        None; raises AssertionError for incorrect finalization or rejection.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-dynamic-fini-") as directory:
        td = pathlib.Path(directory)
        pie_flags = ["-pie"] if pie else []
        assembler, linker = BUILD / "crunch-as", BUILD / "crunch-ld"
        provider, library = td / "provider.o", td / "provider.so"
        command([assembler, "-o", provider], input=
                ".text\n.globl external_fini\n.type external_fini,@function\n"
                "external_fini: mov $1,%eax\nmov $1,%edi\nlea letter_g(%rip),%rsi\n"
                "mov $1,%edx\nsyscall\nret\n"
                "library_fini: mov $1,%eax\nmov $1,%edi\nlea letter_s(%rip),%rsi\n"
                "mov $1,%edx\nsyscall\nret\n"
                '.section .rodata\nletter_g: .byte 71\nletter_s: .byte 83\n'
                '.section .fini_array,"aw",@fini_array\n.quad library_fini\n')
        command([linker, "-nostdlib", "-shared", "-soname", "provider.so", "-o", library, provider])
        first, second, partial, exe = (td / name for name in
                                       ("first.o", "second.o", "partial.o", "program"))
        first_source = (
            ".text\nfini_a: sub $8,%rsp\ncall __crunch_run_finalizers\nadd $8,%rsp\n"
            "mov %rsp,%rax\nand $15,%eax\ncmp $8,%eax\njne bad_alignment\n"
            "mov $1,%eax\nmov $1,%edi\nlea letter_a(%rip),%rsi\n"
            "mov $1,%edx\nsyscall\nret\n"
            "bad_alignment: mov $1,%eax\nmov $1,%edi\nlea letter_x(%rip),%rsi\n"
            "mov $1,%edx\nsyscall\nret\n"
            "fini_e: mov $1,%eax\nmov $1,%edi\nlea letter_e(%rip),%rsi\n"
            "mov $1,%edx\nsyscall\nret\n"
            '.section .rodata\nletter_a: .byte 65\nletter_e: .byte 69\nletter_x: .byte 88\n'
            '.section .fini_array.101,"aw",@fini_array\n.quad fini_a\n'
            '.section .fini_array,"aw",@fini_array\n.quad fini_e\n'
        )
        second_source = (
            ".text\nfini_b: mov $1,%eax\nmov $1,%edi\nlea letter_b(%rip),%rsi\n"
            "mov $1,%edx\nsyscall\nret\n"
            "fini_c: mov $1,%eax\nmov $1,%edi\nlea letter_c(%rip),%rsi\n"
            "mov $1,%edx\nsyscall\nret\n"
            "fini_d: mov $1,%eax\nmov $1,%edi\nlea letter_d(%rip),%rsi\n"
            "mov $1,%edx\nsyscall\nret\n"
            '.section .rodata\nletter_b: .byte 66\nletter_c: .byte 67\nletter_d: .byte 68\n'
            '.section .fini_array.100,"aw",@fini_array\n.quad external_fini\n'
            '.section .fini_array.101,"aw",@fini_array\n.quad fini_b\n'
            '.section .fini_array.200,"aw",@fini_array\n.quad fini_c\n'
            '.section .fini_array.65535,"aw",@fini_array\n.quad fini_d\n'
        )
        command([assembler, "-o", first], input=first_source)
        command([assembler, "-o", second], input=second_source)
        command([linker, "-nostdlib", "-r", "-o", partial, first, second])
        main, main_obj = td / "main.bc", td / "main.o"
        main.write_text("int main() { return 42; }\n")
        command([DRIVER, "-c", main, "-o", main_obj])
        env = {"LD_LIBRARY_PATH": f"{td}:{BUILD}"}
        for objects, options in (([first, second], []), ([partial], ["-s"])):
            command([linker, "-nostdlib", "-dynamic", *pie_flags, *options, "-o", exe, main_obj, *objects,
                     library, BUILD / "libcrunch.so"])
            result = command([exe], env=env, check=False)
            expect(result.returncode == 42 and result.stdout == "EDCBAG",
                   f"main-return finalization failed: {result.returncode} {result.stdout!r} {result.stderr}")
            image = exe.read_bytes()
            shoff = struct.unpack_from("<Q", image, 40)[0]
            entsize, count = struct.unpack_from("<HH", image, 58)
            headers = [struct.unpack_from("<IIQQQQIIQQ", image, shoff + i * entsize)
                       for i in range(count)]
            dynamic = next(h for h in headers if h[1] == 6)
            tags = dict(struct.unpack_from("<qQ", image, pos)
                        for pos in range(dynamic[4], dynamic[4] + dynamic[5], 16))
            fini = next(h for h in headers if h[1] == 15)
            expect(tags.get(26) == fini[3] and tags.get(28) == fini[5] == 48,
                   f"incorrect executable finalization metadata: {tags}")

        main.write_text("#include <stdlib.h>\nint main() { exit(37); return 1; }\n")
        command([DRIVER, "-c", main, "-o", main_obj])
        for runtime in (BUILD / "libcrunch.so", BUILD / "libcrunch.a"):
            fallback = [BUILD / "libcrunch-fallback.a"] if runtime.suffix == ".so" else []
            command([linker, "-nostdlib", "-dynamic", *pie_flags, "-o", exe, main_obj, first, second,
                     library, *fallback, runtime])
            result = command([exe], env=env, check=False)
            expect(result.returncode == 37 and result.stdout == "EDCBAG",
                   f"exit() finalization failed with {runtime}: {result.returncode} {result.stdout!r}")
        command([linker, "-nostdlib", "-pie", "-nostdlib", "-o", exe, main_obj, BUILD / "libcrunch.a"])
        expect(command([exe], check=False).returncode == 37,
               "undefined finalizer hook broke existing native PIE exit")
        init_obj = td / "init.o"
        command([assembler, "-o", init_obj], input=
                ".text\ninitialize: mov $1,%eax\nmov $1,%edi\nlea letter(%rip),%rsi\n"
                "mov $1,%edx\nsyscall\nret\n"
                '.section .rodata\nletter: .byte 73\n'
                '.section .init_array,"aw",@init_array\n.quad initialize\n')
        command([linker, "-nostdlib", "-dynamic", *pie_flags, "-o", exe, main_obj, first, second, init_obj,
                 library, BUILD / "libcrunch-fallback.a", BUILD / "libcrunch.so"])
        result = command([exe], env=env, check=False)
        expect(result.returncode == 37 and result.stdout == "IEDCBAG",
               "combined executable initialization and finalization failed")

        entry = td / "entry.o"
        command([assembler, "-o", entry], input=
                ".text\n.globl _start\n_start: and $-16,%rsp\n"
                "call __crunch_run_finalizers\ncall __crunch_run_finalizers\n"
                "mov $44,%edi\ncall __crunch_end@PLT\n")
        command([linker, "-nostdlib", "-dynamic", *pie_flags, "-o", exe, entry, first, second,
                 library, BUILD / "libcrunch.so"])
        result = command([exe], env=env, check=False)
        expect(result.returncode == 44 and result.stdout == "EDCBAG",
               f"custom or repeated finalization failed: {result.returncode} {result.stdout!r}")
        command([linker, "-nostdlib", "-dynamic", *pie_flags, "-o", exe, entry, BUILD / "libcrunch.so"])
        result = command([exe], env=env, check=False)
        expect(result.returncode == 44 and not result.stdout,
               "empty executable finalization helper failed")

        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            command(["as", "-o", first, "-"], input=first_source)
            command(["as", "-o", second, "-"], input=second_source)
            command([linker, "-nostdlib", "-dynamic", *pie_flags, "-o", exe, main_obj, first, second, library,
                     BUILD / "libcrunch-fallback.a", BUILD / "libcrunch.so"])
            result = command([exe], env=env, check=False)
            expect(result.returncode == 37 and result.stdout == "EDCBAG",
                   "GNU-assembled executable finalizers failed")

        invalid = (
            ('.section .fini_array,"aw",@fini_array\n.quad 0\n', "require relocations"),
            ('.section .fini_array.65536,"aw",@fini_array\n.quad target\n', "array priority"),
            ('.section .fini_array,"a",@fini_array\n.quad target\n', "array layout"),
            ('.section .fini_array,"w",@fini_array\n.quad target\n', "not allocated"),
            ('.section .fini_array,"aw",@fini_array\n.balign 16\n.quad target\n', "array layout"),
            ('.section .fini_array,"aw",@fini_array\n.long target\n.long target\n', "array relocation"),
            ('.section .fini_array,"aw",@progbits\n.quad target\n', "array section"),
            ('.text\n.globl __crunch_run_finalizers\n__crunch_run_finalizers: ret\n',
             "reserved executable symbol"),
            ('.weak __crunch_run_finalizers\n.hidden __crunch_run_finalizers\n'
             '.data\n.quad __crunch_run_finalizers\n',
             "reserved executable symbol"),
        )
        for source, diagnostic in invalid:
            command([assembler, "-o", first], input=".text\n.globl _start\n_start: ret\ntarget: ret\n" + source)
            exe.write_text("preserved")
            result = command([linker, "-nostdlib", "-dynamic", "-o", exe, first], check=False)
            expect(result.returncode != 0 and diagnostic in result.stderr and exe.read_text() == "preserved",
                   f"invalid executable finalizer accepted: {result.stderr}")


def native_cet_property_case():
    """Check CET property handling and explicit protection downgrade diagnostics.

    Returns:
        None; raises AssertionError for incorrect linking or rejection.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-cet-note-") as directory:
        td = pathlib.Path(directory)
        obj, shared, executable = td / "input.o", td / "output.so", td / "program"
        linker, assembler = BUILD / "crunch-ld", BUILD / "crunch-as"
        code = ('.text\n.globl _start\n_start: mov $60,%rax\nxor %rdi,%rdi\nsyscall\n'
                '.globl answer\nanswer: mov $42,%eax\nret\n'
                '.section .note.gnu.property,"a",@note\n.p2align 3\n'
                '.long 4,16,5\n.asciz "GNU"\n.long 0xc0000002,4,3,0\n')
        command([assembler, "-o", obj], input=code)
        for mode, output in (("-shared", shared), ("-dynamic", executable)):
            result = command([linker, "-nostdlib", mode, "-o", output, obj])
            expect("discarding GNU CET properties" in result.stderr and
                   "does not retain IBT or SHSTK" in result.stderr,
                   f"CET protection downgrade was not reported: {result.stderr}")
            expect(b".note.gnu.property\0" not in output.read_bytes(),
                   "output incorrectly advertises CET protection")
        loader = 'import ctypes,sys; assert ctypes.CDLL(sys.argv[1]).answer() == 42'
        command([PYTHON, "-c", loader, shared])
        expect(command([executable], check=False).returncode == 0,
               "dynamic executable containing CET-marked code failed")

        combined = td / "combined.o"
        command([linker, "-nostdlib", "-r", "-o", combined, obj])
        expect(b".note.gnu.property\0" in combined.read_bytes(),
               "relocatable link lost GNU property note")
        result = command([linker, "-nostdlib", "-shared", "-o", shared, combined])
        expect("discarding GNU CET properties" in result.stderr,
               "relocatable output did not retain CET properties")

        original = obj.read_bytes()
        note = struct.pack("<IIIIIIII", 4, 16, 5, 0x00554e47,
                           0xc0000002, 4, 3, 0)
        offset = original.find(note)
        expect(offset >= 0, "test object lacks the expected property note")
        for name, word, value in (("unknown-property", 4, 0xc0008002),
                                  ("unknown-feature", 6, 4),
                                  ("bad-size", 5, 8),
                                  ("bad-padding", 7, 1)):
            bad = bytearray(original)
            struct.pack_into("<I", bad, offset + word * 4, value)
            obj.write_bytes(bad)
            shared.write_text("preserved")
            result = command([linker, "-nostdlib", "-shared", "-o", shared, obj],
                             check=False)
            expect(result.returncode != 0 and "unsupported GNU property note" in result.stderr
                   and shared.read_text() == "preserved",
                   f"linker failed to reject {name}: {result.stderr}")
        for name, bad_code in (
                ("exported", code + ".globl note_export\nnote_export:\n"),
                ("reference", code + ".text\n.quad 1f\n"
                 '.section .note.gnu.property,"a",@note\n1:\n'),
                ("relocation", code + ".quad answer\n")):
            command([assembler, "-o", obj], input=bad_code)
            shared.write_text("preserved")
            result = command([linker, "-nostdlib", "-shared", "-o", shared, obj],
                             check=False)
            expect(result.returncode != 0 and "GNU property note" in result.stderr
                   and shared.read_text() == "preserved",
                   f"linker accepted {name} property note: {result.stderr}")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            source = td / "gcc.c"
            source.write_text("int answer(void) { return 42; }\n")
            command(["gcc", "-c", "-fPIC", "-fcf-protection=full",
                     "-fno-asynchronous-unwind-tables", source, "-o", obj])
            result = command([linker, "-nostdlib", "-shared", "-o", shared, obj])
            expect("discarding GNU CET properties" in result.stderr,
                   "GCC CET note was not handled")
            command([PYTHON, "-c", loader, shared])


def native_shared_linker_case():
    """Load native shared objects and reject unsupported dynamic requirements.

    Returns:
        None; raises AssertionError for incorrect loading, exports, or rejection.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-shared-") as directory:
        td = pathlib.Path(directory)
        assembler, linker = BUILD / "crunch-as", BUILD / "crunch-ld"
        objects = []
        for name, source in (
                ("answer", ".text\n.globl answer\n.type answer,@function\n"
                 ".hidden secret\n.protected two\nanswer:\ncall two\n"
                 "addl secret(%rip),%eax\nret\n"),
                ("values", ".data\n.globl secret\n.hidden secret\nsecret: .long 40\n"
                 ".globl exported_value\n.type exported_value,@object\n"
                 ".size exported_value,4\nexported_value: .long 7\n"
                 ".comm zero_value,4,4\n.text\n.globl two\n.protected two\n"
                 ".type two,@function\ntwo: movl $2,%eax\nret\n"
                 ".weak weak_answer\n.type weak_answer,@function\n"
                 "weak_answer: movl $17,%eax\nret\n")):
            obj = td / f"{name}.o"
            command([assembler, "-o", obj], input=source)
            objects.append(obj)
        library = td / "libanswer.so"
        loader = r"""
import ctypes, sys
library = ctypes.CDLL(sys.argv[1], mode=ctypes.RTLD_LOCAL)
assert library.answer() == 42
assert library.two() == 2
assert library.weak_answer() == 17
value = ctypes.c_int.in_dll(library, "exported_value")
assert value.value == 7
value.value = 19
assert ctypes.c_int.in_dll(library, "exported_value").value == 19
assert ctypes.c_int.in_dll(library, "zero_value").value == 0
try:
    ctypes.c_int.in_dll(library, "secret")
except ValueError:
    pass
else:
    raise AssertionError("hidden symbol was exported")
"""
        env = {key: value for key, value in os.environ.items()
               if key not in ("LD_PRELOAD", "LD_LIBRARY_PATH", "LD_AUDIT")}
        archive = td / "libvalues.a"
        command([BUILD / "crunch-ar", "rcs", archive, objects[1]])
        for flags, inputs in (([], objects), (["-s"], objects), ([], [objects[0], archive])):
            command([linker, "-nostdlib", "-shared", *flags, "-o", library, *inputs])
            image = library.read_bytes()
            expect(image[:5] == b"\x7fELF\x02" and struct.unpack_from("<H", image, 16)[0] == 3,
                   "shared output is not ELF64 ET_DYN")
            command([PYTHON, "-c", loader, library], env=env)
        override_object, override_library = td / "override.o", td / "override.so"
        command([assembler, "-o", override_object],
                input=".text\n.globl two\n.type two,@function\ntwo: movl $99,%eax\nret\n")
        command([linker, "-nostdlib", "-shared", "-o", override_library, override_object])
        command([PYTHON, "-c", loader, library],
                env=dict(env, LD_PRELOAD=str(override_library)))
        bad_cases = (
            ("undefined", ".text\n.globl f\nf: movl missing(%rip),%eax\nret\n", "undefined or preemptible"),
            ("preemptible", ".data\n.globl value\nvalue: .long 1\n.text\n.globl f\n"
             "f: movl value(%rip),%eax\nret\n", "undefined or preemptible"),
            ("absolute", ".text\n.globl f\nf: movq $missing,%rax\nret\n", "dynamic relocation"),
            ("plt_addend", ".text\n.globl f\nf: call missing+1@PLT\nret\n", "PLT relocation addend"),
            ("versioned", ".text\n.globl implementation\nimplementation: ret\n"
             ".symver implementation,versioned@V1\n", "symbol versioning"),
            ("tls", '.section .tdata,"awT",@progbits\n.long 1\n', "unsupported allocated section"),
            ("unwind", '.section .eh_frame,"a",@progbits\n.long 0\n', "unsupported allocated section"),
            ("execstack", '.section .note.GNU-stack,"x",@progbits\n', "executable stack"),
        )
        for name, source, diagnostic in bad_cases:
            obj = td / f"{name}.o"
            command([assembler, "-o", obj], input=source)
            library.write_text("preserved")
            result = command([linker, "-nostdlib", "-shared", "-o", library, obj], check=False)
            expect(result.returncode != 0 and diagnostic in result.stderr and
                   library.read_text() == "preserved",
                   f"shared linker did not reject {name} safely: {result.stderr}")
        malformed = bytearray(objects[0].read_bytes())
        shoff = struct.unpack_from("<Q", malformed, 40)[0]
        shentsize, shnum = struct.unpack_from("<HH", malformed, 58)
        rela = next(shoff + i * shentsize for i in range(shnum)
                    if struct.unpack_from("<I", malformed, shoff + i * shentsize + 4)[0] == 4)
        struct.pack_into("<I", malformed, rela + 40, 0)
        bad_object = td / "bad-relocations.o"
        bad_object.write_bytes(malformed)
        result = command([linker, "-nostdlib", "-shared", "-o", library, bad_object], check=False)
        expect(result.returncode != 0 and "invalid shared relocation section" in result.stderr and
               library.read_text() == "preserved", "malformed relocations were not rejected safely")
        result = command([linker, "-nostdlib", "-shared", "-r", "-o", library, *objects], check=False)
        expect(result.returncode != 0 and result.stderr and library.read_text() == "preserved",
               "shared linker accepted incompatible relocatable output")

def native_shared_dynamic_case():
    """Exercise loader-resolved GOT and eager PLT entries and interposition.

    Returns:
        None; raises AssertionError for incorrect relocations or symbol binding.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-shared-dynamic-") as directory:
        td = pathlib.Path(directory)
        assembler, linker = BUILD / "crunch-as", BUILD / "crunch-ld"
        consumer = (
            ".data\n.globl shared_data\n.type shared_data,@object\nshared_data: .long 5\n"
            ".hidden hidden_data\n.globl hidden_data\nhidden_data: .long 7\n"
            "local_data: .long 1\n"
            ".text\n.globl target\n.type target,@function\ntarget: movl $10,%eax\nret\n"
            ".weak absent_weak\n"
            ".globl calculate\n.type calculate,@function\ncalculate:\npushq %rbx\n"
            "movq shared_data@GOTPCREL(%rip),%rax\nmovl (%rax),%ebx\n"
            "movq hidden_data@GOTPCREL(%rip),%rax\naddl (%rax),%ebx\n"
            "movq local_data@GOTPCREL(%rip),%rax\naddl (%rax),%ebx\n"
            "movq external_data@GOTPCREL(%rip),%rax\naddl (%rax),%ebx\n"
            "call target@PLT\naddl %eax,%ebx\n"
            "call external_function@PLT\naddl %ebx,%eax\npopq %rbx\nret\n"
            ".globl weak_is_null\nweak_is_null:\n"
            "movq absent_weak@GOTPCREL(%rip),%rax\ntestq %rax,%rax\nsete %al\n"
            "movzbl %al,%eax\nret\n"
            ".globl set_data\nset_data:\nmovq shared_data@GOTPCREL(%rip),%rax\n"
            "movl %edi,(%rax)\nret\n"
            '.section .note.GNU-stack,"",@progbits\n'
        )
        provider = (
            ".data\n.globl external_data\n.type external_data,@object\n"
            "external_data: .long 3\n"
            ".text\n.globl external_function\n.type external_function,@function\n"
            "external_function: movl $16,%eax\nret\n"
        )
        override = (
            ".data\n.globl shared_data\n.type shared_data,@object\nshared_data: .long 20\n"
            ".text\n.globl target\n.type target,@function\ntarget: movl $30,%eax\nret\n"
        )
        for name, source in (("consumer", consumer), ("provider", provider), ("override", override)):
            obj, so = td / f"{name}.o", td / f"{name}.so"
            command([assembler, "-o", obj], input=source)
            command([linker, "-nostdlib", "-shared", "-o", so, obj])
        image = (td / "consumer.so").read_bytes()
        shoff = struct.unpack_from("<Q", image, 40)[0]
        entsize, count, names_index = struct.unpack_from("<HHH", image, 58)
        headers = [struct.unpack_from("<IIQQQQIIQQ", image, shoff + i * entsize)
                   for i in range(count)]
        names = headers[names_index]
        section_names = image[names[4]:names[4] + names[5]]
        sections = {}
        for header in headers:
            start = header[0]
            end = section_names.index(b"\0", start)
            sections[section_names[start:end].decode()] = header
        expect(".rela.dyn" in sections and ".plt" in sections,
               "dynamic relocation and PLT sections were not emitted")
        rela = sections[".rela.dyn"]
        entries = [struct.unpack_from("<QQq", image, pos)
                   for pos in range(rela[4], rela[4] + rela[5], 24)]
        expect(sum((info & 0xffffffff) == 6 for _, info, _ in entries) == 5 and
               sum((info & 0xffffffff) == 8 for _, info, _ in entries) == 2,
               f"unexpected dynamic relocations: {entries}")
        loader = r"""
import ctypes, sys
ctypes.CDLL(sys.argv[1], mode=ctypes.RTLD_GLOBAL)
library = ctypes.CDLL(sys.argv[2], mode=ctypes.RTLD_LOCAL)
assert library.calculate() == int(sys.argv[3])
assert library.weak_is_null() == 1
library.set_data(9)
assert library.calculate() == int(sys.argv[4])
"""
        env = {key: value for key, value in os.environ.items()
               if key not in ("LD_PRELOAD", "LD_LIBRARY_PATH", "LD_AUDIT")}
        for preload, before, after in ((False, 42, 46), (True, 77, 66)):
            runenv = dict(env)
            if preload:
                runenv["LD_PRELOAD"] = str(td / "override.so")
            command([PYTHON, "-c", loader, td / "provider.so", td / "consumer.so", before, after],
                    env=runenv)
        failure = command([PYTHON, "-c", "import ctypes,sys; ctypes.CDLL(sys.argv[1])",
                           td / "consumer.so"], env=env, check=False)
        expect(failure.returncode != 0 and "undefined symbol" in failure.stderr,
               f"missing strong dynamic symbols did not fail loading: {failure.stderr}")
        failure = command([PYTHON, "-c",
                           "import _ctypes,os,sys; _ctypes.dlopen(sys.argv[1], os.RTLD_LAZY)",
                           td / "consumer.so"], env=env, check=False)
        expect(failure.returncode != 0 and "undefined symbol" in failure.stderr,
               f"lazy mode unexpectedly deferred a required symbol: {failure.stderr}")

def native_shared_data_relocation_case():
    """Check loader relocations for initialized shared-object data pointers.

    Returns:
        None; raises AssertionError for incorrect binding or unsafe rejection.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-shared-data-") as directory:
        td = pathlib.Path(directory)
        assembler, linker = BUILD / "crunch-as", BUILD / "crunch-ld"
        sources = {
            "consumer": (
                ".data\nlocal_first: .long 11\nlocal_second: .long 12\n"
                ".globl hidden_value\n.hidden hidden_value\nhidden_value: .long 13\n"
                ".globl protected_value\n.protected protected_value\nprotected_value: .long 14\n"
                ".globl public_value\npublic_value: .long 15\n"
                ".weak absent_weak\n"
                ".globl local_ptr\nlocal_ptr: .quad local_second-4\n"
                ".globl hidden_ptr\nhidden_ptr: .quad hidden_value\n"
                ".globl protected_ptr\nprotected_ptr: .quad protected_value\n"
                ".globl public_ptr\npublic_ptr: .quad public_value\n"
                ".globl external_ptr\nexternal_ptr: .quad external_array+4\n"
                ".globl function_ptr\nfunction_ptr: .quad external_function\n"
                ".globl weak_ptr\nweak_ptr: .quad absent_weak\n"
                ".globl weak_addend_ptr\nweak_addend_ptr: .quad absent_weak+4\n"
            ),
            "provider": (
                ".data\n.globl external_array\nexternal_array: .long 20,22\n"
                ".text\n.globl external_function\n.type external_function,@function\n"
                "external_function: movl $42,%eax\nret\n"
            ),
            "override": (
                ".data\n.globl external_array\nexternal_array: .long 30,32\n"
                ".globl public_value\npublic_value: .long 35\n"
                ".globl protected_value\nprotected_value: .long 99\n"
                ".globl absent_weak\nabsent_weak: .long 77\n"
            ),
        }
        for name, source in sources.items():
            command([assembler, "-o", td / f"{name}.o"], input=source)
        command([linker, "-nostdlib", "-shared", "-soname", "provider.so", "-o", td / "provider.so",
                 td / "provider.o"])
        command([linker, "-nostdlib", "-shared", "-o", td / "override.so", td / "override.o"])
        output = td / "consumer.so"
        command([linker, "-nostdlib", "-shared", "-o", output, td / "consumer.o", td / "provider.so"])
        image = output.read_bytes()
        shoff = struct.unpack_from("<Q", image, 40)[0]
        entsize, count = struct.unpack_from("<HH", image, 58)
        headers = [struct.unpack_from("<IIQQQQIIQQ", image, shoff + i * entsize)
                   for i in range(count)]
        rela = next(h for h in headers if h[1] == 4)
        entries = [struct.unpack_from("<QQq", image, pos)
                   for pos in range(rela[4], rela[4] + rela[5], 24)]
        expect(sum((info & 0xffffffff) == 8 for _, info, _ in entries) == 3 and
               sum((info & 0xffffffff) == 1 for _, info, _ in entries) == 5,
               f"incorrect pointer relocations: {entries}")
        loader = r"""
import ctypes, sys
library = ctypes.CDLL(sys.argv[1])
def pointer(name):
    return ctypes.c_void_p.in_dll(library, name).value
def value(name):
    return ctypes.c_int.from_address(pointer(name)).value
assert value("local_ptr") == 11
assert value("hidden_ptr") == 13
assert value("protected_ptr") == 14
assert value("public_ptr") == int(sys.argv[2])
assert value("external_ptr") == int(sys.argv[3])
assert ctypes.CFUNCTYPE(ctypes.c_int)(pointer("function_ptr"))() == 42
weak = pointer("weak_ptr")
assert (ctypes.c_int.from_address(weak).value if weak else 0) == int(sys.argv[4])
assert pointer("weak_addend_ptr") == (weak or 0) + 4
"""
        env = {key: value for key, value in os.environ.items()
               if key not in ("LD_PRELOAD", "LD_LIBRARY_PATH", "LD_AUDIT")}
        env["LD_LIBRARY_PATH"] = str(td)
        command([PYTHON, "-c", loader, output, 15, 22, 0], env=env)
        command([PYTHON, "-c", loader, output, 35, 32, 77],
                env=dict(env, LD_PRELOAD=str(td / "override.so")))
        command([assembler, "-o", td / "mixed.o"], input=sources["consumer"] +
                ".text\n.globl read_external\nread_external:\n"
                "movq external_array@GOTPCREL(%rip),%rax\nmovl 4(%rax),%eax\nret\n")
        command([linker, "-nostdlib", "-shared", "-o", output, td / "mixed.o", td / "provider.so"])
        command([PYTHON, "-c", loader + "\nassert library.read_external() == 22\n",
                 output, 15, 22, 0], env=env)
        command([linker, "-nostdlib", "-r", "-o", td / "partial.o", td / "consumer.o"])
        command([linker, "-nostdlib", "-shared", "-o", output, td / "partial.o", td / "provider.so"])
        command([PYTHON, "-c", loader, output, 15, 22, 0], env=env)
        command([linker, "-nostdlib", "-shared", "-o", output, td / "consumer.o"])
        failure = command([PYTHON, "-c", "import ctypes,sys; ctypes.CDLL(sys.argv[1])",
                           output], env=env, check=False)
        expect(failure.returncode != 0 and "undefined symbol" in failure.stderr,
               f"missing strong pointer target was not reported: {failure.stderr}")

        for name, source, diagnostic in (
                ("readonly", '.section .rodata,"a",@progbits\n.quad missing\n', "read-only"),
                ("text", ".text\n.quad missing\n", "read-only"),
                ("narrow", ".data\n.long missing\n", "dynamic relocation"),
                ("hidden", ".data\n.hidden missing\n.quad missing\n", "unsupported shared relocation"),
                ("linker", ".data\n.quad _end\n", "linker-defined symbol")):
            obj = td / f"{name}.o"
            command([assembler, "-o", obj], input=source)
            output.write_text("preserved")
            result = command([linker, "-nostdlib", "-shared", "-o", output, obj], check=False)
            expect(result.returncode != 0 and diagnostic in result.stderr and
                   output.read_text() == "preserved",
                   f"shared linker did not reject {name} safely: {result.stderr}")

        malformed = bytearray((td / "consumer.o").read_bytes())
        shoff = struct.unpack_from("<Q", malformed, 40)[0]
        entsize, count = struct.unpack_from("<HH", malformed, 58)
        headers = [struct.unpack_from("<IIQQQQIIQQ", malformed, shoff + i * entsize)
                   for i in range(count)]
        rela = next(h for h in headers if h[1] == 4)
        struct.pack_into("<Q", malformed, rela[4], headers[rela[7]][5] - 4)
        bad = td / "bad.o"
        bad.write_bytes(malformed)
        result = command([linker, "-nostdlib", "-shared", "-o", output, bad], check=False)
        expect(result.returncode != 0 and "relocation offset out of range" in result.stderr and
               output.read_text() == "preserved", f"bad pointer offset was accepted: {result.stderr}")

def native_shared_array_case(linker=None):
    """Check shared constructors and destructors, ordering, and rejection.

    Args:
        linker: Linker to test, or None for the host-built linker.
    Returns:
        None; raises AssertionError for incorrect loader behavior or invalid inputs.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-shared-arrays-") as directory:
        td = pathlib.Path(directory)
        assembler, linker = BUILD / "crunch-as", linker or BUILD / "crunch-ld"
        provider = (
            ".data\n.hidden log_value\nlog_value: .long 0\n"
            ".text\n.globl record\n.type record,@function\nrecord:\n"
            "movl log_value(%rip),%eax\nimull $10,%eax,%eax\n"
            "addl %edi,%eax\nmovl %eax,log_value(%rip)\nret\n"
            ".globl get_log\nget_log: movl log_value(%rip),%eax\nret\n"
            ".globl external_init\nexternal_init: movl $7,log_value(%rip)\nret\n"
        )
        first = (
            ".text\ninit_two: subq $8,%rsp\nmovl $2,%edi\ncall record@PLT\naddq $8,%rsp\nret\n"
            "init_three: subq $8,%rsp\nmovl $3,%edi\ncall record@PLT\naddq $8,%rsp\nret\n"
            "init_eight: subq $8,%rsp\nmovl $8,%edi\ncall record@PLT\naddq $8,%rsp\nret\n"
            "fini_four: subq $8,%rsp\nmovl $4,%edi\ncall record@PLT\naddq $8,%rsp\nret\n"
            "fini_five: subq $8,%rsp\nmovl $5,%edi\ncall record@PLT\naddq $8,%rsp\nret\n"
            '.section .init_array,"aw",@init_array\n.quad init_three\n'
            '.section .init_array.200,"aw",@init_array\n.quad init_two\n'
            '.section .init_array.101,"aw",@init_array\n.quad init_eight\n'
            '.section .fini_array.200,"aw",@fini_array\n.quad fini_five\n'
            '.section .fini_array,"aw",@fini_array\n.quad fini_four\n'
        )
        second = (
            ".text\ninit_one: subq $8,%rsp\nmovl $1,%edi\ncall record@PLT\naddq $8,%rsp\nret\n"
            "init_nine: subq $8,%rsp\nmovl $9,%edi\ncall record@PLT\naddq $8,%rsp\nret\n"
            "fini_six: subq $8,%rsp\nmovl $6,%edi\ncall record@PLT\naddq $8,%rsp\nret\n"
            '.section .init_array.101,"aw",@init_array\n.quad init_one\n'
            '.section .init_array.100,"aw",@init_array\n.quad external_init\n'
            '.section .init_array.65535,"aw",@init_array\n.quad init_nine\n'
            '.section .init_array.300,"aw",@init_array\n.globl init_marker\ninit_marker:\n'
            '.section .fini_array.101,"aw",@fini_array\n.quad fini_six\n'
        )
        for name, source in (("provider", provider), ("first", first), ("second", second)):
            command([assembler, "-o", td / f"{name}.o"], input=source)
        command([linker, "-nostdlib", "-shared", "-soname", "provider.so", "-o", td / "provider.so",
                 td / "provider.o"])
        output = td / "consumer.so"
        loader = r"""
import _ctypes, ctypes, sys
provider = ctypes.CDLL(sys.argv[1], mode=ctypes.RTLD_GLOBAL)
first = ctypes.CDLL(sys.argv[2])
second = ctypes.CDLL(sys.argv[2])
assert first._handle == second._handle
assert provider.get_log() == 781293
_ctypes.dlclose(first._handle)
assert provider.get_log() == 781293
_ctypes.dlclose(second._handle)
assert provider.get_log() == 781293456
"""
        env = {key: value for key, value in os.environ.items()
               if key not in ("LD_PRELOAD", "LD_LIBRARY_PATH", "LD_AUDIT")}
        env["LD_LIBRARY_PATH"] = str(td)
        command([linker, "-nostdlib", "-r", "-o", td / "partial.o", td / "first.o", td / "second.o"])
        for objects in ([td / "first.o", td / "second.o"], [td / "partial.o"]):
            command([linker, "-nostdlib", "-shared", "-o", output, *objects, td / "provider.so"])
            image = output.read_bytes()
            shoff = struct.unpack_from("<Q", image, 40)[0]
            entsize, count = struct.unpack_from("<HH", image, 58)
            headers = [struct.unpack_from("<IIQQQQIIQQ", image, shoff + i * entsize)
                       for i in range(count)]
            dynamic = next(h for h in headers if h[1] == 6)
            tags = {}
            for pos in range(dynamic[4], dynamic[4] + dynamic[5], 16):
                tag, value = struct.unpack_from("<qQ", image, pos)
                if tag == 0:
                    break
                tags[tag] = value
            init = next(h for h in headers if h[1] == 14)
            fini = next(h for h in headers if h[1] == 15)
            expect(tags.get(25) == init[3] and tags.get(27) == init[5] == 48 and
                   tags.get(26) == fini[3] and tags.get(28) == fini[5] == 24,
                   f"incorrect initialization or finalization dynamic tags: {tags}")
            dynsym = next(h for h in headers if h[1] == 11)
            strings = headers[dynsym[6]]
            names = image[strings[4]:strings[4] + strings[5]]
            symbols = [struct.unpack_from("<IBBHQQ", image, pos)
                       for pos in range(dynsym[4], dynsym[4] + dynsym[5], dynsym[9])]
            marker = next(s for s in symbols
                          if names[s[0]:names.index(b"\0", s[0])] == b"init_marker")
            expect(marker[4] == init[3] + 32, "empty array symbol has incorrect sorted offset")
            command([PYTHON, "-c", loader, td / "provider.so", output], env=env)

        for section, before in (("init_array", 9), ("fini_array", 0)):
            source = (".text\ncallback: subq $8,%rsp\nmovl $9,%edi\ncall record@PLT\n"
                      "addq $8,%rsp\nret\n" +
                      f'.section .{section},"aw",@{section}\n.quad callback\n')
            command([assembler, "-o", td / "single.o"], input=source)
            command([linker, "-nostdlib", "-shared", "-o", output, td / "single.o", td / "provider.so"])
            script = ("import _ctypes,ctypes,sys; p=ctypes.CDLL(sys.argv[1],mode=ctypes.RTLD_GLOBAL); "
                      "l=ctypes.CDLL(sys.argv[2]); assert p.get_log()==int(sys.argv[3]); "
                      "_ctypes.dlclose(l._handle); assert p.get_log()==9")
            command([PYTHON, "-c", script, td / "provider.so", output, before], env=env)

        for name, source, diagnostic in (
                ("unrelocated", '.section .init_array,"aw",@init_array\n.quad 0\n', "require relocations"),
                ("narrow", '.section .fini_array,"aw",@fini_array\n.long target\n', "array layout"),
                ("wrong_reloc", '.section .fini_array,"aw",@fini_array\n.long target\n.long target\n', "array relocation"),
                ("alignment", '.section .init_array,"aw",@init_array\n.balign 16\n.quad target\n', "array layout"),
                ("readonly", '.section .init_array,"a",@init_array\n.quad target\n', "array layout"),
                ("unallocated", '.section .init_array,"w",@init_array\n.quad target\n', "not allocated"),
                ("priority", '.section .init_array.bad,"aw",@init_array\n.quad target\n', "array priority"),
                ("large_priority", '.section .fini_array.65536,"aw",@fini_array\n.quad target\n', "array priority"),
                ("wrong_type", '.section .init_array,"aw",@progbits\n.quad target\n', "array section"),
                ("preinit", '.section .preinit_array,"aw",@progbits\n.quad target\n', "array section"),
                ("empty_symbol", '.section .init_array,"aw",@init_array\n.globl mark\nmark:\n', "empty shared array"),
                ("empty_reference", '.section .init_array,"aw",@init_array\nmark:\n.data\n.quad mark\n', "empty shared array")):
            obj = td / f"{name}.o"
            command([assembler, "-o", obj], input=source)
            output.write_text("preserved")
            result = command([linker, "-nostdlib", "-shared", "-o", output, obj], check=False)
            expect(result.returncode != 0 and diagnostic in result.stderr and
                   output.read_text() == "preserved",
                   f"shared linker did not reject {name} safely: {result.stderr}")

        command([assembler, "-o", td / "duplicate.o"],
                input='.section .init_array,"aw",@init_array\n.quad target\n.quad target\n')
        malformed = bytearray((td / "duplicate.o").read_bytes())
        shoff = struct.unpack_from("<Q", malformed, 40)[0]
        entsize, count = struct.unpack_from("<HH", malformed, 58)
        headers = [struct.unpack_from("<IIQQQQIIQQ", malformed, shoff + i * entsize)
                   for i in range(count)]
        rela = next(h for h in headers if h[1] == 4)
        struct.pack_into("<Q", malformed, rela[4] + 24, 0)
        (td / "duplicate.o").write_bytes(malformed)
        result = command([linker, "-nostdlib", "-shared", "-o", output, td / "duplicate.o"], check=False)
        expect(result.returncode != 0 and "array relocation" in result.stderr and
               output.read_text() == "preserved",
               f"duplicate array relocations were not rejected safely: {result.stderr}")

def shared_runtime_case():
    """Load the shared runtime and check its ABI, linking, and initializer helper.

    Returns:
        None; raises AssertionError for an incomplete or unusable shared runtime.
    """
    library = BUILD / "libcrunch.so.1"
    link = BUILD / "libcrunch.so"
    expect(link.is_symlink() and os.readlink(link) == "libcrunch.so.1" and library.is_file(),
           "missing shared runtime or linker-name symlink")
    image = library.read_bytes()
    expect(image[:5] == b"\x7fELF\x02" and struct.unpack_from("<H", image, 16)[0] == 3,
           "shared runtime is not ELF64 ET_DYN")
    shoff = struct.unpack_from("<Q", image, 40)[0]
    entsize, count = struct.unpack_from("<HH", image, 58)
    headers = [struct.unpack_from("<IIQQQQIIQQ", image, shoff + i * entsize)
               for i in range(count)]
    dynamic = next(h for h in headers if h[1] == 6)
    strings = headers[dynamic[6]]
    names = image[strings[4]:strings[4] + strings[5]]
    tags = [struct.unpack_from("<qQ", image, pos)
            for pos in range(dynamic[4], dynamic[4] + dynamic[5], 16)]
    soname = next(value for tag, value in tags if tag == 14)
    expect(names[soname:names.index(b"\0", soname)] == b"libcrunch.so.1" and
           not any(tag in (1, 22) or (tag == 30 and value & 4) for tag, value in tags),
           "shared runtime has incorrect SONAME, dependencies, or text relocations")

    def symbols(data, kind):
        """Read named ELF symbol records from the selected symbol-table kind.

        Args:
            data: Complete ELF file bytes.
            kind: Symbol-table section type.
        Returns:
            Mapping from symbol names to ELF symbol records.
        """
        shoff = struct.unpack_from("<Q", data, 40)[0]
        entsize, count = struct.unpack_from("<HH", data, 58)
        headers = [struct.unpack_from("<IIQQQQIIQQ", data, shoff + i * entsize)
                   for i in range(count)]
        table = next(h for h in headers if h[1] == kind)
        strings = headers[table[6]]
        names = data[strings[4]:strings[4] + strings[5]]
        records = [struct.unpack_from("<IBBHQQ", data, pos)
                   for pos in range(table[4], table[4] + table[5], table[9])]
        return {names[s[0]:names.index(b"\0", s[0])].decode(): s for s in records if s[0]}

    exported = symbols(image, 11)
    with tempfile.TemporaryDirectory(prefix="crunch-shared-runtime-") as directory:
        td = pathlib.Path(directory)
        command([BUILD / "crunch-ar", "x", BUILD / "libcrunch.a"], cwd=td)
        expected = set()
        for obj in td.glob("*.o"):
            if obj.name.startswith("fallback_"):
                continue
            for name, sym in symbols(obj.read_bytes(), 2).items():
                if sym[1] >> 4 in (1, 2) and sym[2] & 3 in (0, 3) and sym[3] != 0:
                    expected.add(name)
        expected.update(("__crunch_print", "__crunch_pow", "__crunch_printf_v6",
                         "__crunch_fprintf_v6", "__crunch_snprintf_v6",
                         "_crunch_stdin", "_crunch_stdout", "_crunch_stderr"))
        expect(expected <= exported.keys(), f"shared runtime is missing exports: {sorted(expected - exported.keys())}")
        expect("errno" in exported and exported["errno"][2] & 3 == 3 and
               "_crunch_errno_location" not in exported,
               "shared runtime did not export protected errno storage")
        unresolved = {name for name, sym in exported.items() if sym[3] == 0}
        expect(unresolved == {"__start___crunch_init_array", "__stop___crunch_init_array",
                              "__crunch_run_finalizers"} and
               all(exported[name][1] >> 4 == 2 for name in unresolved),
               f"unexpected shared runtime undefined symbols: {unresolved}")

        env = {key: value for key, value in os.environ.items()
               if key not in ("LD_PRELOAD", "LD_LIBRARY_PATH", "LD_AUDIT")}
        loader = r"""
import ctypes, sys
l = ctypes.CDLL(sys.argv[1])
strlen = l.__crunch_strlen
strlen.argtypes = [ctypes.c_char_p]
strlen.restype = ctypes.c_long
assert strlen(b"shared runtime") == 14
power = l.__crunch_pow
power.argtypes = [ctypes.c_double, ctypes.c_double]
power.restype = ctypes.c_double
assert abs(power(2.0, 5.0) - 32.0) < 1e-10
allocate = l.__crunch_malloc
allocate.argtypes = [ctypes.c_long]
allocate.restype = ctypes.c_void_p
release = l.__crunch_free
release.argtypes = [ctypes.c_void_p]
p = allocate(64)
assert p
ctypes.memmove(p, b"data", 5)
assert ctypes.string_at(p) == b"data"
release(p)
error_address = l.__crunch___errno_location
error_address.restype = ctypes.POINTER(ctypes.c_int)
shared_error = ctypes.c_int.in_dll(l, "errno")
assert ctypes.addressof(shared_error) == ctypes.addressof(error_address().contents)
host_error = ctypes.CDLL(None).__errno_location
host_error.restype = ctypes.POINTER(ctypes.c_int)
host = host_error()
host.contents.value = 34
assert not allocate(-1)
assert error_address().contents.value == 12
assert shared_error.value == 12
assert host.contents.value == 34
for name, fd in (("_crunch_stdin", 0), ("_crunch_stdout", 1), ("_crunch_stderr", 2)):
    stream = ctypes.c_void_p.in_dll(l, name).value
    assert stream and ctypes.c_int.from_address(stream).value == fd
fmt = ctypes.create_string_buffer(b"hello")
buf = ctypes.create_string_buffer(8)
slots = (ctypes.c_uint64 * 3)(ctypes.addressof(fmt), len(buf), ctypes.addressof(buf))
format_output = l.__crunch_snprintf_v6
format_output.argtypes = [ctypes.c_void_p, ctypes.c_long]
format_output.restype = ctypes.c_long
assert format_output(slots, 0) == 5 and buf.value == b"hello"
l.__crunch_run_initializers()
"""
        command([PYTHON, "-c", loader, library], env=env)
        command([PYTHON, "-c", loader.replace("ctypes.CDLL(sys.argv[1])",
                                              "ctypes.CDLL(sys.argv[1], mode=ctypes.RTLD_GLOBAL)"),
                 library], env=env)
        result = command([PYTHON, "-c",
                          "import ctypes,sys; ctypes.CDLL(sys.argv[1]).__crunch_end(23)", library],
                         env=env, check=False)
        expect(result.returncode == 23, "shared exit() failed without a finalization hook")
        assembler, linker = BUILD / "crunch-as", BUILD / "crunch-ld"
        client = (".text\n.globl query\n.type query,@function\n"
                  "query: subq $8,%rsp\ncall __crunch_strlen@PLT\naddq $8,%rsp\nret\n")
        command([assembler, "-o", td / "client.o"], input=client)
        command([linker, "-nostdlib", "-shared", "--no-undefined", "-o", td / "client.so",
                 td / "client.o", "-L", BUILD, "-lcrunch"])
        client_loader = ("import ctypes,sys; l=ctypes.CDLL(sys.argv[1]); "
                         "l.query.argtypes=[ctypes.c_char_p]; l.query.restype=ctypes.c_long; "
                         "assert l.query(b'Crunch')==6")
        command([PYTHON, "-c", client_loader, td / "client.so"],
                env=dict(env, LD_LIBRARY_PATH=str(BUILD)))

        registry = (
            ".data\ncount: .long 0\n"
            ".globl __start___crunch_init_array\n__start___crunch_init_array: .quad initialize\n"
            ".globl __stop___crunch_init_array\n__stop___crunch_init_array:\n"
            ".text\ninitialize: addl $1,count(%rip)\nret\n"
            ".globl get_count\nget_count: movl count(%rip),%eax\nret\n"
        )
        command([assembler, "-o", td / "registry.o"], input=registry)
        command([linker, "-nostdlib", "-shared", "--no-undefined", "-o", td / "registry.so", td / "registry.o"])
        registry_loader = ("import ctypes,sys; p=ctypes.CDLL(sys.argv[1],mode=ctypes.RTLD_GLOBAL); "
                           "l=ctypes.CDLL(sys.argv[2]); l.__crunch_run_initializers(); "
                           "assert p.get_count()==1; l.__crunch_run_initializers(); assert p.get_count()==2")
        command([PYTHON, "-c", registry_loader, td / "registry.so", library], env=env)
        incomplete = registry.replace(".globl __stop___crunch_init_array\n__stop___crunch_init_array:\n", "")
        command([assembler, "-o", td / "incomplete.o"], input=incomplete)
        command([linker, "-nostdlib", "-shared", "--no-undefined", "-o", td / "incomplete.so", td / "incomplete.o"])
        incomplete_loader = ("import ctypes,sys; ctypes.CDLL(sys.argv[1],mode=ctypes.RTLD_GLOBAL); "
                             "l=ctypes.CDLL(sys.argv[2]); l.__crunch_run_initializers(); "
                             "f=l.__crunch___errno_location; f.restype=ctypes.POINTER(ctypes.c_int); "
                             "assert f().contents.value==22")
        result = command([PYTHON, "-c", incomplete_loader, td / "incomplete.so", library], env=env)
        expect("incomplete module initializer bounds" in result.stderr,
               "incomplete initializer bounds did not produce a diagnostic")

def native_shared_dependency_case():
    """Check SONAME dependencies, shared search, archive order, and loader behavior.

    Returns:
        None; raises AssertionError for incorrect dependencies or execution.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-shared-deps-") as directory:
        td = pathlib.Path(directory)
        assembler, linker, archiver = BUILD / "crunch-as", BUILD / "crunch-ld", BUILD / "crunch-ar"
        sources = {
            "provider": ".text\n.globl value\n.type value,@function\nvalue: movl $40,%eax\nret\n",
            "fallback": ".text\n.globl value\n.type value,@function\nvalue: movl $90,%eax\nret\n",
            "other": ".text\n.globl extra\n.type extra,@function\nextra: movl $2,%eax\nret\n",
            "consumer": ".text\n.globl answer\n.type answer,@function\n"
                        "answer: subq $8,%rsp\ncall value@PLT\naddq $8,%rsp\n"
                        "addl $2,%eax\nret\n",
        }
        for name, source in sources.items():
            command([assembler, "-o", td / f"{name}.o"], input=source)
        provider, other, output = td / "libdep.so.1", td / "libother.so", td / "consumer.so"
        command([linker, "-nostdlib", "-shared", "-soname", "libdep.so.1", "-o", provider, td / "provider.o"])
        (td / "libdep.so").symlink_to(provider.name)
        command([linker, "-nostdlib", "-shared", "-o", other, td / "other.o"])
        command([archiver, "rcs", td / "libdep.a", td / "fallback.o"])
        command([linker, "-nostdlib", "-shared", "--soname=consumer.so.3", "-o", output,
                 td / "consumer.o", "-L", td, "-ldep", "-lother", "-ldep", "-l:libdep.a"])

        def dynamic_names(path):
            """Read DT_NEEDED and DT_SONAME entries in a generated ELF object.

            Args:
                path: Shared object to inspect.
            Returns:
                Ordered dependency names and the SONAME, if present.
            """
            image = path.read_bytes()
            shoff = struct.unpack_from("<Q", image, 40)[0]
            entsize, count = struct.unpack_from("<HH", image, 58)
            headers = [struct.unpack_from("<IIQQQQIIQQ", image, shoff + i * entsize)
                       for i in range(count)]
            dynamic = next(h for h in headers if h[1] == 6)
            strings = headers[dynamic[6]]
            data = image[strings[4]:strings[4] + strings[5]]
            needed, soname = [], None
            for offset in range(dynamic[4], dynamic[4] + dynamic[5], 16):
                tag, value = struct.unpack_from("<qQ", image, offset)
                if tag == 0:
                    break
                if tag in (1, 14):
                    text = data[value:data.index(b"\0", value)].decode()
                    if tag == 1:
                        needed.append(text)
                    else:
                        soname = text
            return needed, soname

        expect(dynamic_names(output) == (["libdep.so.1", "libother.so"], "consumer.so.3"),
               f"incorrect ordered dependencies: {dynamic_names(output)}")
        loader = "import ctypes,sys; assert ctypes.CDLL(sys.argv[1]).answer() == 42"
        env = {key: value for key, value in os.environ.items()
               if key not in ("LD_PRELOAD", "LD_LIBRARY_PATH", "LD_AUDIT")}
        command([PYTHON, "-c", loader, output], env=dict(env, LD_LIBRARY_PATH=str(td)))
        failed = command([PYTHON, "-c", loader, output], env=env, check=False)
        expect(failed.returncode != 0 and "libdep.so.1" in failed.stderr,
               f"missing dependency was not reported by the loader: {failed.stderr}")

        for inputs, expected in (([td / "consumer.o", other], [str(other)]),
                                 ([td / "consumer.o", "-L", td, "-lother"], ["libother.so"]),
                                 ([td / "consumer.o", "-L", td, "-l:libother.so"], ["libother.so"])):
            command([linker, "-nostdlib", "-shared", "-o", output, *inputs])
            expect(dynamic_names(output)[0] == expected, "incorrect no-SONAME dependency name")
        command([linker, "-nostdlib", "-shared", "-o", output, provider, td / "consumer.o",
                 td / "libdep.a"])
        command([PYTHON, "-c", loader, output], env=dict(env, LD_LIBRARY_PATH=str(td)))
        command([linker, "-nostdlib", "-shared", "--no-undefined", "-o", output, td / "consumer.o", provider])
        command([PYTHON, "-c", loader, output], env=dict(env, LD_LIBRARY_PATH=str(td)))
        original = output.read_bytes()
        failed = command([linker, "-nostdlib", "-shared", "--no-undefined", "-o", output, td / "consumer.o"],
                         check=False)
        expect(failed.returncode != 0 and "undefined reference" in failed.stderr and
               output.read_bytes() == original, "unresolved strong symbol was not rejected safely")
        command([assembler, "-o", td / "weak.o"],
                input=".globl unused\n.data\n.weak absent\n.quad absent\n")
        command([linker, "-nostdlib", "-shared", "--no-undefined", "-o", output, td / "weak.o"])
        command([assembler, "-o", td / "strong.o"], input=".globl absent\n.text\nret\n")
        failed = command([linker, "-nostdlib", "-shared", "--no-undefined", "-o", output,
                          td / "weak.o", td / "strong.o"], check=False)
        expect(failed.returncode != 0 and "undefined reference" in failed.stderr,
               "mixed weak and strong references were not rejected")
        failed = command([linker, "-nostdlib", "-r", "--no-undefined", "-o", output, td / "weak.o"], check=False)
        expect(failed.returncode != 0 and "--no-undefined" in failed.stderr,
               "--no-undefined was accepted outside shared linking")
        command([linker, "-nostdlib", "-shared", "-o", output, td / "consumer.o",
                 td / "libdep.a", provider])
        failure = command([PYTHON, "-c", loader, output], env=dict(env, LD_LIBRARY_PATH=str(td)),
                          check=False)
        expect(failure.returncode != 0, "archive before shared input was not extracted")

        command([linker, "-nostdlib", "-shared", "--require-defined=value", "-o", output,
                 td / "other.o", provider, td / "libdep.a"])
        image = output.read_bytes()
        shoff = struct.unpack_from("<Q", image, 40)[0]
        entsize, count = struct.unpack_from("<HH", image, 58)
        headers = [struct.unpack_from("<IIQQQQIIQQ", image, shoff + i * entsize)
                   for i in range(count)]
        dynsym = next(h for h in headers if h[1] == 11)
        strings = headers[dynsym[6]]
        names = image[strings[4]:strings[4] + strings[5]]
        symbols = [struct.unpack_from("<IBBHQQ", image, pos)
                   for pos in range(dynsym[4], dynsym[4] + dynsym[5], dynsym[9])]
        expect(any(names[s[0]:names.index(b"\0", s[0])] == b"value" and s[3] == 0
                   for s in symbols), "required DSO symbol was not retained as undefined")
        result = command([linker, "-nostdlib", "-shared", "--require-defined=missing", "-o", output,
                          td / "other.o", provider], check=False)
        expect(result.returncode != 0 and "required symbol" in result.stderr and
               output.read_bytes() == image, "missing required symbol was not rejected safely")

        bad = bytearray(provider.read_bytes())
        shoff = struct.unpack_from("<Q", bad, 40)[0]
        entsize, count = struct.unpack_from("<HH", bad, 58)
        headers = [struct.unpack_from("<IIQQQQIIQQ", bad, shoff + i * entsize)
                   for i in range(count)]
        dynamic = next(h for h in headers if h[1] == 6)
        soname_offset = next(pos for pos in range(dynamic[4], dynamic[4] + dynamic[5], 16)
                             if struct.unpack_from("<q", bad, pos)[0] == 14)
        struct.pack_into("<Q", bad, soname_offset + 8, 0xffffffffffffffff)
        invalid = td / "bad.so"
        invalid.write_bytes(bad)
        output.write_text("preserved")
        for args in ([linker, "-nostdlib", "-shared", "-o", output, td / "consumer.o", invalid],
                     [linker, "-nostdlib", "-r", "-o", output, td / "consumer.o", provider]):
            result = command(args, check=False)
            expect(result.returncode != 0 and result.stderr and output.read_text() == "preserved",
                   f"invalid shared input was not rejected safely: {result.stderr}")

def initialized_block_ir_case():
    """Validate initialized blocks and execute their emitted static storage.

    Returns:
        None; raises AssertionError for invalid acceptance or incorrect storage.
    """
    fixture = FIXTURES / "ir/fixed_block_data.bir"
    ir = fixture.read_text()
    command([ASM, "--validate"], input=ir)
    command([ASM, "--validate"], input=ir.replace("CRUNCH-IR 10", "CRUNCH-IR 11"))
    command([ASM, "--validate"], input=ir + "func another 0 int\npush 0\nret int\nend\n")
    command([ASM, "--validate"], input="CRUNCH-IR 11\nglobalblock data 4 4\n"
                                      "blockdata data 2a000000\n")
    with tempfile.TemporaryDirectory(prefix="crunch-block-data-") as directory:
        td = pathlib.Path(directory)
        assembly, obj, exe = td / "block.s", td / "block.o", td / "block"
        assembly.write_text(command([ASM, fixture]).stdout)
        command([TEST_AS, "-o", obj, assembly])
        command([*TEST_LINK, "-o", exe, obj, LIBCRUNCH])
        expect(command([exe], check=False).returncode == 42,
               "initialized block contents or zero padding were incorrect")
    invalid = (
        ir.replace("CRUNCH-IR 10", "CRUNCH-IR 9"),
        ir.replace("2a00000008000000", "2x"),
        ir.replace("2a00000008000000", "a"),
        ir.replace("2a00000008000000", "00" * 13),
        ir.replace("blockdata values", "blockdata missing"),
        ir.replace("blockdata values 2a00000008000000",
                   "blockdata values 00\nblockdata values 00"),
    )
    for text in invalid:
        result = command([ASM, "--validate"], input=text, check=False)
        expect_clean_rejection(result, "invalid initialized block")
        expect(not result.stdout, "invalid initialized block emitted output")


