def fixed_array_frontend_case():
    """Check fixed-array semantics, AST serialization, and generated IR.

    Returns:
        None; raises AssertionError for incorrect fixed-array handling.
    """
    fixture = FIXTURES / "units/types/fixed_arrays.bc"
    sema_case(fixture, True)
    sema_case(FIXTURES / "units/types/invalid_fixed_arrays.bc", False,
              "positive integer constant")
    tree = json.loads(source_parse(fixture).stdout)
    serialized = json.dumps(tree)
    expect(tree["version"] == 17 and '"kind": "array"' in serialized and
           '"element":' in serialized, "fixed array AST metadata is missing")
    for mode in ([], ["--module"]):
        result = command([IR, *mode, fixture])
        command([ASM, "--validate"], input=result.stdout)
        instructions = {line.split()[0] for line in result.stdout.splitlines() if line.strip()}
        expect(not instructions.intersection({"array_alloc", "array_resize",
                                              "array_resize_bytes", "globalbytes"}),
               "fixed arrays emitted legacy dynamic-array IR")
    invalid = [
        ("int main() { int a[0]; return 0; }", "positive integer constant"),
        ("int main() { int a[-1]; return 0; }", "positive integer constant"),
        ("int main() { int a[1] = {1, 2}; return 0; }", "too many"),
        ('int main() { char a[2] = "abc"; return 0; }', "too long"),
        ("int main() { int a[2]; a = a; return 0; }", "modifiable lvalue"),
        ("int main() { int a[2]; ++a; return 0; }", "modifiable"),
        ("int main() { const int a[2] = {1, 2}; a[0] = 3; return 0; }", "const object"),
        ("struct S { int a[2]; }; int main() { const struct S s; s.a[0] = 3; return 0; }",
         "const object"),
        ("int main() { const { int a[2]; }; int *p = a; return 0; }", "incompatible"),
        ("int main() { int a[9223372036854775807]; return 0; }", "unsupported size"),
        ("int main() { int a[] = {}; return 0; }", "at least one"),
    ]
    with tempfile.TemporaryDirectory(prefix="crunch-fixed-arrays-") as directory:
        source = pathlib.Path(directory) / "array.bc"
        for text, diagnostic in invalid:
            source.write_text(text + "\n")
            sema_case(source, False, diagnostic)
        source.write_text("int main() { int a[2][3]; return sizeof(a) == 24 ? 42 : 1; }\n")
        sema_case(source, True)
        compile_run(source, 42)


def array_typedef_case():
    """Check array typedef storage, decay, parameter adjustment, and bounds.

    Returns:
        None; raises AssertionError for incorrect array alias behavior.
    """
    fixture = FIXTURES / "units/types/array_typedef.bc"
    tree = json.loads(source_parse(fixture).stdout)
    expect(tree["version"] == 32, "array typedef did not select AST v32")
    aliases = {decl["name"]: decl["type"] for decl in tree["declarations"]
               if decl["kind"] == "type_alias"}
    expect(aliases["Records"]["length"] == "1" and aliases["Numbers"]["length"] == "3",
           "array typedef bounds are missing")
    expect(aliases["IntPointer"]["kind"] == "pointer", "comma declarator type changed")
    sema_case(fixture, True)
    compile_run(fixture, 42)
    with tempfile.TemporaryDirectory(prefix="crunch-array-typedef-") as directory:
        source = pathlib.Path(directory) / "array.bc"
        for bound in ("0",):
            source.write_text(f"typedef int A[{bound}]; int main(void) {{ return 0; }}\n")
            lexed = command([LEXER, source])
            expect_clean_rejection(command([PARSER], input=lexed.stdout, check=False),
                                   "unsupported array typedef bound")
        source.write_text("typedef int A[1 + 1]; int main(void) { A a = {40,2}; "
                          "return a[0] + a[1]; }\n")
        sema_case(source, True)
        compile_run(source, 42)
        for text, diagnostic in (
                ("typedef int A[2]; int main(void) { A a = {1, 2, 3}; return 0; }", "too many"),
                ("typedef void A[2]; int main(void) { return 0; }", "incomplete element"),
                ("typedef int A[2]; A f(void); int main(void) { return 0; }",
                 "cannot return arrays"),
                ("typedef int A[2]; typedef A (*F)(void); int main(void) { return 0; }",
                 "cannot return arrays"),
                ("typedef int A[2]; int f(const A a) { a[0] = 1; return 0; }",
                 "const object"),
                ("typedef int A[2]; int main(void) { const A a = {1, 2}; a[0] = 3; return 0; }",
                 "const object")):
            source.write_text(text + "\n")
            sema_case(source, False, diagnostic)
        source.write_text(r'''
typedef int Row[3];
typedef Row Plane[2];
Row global[2] = {{1, 2, 3}, {4, 5, 6}};
Plane volume[2] = {{{1, 2, 3}, {4, 5, 6}}, {{7}, {8}}};
struct Matrix { Row cells[2]; };
int sum(Row rows[]) {
    int total = 0;
    for (int i = 0; i < 2; ++i)
        for (int j = 0; j < 3; ++j)
            total += rows[i][j];
    return total;
}
int main(void) {
    Row flat[] = {1, 2, 3, 4, 5, 6};
    Row designated[2] = {[1][2] = 9, [0][1] = 4};
    static Row stored[2] = {{3}, {0, 7}};
    struct Matrix m = {{{1, 2, 3}, {4, 5, 6}}};
    Row *p = global;
    if (sizeof(global) != 24 || sizeof(global[0]) != 12 || sizeof(flat) != 24)
        return 1;
    if (sum(global) != 21 || sum(flat) != 21 || sum(m.cells) != 21)
        return 2;
    if (p[1][2] != 6 || (p + 1) - p != 1 || designated[1][2] != 9 ||
        designated[0][1] != 4 || designated[0][0] != 0 || stored[1][1] != 7)
        return 3;
    if (sizeof(volume) != 48 || volume[1][0][0] != 7 || volume[1][1][0] != 8)
        return 4;
    return 42;
}
''')
        sema_case(source, True)
        compile_run(source, 42)
        obj, exe = source.with_suffix(".o"), source.with_suffix(".out")
        command([DRIVER, "-c", source, "-o", obj])
        for flags in (["--static"], ["--dynamic"], ["-pie"]):
            command([DRIVER, *flags, obj, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"nested array typedefs failed in {flags}")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            command(["cc", "-x", "c", "-std=c11", "-Wall", "-Wextra", "-Werror",
                     "-Wno-missing-braces",
                     source, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   "host C disagrees with nested array typedef test")
        for text, diagnostic in (
                ("typedef int Row[2]; int main(void) { Row a[2] = {{1,2,3}}; return 0; }",
                 "too many"),
                ("typedef int Row[2]; int main(void) { const Row a[2] = {{1}}; "
                 "a[0][1] = 2; return 0; }", "const object"),
                ("typedef int Row[2]; int main(void) { Row a[2] = {[1][2] = 1}; return 0; }",
                 "out of bounds")):
            source.write_text(text + "\n")
            sema_case(source, False, diagnostic)


def multidimensional_fixed_array_case():
    """Test direct multidimensional arrays, bounds, parameters, and linkage.

    Returns:
        None; raises AssertionError for incorrect parsing, diagnostics, or execution.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-multidimensional-") as directory:
        td = pathlib.Path(directory)
        source, obj, exe = td / "matrix.bc", td / "matrix.o", td / "matrix"
        source.write_text(r'''
enum { COLS = 2 + 1, ROWS = 2 };
typedef int Matrix[ROWS][COLS];
struct Grid { int cells[ROWS][COLS]; };
int global[][COLS] = {1, 2, 3, 4, 5, 6};
int volume[2][2][2] = {{{1,2},{3,4}},{{5,6},{7,8}}};
int sum(int a[ROWS][COLS]) {
    int total = 0;
    for (int i = 0; i < ROWS; ++i)
        for (int j = 0; j < COLS; ++j)
            total += a[i][j];
    return total;
}
int main(void) {
    Matrix m = {{1,2,3}, {4,5,6}};
    struct Grid g = {{{1,2,3}, {4,5,6}}};
    int flat[][COLS] = {1,2,3,4,5,6};
    int marked[ROWS][COLS] = {[1][2] = 9, [0][1] = 4};
    static int saved[2][COLS] = {{3}, {0, 7}};
    char names[2][4] = {"abc", "xy"};
    int (*call)(int [][COLS]) = sum;
    if (sizeof(global) != 24 || sizeof(global[0]) != 12 ||
        sizeof(int[ROWS][COLS]) != 24 || sizeof(flat) != 24 ||
        sizeof(volume) != 32 || volume[1][1][1] != 8) return 1;
    if (sum(m) != 21 || sum(g.cells) != 21 || call(flat) != 21) return 2;
    if (marked[1][2] != 9 || marked[0][1] != 4 ||
        marked[0][0] != 0 || saved[1][1] != 7 || names[1][1] != 'y') return 3;
    return 42;
}
''')
        tree = json.loads(source_parse(source).stdout)
        expect(tree["version"] == 34, "multidimensional arrays did not select AST v34")
        global_array = next(d for d in tree["declarations"]
                            if d["kind"] == "variable" and d["name"] == "global")
        expect(global_array["array_size"] is None and
               global_array["type"]["element"]["array_bound"]["kind"] == "name",
               "AST lost the inner array bound")
        sema_case(source, True)
        compile_run(source, 42)
        command([DRIVER, "-c", source, "-o", obj])
        for flags in (["--static"], ["--dynamic"], ["-pie"]):
            command([DRIVER, *flags, obj, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"multidimensional arrays failed in {flags}")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            command(["cc", "-x", "c", "-std=c11", "-Wall", "-Wextra", "-Werror",
                     "-Wno-missing-braces", source, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   "host C disagrees with multidimensional array test")

        provider, consumer = td / "provider.bc", td / "consumer.bc"
        provider.write_text("int m[2][3]={{1,2,3},{4,5,6}}; "
                            "int read_at(int x[][3]) { return x[1][2]; }\n")
        consumer.write_text("extern int m[2][3]; int read_at(int x[][3]); "
                            "int main(void) { return read_at(m) == 6 ? 42 : 1; }\n")
        objects = [td / "provider.o", td / "consumer.o"]
        for part, output in zip((provider, consumer), objects):
            command([DRIVER, "-c", part, "-o", output])
        for flags in (["--static"], ["--dynamic"], ["-pie"]):
            command([DRIVER, *flags, *objects, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"multidimensional arrays failed across modules in {flags}")

        for program in (r'''
int product(int a[][2], int b[][2], int out[][2]) {
    for (int i=0; i<2; ++i)
        for (int j=0; j<2; ++j) {
            out[i][j] = 0;
            for (int k=0; k<2; ++k) out[i][j] += a[i][k] * b[k][j];
        }
    return out[0][0] + out[0][1] + out[1][0] + out[1][1];
}
int main(void) {
    int a[2][2]={{1,2},{3,4}}, b[2][2]={{1,2},{2,1}}, out[2][2];
    return product(a,b,out)==30 && out[1][1]==10 ? 42 : 1;
}
''', r'''
enum { N=3 };
typedef int Row[N];
int main(void) {
    enum { N=4 };
    Row a[2] = {{1,2,3}, {4,5,6}};
    int transpose[3][2];
    for (int y=0; y<2; ++y)
        for (int x=0; x<3; ++x) transpose[x][y] = a[y][x];
    return sizeof(a)==24 && transpose[2][1]==6 ? 42 : 1;
}
''', r'''
long double values[2][2] = {{1.0L, 2.0L}, {3.0L, 4.0L}};
int main(void) {
    values[1][1] += 1.0L;
    return values[1][1] == 5.0L ? 42 : 1;
}
''', r'''
struct Cell { int x; };
struct Cell cells[2][2] = {{{1},{2}},{{3},{4}}};
int main(void) {
    return cells[1][1].x == 4 ? 42 : 1;
}
'''):
            source.write_text(program)
            compile_run(source, 42)
            if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
                command(["cc", "-x", "c", "-std=c11", "-Wall", "-Wextra", "-Werror",
                         source, "-o", exe])
                expect(command([exe], check=False).returncode == 42,
                       "host C disagrees with matrix program")

        for text, diagnostic in (
                ("int main(void){int a[2][];return 0;}", "bound"),
                ("int main(void){int a[2][0];return 0;}", "positive"),
                ("int main(void){int a[2][-1];return 0;}", "positive"),
                ("typedef int A[-1]; int main(void){return 0;}", "positive"),
                ("int f(int a[2][]){return 0;}", "bound"),
                ("int main(void){int a[2][3]={{1,2,3,4}};return 0;}", "too many"),
                ("int f(int a[][2]); int f(int a[][3]){return 0;}", "conflicting"),
                ("int main(void){int a[2][9223372036854775807];return 0;}",
                 "unsupported size"),
                ("int main(void){const int a[2][3]={{1}}; a[1][2]=3; return 0;}",
                 "const object")):
            source.write_text(text + "\n")
            sema_case(source, False, diagnostic)
        source.write_text("int f(int a[][0]) { return 0; }\n")
        command([SEMA, source, "expect-error-repeat"])
        compile_run(FIXTURES / "units/function_calls/argv_runtime.bc", 42, args=("xy",))


def forward_structure_case():
    """Check standalone structure and union tags, completion, and shadowing.

    Returns:
        None; raises AssertionError for incorrect parsing or semantics.
    """
    program = '''struct Item;
struct Item;
union Choice;
struct Item *identity(struct Item *p) { return p; }
struct Item { int value; };
union Choice { int value; };
int main(void) {
    struct Item outer = {2};
    union Choice choice = {0};
    { struct Item; struct Item *p; struct Item { int value; };
      struct Item inner = {40}; p = &inner;
      choice.value = p->value + identity(&outer)->value; }
    { union Item; union Item { int value; }; union Item item = {0};
      choice.value += item.value; }
    return choice.value;
}
'''
    with tempfile.TemporaryDirectory(prefix="crunch-forward-struct-") as directory:
        source = pathlib.Path(directory) / "program.bc"
        source.write_text(program)
        sema_case(source, True)
        compile_run(source, 42)
        provider = pathlib.Path(directory) / "provider.bc"
        exe = pathlib.Path(directory) / "test"
        provider.write_text("struct Opaque { int value; }; "
                            "struct Opaque shared = {42};\n"
                            "union Other { int value; }; union Other other = {1};\n")
        source.write_text('''struct Opaque;
union Other;
extern struct Opaque shared;
extern union Other other;
struct Opaque *first(void) { return &shared; }
int main(void) {
    extern struct Opaque shared;
    extern union Other other;
    return first() == &shared && &other != 0 ? 42 : 1;
}
''')
        sema_case(source, True)
        command([DRIVER, "--static", source, provider, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "external incomplete aggregate did not link or preserve its address")
        for text in (
                "struct S; struct S f(struct S x); struct S { int value; };",
                "struct S; struct S value; struct S { int value; };",
                "struct S; typedef struct S S; S *p; struct S { int value; }; "
                "int main(void) { S value = {42}; p = &value; return p->value; }",
                "struct S; struct T { struct S *p; }; struct S { int value; };",
                'struct S; _Static_assert(sizeof(struct S *) == 8, "pointer"); '
                'struct S { int value; }; _Static_assert(sizeof(struct S) == 4, "complete");',
                "int main(void) { typedef struct S { int value; } S; S x = {42}; return x.value; }"):
            source.write_text(text + "\n")
            sema_case(source, True)
        for text, diagnostic in (
                ("struct S; int main(void) { struct S value; return 0; }", "unknown structure"),
                ("struct S; extern struct S value = {0};", "unknown structure"),
                ("struct S; extern struct S value; "
                 "int main(void) { return sizeof(value); }", "complete object type"),
                ("struct S; struct S value;", "tentative definition requires a complete"),
                ("struct S; static struct S value; struct S { int value; };", "unknown structure"),
                ('struct S; _Static_assert(sizeof(struct S) == 4, "early"); '
                 'struct S { int value; };', "complete object type"),
                ("struct S; struct T { struct S value; }; struct S { int value; };",
                 "unknown structure"),
                ("struct S; int f(struct S *p) { return (p + 1) != 0; } "
                 "struct S { int value; };", "incomplete structure"),
                ("struct S; int f(struct S *p) { return p->value; } "
                 "struct S { int value; };", "member access on an incomplete structure"),
                ("int main(void) { struct S; int n = sizeof(struct S); "
                 "struct S { int value; }; return n; }", "complete object type"),
                ("struct S; int main(void) { struct S *p = 0; return (p + 1) != 0; }",
                 "incomplete structure"),
                ("struct S { int x; }; int main(void) { struct S outer; "
                 "{ struct S; struct S *p = &outer; } return 0; }", "incompatible")):
            source.write_text(text + "\n")
            sema_case(source, False, diagnostic)
        for text in ("struct S; union S;",
                     "int main(void) { for (struct S; 0; ) {} return 0; }"):
            source.write_text(text + "\n")
            expect_clean_rejection(command([IR, "--module", source], check=False),
                                   "invalid forward declaration", "E_PARSE")
        header = pathlib.Path(directory) / "definition.h"
        header.write_text('#line 1 "logical-definition.h"\nstruct S { int value; };\n')
        source.write_text('''#line 800 "before.h"
struct S;
int before(struct S *p) { return p->value; }
#include "definition.h"
''')
        result = command([DRIVER, "--emit-ir", source], check=False)
        expect(result.returncode != 0 and "member access on an incomplete structure" in result.stderr,
               f"included later definition was visible too early: {result.stderr}")
        source.write_text('''#line 800 "before.h"
struct S;
#include "definition.h"
#line 1 "after.h"
int main(void) { struct S value = {42}; return value.value; }
''')
        command([DRIVER, "--static", source, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "definition completion across source markers failed")


def static_assert_case():
    """Check static assertions, scopes, diagnostics, and AST serialization.

    Returns:
        None; raises AssertionError for incorrect parsing or semantics.
    """
    fixture = FIXTURES / "units/types/static_assert.bc"
    lexed = command([LEXER, fixture])
    expect("STATIC_ASSERT\t" in lexed.stdout, "lexer lost static assertion keyword")
    tree = json.loads(command([PARSER], input=lexed.stdout).stdout)
    expect(tree["version"] == 35, "static assertion did not select AST v35")
    file_assert = next(d for d in tree["declarations"] if d["kind"] == "static_assert")
    expect(file_assert["condition"]["kind"] == "binary" and
           file_assert["message"]["kind"] == "string", "assertion AST is incomplete")
    grid = next(d for d in tree["declarations"]
                if d["kind"] == "struct" and d["name"] == "Grid")
    expect(grid["assertions"][0]["preceding_fields"] == 1 and
           grid["assertions"][0]["declaration"]["kind"] == "static_assert",
           "structure assertion position was lost")
    sema_case(fixture, True)
    compile_run(fixture, 42)
    with tempfile.TemporaryDirectory(prefix="crunch-static-assert-") as directory:
        td = pathlib.Path(directory)
        obj, exe, source = td / "test.o", td / "test", td / "invalid.bc"
        command([DRIVER, "-c", fixture, "-o", obj])
        for flags in (["--static"], ["--dynamic"], ["-pie"]):
            command([DRIVER, *flags, obj, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"static assertion fixture failed in {flags}")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            command(["cc", "-x", "c", "-std=c11", "-Wall", "-Wextra", "-Werror",
                     fixture, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   "host C disagrees with static assertion fixture")
        for text, diagnostic in (
                ('_Static_assert(0, "file " "failure");', "file failure"),
                ('int main(void){_Static_assert(0, "block failure");return 0;}', "block failure"),
                ('struct S {int a; _Static_assert(0, "field failure");};', "field failure"),
                ('int main(void){struct S {_Static_assert(0, "local field"); int x;};return 0;}',
                 "local field"),
                ('int main(void){int x=1; _Static_assert(x,"x");return 0;}', "constant expression"),
                ('_Static_assert(1.0, "real");', "constant expression"),
                ('_Static_assert(1/0, "division");', "constant expression"),
                ('_Static_assert(2147483647+1, "overflow");', "constant expression"),
                ('struct S {_Static_assert(sizeof(struct S), "incomplete"); int x;};',
                 "complete object type"),
                ('struct S {int a; _Static_assert(sizeof(((struct S*)0)->a),"incomplete");};',
                 "incomplete structure"),
                ('_Static_assert(sizeof(later), "forward"); int later;', "undefined identifier"),
                (r'_Static_assert(0, "escaped \x46" "ailure");', "escaped Failure")):
            source.write_text(text + "\n")
            sema_case(source, False, diagnostic)
        source.write_text('_Static_assert(0,"repeat");\n')
        command([SEMA, source, "expect-error-repeat"])
        source.write_text('_Static_assert(1); struct S { _Static_assert(1); int x; }; '
                          'int main(void) { _Static_assert(1); return 42; }\n')
        tree = json.loads(source_parse(source).stdout)
        expect(tree["version"] == 45 and tree["declarations"][0]["message"] is None,
               "message-less assertion AST was not preserved")
        compile_run(source, 42)
        source.write_text('_Static_assert(0);\n')
        sema_case(source, False, "static assertion failed")
        chain = " && ".join(f"({i} == {i})" for i in range(45))
        source.write_text(f"enum {{ check = {chain} }}; "
                          "_Static_assert(check); int main(void) { return check ? 42 : 1; }\n")
        compile_run(source, 42)
        for text in ('_Static_assert(1, 2);',
                     '_Static_assert(1, "x")', 'int main(void){if(1) _Static_assert(1,"x");}'):
            source.write_text(text + "\n")
            result = command([IR, "--module", source], check=False)
            expect_clean_rejection(result, "malformed static assertion", "E_PARSE")


def pointer_to_array_case():
    """Check pointer-to-array declarations, type names, and cross-module calls.

    Returns:
        None; raises AssertionError for incorrect diagnostics or execution.
    """
    fixture = FIXTURES / "units/types/pointer_to_array.bc"
    tree = json.loads(source_parse(fixture).stdout)
    expect(tree["version"] == 34, "pointer-to-array did not select AST v34")
    pointer = next(d for d in tree["declarations"]
                   if d["kind"] == "variable" and d["name"] == "global_rows")
    expect(pointer["type"]["kind"] == "pointer" and
           pointer["type"]["pointee"]["kind"] == "array" and
           pointer["type"]["pointee"]["array_bound"]["kind"] == "name",
           "AST lost the pointer-to-array type or bound")
    sema_case(fixture, True)
    compile_run(fixture, 42)
    with tempfile.TemporaryDirectory(prefix="crunch-pointer-array-") as directory:
        td = pathlib.Path(directory)
        exe, obj = td / "test", td / "test.o"
        command([DRIVER, "-c", fixture, "-o", obj])
        for flags in (["--static"], ["--dynamic"], ["-pie"]):
            command([DRIVER, *flags, obj, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"pointer-to-array fixture failed in {flags}")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            command(["cc", "-x", "c", "-std=c11", "-Wall", "-Wextra", "-Werror",
                     fixture, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   "host C disagrees with pointer-to-array fixture")

        provider, consumer = td / "provider.bc", td / "consumer.bc"
        provider.write_text("int read_row(int (*p)[3]) { return p[1][2]; }\n")
        consumer.write_text("int read_row(int (*)[3]); "
                            "int main(void) { int a[2][3]={{1},{0,0,42}}; "
                            "return read_row(a); }\n")
        objects = [td / "provider.o", td / "consumer.o"]
        for source, output in zip((provider, consumer), objects):
            command([DRIVER, "-c", source, "-o", output])
        for flags in (["--static"], ["--dynamic"], ["-pie"]):
            command([DRIVER, *flags, *objects, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"pointer-to-array cross-module call failed in {flags}")

        source = td / "invalid.bc"
        for text, diagnostic in (
                ("int main(void){int (*p)[0];return 0;}", "positive"),
                ("int main(void){int (*p)[2][];return 0;}", "bound"),
                ("int main(void){int (*p)[]=0; p++;return 0;}", "increment"),
                ("int main(void){int (*p)[]=0; p+=1;return 0;}", "compound assignment"),
                ("int main(void){int (*p)[]=0; p=p+1;return 0;}", "incomplete array"),
                ("int main(void){int (*p)[]=0; return p[0][0];}", "incomplete array"),
                ("int f(int (*p)[2]); int f(int (*p)[3]){return 0;}", "conflicting"),
                ("int main(void){int a[2][3];int (*const p)[3]=a;p=a;return 0;}",
                 "const object")):
            source.write_text(text + "\n")
            sema_case(source, False, diagnostic)
        source.write_text("int f(int (*p)[0]) { return 0; }\n")
        command([SEMA, source, "expect-error-repeat"])


