def short_types_case():
    """Check 16-bit types through parsing, semantics, IR, execution, and the C ABI.

    Returns:
        None; raises AssertionError for incorrect short-type behavior.
    """
    fixture = FIXTURES / "units/types/short_types.bc"
    tree = json.loads(source_parse(fixture).stdout)
    expect(tree["version"] == 18, "short AST did not select version 18")
    sema_case(fixture, True)
    ir, _ = compile_run(fixture, 42)
    expect(ir.startswith("CRUNCH-IR 14\n"), "short executable did not select IR v14")
    module = command([IR, "--module", fixture]).stdout
    expect(module.startswith("CRUNCH-IR 15\n"), "short module did not select IR v15")
    command([ASM, "--validate"], input=module)
    for version in range(2, 14):
        text = f"CRUNCH-IR {version}\nfunc main 0 int\npush 0\nret int\nneg short\nend\n"
        result = command([ASM, "--validate"], input=text, check=False)
        expect(result.returncode != 0 and not result.stdout,
               f"IR v{version} accepted a short type")
    for text in (
            "CRUNCH-IR 14\nglobal value ushort 65536\nfunc main 0 int\npush 0\nret int\nend\n",
            "CRUNCH-IR 14\nglobal value ushort -1\nfunc main 0 int\npush 0\nret int\nend\n",
            "CRUNCH-IR 14\nglobalblock data 2 2\nglobalalias value data 1 short\n"
            "func main 0 int\npush 0\nret int\nend\n"):
        result = command([ASM, "--validate"], input=text, check=False)
        expect(result.returncode != 0 and not result.stdout, "invalid short IR accepted")
    with tempfile.TemporaryDirectory(prefix="crunch-short-") as directory:
        td = pathlib.Path(directory)
        source = td / "invalid.bc"
        for text in (
                "short *p; unsigned short *q; int main() { p = q; return 0; }",
                "short f(short x); int f(short x);",
                "int main() { short x; const short *p = &x; *p = 1; return 0; }",
                "int values[(short)32768.0]; int main() { return 0; }",
                "int main() { short x = 1; x <<= 32; return x; }",
                "int main() { int x; switch (x) { case (short)65535: break; "
                "case -1: break; } return 0; }"):
            source.write_text(text + "\n")
            sema_case(source, False)
        source.write_text("#include <limits.h>\nint main() { "
                          "if (SHRT_MIN != -32768 || SHRT_MAX != 32767 || "
                          "USHRT_MAX != 65535) return 1; return 42; }\n")
        exe = td / "limits"
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 42, "short limits were incorrect")
        provider, consumer = td / "provider.bc", td / "consumer.bc"
        provider.write_text("unsigned short shared = 40000; "
                            "short value(short x) { return x; }\n")
        consumer.write_text("extern unsigned short shared; short value(short x); "
                            "int main() { if (shared != 40000 || value(-2) != -2) "
                            "return 1; return 42; }\n")
        objects = [td / "provider.o", td / "consumer.o"]
        for unit, obj in zip((provider, consumer), objects):
            command([DRIVER, "-c", unit, "-o", obj])
        command([DRIVER, *objects, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "short declarations failed across Crunch modules")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1":
            return
        source.write_text("""
extern short c_func(short a, unsigned short b, short c, unsigned short d,
                    short e, unsigned short f, short g, unsigned short h);
extern unsigned short c_global;
struct Data { char marker; short value; unsigned short other; };
unsigned short crunch_data[3] = {1, 40000, 65535};
short read_data(struct Data *data) {
    if (data->marker != 7 || data->other != 65000) return 0;
    data->other = 32000;
    return data->value;
}
short crunch_func(short a, unsigned short b, short c, unsigned short d,
                  short e, unsigned short f, short g, unsigned short h) {
    if (a != -1 || b != 65535 || c != -2 || d != 60000 ||
        e != -3 || f != 50000 || g != -4 || h != 40000) return 0;
    return -1234;
}
unsigned short crunch_unsigned() { return 60000; }
int invoke() {
    if (c_global != 65000) return 1;
    if (c_func(-1, 65535, -2, 60000, -3, 50000, -4, 40000) != -2345) return 2;
    return 0;
}
""")
        assembly = td / "crunch.s"
        assembly.write_text(command([ASM], input=command([IR, "--module", source]).stdout).stdout)
        host = td / "host.c"
        host.write_text("""
extern short crunch_func(short, unsigned short, short, unsigned short,
                         short, unsigned short, short, unsigned short);
extern unsigned short crunch_unsigned(void);
extern int invoke(void);
struct Data { char marker; short value; unsigned short other; };
extern short read_data(struct Data *);
extern unsigned short crunch_data[3];
unsigned short c_global = 65000;
short c_func(short a, unsigned short b, short c, unsigned short d,
             short e, unsigned short f, short g, unsigned short h) {
    return a == -1 && b == 65535 && c == -2 && d == 60000 &&
           e == -3 && f == 50000 && g == -4 && h == 40000 ? -2345 : 0;
}
int main(void) {
    struct Data data = {7, -30000, 65000};
    return crunch_func(-1, 65535, -2, 60000, -3, 50000, -4, 40000) != -1234 ||
           crunch_unsigned() != 60000 || invoke() != 0 ||
           read_data(&data) != -30000 || data.other != 32000 ||
           crunch_data[0] != 1 || crunch_data[1] != 40000 || crunch_data[2] != 65535;
}
""")
        exe = td / "interop"
        command(["cc", "-o", exe, host, assembly])
        expect(command([exe], check=False).returncode == 0, "C short ABI interoperability failed")


def mixed_declarators_case():
    """Check independent declarator types, qualifiers, scopes, and linkage.

    Returns:
        None; raises AssertionError for incorrect parsing or execution.
    """
    fixture = FIXTURES / "units/parser/mixed_declarations.bc"
    sema_case(fixture, True)
    compile_run(fixture, 42)
    with tempfile.TemporaryDirectory(prefix="crunch-mixed-declarators-") as directory:
        td = pathlib.Path(directory)
        source = td / "types.bc"
        source.write_text("const int *p, value; int *const fixed, *other; "
                          "typedef int *P; P first, *second; "
                          "struct S { int *x, y, *array[2]; }; "
                          "struct Outer { struct { int z; } *a, b; };\n")
        tree = json.loads(source_parse(source).stdout)
        variables = {d["name"]: d["type"] for d in tree["declarations"]
                     if d["kind"] == "variable"}
        expect(variables["p"]["kind"] == "pointer" and variables["p"]["pointee"]["const"] and
               variables["value"]["kind"] == "int" and variables["value"]["const"] and
               variables["fixed"]["const"] and not variables["other"]["const"] and
               variables["first"]["pointee"]["kind"] == "int" and
               variables["second"]["pointee"]["kind"] == "pointer",
               "declarator pointer or qualifier leaked to another variable")
        structures = {d["name"]: d for d in tree["declarations"] if d["kind"] == "struct"}
        fields = {d["name"]: d["type"] for d in structures["S"]["fields"]}
        expect(fields["x"]["kind"] == "pointer" and fields["y"]["kind"] == "int" and
               fields["array"]["kind"] == "array" and
               fields["array"]["element"]["kind"] == "pointer",
               "mixed structure field types are incorrect")
        fields = {d["name"]: d["type"] for d in structures["Outer"]["fields"]}
        expect(fields["a"]["kind"] == "pointer" and fields["b"]["kind"] == "struct" and
               fields["a"]["pointee"]["name"] == fields["b"]["name"],
               "inline structure declarators have incorrect types")
        for text in (
                "int main() { int x = 1; const int *p = &x, value = 2; value = 3; return *p; }",
                "int main() { int x = 1; int *const p = &x, *q = &x; "
                "q = &x; p = &x; return *q; }"):
            source.write_text(text + "\n")
            sema_case(source, False, "const")
        source.write_text("typedef int T; int main() { T T = 40, *p = &T; return *p + 2; }\n")
        compile_run(source, 42)
        source.write_text("int value, *pointer = 0; int main() { return value; }\n")
        result = command([IR, source])
        expect(result.stdout.startswith("CRUNCH-IR 2\n"),
               "null global pointer initializer unnecessarily changed the IR version")
        source.write_text("int value, *pointer = &value, *copy = pointer; "
                          "int main() { return 0; }\n")
        result = command([IR, source], check=False)
        expect_clean_rejection(result, "nonconstant global pointer initializer")
        provider, consumer = td / "provider.bc", td / "consumer.bc"
        source.write_text("int value = 40, *pointer = &value; "
                          "int main() { return *pointer + 2; }\n")
        ir, _ = compile_run(source, 42)
        expect(ir.startswith("CRUNCH-IR 12\n"),
               "global address initializer did not select IR v12")
        provider.write_text("int value = 40, *pointer = &value;\n")
        consumer.write_text("extern int value, *pointer; "
                            "int main() { return *pointer + (value - 38); }\n")
        objects = [td / "provider.o", td / "consumer.o"]
        for unit, obj in zip((provider, consumer), objects):
            command([BUILD / "crunch", "-c", unit, "-o", obj])
        exe = td / "program"
        command([BUILD / "crunch", *objects, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "mixed extern declarations failed across modules")


