    command([ASM, "--validate"], input=ir)
    command([ASM, "--validate"], input=command([IR, "--module", fixture]).stdout)
    with tempfile.TemporaryDirectory(prefix="crunch-designated-init-") as directory:
        td = pathlib.Path(directory)
        exe = td / "program"
        command([BUILD / "crunch", "--dynamic", "--pie", fixture, "-o", exe])
        expect(command([exe], check=False).returncode == 42,
               "designated initializers failed in a dynamic PIE")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            command(["cc", "-w", "-std=c11", "-pedantic-errors", "-x", "c",
                     fixture, "-o", exe])
