def zero_length_array_case():
    """Check zero-length member layout, constraints, and host aggregate ABI.

    Returns:
        None; raises AssertionError for incorrect behavior.
    """
    fixture = FIXTURES / "units/types/zero_length_array.bc"
    sema_case(fixture, True)
    compile_run(fixture, 42)
    with tempfile.TemporaryDirectory(prefix="crunch-zero-array-") as directory:
        td = pathlib.Path(directory)
        source = td / "invalid.bc"
        for text in (
            "struct S { int a[0]; };",
            "struct S { int n; int a[0]; int b; };",
            "union U { int n; int a[0]; };",
            "struct S { int n; void a[0]; };",
            "int a[0];",
            "struct S { int n; int a[0]; }; struct S s = {1, {2}};",
            "struct S { int n; int a[0]; }; struct S s = {.a = {2}};",
        ):
            source.write_text(text + "\n")
            sema_case(source, False)
        gcc = shutil.which("gcc")
        if not gcc or os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1":
            return
        executable = td / "fixture"
        command([gcc, "-std=gnu11", "-x", "c", fixture, "-o", executable])
        expect(command([executable], check=False).returncode == 42,
               "GCC disagreed on zero-length array layout")
        declaration = """
struct I { long n; long double data[0]; };
struct F { double n; long double data[0]; };
struct I make_i(long);
struct F make_f(double);
long take_i(struct I, long);
double take_f(struct F, double);
long spill_i(long, long, long, long, long, long, struct I, long);
double spill_f(double, double, double, double, double, double, double, double,
               struct F, double);
"""
        provider, consumer = td / "provider.bc", td / "consumer.bc"
        provider.write_text(declaration + """
struct I make_i(long n) { struct I x = { n }; return x; }
struct F make_f(double n) { struct F x = { n }; return x; }
long take_i(struct I x, long n) { return x.n + n; }
double take_f(struct F x, double n) { return x.n + n; }
long spill_i(long a, long b, long c, long d, long e, long f, struct I x, long n) {
    return a + b + c + d + e + f + x.n + n;
}
double spill_f(double a, double b, double c, double d, double e, double f,
               double g, double h, struct F x, double n) {
    return a + b + c + d + e + f + g + h + x.n + n;
}
""")
        consumer.write_text(declaration + """
int check(void) {
    struct I x = make_i(10);
    struct F y = make_f(10.0);
    return take_i(x, 32) != 42 || take_f(y, 32.0) != 42.0 ||
           spill_i(0, 0, 0, 0, 0, 0, x, 32) != 42 ||
           spill_f(0., 0., 0., 0., 0., 0., 0., 0., y, 32.) != 42.0;
}
""")
        harness = td / "harness.c"
        harness.write_text("int check(void); int main(void) { return check(); }\n")
        for crunch_source, host_source in ((provider, consumer), (consumer, provider)):
            crunch_obj, host_obj = td / "crunch.o", td / "host.o"
            command([DRIVER, "-c", crunch_source, "-o", crunch_obj])
            command([gcc, "-std=gnu11", "-Wno-psabi", "-x", "c", "-c",
                     host_source, "-o", host_obj])
            command([gcc, harness, crunch_obj, host_obj, "-o", executable])
            expect(command([executable], check=False).returncode == 0,
                   f"zero-length aggregate host ABI failed: {crunch_source.name}")


def flexible_array_case():
    """Exercise flexible members, constraints, and the System V aggregate ABI.

    Returns:
        None; raises AssertionError for incorrect behavior.
    """
    fixture = FIXTURES / "units/types/flexible_array.bc"
    sema_case(fixture, True)
    ir, _ = compile_run(fixture, 42)
    expect(ir.startswith("CRUNCH-IR 46\n") and "agg16a1i" in ir,
           "flexible aggregate ABI missing from executable IR")
    module = command([IR, "--module", fixture]).stdout
    expect(module.startswith("CRUNCH-IR 47\n"), "flexible aggregate module version missing")
    command([ASM, "--validate"], input=module)
    command([ASM, "--validate"],
            input=module.replace("CRUNCH-IR 47\n", "CRUNCH-IR 45\n", 1))
    expect_clean_rejection(command([ASM, "--validate"],
                                  input=module.replace("CRUNCH-IR 47\n", "CRUNCH-IR 43\n", 1),
                                  check=False), "new aggregate ABI in older IR")
    with tempfile.TemporaryDirectory(prefix="crunch-flexible-array-") as directory:
        td = pathlib.Path(directory)
        source = td / "invalid.bc"
        for text in (
            "struct S { int a[]; };",
            "struct S { int n; int a[]; int b; };",
            "union U { int n; int a[]; };",
            "struct S { int n; void a[]; };",
            "struct S { int n; int a[]; }; struct S a[2];",
            "struct S { int n; int a[]; }; struct T { struct S s; };",
            "struct S { int n; int a[]; }; struct S s = {1, {2}};",
            "struct S { int n; int a[]; }; int f(struct S *s) { return sizeof(s->a); }",
            "struct S { int n; const int a[]; }; void f(struct S *s) { s->a[0] = 1; }",
        ):
            source.write_text(text + "\n")
            sema_case(source, False)
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") == "1":
            return
        declaration = """
struct I { long n; long double data[]; };
struct F { double n; long double data[]; };
union U { struct I item; long value; };
struct I make_i(long);
struct F make_f(double);
long take_i(struct I, long);
long spill(long, long, long, long, long, long, struct I, long);
double take_f(struct F, double);
double spill_f(double, double, double, double, double, double, double, double,
               struct F, double);
long take_u(union U, long);
long variadic(int, ...);
long variadic_spill(int, ...);
double variadic_f(int, ...);
"""
        provider = td / "provider.bc"
        consumer = td / "consumer.bc"
        provider.write_text("#include <stdarg.h>\n" + declaration + """
struct I make_i(long n) { struct I x = { n }; return x; }
struct F make_f(double n) { struct F x = { n }; return x; }
long take_i(struct I x, long n) { return x.n + n; }
long spill(long a, long b, long c, long d, long e, long f, struct I x, long n) {
    return a + b + c + d + e + f + x.n + n;
}
double take_f(struct F x, double n) { return x.n + n; }
double spill_f(double a, double b, double c, double d, double e, double f,
               double g, double h, struct F x, double n) {
    return a + b + c + d + e + f + g + h + x.n + n;
}
long take_u(union U x, long n) { return x.item.n + n; }
long variadic(int marker, ...) {
    va_list ap; va_start(ap, marker);
    struct I x = va_arg(ap, struct I);
    long n = va_arg(ap, long);
    va_end(ap); return x.n + n;
}
long variadic_spill(int marker, ...) {
    va_list ap; va_start(ap, marker);
    for (int i = 0; i < 6; ++i) va_arg(ap, long);
    struct I x = va_arg(ap, struct I);
    long n = va_arg(ap, long);
    va_end(ap); return x.n + n;
}
double variadic_f(int marker, ...) {
    va_list ap; va_start(ap, marker);
    struct F x = va_arg(ap, struct F);
    double n = va_arg(ap, double);
    va_end(ap); return x.n + n;
}
""")
        consumer.write_text(declaration + """
int check(void) {
    struct I x = make_i(10);
    struct F y = make_f(10.0);
    union U u; u.item = x;
    long (*indirect)(struct I, long) = take_i;
    if (take_i(x, 32) != 42 || spill(0,0,0,0,0,0,x,32) != 42 ||
        take_f(y, 32.0) != 42.0 ||
        spill_f(0.,0.,0.,0.,0.,0.,0.,0.,y,32.) != 42.0 ||
        take_u(u, 32) != 42 || indirect(x, 32) != 42 ||
        variadic(0, x, 32L) != 42 || variadic_f(0, y, 32.0) != 42.0 ||
        variadic_spill(0,0L,0L,0L,0L,0L,0L,x,32L) != 42) return 1;
    return 0;
}
""")
        exe = td / "interop"
        harness = td / "harness.c"
        harness.write_text("int check(void); int main(void) { return check(); }\n")
        for crunch_source, host_source in ((provider, consumer), (consumer, provider)):
            crunch_obj, host_obj = td / "crunch.o", td / "host.o"
            command([DRIVER, "-c", crunch_source, "-o", crunch_obj])
            command(["cc", "-std=c11", "-x", "c", "-c", host_source, "-o", host_obj])
            command(["cc", harness, crunch_obj, host_obj, "-o", exe])
            expect(command([exe], check=False).returncode == 0,
                   f"flexible aggregate host ABI failed: {crunch_source.name}")


