def pragma_pack_abi_case():
    """Compare packed layouts and aggregate calls with the host compiler.

    Returns:
        None; raises AssertionError for a layout or ABI mismatch.
    """
    header = """
#pragma pack(push, 1)
struct Tiny { char tag; int value; };
struct Large { char tag; long value; int tail; };
struct Bits { char tag; unsigned value:20; unsigned other:7; };
struct Zero { char tag; unsigned :0; char end; };
struct Explicit { char tag; _Alignas(8) int value; char end; };
union PackedUnion { char tag; int value; };
struct Nested { char tag; struct Tiny inner; };
struct Aligned { int value; };
#pragma pack(pop)
#pragma pack(push, 2)
struct Two { char tag; int value; short tail; };
#pragma pack(pop)
#pragma pack(push, 4)
struct PackedBits { char tag; unsigned x:27; unsigned y:10; char end; };
#pragma pack(pop)
struct Normal { char tag; int value; };
_Static_assert(sizeof(struct Tiny) == 5 && _Alignof(struct Tiny) == 1, "tiny");
_Static_assert(sizeof(struct Large) == 13 && _Alignof(struct Large) == 1, "large");
_Static_assert(sizeof(struct Zero) == 5 && _Alignof(struct Zero) == 1, "zero");
_Static_assert(sizeof(struct Explicit) == 6 && _Alignof(struct Explicit) == 1, "alignas");
_Static_assert(sizeof(union PackedUnion) == 4 && _Alignof(union PackedUnion) == 1, "union");
_Static_assert(sizeof(struct Nested) == 6 && _Alignof(struct Nested) == 1, "nested");
_Static_assert(sizeof(struct Two) == 8 && _Alignof(struct Two) == 2, "two");
_Static_assert(sizeof(struct PackedBits) == 8 && _Alignof(struct PackedBits) == 4, "packed bits");
_Static_assert(sizeof(struct Normal) == 8 && _Alignof(struct Normal) == 4, "normal");
"""
    provider = header + """
struct Tiny reverse_tiny(struct Tiny p);
struct Large reverse_large(struct Large p);
int reverse_bits(struct Bits p);
int reverse_aligned(struct Aligned p);
struct Tiny forward_tiny(struct Tiny p) { p.value += 3; return p; }
struct Large forward_large(struct Large p) { p.value += 3; p.tail += 1; return p; }
int forward_nested(struct Nested p) { return p.tag == 4 && p.inner.value == 42; }
int forward_aligned(struct Aligned p) { return p.value == 42; }
int call_reverse(void) {
    struct Tiny t = {7, 39};
    struct Large l = {8, 39, 9};
    struct Bits b = {2, 0xabcde, 65};
    struct Aligned a = {42};
    t = reverse_tiny(t);
    l = reverse_large(l);
    return t.tag == 7 && t.value == 42 && l.tag == 8 && l.value == 42 &&
           l.tail == 10 && reverse_bits(b) && reverse_aligned(a);
}
"""
    consumer = header + """
struct Tiny forward_tiny(struct Tiny p);
struct Large forward_large(struct Large p);
int forward_nested(struct Nested p);
int forward_aligned(struct Aligned p);
int call_reverse(void);
struct Tiny reverse_tiny(struct Tiny p) { p.value += 3; return p; }
struct Large reverse_large(struct Large p) { p.value += 3; p.tail += 1; return p; }
int reverse_bits(struct Bits p) { return p.tag == 2 && p.value == 0xabcde && p.other == 65; }
int reverse_aligned(struct Aligned p) { return p.value == 42; }
int check(void) {
    struct Tiny t = {7, 39};
    struct Large l = {8, 39, 9};
    struct Nested n = {4, {7, 42}};
    struct Two two;
    struct Zero zero;
    struct PackedBits bits = {0};
    struct Aligned a = {42};
    bits.x = 1;
    bits.y = 1;
    t = forward_tiny(t);
    l = forward_large(l);
    return t.tag == 7 && t.value == 42 && l.tag == 8 && l.value == 42 &&
           l.tail == 10 && forward_nested(n) && forward_aligned(a) && call_reverse() &&
           (char *)&two.value - (char *)&two == 2 &&
           (char *)&zero.end - (char *)&zero == 4 &&
           (char *)&bits.end - (char *)&bits == 6 &&
           ((unsigned char *)&bits)[1] == 1 && ((unsigned char *)&bits)[4] == 8 ? 0 : 1;
}
"""
    with tempfile.TemporaryDirectory(prefix="crunch-pack-abi-") as directory:
        td = pathlib.Path(directory)
        sources = [td / "provider.c", td / "consumer.c"]
        for path, text in zip(sources, (provider, consumer)):
            path.write_text(text)
        harness, exe = td / "main.c", td / "program"
        harness.write_text("int check(void); int main(void) { return check(); }\n")
        crunch_objects = [td / "provider.o", td / "consumer.o"]
        for source, obj in zip(sources, crunch_objects):
            command([DRIVER, "-c", source, "-o", obj])
        command([DRIVER, "--static", harness, *crunch_objects, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "packed aggregates failed in Crunch")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            host_objects = [td / "host-provider.o", td / "host-consumer.o"]
            for source, obj in zip(sources, host_objects):
                command(["cc", "-std=c11", "-w", "-c", source, "-o", obj])
            for pair in ((crunch_objects[0], host_objects[1]),
                         (host_objects[0], crunch_objects[1])):
                command(["cc", harness, *pair, "-o", exe])
                expect(command([exe], check=False).returncode == 0,
                       "packed aggregate ABI differs from host C")


