def volatile_access_case():
    """Verify volatile qualifications and observable memory operations.

    Returns:
        None; raises AssertionError for incorrect typing or emitted accesses.
    """
    fixture = FIXTURES / "units/types/volatile_access.bc"
    tree = json.loads(source_parse(fixture).stdout)
    expect(tree["version"] == 36, "volatile type did not select AST v36")
    cell = next(d for d in tree["declarations"] if d.get("name") == "cell")
    pointer = next(d for d in tree["declarations"] if d.get("name") == "pointer")
    expect(cell["type"]["volatile"] and pointer["type"]["volatile"] and
           pointer["type"]["pointee"]["volatile"], "AST lost volatile qualifiers")
    sema_case(fixture, True)
    ir, assembly = compile_run(fixture, 42)
    observe = ir.split("func observe 0 int\n", 1)[1].split("\nend\n", 1)[0]
    for instruction, count in (("gload cell int\n", 4), ("gstore cell int\n", 2),
                               ("gload pointer ptr\n", 1), ("loadind int\n", 2),
                               ("storeind int\n", 1), ("loadind byte\n", 2)):
        expect(observe.count(instruction) == count,
               f"volatile access count for {instruction!r} differs:\n{observe}")
    observe_asm = assembly.split("observe:\n", 1)[1].split(".global main", 1)[0]
    expect(observe_asm.count("movslq cell(%rip), %rax") == 4 and
           observe_asm.count("movl %eax, cell(%rip)") == 2 and
           observe_asm.count("movzbq (%rax), %rax") == 2,
           "assembly optimization removed or duplicated volatile accesses")

    with tempfile.TemporaryDirectory(prefix="crunch-volatile-") as directory:
        td = pathlib.Path(directory)
        obj, exe, source = td / "test.o", td / "test", td / "types.bc"
        command([DRIVER, "-c", fixture, "-o", obj])
        for flags in (["--static"], ["--dynamic"], ["-pie"]):
            command([DRIVER, *flags, obj, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   f"volatile fixture failed in {flags}")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            command(["cc", "-x", "c", "-std=c11", "-Wall", "-Wextra", "-Werror",
                     fixture, "-o", exe])
            expect(command([exe], check=False).returncode == 42,
                   "host C disagrees with volatile fixture")
        for text, diagnostic in (
                ("volatile int x; int *p = &x;", "incompatible"),
                ("volatile static int x; int *p = &x;", "incompatible"),
                ("volatile extern int x; int *p = &x;", "incompatible"),
                ("volatile typedef int T; T x; int *p = &x;", "incompatible"),
                ("volatile int x; void *p = &x;", "incompatible"),
                ("int *p; volatile int **q = &p;", "incompatible"),
                ("volatile int a[2][3]; int (*p)[3] = a;", "incompatible"),
                ("extern volatile int x; int x;", "conflicting"),
                ("typedef volatile int T; typedef int T;", "conflicting"),
                ("int main(void){int x=0; volatile int y=0; int *p=x?&x:&y;return 0;}",
                 "incompatible"),
                ("struct S {int x;}; int main(void){volatile struct S s={1};"
                 "int *p=&s.x;return 0;}", "incompatible"),
                ("typedef int A[2]; int main(void){volatile A a={1,2};"
                 "int *p=a;return 0;}", "incompatible")):
            source.write_text(text + "\n")
            sema_case(source, False, diagnostic)
        source.write_text('''
typedef int Row[2];
typedef volatile int *volatile Ptr;
typedef volatile int VolatileRow[2];
volatile typedef int LeadingVolatile;
volatile static int leading = 1;
volatile extern int leading_external;
volatile int leading_external = 1;
struct Outer { volatile struct { int value; }; };
int read(volatile int *p);
int read(volatile int *p) { return *p; }
int main(void) {
    volatile Row row = {40,2};
    volatile struct Outer outer = {{0}};
    volatile int (*rows)[2] = &row;
    const volatile VolatileRow readonly = {1, 2};
    const volatile int (*readonly_rows)[2] = &readonly;
    LeadingVolatile alias = 1;
    volatile int *leading_pointer = &leading;
    volatile int *external_pointer = &leading_external;
    volatile int *p = &row[0];
    Ptr q = &row[1];
    outer.value = read(p) + (*rows)[1] + *q + (*readonly_rows)[0] +
                  alias + *leading_pointer + *external_pointer - 6;
    return outer.value;
}
''')
        sema_case(source, True)
        compile_run(source, 42)
        source.write_text('''
struct S {int x;}; volatile struct S a = {1}, b = {2};
int main(void) { (void)a; (a,b); 1 ? a : b; return 42; }
''')
        aggregate_ir, _ = compile_run(source, 42)
        expect(aggregate_ir.count("loadind byte\n") == 5,
               "discarded volatile structure expressions lost reads")
        source.write_text('''
struct S {int x;}; volatile struct S a = {2}, b = {0};
int value(struct S s) { return s.x; }
int main(void) {
    struct S copy;
    struct S *p = &copy;
    copy = a;
    *p = copy;
    (*p = copy, 0);
    b = copy;
    return value(b) + 40;
}
''')
        compile_run(source, 42)


def ignored_qualifiers_case():
    """Check register and volatile keywords across compilation stages.

    Returns:
        None; raises AssertionError for incorrect parsing or execution.
    """
    def without_locations(value):
        """Remove source locations from an AST for structural comparison.

        Args:
            value: AST node or scalar.
        Returns:
            A copy without location fields.
        """
        if isinstance(value, dict):
            return {k: without_locations(v) for k, v in value.items() if k != "location"}
        if isinstance(value, list):
            return [without_locations(v) for v in value]
        return value

    program = '''typedef volatile struct Item { volatile int field; } Item;
typedef volatile int *volatile Ptr;
volatile static int global = 2;
int add(register volatile int value) { return value + global; }
int main() {
    volatile int register x = 1;
    Ptr p = &x;
    volatile int *q = (volatile int *)&x;
    Item item = { 3 };
    for (register int i = 0; i < 2; i++) x++;
    *p = *q + item.field;
    if (sizeof(volatile int) != sizeof(int)) return 1;
    if (add(x) != 8) return 2;
    return 0;
}
'''
    unqualified = re.sub(r'\bregister\b',
                         lambda m: " " * len(m.group()), program)
    with tempfile.TemporaryDirectory(prefix="crunch-ignored-qualifiers-") as directory:
        td = pathlib.Path(directory)
        source, obj, exe = td / "qualifiers.bc", td / "qualifiers.o", td / "qualifiers"
        source.write_text(program)
        tokens = command([LEXER, source]).stdout
        expect("\nVOLATILE\t" in tokens and "\nREGISTER\t" in tokens,
               "missing keyword tokens")
        ast = json.loads(command([PARSER], input=tokens).stdout)
        ir = command([IR, source]).stdout
        for separate in (False, True):
            if separate:
                command([DRIVER, "-c", source, "-o", obj])
                command([DRIVER, obj, "-o", exe])
            else:
                command([DRIVER, source, "-o", exe])
            result = command([exe], check=False)
            expect(result.returncode == 0,
                   f"ignored keywords changed execution: {result.returncode} {result.stderr}")
        source.write_text(unqualified)
        plain_tokens = command([LEXER, source]).stdout
        expect(without_locations(json.loads(command([PARSER], input=plain_tokens).stdout)) ==
               without_locations(ast),
               "register changed AST")
        expect(command([IR, source]).stdout == ir, "register changed IR")

        source.write_text("int main() { volatile struct { volatile int n; } x = { 1 }; "
                          "return x.n - 1; }\n")
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "volatile anonymous structure failed")
        source.write_text("int main() { volatile const int x = 1; x = 2; return x; }\n")
        result = command([IR, source], check=False)
        expect(result.returncode != 0, "volatile suppressed const checking")
        source.write_text("int main() { int register = 1; return register; }\n")
        result = command([IR, source], check=False)
        expect(result.returncode != 0, "register was accepted as an identifier")
        source.write_text("int main() { int volatile = 1; return volatile; }\n")
        result = command([IR, source], check=False)
        expect(result.returncode != 0, "volatile was accepted as an identifier")
        source.write_text(
            "int sum(int n, int a[restrict], int b[const volatile n]) { "
            "a[0] = 4; b[0] = 5; return a[0] + b[0]; }\n"
            "int invoke(int (*f)(int, int [restrict], int [const volatile]), "
            "int a[restrict], int b[restrict]) { return f(1, a, b); }\n"
            "int main(void) { int x[1] = {0}, y[1] = {0}; "
            "return invoke(sum, x, y) != 9 || x[0] != 4 || y[0] != 5; }\n")
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "qualified array parameters failed")
        source.write_text("int f(int a[const]) { a = 0; return 0; }\n")
        expect_clean_rejection(command([IR, source], check=False),
                               "assignment to const-qualified array parameter")
        for text in ("int a[restrict];",
                     "int f(int a[2][restrict 3]);",
                     "int f(int a[static 3]);"):
            source.write_text(text + "\n")
            expect_clean_rejection(command([IR, source], check=False),
                                   f"unsupported array qualifier placement: {text}")


def size_t_format_case():
    """Check size_t formatting, diagnostics, and legacy runtime compatibility.

    Returns:
        None; raises AssertionError for incorrect formatting or diagnostics.
    """
    program = r'''#include <stdio.h>
#include <string.h>
int main() {
    size_t max = (size_t)-1;
    char buffer[32];
    char* dynamic = "%zu";
    if (printf("%zu %05zu %-4zu", (size_t)0, (size_t)7, (size_t)9) != 12) return 1;
    if (fprintf(stderr, "%zu", max) != 20) return 2;
    if (snprintf(buffer, 6, "%zu", max) != 20 || strcmp(buffer, "18446")) return 3;
    if (snprintf(0, 0, dynamic, sizeof(int)) != 1) return 4;
    if (snprintf(buffer, 32, dynamic, sizeof(int)) != 1 || strcmp(buffer, "4")) return 5;
    if (snprintf(buffer, 32, "%025zu", max) != 25 ||
        strcmp(buffer, "0000018446744073709551615")) return 6;
    if (printf("|%zu", strlen("hello")) != 2) return 10;
    if (printf("%zu", 1) != -1 || fprintf(stderr, "%zu", 1U) != -1 ||
        snprintf(buffer, 32, "%zu", (long)-1) != -1) return 7;
    if (snprintf(buffer, 32, "%z", max) != -1 ||
        snprintf(buffer, 32, "%zx", max) != -1 ||
        snprintf(buffer, 32, "%zd", max) != -1 ||
        snprintf(buffer, 32, "%zzu", max) != -1) return 8;
    if (printf("%zu") != -1 || fprintf(stderr, "%zu") != -1 ||
        snprintf(buffer, 32, "%zu") != -1) return 9;
    return 0;
}
'''
    with tempfile.TemporaryDirectory(prefix="crunch-size-format-") as directory:
        td = pathlib.Path(directory)
        source, obj, exe = td / "format.bc", td / "format.o", td / "program"
        source.write_text(program)
        for separate in (False, True):
            if separate:
                command([DRIVER, "-c", source, "-o", obj])
                command([DRIVER, obj, "-o", exe])
            else:
                command([DRIVER, source, "-o", exe])
            result = command([exe], check=False)
            expect(result.returncode == 0 and result.stdout == "0 00007 9   |5" and
                   result.stderr == "18446744073709551615",
                   f"size_t formatting failed in {'module' if separate else 'executable'} mode: "
                   f"{result.returncode} {result.stdout!r} {result.stderr!r}")

        source.write_text('''#include <stdio.h>
int main() {
    printf("%zu %zu", (size_t)1);
    fprintf(stderr, "%05zu", (size_t)1, (size_t)2);
    snprintf(0, 0, "%-4zu");
    printf("%zx", (size_t)1, (size_t)2);
    return 0;
}
''')
        diagnostics = command([DRIVER, "--emit-ir", source]).stderr
        for message in ("printf format expects 2 values but received 1",
                        "fprintf format expects 1 value but received 2",
                        "snprintf format expects 1 value but received 0"):
            expect(message in diagnostics, f"missing size_t format warning: {diagnostics}")
        expect(diagnostics.count("format expects") == 3,
               f"unsupported size modifier produced a warning: {diagnostics}")

        assembly = td / "legacy.s"
        for version in (2, 3, 6, 7):
            op = "runtime_call" if version in (3, 7) else "call"
            ir = (f"CRUNCH-IR {version}\nstringlit fmt 257a7500\nfunc main 0 int\n"
                  f"straddr fmt\npush -1\npush 6\n{op} printf 3\nret int\nend\n")
            assembly.write_text(command([ASM, "-"], input=ir).stdout)
            command([TEST_AS, "-o", obj, assembly])
            command([*TEST_LINK, "-o", exe, obj, LIBCRUNCH])
            result = command([exe], check=False)
            expect(result.returncode == (20 if version in (6, 7) else 255) and
                   result.stdout == ("18446744073709551615" if version in (6, 7) else ""),
                   f"IR v{version} size_t format compatibility failed: "
                   f"{result.returncode} {result.stdout!r} {result.stderr!r}")


def scalar_format_promotions_case():
    """Check scalar arguments to Crunch's supported formatted-output runtime.

    Returns:
        None; raises AssertionError for an incorrect formatted result.
    """
    body = """
int main() {
    char c = (char)255; signed char sc = -128; unsigned char uc = 255;
    short s = -32768; unsigned short us = 65535;
    int i = -123; unsigned int ui = 4294967295U;
    long l = -1234567890123; unsigned long ul = 18446744073709551615UL;
    float f = 1.25f; double d = -2.5;
    printf("%d %d %d %d %d %d %u %ld %lu %f %f\\n",
           c, sc, uc, s, us, i, ui, l, ul, f, d);
    return 0;
}
"""
    expected = ("255 -128 255 -32768 65535 -123 4294967295 -1234567890123 "
                "18446744073709551615 1.250000 -2.500000\n")
    with tempfile.TemporaryDirectory(prefix="crunch-scalar-format-") as directory:
        td = pathlib.Path(directory)
        source, exe = td / "format.bc", td / "format"
        source.write_text("#include <stdio.h>\n" + body)
        for mode in ((), ("--c11-numeric",)):
            command([DRIVER, *mode, source, "-o", exe])
            result = command([exe])
            expect(result.stdout == expected,
                   f"scalar formatted arguments failed in {mode}: {result.stdout!r}")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            host = td / "format.c"
            host.write_text("#include <stdio.h>\n" + body)
            command(["cc", "-std=c11", "-funsigned-char", host, "-o", exe])
            expect(command([exe]).stdout == expected, "host C formatting comparison failed")


def enum_case():
    """Check enum scoping, constants, storage and C ABI.

    Returns:
        None; raises AssertionError for incorrect parsing, diagnostics or execution.
    """
    program = """
enum Color { NEG = -1, RED = 2, GREEN, BLUE = GREEN + 3 };
enum Constants { TRUNCATED = (int)1.5, SAFE = 0 && (1 / 0) };
typedef enum Color Color;
typedef enum { FIRST = 1, SECOND } Other;
enum Color global = BLUE;
enum Color array[2] = {NEG, GREEN};
int bound[GREEN];
struct Box { enum Color value; enum Color items[2]; };
struct Embedded { enum EmbeddedTag { EMBEDDED = 9 } field; };
Color identity(Color x) { return x; }
int main() {
    Color c = identity(RED);
    Other other = SECOND;
    struct Box box;
    struct Embedded embedded;
    embedded.field = EMBEDDED;
    box.value = c; box.items[0] = BLUE;
    static Color saved = NEG;
    if (sizeof(Color) != 4 || sizeof(bound) != 12 || global != 6 ||
        array[0] != -1 || array[1] != 3 || saved != -1 ||
        box.value != 2 || box.items[0] != 6 || other != 2 ||
        embedded.field != 9 || TRUNCATED != 1 || SAFE != 0) return 1;
    if ((int)(enum Color)3.9 != 3 || sizeof(+c) != sizeof(int)) return 2;
    switch (global) { case RED: return 3; case BLUE: break; default: return 4; }
    { enum Color { RED = 10, INNER = RED + 1 };
      enum Color local = INNER;
      if (local != 11 || RED != 10) return 5; }
    if (RED != 2) return 6;
    enum Loop { ONCE = 1 };
    for (enum Loop i = ONCE; i; --i) {
        if (ONCE != 1) return 7;
    }
    return 0;
}
"""
    provider = """
enum E { LOW=-1, HIGH=7 };
enum E value = HIGH;
enum E flip(enum E v) { return v == LOW ? HIGH : LOW; }
int edit(enum E *p) { *p = LOW; return *p; }
"""
    consumer = """
enum E { LOW=-1, HIGH=7 };
extern enum E value;
enum E flip(enum E v);
int edit(enum E *p);
int main() { enum E x = HIGH;
    return value != HIGH || flip(x) != LOW || edit(&x) != LOW || x != LOW;
}
"""
    scoped_program = """
int size = sizeof(enum Global { GLOBAL_VALUE = 3 });
int global_bound[GLOBAL_VALUE];
struct Shared { int outer; };
int parameter(enum Parameter { PARAM_VALUE = 4 } p) {
    return p == PARAM_VALUE;
}
int main() {
    int x = (enum Cast { CAST_VALUE = 2 })CAST_VALUE;
    int n = sizeof(enum Size { SIZE_VALUE = 5 });
    struct Local { enum Field { FIELD_VALUE = 3 } e; int a[FIELD_VALUE]; };
    struct Local local;
    local.a[0] = FIELD_VALUE;
    typedef struct Alias { int a[SIZE_VALUE]; } Alias;
    Alias alias;
    alias.a[0] = SIZE_VALUE;
    { enum Shared { INNER_VALUE = 6 }; if (INNER_VALUE != 6) return 1; }
    struct Shared outer;
    outer.outer = 7;
    { enum Local { LOCAL_VALUE = 8 };
      { struct Local { int value; } inner;
        inner.value = LOCAL_VALUE;
        if (inner.value != 8) return 2; } }
    return x != 2 || n != 4 || size != 4 || sizeof(global_bound) != 12 ||
           local.a[0] != 3 || alias.a[0] != 5 || outer.outer != 7 ||
           !parameter(4);
}
"""
    compatible_program = """
enum E { NEGATIVE = -1, POSITIVE = 2 };
int read_value(enum E *p);
int read_value(int *p) { return *p; }
enum E identity(enum E value);
int identity(int value) { return value; }
int main() {
    enum E value = NEGATIVE;
    int *p = &value;
    enum E *ep = p;
    int **pp = &ep;
    const int *cp = ep;
    if (*cp != -1 || read_value(ep) != -1 || identity(value) != -1) return 1;
    **pp = POSITIVE;
    if (value != POSITIVE) return 2;
    int n = 7;
    ep = &n;
    return *ep != 7;
}
"""
    underlying_program = """
enum Positive { ZERO = 0, ONE = 1 };
enum Negative { BELOW = -1 };
typedef enum Positive Positive;
enum Positive global_positive = (enum Positive)-1;
enum Positive values[] = { (enum Positive)-1, ONE };
enum Constant { CONSTANT_TEST = (enum Positive)-1 > 0 };
int parameter(unsigned int value);
int parameter(enum Parameter { PARAM_ZERO = 0 } value) { return value == PARAM_ZERO; }
int main() {
    Positive x = (Positive)-1;
    enum Negative y = BELOW;
    unsigned int *up = &x;
    int *ip = &y;
    long wide = x;
    double real = x;
    static Positive saved = (Positive)-1;
    if (*up != 4294967295U || *ip != -1 || wide != 4294967295L ||
        real != 4294967295.0 || saved != 4294967295U ||
        global_positive != 4294967295U || values[0] != 4294967295U ||
        CONSTANT_TEST != 1 || (x >> 31) != 1 || x % 3 != 0 ||
        (x - 2) < 0 || !parameter(0)) return 1;
    if (+x != 4294967295U || ~x != 0 || -x != 1) return 2;
    x >>= 31;
    if (x != 1) return 3;
    x = 0; x -= 1; x /= 2;
    if (x != 2147483647U) return 4;
    x = (Positive)4294967295.0;
    if (x++ != 4294967295U || x != 0) return 5;
    x = (Positive)-1;
    switch (x) { case -1: break; default: return 6; }
    x = y;
    if ((long)x != 4294967295L) return 7;
    y = x;
    if (y != -1) return 8;
    Positive *xp = &x;
    enum Negative *yp = &y;
    if ((*xp)++ != 4294967295U || (*yp)++ != -1 || x != 0 || y != 0) return 9;
    return 0;
}
"""
    formatting_program = """
#include <stdio.h>
enum U { UZERO = 0 };
enum S { SMINUS = -1 };
int main() {
    enum U u = (enum U)-1;
    enum S s = SMINUS;
    return printf("%u %d", u, s) != 13;
}
"""
    unsigned_provider = """
enum E { ZERO=0, ONE=1 };
enum E value = (enum E)-1;
enum E pass(enum E x) { return x; }
unsigned long widen(enum E x) { return x; }
int edit(enum E *p) { *p = (enum E)-1; return *p > 0; }
"""
    unsigned_consumer = """
enum E { ZERO=0, ONE=1 };
extern enum E value;
enum E pass(enum E x);
unsigned long widen(enum E x);
int edit(enum E *p);
int main() {
    enum E x = ZERO;
    return value != 4294967295U || pass(value) != 4294967295U ||
           widen(value) != 4294967295UL || !edit(&x) || x != 4294967295U;
}
"""
    with tempfile.TemporaryDirectory(prefix="crunch-enum-") as directory:
        td = pathlib.Path(directory)
        source, exe = td / "enum.bc", td / "program"
        source.write_text(program)
        tree = json.loads(source_parse(source).stdout)
        expect(tree["version"] == 23 and tree["declarations"][0]["kind"] == "enum",
               "enum AST version or declaration incorrect")
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 0, "enum execution failed")
        host_mode = os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1"
        if host_mode:
            host = td / "enum.c"
            host.write_text(program)
            command(["cc", "-std=c11", "-funsigned-char", host, "-o", exe])
            expect(command([exe], check=False).returncode == 0, "host C enum differs")
        source.write_text(scoped_program)
        scoped_tree = json.loads(source_parse(source).stdout)
        expect(scoped_tree["version"] == 24 and
               '"struct_scope"' in json.dumps(scoped_tree) and
               '"enum_definition"' in json.dumps(scoped_tree),
               "scoped enum AST representation incorrect")
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 0, "scoped enum execution failed")
        if host_mode:
            host.write_text(scoped_program)
            command(["cc", "-std=c11", "-funsigned-char", host, "-o", exe])
            expect(command([exe], check=False).returncode == 0, "host C scoped enum differs")
        source.write_text(compatible_program)
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "enum-compatible int declarations or pointers failed")
        if host_mode:
            host.write_text(compatible_program)
            command(["cc", "-std=c11", "-pedantic-errors", "-funsigned-char", host, "-o", exe])
            expect(command([exe], check=False).returncode == 0,
                   "host C enum-compatible int behavior differs")
        source.write_text(underlying_program)
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "enum underlying-type arithmetic or storage failed")
        if host_mode:
            host.write_text(underlying_program)
            command(["cc", "-std=c11", "-pedantic-errors", "-funsigned-char", host, "-o", exe])
            expect(command([exe], check=False).returncode == 0,
                   "host C enum underlying-type behavior differs")
        source.write_text(formatting_program)
        command([DRIVER, source, "-o", exe])
        formatted = command([exe], check=False)
        expect(formatted.returncode == 0 and formatted.stdout == "4294967295 -1",
               "enum formatted arguments used incorrect signedness")
        for code in ("enum E { A=2147483648 };",
                     "enum E { A=2147483647, B };",
                     "enum E { A=2147483647+1 };",
                     "enum E { A=(1 << 31) };",
                     "enum E { A=1.0 < 2.0 };",
                     "enum E { A=(int)(1.0+2.0) };",
                     "enum E { A=sizeof(enum E) };",
                     "enum E { A }; int main() { enum E; enum E x=A; return x; }",
                     "enum E { A, A };",
                     "int main() { { enum { A=1 }; } return A; }",
                     "enum E { A }; struct E { int member; };",
                     "struct E { int member; }; enum E { A };",
                     "int f(enum P { A=1 } x); int main() { return A; }",
                     "int f(enum P { A=1 } x) { enum P { B=2 }; return x; }",
                     "int main() { struct S { int x[A]; enum E { A=2 } e; }; return 0; }",
                     "int main() { struct S { int x; }; struct S { int y; }; return 0; }",
                     "enum E { A }; int main() { struct E { int x; }; enum E x; return 0; }",
                     "enum E { A }; int main() { A=1; return 0; }",
                     "enum E { A }; int main() { return *(&A); }",
                     "int main() { for (enum E { A=1 } x=A; x; --x) {} return 0; }",
                     "enum A { X }; enum B { Y }; int main() { enum A *a; enum B *b; a=b; return 0; }",
                     "enum E { A=-1 }; int main() { enum E x=A; unsigned int *p=&x; return 0; }",
                     "enum E { A=1 }; int main() { enum E x=A; int *p=&x; return 0; }",
                     "enum E { A=1 }; int f(enum E *p); int f(int *p) { return *p; }",
                     "enum E { A=-1 }; int main() { const enum E x=A; int *p=&x; return 0; }",
                     "enum E { A=-1 }; typedef enum E T; typedef int T;",
                     "enum E { A=-1 }; int main() { typedef enum E *T; typedef int *T; return 0; }",
                     "int x = A; enum E { A=1 }; int main(){return x;}"):
            result = command([IR, "-"], input=code + "\n", check=False)
            expect(result.returncode != 0, f"invalid enum program accepted: {code}")
        sources = [td / "provider.bc", td / "consumer.bc"]
        objects = [td / "provider.o", td / "consumer.o"]
        for path, obj, text in zip(sources, objects, (provider, consumer)):
            path.write_text(text)
            command([DRIVER, "-c", path, "-o", obj])
        command([DRIVER, *objects, "-o", exe])
        expect(command([exe], check=False).returncode == 0, "Crunch enum module ABI failed")
        if host_mode:
            host_objects = [td / "provider-c.o", td / "consumer-c.o"]
            for i, (text, obj) in enumerate(zip((provider, consumer), host_objects)):
                host = td / f"abi-{i}.c"
                host.write_text(text)
                command(["cc", "-std=c11", "-funsigned-char", "-c", host, "-o", obj])
            for pair, flags in (((objects[0], host_objects[1]), ()),
                                ((host_objects[0], objects[1]), ("-nostartfiles",))):
                command(["cc", "-no-pie", *flags, *pair, "-o", exe])
                expect(command([exe], check=False).returncode == 0, "enum C ABI failed")
        for path, obj, text in zip(sources, objects, (unsigned_provider, unsigned_consumer)):
            path.write_text(text)
            command([DRIVER, "-c", path, "-o", obj])
        command([DRIVER, *objects, "-o", exe])
        expect(command([exe], check=False).returncode == 0, "unsigned enum module ABI failed")
        if host_mode:
            for i, (text, obj) in enumerate(zip((unsigned_provider, unsigned_consumer), host_objects)):
                host = td / f"unsigned-abi-{i}.c"
                host.write_text(text)
                command(["cc", "-std=c11", "-pedantic-errors", "-c", host, "-o", obj])
            for pair, flags in (((objects[0], host_objects[1]), ()),
                                ((host_objects[0], objects[1]), ("-nostartfiles",))):
                command(["cc", "-no-pie", *flags, *pair, "-o", exe])
                expect(command([exe], check=False).returncode == 0, "unsigned enum C ABI failed")


def bool_case():
    """Check boolean conversion, storage, promotions and scalar ABI.

    Returns:
        None; raises AssertionError for incorrect parsing, execution or linkage.
    """
    program = """
#include <stdbool.h>
#if !__bool_true_false_are_defined
#error missing bool macros
#endif
int item;
_Bool a = -4, b = 0.25, c = 0.0, d = &item, e = (void *)0;
_Bool cast_address = (_Bool)&item;
_Bool values[5] = { 2, -3, 0, (_Bool)&item, (_Bool)(void *)0 };
int bound[(_Bool)0.25];
struct Box { _Bool value; char pad; };
_Bool id(_Bool value) { return value; }
int main() {
    bool v = 7;
    double zero = 0.0;
    double nan = zero / zero;
    double infinity = 1.0 / zero;
    int *p = &item;
    char ch = 2;
    _Bool literal_address = "text";
    static _Bool saved = 1.5;
    struct Box box;
    box.value = 25;
    if (sizeof(bool) != 1 || sizeof(box) != 2 || a != 1 || b != 1 ||
        c != 0 || d != 1 || e != 0 || values[0] != 1 ||
        values[1] != 1 || values[2] != 0 || values[3] != 1 ||
        values[4] != 0 || cast_address != 1 || literal_address != 1 ||
        saved != 1 || box.value != 1 || sizeof(bound) != sizeof(int)) return 1;
    if (v != true || id(-9) != 1 || (_Bool)nan != 1 ||
        (_Bool)(-zero) != 0 || (_Bool)infinity != 1 ||
        (_Bool)p != 1 || (_Bool)(void *)0 != 0) return 2;
    v = ch; if (v != 1) return 9;
    v = 0; if (v++ != 0 || v != 1) return 3;
    if (v++ != 1 || v != 1) return 4;
    v--; if (v != 0) return 5;
    v += 5; if (v != 1) return 6;
    v *= 0; if (v != 0 || sizeof(+v) != sizeof(int)) return 7;
    switch (1) { case (_Bool)0.25: break; default: return 8; }
    return 0;
}
"""
    provider = """
struct Box { _Bool value; char pad; };
_Bool flip(_Bool value) { return !value; }
_Bool seventh(int a, int b, int c, int d, int e, int f, _Bool value) { return value; }
int change(struct Box *b, _Bool value) { b->value = value; return b->value; }
"""
    consumer = """
struct Box { _Bool value; char pad; };
_Bool flip(_Bool value);
_Bool seventh(int a, int b, int c, int d, int e, int f, _Bool value);
int change(struct Box *b, _Bool value);
int main() {
    struct Box b;
    if (flip(1) != 0 || flip(0) != 1 || seventh(1,2,3,4,5,6,9) != 1) return 1;
    if (change(&b, 3) != 1 || b.value != 1) return 2;
    return 0;
}
"""
    with tempfile.TemporaryDirectory(prefix="crunch-bool-") as directory:
        td = pathlib.Path(directory)
        source, exe = td / "bool.bc", td / "program"
        source.write_text(program)
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 0, "boolean execution failed")
        host_mode = os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1"
        if host_mode:
            host = td / "bool.c"
            host.write_text(program)
            command(["cc", "-std=c11", "-funsigned-char", host, "-o", exe])
            expect(command([exe], check=False).returncode == 0, "host C boolean differs")
        source.write_text("_Bool b;\n")
        tree = json.loads(source_parse(source).stdout)
        expect(tree["version"] == 22 and tree["declarations"][0]["type"]["kind"] == "bool",
               "boolean AST version or type incorrect")
        for code in ("_Bool *p; char *q; int main() { p = q; return 0; }",
                     "_Bool f(int x); char f(int x);"):
            result = command([IR, "-"], input=code + "\n", check=False)
            expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
                   f"incompatible boolean types accepted: {code}")
        sources = [td / "provider.bc", td / "consumer.bc"]
        objects = [td / "provider.o", td / "consumer.o"]
        for path, obj, text in zip(sources, objects, (provider, consumer)):
            path.write_text(text)
            command([DRIVER, "-c", path, "-o", obj])
        command([DRIVER, *objects, "-o", exe])
        expect(command([exe], check=False).returncode == 0, "Crunch boolean module ABI failed")
        if host_mode:
            host_objects = [td / "provider-c.o", td / "consumer-c.o"]
            for i, (text, obj) in enumerate(zip((provider, consumer), host_objects)):
                host = td / f"abi-{i}.c"
                host.write_text(text)
                command(["cc", "-std=c11", "-funsigned-char", "-c", host, "-o", obj])
            for pair, flags in (((objects[0], host_objects[1]), ()),
                                ((host_objects[0], objects[1]), ("-nostartfiles",))):
                command(["cc", "-no-pie", *flags, *pair, "-o", exe])
                expect(command([exe], check=False).returncode == 0, "boolean C ABI failed")


def long_long_case():
    """Check long long typing, conversions, storage and C ABI interoperability.

    Returns:
        None; raises AssertionError for incorrect parsing, execution or linkage.
    """
    program = """
#include <limits.h>
#if LLONG_MAX != 9223372036854775807LL || ULLONG_MAX != 18446744073709551615ULL
#error incorrect long long limits
#endif
long long minimum = LLONG_MIN;
unsigned long long maximum = ULLONG_MAX;
int mixed_constant = -1LL < 1UL;
int bound[(-1LL < 1UL) ? 1 : 2];
long long narrow = 0x7fffffffffffffffLL;
unsigned long long wide = 0xffffffffffffffffLL;
double real_maximum = 18446744073709551615ULL;
struct Pair { long long signed_value; unsigned long long unsigned_value; };
int main() {
    long long x = -1LL;
    unsigned long y = 1UL;
    unsigned long long z = 18446744073709551615ULL;
    long long values[2] = {LLONG_MIN, 42LL};
    static unsigned long long saved = 18446744073709551615ULL;
    struct Pair p;
    p.signed_value = values[0]; p.unsigned_value = z;
    if (sizeof(long long) != 8 || sizeof(unsigned long long) != 8 ||
        sizeof(bound) != 8 || mixed_constant || x < y || -1LL < 1UL) return 1;
    if (minimum != LLONG_MIN || narrow != LLONG_MAX || maximum != z ||
        wide != z || z + 1ULL != 0 || p.signed_value != minimum) return 2;
    if ((z >> 63) != 1 || p.unsigned_value / 2 != 9223372036854775807ULL ||
        (long long)3.9 != 3 || (unsigned long long)3.9 != 3ULL ||
        (double)z != real_maximum || saved != z) return 3;
    if ((-1LL < 1U) != 1 || (1 ? -1LL : 1UL) < 0 ||
        (values[1]++ != 42LL) || values[1] != 43LL) return 4;
    switch (0) { case (-1LL < 1UL): break; default: return 5; }
    switch (z) { case 18446744073709551615ULL: break; default: return 6; }
    return 0;
}
"""
    provider = """
struct Box { long long s; unsigned long long u; };
long long signed_global = -9223372036854775807LL - 1;
unsigned long long unsigned_global = 18446744073709551615ULL;
long long signed_call(int a, int b, int c, int d, int e, int f, long long x) {
    return x + a + b + c + d + e + f;
}
unsigned long long unsigned_call(unsigned long long x) { return x + 1ULL; }
long long edit(struct Box *p) {
    p->s = p->s + 2LL; p->u = p->u + 1ULL; return p->s;
}
"""
    consumer = """
struct Box { long long s; unsigned long long u; };
extern long long signed_global;
extern unsigned long long unsigned_global;
long long signed_call(int a, int b, int c, int d, int e, int f, long long x);
unsigned long long unsigned_call(unsigned long long x);
long long edit(struct Box *p);
int main() {
    struct Box p; p.s = -4LL; p.u = unsigned_global;
    if (signed_global != -9223372036854775807LL - 1 ||
        unsigned_global != 18446744073709551615ULL) return 1;
    if (signed_call(1, 2, 3, 4, 5, 6, 10000000000LL) != 10000000021LL ||
        unsigned_call(p.u) != 0 || edit(&p) != -2 || p.u != 0) return 2;
    return 0;
}
"""
    with tempfile.TemporaryDirectory(prefix="crunch-long-long-") as directory:
        td = pathlib.Path(directory)
        source, exe = td / "types.bc", td / "program"
        source.write_text(program)
        command([DRIVER, source, "-o", exe])
        expect(command([exe], check=False).returncode == 0, "long long execution failed")
        host_mode = os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1"
        if host_mode:
            host = td / "types.c"
            host.write_text(program)
            command(["cc", "-std=c11", "-funsigned-char", host, "-o", exe])
            expect(command([exe], check=False).returncode == 0, "host C long long differs")

        for suffix, normalized in (("ll", "ll"), ("LL", "ll"), ("uLL", "ull"),
                                   ("LLu", "ull"), ("Ull", "ull"), ("llU", "ull")):
            source.write_text(f"long long value = 42{suffix};\n")
            tree = json.loads(source_parse(source).stdout)
            literal = tree["declarations"][0]["initializer"]["expression"]
            expect(tree["version"] == 21 and literal["value"] == "42" and
                   literal["suffix"] == normalized, f"invalid AST suffix {suffix}")
        source.write_text("unsigned long value = 42UL;\n")
        expect(json.loads(source_parse(source).stdout)["version"] == 15,
               "existing UL suffix changed AST version")
        for literal in ("1lL", "1Ll", "1uLl", "1LLUu", "1LLL"):
            source.write_text(f"int main() {{ return {literal}; }}\n")
            expect(command([LEXER, source], check=False).returncode != 0,
                   f"invalid suffix accepted: {literal}")
        source.write_text("#if 1lL\nint value;\n#endif\n")
        expect(command([PP, source], check=False).returncode != 0,
               "mixed-case long long suffix accepted in #if")
        for literal in ("9223372036854775808LL", "18446744073709551616ULL"):
            result = command([IR, "-"], input=f"long long x = {literal};\n", check=False)
            expect(result.returncode != 0, f"out-of-range literal accepted: {literal}")
        for expression in ("1LL << 64", "1ULL >> 64",
                           "(-9223372036854775807LL - 1) / -1LL"):
            result = command([IR, "-"], input=f"long long x = {expression};\n", check=False)
            expect(result.returncode != 0, f"invalid constant accepted: {expression}")
        for code in ("long *p; long long *q; int main() { p = q; return 0; }",
                     "unsigned long *p; unsigned long long *q; int main() { p = q; return 0; }",
                     "long f(int x); long long f(int x); int main() { return 0; }"):
            result = command([IR, "-"], input=code + "\n", check=False)
            expect(result.returncode != 0 and "E_SEMANTIC" in result.stderr,
                   f"incompatible types accepted: {code}")
        source.write_text('#include <stdio.h>\nint main() { '
                          'printf("%lld %llu %llx\\n", -42LL, '
                          '18446744073709551615ULL, 255ULL); return 0; }\n')
        command([DRIVER, source, "-o", exe])
        expect(command([exe]).stdout == "-42 18446744073709551615 ff\n",
               "long long formatted output differs")

        sources = [td / "provider.bc", td / "consumer.bc"]
        for path, text in zip(sources, (provider, consumer)):
            path.write_text(text)
        objects = [td / "provider.o", td / "consumer.o"]
        for path, obj in zip(sources, objects):
            command([DRIVER, "-c", path, "-o", obj])
        command([DRIVER, *objects, "-o", exe])
        expect(command([exe], check=False).returncode == 0, "Crunch long long module ABI failed")
        if host_mode:
            host_objects = [td / "provider-c.o", td / "consumer-c.o"]
            for i, (text, obj) in enumerate(zip((provider, consumer), host_objects)):
                host = td / f"abi-{i}.c"
                host.write_text(text)
                command(["cc", "-std=c11", "-funsigned-char", "-c", host, "-o", obj])
            for pair, flags in (((objects[0], host_objects[1]), ()),
                                ((host_objects[0], objects[1]), ("-nostartfiles",))):
                command(["cc", "-no-pie", *flags, *pair, "-o", exe])
                expect(command([exe], check=False).returncode == 0,
                       "host C / Crunch long long ABI failed")


def c_integer_literals_case():
    """Check C integer literal radix, unsigned typing and unary minus.

    Returns:
        None; raises AssertionError for an incorrect result or accepted invalid literal.
    """
    program = """
unsigned long maximum = 0xffffffffffffffff;
unsigned int octal = 010U;
int bound[(0xffffffff + 1 == 0) ? 2 : 1];
long shifted = 1L << 32;
int main() {
    if (sizeof(0x7fffffff) != 4 || sizeof(0xffffffff) != 4 ||
        sizeof(0x100000000) != 8 || sizeof(0xffffffffffffffff) != 8 ||
        sizeof(-2147483648) != 8 || sizeof(1L) != 8 ||
        sizeof(010l) != 8 || sizeof(0xffffffffL) != 8) return 1;
    if (0xffffffff + 1 != 0 || 0xffffffff != (unsigned int)-1 ||
        0xffffffffffffffff != maximum || maximum + 1 != 0 ||
        0xffffffffffffffffL != maximum || 0xffffffffL + 1 != 4294967296 ||
        -0x80000000 != 0x80000000 ||
        octal != 8 || 077UL != 63 || 010L != 8 || sizeof(bound) != 8 ||
        shifted != 4294967296) return 2;
    switch (0) { case 0xffffffff + 1: break; default: return 3; }
    return 0;
}
"""
    with tempfile.TemporaryDirectory(prefix="crunch-c-integer-literals-") as directory:
        td = pathlib.Path(directory)
        source, host, exe = td / "literals.bc", td / "literals.c", td / "literals"
        source.write_text(program)
        for options in ((), ("--c11-numeric",)):
            compile_run(source, 0, ir_options=options)
        source.write_text("long value = 42L; int main() { return 0; }\n")
        tree = json.loads(source_parse(source).stdout)
        literal = tree["declarations"][0]["initializer"]["expression"]
        expect(tree["version"] == 20 and literal["value"] == "42" and
               literal["suffix"] == "l", "long suffix was not serialized as AST v20")
        expect(command([IR, source]).stdout.startswith("CRUNCH-IR 2\n"),
               "a signed long literal unnecessarily selected unsigned IR")
        for value in ("0xffffffffffffffffL", "01777777777777777777777L"):
            source.write_text(f"unsigned long value = {value};\n")
            literal = json.loads(source_parse(source).stdout)["declarations"][0]["initializer"]["expression"]
            expect(literal["value"] == "18446744073709551615" and literal["suffix"] == "l" and
                   not literal["out_of_range"], f"incorrect long literal representation: {value}")
        for literal in ("08U", "0x10000000000000000", "9223372036854775808L"):
            result = command([IR, "-"], input=f"int main() {{ return {literal}; }}\n",
                             check=False)
            expect(result.returncode != 0, f"invalid literal {literal} was accepted")
        for code in ("long value = -9223372036854775808;",
                     "int main() { long value = -9223372036854775808; return 0; }",
                     "int main() { return sizeof(-9223372036854775808); }",
                     "int main() { return 0 && -9223372036854775808; }",
                     "int values[(-9223372036854775808) ? 1 : 2];"):
            result = command([IR, "-"], input=code + "\n", check=False)
            expect(result.returncode != 0 and "literal exceeds" in result.stderr,
                   f"out-of-range decimal operand was not diagnosed: {code}\n{result.stderr}")
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            host.write_text(program)
            command(["cc", "-std=c11", "-funsigned-char", host, "-o", exe])
            expect(command([exe], check=False).returncode == 0,
                   "host C literal behavior differs")


def scalar_type_matrix_case(c11_numeric=False):
    """Compare supported scalar operations and conversions with the C11 baseline.

    Args:
        c11_numeric: Exercise the compatibility option.
    Returns:
        None; raises AssertionError for an unexpected result or acceptance.
    """
    types = ("char", "short", "unsigned short", "int", "unsigned int",
             "long", "unsigned long", "long long", "unsigned long long",
             "float", "double", "signed char", "unsigned char")
    implicit = explicit = ("Y" * len(types),) * len(types)
    ir_options = ("--c11-numeric",) if c11_numeric else ()
    integer_types = set(types) - {"float", "double"}

    def common_size(left, right):
        """Return the C11 arithmetic result size for two supported types.

        Args:
            left: Left operand type.
            right: Right operand type.
        Returns:
            Result size in bytes on the target ABI.
        """
        if "double" in (left, right):
            return 8
        if "float" in (left, right):
            return 4
        return 8 if any(t in ("long", "unsigned long", "long long", "unsigned long long")
                        for t in (left, right)) else 4

    with tempfile.TemporaryDirectory(prefix="crunch-scalar-matrix-") as directory:
        td = pathlib.Path(directory)
        source = td / "matrix.bc"
        programs = []
        for i, dest in enumerate(types):
            declarations = [f"{dest} identity_{i}({dest} x) {{ return x; }}"]
            body = []
            for j, src in enumerate(types):
                probes = (
                    ("assignment", implicit, f"int main() {{ {src} b; {dest} a; a = b; return 0; }}"),
                    ("argument", implicit, f"{dest} f({dest} x) {{ return x; }} "
                     f"int main() {{ {src} b; f(b); return 0; }}"),
                    ("return", implicit, f"{dest} f({src} b) {{ return b; }} "
                     "int main() { return 0; }"),
                    ("cast", explicit, f"int main() {{ {src} b; {dest} a; "
                     f"a = ({dest})b; return 0; }}"),
                )
                for context, table, text in probes:
                    result = command([IR, *ir_options, "-"], input=text, check=False)
                    expected = table[i][j] == "Y"
                    expect((result.returncode == 0) == expected,
                           f"{context} {src} -> {dest}: unexpected "
                           f"{'acceptance' if result.returncode == 0 else 'rejection'}"
                           f"\n{result.stderr}")

                case = i * len(types) + j + 1
                checks = ["a + b == 15", "a - b == 9", "a * b == 36",
                          "a / b == 4", "a > b", "a != b", "(1 ? a : b) == 12"]
                checks.append(f"sizeof(a + b) == {common_size(dest, src)}")
                checks.append(f"sizeof(1 ? a : b) == {common_size(dest, src)}")
                if dest in integer_types and src in integer_types:
                    checks += ["a % b == 0", "(a & b) == 0", "(a | b) == 15",
                               "(a ^ b) == 15", "(a << b) == 96", "(a >> b) == 1"]
                statements = [f"{{ {dest} a = ({dest})12; {src} b = ({src})3;"]
                statements += [f"if (!({check})) return {case};" for check in checks]
                negative_less = dest in ("signed char", "short", "int", "long", "long long",
                                         "float", "double")
                if dest in integer_types and (src in ("unsigned long", "unsigned long long") or
                                               (src == "unsigned int" and
                                                dest in ("signed char", "short", "int"))):
                    negative_less = False
                statements += [f"a = ({dest})-1;",
                               f"if ((a < b) != {int(negative_less)}) return {case};"]
                if explicit[i][j] == "Y":
                    statements += [f"a = ({dest})b;", f"if (a != 3) return {case};"]
                if implicit[i][j] == "Y":
                    name = f"convert_{i}_{j}"
                    declarations.append(f"{dest} {name}({src} x) {{ return x; }}")
                    statements += ["a = b;", f"if (a != 3) return {case};",
                                   f"a = identity_{i}(b);", f"if (a != 3) return {case};",
                                   f"a = {name}(b);", f"if (a != 3) return {case};"]
                statements.append("}")
                body.extend(statements)
            programs.append("\n".join(declarations) + "\nint main() {\n" +
                            "\n".join(body) + "\nreturn 0;\n}\n")
        programs.append("""
int main() {
    char c = (char)255; if (c != 255) return 87;
    unsigned int u = 0xffffffffU; if (u + 1U != 0U) return 82;
    unsigned long v = 0xffffffffffffffffUL; if (v + 1UL != 0UL) return 83;
    short s = -32768; unsigned short t = 65535;
    if (s != -32768 || t != 65535 || s + t != 32767) return 84;
    int imin = -2147483648; int imax = 2147483647;
    if (imin + 1 != -2147483647 || imax - 1 != 2147483646) return 88;
    long lmin = -9223372036854775807 - 1; long lmax = 9223372036854775807;
    if (lmin + 1 != -9223372036854775807 || lmax - 1 != 9223372036854775806) return 89;
    float f = 16777216.0f; if (f + 1.0f != f) return 85;
    double d = 9007199254740992.0; if (d + 1.0 != d) return 86;
    return 0;
}
""")
        host, exe = td / "matrix.c", td / "matrix"
        for program in programs:
            source.write_text(program)
            compile_run(source, 0, ir_options=ir_options)
            if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
                host.write_text(program)
                command(["cc", "-std=c11", "-funsigned-char", host, "-o", exe])
                result = command([exe], check=False)
                expect(result.returncode == 0,
                       f"C11 scalar matrix failed with exit status {result.returncode}")

        source.write_text("int main() { char a = (char)200; char b = (char)100; "
                          "if (a + b == 300 && sizeof(a + b) == 4) return 10; "
                          "if (a + b == 44 && sizeof(a + b) == 1) return 11; "
                          "return 12; }\n")
        compile_run(source, 10, ir_options=ir_options)
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            host.write_text(source.read_text())
            command(["cc", "-std=c11", "-funsigned-char", host, "-o", exe])
            expect(command([exe], check=False).returncode == 10,
                   "C11 char arithmetic did not promote to int")

        source.write_text("int main() { double x = -32768.5; double y = -2147483648.5; "
                          "if ((short)x == -32768 && (int)y == -2147483648) return 10; "
                          "if ((short)x == 0 && (int)y == 0) return 11; return 12; }\n")
        compile_run(source, 10, ir_options=ir_options)
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            host.write_text(source.read_text())
            command(["cc", "-std=c11", "-funsigned-char", host, "-o", exe])
            expect(command([exe], check=False).returncode == 10,
                   "C11 floating conversion did not truncate before checking range")


def c11_numeric_case():
    """Check C promotions, conversions, option compatibility and module linkage.

    Returns:
        None; raises AssertionError for a mismatch.
    """
    source = FIXTURES / "units/types/c11_numeric.bc"
    result = command([IR, source], check=False)
    expect(result.returncode == 0, "default mode rejected C numeric conversions")
    ir, _ = compile_run(source, 0, ir_options=("--c11-numeric",))
    expect(ir.startswith("CRUNCH-IR 12\n"), "numeric fixture has the wrong IR version")
    command([ASM, "--validate"], input=ir)
    for text in (
            "int main() { char x = 1; return x << 32L; }",
            "int main() { int *p = (char)200 + (char)56; return 0; }",
            "int main() { switch (0) { case (char)11 / (char)2: break; "
            "case 5: break; } return 0; }"):
        result = command([IR, "--c11-numeric", "-"], input=text, check=False)
        expect(result.returncode != 0, f"invalid C11 numeric source accepted: {text}")
    with tempfile.TemporaryDirectory(prefix="crunch-c11-numeric-") as directory:
        td = pathlib.Path(directory)
        exe = td / "program"
        small = td / "char-conversion.bc"
        small.write_text("char convert(double x) { return x; } "
                         "int main() { return convert(255.75) != 255 || "
                         "convert(-0.5) != 0; }\n")
        small_ir, _ = compile_run(small, 0)
        expect(small_ir.startswith("CRUNCH-IR 2\n"),
               "plain-char conversion unnecessarily changed the IR version")
        command([ASM, "--validate"], input=small_ir)
        command([DRIVER, "--c11-numeric", source, "-o", exe])
        expect(command([exe], check=False).returncode == 0, "driver lost numeric mode")
        module = command([IR, "--c11-numeric", "--module", source]).stdout
        expect(module.startswith("CRUNCH-IR 13\n"), "numeric module has the wrong IR version")
        command([ASM, "--validate"], input=module)
        provider, consumer = td / "provider.bc", td / "consumer.bc"
        provider.write_text("char convert(double x) { return x; }\n")
        consumer.write_text("char convert(double x); int main() { char x = 200; "
                            "return convert(12.5) == 12 && x + x == 400 ? 0 : 1; }\n")
        objects = [td / "provider.o", td / "consumer.o"]
        for unit, obj in zip((provider, consumer), objects):
            command([DRIVER, "--c11-numeric", "-c", unit, "-o", obj])
        command([DRIVER, *objects, "-o", exe])
        expect(command([exe], check=False).returncode == 0, "separate modules lost numeric mode")
        extension = td / "power.bc"
        extension.write_text("int comparison = 2.0 ** 3.0 == 8.0; "
                             "char converted = 2.0 ** 3.0; "
                             "double nested = (char)(2.0 ** 3.0); "
                             "int items[1] = {2.0 ** 3.0 == 8.0}; "
                             "int main() { return comparison != 1 || converted != 8 || "
                             "nested != 8.0 || items[0] != 1; }\n")
        compile_run(extension, 0, ir_options=("--c11-numeric",))
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            host = td / "program.c"
            host.write_text(source.read_text())
            command(["cc", "-std=c11", "-funsigned-char", host, "-o", exe])
            expect(command([exe], check=False).returncode == 0, "C11 reference differs")


def numeric_version_compatibility_case():
    """Check numeric mode, format selection and historical IR execution.

    Returns:
        None; raises AssertionError for a format or compatibility regression.
    """
    cases = (
        ("int main() { return 0; }", 15, 2),
        ("unsigned int u; int main() { return 0; }", 15, 6),
        ("float f; int main() { return 0; }", 16, 8),
        ("int main() { int a[2]; return 0; }", 17, 2),
        ("int a[2]; int main() { return 0; }", 17, 12),
        ("float a[2]; int main() { return 0; }", 17, 12),
        ("short s; int main() { return 0; }", 18, 14),
        ("signed char c; int main() { return 0; }", 19, 16),
        ("unsigned int u; float f; short s; unsigned char c; "
         "int a[2]; int main() { return 0; }", 19, 16),
    )
    with tempfile.TemporaryDirectory(prefix="crunch-numeric-compat-") as directory:
        td = pathlib.Path(directory)
        source = td / "source.bc"
        for text, ast_version, ir_version in cases:
            source.write_text(text + "\n")
            expect(json.loads(source_parse(source).stdout)["version"] == ast_version,
                   f"wrong AST version for {text}")
            for mode in ((), ("--c11-numeric",)):
                for module in (False, True):
                    options = (*mode, *(("--module",) if module else ()))
                    result = command([IR, *options, source])
                    expected = ir_version + int(module)
                    expect(result.stdout.startswith(f"CRUNCH-IR {expected}\n"),
                           f"wrong IR version for {text}, options {options}")
                    command([ASM, "--validate"], input=result.stdout)
                emitted = command([DRIVER, *mode, "--emit-ir", source]).stdout
                expected = ir_version
                expect(emitted.startswith(f"CRUNCH-IR {expected}\n"),
                       f"driver lost numeric mode for {text}, options {mode}")

        provider, consumer, exe = td / "provider.bc", td / "consumer.bc", td / "mixed"
        provider.write_text("int sum(char a, char b) { return a + b; }\n")
        consumer.write_text("int sum(char a, char b); int main() { char x = (char)200; "
                            "return sum(x, x) == 400 && x + x == 400 ? 0 : 1; }\n")
        command([DRIVER, "--c11-numeric", provider, consumer, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "numeric mode did not reach every source in one driver invocation")
        consumer.write_text("int sum(char a, char b); int main() { char x = (char)200; "
                            "return sum(x, x) == 400 && x + x == 400 ? 0 : 1; }\n")
        provider_o, consumer_o = td / "provider.o", td / "consumer.o"
        command([DRIVER, "-c", provider, "-o", provider_o])
        command([DRIVER, "--c11-numeric", "-c", consumer, "-o", consumer_o])
        command([DRIVER, "--c11-numeric", provider_o, consumer_o, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "separately compiled objects disagreed on C numeric semantics")

        # Old IR casts check the original floating value; byte addition wraps.
        bits = struct.unpack(">Q", struct.pack(">d", -2147483648.5))[0]
        instructions = (f"pushr 0x{bits:016x}\ncast real int\npush 0\nne int\n"
                        "push 200\ncast int byte\npush 100\ncast int byte\n"
                        "add byte\ncast byte int\npush 44\nne int\nbor int\nret int\n")
        for version in range(2, 24):
            module = version in (3, 4) or (version >= 6 and version % 2 == 1)
            name = "old_value" if module else "main"
            initializer = ("internal old_init\ninitializer old_init\n"
                           "func old_init 0 int\npush 0\nret int\nend\n"
                           if version in (4, 5) else "")
            text = (f"CRUNCH-IR {version}\n{initializer}"
                    f"func {name} 0 int\n{instructions}end\n")
            command([ASM, "--validate"], input=text)
            if module:
                assembly, obj = td / "old.s", td / "old.o"
                assembly.write_text(command([ASM, "-"], input=text).stdout)
                command([TEST_AS, "-o", obj, assembly])
                source.write_text("int old_value(); int main() { return old_value(); }\n")
                command([DRIVER, source, obj, "-o", exe])
                expect(command([exe], check=False).returncode == 0,
                       f"historical IR v{version} module changed numeric behavior")
            else:
                old_ir = td / "old.bir"
                old_ir.write_text(text)
                compile_run(old_ir, 0)
        for version in (1, 20):
            result = command([ASM, "-"], input=f"CRUNCH-IR {version}\n", check=False)
            expect(result.returncode != 0 and not result.stdout,
                   f"unsupported IR v{version} was accepted")


def c11_numeric_boundaries_case():
    """Compare constant and runtime conversions at numeric boundaries.

    Returns:
        None; raises AssertionError for incorrect conversion or compatibility behavior.
    """
    source = FIXTURES / "units/types/c11_numeric_boundaries.bc"
    diagnostics = command([IR, "--c11-numeric", source]).stderr
    expect("out of range" not in diagnostics, "valid truncated constants were warned")
    ir, _ = compile_run(source, 0, ir_options=("--c11-numeric",))
    command([ASM, "--validate"], input=ir)
    with tempfile.TemporaryDirectory(prefix="crunch-c11-boundaries-") as directory:
        td = pathlib.Path(directory)
        if os.environ.get("CRUNCH_TEST_NATIVE_ONLY") != "1":
            host, exe = td / "boundaries.c", td / "boundaries"
            host.write_text(source.read_text())
            command(["cc", "-std=c11", "-funsigned-char", host, "-o", exe])
            expect(command([exe], check=False).returncode == 0, "C11 boundary reference differs")
        for version in (14, 16):
            old_ir = td / "old.bir"
            old_ir.write_text(f"CRUNCH-IR {version}\nfunc main 0 int\n"
                              "pushr 0xc0e0001000000000\ncast real short\n"
                              "cast short int\nret int\nend\n")
            compile_run(old_ir, 0)
        invalid_bound = command([IR, "--c11-numeric", "-"], input=
                                "int n; int a[1 ? 1 : n]; int main() { return 0; }\n",
                                check=False)
        expect(invalid_bound.returncode != 0, "unevaluated nonconstant array bound was accepted")
        for text in ("int main() { return 1U / 0U; }",
                     "int main() { return 1U << 32; }",
                     "int main() { return 1 ? 0 : (1.0 << 1); }"):
            expect(command([IR, "--c11-numeric", "-"], input=text, check=False).returncode != 0,
                   f"invalid evaluated operation or operand type was accepted: {text}")
        default = command([IR, "-"], input="int main() { return 1 || (1U / 0U); }\n",
                          check=False)
        expect(default.returncode == 0, "default mode rejected an unevaluated division")
        obj, exe = td / "boundaries.o", td / "boundaries-crunch"
        command([DRIVER, "--c11-numeric", "-c", source, "-o", obj])
        command([DRIVER, obj, "-o", exe])
        expect(command([exe], check=False).returncode == 0,
               "separately compiled boundary conversions failed")
        invalid = td / "invalid.bc"
        invalid.write_text("""
signed char gc = (signed char)-129.0;
short gs = (short)-32769.0;
int gi = (int)-2147483649.0;
int gu = (int)2147483648.0;
long gl = (long)-9223372036854777856.0;
int gn = (int)(0.0 / 0.0);
int gp = (int)(1.0 / 0.0);
int nan_equal = (0.0 / 0.0) == (0.0 / 0.0);
int nan_unequal = (0.0 / 0.0) != (0.0 / 0.0);
double negative_zero = -0.0;
double identity(double x) { return x; }
int main() {
    if (gc != 0 || gs != 0 || gi != 0 || gu != 0 || gl != 0 || gn != 0 || gp != 0) return 1;
    if ((signed char)identity(-129.0) != gc ||
        (short)identity(-32769.0) != gs ||
        (int)identity(-2147483649.0) != gi ||
        (int)identity(2147483648.0) != gu ||
        (long)identity(-9223372036854777856.0) != gl) return 2;
    double zero = identity(0.0);
    if ((int)(zero / zero) != gn || (int)(1.0 / zero) != gp) return 3;
    double nan = zero / zero;
    if (nan_equal != (nan == nan) || nan_unequal != (nan != nan) ||
        (1.0 / negative_zero) >= 0.0) return 4;
    return 0;
}
""")
        expect("out of range" in command([IR, "--c11-numeric", invalid]).stderr,
               "out-of-range constants were not warned")
        compile_run(invalid, 0, ir_options=("--c11-numeric",))


def native_only_driver_case():
    """Exercise native defaults, archive extraction, partial links, and errors.

    Returns:
        None; raises AssertionError for an incorrect native-only pipeline.
    """
    with tempfile.TemporaryDirectory(prefix="crunch-native-only-") as directory:
        td = pathlib.Path(directory)
        env = dict(os.environ, CRUNCH_CONF_FILE=str(td / "missing.conf"))
        driver = BUILD / "crunch"
        main, helper, assembly, preprocessed = (
            td / name for name in ("main.bc", "helper.bc", "extra.s", "value.S"))
        main.write_text('int answer(); int printf(const char* format); int main() { printf("native"); return answer(); }\n')
        helper.write_text("int value(); int extra(); int answer() { return value() + extra(); }\n")
        assembly.write_text(".text\n.globl extra\nextra: movl $2,%eax\nret\n"
                            '.section .note.GNU-stack,"",@progbits\n')
        preprocessed.write_text("#define VALUE 40\n.text\n.globl value\n"
                                "value: movl $VALUE,%eax\nret\n"
                                '.section .note.GNU-stack,"",@progbits\n')
        main_o, helper_o, asm_o, pp_o, archive, combined, exe = (
            td / name for name in ("main.o", "helper.o", "extra.o", "value.o", "libanswer.a",
                                   "combined.o", "program"))
        for source, obj in ((main, main_o), (helper, helper_o), (assembly, asm_o),
                            (preprocessed, pp_o)):
            result = command([driver, "-v", "-c", source, "-o", obj], env=env)
            expect(str(BUILD / "crunch-as") in result.stderr,
                   f"default assembler was not crunch-as: {result.stderr}")
        command([driver, "--archive", "-o", archive, helper_o, asm_o, pp_o], env=env)
        members = command([BUILD / "crunch-ar", "t", archive]).stdout.splitlines()
        expect(members == ["helper.o", "extra.o", "value.o"], f"incorrect archive members: {members}")
        result = command([driver, "-v", "-c", main_o, archive, "-o", combined], env=env)
        expect(str(BUILD / "crunch-ld") in result.stderr,
               f"default linker was not crunch-ld: {result.stderr}")
        command([driver, combined, "-o", exe], env=env)
        result = command([exe], check=False)
        expect(result.returncode == 42 and result.stdout == "native",
               f"native executable failed: {result.returncode}, {result.stdout!r}")
        exe.write_text("preserved")
        result = command([driver, archive, main_o, "-o", exe], env=env, check=False)
        expect(result.returncode != 0 and result.stderr and exe.read_text() == "preserved",
               "archive order error did not preserve the output")
        conf = td / "gnu.conf"
        env["CRUNCH_CONF_FILE"] = str(conf)
        for text, args in (("assembler = gnu\n", [main, "-c"]),
                           ("linker = gnu\n", ["--static", main_o])):
            conf.write_text(text)
            result = command([driver, *args, "-o", exe], env=env, check=False)
            expect(result.returncode != 0 and "not configured" in result.stderr and
                   exe.read_text() == "preserved",
                   f"unconfigured GNU tool was not rejected: {result.stderr}")

def frontend_fixture_cases():
    """Run tool-independent lexer, parser, AST, and semantic fixture checks.

    Returns:
        None; each fixture reports its own result.
    """
    # Lexer unit: every fixture is tested independently.
    for filename in sorted((FIXTURES / "units/lexer").glob("*.bc")):
        def check_lexer(path=filename):
            """Check token output or expected lexical rejection for one fixture.

            Args:
                path: Fixture path captured from the enclosing registration loop.
            Returns:
                None; raises AssertionError for unexpected tokens or diagnostics.
            """
            result = command([LEXER, path], check=False)
            if path.name.startswith("invalid_"):
                expect(result.returncode != 0, "invalid lexer fixture was accepted")
                expect("invalid token" in result.stderr.lower(), f"missing lexer diagnostic: {result.stderr}")
            else:
                expect(result.returncode == 0, f"valid lexer fixture rejected: {result.stderr}")
                expect(result.stdout.startswith("CRUNCH-TOKENS 1\n"), "missing token stream header")
                if path.name == "leading_dot_real.bc":
                    tokens = result.stdout.splitlines()
                    expect(any(line.startswith("REAL_LITERAL\t") and line.endswith("\t2e35") for line in tokens),
                           ".5 must be a single REAL_LITERAL token")
                    expect(not any(line.startswith("DOT\t") for line in tokens),
                           ".5 must not be tokenized as DOT followed by an integer")
        report("lexer", filename.name, check_lexer)

    # Parser: every accepted source fixture gets a fresh lexer/parser run.
    parser_valid = ["hello.bc", "arithmetic.bc", "loops.bc", "arrays.bc", "structures.bc", "argv.bc"]
    parser_valid += [p.name for p in sorted((FIXTURES / "units/parser").glob("*.bc")) if not p.name.startswith("invalid_")]
    for filename in parser_valid:
        path = (FIXTURES / "parser" / filename) if (FIXTURES / "parser" / filename).exists() else (FIXTURES / "units/parser" / filename)
        def check_parser(path=path):
            """Check that a valid fixture produces a complete versioned JSON AST.

            Args:
                path: Fixture path captured from the enclosing registration loop.
            Returns:
                None; raises AssertionError for parser failure or malformed AST output.
            """
            parsed = source_parse(path)
            tree = json.loads(parsed.stdout)
            versions = (34,) if path.name == "argv.bc" else (15, 16, 17)
            expect(tree.get("format") == "CRUNCH-AST" and tree.get("version") in versions,
                   "unexpected AST document header")
            expect(isinstance(tree.get("declarations"), list), "AST declarations should be a list")
        report("parser", path.name, check_parser)
    for filename in ["invalid_missing_semicolon.bc"] + [p.name for p in sorted((FIXTURES / "units/parser").glob("invalid_*.bc"))]:
        path = (FIXTURES / "parser" / filename) if (FIXTURES / "parser" / filename).exists() else (FIXTURES / "units/parser" / filename)
        def check_bad_parser(path=path):
            """Check that invalid syntax is rejected without partial AST output.

            Args:
                path: Fixture path captured from the enclosing registration loop.
            Returns:
                None; raises AssertionError for acceptance or missing diagnostics.
            """
            lexed = command([LEXER, path])
            parsed = command([PARSER], input=lexed.stdout, check=False)
            expect(parsed.returncode != 0, "invalid parser fixture was accepted")
            expect(bool(parsed.stderr.strip()), "invalid parser fixture produced no diagnostic")
            expect(not parsed.stdout.strip(), "invalid parser fixture emitted partial AST output")
        report("parser", path.name, check_bad_parser)

    for filename in parser_valid:
        path = (FIXTURES / "parser" / filename) if (FIXTURES / "parser" / filename).exists() else (FIXTURES / "units/parser" / filename)
        def check_ast_json(path=path, filename=filename):
            """Check JSON AST structure and fixture-specific serialized content.

            Args:
                path: Source fixture path.
                filename: Fixture name selecting additional content assertions.
            Returns:
                None; raises AssertionError for invalid AST format or missing nodes.
            """
            tree = json.loads(source_parse(path).stdout)
            versions = (34,) if filename == "argv.bc" else (15, 16, 17)
            expect(tree.get("format") == "CRUNCH-AST" and tree.get("version") in versions,
                   "unexpected AST document header")
            expect(isinstance(tree.get("declarations"), list), "AST declarations should be a list")
            if filename == "loops.bc":
                serialized = json.dumps(tree)
                for fragment in ('"name": "i"', '"name": "total"', '"kind": "for"'):
                    expect(fragment in serialized, f"AST missing {fragment}")
        report("AST JSON", path.name, check_ast_json)

    # Semantic tests: legacy fixtures are grouped by purpose, but reported one file at a time.
    sema_valid = ["scopes_valid.bc", "types_valid.bc", "casts_valid.bc", "numeric_bounds_valid.bc",
                  "numeric_bad_byte_cast_constant.bc", "numeric_bad_int_cast_constant.bc",
                  "type_bad_assignment.bc", "type_bad_array_init.bc", "type_bad_argument.bc",
                  "type_bad_return.bc", "type_bad_byte_real_cast.bc", "type_bad_real_byte_cast.bc",
                  "numeric_bad_byte_initializer.bc", "numeric_bad_assignment.bc",
                  "numeric_bad_int_initializer.bc"]
    sema_invalid_groups = {
        "scopes": ["duplicate_local.bc", "undefined_name.bc", "duplicate_parameter.bc", "duplicate_global.bc", "duplicate_structure.bc", "duplicate_struct_field.bc", "conflicting_function.bc", "duplicate_definition.bc", "undefined_function.bc"],
        "expressions": ["type_bad_operator.bc", "type_bad_member.bc"],
        "function calls": ["type_bad_call.bc", "type_bad_void_return.bc"],
        "numeric types": ["numeric_bad_long_literal.bc"],
    }
    for filename in sema_valid:
        path = FIXTURES / "sema" / filename
        unit = "semantic / scopes" if filename == "scopes_valid.bc" else "semantic / types"
        report(unit, filename, lambda path=path: sema_case(path, True))
    for unit, files in sema_invalid_groups.items():
        for filename in files:
            path = FIXTURES / "sema" / filename
            report("semantic / " + unit, filename, lambda path=path: sema_case(path, False))

    # New, explicitly categorized semantic fixtures.
    new_sema = {
        "expressions": [("valid_numeric_expressions.bc", True), ("precedence_runtime.bc", True), ("invalid_operator_types.bc", False), ("invalid_byte_real_cast.bc", True)],
        "function calls": [("arguments_and_return.bc", True), ("argument_order.bc", True), ("nested_calls_stack.bc", True), ("invalid_argument_count.bc", False), ("invalid_return_type.bc", True)],
        "scopes": [("nested_shadowing.bc", True), ("invalid_same_scope_duplicate.bc", False)],
        "globals": [("global_and_local_names.bc", True), ("global_runtime.bc", True), ("invalid_duplicate_global.bc", False)],
        "types": [("valid_numeric_widening.bc", True), ("invalid_implicit_narrowing.bc", True)],
        "structures": [("local_global_members.bc", True), ("local_contiguous_layout.bc", True), ("nested_members_and_addresses.bc", True), ("whole_structure_assignment.bc", True), ("whole_structure_array_descriptor_copy.bc", True), ("nested_dynamic_array_field.bc", True), ("dynamic_array_fields.bc", True), ("array_field_initializers.bc", True), ("global_layout.bc", True), ("def_named_struct.bc", True), ("def_anonymous_struct.bc", True)],
        "pointers": [("address_and_indirect_store.bc", True), ("pointer_aliasing.bc", True), ("uninitialized_pointers.bc", True), ("invalid_pointer_type_mismatch.bc", False)],
    }
    for unit, cases in new_sema.items():
        for filename, valid in cases:
            path = FIXTURES / "units" / unit.replace(" ", "_") / filename
            report("semantic / " + unit, filename, lambda path=path, valid=valid: sema_case(path, valid))


