for filename, path, expected, checks in ir_cases:
    def check_pipeline(path=path, expected=expected, checks=checks, filename=filename):
        """Run an executable fixture and inspect its IR and assembly.

        Args:
            path: Source fixture path.
            expected: Required executable exit status.
            checks: Substrings required in generated IR.
            filename: Fixture name selecting additional assembly assertions.
        Returns:
            None; raises AssertionError for incorrect execution or generated code.
        """
        irtext, asmtext = compile_run(path, expected, checks=checks)
        if filename == "global_layout.bc":
            for needle in (".size origin, 32", ".set origin__tag, origin+0", ".set origin__count, origin+4", ".set origin__total, origin+8", ".set origin__name, origin+16"):
                expect(needle in asmtext, f"assembly missing structure layout {needle!r}\n{asmtext}")
        if filename == "hello.bc":
            expect(irtext.count("ret int") == 1, "explicit return duplicated in IR")
            expect(asmtext.count("mov $60, %rax") == 1, "expected one exit syscall sequence")
        if filename == "loop_condition.bc":
            expect("dup\n" not in irtext, "discarded postfix decrement unexpectedly duplicated")
            lines = [line.strip() for line in asmtext.splitlines()]
            expect(not any(a == "push %rax" and b == "pop %rax" for a, b in zip(lines, lines[1:])), "redundant adjacent push/pop pair")
    report("IR + x86-64 execution", filename, check_pipeline)

def native_runtime_differential_case():
    """Compare GNU and native assembler/runtime combinations across executable fixtures.

    Returns:
        None; raises AssertionError for build, output, or execution differences.
    """
    native = BUILD / "libcrunch-native.a"
    original_archive = (BUILD / "libcrunch.a").read_bytes()
    make_native = ["make", "-C", ROOT / "build",
                   f"CONFIG_MK={BUILD.parent / 'config.mk'}",
                   f"BUILD_DIR={BUILD}", "native-runtime"]
    command(make_native, timeout=180)
    expect((BUILD / "libcrunch.a").read_bytes() == original_archive,
           "separate native build changed the selected runtime")
    gnu_members = command(["ar", "t", GNU_LIBCRUNCH]).stdout.splitlines()
    native_members = command(["ar", "t", native]).stdout.splitlines()
    expect(gnu_members == native_members, "native and GNU runtime archive members differ")
    native_mtime = native.stat().st_mtime_ns
    command(make_native, timeout=180)
    expect(native.stat().st_mtime_ns == native_mtime, "native runtime rebuilt without changes")

    header_cases = [
        ("stdio_snprintf.bc", 0), ("strtol.bc", 42),
        ("strtoul.bc", 42), ("allocator.bc", 42),
    ]
    with tempfile.TemporaryDirectory(prefix="crunch-native-corpus-") as directory:
        td = pathlib.Path(directory)
        cases = [(name, path, expected, False) for name, path, expected, _ in ir_cases]
        cases.extend((name, FIXTURES / "units/library" / name, expected, True)
                     for name, expected in header_cases)
        for name, source, expected, needs_preprocessing in cases:
            assembly = td / "program.s"
            if needs_preprocessing:
                command([DRIVER, "-S", source, "-o", assembly])
            else:
                ir = source.read_text() if source.suffix == ".bir" else command([IR, source]).stdout
                assembly.write_text(command([ASM, "-"], input=ir).stdout)
            objects = []
            for assembler in ("as", BUILD / "crunch-as"):
                obj = td / f"program-{len(objects)}.o"
                command([assembler, "-o", obj, assembly])
                objects.append(obj)
            reference = None
            for obj in objects:
                for archive in (GNU_LIBCRUNCH, native):
                    linkers = [["ld"]]
                    if test_linker == "crunch":
                        linkers.append(TEST_LINK)
                    for linker in linkers:
                        exe = td / "program"
                        command([*linker, "-o", exe, obj, archive])
                        result = command([exe], check=False)
                        actual = (result.returncode, result.stdout, result.stderr)
                        expect(result.returncode == expected,
                               f"{name}: {obj.name} with {archive.name} and {linker[0]} returned "
                               f"{result.returncode}, expected {expected}\n{result.stderr}")
                        if reference is None:
                            reference = actual
                        expect(actual == reference,
                               f"{name}: {obj.name} with {archive.name} and {linker[0]} "
                               "differs from GNU/GNU/GNU")

report("integration", "native runtime differential corpus", native_runtime_differential_case)

