# Runtime helpers are included selectively, once per generated translation unit.
def check_runtime_helper_selection():
    """Check that only programs using arrays reference the allocation runtime.

    Returns:
        None; raises AssertionError for missing or unnecessarily emitted helpers.
    """
    _, plain_asm = compile_run(FIXTURES / "ir/main42.bc", 42)
    _, array_asm = compile_run(FIXTURES / "ir/legacy_local_array_resize.bir", 42)
    expect("__crunch_alloc_bytes" not in plain_asm, "non-array program unexpectedly includes allocation helper")
    expect("__crunch_free_bytes" not in plain_asm, "non-array program unexpectedly includes free helper")
    expect("__crunch_alloc_bytes:" not in array_asm, "allocation helper should be linked from libcrunch.a")
    expect("__crunch_free_bytes:" not in array_asm, "free helper should be linked from libcrunch.a")
    expect("call __crunch_alloc_bytes" in array_asm, "array operations should call shared allocator")
    expect("call .Lcrunch_free_array" in array_asm and
           "jmp __crunch_free_bytes" in array_asm,
           "resize should check static storage before calling the shared free helper")

report("codegen runtime", "selective helper emission", check_runtime_helper_selection)

# The assembly backend is independently callable and must reject malformed IR.
ir_invalid_cases = [
    ("invalid_header.bir", None), ("unknown_instruction.bir", "IR line"),
    ("unknown_function_call.bir", "IR line"), ("undefined_branch_target.bir", None),
    ("unknown_top_level.bir", "unknown IR directive"),
    ("invalid_stringlit_label.bir", "invalid string literal directive"),
    ("stringlit_extra_field.bir", "invalid string literal directive"),
    ("invalid_stringlit_hex.bir", "invalid hexadecimal string literal"),
    ("invalid_stringlit_odd_hex.bir", "invalid string literal directive"),
    ("invalid_global_initializer.bir", "invalid initializer for global"),
    ("unterminated_function.bir", "unterminated function"),
    ("end_outside_function.bir", "unknown IR directive 'end'"),
    ("missing_main_function.bir", "IR has no main function"),
    ("duplicate_label.bir", None), ("duplicate_function.bir", None),
    ("branch_into_other_function.bir", None), ("invalid_label_spelling.bir", None),
    ("stack_underflow.bir", "stack underflow"),
    ("stack_merge_mismatch.bir", "inconsistent stack depth"),
    ("reachable_fallthrough.bir", "falls through past 'end'"),
    ("conditional_branch_underflow.bir", "stack underflow"),
    ("stack_type_mismatch.bir", "binary operand types do not match"),
    ("stack_type_merge_mismatch.bir", "incompatible stack types at control-flow merge"),
]
for filename, diagnostic in ir_invalid_cases:
    path = FIXTURES / "units/ir" / filename
    def check_invalid_ir(path=path, diagnostic=diagnostic):
        """Check backend rejection and diagnostics for one malformed IR fixture.

        Args:
            path: IR fixture path.
            diagnostic: Case-insensitive diagnostic substring required in stderr.
        Returns:
            None; raises AssertionError for acceptance or missing diagnostics.
        """
        result = command([ASM, path], check=False)
        expect(result.returncode != 0, "assembly backend accepted malformed IR")
        expect("crunch-asm:" in result.stderr, f"missing backend diagnostic: {result.stderr}")
        if diagnostic:
            expect(diagnostic in result.stderr, f"expected diagnostic {diagnostic!r}; got {result.stderr!r}")
    report("IR validation", filename, check_invalid_ir)

print(f"\nTest summary: {GREEN}{passed} passed{RESET}, {RED}{failed} failed{RESET}, {passed + failed} total")
sys.exit(1 if failed else 0)
